<?php
require_once __DIR__ . '/auth.php';
requireAuth();
header('Cache-Control: no-store, no-cache, must-revalidate, max-age=0');
header('Pragma: no-cache');
header('Expires: Thu, 01 Jan 1970 00:00:00 GMT');
// Server build identifier — file mtime of index.php. Used as a
// cache-busting suffix on the document so any intermediate caches
// (bfcache, proxies, browser disk cache) can't serve a stale snapshot
// without us noticing — the operator can read the badge bottom-right
// to confirm what build they're actually on.
$_msBuildId = @filemtime(__FILE__) ?: time();
$_msBuildIso = date('Y-m-d H:i', $_msBuildId);
header('Last-Modified: ' . gmdate('D, d M Y H:i:s', $_msBuildId) . ' GMT');
header('ETag: "' . dechex($_msBuildId) . '"');
// Server-side cache bust: if the URL doesn't carry ?v=<current build>,
// send a 302 to the same URL with the correct ?v=. This fires BEFORE
// any HTML body, so Bluehost edge caching / browser-disk caching
// can't serve a "200 with stale body" — the redirect itself is a
// brand-new resource keyed on the new query string, and intermediate
// caches treat the destination URL as unseen.
$_msReqV  = isset($_GET['v']) ? (string)$_GET['v'] : '';
$_msWantV = (string)$_msBuildId;
if ($_msReqV !== $_msWantV) {
  $_msUri = $_SERVER['REQUEST_URI'] ?? '/index.php';
  // Split path from query, rebuild query without any v= entries, then
  // append the correct v=. Parsing via parse_str round-trip handles
  // duplicate v= keys cleanly (which a naive preg_replace did not).
  $_msQs   = '';
  $_msPath = $_msUri;
  $_msQPos = strpos($_msUri, '?');
  if ($_msQPos !== false) {
    $_msPath = substr($_msUri, 0, $_msQPos);
    $_msQs   = substr($_msUri, $_msQPos + 1);
  }
  $_msParams = [];
  if ($_msQs !== '') parse_str($_msQs, $_msParams);
  unset($_msParams['v']);
  $_msParams['v'] = $_msWantV;
  $_msNewQs = http_build_query($_msParams);
  $_msDest  = $_msPath . ($_msNewQs !== '' ? '?' . $_msNewQs : '');
  header('Location: ' . $_msDest, true, 302);
  exit;
}
$_msUser     = htmlspecialchars($_SESSION['display_name'] ?? $_SESSION['username'] ?? '', ENT_QUOTES);
$_msRole     = $_SESSION['role'] ?? 'user';
$_msUserId   = (int)($_SESSION['user_id'] ?? 0);
$_msUsername = htmlspecialchars($_SESSION['username'] ?? '', ENT_QUOTES);
?>
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <!-- HTTP headers (set above) already disable caching, but some browsers
       (older Safari especially) honor the meta hint more reliably for
       back/forward navigation and offline-mode revalidation. Keep both. -->
  <meta http-equiv="Cache-Control" content="no-cache, no-store, must-revalidate" />
  <meta http-equiv="Pragma" content="no-cache" />
  <meta http-equiv="Expires" content="0" />
  <link rel="icon" type="image/svg+xml" href="favicon.svg">
  <title>Market Sculpt — Product Workbook</title>
  <!-- Hard cache bust — every deploy bumps the file's mtime, so the
       URL we navigate to includes that as ?v=… and any intermediate
       cache (browser, bfcache, edge) is forced to treat each build
       as a brand-new resource. Also unregisters any service worker
       that might be intercepting the response — the workbook has no
       PWA install path, so any sw.* registered here is stale. -->
  <script>
    (function () {
      var build = "<?= (int)$_msBuildId ?>";
      try {
        var u = new URL(window.location.href);
        if (u.searchParams.get('v') !== build) {
          u.searchParams.set('v', build);
          window.location.replace(u.toString());
          return;
        }
      } catch (_) {}
      // Drop any straggling service worker — we don't ship one, so
      // anything registered is from a prior experiment / dev pivot
      // and would silently serve stale responses forever.
      if ('serviceWorker' in navigator) {
        navigator.serviceWorker.getRegistrations().then(function (regs) {
          regs.forEach(function (r) { r.unregister(); });
        }).catch(function () {});
      }
    })();
