</div>

<script>
  /* ── Session guard: require login on every hard refresh ─────────────── */
  (function() {
    const params = new URLSearchParams(window.location.search);
    if (params.get('new_login')) {
      sessionStorage.setItem('ms_auth', '1');
      const savedHash = params.get('hash');
      window.history.replaceState({}, '', window.location.pathname);
      if (savedHash) location.hash = savedHash;
    } else if (!sessionStorage.getItem('ms_auth')) {
      const h = location.hash;
      window.location.href = 'logout.php' + (h ? '?hash=' + encodeURIComponent(h) : '');
    }
  })();

  /* ── Sidebar Submenu Toggle ─────────────────────────────────────────── */
  function toggleSubmenu(btn) {
    btn.classList.toggle('expanded');
    const submenu = btn.nextElementSibling;
    if (submenu && submenu.classList.contains('nav-submenu')) {
      submenu.classList.toggle('open');
    }
  }
  /* ── Theme ─────────────────────────────────────────────────────────────── */
  /* ── Mobile Sidebar Toggle ─────────────────────────────────────────── */
  function toggleMobileSidebar() {
    document.querySelector('.sidebar').classList.toggle('mobile-open');
    document.getElementById('sidebar-overlay').classList.toggle('open');
    document.body.classList.toggle('sidebar-open');
  }
  // Close sidebar when a nav-item is clicked on mobile (event delegation)
  document.querySelector('.sidebar').addEventListener('click', (e) => {
    if (e.target.closest('.nav-item') && document.querySelector('.sidebar').classList.contains('mobile-open')) {
      toggleMobileSidebar();
    }
  });

  /* ── Sidebar drag-to-resize ─────────────────────────────────────────
     Lets the operator widen the sidebar by dragging the right edge.
     Width is persisted in localStorage so it sticks across sessions and
     across reloads of the SPA. Double-click resets to the default. */
  (function () {
    const SIDEBAR_MIN_PX = 140;
    const SIDEBAR_MAX_PX = 420;
    const DEFAULT_PX     = 180;
    const STORAGE_KEY    = 'ms_sidebarWidth';
    const root           = document.documentElement;
    const handle         = document.getElementById('sidebar-resize-handle');
    if (!handle) return;

    const applyWidth = (px) => {
      const clamped = Math.max(SIDEBAR_MIN_PX, Math.min(SIDEBAR_MAX_PX, px));
      root.style.setProperty('--sidebar-width', clamped + 'px');
      return clamped;
    };

    // Restore saved width on first load.
    const saved = parseInt(localStorage.getItem(STORAGE_KEY), 10);
    if (!isNaN(saved)) applyWidth(saved);

    let dragging   = false;
    let startX     = 0;
    let startWidth = 0;
    let pointerId  = null;

    const onDown = (clientX, e) => {
      // Skip resizing on mobile (sidebar is a drawer there).
      if (window.matchMedia('(max-width: 768px)').matches) return;
      dragging   = true;
      startX     = clientX;
      startWidth = parseInt(getComputedStyle(root).getPropertyValue('--sidebar-width')) || DEFAULT_PX;
      handle.classList.add('active');
      document.body.classList.add('sidebar-resizing');
      if (e && e.preventDefault) e.preventDefault();
    };
    const onMove = (clientX) => {
      if (!dragging) return;
      applyWidth(startWidth + (clientX - startX));
    };
    const onUp = () => {
      if (!dragging) return;
      dragging = false;
      handle.classList.remove('active');
      document.body.classList.remove('sidebar-resizing');
      const final = parseInt(getComputedStyle(root).getPropertyValue('--sidebar-width'));
      if (!isNaN(final)) localStorage.setItem(STORAGE_KEY, final);
    };

    // Pointer Events cover mouse + touch + pen with a single API.
    handle.addEventListener('pointerdown', (e) => {
      pointerId = e.pointerId;
      handle.setPointerCapture(pointerId);
      onDown(e.clientX, e);
    });
    handle.addEventListener('pointermove', (e) => {
      if (e.pointerId !== pointerId) return;
      onMove(e.clientX);
    });
    handle.addEventListener('pointerup',   (e) => { onUp(); pointerId = null; });
    handle.addEventListener('pointercancel', () => { onUp(); pointerId = null; });

    // Double-click → reset to default and clear the saved override.
    handle.addEventListener('dblclick', () => {
      applyWidth(DEFAULT_PX);
      localStorage.removeItem(STORAGE_KEY);
    });
  })();

  function toggleTheme() {
    const body = document.body;
    const isDark = body.dataset.theme === 'dark';
    body.dataset.theme = isDark ? 'light' : 'dark';
    const btn = document.getElementById('theme-dropdown-btn');
    if (btn) btn.textContent = isDark ? 'Dark Mode' : 'Light Mode';
  }

  /* ── User Dropdown ──────────────────────────────────────────────────────── */
  function toggleUserDropdown() {
    document.getElementById('user-dropdown').classList.toggle('open');
  }
  function closeUserDropdown() {
    document.getElementById('user-dropdown').classList.remove('open');
  }
  document.addEventListener('click', function(e) {
    const menu = document.getElementById('user-menu');
    if (menu && !menu.contains(e.target)) closeUserDropdown();
  });

  // ── Autofill nuke — global animationstart listener ─────────────────
  // Chrome fires `animationstart` with name "ms-autofill-detect" the
  // moment :-webkit-autofill activates on an element. We use that as
  // the earliest possible signal that the browser/password-manager has
  // tried to fill the field, and we scrub:
  //   - Always: any field tagged data-no-autofill="1" (no exceptions)
  //   - Otherwise: only fields whose autofilled value matches the
  //     active session user's display_name / username (those can never
  //     legitimately appear in workbook data fields).
  // Use capture so we run before any focus handler the field defines.
  document.addEventListener('animationstart', function(e) {
    if (e.animationName !== 'ms-autofill-detect') return;
    const el = e.target;
    if (!el || typeof el.value !== 'string') return;
    if (el.getAttribute('data-no-autofill') === '1') {
      el.value = '';
      return;
    }
    const sessName = (window.MS_SESSION && (window.MS_SESSION.name || window.MS_SESSION.display_name)) || '';
    const sessUser = (window.MS_SESSION && window.MS_SESSION.username) || '';
    const v = el.value.trim().toLowerCase();
    if ((sessName && v === sessName.toLowerCase()) ||
        (sessUser && v === sessUser.toLowerCase())) {
      el.value = '';
    }
  }, true);

  /* ── Change Password Modal ──────────────────────────────────────────────── */
  function openChangePasswordModal() {
    let modal = document.getElementById('change-password-modal');
    if (!modal) {
      modal = document.createElement('div');
      modal.id = 'change-password-modal';
      modal.className = 'modal-overlay';
      modal.style.cssText = 'display:flex;';
      modal.innerHTML = `
        <div class="modal" style="max-width:400px; width:100%;">
          <div class="modal-header">
            <h3 style="margin:0; font-size:16px;">Change Password</h3>
            <button onclick="document.getElementById('change-password-modal').remove()" style="background:none; border:none; font-size:20px; cursor:pointer; color:var(--text-muted);">&times;</button>
          </div>
          <div class="modal-body" style="display:flex; flex-direction:column; gap:14px;">
            <div id="cp-error" style="display:none; background:rgba(251,113,133,0.12); border:1px solid rgba(251,113,133,0.35); color:#fb7185; border-radius:8px; padding:8px 12px; font-size:13px;"></div>
            <div>
              <label style="font-size:11px; font-weight:600; text-transform:uppercase; letter-spacing:0.05em; color:var(--text-muted); display:block; margin-bottom:4px;">Current Password</label>
              <input id="cp-current" type="password" class="form-input" style="width:100%;"
                autocomplete="current-password" data-1p-ignore="true" data-lpignore="true" data-form-type="other" />
            </div>
            <div>
              <label style="font-size:11px; font-weight:600; text-transform:uppercase; letter-spacing:0.05em; color:var(--text-muted); display:block; margin-bottom:4px;">New Password</label>
              <input id="cp-new" type="password" class="form-input" style="width:100%;"
                autocomplete="new-password" data-1p-ignore="true" data-lpignore="true" data-form-type="other" />
            </div>
            <div>
              <label style="font-size:11px; font-weight:600; text-transform:uppercase; letter-spacing:0.05em; color:var(--text-muted); display:block; margin-bottom:4px;">Confirm New Password</label>
              <input id="cp-confirm" type="password" class="form-input" style="width:100%;"
                autocomplete="new-password" data-1p-ignore="true" data-lpignore="true" data-form-type="other" />
            </div>
            <button class="btn btn-primary" onclick="submitChangePassword()">Update Password</button>
          </div>
        </div>`;
      document.body.appendChild(modal);
    } else {
      modal.style.display = 'flex';
    }
  }
  async function submitChangePassword() {
    const current = document.getElementById('cp-current').value;
    const newPw = document.getElementById('cp-new').value;
    const confirm = document.getElementById('cp-confirm').value;
    const errEl = document.getElementById('cp-error');
    errEl.style.display = 'none';
    if (!current || !newPw || !confirm) { errEl.textContent = 'All fields are required.'; errEl.style.display = 'block'; return; }
    if (newPw !== confirm) { errEl.textContent = 'New passwords do not match.'; errEl.style.display = 'block'; return; }
    if (newPw.length < 6) { errEl.textContent = 'Password must be at least 6 characters.'; errEl.style.display = 'block'; return; }
    const res = await apiCall('change_password', { current_password: current, new_password: newPw });
    if (res.success) {
      document.getElementById('change-password-modal').remove();
      alert('Password updated successfully.');
    } else {
      errEl.textContent = res.error || 'Failed to update password.';
      errEl.style.display = 'block';
    }
  }

  /* ── Image Upload ──────────────────────────────────────────────────────── */
  let _productImages = []; // array of { url: 'uploads/28/abc.jpg' }

  async function handleImages(e) {
    const files = Array.from(e.target.files);
    // Visible bail-out reasons instead of silent return — every reason
    // this drop "did nothing" should surface in the UI + console so the
    // operator (and we) know exactly which gate tripped.
    if (!files.length) {
      console.warn('[handleImages] No files in event');
      return;
    }
    if (!currentWorkbookId) {
      alert('Open a workbook first, then drop the image into the gallery.');
      console.warn('[handleImages] currentWorkbookId is not set');
      return;
    }
    const dbId = dbWorkbookMap[`${currentClient}|${currentWorkbookId}`] || currentWorkbookId;
    const failures = [];
    let uploaded = 0;
    for (const file of files) {
      if (!file.type.startsWith('image/')) {
        failures.push(`${file.name}: not an image (got "${file.type || 'unknown type'}")`);
        continue;
      }
      const formData = new FormData();
      formData.append('image', file);
      formData.append('workbook_id', dbId);
      try {
        const res = await fetch('api.php?action=upload_image', { method: 'POST', body: formData });
        const data = await res.json().catch(() => ({}));
        if (data && data.success) {
          _productImages.push({ url: data.url });
          uploaded++;
        } else {
          const msg = (data && data.error) ? data.error : `HTTP ${res.status}`;
          failures.push(`${file.name}: ${msg}`);
          console.warn('[handleImages] upload failed', file.name, data);
        }
      } catch (err) {
        failures.push(`${file.name}: ${err.message || 'network error'}`);
        console.warn('[handleImages] fetch exception', err);
      }
    }
    // Render + persist whatever DID land so partial successes survive.
    if (uploaded > 0) {
      renderImageGallery();
      saveImageList();
    }
    if (failures.length) {
      alert(`Couldn't upload ${failures.length} of ${files.length} file${files.length === 1 ? '' : 's'}:\n\n• ` + failures.join('\n• ') + `\n\nTip: max 10 MB per image; allowed types: jpg, jpeg, png, gif, webp.`);
    }
    e.target.value = '';
  }

  async function removeGalleryImage(idx, e) {
    e.stopPropagation();
    const img = _productImages[idx];
    if (!img) return;
    // Delete file from server
    try { await apiCall('delete_image', { url: img.url }); } catch (err) { /* ignore */ }
    _productImages.splice(idx, 1);
    renderImageGallery();
    saveImageList();
  }

  function renderImageGallery() {
    const gallery = document.getElementById('imageGallery');
    const addBtn = gallery.querySelector('.image-add-btn');
    // Remove existing image items
    gallery.querySelectorAll('.image-gallery-item').forEach(el => el.remove());
    // Add image items before the add button
    _productImages.forEach((img, idx) => {
      const item = document.createElement('div');
      item.className = 'image-gallery-item';
      item.innerHTML = `
        <img src="${img.url}" alt="Product image ${idx+1}" onclick="openLightbox('${img.url}')" />
        <button class="img-remove" onclick="removeGalleryImage(${idx}, event)" title="Remove">✕</button>
      `;
      gallery.insertBefore(item, addBtn);
    });
  }

  function openLightbox(url) {
    document.getElementById('lightboxImg').src = url;
    document.getElementById('lightboxOverlay').classList.add('open');
  }

  function saveImageList() {
    if (!currentClient || !currentWorkbookId) return;
    const key = `${currentClient}|${currentWorkbookId}`;
    if (!workbookDetail[key]) workbookDetail[key] = {};
    workbookDetail[key].productImages = _productImages.map(i => i.url);
    // Also update legacy field
    workbookDetail[key].productImage = _productImages.length > 0 ? _productImages[0].url : '';
    const dbId = dbWorkbookMap[key] || currentWorkbookId;
    const detail = collectWorkbookDetail();
    // Ensure image data from _productImages is preserved in the detail sent to API
    detail.productImages = _productImages.map(i => i.url);
    detail.productImage = _productImages.length > 0 ? _productImages[0].url : '';
    apiCall('save_workbook_detail', { id: dbId, detail: detail });
    saveToLocalStorage();
  }

  const VIDEO_EXTS = new Set(['mp4','mov','webm','avi','mkv','m4v','qt']);
  function isVideoFile(f) {
    if (f.type.startsWith('video/')) return true;
    const ext = f.name.split('.').pop().toLowerCase();
    return VIDEO_EXTS.has(ext);
  }

  // Drag and drop support for image gallery — accepts both images and videos
  const galleryEl = document.getElementById('imageGallery');
  galleryEl.addEventListener('dragover', e => { e.preventDefault(); galleryEl.style.outline = '2px solid var(--accent)'; });
  galleryEl.addEventListener('dragleave', e => { if (!galleryEl.contains(e.relatedTarget)) galleryEl.style.outline = ''; });
  galleryEl.addEventListener('drop', async e => {
    e.preventDefault();
    galleryEl.style.outline = '';
    const allFiles = Array.from(e.dataTransfer.files);
    const imageFiles = allFiles.filter(f => f.type.startsWith('image/'));
    const videoFiles = allFiles.filter(f => !f.type.startsWith('image/') && isVideoFile(f));
    if (imageFiles.length) handleImages({ target: { files: imageFiles } });
    if (videoFiles.length) handleVideoFiles(videoFiles);
    // Cross-tab drag — when the user drags an image from another
    // browser tab (or a Google image search), the drop event delivers a
    // text/uri-list (or text/html) entry instead of a File. Fetch the
    // URL, wrap it in a Blob, and route through handleImages so the
    // same upload + persist pipeline runs.
    if (imageFiles.length === 0 && videoFiles.length === 0) {
      const uriList = e.dataTransfer.getData('text/uri-list')
                   || e.dataTransfer.getData('text/plain') || '';
      const urls = uriList.split(/\r?\n/).map(s => s.trim()).filter(s => /^https?:\/\//i.test(s));
      if (urls.length === 0) {
        if (!currentWorkbookId) {
          alert('Open a workbook first, then drop the image into the gallery.');
        } else {
          console.warn('[gallery drop] No files or URLs in dataTransfer', e.dataTransfer.types);
        }
        return;
      }
      const fetched = [];
      const fetchFails = [];
      for (const u of urls) {
        try {
          const r = await fetch(u, { mode: 'cors' });
          if (!r.ok) throw new Error('HTTP ' + r.status);
          const blob = await r.blob();
          if (!blob.type.startsWith('image/')) throw new Error('not an image (' + (blob.type || 'unknown') + ')');
          // Pick a sensible filename — last URL path segment, falling
          // back to a generic stamped name when the URL is opaque.
          let name = (new URL(u)).pathname.split('/').pop() || ('image-' + Date.now());
          if (!/\.[a-z0-9]{2,4}$/i.test(name)) name += '.' + (blob.type.split('/')[1] || 'jpg');
          fetched.push(new File([blob], name, { type: blob.type }));
        } catch (err) {
          fetchFails.push(`${u}: ${err.message || err}`);
        }
      }
      if (fetched.length) handleImages({ target: { files: fetched } });
      if (fetchFails.length) {
        alert("Couldn't fetch " + fetchFails.length + " dragged image" + (fetchFails.length === 1 ? '' : 's') + ' (the source may block cross-origin downloads):\n\n• ' + fetchFails.join('\n• ') + '\n\nTip: save the image to your computer first, then drag it into the gallery.');
      }
    }
  });

  // Drag and drop support for the Art Files gallery — images only.
  // Mirrors the image-gallery wiring so the Art tab has the same
  // "drop or click to upload" UX without needing to bounce through a
  // browse dialog.
  const artGalleryEl = document.getElementById('artGallery');
  if (artGalleryEl) {
    artGalleryEl.addEventListener('dragover',  e => { e.preventDefault(); artGalleryEl.style.outline = '2px solid var(--accent)'; });
    artGalleryEl.addEventListener('dragleave', e => { if (!artGalleryEl.contains(e.relatedTarget)) artGalleryEl.style.outline = ''; });
    artGalleryEl.addEventListener('drop', e => {
      e.preventDefault();
      artGalleryEl.style.outline = '';
      const imageFiles = Array.from(e.dataTransfer.files).filter(f => f.type.startsWith('image/'));
      if (imageFiles.length) handleArtFiles({ target: { files: imageFiles, value: '' } });
    });
  }

  // Clipboard paste — upload images when workbook is open
  document.addEventListener('paste', function(e) {
    if (!currentWorkbookId) return;
    const active = document.activeElement;
    // Don't intercept when user is typing in a text/textarea field
    if (active && (active.tagName === 'TEXTAREA' || (active.tagName === 'INPUT' && active.type !== 'file' && active.id !== 'videoUrlInput'))) return;
    const items = Array.from(e.clipboardData?.items || []);
    const imageItems = items.filter(item => item.type.startsWith('image/'));
    if (!imageItems.length) return;
    e.preventDefault();
    imageItems.forEach(item => {
      const file = item.getAsFile();
      if (file) handleImages({ target: { files: [file] } });
    });
  });

  /* ── Product Videos ─────────────────────────────────────────────────────── */
  let _productVideos = [];

  function getVideoInfo(url) {
    const ytMatch = url.match(/(?:youtube\.com\/(?:watch\?v=|shorts\/)|youtu\.be\/)([a-zA-Z0-9_-]{11})/);
    if (ytMatch) {
      const id = ytMatch[1];
      return { thumb: 'https://img.youtube.com/vi/' + id + '/mqdefault.jpg', embedUrl: 'https://www.youtube.com/embed/' + id + '?autoplay=1', type: 'iframe' };
    }
    const vimeoMatch = url.match(/vimeo\.com\/(\d+)/);
    if (vimeoMatch) {
      return { thumb: null, embedUrl: 'https://player.vimeo.com/video/' + vimeoMatch[1] + '?autoplay=1', type: 'iframe' };
    }
    if (/\.(mp4|webm|ogg|mov|m4v)(\?|$)/i.test(url) || url.startsWith('uploads/')) {
      return { thumb: null, embedUrl: url, type: 'video' };
    }
    return { thumb: null, embedUrl: url, type: 'link' };
  }

  function addProductVideo() {
    const input = document.getElementById('videoUrlInput');
    const url = input.value.trim();
    if (!url) return;
    // Last-line autofill defense: never let a Product Video entry be
    // saved if its value matches the session user's display name.
    // (Chrome's password manager autofills certain types of inputs
    // even with autocomplete=off and the user could hit Enter without
    // realizing.)
    const sessName = (window.MS_SESSION && (window.MS_SESSION.name || window.MS_SESSION.display_name)) || '';
    if (sessName && url.toLowerCase() === sessName.toLowerCase()) {
      input.value = '';
      return;
    }
    _productVideos.push(url);
    input.value = '';
    renderVideoGallery();
    saveVideoList();
  }

  // Strip a value off a "no autofill" input if browser/password-manager
  // autofill snuck through despite autocomplete=off. Called on focus
  // and input events. The check looks for values that match the active
  // user's display name or username (those are 100% autofill garbage —
  // a video URL never legitimately equals the operator's name).
  function msStripAutofill(el) {
    if (!el || typeof el.value !== 'string' || !el.value) return;
    const sessName = (window.MS_SESSION && (window.MS_SESSION.name || window.MS_SESSION.display_name)) || '';
    const sessUser = (window.MS_SESSION && window.MS_SESSION.username) || '';
    const v = el.value.trim().toLowerCase();
    if ((sessName && v === sessName.toLowerCase()) ||
        (sessUser && v === sessUser.toLowerCase())) {
      el.value = '';
    }
  }

  async function handleVideoFiles(files) {
    if (!files.length || !currentWorkbookId) return;
    const dbId = dbWorkbookMap[`${currentClient}|${currentWorkbookId}`] || currentWorkbookId;
    for (const file of files) {
      if (!isVideoFile(file)) continue;
      const formData = new FormData();
      formData.append('video', file);
      formData.append('workbook_id', dbId);
      try {
        const res = await fetch('api.php?action=upload_video', { method: 'POST', body: formData });
        const data = await res.json();
        if (data.success) {
          _productVideos.push(data.url);
          renderVideoGallery();
          saveVideoList();
        } else {
          console.warn('Video upload failed:', data.error);
        }
      } catch (err) { console.warn('Video upload error:', err); }
    }
  }

  async function removeProductVideo(idx) {
    const url = _productVideos[idx];
    if (!url) return;
    // Delete server-uploaded files from the uploads directory
    if (url.startsWith('uploads/')) {
      try { await apiCall('delete_image', { url }); } catch (err) { /* ignore */ }
    }
    _productVideos.splice(idx, 1);
    renderVideoGallery();
    saveVideoList();
  }

  function renderVideoGallery() {
    const gallery = document.getElementById('videoGallery');
    gallery.querySelectorAll('.video-item').forEach(el => el.remove());
    _productVideos.forEach((url, idx) => {
      const info = getVideoInfo(url);
      const item = document.createElement('div');
      item.className = 'video-item';
      const label = url.startsWith('uploads/') ? url.split('/').pop() : url;
      const shortLabel = label.length > 55 ? label.slice(0, 52) + '…' : label;
      const thumbHtml = info.thumb
        ? `<img class="video-thumb" src="${info.thumb}" alt="Video" onclick="openVideoLightbox(${idx})" />`
        : `<div class="video-thumb-placeholder" onclick="openVideoLightbox(${idx})">▶</div>`;
      item.innerHTML = `
        ${thumbHtml}
        <span class="video-url-label" onclick="openVideoLightbox(${idx})" title="${url}">${shortLabel}</span>
        <button class="img-remove" onclick="removeProductVideo(${idx})" title="Remove">✕</button>
      `;
      gallery.appendChild(item);
    });
  }

  function openVideoLightbox(idx) {
    const url = _productVideos[idx];
    const info = getVideoInfo(url);
    const overlay = document.getElementById('videoLightboxOverlay');
    const iframe = document.getElementById('videoLightboxIframe');
    const video = document.getElementById('videoLightboxVideo');
    if (info.type === 'video') {
      iframe.src = '';
      iframe.style.display = 'none';
      video.src = url;
      video.style.display = '';
    } else if (info.type === 'iframe') {
      video.src = '';
      video.style.display = 'none';
      iframe.src = info.embedUrl;
      iframe.style.display = '';
    } else {
      window.open(url, '_blank');
      return;
    }
    overlay.classList.add('open');
  }

  function saveVideoList() {
    if (!currentClient || !currentWorkbookId) return;
    const key = `${currentClient}|${currentWorkbookId}`;
    if (!workbookDetail[key]) workbookDetail[key] = {};
    workbookDetail[key].productVideos = _productVideos.slice();
    const dbId = dbWorkbookMap[key] || currentWorkbookId;
    const detail = collectWorkbookDetail();
    detail.productVideos = _productVideos.slice();
    apiCall('save_workbook_detail', { id: dbId, detail: detail });
    saveToLocalStorage();
  }

  /* ── Product Category / Subcategory ────────────────────────────────────── */
  const SUBCATEGORIES = {
    packaging: [
      'Polyethylene (PE)', 'Polypropylene (PP)', 'Polyvinyl Chloride (PVC)',
      'Polyethylene Terephthalate (PET)', 'Polylactic Acid (PLA)',
      'Polybutylene Adipate Terephthalate (PBAT)', 'Polyamide (PA / Nylon)',
      'Ethylene Vinyl Acetate (EVA)', 'Corrugated Cardboard', 'Kraft Paper',
      'Rigid Paperboard', 'Glass', 'Aluminum', 'Tin / Tinplate', 'Wood'
    ],
    apparel: [
      'Cotton', 'Polyester', 'Nylon', 'Silk', 'Wool', 'Linen', 'Rayon',
      'Spandex / Elastane', 'Bamboo Fiber', 'Hemp', 'Leather', 'Faux Leather',
      'Denim', 'Fleece', 'Mesh'
    ],
    furniture: [
      'Solid Wood', 'Plywood', 'MDF', 'Particle Board', 'Bamboo',
      'Steel', 'Aluminum', 'Wrought Iron', 'Rattan / Wicker',
      'Acrylic', 'Tempered Glass', 'Marble', 'Granite', 'Upholstered Fabric'
    ],
    electronics: [
      'ABS Plastic', 'Polycarbonate (PC)', 'Aluminum Alloy', 'Stainless Steel',
      'Silicone', 'TPU', 'FR-4 (PCB)', 'Copper', 'Glass (Display)', 'Ceramic'
    ],
    promotional: [
      'ABS Plastic', 'Silicone', 'Stainless Steel', 'Cotton', 'Polyester',
      'Neoprene', 'PVC', 'Rubber', 'Cork', 'Bamboo', 'Recycled Material'
    ],
    'food-beverage': [
      'Food-Grade PP', 'Food-Grade PE', 'Food-Grade Silicone', 'Stainless Steel (304/316)',
      'Borosilicate Glass', 'Ceramic', 'Bamboo', 'Kraft Paper (FDA)', 'PLA (Compostable)',
      'Aluminum (Food-Safe)'
    ],
    toys: [
      'ABS Plastic', 'PP', 'Plush (Polyester)', 'Wood (Beech/Maple)',
      'Silicone (BPA-Free)', 'EVA Foam', 'Cotton', 'Nylon', 'Rubber'
    ],
    beauty: [
      'Glass (Cosmetic)', 'PP (Cosmetic Grade)', 'PET', 'Aluminum',
      'Acrylic (PMMA)', 'Bamboo', 'PCR Plastic', 'Silicone', 'Ceramic'
    ],
    'home-garden': [
      'Ceramic', 'Terracotta', 'Stainless Steel', 'Cast Iron', 'Bamboo',
      'Cotton', 'Linen', 'Jute', 'Rattan', 'Teak', 'Resin', 'Concrete'
    ],
    sports: [
      'Nylon', 'Polyester', 'Neoprene', 'Silicone', 'EVA Foam', 'TPE',
      'Carbon Fiber', 'Aluminum', 'Rubber', 'Mesh', 'Spandex'
    ],
    stationery: [
      'Paper (Offset)', 'Kraft Paper', 'Recycled Paper', 'PU Leather',
      'PP', 'ABS', 'Bamboo', 'Wood', 'Metal (Brass/Steel)', 'Cork'
    ]
  };

  function updateSubcategories() {
    const cat  = document.getElementById('product-category').value;
    const cat2 = document.getElementById('product-category-2').value;
    const subSel  = document.getElementById('product-subcategory');
    const subSel2 = document.getElementById('product-subcategory-2');

    // Primary material — driven by primary category. Always tack on
    // "Other" at the end so the operator can fall back to typing a
    // custom material name (handled by _onMaterialChange below).
    const prev = subSel.value;
    subSel.innerHTML = '';
    if (!cat || !SUBCATEGORIES[cat]) {
      subSel.innerHTML = '<option value="">Select category first...</option>';
    } else {
      subSel.innerHTML = '<option value="">Select material type...</option>' +
        SUBCATEGORIES[cat].map(s => `<option value="${s}">${s}</option>`).join('') +
        '<option value="Other">Other…</option>';
      if (prev) subSel.value = prev; // restore if still valid
    }

    // Secondary material — union of primary + secondary category options
    const prev2 = subSel2.value;
    const cats = [cat, cat2].filter(c => c && SUBCATEGORIES[c]);
    const matOpts = cats.length
      ? [...new Set(cats.flatMap(c => SUBCATEGORIES[c]))]
      : Object.values(SUBCATEGORIES).flat();
    subSel2.innerHTML = '<option value="">None</option>' +
      matOpts.map(s => `<option value="${s}">${s}</option>`).join('') +
      '<option value="Other">Other…</option>';
    if (prev2) subSel2.value = prev2;
    document.getElementById('mat2-wrap').classList.toggle('has-value', !!subSel2.value);
    checkSecondaryLock();
    _onMaterialChange();
  }

  // Toggle the "Other" custom-material text input visibility based on
  // the current select value. Shown only when the operator picks
  // "Other"; the text they type is captured into productSubcategoryOther
  // (or productSubcategoryOther2) on save.
  function _onMaterialChange() {
    const sel  = document.getElementById('product-subcategory');
    const sel2 = document.getElementById('product-subcategory-2');
    const inp  = document.getElementById('product-subcategory-other');
    const inp2 = document.getElementById('product-subcategory-other-2');
    if (inp)  inp.style.display  = (sel  && sel.value  === 'Other') ? '' : 'none';
    if (inp2) inp2.style.display = (sel2 && sel2.value === 'Other') ? '' : 'none';
  }

  function checkSecondaryLock() {
    const cat = document.getElementById('product-category').value;
    const mat = document.getElementById('product-subcategory').value;
    const ready = !!(cat && mat);

    const cat2Wrap = document.getElementById('cat2-wrap');
    const mat2Wrap = document.getElementById('mat2-wrap');
    const cat2Sel  = document.getElementById('product-category-2');
    const mat2Sel  = document.getElementById('product-subcategory-2');

    if (ready) {
      cat2Wrap.classList.add('unlocked');
      mat2Wrap.classList.add('unlocked');
      cat2Sel.disabled = false;
      mat2Sel.disabled = false;
    } else {
      cat2Wrap.classList.remove('unlocked', 'has-value');
      mat2Wrap.classList.remove('unlocked', 'has-value');
      cat2Sel.disabled = true;  cat2Sel.value = '';
      mat2Sel.disabled = true;  mat2Sel.value = '';
    }
  }

  function onSecondaryChange(wrapId, sel) {
    document.getElementById(wrapId).classList.toggle('has-value', !!sel.value);
    if (_appReady) autoSaveWorkbook();
  }

  // Toggle the inline Secondary Material selector on / off. When OFF the
  // selector hides AND the value is cleared so a stale selection can't
  // sneak into the saved workbook. When ON the selector reveals inline
  // beside the primary Material Type and unlocks via checkSecondaryLock
  // (which still requires category + primary material to be filled in
  // before the dropdown becomes interactive).
  function onMat2ToggleVisibility() {
    const cb   = document.getElementById('mat2-toggle');
    const wrap = document.getElementById('mat2-wrap');
    if (!cb || !wrap) return;
    const on = !!cb.checked;
    wrap.style.display = on ? '' : 'none';
    if (!on) {
      const sel = document.getElementById('product-subcategory-2');
      const oth = document.getElementById('product-subcategory-other-2');
      if (sel) sel.value = '';
      if (oth) { oth.value = ''; oth.style.display = 'none'; }
      wrap.classList.remove('has-value');
    } else if (typeof checkSecondaryLock === 'function') {
      // Refresh lock state so the secondary dropdown enables the moment
      // the operator ticks the box (if category + primary material are
      // already set).
      checkSecondaryLock();
    }
    if (_appReady && typeof autoSaveWorkbook === 'function') autoSaveWorkbook();
  }

  /* ── Art Tab ─────────────────────────────────────────────────────────────── */
  let _artImages = [];
  let _clientLogo = null;

  async function handleClientLogoUpload(e) {
    const file = e.target.files[0];
    if (!file || !currentWorkbookId) return;
    const dbId = dbWorkbookMap[`${currentClient}|${currentWorkbookId}`] || currentWorkbookId;
    const formData = new FormData();
    formData.append('image', file);
    formData.append('workbook_id', dbId);
    const res = await fetch('api.php?action=upload_image', { method: 'POST', body: formData });
    const data = await res.json();
    if (data.success) {
      _clientLogo = data.url;
      renderClientLogo();
      saveClientLogo();
      rebuildSidebar();
    }
    e.target.value = '';
  }

  async function removeClientLogo() {
    if (!_clientLogo) return;
    try { await apiCall('delete_image', { url: _clientLogo }); } catch {}
    _clientLogo = null;
    renderClientLogo();
    saveClientLogo();
    rebuildSidebar();
  }

  function renderClientLogo() {
    const preview = document.getElementById('client-logo-preview');
    const placeholder = document.getElementById('client-logo-placeholder');
    const removeBtn = document.getElementById('client-logo-remove-btn');
    if (!preview) return;
    if (_clientLogo) {
      preview.style.border = '2px solid var(--border)';
      placeholder.style.display = 'none';
      let img = preview.querySelector('img');
      if (!img) { img = document.createElement('img'); preview.appendChild(img); }
      img.src = _clientLogo;
      img.style.cssText = 'width:100%; height:100%; object-fit:contain;';
      if (removeBtn) removeBtn.style.display = '';
    } else {
      preview.style.border = '2px dashed var(--border)';
      placeholder.style.display = '';
      const img = preview.querySelector('img');
      if (img) img.remove();
      if (removeBtn) removeBtn.style.display = 'none';
    }
  }

  function saveClientLogo() {
    const key = `${currentClient}|${currentWorkbookId}`;
    if (!workbookDetail[key]) workbookDetail[key] = {};
    workbookDetail[key].clientLogo = _clientLogo || '';
    const dbId = dbWorkbookMap[key] || currentWorkbookId;
    apiCall('save_workbook_detail', { id: dbId, detail: collectWorkbookDetail() });
  }

  async function handleArtFiles(e) {
    const files = Array.from(e.target.files);
    if (!files.length || !currentWorkbookId) return;
    const dbId = dbWorkbookMap[`${currentClient}|${currentWorkbookId}`] || currentWorkbookId;
    for (const file of files) {
      if (!file.type.startsWith('image/')) continue;
      const formData = new FormData();
      formData.append('image', file);
      formData.append('workbook_id', dbId);
      try {
        const res = await fetch('api.php?action=upload_image', { method: 'POST', body: formData });
        const data = await res.json();
        if (data.success) {
          _artImages.push({ url: data.url });
          renderArtGallery();
          saveArtList();
        }
      } catch (err) { console.warn('Art upload failed:', err); }
    }
    e.target.value = '';
  }

  async function removeArtImage(idx, e) {
    e.stopPropagation();
    const img = _artImages[idx];
    if (!img) return;
    try { await apiCall('delete_image', { url: img.url }); } catch (err) {}
    _artImages.splice(idx, 1);
    renderArtGallery();
    saveArtList();
  }

  function renderArtGallery() {
    const gallery = document.getElementById('artGallery');
    const addBtn = gallery.querySelector('.image-add-btn');
    gallery.querySelectorAll('.image-gallery-item').forEach(el => el.remove());
    _artImages.forEach((img, idx) => {
      const item = document.createElement('div');
      item.className = 'image-gallery-item';
      item.innerHTML = `
        <img src="${img.url}" alt="Art file ${idx+1}" onclick="openLightbox('${img.url}')" />
        <button class="img-remove" onclick="removeArtImage(${idx}, event)" title="Remove">✕</button>
      `;
      gallery.insertBefore(item, addBtn);
    });
  }

  function saveArtList() {
    if (!currentClient || !currentWorkbookId) return;
    const key = `${currentClient}|${currentWorkbookId}`;
    if (!workbookDetail[key]) workbookDetail[key] = {};
    workbookDetail[key].artImages = _artImages.map(i => i.url);
    const dbId = dbWorkbookMap[key] || currentWorkbookId;
    const detail = collectWorkbookDetail();
    apiCall('save_workbook_detail', { id: dbId, detail: detail });
    saveToLocalStorage();
  }

  /* ── Dimension Conversion ──────────────────────────────────────────────── */
  const IN_TO_MM = 25.4;
  let converting = false;

  function convertToMm(source) {
    if (converting) return;
    converting = true;
    ['l','w','h'].forEach(axis => {
      const inVal = parseFloat(document.getElementById(`dim-in-${axis}`).value);
      const mmEl  = document.getElementById(`dim-mm-${axis}`);
      mmEl.value  = isNaN(inVal) ? '' : (inVal * IN_TO_MM).toFixed(1);
    });
    converting = false;
  }

  function convertToIn(source) {
    if (converting) return;
    converting = true;
    ['l','w','h'].forEach(axis => {
      const mmVal = parseFloat(document.getElementById(`dim-mm-${axis}`).value);
      const inEl  = document.getElementById(`dim-in-${axis}`);
      inEl.value  = isNaN(mmVal) ? '' : (mmVal / IN_TO_MM).toFixed(3);
    });
    converting = false;
  }

  /* ── Weight Conversion (kg ↔ lbs) ─────────────────────────────────────── */
  const KG_TO_LBS = 2.20462;
  let convertingWeight = false;

  /* ── Carton Auto-Calculation ──────────────────────────────────────────── */
  function bestCartonDims(pL, pW, pH, qty, padding) {
    // Fill base layer first (side by side), then stack up
    // Primary score: minimize nz (layers stacked in height)
    // Secondary score: make base footprint (L×W) as square as possible
    // Returns { L, W, H, nx, ny, nz } where nx*ny*nz = qty
    let best = null, bestScore = Infinity;
    for (let a = 1; a <= qty; a++) {
      if (qty % a) continue;
      for (let b = a; b <= qty / a; b++) {
        if ((qty / a) % b) continue;
        const c = qty / a / b;
        [[a,b,c],[a,c,b],[b,a,c],[b,c,a],[c,a,b],[c,b,a]].forEach(([x,y,z]) => {
          const L = x * pL + padding, W = y * pW + padding, H = z * pH + padding;
          // z = items stacked in height — minimize this first, then square up the base
          const score = z * 1e8 + (L - W) * (L - W);
          if (score < bestScore) { bestScore = score; best = { L, W, H, nx: x, ny: y, nz: z }; }
        });
      }
    }
    return best;
  }

  function setCartonDimFields(prefix, L, W, H) {
    // Round UP to the nearest 0.1 — under-sized boxes don't actually fit
    // the product, so always round in the safe direction. Set cm and in
    // independently rather than going through convertDim, which uses
    // .toFixed(2) and would land us at e.g. 55.6cm / 21.89in instead of
    // a clean 55.6 / 21.9.
    const ceilTenth = v => Math.ceil(v * 10) / 10;
    const setAxis = (axis, cm) => {
      const cmEl = document.getElementById(prefix + '-' + axis + '-cm');
      const inEl = document.getElementById(prefix + '-' + axis + '-in');
      if (cmEl) cmEl.value = ceilTenth(cm).toFixed(1);
      if (inEl) inEl.value = ceilTenth(cm / 2.54).toFixed(1);
    };
    setAxis('l', L);
    setAxis('w', W);
    setAxis('h', H);
    // Refresh the 3D preview for whichever box just changed
    if (typeof renderBoxViz === 'function') {
      if (prefix === 'carton-inner')      renderBoxViz('inner');
      else if (prefix === 'carton-outer') renderBoxViz('outer');
    }
  }

  // Manual edit on inner cm/in: don't blow away the user's typed inner
  // dims via autoCalcCartons (which would re-derive from arrangement).
  // Instead, just propagate the new inner dims FORWARD to the outer
  // carton if outer arrangement is set.
  function recalcOuterFromInner() {
    const innerL = parseFloat(document.getElementById('carton-inner-l-cm')?.value);
    const innerW = parseFloat(document.getElementById('carton-inner-w-cm')?.value);
    const innerH = parseFloat(document.getElementById('carton-inner-h-cm')?.value);
    if (!innerL || !innerW || !innerH) return;
    const oRowQty   = parseInt(document.getElementById('carton-outer-row')?.value);
    const oSideQty  = parseInt(document.getElementById('carton-outer-side')?.value);
    const oStackQty = parseInt(document.getElementById('carton-outer-stack')?.value);
    const useArr    = (oRowQty >= 1) || (oSideQty >= 1) || (oStackQty >= 1);
    if (!useArr) {
      renderBoxViz('outer'); // dims unchanged but inner just changed — re-render
      return;
    }
    const oWallSel = parseInt(document.getElementById('carton-outer-wall')?.value) || 2;
    const oWallCm  = oWallSel === 2 ? 0.7 : 0.4;
    const r = oRowQty   >= 1 ? oRowQty   : 1;
    const s = oSideQty  >= 1 ? oSideQty  : 1;
    const h = oStackQty >= 1 ? oStackQty : 1;
    // count × (inner + 2*wall) — see autoCalcCartons for the rationale
    setCartonDimFields('carton-outer', r * (innerL + 2 * oWallCm), s * (innerW + 2 * oWallCm), h * (innerH + 2 * oWallCm));
    renderBoxViz('outer');
    if (typeof renderPalletViz === 'function') renderPalletViz();
    if (!_filling) autoSaveWorkbook();
  }

  // 3D box render — isometric SVG. Standard upper-front-right camera:
  // back ends up upper-LEFT, front lower-RIGHT.
  //   • Product: closed box (3 faces shaded).
  //   • Inner / Outer: open box — back/left/bottom inside walls drawn
  //     lightly, contents (products inside inner; inners inside outer)
  //     drawn as a Depth × Width × Height grid in proper z-order, then
  //     front + right outer walls drawn last.
  // Always labels L, W, H along the visible edges.
  function renderBoxViz(target) {
    const cfg = {
      product: { svg: 'viz-product', l: 'dim-cm-l',          w: 'dim-cm-w',          h: 'dim-cm-h',          accent: '#6b93ff' },
      inner:   { svg: 'viz-inner',   l: 'carton-inner-l-cm', w: 'carton-inner-w-cm', h: 'carton-inner-h-cm', accent: '#E8751A' },
      outer:   { svg: 'viz-outer',   l: 'carton-outer-l-cm', w: 'carton-outer-w-cm', h: 'carton-outer-h-cm', accent: '#4ade80' }
    }[target];
    if (!cfg) return;
    const svg = document.getElementById(cfg.svg);
    if (!svg) return;
    // Treat blank, zero, and NaN as "no dimensions". Trim handles
    // whitespace-only inputs that would otherwise parseFloat to NaN.
    const rawL = (document.getElementById(cfg.l)?.value || '').trim();
    const rawW = (document.getElementById(cfg.w)?.value || '').trim();
    const rawH = (document.getElementById(cfg.h)?.value || '').trim();
    const L = parseFloat(rawL);
    const W = parseFloat(rawW);
    const H = parseFloat(rawH);
    const hasAll = rawL !== '' && rawW !== '' && rawH !== '' &&
                   !isNaN(L) && !isNaN(W) && !isNaN(H) &&
                   L > 0 && W > 0 && H > 0;
    if (!hasAll) {
      // Wipe every child node first so no stale paths/polygons leak
      // through if the previous innerHTML replacement was deferred or
      // cached by the browser, then drop in a single placeholder text.
      while (svg.firstChild) svg.removeChild(svg.firstChild);
      const ns = 'http://www.w3.org/2000/svg';
      const txt = document.createElementNS(ns, 'text');
      txt.setAttribute('x', '120');
      txt.setAttribute('y', '90');
      txt.setAttribute('text-anchor', 'middle');
      txt.setAttribute('fill', '#9ba3c0');
      txt.setAttribute('font-family', 'inherit');
      txt.setAttribute('font-size', '12');
      txt.setAttribute('font-style', 'italic');
      txt.textContent = 'Enter dimensions';
      svg.appendChild(txt);
      return;
    }

    // Standard iso projection (camera upper-front-right): x → right,
    // y → up, z → away from viewer. Back (high z) lands upper-LEFT,
    // front (low z) lower-RIGHT.
    const cos30 = Math.cos(Math.PI / 6);
    const sin30 = 0.5;
    const proj = (x, y, z) => ({
      x: (x - z) * cos30,
      y: (x + z) * sin30 - y
    });

    const xL = -L/2, xR = L/2;
    const yB = -H/2, yT = H/2;
    const zF = -W/2, zB = W/2;
    const v = {
      bfl: proj(xL, yB, zF), bfr: proj(xR, yB, zF),
      bbl: proj(xL, yB, zB), bbr: proj(xR, yB, zB),
      tfl: proj(xL, yT, zF), tfr: proj(xR, yT, zF),
      tbl: proj(xL, yT, zB), tbr: proj(xR, yT, zB)
    };

    // Read arrangement for inner/outer; product renders as one solid cell
    // sized to the box itself. Each viz now follows the same pattern:
    // solid Option-B–style 3D box(es) inside, plus a thin wireframe
    // silhouette overlay so the cardboard outline reads.
    let contents;
    if (target === 'product') {
      contents = { depth: 1, width: 1, height: 1, color: cfg.accent };
    } else if (target === 'inner') {
      const d = parseInt(document.getElementById('carton-inner-row')?.value);
      const w = parseInt(document.getElementById('carton-inner-side')?.value);
      const h = parseInt(document.getElementById('carton-inner-stack')?.value);
      contents = (d >= 1 || w >= 1 || h >= 1)
        ? { depth: d || 1, width: w || 1, height: h || 1, color: '#6b93ff' }
        : null;
    } else if (target === 'outer') {
      const d = parseInt(document.getElementById('carton-outer-row')?.value);
      const w = parseInt(document.getElementById('carton-outer-side')?.value);
      const h = parseInt(document.getElementById('carton-outer-stack')?.value);
      contents = (d >= 1 || w >= 1 || h >= 1)
        ? { depth: d || 1, width: w || 1, height: h || 1, color: '#E8751A' }
        : null;
    }

    // Fit-to-viewBox scale + center, with padding for L/W/H labels.
    // Left padding sized to fit the horizontal H label ("999.9 cm H")
    // so it reads on a single line matching the L and W labels;
    // bottom padding for L/W brackets. Padding is generous so the
    // larger 13px label text doesn't crash the silhouette.
    const VBW = 240, VBH = 180;
    const PAD_L = 78, PAD_R = 22, PAD_TOP = 14, PAD_BOTTOM = 56;
    const allX = Object.values(v).map(p => p.x);
    const allY = Object.values(v).map(p => p.y);
    const minX = Math.min(...allX), maxX = Math.max(...allX);
    const minY = Math.min(...allY), maxY = Math.max(...allY);
    const sX = (VBW - PAD_L - PAD_R) / (maxX - minX || 1);
    const sY = (VBH - PAD_TOP - PAD_BOTTOM) / (maxY - minY || 1);
    const s  = Math.min(sX, sY);
    const cx = (PAD_L + (VBW - PAD_R)) / 2 - ((minX + maxX)/2) * s;
    const cy = (PAD_TOP + (VBH - PAD_BOTTOM)) / 2 - ((minY + maxY)/2) * s;
    const xform = p => ({ x: p.x * s + cx, y: p.y * s + cy });

    const polyStr = pts => pts.map(p => `${p.x.toFixed(1)},${p.y.toFixed(1)}`).join(' ');
    const c = cfg.accent;
    let html = '';

    // ── Unified Option-B rendering for product / inner / outer ─────────
    // All three vizes use the pallet-style camera (upper-back-right) so
    // the visible front face lands on the lower-LEFT of each box, the
    // right face on the lower-right, and the top face spans the top.
    // Cells (= the product itself for product viz; products for inner;
    // inners for outer) fill the box edge-to-edge with pallet shading
    // (top lighter, right base, front darker — all fully opaque).
    //
    // visualPad shrinks the entire cell stack a hair on every face so
    // there's a perceptible gap between the orange/blue fill and the
    // silhouette outline drawn afterwards. Without this, cells touch
    // the wireframe and the outline disappears under the fill.
    if (contents) {
      const { depth, width, height, color: cellC } = contents;
      const visualPad = Math.max(0.25, Math.min(L, W, H) * 0.04);
      const cellL = ((xR - xL) - 2 * visualPad) / depth;
      const cellW = ((zB - zF) - 2 * visualPad) / width;
      const cellH = ((yT - yB) - 2 * visualPad) / height;
      const topC   = shadeRgb(cellC,  25);
      const rightC = cellC;
      const frontC = shadeRgb(cellC, -40);
      const cellStrokeStyle = `stroke="rgba(0,0,0,0.20)" stroke-width="0.9" stroke-linejoin="round"`;
      // Painters' for upper-back-right camera: bottom→top, low z first
      // (far→near), low x first (far→near).
      for (let hi = 0; hi < height; hi++) {
        for (let wi = 0; wi < width; wi++) {
          for (let di = 0; di < depth; di++) {
            const cxLb = xL + visualPad + di * cellL,  cxRb = cxLb + cellL;
            const cyBb = yB + visualPad + hi * cellH,  cyTb = cyBb + cellH;
            const czFb = zF + visualPad + wi * cellW,  czBb = czFb + cellW;
            const cv = {
              bfl: proj(cxLb, cyBb, czFb), bfr: proj(cxRb, cyBb, czFb),
              bbl: proj(cxLb, cyBb, czBb), bbr: proj(cxRb, cyBb, czBb),
              tfl: proj(cxLb, cyTb, czFb), tfr: proj(cxRb, cyTb, czFb),
              tbl: proj(cxLb, cyTb, czBb), tbr: proj(cxRb, cyTb, czBb)
            };
            // Cell's BACK face (z=zB) reads as the visible front because
            // the camera looks from the +z side.
            const cFront = [cv.bbl, cv.bbr, cv.tbr, cv.tbl].map(xform);
            const cRight = [cv.bfr, cv.bbr, cv.tbr, cv.tfr].map(xform);
            const cTop   = [cv.tfl, cv.tfr, cv.tbr, cv.tbl].map(xform);
            html += `<polygon points="${polyStr(cFront)}" fill="${frontC}" ${cellStrokeStyle} />`;
            html += `<polygon points="${polyStr(cRight)}" fill="${rightC}" ${cellStrokeStyle} />`;
            html += `<polygon points="${polyStr(cTop)}"   fill="${topC}"   ${cellStrokeStyle} />`;
          }
        }
      }
    }
    // Silhouette-only outline: the 6 box edges that form the convex
    // hexagon hull in iso projection. Skipping the 6 interior edges
    // (the "Y" lines through the box) keeps the outline clean and
    // avoids the goofy back-corner crisscross that drawing all 12
    // edges produced. Polygon also closes the outline crisply at
    // each corner.
    const hullPath = ['tfl','tfr','bfr','bbr','bbl','tbl']
      .map(k => xform(v[k]))
      .map((p, i) => `${i === 0 ? 'M' : 'L'} ${p.x.toFixed(1)} ${p.y.toFixed(1)}`)
      .join(' ') + ' Z';
    html += `<path d="${hullPath}" fill="none" stroke="${c}" stroke-width="1.4" stroke-linejoin="round" stroke-opacity="0.9" />`;

    // ── Dimension labels (L, W, H) outside the silhouette ──────────────
    // Build a horizontal "L" bracket below the box, a slanted "W" bracket
    // angled to follow the right-bottom edge, and a vertical "H" bracket
    // on the LEFT outside of the box. Endpoints are extended with thin
    // extension lines so the dim ladder doesn't overlap the geometry.
    const tBfl = xform(v.bfl), tBfr = xform(v.bfr), tBbr = xform(v.bbr);
    const tTfl = xform(v.tfl), tTbl = xform(v.tbl), tBbl = xform(v.bbl);
    const allXf = [tBfl, tBfr, tBbr, tBbl, tTfl, xform(v.tfr), tTbl, xform(v.tbr)];
    const sxMin = Math.min(...allXf.map(p => p.x));
    const sxMax = Math.max(...allXf.map(p => p.x));
    const syMax = Math.max(...allXf.map(p => p.y));

    const TICK = 4;
    const drawDim = (a, b, labelPos, txt, anchor='middle', rotate=0) => {
      // Solid line from a to b with end ticks; text near labelPos
      let textT = '';
      if (rotate) {
        textT = `transform="rotate(${rotate} ${labelPos.x.toFixed(1)} ${labelPos.y.toFixed(1)})"`;
      }
      const perp = (() => {
        const dx = b.x - a.x, dy = b.y - a.y;
        const len = Math.sqrt(dx*dx + dy*dy) || 1;
        return { x: -dy/len * TICK, y: dx/len * TICK };
      })();
      return `
        <line x1="${a.x.toFixed(1)}" y1="${a.y.toFixed(1)}" x2="${b.x.toFixed(1)}" y2="${b.y.toFixed(1)}" stroke="${c}" stroke-width="1" />
        <line x1="${(a.x - perp.x).toFixed(1)}" y1="${(a.y - perp.y).toFixed(1)}" x2="${(a.x + perp.x).toFixed(1)}" y2="${(a.y + perp.y).toFixed(1)}" stroke="${c}" stroke-width="1" />
        <line x1="${(b.x - perp.x).toFixed(1)}" y1="${(b.y - perp.y).toFixed(1)}" x2="${(b.x + perp.x).toFixed(1)}" y2="${(b.y + perp.y).toFixed(1)}" stroke="${c}" stroke-width="1" />
        <text x="${labelPos.x.toFixed(1)}" y="${labelPos.y.toFixed(1)}" text-anchor="${anchor}" fill="${c}" font-family="inherit" font-size="13" font-weight="700" ${textT}>${txt}</text>
      `;
    };

    // Box centroid in screen coords — used to pick the OUTWARD perpendicular
    // for each dim bracket regardless of box proportions.
    const cxBox = allXf.reduce((s, p) => s + p.x, 0) / allXf.length;
    const cyBox = allXf.reduce((s, p) => s + p.y, 0) / allXf.length;
    // Pick whichever of the two perpendiculars to (a→b) points AWAY from
    // the centroid. More robust than the old sign-of-y heuristic, which
    // failed for boxes where the silhouette edge happened to slope the
    // "wrong" way relative to screen y.
    const outwardPerp = (a, b) => {
      const dx = b.x - a.x, dy = b.y - a.y;
      const len = Math.sqrt(dx*dx + dy*dy) || 1;
      const px = -dy/len, py = dx/len;
      const midX = (a.x + b.x)/2, midY = (a.y + b.y)/2;
      const dot = px*(midX - cxBox) + py*(midY - cyBox);
      return dot >= 0 ? { x: px, y: py } : { x: -px, y: -py };
    };

    // Bracket bars tucked CLOSE to the box; labels sit well past the
    // bars so the bar lines never cross the text. Per the user's
    // request, we pulled the lines toward the model and let the text
    // hang out further away.

    // L (length) — bracket along the back-bottom edge bbl→bbr.
    const lOff = 12;        // bar this far from the box silhouette edge
    const lLabelGap = 32;   // text baseline this far past the bar
    const lP = outwardPerp(tBbl, tBbr);
    const lA = { x: tBbl.x + lP.x*lOff, y: tBbl.y + lP.y*lOff };
    const lB = { x: tBbr.x + lP.x*lOff, y: tBbr.y + lP.y*lOff };
    const lMid = { x: (lA.x + lB.x)/2 + lP.x*lLabelGap, y: (lA.y + lB.y)/2 + lP.y*lLabelGap + 4 };
    html += drawDim(lA, lB, lMid, `${L.toFixed(1)} cm L`);

    // W (depth) — bracket along the right-bottom edge bfr→bbr.
    const wOff = 12;
    const wLabelGap = 32;
    const wP = outwardPerp(tBfr, tBbr);
    const wA = { x: tBfr.x + wP.x*wOff, y: tBfr.y + wP.y*wOff };
    const wB = { x: tBbr.x + wP.x*wOff, y: tBbr.y + wP.y*wOff };
    const wMid = { x: (wA.x + wB.x)/2 + wP.x*wLabelGap, y: (wA.y + wB.y)/2 + wP.y*wLabelGap + 4 };
    html += drawDim(wA, wB, wMid, `${W.toFixed(1)} cm W`);

    // H (height) — bracket vertical, hugging the box's left silhouette.
    // Label reads horizontally (no rotation) so it matches the L and W
    // labels: text is right-anchored so its right edge sits a hair to
    // the left of the bracket bar regardless of box width.
    const hX = sxMin - 12;
    const hA = { x: hX, y: tTbl.y };
    const hB = { x: hX, y: tBbl.y };
    const hLabelPos = { x: hX - 8, y: (hA.y + hB.y)/2 + 4 };
    html += drawDim(hA, hB, hLabelPos, `${H.toFixed(1)} cm H`, 'end', 0);

    svg.innerHTML = html;
  }

  // Back-solve handler for "Qty (Units per Outer Carton)". The user types
  // a target like 10 — we divide by units-per-inner to get inner cartons
  // per outer, write that to carton-outer-count, and clear any explicit
  // Row/Side/Height arrangement so the explicit count is what drives the
  // outer dims (autoCalcCartons' arrangement path would otherwise override
  // the back-solved count).
  function onOuterUnitsInput() {
    const targetUnits = parseInt(document.getElementById('carton-outer-units')?.value);
    const innerCount  = parseInt(document.getElementById('carton-inner-count')?.value) || 0;
    if (!isNaN(targetUnits) && targetUnits > 0 && innerCount > 0) {
      // Round up — partial outer cartons aren't a thing, you'd need a
      // full outer to hold any leftover inners.
      const outerCount = Math.ceil(targetUnits / innerCount);
      const outerCountEl = document.getElementById('carton-outer-count');
      if (outerCountEl) outerCountEl.value = outerCount;
      // Clear arrangement so the back-solved count becomes authoritative.
      ['carton-outer-row','carton-outer-side','carton-outer-stack'].forEach(id => {
        const el = document.getElementById(id);
        if (el && el !== document.activeElement) el.value = '';
      });
    }
    autoCalcCartons();
    updateOuterWeightHint();
  }

  function autoCalcCartons() {
    const pL = parseFloat(document.getElementById('dim-cm-l').value);
    const pW = parseFloat(document.getElementById('dim-cm-w').value);
    const pH = parseFloat(document.getElementById('dim-cm-h').value);
    const outerQty = parseInt(document.getElementById('carton-outer-count').value);  // inner cartons per outer carton

    // Row × Side × Height arrangement (explicit-control path). When at
    // least one of Row/Side/Height is set we drive the inner carton from
    // these directly instead of guessing via bestCartonDims. Missing axes
    // default to 1 (single product on that axis). Wall thickness comes
    // from the single/double-wall dropdown (4mm or 7mm per side).
    const rowQty   = parseInt(document.getElementById('carton-inner-row')?.value);
    const sideQty  = parseInt(document.getElementById('carton-inner-side')?.value);
    const stackQty = parseInt(document.getElementById('carton-inner-stack')?.value);
    const wallSel  = parseInt(document.getElementById('carton-inner-wall')?.value) || 1;
    const wallCm   = wallSel === 2 ? 0.7 : 0.4;  // single ≈ 4mm, double ≈ 7mm
    const PADDING = 2; // 2cm fallback for the legacy bestCartonDims path

    if (!pL || !pW || !pH) return;

    let innerDims = null;
    let innerQty  = parseInt(document.getElementById('carton-inner-count').value);

    const productWeightKg = parseFloat(document.getElementById('dim-weight-kg').value);

    const setHint = (id, nx, ny, nz, itemWord) => {
      const el = document.getElementById(id);
      if (!el) return;
      el.style.display = '';
      const layerNote = nz > 1 ? ` × ${nz} layers` : ' (single layer)';
      el.textContent = `${nx} × ${ny}${layerNote}  =  ${nx * ny * nz} ${itemWord}`;
    };

    const useArrangement = (rowQty >= 1) || (sideQty >= 1) || (stackQty >= 1);

    // ── Inner carton: explicit Row × Side × Height path takes precedence ──
    if (useArrangement) {
      const r = rowQty   >= 1 ? rowQty   : 1;
      const s = sideQty  >= 1 ? sideQty  : 1;
      const h = stackQty >= 1 ? stackQty : 1;
      const innerL = pL * r + 2 * wallCm;
      const innerW = pW * s + 2 * wallCm;
      const innerH = pH * h + 2 * wallCm;
      innerDims = { L: innerL, W: innerW, H: innerH, nx: r, ny: s, nz: h };
      setCartonDimFields('carton-inner', innerL, innerW, innerH);
      // Auto-fill the Qty field from Row × Side × Height
      innerQty = r * s * h;
      const qtyEl = document.getElementById('carton-inner-count');
      if (qtyEl && qtyEl !== document.activeElement) qtyEl.value = innerQty;
      setHint('inner-arrange-hint', r, s, h, innerQty === 1 ? 'unit' : 'units');
      if (!isNaN(productWeightKg) && productWeightKg > 0) {
        document.getElementById('carton-inner-weight').value = (productWeightKg * innerQty).toFixed(2);
        convertWeight('carton-inner-weight', 'carton-inner-weight-lbs', 'kg');
      }
      const badge = document.getElementById('inner-calc-badge');
      if (badge) badge.style.display = '';
    } else if (innerQty >= 1) {
      // ── Legacy path: pack innerQty products into the smallest box ──
      innerDims = bestCartonDims(pL, pW, pH, innerQty, PADDING);
      setCartonDimFields('carton-inner', innerDims.L, innerDims.W, innerDims.H);
      setHint('inner-arrange-hint', innerDims.nx, innerDims.ny, innerDims.nz, innerQty === 1 ? 'unit' : 'units');
      if (!isNaN(productWeightKg) && productWeightKg > 0) {
        document.getElementById('carton-inner-weight').value = (productWeightKg * innerQty).toFixed(2);
        convertWeight('carton-inner-weight', 'carton-inner-weight-lbs', 'kg');
      }
      const badge = document.getElementById('inner-calc-badge');
      if (badge) badge.style.display = '';
    } else {
      const h = document.getElementById('inner-arrange-hint');
      if (h) h.style.display = 'none';
    }

    // ── Outer carton ──────────────────────────────────────────────────
    // Mirrors the inner: explicit Row × Side × Height + Box Wall path takes
    // precedence over the legacy "fit outerQty inner cartons in the
    // smallest box" packing. Outer wall defaults to double (≈7mm) since
    // shipping cartons are usually heavier-duty than inners.
    const oRowQty   = parseInt(document.getElementById('carton-outer-row')?.value);
    const oSideQty  = parseInt(document.getElementById('carton-outer-side')?.value);
    const oStackQty = parseInt(document.getElementById('carton-outer-stack')?.value);
    const oWallSel  = parseInt(document.getElementById('carton-outer-wall')?.value) || 2;
    const oWallCm   = oWallSel === 2 ? 0.7 : 0.4;
    const oUseArrangement = (oRowQty >= 1) || (oSideQty >= 1) || (oStackQty >= 1);

    let resolvedOuterCount = outerQty;

    if (oUseArrangement && innerDims) {
      const r = oRowQty   >= 1 ? oRowQty   : 1;
      const s = oSideQty  >= 1 ? oSideQty  : 1;
      const h = oStackQty >= 1 ? oStackQty : 1;
      // count × (inner_dim + 2 × wall) — each inner carton occupies its own
      // footprint plus a wall thickness on every side. Doubling Width takes
      // outer_W from inner_W + 2*wall to 2 × (inner_W + 2*wall), which is
      // what the user gets when they account for every wall around every
      // inner. Adjacent inners share contact surfaces but each contributes
      // its own wall thickness to the total.
      const outerL = r * (innerDims.L + 2 * oWallCm);
      const outerW = s * (innerDims.W + 2 * oWallCm);
      const outerH = h * (innerDims.H + 2 * oWallCm);
      setCartonDimFields('carton-outer', outerL, outerW, outerH);
      // Auto-fill the Qty (Inner Cartons per Outer) field from arrangement
      resolvedOuterCount = r * s * h;
      const qtyEl = document.getElementById('carton-outer-count');
      if (qtyEl && qtyEl !== document.activeElement) qtyEl.value = resolvedOuterCount;
      setHint('outer-arrange-hint', r, s, h, resolvedOuterCount === 1 ? 'inner' : 'inners');
      if (!isNaN(productWeightKg) && productWeightKg > 0) {
        const productsPerOuter = innerQty >= 1 ? innerQty * resolvedOuterCount : resolvedOuterCount;
        document.getElementById('carton-outer-weight').value = (productWeightKg * productsPerOuter).toFixed(2);
        convertWeight('carton-outer-weight', 'carton-outer-weight-lbs', 'kg');
      }
      const badge = document.getElementById('outer-calc-badge');
      if (badge) badge.style.display = '';
    } else if (outerQty >= 1) {
      // Legacy path — pack outerQty inner cartons into the smallest box
      let outerDims;
      if (innerDims) {
        outerDims = bestCartonDims(innerDims.L, innerDims.W, innerDims.H, outerQty, PADDING);
        setHint('outer-arrange-hint', outerDims.nx, outerDims.ny, outerDims.nz, outerQty === 1 ? 'inner' : 'inners');
      } else {
        outerDims = bestCartonDims(pL, pW, pH, outerQty, PADDING);
        setHint('outer-arrange-hint', outerDims.nx, outerDims.ny, outerDims.nz, outerQty === 1 ? 'unit' : 'units');
      }
      setCartonDimFields('carton-outer', outerDims.L, outerDims.W, outerDims.H);
      if (!isNaN(productWeightKg) && productWeightKg > 0) {
        const productsPerOuter = innerDims && innerQty >= 1 ? innerQty * outerQty : outerQty;
        document.getElementById('carton-outer-weight').value = (productWeightKg * productsPerOuter).toFixed(2);
        convertWeight('carton-outer-weight', 'carton-outer-weight-lbs', 'kg');
      }
      const badge = document.getElementById('outer-calc-badge');
      if (badge) badge.style.display = '';
    } else {
      const h = document.getElementById('outer-arrange-hint');
      if (h) h.style.display = 'none';
    }

    // Auto-fill "Qty (Units per Outer Carton)" = inner units × inner cartons
    // per outer. Skipped when the user is actively typing in this field
    // (onOuterUnitsInput handles the back-solve direction in that case).
    const unitsPerOuterEl = document.getElementById('carton-outer-units');
    if (unitsPerOuterEl && unitsPerOuterEl !== document.activeElement) {
      const u = (innerQty >= 1 && resolvedOuterCount >= 1) ? innerQty * resolvedOuterCount : 0;
      unitsPerOuterEl.value = u > 0 ? u : '';
    }

    renderPalletViz();
    updateOuterWeightHint();
    if (typeof _updateSectionSummary === 'function') _updateSectionSummary('dimensions');
  }

  // Was the source of the legacy "Est. total outer weight" hint UI; that
  // banner has been removed in favor of the new arrangement controls.
  // The function now just keeps carton-outer-weight in sync with
  // (inner weight × inner cartons per outer) and refreshes freight.
  function updateOuterWeightHint() {
    const innerKg  = parseFloat(document.getElementById('carton-inner-weight')?.value) || 0;
    const outerQty = parseInt(document.getElementById('carton-outer-count')?.value) || 0;
    if (!innerKg || !outerQty) return;
    const totalKg  = innerKg * outerQty;
    const outerWtEl = document.getElementById('carton-outer-weight');
    if (outerWtEl) {
      outerWtEl.value = totalKg.toFixed(2);
      convertWeight('carton-outer-weight', 'carton-outer-weight-lbs', 'kg');
      calcFreight();
    }
  }

  /* ── Pallet Visualization ─────────────────────────────────────────────── */
  const PALLET_L = 101.6;    // cm (40 in)
  const PALLET_W = 121.92;   // cm (48 in)
  const PALLET_DECK = 15;    // cm pallet deck height
  const MAX_LOAD_H_DEFAULT = 152.4; // cm default max stack height (60 in)
  const ISO_COS30 = Math.cos(Math.PI / 6); // 0.866
  const ISO_SIN30 = 0.5;

  // Camera from above: +x goes right-down, +z goes left-down, +y goes up
  function isoProj(wx, wy, wz, s, ox, oy) {
    return {
      x: ox + (wx - wz) * ISO_COS30 * s,
      y: oy + (wx + wz) * ISO_SIN30 * s - wy * s
    };
  }

  function isoFace(ctx, pts, fill, stroke) {
    ctx.beginPath();
    ctx.moveTo(pts[0].x, pts[0].y);
    for (let i = 1; i < pts.length; i++) ctx.lineTo(pts[i].x, pts[i].y);
    ctx.closePath();
    ctx.fillStyle = fill;
    ctx.fill();
    ctx.strokeStyle = stroke || 'rgba(0,0,0,0.13)';
    ctx.lineWidth = 0.6;
    ctx.stroke();
  }

  function shadeRgb(hex, amt) {
    const n = parseInt(hex.replace('#',''), 16);
    const r = Math.min(255, Math.max(0, (n>>16) + amt));
    const g = Math.min(255, Math.max(0, ((n>>8)&0xff) + amt));
    const b = Math.min(255, Math.max(0, (n&0xff) + amt));
    return `rgb(${r},${g},${b})`;
  }

  function drawIsoBox(ctx, wx, wy, wz, bw, bh, bd, s, ox, oy, hex) {
    const p = (x,y,z) => isoProj(x,y,z,s,ox,oy);
    // Top face (+y) — brightest
    isoFace(ctx, [p(wx,wy+bh,wz), p(wx+bw,wy+bh,wz), p(wx+bw,wy+bh,wz+bd), p(wx,wy+bh,wz+bd)], shadeRgb(hex, 25));
    // Right face (+x at wx+bw) — medium
    isoFace(ctx, [p(wx+bw,wy,wz), p(wx+bw,wy,wz+bd), p(wx+bw,wy+bh,wz+bd), p(wx+bw,wy+bh,wz)], hex);
    // Front face (+z at wz+bd) — darkest
    isoFace(ctx, [p(wx,wy,wz+bd), p(wx+bw,wy,wz+bd), p(wx+bw,wy+bh,wz+bd), p(wx,wy+bh,wz+bd)], shadeRgb(hex, -40));
  }

  function bestPalletOrientation(bL, bW) {
    const o1 = { cols: Math.floor(PALLET_L/bL), rows: Math.floor(PALLET_W/bW), bL, bW };
    const o2 = { cols: Math.floor(PALLET_L/bW), rows: Math.floor(PALLET_W/bL), bL: bW, bW: bL };
    return (o1.cols * o1.rows >= o2.cols * o2.rows) ? o1 : o2;
  }

  // Manual-mode toggle handler — flips the pallet calc between
  // standard (carton-driven) and manual (product-direct) mode.
  // In manual mode:
  //   • Inner / Outer Carton columns gray out (data-carton-col="inner|outer")
  //   • Pallet stats use product L×W×H to fit products directly on
  //     the 40 × 48 base
  //   • The "Total Outer Cartons to Ship" label flips to
  //     "Total Units to Ship" and the placeholder/hint update too
  // Persists to detail.palletManual via autosave so the toggle
  // stays set across reloads.
  function onPalletManualToggle() {
    const cb = document.getElementById('pallet-manual');
    const on = !!(cb && cb.checked);
    document.querySelectorAll('.specs-col[data-carton-col]').forEach(col => {
      col.classList.toggle('pallet-manual-disabled', on);
    });
    // 4 mm divider option is only meaningful when fitting products
    // directly on the pallet — hide the row in carton mode.
    const dividerWrap = document.getElementById('pallet-divider-wrap');
    if (dividerWrap) dividerWrap.style.display = on ? '' : 'none';
    // Label / placeholder / hint stay as "Total Units to Ship" in
    // BOTH modes now — the pallet view derives cartons + pallets
    // from the unit count automatically. Pull the current RFQ grand
    // qty into the input whenever the toggle changes.
    if (typeof syncManualPalletTotalUnits === 'function') syncManualPalletTotalUnits();
    renderPalletViz();
    // The shipping tab pulls dims/weight/count from PRODUCT in manual
    // mode and OUTER CARTON otherwise — refresh both functions so the
    // freight calc + dim display flip correctly when the toggle changes.
    if (typeof syncShippingDims === 'function') syncShippingDims();
    if (typeof calcFreight === 'function') calcFreight();
    if (typeof autoSaveWorkbook === 'function' && !_filling) autoSaveWorkbook();
  }

  // ── Product Dimensions Lock ─────────────────────────────────────────
  // When checked, the L/W/H/weight inputs in the Product column become
  // read-only so the operator can't accidentally edit them, AND the
  // pallet-fit optimiser refuses to suggest any outer-carton footprint
  // SMALLER than the locked product dims on any axis (a carton has to
  // contain the product). The lock state lives on the checkbox + a
  // .product-dims-locked class on the input row, plus persists to
  // detail.productDimsLocked so a hard refresh keeps the lock.
  function onProductDimsLockToggle() {
    const cb = document.getElementById('product-dims-lock');
    if (!cb) return;
    const on = !!cb.checked;
    ['dim-cm-l', 'dim-in-l', 'dim-cm-w', 'dim-in-w',
     'dim-cm-h', 'dim-in-h', 'dim-weight-kg', 'dim-weight-lbs'
    ].forEach(id => {
      const el = document.getElementById(id);
      if (el) el.disabled = on;
    });
    // Re-run the pallet view so the side-by-side "Most Efficient"
    // pane respects the new lock immediately.
    if (typeof renderPalletViz === 'function') renderPalletViz();
    if (typeof autoSaveWorkbook === 'function' && !_filling) autoSaveWorkbook();
  }

  // ── Weight-Only Override ────────────────────────────────────────────
  // When ticked, the operator skips ALL dim sections and just types
  // Case Qty + per-case Weight. Shipping freight reads those two
  // numbers as the Actual Weight bucket. Inner / Outer columns get
  // the same pallet-manual-disabled gray-out; the Product column
  // grays its dim grid + 3D viz but leaves the override controls
  // themselves fully interactive (they live in the same column).
  function onWeightOnlyToggle() {
    const cb = document.getElementById('weight-only-override');
    if (!cb) return;
    const on = !!cb.checked;
    // Toggle the override fields' enabled/disabled visuals.
    const fields = document.getElementById('weight-only-fields');
    if (fields) {
      fields.style.opacity = on ? '' : '0.45';
      fields.style.pointerEvents = on ? '' : 'none';
    }
    ['weight-only-qty', 'weight-only-kg', 'weight-only-lbs'].forEach(id => {
      const el = document.getElementById(id);
      if (el) el.disabled = !on;
    });
    // Gray out the OTHER columns (Inner + Outer) and the Product
    // dim grid above this block.
    document.querySelectorAll('.specs-col[data-carton-col]').forEach(col => {
      col.classList.toggle('weight-only-disabled', on);
    });
    const productCol = document.querySelector('.specs-col:not([data-carton-col])');
    if (productCol) productCol.classList.toggle('weight-only-locked', on);
    // Pallet View card (which also hosts the Container View) grays out
    // wholesale — the dim-driven pallet/container math has no inputs
    // to work with in weight-only mode.
    const palletCard = document.querySelector('.section-card[data-section="pallet"]');
    if (palletCard) palletCard.classList.toggle('weight-only-disabled', on);
    // Also disable the manual-mode pallet checkbox if override is on
    // — the two modes are mutually exclusive.
    const palletManualEl = document.getElementById('pallet-manual');
    if (palletManualEl) {
      palletManualEl.disabled = on;
      if (on && palletManualEl.checked) {
        palletManualEl.checked = false;
        if (typeof onPalletManualToggle === 'function') onPalletManualToggle();
      }
    }
    onWeightOnlyChanged();
    // Refresh dependent views.
    if (typeof renderPalletViz === 'function') renderPalletViz();
    if (typeof syncShippingDims === 'function') syncShippingDims();
    if (typeof calcFreight === 'function') calcFreight();
    if (typeof autoSaveWorkbook === 'function' && !_filling) autoSaveWorkbook();
  }
  // Recompute the Actual Weight sub-text + push the values downstream
  // every time Case Qty / Weight (kg|lb) changes. Doesn't touch the
  // override checkbox state.
  function onWeightOnlyChanged() {
    const qty = parseInt(document.getElementById('weight-only-qty')?.value) || 0;
    const wt  = parseFloat(document.getElementById('weight-only-kg')?.value) || 0;
    const hint = document.getElementById('weight-only-actual-hint');
    if (hint) {
      if (qty > 0 && wt > 0) {
        const totalKg = qty * wt;
        const totalLb = totalKg * 2.20462;
        const fmt = (n) => n < 10 ? n.toFixed(2) : n.toLocaleString('en-US', { maximumFractionDigits: 2 });
        hint.innerHTML = `↳ Actual Weight: <strong>${fmt(totalKg)} kg</strong> <span style="opacity:0.7;">/ ${fmt(totalLb)} lb</span> <span style="opacity:0.7;">(${qty.toLocaleString()} × ${wt} kg)</span>`;
      } else {
        hint.innerHTML = `Enter Case Qty + Weight to see the total Actual Weight.`;
      }
    }
    if (typeof syncShippingDims === 'function') syncShippingDims();
    if (typeof calcFreight === 'function') calcFreight();
    if (typeof autoSaveWorkbook === 'function' && !_filling) autoSaveWorkbook();
    if (typeof _updateSectionSummary === 'function') _updateSectionSummary('dimensions');
  }

  // ── Case Only Override ──────────────────────────────────────────────
  // Mirrors Weight Only Override but with case-level inputs (products
  // per case, cases per order, case L × W × H × weight). When ticked:
  //   • Product Dimensions + Outer Carton columns gray out (Inner
  //     dim grid stays grayed too — only the override block stays
  //     interactive)
  //   • Weight-only + pallet-manual modes lock OFF since the three
  //     overrides are mutually exclusive
  //   • Pallet view + container view treat each CASE as the ship
  //     unit (case footprint on the pallet base, case stack height
  //     drives layers, case weight × case count drives the totals)
  //   • Shipping freight reads case dims/weight × case count
  function onCaseOnlyToggle() {
    const cb = document.getElementById('case-only-override');
    if (!cb) return;
    const on = !!cb.checked;
    // Toggle visuals on the override fields themselves.
    const fields = document.getElementById('case-only-fields');
    if (fields) {
      fields.style.opacity = on ? '' : '0.45';
      fields.style.pointerEvents = on ? '' : 'none';
    }
    ['case-only-products-per', 'case-only-cases-order',
     'case-only-l-cm', 'case-only-l-in', 'case-only-w-cm', 'case-only-w-in',
     'case-only-h-cm', 'case-only-h-in',
     'case-only-weight-kg', 'case-only-weight-lbs'
    ].forEach(id => {
      const el = document.getElementById(id);
      if (el) el.disabled = !on;
    });
    // Gray out the Product + Outer columns. Inner dim grid grays too
    // (matches the weight-only treatment) — only the case override
    // controls stay interactive.
    const productCol = document.querySelector('.specs-col:not([data-carton-col])');
    if (productCol) productCol.classList.toggle('weight-only-locked', on);
    document.querySelectorAll('.specs-col[data-carton-col="outer"]').forEach(col => {
      col.classList.toggle('weight-only-disabled', on);
    });
    // Inner dim grid (sibling of the override block) — gray out via
    // the same locked class on the inner column.
    const innerCol = document.querySelector('.specs-col[data-carton-col="inner"]');
    if (innerCol) innerCol.classList.toggle('weight-only-locked', on);
    // Mutually exclusive with the other override modes.
    const weightOnlyEl   = document.getElementById('weight-only-override');
    const palletManualEl = document.getElementById('pallet-manual');
    if (on) {
      if (weightOnlyEl   && weightOnlyEl.checked)   { weightOnlyEl.checked   = false; if (typeof onWeightOnlyToggle === 'function') onWeightOnlyToggle(); }
      if (palletManualEl && palletManualEl.checked) { palletManualEl.checked = false; if (typeof onPalletManualToggle === 'function') onPalletManualToggle(); }
    }
    if (weightOnlyEl)   weightOnlyEl.disabled   = on;
    if (palletManualEl) palletManualEl.disabled = on;
    // Restore the Total Units input + hint when turning OFF so the
    // operator can type freely / re-sync from RFQ. onCaseOnlyChanged
    // will re-lock + re-derive when ON.
    if (!on) {
      const palletTotalEl = document.getElementById('pallet-total-cartons');
      if (palletTotalEl) {
        palletTotalEl.readOnly = false;
        delete palletTotalEl.dataset.caseLocked;
      }
      if (typeof _refreshPalletTotalHint === 'function') _refreshPalletTotalHint();
    }
    onCaseOnlyChanged();
    if (typeof renderPalletViz === 'function') renderPalletViz();
    if (typeof syncShippingDims === 'function') syncShippingDims();
    if (typeof calcFreight === 'function') calcFreight();
    if (typeof autoSaveWorkbook === 'function' && !_filling) autoSaveWorkbook();
  }
  function onCaseOnlyChanged() {
    const pc  = _msIntFromInput(document.getElementById('case-only-products-per'));
    const co  = _msIntFromInput(document.getElementById('case-only-cases-order'));
    const wt  = parseFloat(document.getElementById('case-only-weight-kg')?.value) || 0;
    const lCm = parseFloat(document.getElementById('case-only-l-cm')?.value) || 0;
    const wCm = parseFloat(document.getElementById('case-only-w-cm')?.value) || 0;
    const hCm = parseFloat(document.getElementById('case-only-h-cm')?.value) || 0;
    // Auto-mirror products-per-case × cases-per-order into the Total
    // Units to Ship input so the pallet view + container math + Last
    // Container Room-to-Fill all read the case-derived total instead
    // of a stale RFQ Grand Total qty. The input is also flagged
    // read-only via data-case-locked so the field visibly grays out
    // (handled in CSS) and any typed override gets ignored.
    const palletTotalEl = document.getElementById('pallet-total-cartons');
    if (palletTotalEl) {
      const caseOn = !!document.getElementById('case-only-override')?.checked;
      if (caseOn && pc > 0 && co > 0) {
        const total = pc * co;
        palletTotalEl.value = total.toLocaleString('en-US');
        palletTotalEl.readOnly = true;
        palletTotalEl.dataset.caseLocked = '1';
        palletTotalEl.dataset.looseTopOff = '';   // clear any stale loose flag
        palletTotalEl.dataset.lastRfqSync  = '';  // case-only overrides the RFQ sync
        // Update the hint under the input so it stops promising an
        // RFQ Grand Total auto-fill that doesn't apply in case mode.
        const palletTotalHint = document.getElementById('pallet-total-hint');
        if (palletTotalHint) {
          palletTotalHint.innerHTML = `Auto-derived from <strong>Case Only Override</strong>: ${pc.toLocaleString()} products/case × ${co.toLocaleString()} cases = <strong>${total.toLocaleString()}</strong> products.`;
        }
      } else if (caseOn) {
        // Case mode is on but Products/Case or Cases/Order isn't filled
        // in yet — clear the input + lock so we don't carry a stale RFQ
        // qty forward.
        palletTotalEl.value = '';
        palletTotalEl.readOnly = true;
        palletTotalEl.dataset.caseLocked = '1';
      } else {
        palletTotalEl.readOnly = false;
        delete palletTotalEl.dataset.caseLocked;
      }
    }
    const hint = document.getElementById('case-only-hint');
    if (hint) {
      if (pc > 0 && co > 0) {
        const totalProducts = pc * co;
        const totalKg = wt > 0 ? wt * co : 0;
        const totalLb = totalKg * 2.20462;
        // CBM per case = L × W × H (cm) / 1,000,000 → m³. Total CBM
        // scales linearly with case count. Shown as N.NN m³ at high
        // volumes, N.NNN m³ when the per-case volume is sub-litre.
        const cbmPer   = (lCm > 0 && wCm > 0 && hCm > 0) ? (lCm * wCm * hCm) / 1_000_000 : 0;
        const cbmTotal = cbmPer * co;
        const fmt = (n) => n < 10 ? n.toFixed(2) : n.toLocaleString('en-US', { maximumFractionDigits: 2 });
        const fmtCbm = (m3) => m3 < 0.01
          ? m3.toFixed(4) + ' m³'
          : (m3 < 1 ? m3.toFixed(3) + ' m³' : m3.toLocaleString('en-US', { maximumFractionDigits: 2 }) + ' m³');
        const wPart = totalKg > 0
          ? `<br>↳ Weight: <strong>${fmt(totalKg)} kg</strong> <span style="opacity:0.7;">/ ${fmt(totalLb)} lb</span> total (${fmt(wt)} kg × ${co.toLocaleString()})`
          : '';
        const cbmPart = cbmPer > 0
          ? `<br>↳ Volume: <strong>${fmtCbm(cbmPer)}</strong> per case &nbsp;·&nbsp; <strong>${fmtCbm(cbmTotal)}</strong> total (${co.toLocaleString()} case${co === 1 ? '' : 's'})`
          : '';
        // Lead with the explicit multiplication so the operator can
        // read the total at a glance: "2,500 × 40 = 100,000 products"
        hint.innerHTML = `↳ <strong>${pc.toLocaleString()}</strong> × <strong>${co.toLocaleString()}</strong> = <strong style="color:var(--accent);">${totalProducts.toLocaleString()}</strong> products${wPart}${cbmPart}`;
      } else {
        hint.innerHTML = 'Enter Products/Case + Cases/Order + case L × W × H to drive the pallet view.';
      }
    }
    if (typeof renderPalletViz === 'function') renderPalletViz();
    if (typeof syncShippingDims === 'function') syncShippingDims();
    if (typeof calcFreight === 'function') calcFreight();
    if (typeof autoSaveWorkbook === 'function' && !_filling) autoSaveWorkbook();
    if (typeof _updateSectionSummary === 'function') _updateSectionSummary('dimensions');
  }
  // Returns whether Case Only Override is currently active.
  function _caseOnlyActive() {
    return !!document.getElementById('case-only-override')?.checked;
  }

  // ── Ship-mode helpers — SINGLE SOURCE OF TRUTH ───────────────────────
  // Every pallet/container/freight consumer needs to know three things:
  //
  //   1. Which mode is active (case-only / manual / default carton)
  //   2. How many products are inside each ship-item (44 for cases,
  //      1 for manual, inner×outer for carton mode)
  //   3. The canonical "Total Units to Ship" — in case-only mode this
  //      is products/case × cases/order, and falls back to the
  //      pallet-total-cartons input when case fields are blank
  //
  // Historically every consumer duplicated this cascade inline, and
  // each one had its own way of forgetting the Case Only branch — the
  // Fill button, the Hypothetical Scenarios bail, the loose-CBM
  // accounting, etc. all had the same class of bug. These helpers
  // centralize the logic so future readers see one place to look.
  //
  // RULE: any new code that branches on shipping mode MUST call these
  // helpers instead of re-deriving the booleans / counts inline.
  function _msShipMode() {
    if (_caseOnlyActive()) return 'case';
    if (document.getElementById('pallet-manual')?.checked) return 'manual';
    return 'carton';
  }
  function _msProductsPerShipItem() {
    const mode = _msShipMode();
    if (mode === 'case') {
      const pc = _msIntFromInput(document.getElementById('case-only-products-per'));
      return pc > 0 ? pc : 1;
    }
    if (mode === 'manual') return 1;
    const inner = parseInt(document.getElementById('carton-inner-count')?.value) || 0;
    const outer = parseInt(document.getElementById('carton-outer-count')?.value) || 0;
    const ppo = (inner > 0 && outer > 0) ? inner * outer : 0;
    return ppo > 0 ? ppo : 0;  // 0 here means "carton mode but not configured yet"
  }
  function _msEffectiveTotalUnits() {
    const palletInput = _msIntFromInput(document.getElementById('pallet-total-cartons'));
    if (_msShipMode() !== 'case') return palletInput;
    const pc = _msIntFromInput(document.getElementById('case-only-products-per'));
    const co = _msIntFromInput(document.getElementById('case-only-cases-order'));
    const caseTotal = (pc > 0 && co > 0) ? pc * co : 0;
    // Case math wins when the pallet-total input is empty (load-time
    // race) OR when the operator has bumped the input ABOVE the case
    // math via Apply Full Container Pitch — Math.max picks whichever
    // is larger, so both behaviors are preserved.
    return Math.max(caseTotal, palletInput);
  }
  // Pallet vs Loose-Load — when the operator picks Loose Load, the
  // pallet tare weight and the deck height penalty drop out of every
  // total, and the divider option is hidden by default. renderPalletViz
  // + renderContainerViz both check _palletLoadMode() to branch.
  function _palletLoadMode() {
    const looseEl = document.getElementById('pallet-load-loose');
    return (looseEl && looseEl.checked) ? 'loose' : 'pallet';
  }
  function onPalletLoadModeChange() {
    if (typeof renderPalletViz === 'function') renderPalletViz();
    if (typeof syncShippingDims === 'function') syncShippingDims();
    if (typeof calcFreight === 'function') calcFreight();
    if (typeof autoSaveWorkbook === 'function' && !_filling) autoSaveWorkbook();
  }

  // ── Apply-suggestion helpers ────────────────────────────────────────
  // The optimization tip + container side-panel surface concrete
  // suggestions ("reduce max height to 47", "set total units to
  // 9,360", "top off with 1,407 loose units"). These helpers wire
  // those suggestions to one-click "Update" buttons that mutate the
  // relevant input + trigger downstream renders. Each one accepts a
  // numeric value (or reads it back from a data attribute) and
  // applies the change as if the operator typed it.
  function applyMaxHeightSuggestion(inches) {
    const el = document.getElementById('pallet-max-height');
    if (!el) return;
    const v = parseFloat(inches);
    if (isNaN(v) || v <= 0) return;
    el.value = String(v);
    if (typeof savePalletMaxHeightDefault === 'function') savePalletMaxHeightDefault();
    if (typeof renderPalletViz === 'function') renderPalletViz();
    if (typeof autoSaveWorkbook === 'function' && !_filling) autoSaveWorkbook();
  }
  function applyTotalUnitsSuggestion(units, looseUnitsCount) {
    const el = document.getElementById('pallet-total-cartons');
    if (!el) return;
    const v = parseInt(units);
    if (isNaN(v) || v < 0) return;
    el.value = String(v);
    // Update auto-sync marker so the new value isn't immediately
    // overwritten by the next RFQ recalc — this is an explicit
    // override applied via the suggestion button.
    el.dataset.lastRfqSync = ''; // let the override stand
    // When the operator clicks "↻ Top Off", we receive a positive
    // looseUnitsCount — the products that should be shipped LOOSE
    // (cardboard, no pallet) inside the leftover container CBM. The
    // container viz reads this flag to render those products in blue
    // so they're visually distinct from the orange palletized goods.
    // Cleared when the operator types a new value into the input.
    if (looseUnitsCount && looseUnitsCount > 0) {
      el.dataset.looseTopOff = String(looseUnitsCount);
    } else {
      el.dataset.looseTopOff = '';
    }
    if (typeof renderPalletViz === 'function') renderPalletViz();
    if (typeof syncShippingDims === 'function') syncShippingDims();
    if (typeof calcFreight === 'function') calcFreight();
    if (typeof _refreshPalletTotalHint === 'function') _refreshPalletTotalHint();
    if (typeof autoSaveWorkbook === 'function' && !_filling) autoSaveWorkbook();
  }

  // ── Full Container Pitch — apply / revert ─────────────────────────────
  // Wraps applyTotalUnitsSuggestion with a snapshot of the previous
  // state so the operator can press the button once to APPLY the
  // suggestion, then press it again to REVERT back to whatever they
  // had before. Without the snapshot, repeated clicks compounded the
  // qty into the tens of thousands (each click re-suggested a bigger
  // "fill the container" target from the already-applied state, and
  // when looseUnitsCount happened to land on 0 the looseTopOff flag
  // would clear and rebloat the palletized count further).
  window._fullContainerPitchSnap = null;
  // Full-container freight default — what a typical 40' HC ocean
  // freight runs in USD. Used as the override value when the operator
  // applies the Full Container Pitch so the shipping tab + Landed Cost
  // block + Hypothetical scenarios all reflect a real-world quote.
  const FULL_CONTAINER_FREIGHT_USD = 16500;
  function applyFullContainerPitch(fullQty, looseProducts, appliedFlag) {
    const el = document.getElementById('pallet-total-cartons');
    if (!el) return;
    const overrideEl     = document.getElementById('freight-cost-override');
    const overrideToggle = document.getElementById('freight-cost-override-toggle');
    // Snapshot the CURRENT state so revert returns to exactly here.
    // Skip re-snapshotting if a snapshot already exists (consecutive
    // applies without a revert in between keep the original baseline).
    if (!window._fullContainerPitchSnap) {
      window._fullContainerPitchSnap = {
        totalUnits:   el.value || '',
        looseTopOff:  el.dataset.looseTopOff || '',
        lastRfqSync:  el.dataset.lastRfqSync || '',
        // Capture the freight-override state too so revert can put it
        // back exactly the way it was — including the checkbox state
        // (was it on? off?) and the raw value text the operator had
        // typed (commas and all).
        overrideOn:   !!(overrideToggle && overrideToggle.checked),
        overrideVal:  overrideEl ? (overrideEl.value || '') : '',
        appliedQty:   String(parseInt(fullQty) || 0),
        appliedLoose: String(parseInt(looseProducts) || 0),
        pitchKind:    'full'
      };
    } else {
      window._fullContainerPitchSnap.appliedQty   = String(parseInt(fullQty) || 0);
      window._fullContainerPitchSnap.appliedLoose = String(parseInt(looseProducts) || 0);
      window._fullContainerPitchSnap.pitchKind    = 'full';
    }
    applyTotalUnitsSuggestion(fullQty, looseProducts);
    // Auto-flip the shipping-tab override to the full-container rate
    // so Estimated Shipping Cost + Total Landed Cost + the Hypothetical
    // freight rows all reflect the real-world ocean-freight quote
    // ($FULL_CONTAINER_FREIGHT_USD) instead of the per-kg computation.
    if (overrideToggle && overrideEl) {
      overrideToggle.checked = true;
      overrideEl.value = String(FULL_CONTAINER_FREIGHT_USD);
      if (typeof onShippingCostOverrideToggle === 'function') onShippingCostOverrideToggle();
    }
    // Refresh the Pricing tab's Delivered Cost Summary so Product
    // Cost + Shipping Per + Total Landed Cost all roll up to the
    // bumped qty in real time. Also rebuild the Shipping tab's
    // tier dropdown so the synthetic "★ Full Container Pitch" option
    // appears + auto-selects, mirroring the applied state.
    if (typeof populateTierDropdown === 'function') populateTierDropdown();
    if (typeof renderPricingTab === 'function') renderPricingTab();
  }
  // Half-container Apply — sets Total Units to halfQty but DOESN'T
  // touch the freight override (half-container ships LCL, not at the
  // full $16,500 ocean rate). Snapshot is shared with the full pitch
  // so Revert works for either one. No loose top-off either —
  // half-container by design isn't maximizing the leftover CBM.
  function applyHalfContainerPitch(halfQty) {
    const el = document.getElementById('pallet-total-cartons');
    if (!el) return;
    const overrideEl     = document.getElementById('freight-cost-override');
    const overrideToggle = document.getElementById('freight-cost-override-toggle');
    if (!window._fullContainerPitchSnap) {
      window._fullContainerPitchSnap = {
        totalUnits:   el.value || '',
        looseTopOff:  el.dataset.looseTopOff || '',
        lastRfqSync:  el.dataset.lastRfqSync || '',
        overrideOn:   !!(overrideToggle && overrideToggle.checked),
        overrideVal:  overrideEl ? (overrideEl.value || '') : '',
        appliedQty:   String(parseInt(halfQty) || 0),
        appliedLoose: '0',
        pitchKind:    'half'
      };
    } else {
      window._fullContainerPitchSnap.appliedQty   = String(parseInt(halfQty) || 0);
      window._fullContainerPitchSnap.appliedLoose = '0';
      window._fullContainerPitchSnap.pitchKind    = 'half';
    }
    applyTotalUnitsSuggestion(halfQty, 0);
    // If the Full Container Pitch was previously applied, it set the
    // freight override to the $16,500 full-container rate. Switching
    // to Half (LCL) means we're no longer booking a full container, so
    // unset the override and fall back to the calc-method rate. snap
    // stays so Revert still returns to the pre-Apply state.
    if (overrideToggle && overrideEl) {
      // Only restore the pre-Apply override state if the snap remembers
      // one. (snap.overrideOn === false means the operator had no
      // override before Apply, so we keep it off here.)
      overrideToggle.checked = !!window._fullContainerPitchSnap.overrideOn;
      overrideEl.value = window._fullContainerPitchSnap.overrideVal || '';
      if (typeof onShippingCostOverrideToggle === 'function') onShippingCostOverrideToggle();
    }
    // Rebuild the Shipping tab's tier dropdown so the synthetic
    // "★ Half Container Pitch" option shows up and auto-selects.
    if (typeof populateTierDropdown === 'function') populateTierDropdown();
    if (typeof renderPricingTab === 'function') renderPricingTab();
  }
  function revertFullContainerPitch() {
    const el = document.getElementById('pallet-total-cartons');
    if (!el || !window._fullContainerPitchSnap) return;
    const snap = window._fullContainerPitchSnap;
    el.value = snap.totalUnits || '';
    el.dataset.looseTopOff = snap.looseTopOff || '';
    el.dataset.lastRfqSync = snap.lastRfqSync || '';
    // Restore the shipping-tab freight override to whatever the
    // operator had configured before they applied the Full Container
    // Pitch (might have been off entirely, or set to a different
    // override value).
    const overrideEl     = document.getElementById('freight-cost-override');
    const overrideToggle = document.getElementById('freight-cost-override-toggle');
    if (overrideToggle && overrideEl) {
      overrideToggle.checked = !!snap.overrideOn;
      overrideEl.value = snap.overrideVal || '';
      if (typeof onShippingCostOverrideToggle === 'function') onShippingCostOverrideToggle();
    }
    window._fullContainerPitchSnap = null;
    // Drop the stale pitch sentinel + rebuild the dropdown without
    // the synthetic option. Default back to tier 1 so the Shipping
    // tab keeps a real selection after Revert.
    if (typeof _selectedTierId === 'string' && _selectedTierId.indexOf('pitch-') === 0) {
      _selectedTierId = 1;
    }
    if (typeof renderPalletViz === 'function') renderPalletViz();
    if (typeof syncShippingDims === 'function') syncShippingDims();
    if (typeof calcFreight === 'function') calcFreight();
    if (typeof populateTierDropdown === 'function') populateTierDropdown();
    if (typeof renderPricingTab === 'function') renderPricingTab();
    if (typeof _refreshPalletTotalHint === 'function') _refreshPalletTotalHint();
    if (typeof autoSaveWorkbook === 'function' && !_filling) autoSaveWorkbook();
  }
  // Any non-pitch path that changes the Total Units value MUST clear
  // the snapshot too — otherwise a stale snapshot points at a baseline
  // the operator already moved past. Manual typing into the input,
  // the Sync from RFQ button, the optimisation-tip Update buttons,
  // etc. all funnel through here.
  function _clearFullContainerPitchSnap() {
    window._fullContainerPitchSnap = null;
  }

  // ── Pallet Max Height — per-workbook value + new-workbook seed ────
  // The "Max height" input is saved PER WORKBOOK (detail.palletMaxHeight).
  // localStorage holds a "default for new workbooks" seed only — it
  // does NOT override values on existing workbooks. So setting 47" on
  // the workbook you're editing affects this workbook + every NEW
  // workbook created from now on, but every workbook that already
  // existed keeps whatever it had (which falls back to the HTML
  // default of 60" for legacy workbooks that never saved this field).
  const _PALLET_MAX_HEIGHT_KEY = 'ms_pallet_max_height_default';
  function savePalletMaxHeightDefault() {
    const el = document.getElementById('pallet-max-height');
    if (!el) return;
    const v = parseFloat(el.value);
    if (isNaN(v) || v <= 0) return;
    try { localStorage.setItem(_PALLET_MAX_HEIGHT_KEY, String(v)); } catch (_) { /* private mode etc. */ }
  }
  // Read the new-workbook seed from localStorage. Used at workbook
  // CREATION time only — never on the open path.
  function getPalletMaxHeightSeed() {
    try {
      const saved = localStorage.getItem(_PALLET_MAX_HEIGHT_KEY);
      const v = parseFloat(saved);
      if (!isNaN(v) && v > 0) return v;
    } catch (_) {}
    return null;
  }
  // Apply the per-workbook value to the input. If the workbook has no
  // saved value (legacy workbook), fall back to the HTML default of
  // 60" — NOT to the localStorage seed. This is what keeps the user's
  // recent default change from rewriting every old workbook.
  function applyPalletMaxHeight(savedValue) {
    const el = document.getElementById('pallet-max-height');
    if (!el) return;
    const v = parseFloat(savedValue);
    if (!isNaN(v) && v > 0) {
      el.value = String(v);
    } else {
      el.value = '60'; // HTML default
    }
  }

  // Auto-populate "Total Units to Ship" from the RFQ Grand Total qty.
  // The input always represents PRODUCT count; the pallet view
  // derives carton count and pallets needed from that downstream.
  // Merge rule respects user overrides:
  //   - If the input is empty → fill with grandQty
  //   - If the input still equals the value we last auto-synced (i.e.
  //     the user hasn't typed anything different) → re-sync
  //   - Also: if the input matches grandQty exactly, register it as
  //     auto-synced so future RFQ edits propagate (handles the case
  //     where a saved workbook lands with a value that already matches
  //     the current RFQ — without this, the dataset.lastRfqSync was
  //     empty and we'd treat the value as a user override forever).
  //   - Otherwise (user has overridden to a different value) → leave
  //     it alone, but show the "↻ Sync from RFQ" button so the user
  //     can pull the RFQ value in with one click.
  // After every sync attempt, refresh the hint text so the operator
  // can see the live RFQ qty and the override status.
  function syncManualPalletTotalUnits() {
    const input = document.getElementById('pallet-total-cartons');
    if (!input) return;
    const grandQty = (typeof _lastRfqPriceSummary !== 'undefined' && _lastRfqPriceSummary && _lastRfqPriceSummary.grandQty) || 0;
    const last    = input.dataset.lastRfqSync || '';
    const current = String(input.value || '').trim();
    const target  = grandQty > 0 ? String(grandQty) : '';

    if (target) {
      // Sync if empty, matches the last auto-synced value, or already
      // happens to match grandQty (the load-time recovery case).
      if (current === '' || current === last || current === target) {
        if (current !== target) {
          input.value = target;
          // Reverting to the clean RFQ qty has to wipe any stashed
          // loose top-off — otherwise the previously-applied Full
          // Container Pitch flag lingers and the container viz keeps
          // drawing leftover blue boxes while the Hypothetical panel
          // computes against a phantom palletized subset. Also drop
          // the Full Container Pitch snapshot so the button rebuilds
          // its "Apply" affordance from a clean baseline.
          input.dataset.looseTopOff = '';
          if (typeof _clearFullContainerPitchSnap === 'function') _clearFullContainerPitchSnap();
          if (typeof renderPalletViz === 'function') renderPalletViz();
          if (typeof syncShippingDims === 'function') syncShippingDims();
          if (typeof calcFreight === 'function') calcFreight();
          if (typeof autoSaveWorkbook === 'function' && !_filling) autoSaveWorkbook();
        }
        input.dataset.lastRfqSync = target;
      }
    }
    // Update hint + show/hide the re-sync button so the operator
    // always sees whether the field is locked to RFQ or overridden.
    _refreshPalletTotalHint();
  }

  // Force a re-pull from the RFQ Grand Total — drops any user
  // override and locks the input back to the live RFQ qty. Wired to
  // the "↻ Sync from RFQ" button next to the input.
  function resyncPalletTotalUnitsFromRfq() {
    const input = document.getElementById('pallet-total-cartons');
    if (!input) return;
    const grandQty = (typeof _lastRfqPriceSummary !== 'undefined' && _lastRfqPriceSummary && _lastRfqPriceSummary.grandQty) || 0;
    if (!grandQty) return;
    input.value = String(grandQty);
    input.dataset.lastRfqSync = String(grandQty);
    // Manual revert to the RFQ qty also clears the loose top-off flag
    // so Scenario B in the Hypothetical Scenarios panel rebuilds from
    // the clean RFQ qty (most-efficient pitch from scratch), and the
    // container viz drops the leftover blue boxes from the previous
    // Apply Full Container Pitch press. Also drop the pitch snapshot
    // so the button reverts to its "Apply" affordance.
    input.dataset.looseTopOff = '';
    if (typeof _clearFullContainerPitchSnap === 'function') _clearFullContainerPitchSnap();
    if (typeof renderPalletViz === 'function') renderPalletViz();
    if (typeof syncShippingDims === 'function') syncShippingDims();
    if (typeof calcFreight === 'function') calcFreight();
    if (typeof autoSaveWorkbook === 'function' && !_filling) autoSaveWorkbook();
    _refreshPalletTotalHint();
  }

  // Refresh the small hint text under the Total Units input + show the
  // "Sync from RFQ" button only when the input is genuinely overridden.
  function _refreshPalletTotalHint() {
    const input = document.getElementById('pallet-total-cartons');
    const hint  = document.getElementById('pallet-total-hint');
    const btn   = document.getElementById('pallet-total-resync-btn');
    if (!input || !hint) return;
    const grandQty = (typeof _lastRfqPriceSummary !== 'undefined' && _lastRfqPriceSummary && _lastRfqPriceSummary.grandQty) || 0;
    const current  = String(input.value || '').trim();
    const target   = grandQty > 0 ? String(grandQty) : '';
    if (!grandQty) {
      hint.innerHTML = `Will auto-fill from <strong>RFQ Grand Total qty</strong> once the RFQ is filled in.`;
      if (btn) btn.style.display = 'none';
      return;
    }
    if (current === target) {
      hint.innerHTML = `Synced with <strong>RFQ Grand Total qty</strong> (${grandQty.toLocaleString()} units).`;
      if (btn) btn.style.display = 'none';
    } else {
      hint.innerHTML = `Overridden — <strong>RFQ Grand Total</strong> is <strong>${grandQty.toLocaleString()}</strong> units.`;
      if (btn) btn.style.display = '';
    }
  }

  // ── 40' High Cube container viz ─────────────────────────────────────
  // Renders the container as a wireframe iso box and the loaded pallets
  // (with their product stacks on top) as solid boxes inside. Computes:
  //   • Best-fit pallet floor arrangement (try both orientations)
  //   • Vertical stacking — up to 2 layers of pallets if heights allow
  //   • Total weight, total pallets, space remaining (per-container)
  // 40' HC INTERIOR dimensions (cm): 1203 L × 235 W × 269 H
  // Cargo planning capacity (per user / standard practice):
  //   ~67 CBM usable cargo space, 26,000 kg max payload.
  const HC_L = 1203, HC_W = 235, HC_H = 269;
  const HC_MAX_KG = 26000;     // max payload (kg)
  const HC_USABLE_CBM = 67;    // usable cargo volume (m³)
  function renderContainerViz(palletsNeeded, palletStackHcm, drawCellL, drawCellW, layoutCols, layoutRows, padCm, palletWeightKgArg, unitsPerPalletArg, unitWordArg, unitCbmArg, unitWeightKgArg) {
    const canvas = document.getElementById('container-canvas');
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    const CW = canvas.width, CH = canvas.height;
    ctx.clearRect(0, 0, CW, CH);
    const inlineEl = document.getElementById('container-stats-inline');
    const sideEl   = document.getElementById('container-side-stats');
    const fillEl   = document.getElementById('container-fill-room');
    // Hard-clear the room-to-fill slot upfront. Anything that wants to
    // populate it later in this function MUST reach the if (fillEl)
    // assignment below — otherwise we'd rather show an empty slot than
    // leave behind stale numbers from a prior render with different
    // shipment qty / mode. Previously a path that returned early
    // (canvas missing, exception inside the side-stats block) would
    // leave the panel reading e.g. "+528 more cases" long after the
    // operator cleared the inputs that produced it.
    if (fillEl) fillEl.innerHTML = '';

    // Fit pallets on the container floor — try both orientations.
    const optA = { cols: Math.floor(HC_L / PALLET_L), rows: Math.floor(HC_W / PALLET_W), pL: PALLET_L, pW: PALLET_W };
    const optB = { cols: Math.floor(HC_L / PALLET_W), rows: Math.floor(HC_W / PALLET_L), pL: PALLET_W, pW: PALLET_L };
    const palletLayout = (optA.cols * optA.rows >= optB.cols * optB.rows) ? optA : optB;
    const palletsPerLayer = palletLayout.cols * palletLayout.rows;

    // Stack height of each pallet (pallet deck + product stack).
    // Falls back to ~150 cm for the empty preview.
    const palletStack = (palletStackHcm && palletStackHcm > 0)
      ? palletStackHcm
      : 152;
    // Vertical layers of pallets that fit in the container (cap at 2 —
    // double-stacking is industry-standard upper limit for stability;
    // triple-stacking is rare and we'd overstate capacity).
    const verticalLayers = Math.max(1, Math.min(2, Math.floor(HC_H / palletStack)));
    const palletsPerContainer = palletsPerLayer * verticalLayers;
    const palletsToShow = palletsNeeded > 0
      ? Math.min(palletsNeeded, palletsPerContainer)
      : palletsPerContainer; // empty state — show a full container

    // Total visible stack height for canvas scaling.
    const totalPalletsHeight = Math.min(verticalLayers * palletStack, HC_H);

    // Iso projection — shared with the pallet viz. Generous padding so
    // the W and L labels (which extend down/right) and H label (left)
    // fit comfortably without clipping. Sized for 16px dim labels +
    // a top-right "40' HC" badge.
    const PAD_LEFT = 130, PAD_RIGHT = 140, PAD_TOP = 40, PAD_BOTTOM = 100;
    const footprintSpan = HC_L + HC_W;
    const stackSpan = totalPalletsHeight + footprintSpan * ISO_SIN30;
    const s = Math.min(
      (CW - PAD_LEFT - PAD_RIGHT) / (footprintSpan * ISO_COS30),
      (CH - PAD_TOP - PAD_BOTTOM) / stackSpan
    );
    // Center along x — average of the leftmost (0,0,HC_W) and rightmost
    // (HC_L,0,0) projected x positions.
    const ox = (CW + (HC_W - HC_L) * ISO_COS30 * s) / 2;
    const oy = totalPalletsHeight * s + PAD_TOP;

    // ── Draw pallets / cargo blocks (solid) inside the container ──────
    // Layer 0 = bottom, layer 1 = top (when stacked). Each layer is
    // drawn back-to-front in painter's order. Top layer is drawn after
    // the bottom one so it overlaps correctly. In LOOSE-LOAD mode the
    // wood pallet deck is skipped — cargo blocks sit straight on the
    // container floor, freeing the 15 cm of deck height for product.
    const _ctxLoadMode = (typeof _palletLoadMode === 'function') ? _palletLoadMode() : 'pallet';
    const _ctxLoose    = _ctxLoadMode === 'loose';
    const palletDeckHere = _ctxLoose ? 0 : PALLET_DECK;
    let drawn = 0;
    const stackOnly = Math.max(0, palletStack - palletDeckHere);
    for (let layerIdx = 0; layerIdx < verticalLayers && drawn < palletsToShow; layerIdx++) {
      const layerY = layerIdx * palletStack;
      for (let diag = 0; diag <= palletLayout.cols + palletLayout.rows - 2 && drawn < palletsToShow; diag++) {
        for (let col = Math.max(0, diag - palletLayout.rows + 1); col <= Math.min(diag, palletLayout.cols - 1); col++) {
          if (drawn >= palletsToShow) break;
          const row = diag - col;
          const x = col * palletLayout.pL;
          const z = row * palletLayout.pW;
          // Pallet deck (gray) — pallet mode only
          if (palletDeckHere > 0) {
            drawIsoBox(ctx, x, layerY, z, palletLayout.pL, palletDeckHere, palletLayout.pW, s, ox, oy, '#a8a8a8');
          }
          // Product stack (orange) on top of the deck (or directly on
          // the floor in loose-load mode).
          if (stackOnly > 0) {
            drawIsoBox(ctx, x, layerY + palletDeckHere, z, palletLayout.pL, stackOnly, palletLayout.pW, s, ox, oy, '#E8751A');
          }
          drawn++;
        }
      }
    }

    // ── Draw loose top-off load (BLUE) — FLOOR-LOADED at the door end ──
    // The "↻ Top Off" button stashes a "products beyond the palletized
    // count" flag on the Total Units input. Render those products as
    // BLUE cardboard boxes on the CONTAINER FLOOR, anchored at the
    // door end (high x) of the container, in the strip of floor that
    // the pallets don't occupy. Real ocean shipments load loose-load
    // boxes from the floor outward toward the doors, NOT on top of
    // the pallets — and stacking them in the headroom misrepresents
    // both the centre of gravity and how the load is actually pulled
    // off at the destination terminal.
    const looseTopOffStr = document.getElementById('pallet-total-cartons')?.dataset.looseTopOff || '';
    const looseTopOffUnits = parseInt(looseTopOffStr) || 0;
    if (looseTopOffUnits > 0 && palletsToShow > 0) {
      const _manualOn = !!document.getElementById('pallet-manual')?.checked;
      const _caseOnly = !!document.getElementById('case-only-override')?.checked;
      const get = id => parseFloat(document.getElementById(id)?.value) || 0;
      // Pick the right box dims for the BLUE loose-load draw based on
      // which override is active. case-only ships cases, so the loose
      // boxes use case dims; manual mode ships products direct;
      // default carton mode uses outer-carton dims.
      const boxL = _caseOnly ? get('case-only-l-cm') : (_manualOn ? get('dim-cm-l') : get('carton-outer-l-cm'));
      const boxW = _caseOnly ? get('case-only-w-cm') : (_manualOn ? get('dim-cm-w') : get('carton-outer-w-cm'));
      const boxH = _caseOnly ? get('case-only-h-cm') : (_manualOn ? get('dim-cm-h') : get('carton-outer-h-cm'));
      const _innerQty = parseInt(document.getElementById('carton-inner-count')?.value) || 0;
      const _outerQty = parseInt(document.getElementById('carton-outer-count')?.value) || 0;
      const _ppo = (_innerQty > 0 && _outerQty > 0) ? _innerQty * _outerQty : 0;
      const _casePer = _msIntFromInput(document.getElementById('case-only-products-per'));
      // products-per-box = 1 for manual mode (each loose unit is a
      // product), the case's products-per-case count in case-only
      // mode, and inner × outer for default carton mode.
      const productsPerBox = _caseOnly ? (_casePer || 1) : (_manualOn ? 1 : (_ppo || 1));
      const looseBoxesToDraw = Math.max(0, Math.ceil(looseTopOffUnits / productsPerBox));
      if (boxL > 0 && boxW > 0 && boxH > 0 && looseBoxesToDraw > 0) {
        // Door-end strip = the x-range between the last pallet column
        // and HC_L. Pallets fill from x=0 to palCols × pL; the leftover
        // sits at the door (high x) side of the container.
        const palletsXUsed   = palletLayout.cols * palletLayout.pL;
        const palletsZUsed   = palletLayout.rows * palletLayout.pW;
        const looseXSpace    = Math.max(0, HC_L - palletsXUsed);
        const looseColsX     = Math.max(0, Math.floor(looseXSpace / boxL));
        // Match the loose stack's z (width) extent to the pallets'
        // z extent so the orange + blue blocks read as a continuous
        // load. Falls back to full HC_W if pallets cover no z.
        const looseZSpace    = palletsZUsed > 0 ? palletsZUsed : HC_W;
        const looseColsZ     = Math.max(0, Math.floor(looseZSpace / boxW));
        // Stack the loose load up to the SAME y as the top of the
        // palletised cargo so the two blocks line up visually. Cap to
        // HC_H so we don't punch through the ceiling.
        const palletTopY     = Math.min(HC_H, verticalLayers * palletStack);
        const looseMaxLayers = Math.max(0, Math.floor(palletTopY / boxH));
        const loosePerLayer  = looseColsX * looseColsZ;
        const looseLayers    = loosePerLayer > 0
          ? Math.min(looseMaxLayers, Math.ceil(looseBoxesToDraw / loosePerLayer))
          : 0;
        if (looseLayers > 0 && loosePerLayer > 0) {
          // Anchor the loose stack to the right edge of the last pallet
          // column so orange and blue TOUCH (no awkward gap), and
          // anchor z to the pallet's z origin so the widths line up.
          const looseStackXSpan = looseColsX * boxL;
          // Door-end if room allows, otherwise pin against pallets.
          const looseOffX = Math.min(HC_L - looseStackXSpan, palletsXUsed);
          const looseOffZ = palletsZUsed > 0 ? 0 : Math.max(0, (HC_W - looseColsZ * boxW) / 2);
          const looseColor = '#3b82f6'; // blue-500
          let looseDrawn = 0;
          for (let ly = 0; ly < looseLayers && looseDrawn < looseBoxesToDraw; ly++) {
            for (let diag = 0; diag <= looseColsX + looseColsZ - 2 && looseDrawn < looseBoxesToDraw; diag++) {
              for (let cx = Math.max(0, diag - looseColsZ + 1); cx <= Math.min(diag, looseColsX - 1); cx++) {
                if (looseDrawn >= looseBoxesToDraw) break;
                const cz = diag - cx;
                drawIsoBox(ctx,
                  looseOffX + cx * boxL,
                  ly * boxH,                 // floor-up, not pallet-top
                  looseOffZ + cz * boxW,
                  boxL, boxH, boxW, s, ox, oy, looseColor);
                looseDrawn++;
              }
            }
          }
        }
      }
    }

    // ── Draw container as wireframe overlay ───────────────────────────
    const cv = {
      bbl: isoProj(0,    0,    0,    s, ox, oy),
      bbr: isoProj(HC_L, 0,    0,    s, ox, oy),
      bfl: isoProj(0,    0,    HC_W, s, ox, oy),
      bfr: isoProj(HC_L, 0,    HC_W, s, ox, oy),
      tbl: isoProj(0,    HC_H, 0,    s, ox, oy),
      tbr: isoProj(HC_L, HC_H, 0,    s, ox, oy),
      tfl: isoProj(0,    HC_H, HC_W, s, ox, oy),
      tfr: isoProj(HC_L, HC_H, HC_W, s, ox, oy)
    };
    const edges = [
      ['bbl','bbr'],['bfl','bfr'],['bbl','bfl'],['bbr','bfr'],
      ['tbl','tbr'],['tfl','tfr'],['tbl','tfl'],['tbr','tfr'],
      ['bbl','tbl'],['bbr','tbr'],['bfl','tfl'],['bfr','tfr']
    ];
    ctx.strokeStyle = 'rgba(70, 130, 180, 0.55)';
    ctx.lineWidth = 1.4;
    edges.forEach(([a, b]) => {
      ctx.beginPath();
      ctx.moveTo(cv[a].x, cv[a].y);
      ctx.lineTo(cv[b].x, cv[b].y);
      ctx.stroke();
    });
    // Roof tint — light steel-blue so the container reads as enclosed
    // but the cargo inside stays visible through the side walls.
    ctx.fillStyle = 'rgba(70, 130, 180, 0.08)';
    ctx.beginPath();
    ctx.moveTo(cv.tbl.x, cv.tbl.y);
    ctx.lineTo(cv.tbr.x, cv.tbr.y);
    ctx.lineTo(cv.tfr.x, cv.tfr.y);
    ctx.lineTo(cv.tfl.x, cv.tfl.y);
    ctx.closePath();
    ctx.fill();

    // ── Dim labels (L, W, H) outside the wireframe ────────────────────
    const allPts = Object.values(cv);
    const cxBox = allPts.reduce((sum,p) => sum + p.x, 0) / allPts.length;
    const cyBox = allPts.reduce((sum,p) => sum + p.y, 0) / allPts.length;
    const sxMin = Math.min(...allPts.map(p => p.x));
    const outwardPerp = (a, b) => {
      const dx = b.x - a.x, dy = b.y - a.y;
      const len = Math.sqrt(dx*dx + dy*dy) || 1;
      const px = -dy/len, py = dx/len;
      const midX = (a.x + b.x)/2, midY = (a.y + b.y)/2;
      const dot = px*(midX - cxBox) + py*(midY - cyBox);
      return dot >= 0 ? { x: px, y: py } : { x: -px, y: -py };
    };
    const TICK = 4;
    ctx.fillStyle = '#6b7280';
    ctx.strokeStyle = '#6b7280';
    ctx.lineWidth = 1.4;
    ctx.font = `700 16px -apple-system, BlinkMacSystemFont, sans-serif`;
    const drawDim = (a, b, labelPos, txt, anchor='center') => {
      ctx.beginPath(); ctx.moveTo(a.x, a.y); ctx.lineTo(b.x, b.y); ctx.stroke();
      const dx = b.x - a.x, dy = b.y - a.y;
      const len = Math.sqrt(dx*dx + dy*dy) || 1;
      const tpx = -dy/len * TICK, tpy = dx/len * TICK;
      ctx.beginPath();
      ctx.moveTo(a.x - tpx, a.y - tpy); ctx.lineTo(a.x + tpx, a.y + tpy);
      ctx.moveTo(b.x - tpx, b.y - tpy); ctx.lineTo(b.x + tpx, b.y + tpy);
      ctx.stroke();
      ctx.textAlign = anchor;
      ctx.textBaseline = 'middle';
      ctx.fillText(txt, labelPos.x, labelPos.y);
    };
    const fmtFt = (cm) => {
      const inches = cm / 2.54;
      const feet   = Math.floor(inches / 12);
      const inRem  = inches - feet * 12;
      return inRem < 0.5 ? `${feet}'` : `${feet}'${inRem.toFixed(0)}"`;
    };
    // Bracket bars sit close to the silhouette; labels are pushed
    // well past the bars so the 16px text reads cleanly without
    // crashing into the bracket bar.
    // L bracket — front-left-bottom edge
    {
      const lOff = 18, lLabelGap = 48;
      const a0 = cv.bfl, b0 = cv.bfr;
      const p = outwardPerp(a0, b0);
      const a = { x: a0.x + p.x*lOff, y: a0.y + p.y*lOff };
      const b = { x: b0.x + p.x*lOff, y: b0.y + p.y*lOff };
      const mid = { x: (a.x + b.x)/2 + p.x*lLabelGap, y: (a.y + b.y)/2 + p.y*lLabelGap };
      drawDim(a, b, mid, `L ${fmtFt(HC_L)} (${(HC_L/100).toFixed(2)} m)`);
    }
    // W bracket — front-right-bottom edge
    {
      const wOff = 18, wLabelGap = 48;
      const a0 = cv.bfr, b0 = cv.bbr;
      const p = outwardPerp(a0, b0);
      const a = { x: a0.x + p.x*wOff, y: a0.y + p.y*wOff };
      const b = { x: b0.x + p.x*wOff, y: b0.y + p.y*wOff };
      const mid = { x: (a.x + b.x)/2 + p.x*wLabelGap, y: (a.y + b.y)/2 + p.y*wLabelGap };
      drawDim(a, b, mid, `W ${fmtFt(HC_W)} (${(HC_W/100).toFixed(2)} m)`);
    }
    // H bracket — vertical, OUTSIDE leftmost silhouette
    {
      const hX = sxMin - 30;
      const a = { x: hX, y: cv.tfl.y };
      const b = { x: hX, y: cv.bfl.y };
      drawDim(a, b, { x: hX - 16, y: (a.y + b.y)/2 }, `H ${fmtFt(HC_H)} (${(HC_H/100).toFixed(2)} m)`, 'right');
    }
    // Container badge — anchored top-right corner of the canvas so it
    // doesn't overlap the L bracket beneath the wireframe.
    ctx.fillStyle = '#6b7280';
    ctx.font = `700 12px -apple-system, sans-serif`;
    ctx.textAlign = 'right';
    ctx.textBaseline = 'top';
    ctx.fillText("40' High Cube Container", CW - 14, 12);

    // ── Compute container math ─────────────────────────────────────────
    const containersNeeded = palletsNeeded > 0 ? Math.ceil(palletsNeeded / palletsPerContainer) : 0;
    const palletsInLast = palletsNeeded > 0
      ? (palletsNeeded - (containersNeeded - 1) * palletsPerContainer)
      : 0;
    const palletsRoomLeft = Math.max(0, palletsPerContainer - palletsInLast);
    const palletWeightKg = palletWeightKgArg && palletWeightKgArg > 0 ? palletWeightKgArg : 0;
    const lastContainerWeightKg = palletWeightKg * palletsInLast;
    const totalShipmentWeightKg = palletWeightKg * palletsNeeded;
    // Cache total shipment weight on the workbook so the Add Workbook
    // to Order picker (and other dashboards) can show the order weight
    // without re-running the freight calc. Mirrors how
    // renderPricingTab caches pricingLandedTotal. CBM is cached
    // alongside so the picker can show "X / 67 CBM" container fill.
    if (typeof currentClient === 'string' && currentWorkbookId) {
      const _wbWtKey = `${currentClient}|${currentWorkbookId}`;
      if (!workbookDetail[_wbWtKey]) workbookDetail[_wbWtKey] = {};
      workbookDetail[_wbWtKey].pricingShipmentWeightKg = totalShipmentWeightKg > 0 ? totalShipmentWeightKg : 0;
      // Note: totalShipmentCbm is computed below; we patch the cache
      // again after it's available.
    }
    // Units math — how many products fit per pallet, how many more
    // products would fill the empty pallet slots in the last container.
    const unitsPerPallet = (unitsPerPalletArg && unitsPerPalletArg > 0) ? unitsPerPalletArg : 0;
    const unitWord = unitWordArg || 'units';
    const unitsToFillLastContainer = unitsPerPallet * palletsRoomLeft;
    // CBM math — each pallet occupies (PALLET_L × PALLET_W × stack
    // height) cm³. Convert to m³, multiply by pallets in last container,
    // subtract from the 67 CBM usable cargo allowance.
    const palletCbm = (PALLET_L * PALLET_W * palletStack) / 1_000_000; // m³
    const lastContainerCbm = palletCbm * palletsInLast;
    const totalShipmentCbm = palletCbm * palletsNeeded;
    // Cache CBM alongside the weight cache above. The picker uses this
    // to roll up "X / 67 CBM" container fill across selected workbooks.
    if (typeof currentClient === 'string' && currentWorkbookId) {
      const _wbCbmKey = `${currentClient}|${currentWorkbookId}`;
      if (!workbookDetail[_wbCbmKey]) workbookDetail[_wbCbmKey] = {};
      workbookDetail[_wbCbmKey].pricingShipmentCbm = totalShipmentCbm > 0 ? totalShipmentCbm : 0;
    }
    // ── Loose top-off accounting ─────────────────────────────────────
    // When the operator clicks "↻ Top Off", we stash the loose unit
    // count (in PRODUCTS) on the input's dataset. Those loose cardboard
    // boxes consume CBM and weight inside the last container, so we
    // subtract them here BEFORE computing room-left. Without this, the
    // panel would still report "+13 CBM remaining" right after Top Off,
    // contradicting the user's just-applied action.
    const _looseStrCV   = document.getElementById('pallet-total-cartons')?.dataset.looseTopOff || '';
    const _looseUnitsCV = parseInt(_looseStrCV) || 0;
    // Convert loose products → loose-cardboard-cartons via the same
    // products-per-item ratio used when stashing (1 in manual mode,
    // products-per-outer-carton in carton mode, products-per-case in
    // case-only mode). Routed through the canonical helper so this
    // function can't drift from the rest of the pallet/container math
    // when the case-only branch grows new edge cases.
    const _ppiCV = _msProductsPerShipItem() || 1;
    const _looseCartonCountCV = _ppiCV > 0 ? (_looseUnitsCV / _ppiCV) : 0;
    const _unitCbmCV = (typeof unitCbmArg === 'number' && unitCbmArg > 0) ? unitCbmArg : 0;
    const _unitWtCV  = (typeof unitWeightKgArg === 'number' && unitWeightKgArg > 0) ? unitWeightKgArg : 0;
    // Effective CBM consumed by loose cartons. Divide by 0.80 packing
    // efficiency so the loose-fit cap (which uses ×0.80) and the
    // room-left value stay self-consistent — i.e. once the operator
    // tops off the maximum we suggested, room-left collapses to ~0
    // rather than leaving a phantom 20% slack the user can't actually
    // use.
    const _looseCbmConsumed = _unitCbmCV > 0 ? (_looseCartonCountCV * _unitCbmCV) / 0.80 : 0;
    const _looseWtConsumed  = _unitWtCV > 0 ? (_looseCartonCountCV * _unitWtCV)  : 0;
    const cbmRoomLeft = Math.max(0, HC_USABLE_CBM - lastContainerCbm - _looseCbmConsumed);
    const weightRoomLeftKg = palletWeightKg > 0
      ? Math.max(0, HC_MAX_KG - lastContainerWeightKg - _looseWtConsumed)
      : Math.max(0, HC_MAX_KG - _looseWtConsumed);

    // ── Inline summary line above the canvas ───────────────────────────
    if (inlineEl) {
      const stackTag = verticalLayers > 1 ? ` <span style="opacity:0.7;">(${verticalLayers}-high)</span>` : '';
      if (palletsNeeded > 0) {
        inlineEl.innerHTML = `<strong>${palletsPerContainer}</strong> pallets fit per 40' HC${stackTag} &nbsp;·&nbsp; ` +
          `<strong style="color:var(--accent);">${containersNeeded}</strong> container${containersNeeded === 1 ? '' : 's'} needed for ${palletsNeeded.toLocaleString()} pallets`;
      } else {
        inlineEl.innerHTML = `<strong>${palletsPerContainer}</strong> pallets fit per 40' HC${stackTag} <span style="opacity:0.7;">(enter shipment qty to see containers needed)</span>`;
      }
    }

    // ── Side stats panel ───────────────────────────────────────────────
    if (sideEl) {
      const fmtKg = (kg) => {
        if (!kg || kg <= 0) return '0 kg';
        const lb = kg * 2.20462;
        return kg < 10
          ? `${kg.toFixed(2)} kg <span style="color:var(--text-muted); font-weight:500;">/ ${lb.toFixed(2)} lb</span>`
          : `${kg.toLocaleString('en-US', {maximumFractionDigits:1})} kg <span style="color:var(--text-muted); font-weight:500;">/ ${lb.toLocaleString('en-US', {maximumFractionDigits:1})} lb</span>`;
      };
      const stackBadge = verticalLayers > 1
        ? `<div style="font-size:11px; color:var(--accent); margin-top:4px;">↳ ${verticalLayers}-pallet vertical stacking enabled</div>`
        : '';
      const palletsBadge = palletsNeeded > 0
        ? `<div style="font-size:11px; color:var(--text-muted); margin-top:4px;">${containersNeeded} × 40' HC container${containersNeeded === 1 ? '' : 's'}</div>`
        : '';
      const fmtCbm = (m3) => m3 < 1
        ? `${m3.toFixed(2)} m³`
        : `${m3.toLocaleString('en-US', {maximumFractionDigits:1})} m³`;
      // Loose-load top-off: how many extra units fit in the leftover
      // CBM/weight if shipped in cardboard boxes (no pallet) — pure
      // unit dims, no pallet/divider overhead. Limited by either CBM
      // remaining or weight remaining, whichever is tighter.
      const unitCbm = (typeof unitCbmArg === 'number' && unitCbmArg > 0) ? unitCbmArg : 0;
      const unitWtKg = (typeof unitWeightKgArg === 'number' && unitWeightKgArg > 0) ? unitWeightKgArg : 0;
      let looseByCbm = 0, looseByWeight = Infinity, looseFit = 0;
      if (unitCbm > 0) {
        // Real-world cardboard packing isn't 100% efficient — assume
        // 80% volumetric utilization (rest is box wall + air gaps).
        const PACK_EFFICIENCY = 0.80;
        looseByCbm = Math.floor((cbmRoomLeft * PACK_EFFICIENCY) / unitCbm);
        looseByWeight = unitWtKg > 0 ? Math.floor(weightRoomLeftKg / unitWtKg) : Infinity;
        looseFit = Math.max(0, Math.min(looseByCbm, looseByWeight));
      }
      const looseLabel = unitWord === 'units' || unitWord === 'unit'
        ? 'loose units (cardboard, no pallet)'
        : 'loose cartons (no pallet)';

      // Compute the actual product/unit qtys behind each suggestion so
      // the Update buttons can flip the Total Units to Ship straight
      // to a meaningful target. In manual mode every "ship item" is a
      // product (1:1). In carton mode each ship item is an outer
      // carton holding `productsPerOuter` products, so we multiply by
      // that to reach the products figure the input expects.
      // products-per-ship-item — routed through the canonical helper
      // so the case-only branch can't be accidentally omitted (which
      // is what previously made the Fill button collapse to × 1 and
      // suggest the cases-count target instead of the products-count
      // target, so clicking Fill looked silent).
      const productsPerItem = _msProductsPerShipItem() || 1;
      // ── Fill / Top-Off target — absolute, NOT additive ────────────────
      // Earlier versions did `current + roomLeft × productsPerItem`, but
      // ceil() rounding meant clicking again kept inflating the qty
      // (each click bumped palletsNeeded past the container boundary →
      // a brand-new container appeared with another full set of empty
      // slots → another huge "+roomLeft" bump). The fix: compute the
      // exact products needed to fully load the CURRENT container count
      // (palletsPerContainer × containersNeeded × items-per-pallet, in
      // products), so repeated clicks settle on the same value.
      const targetFillPallets    = palletsPerContainer * containersNeeded * unitsPerPallet * productsPerItem;
      // Top-off adds the loose-load capacity to a fully-palletized
      // shipment (still absolute, so repeat clicks are stable too).
      const targetFillWithLoose  = targetFillPallets + looseFit * productsPerItem;
      const upBtn = `display:inline-flex; align-items:center; gap:4px; padding:2px 8px; font-size:10px; font-weight:700; color:#fff; background:var(--accent); border:none; border-radius:4px; cursor:pointer; white-space:nowrap; margin-left:6px; vertical-align:middle;`;

      // ── Last Container — Room to Fill (always expanded) ──────────────
      // <details open> so the operator can always see the Fill / Top-Off
      // controls + remaining-room stats. The summary still acts as a
      // collapse handle if they want to hide it temporarily. After a
      // successful Top Off, the body shows 0 across the board (the
      // loose-CBM-consumed subtraction above zeros out room-left).
      // <summary>'s default disclosure triangle is suppressed via
      // list-style:none; a custom chevron is inlined instead.
      const remainingBlock = palletsNeeded > 0
        ? `<details open style="margin-top:14px; border:1px solid var(--border); border-radius:8px; background:var(--surface2);">
             <summary style="list-style:none; padding:10px 12px; cursor:pointer; display:flex; align-items:center; justify-content:space-between; gap:8px; user-select:none;">
               <span style="font-size:10px; font-weight:700; text-transform:uppercase; letter-spacing:0.06em; color:var(--text-muted);">
                 Last Container — Room to Fill
               </span>
               <span style="font-size:11px; color:var(--text-muted); display:flex; align-items:center; gap:6px;">
                 ${palletsRoomLeft > 0
                   ? `<span style="color:var(--accent); font-weight:700;">+${palletsRoomLeft}</span>`
                   : `<span style="opacity:0.7;">full</span>`}
                 <span style="font-size:13px;">▾</span>
               </span>
             </summary>
             <div style="padding:0 12px 12px;">
               ${palletsRoomLeft > 0 ? `<div style="display:flex; justify-content:flex-end; margin-bottom:6px;"><button type="button" style="${upBtn} margin-left:0;" onclick="applyTotalUnitsSuggestion(${targetFillPallets})" title="Bump Total Units to ${targetFillPallets.toLocaleString()} to fill the last container with pallets">↻ Fill</button></div>` : ''}
               <div style="font-size:13px; color:var(--text); line-height:1.55;">
                 <div>+ <strong style="color:var(--accent);">${palletsRoomLeft}</strong> more pallet${palletsRoomLeft === 1 ? '' : 's'}</div>
                 ${unitsPerPallet > 0
                   ? `<div style="margin-top:4px;">+ <strong style="color:var(--accent);">${(unitsPerPallet * palletsRoomLeft).toLocaleString()}</strong> more ${unitWord} (${unitsPerPallet.toLocaleString()} / pallet)</div>`
                   : ''}
                 <div style="margin-top:4px;">+ <strong style="color:var(--accent);">${fmtCbm(cbmRoomLeft)}</strong> CBM</div>
                 ${palletWeightKg > 0
                   ? `<div style="margin-top:4px;">+ <strong style="color:var(--accent);">${fmtKg(weightRoomLeftKg)}</strong> weight</div>`
                   : `<div style="margin-top:4px; font-size:11px; color:var(--text-muted);">Enter product / carton weight to see weight remaining</div>`}
                 <div style="margin-top:8px; font-size:11px; color:var(--text-muted); line-height:1.5;">
                   to fill the 40' HC limit of <strong>${HC_USABLE_CBM} CBM</strong> · <strong>${HC_MAX_KG.toLocaleString()} kg</strong>
                 </div>
               </div>
               ${looseFit > 0 ? `
               <div style="margin-top:12px; padding-top:12px; border-top:1px dashed var(--border);">
                 <div style="display:flex; align-items:center; justify-content:space-between; gap:8px; margin-bottom:4px;">
                   <div style="font-size:11px; font-weight:700; color:var(--accent);">↳ Top-Off Capacity</div>
                   <button type="button" style="${upBtn}" onclick="applyTotalUnitsSuggestion(${targetFillWithLoose}, ${looseFit * productsPerItem})" title="Bump Total Units to ${targetFillWithLoose.toLocaleString()} — pallets + loose top-off in blue">↻ Top Off</button>
                 </div>
                 <div style="font-size:13px; color:var(--text); line-height:1.5;">
                   You could top off the last container with up to
                   <strong style="color:var(--accent);">~${looseFit.toLocaleString()}</strong> more ${looseLabel}
                   by skipping the pallet and shipping in cardboard boxes.
                 </div>
                 <div style="font-size:11px; color:var(--text-muted); margin-top:6px; line-height:1.5;">
                   Bound by ${looseByCbm <= looseByWeight ? 'CBM' : 'weight'}: ${fmtCbm(cbmRoomLeft)} ÷ ${unitCbm < 0.01 ? (unitCbm * 1000).toFixed(2) + ' L' : unitCbm.toFixed(4) + ' m³'} per unit, at ~80% packing efficiency
                   ${unitWtKg > 0 ? ` &nbsp;·&nbsp; weight cap: ${Math.floor(weightRoomLeftKg / unitWtKg).toLocaleString()} units` : ''}
                 </div>
               </div>` : (_looseUnitsCV > 0 ? `
               <div style="margin-top:12px; padding-top:12px; border-top:1px dashed var(--border); font-size:11px; color:var(--text-muted); line-height:1.5;">
                 ↳ Top-off applied — ${_looseUnitsCV.toLocaleString()} loose ${unitWord}${_looseUnitsCV === 1 ? '' : 's'} already consume the last container's leftover capacity.
               </div>` : '')}
             </div>
           </details>`
        : `<div style="margin-top:14px; padding:12px; border:1px dashed var(--border); border-radius:8px; font-size:12px; color:var(--text-muted); line-height:1.5;">
             A single 40' HC fits <strong>${palletsPerContainer}</strong> pallets${verticalLayers > 1 ? ` (${verticalLayers}-high)` : ''}, up to <strong>${HC_USABLE_CBM} CBM</strong> / <strong>${HC_MAX_KG.toLocaleString()} kg</strong>.
           </div>`;
      // The Optimization Tip — including the loose-load top-off math —
      // lives in the Pallet Stats panel (right column of the Pallet
      // View; see renderPalletViz). Keeping it out of this side panel
      // avoids duplication.

      sideEl.innerHTML = `
        <div style="display:flex; flex-direction:column; gap:14px;">
          <div>
            <div style="font-size:10px; font-weight:700; text-transform:uppercase; letter-spacing:0.06em; color:var(--text-muted); margin-bottom:4px;">Total Pallets</div>
            <div style="font-size:22px; font-weight:700; color:var(--text);">${palletsNeeded.toLocaleString()}</div>
            ${palletsBadge}
            ${stackBadge}
          </div>
          ${palletWeightKg > 0 ? `
          <div>
            <div style="font-size:10px; font-weight:700; text-transform:uppercase; letter-spacing:0.06em; color:var(--text-muted); margin-bottom:4px;">Total Weight</div>
            <div style="font-size:18px; font-weight:700; color:var(--text); line-height:1.3;">${fmtKg(totalShipmentWeightKg)}</div>
            <div style="font-size:11px; color:var(--text-muted); margin-top:4px;">${palletsNeeded.toLocaleString()} pallets × ${fmtKg(palletWeightKg)}</div>
          </div>` : ''}
          ${palletsNeeded > 0 ? `
          <div>
            <div style="font-size:10px; font-weight:700; text-transform:uppercase; letter-spacing:0.06em; color:var(--text-muted); margin-bottom:4px;">Total Volume</div>
            <div style="font-size:18px; font-weight:700; color:var(--text); line-height:1.3;">${fmtCbm(totalShipmentCbm)}</div>
            <div style="font-size:11px; color:var(--text-muted); margin-top:4px;">${fmtCbm(palletCbm)} per pallet × ${palletsNeeded.toLocaleString()} pallets</div>
          </div>` : ''}
        </div>
      `;
      // Render the Last Container — Room to Fill block in its own slot
      // beneath the container 3D viz so it fills the white space there
      // instead of crowding the side stats panel.
      if (fillEl) fillEl.innerHTML = remainingBlock;
    } else if (fillEl) {
      fillEl.innerHTML = '';
    }
    // Hypothetical pricing scenarios — sits between the 3D viz and
    // the Room-to-Fill panel. Computes (A) cost of the as-entered
    // shipment vs (B) cost of filling the remaining container space.
    // Use the FUNCTION ARGS for unitCbm / unitWtKg (the local consts
    // of those names are scoped inside the if (sideEl) block above).
    if (typeof _renderContainerHypotheticals === 'function') {
      _renderContainerHypotheticals({
        palletsNeeded, palletsPerContainer, palletsInLast, palletsRoomLeft,
        cbmRoomLeft, weightRoomLeftKg,
        palletWeightKg, unitsPerPallet,
        unitWord,
        unitCbm: (typeof unitCbmArg === 'number' && unitCbmArg > 0) ? unitCbmArg : 0,
        unitWtKg: (typeof unitWeightKgArg === 'number' && unitWeightKgArg > 0) ? unitWeightKgArg : 0
      });
    }
  }

  // ── Container Hypothetical Pricing Scenarios ─────────────────────────
  // Renders two cards under the 3D container viz:
  //   A. Actual — cost of the current shipment qty at the partial
  //      container state (product cost + freight).
  //   B. Full Container — cost if the operator fills the remaining
  //      container space with the same product (pallets + loose top-
  //      off). Lets them pitch "fill it up" with a concrete delta.
  // Freight method = the shipping tab's #freight-mode dropdown; falls
  // back to "fast" (Fast Boat) when nothing is selected. Per-unit USD
  // price = _lastRfqPriceSummary.grandUsdUnit (single price) or
  // grandUsd / grandQty (weighted across variants).
  function _renderContainerHypotheticals(ctx) {
    try { return _renderContainerHypotheticalsInner(ctx); }
    catch (e) {
      try {
        console.error('[MS hypothetical] threw', e);
        const host = document.getElementById('container-hypothetical');
        if (host) {
          host.innerHTML = `
            <div style="padding:12px 14px; border:1px dashed #ef4444; border-radius:8px; font-size:12px; color:#ef4444; line-height:1.55; font-family:monospace;">
              <strong>Hypothetical threw:</strong> ${String(e && e.message || e)} —
              this means a silent exception was eating the re-render, leaving stale content.
              Screenshot this; the message names the broken function.
            </div>`;
        }
      } catch (_) {}
    }
  }
  function _renderContainerHypotheticalsInner(ctx) {
    const host = document.getElementById('container-hypothetical');
    if (!host) return;
    // Stamp every render with a timestamp so it's instantly visible
    // whether the panel is fresh or stale. If the operator types in a
    // case-only field and this timestamp doesn't update, the render
    // chain is broken upstream (renderPalletViz threw, or oninput
    // isn't firing) — not a bug in this function.
    const _renderTs = new Date().toLocaleTimeString();
    try { console.debug('[MS hypothetical] render', _renderTs, 'mode=' + (typeof _msShipMode === 'function' ? _msShipMode() : '?'), 'palletsNeeded=' + (ctx && ctx.palletsNeeded)); } catch (_) {}
    // Resolve ship-mode + counts through the canonical helpers so any
    // bug in the case-only cascade fixes itself everywhere at once.
    const mode             = _msShipMode();
    const caseOn           = mode === 'case';
    const manualOn         = mode === 'manual';
    const productsPerItem  = _msProductsPerShipItem() || 0;
    const totalUnits       = _msEffectiveTotalUnits();
    // Per-unit USD product price — required for cost math. If the
    // shared _lastRfqPriceSummary hasn't been computed yet (load-time
    // race when fillWorkbook calls renderPalletViz before its later
    // recalcRfqTotals), force a recalc on the spot so the panel reads
    // the price the operator actually entered instead of stalling on a
    // stale null.
    let ps = (typeof _lastRfqPriceSummary !== 'undefined' && _lastRfqPriceSummary) || null;
    if (!ps && typeof recalcRfqTotals === 'function') {
      try { recalcRfqTotals(); } catch (_) {}
      ps = (typeof _lastRfqPriceSummary !== 'undefined' && _lastRfqPriceSummary) || null;
    }
    let usdPerUnit = 0;
    if (ps) {
      if (ps.grandUsdUnit && ps.grandUsdUnit > 0) usdPerUnit = ps.grandUsdUnit;
      else if (ps.grandUsd && ps.grandQty)         usdPerUnit = ps.grandUsd / ps.grandQty;
      else if (ps.usdMin && ps.usdMin > 0)         usdPerUnit = ps.usdMin;
    }
    // Final fallback: scrape the first priced RFQ row directly. Handles
    // edge cases where _lastRfqPriceSummary exists but grandUsdUnit=0
    // (e.g. summary was built from a row whose price was cleared, then
    // a new priced row was added but the recalc bookkeeping missed the
    // unit price for some reason).
    if (!usdPerUnit) {
      const rfqRows = document.querySelectorAll('#rfq-body tr:not([data-rfq-parent]):not([data-rfq-add-for])');
      for (const r of rfqRows) {
        const inputs = r.querySelectorAll('input:not([type="checkbox"])');
        const rmb = _msNumFromInput(inputs[3]);
        if (rmb > 0) {
          usdPerUnit = (typeof _fxUsdFromRmb === 'function') ? _fxUsdFromRmb(rmb) : (rmb / 7.2);
          break;
        }
      }
    }
    // Bail conditions — show a friendly stub instead of a half-baked
    // panel when we lack the *structural* inputs (qty, pallet count).
    // Price (usdPerUnit) is treated as soft: if it's missing we still
    // render the A/B comparison so the operator can see the qty/pallet
    // delta, and the cost rows show a "Add RFQ price" prompt instead
    // of bogus $0.00 numbers.
    if (!totalUnits || ctx.palletsNeeded <= 0) {
      const _dimReason = caseOn
        ? 'Fill in the Case Only Override block (products/case, cases/order, case L × W × H × weight) so the pallet count is known.'
        : (manualOn
          ? 'Set product dimensions so the pallet count is known.'
          : 'Set outer carton dimensions so the pallet count is known.');
      // Diagnostic — when totalUnits is 0 even though the room-to-fill
      // panel is rendering pallet math, the helpers see something the
      // operator doesn't expect. Surface every input the helper reads
      // + the mode it resolved so the next screenshot tells us the
      // exact disagreement.
      const _pcDbg = _msIntFromInput(document.getElementById('case-only-products-per'));
      const _coDbg = _msIntFromInput(document.getElementById('case-only-cases-order'));
      const _ptDbg = _msIntFromInput(document.getElementById('pallet-total-cartons'));
      const _cbDbg = !!document.getElementById('case-only-override')?.checked;
      const _mnDbg = !!document.getElementById('pallet-manual')?.checked;
      const _diag = `<span style="display:block; margin-top:6px; font-size:11px; color:var(--text-muted); font-family:monospace;">[diag @${_renderTs}: mode=${mode} · case-checkbox=${_cbDbg} · manual-checkbox=${_mnDbg} · pc=${_pcDbg} · co=${_coDbg} · pallet-total=${_ptDbg} · totalUnits=${totalUnits} · palletsNeeded=${ctx.palletsNeeded}]</span>`;
      let reason;
      if (!totalUnits) {
        if (caseOn) {
          if (_pcDbg === 0 && _coDbg === 0 && _ptDbg === 0) {
            reason = 'Enter Products/Case + Cases/Order in the Case Only Override block (or Total Units to Ship on the Pallet section).';
          } else if (_pcDbg === 0) {
            reason = 'Enter Products/Case in the Case Only Override block.';
          } else if (_coDbg === 0) {
            reason = 'Enter Cases/Order in the Case Only Override block.';
          } else {
            reason = 'Case math should have produced a positive total — see diag below.';
          }
        } else {
          reason = 'Enter Total Units to Ship.';
        }
      } else {
        reason = _dimReason;
      }
      reason = reason + _diag;
      host.innerHTML = `
        <div style="padding:12px 14px; border:1px dashed var(--border); border-radius:8px; font-size:12px; color:var(--text-muted); line-height:1.55;">
          <strong style="color:var(--text);">Hypothetical scenarios:</strong> ${reason}
        </div>`;
      return;
    }
    // Freight method — prefer the shipping tab's selection, else Fast.
    const modeSel = document.getElementById('freight-mode');
    const method  = (modeSel && modeSel.value && freightMethodRates[modeSel.value]) ? modeSel.value : 'fast';
    const methodLabel = (typeof SPLIT_METHOD_LABELS !== 'undefined' && SPLIT_METHOD_LABELS[method]) || method;
    const usingUserMethod = (modeSel && modeSel.value && modeSel.value === method && method !== 'fast') || (modeSel && modeSel.value === 'fast');
    // ── Compute the pre-Apply baseline ──────────────────────────────────
    // When a pitch is applied, totalUnits + ctx.palletsNeeded reflect
    // the BUMPED state (e.g. 36 pallets after Full Apply). To keep
    // Card A always showing the original 110,000 / 3-pallet state for
    // comparison, recover the baseline from the snapshot.
    //
    //   - snap.totalUnits     → string with commas → baseQty (products)
    //   - basePalletsNeeded   → ceil(baseQty / productsPerItem / cases-per-pallet)
    //   - basePalletsInLast   → pallets in the LAST container at baseline
    //   - basePalletsRoomLeft → empty slots in that last container
    //
    // All three scenario cards (A/B/C) then compute against THIS baseline,
    // not against the currently-applied state. The "currently applied"
    // card just gets the Revert affordance.
    // Snap sanity check — if the operator typed over the Total Units
    // input (or RFQ resync ran) without going through Revert, snap.
    // appliedQty no longer matches what's in the input. The "Apply"
    // / "Revert" buttons would then lie about state. Safer to drop a
    // diverged snap here so the panel re-derives from the live qty.
    // Logged so we can spot which paths leak. The Math.max guard on
    // appliedQty is so legacy snaps without that field don't trip.
    let _snap = window._fullContainerPitchSnap;
    if (_snap && _snap.appliedQty) {
      const _snapAppliedQty = parseInt(String(_snap.appliedQty).replace(/,/g, ''), 10) || 0;
      if (_snapAppliedQty > 0 && Math.abs(totalUnits - _snapAppliedQty) > 0) {
        try { console.warn('[MS hypotheticals] snap.appliedQty (' + _snapAppliedQty + ') diverges from input (' + totalUnits + ') — clearing stale snap'); } catch(_) {}
        window._fullContainerPitchSnap = null;
        _snap = null;
      }
    }
    const snap = _snap;
    const isApplied = !!snap;
    const appliedKind = isApplied ? (snap.pitchKind || 'full') : null;
    const baseQty = isApplied
      ? (parseInt((snap.totalUnits || '').replace(/,/g, ''), 10) || totalUnits)
      : totalUnits;
    const _ppi = productsPerItem || 1;
    const _upp = ctx.unitsPerPallet || 0;
    const _palletsPerContainer = ctx.palletsPerContainer || 0;
    // basePalletsNeeded: ceil(baseQty / products-per-case / cases-per-pallet)
    const baseTotalItems     = _ppi > 0 ? Math.ceil(baseQty / _ppi) : 0;
    const basePalletsNeeded  = (_upp > 0 && baseTotalItems > 0)
      ? Math.ceil(baseTotalItems / _upp)
      : (ctx.palletsNeeded || 0);
    const baseContainersNeeded = (_palletsPerContainer > 0 && basePalletsNeeded > 0)
      ? Math.ceil(basePalletsNeeded / _palletsPerContainer) : 0;
    const basePalletsInLast    = (baseContainersNeeded > 0)
      ? (basePalletsNeeded - (baseContainersNeeded - 1) * _palletsPerContainer)
      : (ctx.palletsInLast || 0);
    const basePalletsRoomLeft  = Math.max(0, _palletsPerContainer - basePalletsInLast);

    // ── Scenario C (full container) math — against the baseline ────────
    const palletItems     = basePalletsRoomLeft * _upp;
    const palletProducts  = palletItems * _ppi;
    const PACK_EFF = 0.80;
    // Loose top-off based on baseline's leftover CBM/weight. Approximate
    // by computing remaining capacity in the last container after the
    // baseline pallets, not relying on ctx.cbmRoomLeft (which reflects
    // the CURRENT applied state).
    const HC_USABLE_CBM_LOCAL = 67;
    const HC_MAX_KG_LOCAL     = 26000;
    const palletCbmLocal = ctx.palletWeightKg && _upp > 0 && ctx.unitCbm > 0
      ? (ctx.unitCbm * _upp + 0.05 /* deck approx */)
      : 0;
    // Simpler: cbm/weight room left at baseline = full container minus
    // baseline pallets' CBM/weight. Use ctx.palletWeightKg as per-pallet
    // weight (caller passes the same value regardless of applied state).
    const _palletWtKg = ctx.palletWeightKg || 0;
    const _basePalletCbm = (ctx.unitCbm > 0 && _upp > 0) ? ctx.unitCbm * _upp : 0;
    const baseCbmRoomLeft = Math.max(0, HC_USABLE_CBM_LOCAL - _basePalletCbm * basePalletsInLast);
    const baseWtRoomLeft  = Math.max(0, HC_MAX_KG_LOCAL - _palletWtKg * basePalletsInLast);
    let looseItems = 0;
    if (ctx.unitCbm > 0) {
      const byCbm    = Math.floor((baseCbmRoomLeft * PACK_EFF) / ctx.unitCbm);
      const byWeight = ctx.unitWtKg > 0 ? Math.floor(baseWtRoomLeft / ctx.unitWtKg) : byCbm;
      looseItems = Math.max(0, Math.min(byCbm, byWeight));
    }
    const looseProducts = looseItems * _ppi;
    const additionalProducts = palletProducts + looseProducts;
    const fullQty = baseQty + additionalProducts;

    // ── Scenario B (half container LCL) math — against the baseline ────
    // Half = fill the last container to floor(palletsPerContainer / 2)
    // pallets, no loose top-off (LCL doesn't maximize leftover space).
    const _halfPalletsTarget = Math.floor(_palletsPerContainer / 2);
    const _halfAddPallets    = Math.max(0, _halfPalletsTarget - basePalletsInLast);
    const _halfAddItems      = _halfAddPallets * _upp;
    const _halfAddProducts   = _halfAddItems * _ppi;
    const halfQty            = baseQty + _halfAddProducts;
    const _halfPalletsTotal  = basePalletsNeeded + _halfAddPallets;
    // Freight costs — calcSplitCost takes qty in PRODUCTS and bakes in
    // outer-carton conversion + per-mode rate/divisor for us. Manual
    // shipping-cost override (if active) replaces BOTH scenarios with
    // the same value, since real-world ocean freight is per-container
    // regardless of fill rate. Per-unit cost then differs between A
    // and B purely from the division by qty — which IS the whole
    // point of the "fill the container" pitch.
    // Freight computation — three scenarios, each at its own qty.
    // - A (Actual) ALWAYS uses the calc-method at baseQty (no override),
    //   because the override represents the projected full-container
    //   freight, not the actual partial-load rate.
    // - B (Half) uses the calc-method at halfQty (LCL, no override).
    // - C (Full) uses the override if set ($16,500 typical), else the
    //   calc-method projected onto fullQty.
    const overrideUsd = (typeof _getShippingCostOverrideUsd === 'function')
      ? _getShippingCostOverrideUsd() : null;
    const parseUsd = (s) => s ? parseFloat(s.replace(/[^0-9.\-]/g, '')) || 0 : 0;
    // Mode-aware freight per qty. calcSplitCost reads only the outer-
    // carton fields, which are EMPTY in Case Only and Manual mode, so
    // it returned null and the freight rendered as $0.00. Compute
    // freight here against the active mode's ship-unit dims + weight
    // so A and B show a real Slow Boat rate instead of zero.
    //
    //   freight (USD) = max(actual_kg, volumetric_kg) × rate × cartons / USD_TO_RMB
    //     - cartons         = ceil(qty / products-per-ship-item)
    //     - rate            = freightMethodRates[method]   (¥/kg)
    //     - volumetric_kg   = L × W × H (cm) / divisor
    //     - actual_kg       = ship-unit weight (case / product / outer)
    const _modeForFreight = _msShipMode();
    const _ppiForFreight  = _msProductsPerShipItem() || 1;
    let _fL = 0, _fW = 0, _fH = 0, _fKg = 0;
    if (_modeForFreight === 'case') {
      _fL  = parseFloat(document.getElementById('case-only-l-cm')?.value) || 0;
      _fW  = parseFloat(document.getElementById('case-only-w-cm')?.value) || 0;
      _fH  = parseFloat(document.getElementById('case-only-h-cm')?.value) || 0;
      _fKg = parseFloat(document.getElementById('case-only-weight-kg')?.value) || 0;
    } else if (_modeForFreight === 'manual') {
      _fL  = parseFloat(document.getElementById('dim-cm-l')?.value) || 0;
      _fW  = parseFloat(document.getElementById('dim-cm-w')?.value) || 0;
      _fH  = parseFloat(document.getElementById('dim-cm-h')?.value) || 0;
      _fKg = parseFloat(document.getElementById('dim-weight-kg')?.value) || 0;
    } else {
      _fL  = parseFloat(document.getElementById('carton-outer-l-cm')?.value) || 0;
      _fW  = parseFloat(document.getElementById('carton-outer-w-cm')?.value) || 0;
      _fH  = parseFloat(document.getElementById('carton-outer-h-cm')?.value) || 0;
      _fKg = parseFloat(document.getElementById('carton-outer-weight')?.value) || 0;
    }
    const _fRate    = (typeof freightMethodRates    !== 'undefined' && freightMethodRates[method])    || (freightMethodRates && freightMethodRates.slow)    || 12;
    const _fDivisor = (typeof freightMethodDivisors !== 'undefined' && freightMethodDivisors[method]) || (freightMethodDivisors && freightMethodDivisors.slow) || 6000;
    const _fxRate   = (typeof USD_TO_RMB === 'number' && USD_TO_RMB > 0) ? USD_TO_RMB : 7.2;
    const _calcFreightUsdForQty = (qty) => {
      const q = parseInt(qty) || 0;
      if (q <= 0 || !_fL || !_fW || !_fH || !_fKg) return 0;
      const cartons = Math.ceil(q / _ppiForFreight);
      const volKg   = (_fL * _fW * _fH) / _fDivisor;
      const charge  = Math.max(_fKg, volKg);
      const rmb     = charge * cartons * _fRate;
      return rmb / _fxRate;
    };
    const _calcAUsd = _calcFreightUsdForQty(baseQty);
    const _calcBUsd = _calcFreightUsdForQty(halfQty);
    const _calcCUsd = _calcFreightUsdForQty(fullQty);
    // A always shows the calc rate (the baseline reality). B (half /
    // LCL) also uses the calc rate. C is the FULL container booking,
    // which in the real world is a flat per-container fee — pin it to
    // FULL_CONTAINER_FREIGHT_USD ($16,500 by default) so the operator
    // can always see "this is what a full container costs." If the
    // operator has set an override quote (e.g. a freight broker quoted
    // them a different number), honor that override instead.
    const _fullFreightDefault = (typeof FULL_CONTAINER_FREIGHT_USD === 'number') ? FULL_CONTAINER_FREIGHT_USD : 16500;
    const freightUsdA = _calcAUsd;
    const freightUsdB = _calcBUsd;
    const freightUsdC = (overrideUsd !== null && overrideUsd > 0) ? overrideUsd : _fullFreightDefault;
    const productUsdA = baseQty * usdPerUnit;
    const productUsdB = halfQty * usdPerUnit;
    const productUsdC = fullQty * usdPerUnit;
    const totalUsdA   = productUsdA + freightUsdA;
    const totalUsdB   = productUsdB + freightUsdB;
    const totalUsdC   = productUsdC + freightUsdC;
    const landedA = baseQty > 0 ? totalUsdA / baseQty : 0;
    const landedB = halfQty > 0 ? totalUsdB / halfQty : 0;
    const landedC = fullQty > 0 ? totalUsdC / fullQty : 0;
    // Savings vs baseline (A) for each upsell card
    const savingsB    = landedA - landedB;
    const savingsBPct = landedA > 0 ? Math.round((savingsB / landedA) * 100) : 0;
    const savingsC    = landedA - landedC;
    const savingsCPct = landedA > 0 ? Math.round((savingsC / landedA) * 100) : 0;
    const fmt$ = (n) => '$' + n.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    const card = (kind, title, lines, footer, action, isLive) => {
      const colors = {
        actual: { bd:'var(--border)', bg:'var(--surface2)', accent:'var(--text)' },
        // Half-container = sales-pitch blue (calmer than the full-
        // container green so the upsell hierarchy still reads B > C).
        half:   { bd:'#3b82f6',       bg:'rgba(59,130,246,0.08)', accent:'#3b82f6' },
        full:   { bd:'#10b981',       bg:'rgba(16,185,129,0.08)', accent:'#10b981' }
      };
      const c = colors[kind] || colors.actual;
      // Static cards — same dimensions / border / shadow / position
      // regardless of which scenario is currently applied. The only
      // visual cue for "this one is applied" is a small inline ✓ next
      // to the letter in the title row, so layout never shifts when
      // the operator clicks Apply / Revert.
      const liveCheck = isLive
        ? `<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="${c.accent}" stroke-width="3" stroke-linecap="round" stroke-linejoin="round" style="display:inline-block; vertical-align:-2px; margin-right:4px;"><polyline points="20 6 9 17 4 12"></polyline></svg>`
        : '';
      const actionHtml = action
        ? `<div style="margin-top:10px;">
             <button type="button" onclick="${action.call}"
               style="background:${c.accent}; color:#fff; border:none; padding:7px 14px; border-radius:6px; font-size:12px; font-weight:700; cursor:pointer; display:inline-flex; align-items:center; gap:5px;"
               onmouseover="this.style.filter='brightness(0.92)';"
               onmouseout="this.style.filter='';"
               title="${action.title || action.label}">↻ ${action.label}</button>
           </div>`
        : '';
      return `<div style="padding:14px; border:1px solid ${c.bd}; border-radius:8px; background:${c.bg}; min-width:0;">
        <div style="font-size:10px; font-weight:700; text-transform:uppercase; letter-spacing:0.06em; color:${c.accent}; margin-bottom:10px;">${liveCheck}${title}</div>
        ${lines.map(l => `<div style="display:flex; justify-content:space-between; gap:10px; font-size:12px; line-height:1.8;">
          <span style="color:var(--text-muted);">${l[0]}</span>
          <span style="color:var(--text); font-weight:600; white-space:nowrap;">${l[1]}</span>
        </div>`).join('')}
        ${footer ? `<div style="margin-top:10px; padding-top:10px; border-top:1px solid var(--border); font-size:11px; color:var(--text-muted); line-height:1.5;">${footer}</div>` : ''}
        ${actionHtml}
      </div>`;
    };
    // Per-scenario freight labels. A and B are always calc-method
    // (LCL / partial-load reality). C is pinned to the full-container
    // booking rate ($16,500 by default, or the operator's override
    // quote if set) — the label reflects which source produced it.
    const labelMethod   = `Freight (${methodLabel})`;
    const labelOverride = `Freight (override)`;
    const labelFullCnt  = `Freight (full container)`;
    const freightLabelA = labelMethod;
    const freightLabelB = labelMethod;
    const freightLabelC = (overrideUsd !== null && overrideUsd > 0) ? labelOverride : labelFullCnt;
    // When usdPerUnit is missing, swap every cost row for an inline
    // prompt so the operator sees the qty/pallet delta but isn't
    // misled by bogus $0.00 totals. The Per-unit landed row still
    // shows the freight-per-unit (which is independent of product
    // price) so they get a real partial-vs-full freight comparison.
    const _needsPrice = !ps || !usdPerUnit;
    const priceMissing = `<span style="color:var(--text-muted); font-style:italic;">Add RFQ price →</span>`;
    const freightPerUnitA = baseQty > 0 ? freightUsdA / baseQty : 0;
    const freightPerUnitB = halfQty > 0 ? freightUsdB / halfQty : 0;
    const freightPerUnitC = fullQty > 0 ? freightUsdC / fullQty : 0;
    // A = baseline / pre-Apply state. Always shown with neutral styling
    // for comparison, regardless of which (if any) pitch is applied.
    const linesA = [
      ['Units shipped',  baseQty.toLocaleString()],
      ['Pallets needed', basePalletsNeeded.toLocaleString()],
      ['Product cost',   _needsPrice ? priceMissing : fmt$(productUsdA)],
      [freightLabelA,    fmt$(freightUsdA)],
      ['Total landed',   _needsPrice ? priceMissing : `<strong style="font-size:14px;">${fmt$(totalUsdA)}</strong>`],
      [_needsPrice ? 'Freight / unit' : 'Per-unit landed', fmt$(_needsPrice ? freightPerUnitA : landedA)]
    ];
    // B = Half Container Pitch (LCL), blue accent.
    const linesB = [
      ['Units shipped',  `${halfQty.toLocaleString()} <span style="color:#3b82f6; font-weight:700;">(+${_halfAddProducts.toLocaleString()})</span>`],
      ['Pallets needed', `${_halfPalletsTotal.toLocaleString()}`],
      ['Product cost',   _needsPrice ? priceMissing : fmt$(productUsdB)],
      [freightLabelB,    fmt$(freightUsdB)],
      ['Total landed',   _needsPrice ? priceMissing : `<strong style="font-size:14px; color:#3b82f6;">${fmt$(totalUsdB)}</strong>`],
      [_needsPrice ? 'Freight / unit' : 'Per-unit landed', `<strong style="color:#3b82f6;">${fmt$(_needsPrice ? freightPerUnitB : landedB)}</strong>`]
    ];
    // C = Full Container Pitch, green accent.
    const linesC = [
      ['Units shipped',  `${fullQty.toLocaleString()} <span style="color:#10b981; font-weight:700;">(+${additionalProducts.toLocaleString()})</span>`],
      ['Pallets needed', `${(basePalletsNeeded + basePalletsRoomLeft).toLocaleString()}`],
      ['Product cost',   _needsPrice ? priceMissing : fmt$(productUsdC)],
      [freightLabelC,    fmt$(freightUsdC)],
      ['Total landed',   _needsPrice ? priceMissing : `<strong style="font-size:14px; color:#10b981;">${fmt$(totalUsdC)}</strong>`],
      [_needsPrice ? 'Freight / unit' : 'Per-unit landed', `<strong style="color:#10b981;">${fmt$(_needsPrice ? freightPerUnitC : landedC)}</strong>`]
    ];
    // Footer for A — baseline. Just notes the pallet slots unused at
    // the BASELINE qty (not whatever's currently applied).
    const footerA = `${basePalletsRoomLeft} pallet slot${basePalletsRoomLeft === 1 ? '' : 's'} unused in the last container at the baseline qty.`;
    // Footer for B (half / blue) — landed savings vs A, or freight-
    // savings if no product price yet.
    const _freightSavB    = freightPerUnitA - freightPerUnitB;
    const _freightSavBPct = freightPerUnitA > 0 ? Math.round((_freightSavB / freightPerUnitA) * 100) : 0;
    const footerB = _needsPrice
      ? (_freightSavB > 0
        ? `↓ <strong style="color:#3b82f6;">${fmt$(_freightSavB)}/unit (${_freightSavBPct}%)</strong> lower freight per unit at ~50% container fill (LCL). Add an RFQ price to see the full landed-cost delta.`
        : `Add an RFQ price to see the landed-cost savings at half-container fill.`)
      : (savingsB > 0
        ? `↓ <strong style="color:#3b82f6;">${fmt$(savingsB)}/unit (${savingsBPct}%)</strong> lower than the baseline — half-container fill (LCL) at the calculated method rate.`
        : `Half-container fill (LCL) at the current price point.`);
    // Footer for C (full / green) — landed savings vs A, or freight-
    // savings if no product price yet.
    const _freightSavC    = freightPerUnitA - freightPerUnitC;
    const _freightSavCPct = freightPerUnitA > 0 ? Math.round((_freightSavC / freightPerUnitA) * 100) : 0;
    const footerC = _needsPrice
      ? (_freightSavC > 0
        ? `↓ <strong style="color:#10b981;">${fmt$(_freightSavC)}/unit (${_freightSavCPct}%)</strong> lower freight per unit — filling the container with ${additionalProducts.toLocaleString()} more units spreads the freight across the full load. Add an RFQ price to see the full landed-cost delta.`
        : `Add an RFQ price to see the landed-cost savings from filling the container.`)
      : (savingsC > 0
        ? `↓ <strong style="color:#10b981;">${fmt$(savingsC)}/unit (${savingsCPct}%)</strong> lower than the baseline — filling the container with ${additionalProducts.toLocaleString()} more units spreads freight across the full load.`
        : `Filling the container doesn't lower the per-unit landed cost at the current price point.`);
    host.innerHTML = `
      <div style="display:flex; align-items:center; justify-content:space-between; margin-bottom:8px; gap:10px;">
        <div style="font-size:11px; font-weight:700; text-transform:uppercase; letter-spacing:0.06em; color:var(--text-muted);">Hypothetical Scenarios</div>
        <div style="font-size:11px; color:var(--text-muted);">Method: <strong style="color:var(--text);">${methodLabel}</strong> · Per-unit: ${_needsPrice ? '<span style="font-style:italic;">—</span>' : fmt$(usdPerUnit)}</div>
      </div>
      ${(() => {
        // Card actions:
        //   - A (baseline) never has an action; it's a pure comparison
        //     card that stays the same regardless of which pitch is
        //     currently applied.
        //   - B (half) shows "Apply Half" by default, "Revert" when
        //     the half pitch is currently applied, and "Apply Half"
        //     when the full pitch is applied (clicking switches to
        //     half without losing the baseline snap).
        //   - C (full) shows "Apply Full" by default, "Revert" when
        //     the full pitch is currently applied, and "Apply Full"
        //     when the half pitch is applied (clicking switches to
        //     full, also flips the freight override to $16,500).
        // Short button labels — keep the column from wrapping the
        // button onto two lines. Full context (qty + behavior) lives
        // in the title attribute / tooltip.
        const revertTooltip = baseQty > 0
          ? `Revert Total Units back to ${baseQty.toLocaleString()}`
          : 'Revert Total Units to the pre-apply value';
        // Apply Half is always offered when halfQty is valid so the
        // operator can always toggle / re-lock the half-container
        // state. When _halfAddProducts > 0 it adds units; when it's
        // 0 (current qty already at-or-past the half-fill threshold)
        // it's a no-op snap that just records "Half" as the state so
        // Revert / scenario badges read correctly. Without this the
        // button used to disappear entirely after Apply→Revert
        // sequences left the operator past the threshold, with no
        // way to get the button back without typing into the input.
        const actionB = (appliedKind === 'half')
          ? { label: 'Revert',
              title: revertTooltip,
              call:  `revertFullContainerPitch()` }
          : (halfQty > 0
            ? { label: _halfAddProducts > 0 ? 'Apply Half' : 'Lock Half',
                title: _halfAddProducts > 0
                  ? `Set Total Units to ${halfQty.toLocaleString()} (LCL, ~50% container fill)`
                  : `Already at the half-container fill threshold (${halfQty.toLocaleString()} units). Click to lock this state in so the panel labels Half as the applied scenario.`,
                call:  `applyHalfContainerPitch(${halfQty})` }
            : null);
        const actionC = (appliedKind === 'full')
          ? { label: 'Revert',
              title: revertTooltip,
              call:  `revertFullContainerPitch()` }
          : (additionalProducts > 0
            ? { label: 'Apply Full',
                title: `Set Total Units to ${fullQty.toLocaleString()} and flip freight to the full-container rate`,
                call:  `applyFullContainerPitch(${fullQty}, ${looseProducts})` }
            : null);
        // Which scenario is currently live on the workbook?
        // - No snap → A (baseline)
        // - snap.pitchKind === 'half' → B
        // - snap.pitchKind === 'full' → C
        // Which scenario is currently live on the workbook?
        //   - No snap        → A (baseline)
        //   - snap.kind 'half' → B
        //   - snap.kind 'full' → C
        // card() paints a thick accent border + accent body tint +
        // accent-tinted shadow + a green "✓ APPLIED" pill on whichever
        // card matches liveKind. Multiple stacked cues so the operator
        // can't miss which scenario is the workbook's current state.
        const liveKind = appliedKind || 'actual';
        // Three-column grid so A/B/C stay on the same row across the
        // full panel width.
        // auto-fit keeps the three-up layout on desktop but stacks
        // (or 2-ups) when the viewport narrows past ~720px — phone
        // operators can still read the comparison without horizontal
        // scrolling.
        return `<div style="display:grid; grid-template-columns:repeat(auto-fit, minmax(220px, 1fr)); gap:12px;">
          ${card('actual', 'A · Actual (Partial)',           linesA, footerA, null,    liveKind === 'actual')}
          ${card('half',   'B · Half Container Pitch (LCL)', linesB, footerB, actionB, liveKind === 'half')}
          ${card('full',   'C · Full Container Pitch',       linesC, footerC, actionC, liveKind === 'full')}
        </div>`;
      })()}`;
  }

  // Safety wrapper — any uncaught exception inside the pallet render
  // used to bubble all the way up to _fillWorkbookInner and bork the
  // "Could not load this workbook" path. Log + swallow so the rest of
  // the workbook stays loadable even if a future edit introduces a
  // TDZ / null-ref in this huge function.
  function renderPalletViz() {
    try { _renderPalletVizInner(); }
    catch (e) { try { console.error('[MS renderPalletViz]', e); } catch (_) {} }
  }
  function _renderPalletVizInner() {
    const canvas = document.getElementById('pallet-canvas');
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    const CW = canvas.width, CH = canvas.height;
    ctx.clearRect(0, 0, CW, CH);
    // ── Load-mode resolution (HOISTED) ────────────────────────────────
    // Pallet vs Loose-Load radio on the Pallet View card. Declared at
    // the top of the function so every downstream block can reference
    // _looseLoad without tripping the const-TDZ — earlier the deck-
    // height path used _looseLoad before it was declared further down,
    // which threw a ReferenceError and killed workbook loading.
    const _loadMode = (typeof _palletLoadMode === 'function') ? _palletLoadMode() : 'pallet';
    const _looseLoad = _loadMode === 'loose';

    // Mode resolution — three mutually-exclusive overrides plus the
    // default carton-driven path:
    //   • caseOn    → use Case Only Override dims (case L × W × H,
    //     cases-per-order, products-per-case). Each CASE lands on the
    //     pallet, drives the freight + container math.
    //   • manualOn  → use PRODUCT dims directly on the pallet base
    //     (existing manual mode).
    //   • default   → carton mode (outer carton dims).
    const caseOn   = !!document.getElementById('case-only-override')?.checked;
    const manualOn = !caseOn && !!document.getElementById('pallet-manual')?.checked;
    let bL, bW, bH;
    if (caseOn) {
      bL = parseFloat(document.getElementById('case-only-l-cm').value);
      bW = parseFloat(document.getElementById('case-only-w-cm').value);
      bH = parseFloat(document.getElementById('case-only-h-cm').value);
    } else if (manualOn) {
      bL = parseFloat(document.getElementById('dim-cm-l').value);
      bW = parseFloat(document.getElementById('dim-cm-w').value);
      bH = parseFloat(document.getElementById('dim-cm-h').value);
    } else {
      bL = parseFloat(document.getElementById('carton-outer-l-cm').value);
      bW = parseFloat(document.getElementById('carton-outer-w-cm').value);
      bH = parseFloat(document.getElementById('carton-outer-h-cm').value);
    }

    if (!bL || !bW || !bH) {
      ctx.fillStyle = '#aaa';
      ctx.font = '13px -apple-system, BlinkMacSystemFont, sans-serif';
      ctx.textAlign = 'center';
      const need = caseOn ? 'case' : (manualOn ? 'product' : 'outer carton');
      ctx.fillText(`Enter ${need} dimensions`, CW/2, CH/2 - 8);
      ctx.fillText('to see pallet visualization', CW/2, CH/2 + 10);
      document.getElementById('pallet-stats').innerHTML = `<span style="color:var(--text-muted); font-size:13px;">Enter ${need} dimensions to calculate.</span>`;
      const inlineEl = document.getElementById('pallet-inline-stats');
      if (inlineEl) { inlineEl.style.display = 'none'; inlineEl.textContent = ''; }
      // Still render an empty-state container preview so the operator
      // sees the 40' HC capacity badge even before entering dims.
      if (typeof renderContainerViz === 'function') renderContainerViz(0, 0, PALLET_L, PALLET_W, 0, 0, 0);
      const sugHost = document.getElementById('pallet-fit-suggestion');
      if (sugHost) { sugHost.style.display = 'none'; sugHost.innerHTML = ''; }
      return;
    }

    // 4 mm divider — applies in manual mode only. Adds 0.4 cm of pad
    // around every product on every axis so adjacent items have room
    // for cardboard / foam separators. The padding flows into the
    // orientation math (cols/rows) AND the vertical stack (max layers).
    const dividerOn = manualOn && !!document.getElementById('pallet-divider')?.checked;
    const padCm = dividerOn ? 0.4 : 0;
    const layout = bestPalletOrientation(bL + padCm, bW + padCm);
    const perLayer = layout.cols * layout.rows;

    // Footprint too large to fit on pallet. We do NOT assume overhang —
    // if a single unit is wider than 40×48 in, then 0 fit per pallet.
    // The operator should re-check dimensions (likely a unit error like
    // 220 cm meant 22 cm) or accept this is a corner case for ops to
    // handle off-system.
    if (perLayer === 0) {
      const noun     = caseOn ? 'Case'  : (manualOn ? 'Product' : 'Outer carton');
      const lcNoun   = caseOn ? 'case'  : (manualOn ? 'product' : 'outer carton');
      const remedy   = caseOn
        ? 'Double-check the case dimensions in the Case Only Override block — a 40 × 48 in (101.6 × 121.9 cm) pallet base can\'t hold this footprint.'
        : (manualOn
          ? 'Double-check the product dimensions — a 40 × 48 in (101.6 × 121.9 cm) pallet base can\'t hold this footprint. If this is intentional (oversized crate), it must be handled outside the pallet calculator.'
          : 'Try reducing the <strong>inner cartons / outer</strong> qty so the outer carton fits on the pallet.');
      ctx.fillStyle = '#aaa';
      ctx.font = '13px -apple-system, BlinkMacSystemFont, sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(`${noun} is too large for a 40 × 48 pallet.`, CW/2, CH/2 - 10);
      ctx.font = '11px -apple-system, BlinkMacSystemFont, sans-serif';
      ctx.fillText(`${noun}: ${bL.toFixed(1)} × ${bW.toFixed(1)} cm — Pallet: ${PALLET_L} × ${PALLET_W} cm`, CW/2, CH/2 + 10);
      if (!manualOn && !caseOn) ctx.fillText('Try reducing the number of inner cartons per outer.', CW/2, CH/2 + 28);
      document.getElementById('pallet-stats').innerHTML = `
        <div style="color:#f59e0b; font-size:13px; font-weight:600; margin-bottom:8px;">⚠ ${noun} exceeds pallet dimensions</div>
        <div style="font-size:12px; color:var(--text-muted); line-height:1.6;">
          The ${lcNoun} footprint (${bL.toFixed(1)} × ${bW.toFixed(1)} cm) is larger than the 40 × 48 in pallet (101.6 × 121.9 cm).<br><br>
          ${remedy}
        </div>`;
      const inlineEl = document.getElementById('pallet-inline-stats');
      if (inlineEl) {
        inlineEl.style.display = '';
        inlineEl.innerHTML = caseOn
          ? `<span style="color:#f59e0b;">⚠ Case too large for pallet base — check case dimensions</span>`
          : (manualOn
            ? `<span style="color:#f59e0b;">⚠ Product too large for pallet base — check dimensions</span>`
            : `<span style="color:#f59e0b;">⚠ Outer carton too large for pallet — reduce inner cartons / outer</span>`);
      }
      // Even when the current box overhangs, surface a fit suggestion
      // if an outer carton is filled in and shrinking it lands a clean
      // grid. Same outer-carton-required gate as the non-overhang path.
      const _maxHIn = parseFloat(document.getElementById('pallet-max-height')?.value) || 60;
      const _oL = parseFloat(document.getElementById('carton-outer-l-cm')?.value);
      const _oW = parseFloat(document.getElementById('carton-outer-w-cm')?.value);
      const _oH = parseFloat(document.getElementById('carton-outer-h-cm')?.value);
      if (typeof _renderPalletFitSuggestion === 'function') {
        if (_oL > 0 && _oW > 0 && _oH > 0) {
          _renderPalletFitSuggestion(_oL, _oW, _oH, 0, _maxHIn * 2.54, false, 0, 1, 0);
        } else {
          const sugHost = document.getElementById('pallet-fit-suggestion');
          if (sugHost) { sugHost.style.display = 'none'; sugHost.innerHTML = ''; }
        }
      }
      return;
    }

    const maxLoadHIn = parseFloat(document.getElementById('pallet-max-height').value) || 60;
    const maxLoadH = maxLoadHIn * 2.54; // convert inches to cm
    // Vertical stack pitch includes the divider pad — products are
    // separated by 0.4 cm of cardboard / foam between layers too when
    // the divider option is on.
    const stackPitchH = bH + padCm;
    const maxLayers = Math.max(1, Math.floor(maxLoadH / stackPitchH));
    const showLayers = Math.min(maxLayers, 12); // cap visual layers

    // Per-row / per-layer height hint — sits directly below the Max
    // Height field. Shows the height of each outer-carton (or product,
    // in manual mode) row in inches, rounded UP so the operator knows
    // the worst-case per-layer height including the 4 mm divider pad
    // when applicable.
    const layerHintEl = document.getElementById('pallet-layer-height-hint');
    if (layerHintEl) {
      if (bH > 0) {
        const layerInRound = Math.ceil(stackPitchH / 2.54);
        const noun = caseOn ? 'case' : (manualOn ? 'product' : 'carton');
        layerHintEl.innerHTML = `Each ${noun} row: <strong>~${layerInRound}"</strong> <span style="opacity:0.7;">(${stackPitchH.toFixed(1)} cm${dividerOn ? ' incl. 4mm pad' : ''})</span>`;
      } else {
        layerHintEl.textContent = '';
      }
    }

    // Scale to fit canvas — origin near top, stack grows upward.
    // Asymmetric padding: WAY more room on the LEFT for the H bracket
    // + horizontal H label like "H 62\" (158.5 cm)" (~150 px wide at
    // 16px), tight right edge for the W label tail. The iso shape
    // shifts well into the right half of the canvas so the L and W
    // labels at the bottom corners separate cleanly.
    // In loose-load mode every reference to the wood-pallet deck drops
    // out — the cargo sits straight on the container floor, so the
    // ~15 cm of deck height becomes additional vertical room for
    // product. palletDeckCm shadows the global PALLET_DECK constant
    // through the rest of this function (drawing + stack-height math +
    // dim-label totals + optimization-tip thresholds).
    const palletDeckCm = _looseLoad ? 0 : PALLET_DECK;
    const footprintSpan = PALLET_L + PALLET_W;
    const stackH = palletDeckCm + showLayers * stackPitchH;
    const LABEL_PAD_LEFT  = 190; // room for the full H bracket + label
    const LABEL_PAD_RIGHT = 40;  // tight right edge — W label tail clears
    const LABEL_PAD_Y     = 110; // px reserved below for L bracket
    const LABEL_PAD_TOP   = 32;  // px reserved above for the top-right badge
    const s = Math.min(
      (CW - LABEL_PAD_LEFT - LABEL_PAD_RIGHT) / (footprintSpan * ISO_COS30),
      (CH - LABEL_PAD_Y - LABEL_PAD_TOP) / (stackH + footprintSpan * ISO_SIN30)
    );
    // Pin the iso's leftmost silhouette point exactly at LABEL_PAD_LEFT
    // so all the extra slack lives on the left where the H label sits.
    // The leftmost screen x of the diamond is at (0, 0, PALLET_W) →
    // ox - PALLET_W * ISO_COS30 * s, so ox = LABEL_PAD_LEFT + that.
    const ox = LABEL_PAD_LEFT + PALLET_W * ISO_COS30 * s;
    const oy = stackH * s + LABEL_PAD_TOP; // top-right badge sits above

    // Draw pallet deck — only in pallet-load mode. Loose load skips
    // the wood deck entirely so the viz shows cargo sitting directly
    // on the floor (matching the real-world floor-load geometry).
    if (palletDeckCm > 0) {
      drawIsoBox(ctx, 0, 0, 0, PALLET_L, palletDeckCm, PALLET_W, s, ox, oy, '#a8a8a8');
    }

    // Draw boxes back-to-front: diag 0 (back corner) → max (front corner)
    // Each cell occupies layout.bL × layout.bW (including the divider
    // pad); the actual drawn box is the cell minus pad on each axis,
    // which leaves a 0.4 cm gap between adjacent items.
    const drawL = layout.bL - padCm;
    const drawW = layout.bW - padCm;
    // Center the box pattern on the pallet base — when the items don't
    // fully cover the 40 × 48 footprint (e.g. 3 × 3 of 22 cm products
    // leaves margin on every side), evenly split the leftover space so
    // the stack sits centered instead of jammed into the back corner.
    const occupiedL = layout.cols * layout.bL;
    const occupiedW = layout.rows * layout.bW;
    const offsetX = Math.max(0, (PALLET_L - occupiedL) / 2);
    const offsetZ = Math.max(0, (PALLET_W - occupiedW) / 2);
    for (let layer = 0; layer < showLayers; layer++) {
      for (let diag = 0; diag <= layout.cols + layout.rows - 2; diag++) {
        for (let col = Math.max(0, diag - layout.rows + 1); col <= Math.min(diag, layout.cols - 1); col++) {
          const row = diag - col;
          drawIsoBox(ctx,
            offsetX + col * layout.bL, palletDeckCm + layer * stackPitchH, offsetZ + row * layout.bW,
            drawL, bH, drawW, s, ox, oy, '#E8751A');
        }
      }
    }

    // ── Dimension labels (L / W / H) — match the product overview
    // SVG viz style: bracket bars sit OUTSIDE the silhouette with end
    // ticks, labels read horizontally past the bar. Pull all vertices
    // into screen space so we can find the outward perpendicular for
    // each face automatically (works regardless of stack height).
    const totalH_cm = palletDeckCm + showLayers * stackPitchH;
    const v3 = {
      bbl: isoProj(0,        0,         0,        s, ox, oy),
      bbr: isoProj(PALLET_L, 0,         0,        s, ox, oy),
      bfl: isoProj(0,        0,         PALLET_W, s, ox, oy),
      bfr: isoProj(PALLET_L, 0,         PALLET_W, s, ox, oy),
      tbl: isoProj(0,        totalH_cm, 0,        s, ox, oy),
      tbr: isoProj(PALLET_L, totalH_cm, 0,        s, ox, oy),
      tfl: isoProj(0,        totalH_cm, PALLET_W, s, ox, oy),
      tfr: isoProj(PALLET_L, totalH_cm, PALLET_W, s, ox, oy)
    };
    const allPts = Object.values(v3);
    const cxBox = allPts.reduce((sum,p) => sum + p.x, 0) / allPts.length;
    const cyBox = allPts.reduce((sum,p) => sum + p.y, 0) / allPts.length;
    const sxMin = Math.min(...allPts.map(p => p.x));
    // Pick the perpendicular pointing AWAY from the box centroid.
    const outwardPerp = (a, b) => {
      const dx = b.x - a.x, dy = b.y - a.y;
      const len = Math.sqrt(dx*dx + dy*dy) || 1;
      const px = -dy/len, py = dx/len;
      const midX = (a.x + b.x)/2, midY = (a.y + b.y)/2;
      const dot = px*(midX - cxBox) + py*(midY - cyBox);
      return dot >= 0 ? { x: px, y: py } : { x: -px, y: -py };
    };
    const TICK = 4;
    const dimColor = '#6b7280';
    ctx.fillStyle = dimColor;
    ctx.strokeStyle = dimColor;
    ctx.lineWidth = 1;
    const drawDim = (a, b, labelPos, txt, anchor='center') => {
      // Bar
      ctx.beginPath();
      ctx.moveTo(a.x, a.y);
      ctx.lineTo(b.x, b.y);
      ctx.stroke();
      // End ticks (perpendicular to a→b)
      const dx = b.x - a.x, dy = b.y - a.y;
      const len = Math.sqrt(dx*dx + dy*dy) || 1;
      const tpx = -dy/len * TICK, tpy = dx/len * TICK;
      ctx.beginPath();
      ctx.moveTo(a.x - tpx, a.y - tpy); ctx.lineTo(a.x + tpx, a.y + tpy);
      ctx.moveTo(b.x - tpx, b.y - tpy); ctx.lineTo(b.x + tpx, b.y + tpy);
      ctx.stroke();
      // Label
      ctx.textAlign = anchor;
      ctx.textBaseline = 'middle';
      ctx.fillText(txt, labelPos.x, labelPos.y);
    };
    ctx.lineWidth = 1.4;
    ctx.font = `700 16px -apple-system, BlinkMacSystemFont, sans-serif`;
    const inSize = (cm) => `${(cm / 2.54).toFixed(0)}"`;
    const cmSize = (cm) => `${cm.toFixed(1)} cm`;

    // L bracket — front-left edge bbl(top of diamond) → bfl is W;
    // L runs along bfl(left)→bfr(bottom): the front-left-bottom edge.
    // Match the product viz: place bracket outside this edge. Label
    // gap sized so the 16px text clears the bracket bar AND L stays
    // separate from W at the shared bottom corner.
    {
      const lOff = 16, lLabelGap = 42;
      const a0 = v3.bfl, b0 = v3.bfr;
      const p = outwardPerp(a0, b0);
      const a = { x: a0.x + p.x*lOff, y: a0.y + p.y*lOff };
      const b = { x: b0.x + p.x*lOff, y: b0.y + p.y*lOff };
      const mid = { x: (a.x + b.x)/2 + p.x*lLabelGap, y: (a.y + b.y)/2 + p.y*lLabelGap };
      drawDim(a, b, mid, `L ${inSize(PALLET_L)} (${cmSize(PALLET_L)})`);
    }
    // W bracket — front-right-bottom edge bfr→bbr.
    {
      const wOff = 16, wLabelGap = 42;
      const a0 = v3.bfr, b0 = v3.bbr;
      const p = outwardPerp(a0, b0);
      const a = { x: a0.x + p.x*wOff, y: a0.y + p.y*wOff };
      const b = { x: b0.x + p.x*wOff, y: b0.y + p.y*wOff };
      const mid = { x: (a.x + b.x)/2 + p.x*wLabelGap, y: (a.y + b.y)/2 + p.y*wLabelGap };
      drawDim(a, b, mid, `W ${inSize(PALLET_W)} (${cmSize(PALLET_W)})`);
    }
    // H bracket — vertical, OUTSIDE the leftmost silhouette point
    // (sxMin), running from top of stack to base. Label sits to the
    // LEFT of the bar, right-anchored.
    {
      const hX = sxMin - 26;
      const a = { x: hX, y: v3.tfl.y };
      const b = { x: hX, y: v3.bfl.y };
      drawDim(a, b, { x: hX - 12, y: (a.y + b.y)/2 }, `H ${inSize(totalH_cm)} (${cmSize(totalH_cm)})`, 'right');
    }
    // Pallet "40 × 48 in" badge — anchored top-right corner of the
    // canvas so it never overlaps the L bracket below the silhouette.
    ctx.fillStyle = '#6b7280';
    ctx.font = `700 12px -apple-system, sans-serif`;
    ctx.textAlign = 'right';
    ctx.textBaseline = 'top';
    ctx.fillText('40 × 48 in pallet', CW - 12, 10);

    // Surface use measures product/carton area only (excludes the
    // divider gap so 100% means the items themselves cover the pallet).
    const surfaceUse = Math.round((layout.cols * drawL * layout.rows * drawW) / (PALLET_L * PALLET_W) * 100);
    // totalPerPallet always means "items (products in manual mode /
    // outer cartons in carton mode / cases in case-only mode) per pallet"
    const totalPerPallet = perLayer * maxLayers;
    const unitWord  = caseOn ? 'case'  : (manualOn ? 'unit'  : 'outer carton');
    const unitWordP = caseOn ? 'cases' : (manualOn ? 'units' : 'outer cartons');

    // "Total Units to Ship" — routed through the canonical helper so
    // case-only auto-derive (products/case × cases/order, with Top-Off
    // bumping the pallet-total input above the base) stays in sync
    // with every other consumer (Hypothetical Scenarios, Fill button,
    // freight calc).
    const totalUnits = _msEffectiveTotalUnits();
    // Loose top-off count (in PRODUCTS) — stashed by "↻ Top Off" so the
    // last container's leftover CBM gets blue cardboard boxes in the
    // viz. The loose units must be SUBTRACTED before computing
    // palletsNeeded, otherwise the totalUnits = palletized + loose lump
    // forces an extra container and the "Fill" button bumps the qty
    // every click. Tap an empty/0 dataset → palletizedUnits = totalUnits.
    const _looseTopOffStr  = document.getElementById('pallet-total-cartons')?.dataset.looseTopOff || '';
    const _looseTopOffNum  = parseInt(_looseTopOffStr) || 0;
    const palletizedUnits  = Math.max(0, totalUnits - _looseTopOffNum);
    // Carton-driven product counts only apply in default carton mode.
    // Case Only Override treats each case AS the ship unit (so the
    // "products per outer carton" concept doesn't apply — instead
    // products-per-case + cases-per-order drive the totals).
    const innerQtyVal  = (manualOn || caseOn) ? 0 : (parseInt(document.getElementById('carton-inner-count').value) || 0);
    const outerQtyVal  = (manualOn || caseOn) ? 0 : (parseInt(document.getElementById('carton-outer-count').value) || 0);
    // productsPerOuter here is BOTH the math conversion and the
    // display gate (stats render only when this is > 0). Manual mode
    // intentionally returns 0 so the carton-specific stats hide.
    // Don't route through _msProductsPerShipItem() — it returns 1 in
    // manual mode (correct for math elsewhere, wrong for the gate
    // here).
    const productsPerOuter = caseOn
      ? _msIntFromInput(document.getElementById('case-only-products-per'))
      : ((innerQtyVal > 0 && outerQtyVal > 0) ? innerQtyVal * outerQtyVal : 0);
    // In manual mode, items-on-pallet = products. In case-only or
    // carton mode, items-on-pallet = cases / outer cartons, derived
    // from units / products-per-ship-unit. Use the PALLETIZED count so
    // the loose top-off doesn't get billed as palletized.
    const totalCartons = manualOn
      ? palletizedUnits
      : (productsPerOuter > 0 ? Math.ceil(palletizedUnits / productsPerOuter) : 0);
    const totalInners  = (totalCartons > 0 && outerQtyVal > 0) ? totalCartons * outerQtyVal : 0;
    const totalProducts = totalUnits;
    // Pallets needed = items-on-pallet ÷ items-per-pallet (round up)
    const palletsNeeded = (totalCartons > 0 && totalPerPallet > 0)
      ? Math.ceil(totalCartons / totalPerPallet)
      : null;
    // RFQ grand qty (kept for legacy callers / display logic)
    const rfqGrandQty = (typeof _lastRfqPriceSummary !== 'undefined' && _lastRfqPriceSummary && _lastRfqPriceSummary.grandQty) || 0;

    // Per-unit weight: in manual mode this is the product weight,
    // in case-only mode the case weight, otherwise the outer-carton
    // weight. Used to surface weight/pallet so the operator can
    // sanity-check pallets against truck/container weight limits
    // without leaving the page.
    const unitWeightKg = caseOn
      ? (parseFloat(document.getElementById('case-only-weight-kg').value) || 0)
      : (manualOn
        ? (parseFloat(document.getElementById('dim-weight-kg').value) || 0)
        : (parseFloat(document.getElementById('carton-outer-weight').value) || 0));
    // Divider material weight — when the 4 mm divider option is on,
    // approximate the cardboard / foam separator weight added per
    // pallet so the shipment weight stays honest. Model:
    //   • Horizontal sheets — one full pallet sheet between each layer
    //     + one beneath the bottom layer = `maxLayers` sheets per pallet
    //   • Vertical sheets — between adjacent items on each layer:
    //     (cols-1) sheets running across the pallet width × layer
    //     height + (rows-1) sheets running across the pallet length ×
    //     layer height, repeated across all layers
    //   • Sheet weight ≈ 0.8 kg/m² (typical 4 mm double-wall corrugated
    //     cardboard at ~800 g/m²; foam separators run lighter so this
    //     is a conservative estimate).
    const PALLET_AREA_M2 = (PALLET_L * PALLET_W) / 10000; // cm² → m²
    const DIVIDER_KG_PER_M2 = 0.8;
    let dividerWeightPerPalletKg = 0;
    if (dividerOn) {
      // Horizontal layer sheets
      const horizontalArea_m2 = maxLayers * PALLET_AREA_M2;
      // Vertical between-item sheets (per layer): (cols-1) × W × bH
      // running rows-direction + (rows-1) × L × bH running cols-direction.
      const verticalAreaPerLayer_cm2 = Math.max(0, layout.cols - 1) * PALLET_W * bH +
                                       Math.max(0, layout.rows - 1) * PALLET_L * bH;
      const verticalArea_m2 = (maxLayers * verticalAreaPerLayer_cm2) / 10000;
      dividerWeightPerPalletKg = (horizontalArea_m2 + verticalArea_m2) * DIVIDER_KG_PER_M2;
    }
    // Standard wood pallet tare weight ≈ 45 lb (≈ 20.41 kg). Dropped
    // out of every total when the operator has picked Loose Load on
    // the Pallet View card — the cargo floor-loads straight onto the
    // container, no pallet underneath. _looseLoad is resolved at the
    // top of the function (hoisted) so this stays a one-line check.
    const PALLET_TARE_LB = _looseLoad ? 0 : 45;
    const PALLET_TARE_KG = PALLET_TARE_LB * 0.453592; // ≈ 20.41 (0 when loose)
    const palletWeightKg = unitWeightKg > 0
      ? (unitWeightKg * totalPerPallet) + dividerWeightPerPalletKg + PALLET_TARE_KG
      : 0;
    const fmtWt = (kg) => {
      if (!kg || kg <= 0) return '—';
      const lbs = kg * KG_TO_LBS;
      return kg < 10
        ? `${kg.toFixed(2)} kg <span style="color:var(--text-muted); font-weight:500;">/ ${lbs.toFixed(2)} lb</span>`
        : `${kg.toLocaleString('en-US', {maximumFractionDigits:1})} kg <span style="color:var(--text-muted); font-weight:500;">/ ${lbs.toLocaleString('en-US', {maximumFractionDigits:1})} lb</span>`;
    };

    // ── Optimization Tip — Maximize 40' HC capacity ─────────────────
    // When the current pallet is too tall for 2-pallet vertical
    // stacking inside an 8'10" container interior, surface a concrete
    // recommendation: the new max height, the new pallets/units per
    // container, and the leftover CBM / loose-load capacity after
    // fully filling the optimized container with palletized goods.
    let optimizationTipHTML = '';
    {
      const HC_INTERIOR_H = 269;            // cm (8'10")
      const HC_INTERIOR_L = 1203;           // cm
      const HC_INTERIOR_W_CM = 235;         // cm
      const HC_USABLE_CBM_FULL = 67;        // m³ usable cargo allowance
      // Pallets per container floor — try both pallet orientations.
      const palletsPerLayerInContainer = Math.max(
        Math.floor(HC_INTERIOR_L / PALLET_L) * Math.floor(HC_INTERIOR_W_CM / PALLET_W),
        Math.floor(HC_INTERIOR_L / PALLET_W) * Math.floor(HC_INTERIOR_W_CM / PALLET_L)
      );
      // Current stack height. Pallet mode includes the 15 cm deck;
      // loose-load mode floor-loads so the stack is just cargo.
      const currentPalletStackCm = palletDeckCm + maxLayers * stackPitchH;
      const currentVerticalLayers = Math.max(1, Math.min(2, Math.floor(HC_INTERIOR_H / currentPalletStackCm)));
      // Threshold: max cargo-stack height for 2-pallet vertical stack.
      // Loose-load mode has no deck so the cargo-only allowance grows
      // by the deck's 15 cm × 2 = 30 cm of freed vertical room.
      const maxStackForDoubleCm = (HC_INTERIOR_H - 2 * palletDeckCm) / 2;
      const maxStackForDoubleIn = Math.floor(maxStackForDoubleCm / 2.54);
      const currentMaxHeightIn = parseFloat(document.getElementById('pallet-max-height')?.value) || 60;
      if (currentVerticalLayers === 1 && bH > 0 &&
          currentMaxHeightIn > maxStackForDoubleIn && perLayer > 0) {
        // Recompute with the suggested max height — same divider state.
        const newMaxHeightCm = maxStackForDoubleIn * 2.54;
        const newLayersInPallet = Math.max(1, Math.floor(newMaxHeightCm / stackPitchH));
        const newUnitsPerPallet = perLayer * newLayersInPallet;
        const newPalletsPerContainer = palletsPerLayerInContainer * 2;
        const newUnitsPerContainer = newUnitsPerPallet * newPalletsPerContainer;
        const newPalletStackCm = palletDeckCm + newLayersInPallet * stackPitchH;
        const newPalletCbm = (PALLET_L * PALLET_W * newPalletStackCm) / 1_000_000;
        // Container after FULLY loading with 2-stacked pallets
        const fullContainerCbmUsed = newPalletCbm * newPalletsPerContainer;
        const cbmRemainingAfterFull = Math.max(0, HC_USABLE_CBM_FULL - fullContainerCbmUsed);
        // Loose-load (cardboard, no pallet) capacity in the leftover CBM
        const unitCbmM3 = (bL * bW * bH) / 1_000_000;
        const PACK_EFFICIENCY = 0.80;
        const looseFitInRemaining = unitCbmM3 > 0
          ? Math.floor((cbmRemainingAfterFull * PACK_EFFICIENCY) / unitCbmM3)
          : 0;
        // Only surface the tip if the change actually IMPROVES capacity.
        const currentUnitsPerContainer = totalPerPallet * palletsPerLayerInContainer;
        if (newUnitsPerContainer > currentUnitsPerContainer) {
          const fmtCbmShort = (m3) => m3 < 1
            ? `${m3.toFixed(2)} m³`
            : `${m3.toLocaleString('en-US', {maximumFractionDigits:1})} m³`;
          const totalLabelWord = (unitWord === 'units' || unitWord === 'unit') ? 'Units' : 'Outer Cartons';
          // Inline button styling, kept tight so the suggestion card
          // stays compact even with multiple Update affordances.
          const upBtnStyle = `display:inline-flex; align-items:center; gap:4px; padding:3px 9px; font-size:11px; font-weight:700; color:#fff; background:var(--accent); border:none; border-radius:5px; cursor:pointer; white-space:nowrap; margin-left:8px;`;
          const looseTotal = newUnitsPerContainer + looseFitInRemaining;
          optimizationTipHTML = `
            <div style="margin-top:16px; padding:14px; border:1px solid var(--accent); border-radius:8px; background:rgba(232,117,26,0.06);">
              <div style="display:flex; align-items:center; gap:6px; margin-bottom:10px;">
                <span style="font-size:14px;">💡</span>
                <span style="font-size:10px; font-weight:700; text-transform:uppercase; letter-spacing:0.06em; color:var(--accent);">Optimization Tip — Maximize 40' HC Container</span>
              </div>
              <div style="font-size:13px; color:var(--text); line-height:1.55;">
                Reduce <strong>Max Height</strong> from <strong>${currentMaxHeightIn}"</strong> to <strong>${maxStackForDoubleIn}"</strong> per pallet so two pallets stack vertically inside the 8'10" container.
                <button type="button" style="${upBtnStyle}" onclick="applyMaxHeightSuggestion(${maxStackForDoubleIn})" title="Set Max Height to ${maxStackForDoubleIn}&quot;">↻ Update Max Height</button>
              </div>
              <div style="margin-top:10px; padding:10px 12px; background:rgba(232,117,26,0.08); border-radius:6px; font-size:12px; line-height:1.7;">
                <div>→ <strong style="color:var(--accent);">${newPalletsPerContainer}</strong> pallets per container <span style="color:var(--text-muted);">(was ${palletsPerLayerInContainer})</span></div>
                <div>→ <strong style="color:var(--accent);">${newUnitsPerPallet.toLocaleString()}</strong> ${unitWordP} per pallet <span style="color:var(--text-muted);">(was ${totalPerPallet.toLocaleString()})</span></div>
                <div>→ <strong style="color:var(--accent);">${newUnitsPerContainer.toLocaleString()}</strong> ${unitWordP} per fully-loaded container</div>
              </div>
              ${looseFitInRemaining > 0 ? `
              <div style="margin-top:10px; font-size:12px; color:var(--text); line-height:1.55;">
                After fully loading with pallets, you'd still have
                <strong style="color:var(--accent);">${fmtCbmShort(cbmRemainingAfterFull)}</strong>
                of CBM left — enough to top off with up to
                <strong style="color:var(--accent);">~${looseFitInRemaining.toLocaleString()}</strong>
                more loose ${unitWordP} (cardboard, no pallet, 80% packing efficiency).
              </div>` : ''}
              <div style="margin-top:12px; padding-top:10px; border-top:1px dashed var(--border); font-size:12px; color:var(--text); line-height:1.6;">
                <div style="display:flex; align-items:center; flex-wrap:wrap; gap:6px;">
                  <span>↳ Fill 1 container with pallets:</span>
                  <strong>${newUnitsPerContainer.toLocaleString()}</strong>
                  <span style="color:var(--text-muted);">${unitWordP}</span>
                  <button type="button" style="${upBtnStyle}" onclick="applyTotalUnitsSuggestion(${newUnitsPerContainer})" title="Set Total Units to Ship to ${newUnitsPerContainer.toLocaleString()}">↻ Update Units</button>
                </div>
                ${looseFitInRemaining > 0 ? `
                <div style="display:flex; align-items:center; flex-wrap:wrap; gap:6px; margin-top:6px;">
                  <span>↳ Fill 1 container w/ loose top-off:</span>
                  <strong>${looseTotal.toLocaleString()}</strong>
                  <span style="color:var(--text-muted);">${unitWordP}</span>
                  <button type="button" style="${upBtnStyle}" onclick="applyTotalUnitsSuggestion(${looseTotal}, ${looseFitInRemaining * (manualOn ? 1 : ((parseInt(document.getElementById('carton-inner-count')?.value)||0) * (parseInt(document.getElementById('carton-outer-count')?.value)||0) || 1))})" title="Set Total Units to ${looseTotal.toLocaleString()} — pallets + loose top-off in blue">↻ Update Units</button>
                </div>` : ''}
              </div>
            </div>`;
        }
      }
    }

    document.getElementById('pallet-stats').innerHTML = `
      <div style="display:grid; grid-template-columns:1fr 1fr; gap:16px;">
        <div><div style="font-size:22px; font-weight:700; color:var(--text);">${perLayer}</div><div style="font-size:11px; color:var(--text-muted); margin-top:2px;">${unitWordP} / layer</div></div>
        <div><div style="font-size:22px; font-weight:700; color:var(--text);">${maxLayers}</div><div style="font-size:11px; color:var(--text-muted); margin-top:2px;">max layers</div></div>
        <div><div style="font-size:22px; font-weight:700; color:var(--text);">${totalPerPallet}</div><div style="font-size:11px; color:var(--text-muted); margin-top:2px;">${unitWordP} / pallet</div></div>
        <div><div style="font-size:22px; font-weight:700; color:var(--text);">${surfaceUse}%</div><div style="font-size:11px; color:var(--text-muted); margin-top:2px;">surface coverage</div></div>
        ${unitWeightKg > 0 ? `
        <div><div style="font-size:18px; font-weight:700; color:var(--text); line-height:1.25;">${fmtWt(unitWeightKg)}</div><div style="font-size:11px; color:var(--text-muted); margin-top:2px;">weight / ${unitWord}</div></div>
        <div>
          <div style="font-size:18px; font-weight:700; color:var(--text); line-height:1.25;">${fmtWt(palletWeightKg)}</div>
          <div style="font-size:11px; color:var(--text-muted); margin-top:2px;">weight / pallet${dividerOn ? ` <span style="opacity:0.75;">(incl. ${fmtWt(dividerWeightPerPalletKg)} dividers)</span>` : ''}</div>
          <div style="font-size:11px; color:var(--text-muted); margin-top:6px; line-height:1.4; opacity:0.85;">
            &nbsp;↳ pallet alone: <strong>${fmtWt(PALLET_TARE_KG)}</strong> <span style="opacity:0.7;">(45 lb)</span>
          </div>
        </div>` : `
        <div style="grid-column:span 2; font-size:11px; color:var(--text-muted); padding:6px 0; line-height:1.5;">
          Enter ${caseOn ? 'case' : (manualOn ? 'product' : 'outer carton')} weight in the ${caseOn ? 'Case Only Override block' : 'dimensions section'} to see weight per ${unitWord} and per pallet.
        </div>`}
        ${productsPerOuter > 0 ? `
        ${caseOn
          ? `<div style="grid-column:span 2;"><div style="font-size:22px; font-weight:700; color:var(--text);">${productsPerOuter.toLocaleString()}</div><div style="font-size:11px; color:var(--text-muted); margin-top:2px;">products / case</div></div>`
          : `<div><div style="font-size:22px; font-weight:700; color:var(--text);">${outerQtyVal}</div><div style="font-size:11px; color:var(--text-muted); margin-top:2px;">inner cartons / outer</div></div>
             <div><div style="font-size:22px; font-weight:700; color:var(--text);">${productsPerOuter}</div><div style="font-size:11px; color:var(--text-muted); margin-top:2px;">products / outer carton</div></div>`}` : ''}
      </div>
      ${totalUnits > 0 ? `
      <div style="margin-top:16px; padding-top:14px; border-top:1px solid var(--border);">
        <div style="font-size:11px; font-weight:700; text-transform:uppercase; letter-spacing:0.06em; color:var(--text-muted); margin-bottom:10px;">Shipment of ${totalUnits.toLocaleString()} units</div>
        <div style="display:grid; grid-template-columns:1fr 1fr; gap:12px;">
          ${!manualOn && totalCartons > 0 ? `<div style="grid-column:span 2;"><div style="font-size:18px; font-weight:700; color:var(--text);">${totalCartons.toLocaleString()} <span style="font-size:11px; font-weight:500; color:var(--text-muted);">${unitWordP}</span></div><div style="font-size:11px; color:var(--text-muted); margin-top:2px;">${productsPerOuter > 0 ? `${productsPerOuter} products / ${unitWord}` : ''}</div></div>` : ''}
          <div><div style="font-size:22px; font-weight:700; color:var(--accent);">${palletsNeeded || 0}</div><div style="font-size:11px; color:var(--text-muted); margin-top:2px;">pallets needed</div></div>
          ${unitWeightKg > 0 ? `<div>
            <div style="font-size:18px; font-weight:700; color:var(--text); line-height:1.25;">${fmtWt(unitWeightKg * totalCartons + dividerWeightPerPalletKg * (palletsNeeded || 0) + PALLET_TARE_KG * (palletsNeeded || 0))}</div>
            <div style="font-size:11px; color:var(--text-muted); margin-top:2px;">total shipment weight${dividerOn ? ' <span style=\"opacity:0.7;\">(incl. dividers)</span>' : ''}</div>
            <div style="font-size:11px; color:var(--text-muted); margin-top:6px; line-height:1.4; opacity:0.85;">
              &nbsp;↳ pallets alone: <strong>${fmtWt(PALLET_TARE_KG * (palletsNeeded || 0))}</strong>
              <span style="opacity:0.7;">(${(palletsNeeded || 0).toLocaleString()} × 45 lb)</span>
            </div>
          </div>` : (totalInners > 0 ? `<div><div style="font-size:22px; font-weight:700; color:var(--text);">${totalInners}</div><div style="font-size:11px; color:var(--text-muted); margin-top:2px;">total inner cartons</div></div>` : '<div></div>')}
          ${totalProducts > 0 ? `<div style="grid-column:span 2;">
            <div style="font-size:22px; font-weight:700; color:var(--text);">${totalProducts.toLocaleString()}</div>
            <div style="font-size:11px; color:var(--text-muted); margin-top:2px;">total products</div>
            ${(() => {
              // Sub-text: how many OUTER CARTONS that many products
              // would fill at the current outer carton arrangement.
              // Only meaningful when an outer arrangement is set
              // (productsPerOuter > 0). Uses the OUTER CARTON dims so
              // the operator can sanity-check carton count + size at
              // a glance, even when in manual mode.
              // In case-only mode the ship unit is the case (its dims
              // come from the Case Only block), so read those instead of
              // the outer carton fields (which are grayed out + empty).
              const dimL = caseOn
                ? parseFloat(document.getElementById('case-only-l-cm')?.value)
                : parseFloat(document.getElementById('carton-outer-l-cm')?.value);
              const dimW = caseOn
                ? parseFloat(document.getElementById('case-only-w-cm')?.value)
                : parseFloat(document.getElementById('carton-outer-w-cm')?.value);
              const dimH = caseOn
                ? parseFloat(document.getElementById('case-only-h-cm')?.value)
                : parseFloat(document.getElementById('carton-outer-h-cm')?.value);
              if (productsPerOuter > 0) {
                const cartonsNeeded = Math.ceil(totalProducts / productsPerOuter);
                const dimStr = (dimL && dimW && dimH)
                  ? ` at <strong>${dimL.toFixed(1)} × ${dimW.toFixed(1)} × ${dimH.toFixed(1)} cm</strong>`
                  : '';
                const noun = caseOn ? 'case' : 'outer carton';
                const perSuffix = caseOn ? '/ case' : '/ outer';
                return `<div style="font-size:11px; color:var(--text-muted); margin-top:6px; line-height:1.4; opacity:0.85;">
                  &nbsp;↳ fills <strong>${cartonsNeeded.toLocaleString()}</strong> ${noun}${cartonsNeeded === 1 ? '' : 's'}${dimStr}
                  <span style="opacity:0.7;">(${productsPerOuter.toLocaleString()} ${perSuffix})</span>
                </div>`;
              }
              return '';
            })()}
          </div>` : ''}
        </div>
      </div>` : ''}
      <div style="margin-top:14px; font-size:11px; color:var(--text-muted); padding-top:12px; border-top:1px solid var(--border);">
        ${caseOn ? 'Case' : (manualOn ? 'Product' : 'Box')} orientation: ${drawL.toFixed(1)} × ${drawW.toFixed(1)} cm &nbsp;·&nbsp; ${layout.cols} × ${layout.rows} per layer${dividerOn ? ` &nbsp;·&nbsp; <span style="color:var(--accent); font-weight:600;">+ 4 mm dividers</span>` : ''}${manualOn ? '<br><span style="color:var(--accent); font-weight:600;">Manual mode — fitting products directly on pallet base.</span>' : ''}${caseOn ? '<br><span style="color:var(--accent); font-weight:600;">Case Only Override — fitting cases directly on pallet base.</span>' : ''}
      </div>
      ${optimizationTipHTML}`;

    // Store pallet stats globally so shipping tab can read them
    window._palletStats = { perLayer, maxLayers, totalPerPallet, surfaceUse, outerQtyVal, productsPerOuter, totalCartons, palletsNeeded, totalInners, totalProducts };
    // Keep the collapsed Pallet section header summary in sync
    if (typeof _updateSectionSummary === 'function') _updateSectionSummary('pallet');

    // Inline summary in the Outer Carton column header
    const inlineEl = document.getElementById('pallet-inline-stats');
    if (inlineEl) {
      inlineEl.style.display = '';
      const palletPart = palletsNeeded !== null ? ` &nbsp;·&nbsp; <strong style="color:var(--accent);">${palletsNeeded} pallets</strong>` : '';
      inlineEl.innerHTML = `<span style="opacity:0.75;">Pallet:</span> <strong>${perLayer}</strong> / layer &nbsp;·&nbsp; <strong>${totalPerPallet}</strong> / pallet${palletPart}`;
    }

    // Refresh shipping tab dims/freight + pallet stats. The shipping
    // tab pulls its dims/weight from PRODUCT in manual mode and
    // OUTER CARTON otherwise (see _shipUnit) — calling these here
    // keeps the shipping tab in sync the moment the operator toggles
    // manual mode, edits product/carton dims, or changes the unit
    // count, without waiting for the tab to be reopened.
    syncShippingPalletStats();
    if (typeof syncShippingDims === 'function') syncShippingDims();
    if (typeof calcFreight === 'function') calcFreight();

    // Refresh the 40' HC container preview using the just-computed
    // pallet stack height + per-pallet weight + units-per-pallet +
    // per-unit volume + per-unit weight so the side stats panel can
    // render Total Weight, Total Volume, "+N more units palletized"
    // and "+N more loose units (in cardboard boxes)" accurately.
    const unitCbmM3 = (bL * bW * bH) / 1_000_000; // cm³ → m³
    if (typeof renderContainerViz === 'function') {
      renderContainerViz(
        palletsNeeded || 0, totalH_cm, drawL, drawW, layout.cols, layout.rows, padCm,
        palletWeightKg, totalPerPallet, unitWordP,
        unitCbmM3, unitWeightKg
      );
    }

    // ── Pallet Fit Suggestion ────────────────────────────────────────
    // Surface a one-click "use these dims instead" panel under the 3D
    // pallet viz when the outer-carton footprint wastes pallet space,
    // overhangs the 40 × 48 base, or could trim height for an extra
    // layer. Per spec the suggestion ONLY runs when an outer carton
    // L / W / H is filled in — manual-mode product dims don't trigger
    // it, and a partially-filled outer carton column suppresses it.
    if (typeof _renderPalletFitSuggestion === 'function') {
      const oL = parseFloat(document.getElementById('carton-outer-l-cm')?.value);
      const oW = parseFloat(document.getElementById('carton-outer-w-cm')?.value);
      const oH = parseFloat(document.getElementById('carton-outer-h-cm')?.value);
      if (oL > 0 && oW > 0 && oH > 0) {
        // Always size the suggestion against the OUTER CARTON, even in
        // manual mode (the user explicitly asked for outer-carton fit
        // tips, not product fit tips). Re-derive perLayer / maxLayers
        // from the outer carton dims since the live `bL/bW/bH` may be
        // product dims in manual mode.
        const oLayout    = bestPalletOrientation(oL + 0, oW + 0);
        const oPerLayer  = (oLayout.cols || 0) * (oLayout.rows || 0);
        const oMaxLayers = Math.max(1, Math.floor(maxLoadH / (oH || 1)));
        const oTotalPerPallet = oPerLayer * oMaxLayers;
        _renderPalletFitSuggestion(oL, oW, oH, 0, maxLoadH, false,
                                   oPerLayer, oMaxLayers, oTotalPerPallet);
      } else {
        const sugHost = document.getElementById('pallet-fit-suggestion');
        if (sugHost) { sugHost.style.display = 'none'; sugHost.innerHTML = ''; }
      }
    }
  }

  // ── Pallet fit optimiser ─────────────────────────────────────────────
  // Searches a small grid of (cols × rows) arrangements that fit
  // perfectly on the 40 × 48 in pallet base, finds the one with the
  // highest items-per-pallet that stays within ±30% of the current
  // L / W (so the operator isn't asked to redesign the box around a
  // 5 cm cube). Also probes a "shave the height" option that adds one
  // more layer without changing the footprint. Renders into
  // #pallet-fit-suggestion. Hides the panel when the current dims are
  // already the best we can find.
  function _palletFitSearch(curL, curW, curH, padCm, maxLoadH) {
    if (!curL || !curW || !curH) return null;
    const PL = 101.6, PW = 121.92;            // 40 × 48 in pallet base, cm
    const MIN_DIM = 5;                        // don't suggest sub-5 cm boxes
    const MAX_DELTA = 0.30;                   // ±30% per axis vs current
    const curLayout = bestPalletOrientation(curL + padCm, curW + padCm);
    const curPerLayer = (curLayout.cols || 0) * (curLayout.rows || 0);
    const curStackPitch = curH + padCm;
    const curMaxLayers = Math.max(1, Math.floor(maxLoadH / curStackPitch));
    const curUpp = curPerLayer * curMaxLayers;
    // Product Dimensions Lock — when on, no outer-carton suggestion may
    // be smaller than the product on any axis (the carton has to
    // contain it). Reads the locked product L/W/H from the workbook
    // inputs; either orientation of (productL/productW) is allowed
    // since the carton can be rotated relative to the product.
    const lockOn = !!document.getElementById('product-dims-lock')?.checked;
    const prodL  = lockOn ? (parseFloat(document.getElementById('dim-cm-l')?.value) || 0) : 0;
    const prodW  = lockOn ? (parseFloat(document.getElementById('dim-cm-w')?.value) || 0) : 0;
    const prodH  = lockOn ? (parseFloat(document.getElementById('dim-cm-h')?.value) || 0) : 0;
    const productFits = (newL, newW, newH) => {
      if (!lockOn) return true;
      if (prodH > 0 && newH < prodH - 0.01) return false;
      // Carton can hold the product in either L↔W orientation.
      const fitA = (prodL <= newL + 0.01) && (prodW <= newW + 0.01);
      const fitB = (prodW <= newL + 0.01) && (prodL <= newW + 0.01);
      return fitA || fitB;
    };
    let best = null;
    const considerFloor = (newL, newW, cols, rows) => {
      if (newL < MIN_DIM || newW < MIN_DIM) return;
      // Floor must actually fit on the pallet (account for floating-
      // point slop from the / cols and / rows divisions by allowing a
      // 1 mm tolerance against the pallet edges).
      if ((newL + padCm) * cols > PL + 0.1) return;
      if ((newW + padCm) * rows > PW + 0.1) return;
      // Lock floor — outer carton must contain the locked product.
      if (!productFits(newL, newW, curH)) return;
      const lDelta = Math.abs(newL - curL) / curL;
      const wDelta = Math.abs(newW - curW) / curW;
      if (lDelta > MAX_DELTA || wDelta > MAX_DELTA) return;
      const perLayer = cols * rows;
      const upp = perLayer * curMaxLayers;
      const score = upp;
      const closeness = -(lDelta + wDelta);
      if (!best || score > best.score ||
          (score === best.score && closeness > best.closeness)) {
        best = { kind: 'floor', newL, newW, newH: curH, cols, rows,
                 perLayer, layers: curMaxLayers, upp, score, closeness };
      }
    };
    for (let cols = 1; cols <= 10; cols++) {
      for (let rows = 1; rows <= 10; rows++) {
        // Two pallet orientations — boxes lay along L × W or rotated.
        const aL = PL / cols - padCm, aW = PW / rows - padCm;
        const bL = PW / cols - padCm, bW = PL / rows - padCm;
        considerFloor(aL, aW, cols, rows);
        considerFloor(bL, bW, cols, rows);
      }
    }
    // Height probe — keep current floor, shave H so one more layer fits.
    const newLayersTarget = curMaxLayers + 1;
    const newPitch = maxLoadH / newLayersTarget;
    const newH = newPitch - padCm;
    // Skip the height-shave branch if locked product H wouldn't fit
    // inside the proposed shorter carton.
    if (newH >= MIN_DIM && newH < curH && productFits(curL, curW, newH)) {
      const heightDelta = (curH - newH) / curH;
      if (heightDelta <= MAX_DELTA) {
        const upp = curPerLayer * newLayersTarget;
        if (!best || upp > best.upp) {
          best = { kind: 'height', newL: curL, newW: curW, newH,
                   cols: curLayout.cols, rows: curLayout.rows,
                   perLayer: curPerLayer, layers: newLayersTarget,
                   upp, score: upp, closeness: -heightDelta };
        }
      }
    }
    if (!best) return null;
    if (best.upp <= curUpp) return null;        // no improvement
    return { ...best, curUpp, curPerLayer, curMaxLayers };
  }

  function _renderPalletFitSuggestion(bL, bW, bH, padCm, maxLoadH, manualOn,
                                      curPerLayer, curMaxLayers, curTotalPerPallet) {
    const host = document.getElementById('pallet-fit-suggestion');
    if (!host) return;
    if (!bL || !bW || !bH) { host.style.display = 'none'; host.innerHTML = ''; return; }
    const sug = _palletFitSearch(bL, bW, bH, padCm, maxLoadH);
    if (!sug) { host.style.display = 'none'; host.innerHTML = ''; return; }
    const target = manualOn ? 'product' : 'outer carton';
    const ppGain = sug.upp - sug.curUpp;
    const ppGainPct = sug.curUpp > 0 ? Math.round((ppGain / sug.curUpp) * 100) : 0;
    const newL = sug.newL.toFixed(1);
    const newW = sug.newW.toFixed(1);
    const newH = sug.newH.toFixed(1);
    const inFmt = (cm) => `${(cm / 2.54).toFixed(1)}"`;
    const headline = sug.kind === 'height'
      ? `Trim height by <strong>${(bH - sug.newH).toFixed(1)} cm</strong> to unlock <strong>${sug.layers - sug.curMaxLayers}</strong> more layer${sug.layers - sug.curMaxLayers === 1 ? '' : 's'} per pallet.`
      : `Resize the ${target} footprint to <strong>${newL} × ${newW} cm</strong> for a near-perfect 40 × 48 fit.`;
    const apply = `applyPalletFitSuggestion(${sug.newL}, ${sug.newW}, ${sug.newH}, ${manualOn ? 'true' : 'false'})`;
    const btnStyle = `display:inline-flex; align-items:center; gap:4px; padding:6px 12px; font-size:12px; font-weight:700; color:#fff; background:var(--accent); border:none; border-radius:6px; cursor:pointer; white-space:nowrap;`;
    host.style.display = '';
    host.innerHTML = `
      <div style="padding:14px; border:1px solid var(--accent); border-radius:8px; background:rgba(232,117,26,0.06);">
        <div style="display:flex; align-items:center; gap:6px; margin-bottom:8px;">
          <span style="font-size:14px;">📦</span>
          <span style="font-size:10px; font-weight:700; text-transform:uppercase; letter-spacing:0.06em; color:var(--accent);">Pallet Fit Suggestion</span>
        </div>
        <div style="font-size:13px; color:var(--text); line-height:1.55; margin-bottom:10px;">
          ${headline}
        </div>
        <div style="padding:10px 12px; background:rgba(232,117,26,0.08); border-radius:6px; font-size:12px; line-height:1.7; margin-bottom:10px;">
          <div>→ <strong style="color:var(--accent);">${sug.cols} × ${sug.rows}</strong> per layer <span style="color:var(--text-muted);">(was ${sug.curPerLayer})</span></div>
          <div>→ <strong style="color:var(--accent);">${sug.layers}</strong> layer${sug.layers === 1 ? '' : 's'} <span style="color:var(--text-muted);">(was ${sug.curMaxLayers})</span></div>
          <div>→ <strong style="color:var(--accent);">${sug.upp.toLocaleString()}</strong> ${target}s per pallet <span style="color:var(--text-muted);">(was ${sug.curUpp.toLocaleString()}, +${ppGain.toLocaleString()} / +${ppGainPct}%)</span></div>
        </div>
        <div style="display:flex; align-items:center; justify-content:space-between; gap:10px; flex-wrap:wrap;">
          <div style="font-size:11px; color:var(--text-muted); line-height:1.5;">
            New ${target} dims: <strong>${newL} × ${newW} × ${newH} cm</strong>
            <span style="opacity:0.7;">(${inFmt(sug.newL)} × ${inFmt(sug.newW)} × ${inFmt(sug.newH)})</span>
          </div>
          <button type="button" style="${btnStyle}" onclick="${apply}" title="Update ${target} dimensions to ${newL} × ${newW} × ${newH} cm">↻ Apply Suggested Dims</button>
        </div>
      </div>
    `;
  }

  // Apply a suggested footprint — flips the relevant L/W/H inputs (in
  // cm + in), clears the row/side/stack arrangement (otherwise it'd
  // re-derive the dims back to whatever the operator had) and triggers
  // every downstream recalc so the pallet stack, container preview,
  // freight, and shipping tab all snap to the new layout.
  function applyPalletFitSuggestion(newL, newW, newH, manualOn) {
    const round2 = (x) => Math.round(x * 100) / 100;
    const setDim = (cmId, inId, valueCm) => {
      const cm = round2(valueCm);
      const inEl = document.getElementById(inId);
      const cmEl = document.getElementById(cmId);
      if (cmEl) cmEl.value = String(cm);
      if (inEl) inEl.value = round2(cm / 2.54).toFixed(2);
    };
    if (manualOn) {
      setDim('dim-cm-l', 'dim-in-l', newL);
      setDim('dim-cm-w', 'dim-in-w', newW);
      setDim('dim-cm-h', 'dim-in-h', newH);
      if (typeof renderBoxViz === 'function') renderBoxViz('product');
    } else {
      // Clear the outer arrangement first so autoCalcCartons doesn't
      // turn around and overwrite our dims from inner × Row/Side/Height.
      ['carton-outer-row', 'carton-outer-side', 'carton-outer-stack'].forEach(id => {
        const el = document.getElementById(id);
        if (el) el.value = '';
      });
      setDim('carton-outer-l-cm', 'carton-outer-l-in', newL);
      setDim('carton-outer-w-cm', 'carton-outer-w-in', newW);
      setDim('carton-outer-h-cm', 'carton-outer-h-in', newH);
      if (typeof renderBoxViz === 'function') renderBoxViz('outer');
      const hint = document.getElementById('outer-arrange-hint');
      if (hint) hint.style.display = 'none';
    }
    if (typeof renderPalletViz === 'function') renderPalletViz();
    if (typeof syncShippingDims === 'function') syncShippingDims();
    if (typeof calcFreight === 'function') calcFreight();
    if (typeof autoSaveWorkbook === 'function' && !_filling) autoSaveWorkbook();
  }

  let convertingDim = false;
  function convertDim(sourceId, targetId, sourceUnit) {
    if (convertingDim) return;
    convertingDim = true;
    const val = parseFloat(document.getElementById(sourceId).value);
    const targetEl = document.getElementById(targetId);
    if (isNaN(val)) {
      targetEl.value = '';
    } else if (sourceUnit === 'in') {
      targetEl.value = (val * 2.54).toFixed(2);
    } else {
      targetEl.value = (val / 2.54).toFixed(2);
    }
    convertingDim = false;
    if (_appReady) autoSaveWorkbook();
  }

  function convertWeight(sourceId, targetId, sourceUnit) {
    if (convertingWeight) return;
    convertingWeight = true;
    const sourceEl = document.getElementById(sourceId);
    const targetEl = document.getElementById(targetId);
    if (sourceUnit === 'kg') {
      const val = parseFloat(sourceEl.value);
      if (isNaN(val)) {
        targetEl.value = '';
      } else {
        const totalLbs = val * KG_TO_LBS;
        const wholeLbs = Math.floor(totalLbs);
        const oz = Math.round((totalLbs - wholeLbs) * 16 * 10) / 10;
        targetEl.value = wholeLbs + ' lbs ' + oz.toFixed(1) + ' oz';
      }
    } else {
      const raw = sourceEl.value.trim();
      const parsed = raw.match(/^(\d+(?:\.\d+)?)\s*lbs?\s*(\d+(?:\.\d+)?)\s*oz/i);
      let totalLbs;
      if (parsed) {
        totalLbs = parseFloat(parsed[1]) + parseFloat(parsed[2]) / 16;
      } else {
        totalLbs = parseFloat(raw);
      }
      if (isNaN(totalLbs)) {
        targetEl.value = '';
      } else {
        targetEl.value = (totalLbs / KG_TO_LBS).toFixed(2);
      }
    }
    convertingWeight = false;
  }

  /* ── Pantone Swatch ────────────────────────────────────────────────────── */
  function syncPantone() {
    // swatch is just a helper; text field is the source of truth
  }

  /* ── RMB ↔ USD Live Exchange Rate ──────────────────────────────────────── */
  let USD_TO_RMB = 7.24; // fallback — replaced immediately by cache or live fetch
  const RATE_TTL = 30 * 60 * 1000; // 30 minutes in ms

  function applyNewRate(rate, source) {
    USD_TO_RMB = rate;
    // Recalc all open RFQ rows
    document.querySelectorAll('#rfq-body tr[id^="rfq-"]').forEach(tr => {
      const rowId = parseInt(tr.id.replace('rfq-', ''));
      if (!isNaN(rowId)) recalcRfqRow(rowId);
    });
    document.querySelectorAll('[id^="rfq-variant-"]').forEach(tr => {
      const rowId = parseInt(tr.id.replace('rfq-variant-', ''));
      if (!isNaN(rowId)) recalcRfqVariantRow(rowId);
    });
    // Update rate indicator in header  (shows: 1 ¥ = $X.XXXX)
    const el = document.getElementById('fx-rate-display');
    if (el) {
      const now = new Date();
      const time = now.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' });
      const cnyToUsd = (1 / rate).toFixed(4);
      el.textContent = `1 ¥ = $${cnyToUsd}`;
      el.title = `CNY → USD rate: $${cnyToUsd} per Yuan (source: ${source}, updated ${time})`;
    }
    // Push the live rate to app_state so server-side recompute paths
    // (commissions backfill, etc.) convert RMB→USD using the same rate
    // the operator sees on screen. Without this the server falls back
    // to a stale 7.24 and the Commissions dashboard underquotes the
    // gross by ~5% on every commission row.
    if (rate > 0 && typeof apiCall === 'function') {
      try {
        apiCall('save_app_state', {
          key: 'fx_usd_cny',
          value: JSON.stringify({ rate, ts: Date.now(), source })
        }).catch(() => {});
      } catch (_) { /* best-effort */ }
    }
  }

  // ── Header currency calculator ───────────────────────────────────────────
  // Up to 4 decimals so small RMB→USD conversions stay precise (¥1 = $0.1462,
  // not $0.15). Big round numbers like $1 = ¥7.24 still render cleanly because
  // we let the trailing zeros drop (min 2, max 4).
  const _fmtCalc  = n => n.toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 4});
  const _parseCalc = s => parseFloat(String(s).replace(/,/g, '')) || 0;

  // Permanently block letters / anything non-numeric from the calc inputs.
  // Covers browser autofill (e.g. "Parker" getting dropped into the field),
  // paste of mixed text, and accidental keystrokes. Keeps digits, a single
  // dot, and commas (commas are re-emitted by the live formatter).
  function _hdrSanitize(el) {
    const before = el.value;
    // Strip everything that isn't a digit, dot, or comma
    let cleaned = before.replace(/[^0-9.,]/g, '');
    // Collapse multiple dots down to the first one (keeps "1.2.3" from sticking)
    const firstDot = cleaned.indexOf('.');
    if (firstDot !== -1) {
      cleaned = cleaned.slice(0, firstDot + 1) + cleaned.slice(firstDot + 1).replace(/\./g, '');
    }
    if (cleaned !== before) {
      // Preserve caret position relative to the number of characters removed
      const cursor = el.selectionStart ?? cleaned.length;
      const removed = before.length - cleaned.length;
      el.value = cleaned;
      const newCursor = Math.max(0, cursor - removed);
      try { el.setSelectionRange(newCursor, newCursor); } catch (e) { /* input may not support selection */ }
    }
  }

  // Format the active input with commas as the user types, preserving cursor position.
  function _hdrLiveFormat(el) {
    _hdrSanitize(el); // scrub letters FIRST (defeats autofill + paste)
    const cursor = el.selectionStart;
    const old    = el.value;
    const raw    = old.replace(/,/g, '');
    if (!raw || raw === '.') return;
    const dot = raw.indexOf('.');
    let fmt;
    if (dot === -1) {
      const n = parseInt(raw, 10);
      if (isNaN(n)) return;
      fmt = n.toLocaleString('en-US');
    } else {
      const n = parseInt(raw.slice(0, dot) || '0', 10);
      if (isNaN(n)) return;
      fmt = n.toLocaleString('en-US') + '.' + raw.slice(dot + 1);
    }
    el.value = fmt;
    const newCursor = Math.max(0, cursor + (fmt.length - old.length));
    el.setSelectionRange(newCursor, newCursor);
  }

  function hdrCalcRmbToUsd() {
    const rmbEl = document.getElementById('hdr-calc-rmb');
    _hdrLiveFormat(rmbEl);
    const rmb   = _parseCalc(rmbEl.value);
    const usdEl = document.getElementById('hdr-calc-usd');
    // Convert + ceil to the cent so the header calc matches every
    // other RMB↔USD conversion in the workbook.
    usdEl.value = rmb > 0 ? _fmtCalc(_fxUsdFromRmb(rmb)) : '';
  }
  function hdrCalcUsdToRmb() {
    const usdEl = document.getElementById('hdr-calc-usd');
    _hdrLiveFormat(usdEl);
    const usd   = _parseCalc(usdEl.value);
    const rmbEl = document.getElementById('hdr-calc-rmb');
    rmbEl.value = usd > 0 ? _fmtCalc(_fxRmbFromUsd(usd)) : '';
  }

  /* ── Dimensions Calculator (header modal) ────────────────────────────
     Free-floating pallet-fit calculator that doesn't touch any
     workbook data. The operator types package L/W/H/weight + picks a
     pallet preset (or Custom), and Calculate fits boxes on the pallet
     base with best-orientation packing. Internal state lives on
     window._dimsCalc so the unit toggle can convert in place. */
  window._dimsCalc = { unit: 'cm' };

  function openDimsCalcModal() {
    const ov = document.getElementById('dims-calc-modal-overlay');
    if (!ov) return;
    ov.classList.add('open');
    ov.style.display = 'flex';
    setTimeout(() => document.getElementById('dc-pkg-l')?.focus(), 50);
  }
  function closeDimsCalcModal() {
    const ov = document.getElementById('dims-calc-modal-overlay');
    if (!ov) return;
    ov.classList.remove('open');
    ov.style.display = 'none';
  }

  function setDimsCalcUnit(unit) {
    const prev = window._dimsCalc.unit;
    if (prev === unit) return;
    window._dimsCalc.unit = unit;
    // Toggle button styles
    const cmBtn = document.getElementById('dc-unit-cm');
    const inBtn = document.getElementById('dc-unit-in');
    if (cmBtn && inBtn) {
      const active = (el) => { el.style.background = 'var(--accent)'; el.style.color = '#fff'; };
      const idle   = (el) => { el.style.background = 'var(--surface2)'; el.style.color = 'var(--text-muted)'; };
      if (unit === 'cm') { active(cmBtn); idle(inBtn); }
      else               { active(inBtn); idle(cmBtn); }
    }
    // Convert existing package dim values in place so the operator
    // doesn't have to retype after switching units.
    const factor = (prev === 'cm' && unit === 'in') ? (1 / 2.54)
                 : (prev === 'in' && unit === 'cm') ? 2.54
                 : 1;
    if (factor !== 1) {
      ['dc-pkg-l', 'dc-pkg-w', 'dc-pkg-h'].forEach(id => {
        const el = document.getElementById(id);
        if (!el) return;
        const v = parseFloat(el.value);
        if (!isNaN(v) && v > 0) el.value = (v * factor).toFixed(2);
      });
    }
    // Update placeholder text on package size hint line — re-render
    // results too so dim labels in the canvas match the new unit.
    if (document.getElementById('dc-results')?.style.display !== 'none') runDimsCalc();
  }

  function onDimsCalcPalletChange() {
    const sel = document.getElementById('dc-pallet-preset');
    const customRow = document.getElementById('dc-custom-pallet-row');
    if (!sel || !customRow) return;
    if (sel.value === 'custom') customRow.style.display = 'grid';
    else customRow.style.display = 'none';
  }

  function _dcResolvePalletCm() {
    const sel = document.getElementById('dc-pallet-preset');
    if (!sel) return null;
    if (sel.value === 'custom') {
      const l = parseFloat(document.getElementById('dc-pallet-l')?.value);
      const w = parseFloat(document.getElementById('dc-pallet-w')?.value);
      if (!l || !w) return null;
      return { l, w, label: 'Custom pallet' };
    }
    const opt = sel.options[sel.selectedIndex];
    const l = parseFloat(opt?.dataset?.l);
    const w = parseFloat(opt?.dataset?.w);
    if (!l || !w) return null;
    return { l, w, label: opt.textContent.trim() };
  }

  function runDimsCalc() {
    const unit = window._dimsCalc.unit;
    const toCm = (v) => unit === 'cm' ? v : v * 2.54;
    const pkgL = toCm(parseFloat(document.getElementById('dc-pkg-l')?.value) || 0);
    const pkgW = toCm(parseFloat(document.getElementById('dc-pkg-w')?.value) || 0);
    const pkgH = toCm(parseFloat(document.getElementById('dc-pkg-h')?.value) || 0);
    const pkgWtKg = parseFloat(document.getElementById('dc-pkg-wt')?.value) || 0;
    const totalQty = parseInt(document.getElementById('dc-pkg-qty')?.value) || 0;
    const loadHIn = parseFloat(document.getElementById('dc-load-height')?.value) || 60;
    const loadH = loadHIn * 2.54;
    const pal = _dcResolvePalletCm();
    const resultsEl = document.getElementById('dc-results');
    const statsEl   = document.getElementById('dc-stats');
    if (!pal || !pkgL || !pkgW || !pkgH) {
      if (resultsEl) resultsEl.style.display = '';
      if (statsEl) statsEl.innerHTML = `<div style="color:var(--text-muted); font-style:italic;">Enter package length, width, height, and pick a pallet to compute.</div>`;
      const c = document.getElementById('dc-canvas');
      if (c) c.getContext('2d').clearRect(0, 0, c.width, c.height);
      return;
    }
    // Best-orientation packing on the pallet base.
    const o1 = { cols: Math.floor(pal.l / pkgL), rows: Math.floor(pal.w / pkgW), bL: pkgL, bW: pkgW };
    const o2 = { cols: Math.floor(pal.l / pkgW), rows: Math.floor(pal.w / pkgL), bL: pkgW, bW: pkgL };
    const layout = (o1.cols * o1.rows >= o2.cols * o2.rows) ? o1 : o2;
    const perLayer = layout.cols * layout.rows;
    const maxLayers = Math.max(1, Math.floor(loadH / pkgH));
    const totalPerPallet = perLayer * maxLayers;
    const palletsNeeded = (totalQty > 0 && totalPerPallet > 0) ? Math.ceil(totalQty / totalPerPallet) : 0;
    const surfaceUse = perLayer > 0
      ? Math.round((layout.cols * layout.bL * layout.rows * layout.bW) / (pal.l * pal.w) * 100)
      : 0;
    // ── Stats panel ─────────────────────────────────────────────────
    const fmtKg = (kg) => kg < 10 ? kg.toFixed(2) : kg.toLocaleString('en-US', {maximumFractionDigits:1});
    const palletWtKg = pkgWtKg > 0 ? pkgWtKg * totalPerPallet : 0;
    const totalWtKg  = totalQty > 0 && pkgWtKg > 0 ? pkgWtKg * totalQty : 0;
    if (statsEl) {
      const fitWarn = perLayer === 0
        ? `<div style="color:#f59e0b; font-weight:600; margin-bottom:8px;">⚠ Package too large — doesn't fit on the ${pal.label}.</div>`
        : '';
      statsEl.innerHTML = `
        ${fitWarn}
        <div style="font-size:11px; font-weight:700; text-transform:uppercase; letter-spacing:0.06em; color:var(--text-muted); margin-bottom:6px;">Per Pallet</div>
        <div style="display:grid; grid-template-columns:1fr 1fr; gap:10px 16px; margin-bottom:12px;">
          <div><div style="font-size:20px; font-weight:700; color:var(--text);">${perLayer}</div><div style="font-size:11px; color:var(--text-muted);">per layer</div></div>
          <div><div style="font-size:20px; font-weight:700; color:var(--text);">${maxLayers}</div><div style="font-size:11px; color:var(--text-muted);">max layers</div></div>
          <div><div style="font-size:20px; font-weight:700; color:var(--accent);">${totalPerPallet.toLocaleString()}</div><div style="font-size:11px; color:var(--text-muted);">items / pallet</div></div>
          <div><div style="font-size:20px; font-weight:700; color:var(--text);">${surfaceUse}%</div><div style="font-size:11px; color:var(--text-muted);">surface use</div></div>
          ${palletWtKg > 0 ? `<div style="grid-column:span 2;"><div style="font-size:14px; font-weight:700; color:var(--text);">${fmtKg(palletWtKg)} kg <span style="font-weight:500; color:var(--text-muted);">/ ${fmtKg(palletWtKg * 2.20462)} lb</span></div><div style="font-size:11px; color:var(--text-muted);">weight per pallet</div></div>` : ''}
        </div>
        ${totalQty > 0 ? `
        <div style="margin-top:6px; padding-top:12px; border-top:1px solid var(--border);">
          <div style="font-size:11px; font-weight:700; text-transform:uppercase; letter-spacing:0.06em; color:var(--text-muted); margin-bottom:6px;">Shipment of ${totalQty.toLocaleString()}</div>
          <div style="display:grid; grid-template-columns:1fr 1fr; gap:10px 16px;">
            <div><div style="font-size:20px; font-weight:700; color:var(--accent);">${palletsNeeded}</div><div style="font-size:11px; color:var(--text-muted);">pallets needed</div></div>
            ${totalWtKg > 0 ? `<div><div style="font-size:14px; font-weight:700; color:var(--text);">${fmtKg(totalWtKg)} kg</div><div style="font-size:11px; color:var(--text-muted);">total weight</div></div>` : '<div></div>'}
          </div>
        </div>` : ''}
        <div style="margin-top:10px; font-size:11px; color:var(--text-muted); line-height:1.5;">
          ${pal.label} · ${pal.l.toFixed(1)} × ${pal.w.toFixed(1)} cm <br>
          Box orientation: ${layout.bL.toFixed(1)} × ${layout.bW.toFixed(1)} cm · ${layout.cols} × ${layout.rows} per layer
        </div>
      `;
    }
    if (resultsEl) resultsEl.style.display = '';
    // ── 3D iso preview ──────────────────────────────────────────────
    if (perLayer > 0) {
      _drawDimsCalcViz({
        palL: pal.l, palW: pal.w, palLabel: pal.label,
        bL: layout.bL, bW: layout.bW, bH: pkgH,
        cols: layout.cols, rows: layout.rows,
        showLayers: Math.min(maxLayers, 10),
        unit
      });
    } else {
      const c = document.getElementById('dc-canvas');
      if (c) {
        const ctx = c.getContext('2d');
        ctx.clearRect(0, 0, c.width, c.height);
        ctx.fillStyle = '#9ca3af';
        ctx.font = `600 13px -apple-system, sans-serif`;
        ctx.textAlign = 'center';
        ctx.fillText(`Package too large for ${pal.label}.`, c.width/2, c.height/2);
      }
    }
    // Cache the latest run for the email export — sent verbatim to
    // api.php so the server-side template doesn't need to recompute.
    window._dimsCalcLastRun = {
      pkgL, pkgW, pkgH, pkgWtKg, totalQty, loadHIn,
      palL: pal.l, palW: pal.w, palLabel: pal.label,
      perLayer, maxLayers, totalPerPallet, palletsNeeded, surfaceUse,
      palletWtKg, totalWtKg, layoutCols: layout.cols, layoutRows: layout.rows,
      boxL: layout.bL, boxW: layout.bW, unit
    };
    // Enable the Email + Download PDF buttons — the report is now
    // meaningful.
    const emailBtn = document.getElementById('dc-email-toggle-btn');
    if (emailBtn) {
      emailBtn.disabled = false;
      emailBtn.style.opacity = '';
      emailBtn.style.color = 'var(--text)';
      emailBtn.title = 'Email this pallet report';
    }
    const pdfBtn = document.getElementById('dc-pdf-btn');
    if (pdfBtn) {
      pdfBtn.disabled = false;
      pdfBtn.style.opacity = '';
      pdfBtn.style.color = 'var(--text)';
      pdfBtn.title = 'Download this pallet report as PDF';
    }
    // Populate the optimization-tips section (dynamic + static).
    if (typeof _renderDimsCalcOptimization === 'function') {
      _renderDimsCalcOptimization(window._dimsCalcLastRun);
    }
    // Render the collapsed Container View — drawn even when collapsed
    // so opening <details> instantly reveals an up-to-date viz.
    if (typeof _drawDimsCalcContainerViz === 'function') {
      _drawDimsCalcContainerViz(window._dimsCalcLastRun);
    }
  }

  // ── Pallet Calc — Optimization & Stacking Suggestions ────────────────
  // Combines run-specific suggestions (e.g. "shave H by 3 cm to unlock
  // an extra layer") with static stacking / container-loading best
  // practices the operator should follow regardless of the input. The
  // server-side email export reuses the exact same HTML so the printed
  // PDF and the emailed report stay identical.
  function _buildPalletCalcSuggestions(r) {
    if (!r) return [];
    // Builds two pools — actionable suggestions (tip/good with an
    // Apply button) and pure facts (info). Suggestions render FIRST so
    // they're impossible to miss. Each suggestion can attach an
    // `action` object { label, fn } that the renderer turns into a
    // real <button>.
    const HC_INT_H = 269, PALLET_DECK = 15;
    const stackTotalCm = PALLET_DECK + r.maxLayers * r.pkgH;
    const fitsDouble   = stackTotalCm <= (HC_INT_H / 2);
    const suggestions = [];   // tip / good — surface FIRST
    const facts       = [];   // info — totals & estimates, render AFTER

    // ── Suggestion: tighter carton footprint ─────────────────────────
    // Search a small grid of cols × rows that divide the pallet evenly
    // and keep the closest-to-current option that beats per-pallet
    // count (within ±30% of the current carton on each axis).
    const MIN_DIM = 5, MAX_DELTA = 0.30;
    const palL = r.palL, palW = r.palW;
    const curUpp = (r.totalPerPallet || 0);
    // Lock toggle — when checked, the engine refuses to propose any
    // option whose footprint is SMALLER than the entered carton on
    // either axis. The supplier can't make the box smaller, so don't
    // bother suggesting it.
    const dimsLocked = !!document.getElementById('dc-lock-dims')?.checked;
    let best = null;
    const consider = (newL, newW, cols, rows) => {
      if (newL < MIN_DIM || newW < MIN_DIM) return;
      if (newL * cols > palL + 0.1) return;
      if (newW * rows > palW + 0.1) return;
      // Lock floor — both axes must be ≥ current dims (small float
      // tolerance so a near-equal candidate isn't rejected for slop).
      if (dimsLocked && (newL < r.pkgL - 0.01 || newW < r.pkgW - 0.01)) return;
      const lDelta = Math.abs(newL - r.pkgL) / r.pkgL;
      const wDelta = Math.abs(newW - r.pkgW) / r.pkgW;
      if (lDelta > MAX_DELTA || wDelta > MAX_DELTA) return;
      const upp = cols * rows * r.maxLayers;
      const closeness = -(lDelta + wDelta);
      if (!best || upp > best.upp ||
          (upp === best.upp && closeness > best.closeness)) {
        best = { newL, newW, cols, rows, upp, closeness };
      }
    };
    if (palL > 0 && palW > 0 && r.pkgL > 0 && r.pkgW > 0) {
      for (let cols = 1; cols <= 10; cols++) {
        for (let rows = 1; rows <= 10; rows++) {
          consider(palL / cols, palW / rows, cols, rows);
          consider(palW / cols, palL / rows, cols, rows);
        }
      }
    }
    if (best && best.upp > curUpp) {
      const fmt = (cm) => r.unit === 'in'
        ? `${(cm / 2.54).toFixed(1)}"`
        : `${cm.toFixed(1)} cm`;
      const gain = best.upp - curUpp;
      const gainPct = curUpp > 0 ? Math.round((gain / curUpp) * 100) : 0;
      const newPallets = (r.totalQty > 0 && best.upp > 0)
        ? Math.ceil(r.totalQty / best.upp) : 0;
      const palletDelta = (r.palletsNeeded || 0) - newPallets;
      // Apply call needs the values in the CURRENT input unit (cm or in)
      // so we don't double-convert when runDimsCalc reads them back.
      const applyL = r.unit === 'in' ? (best.newL / 2.54) : best.newL;
      const applyW = r.unit === 'in' ? (best.newW / 2.54) : best.newW;
      suggestions.push({
        kind: 'tip',
        title: `Try ${fmt(best.newL)} × ${fmt(best.newW)} carton for a tighter fit`,
        body: `Resizing to <strong>${fmt(best.newL)} × ${fmt(best.newW)} × ${fmt(r.pkgH)}</strong> packs <strong>${best.cols} × ${best.rows}</strong> per layer (${best.upp.toLocaleString()} per pallet — +${gain.toLocaleString()}, +${gainPct}%)${newPallets > 0 ? `. Drops pallets needed to <strong>${newPallets.toLocaleString()}</strong>${palletDelta > 0 ? ` (saves ${palletDelta.toLocaleString()})` : ''}` : ''}.`,
        actionLabel: `Apply ${fmt(best.newL)} × ${fmt(best.newW)}`,
        actionCall:  `applyDimsCalcCartonDims(${applyL.toFixed(2)}, ${applyW.toFixed(2)})`
      });
    }

    // ── Suggestion: drop load height to enable double-stacking ───────
    if (!fitsDouble && r.totalQty > 0 && r.pkgH > 0) {
      const maxLoadCmForDouble = (HC_INT_H - 2 * PALLET_DECK) / 2;
      const maxLoadInForDouble = Math.floor(maxLoadCmForDouble / 2.54);
      const newMaxLayers     = Math.max(1, Math.floor(maxLoadCmForDouble / r.pkgH));
      const newPerPallet     = (r.perLayer || 0) * newMaxLayers;
      const newPalletsNeeded = newPerPallet > 0 ? Math.ceil(r.totalQty / newPerPallet) : 0;
      const newContainers    = newPalletsNeeded > 0 ? Math.ceil(newPalletsNeeded / 36) : 0;
      const curContainers    = Math.ceil(r.palletsNeeded / 18);
      if (newContainers > 0 && newContainers <= curContainers) {
        const fitsInOne = newContainers === 1;
        suggestions.push({
          kind: 'good',
          title: `Drop load height to ${maxLoadInForDouble}" to enable double-stacking`,
          body: `At <strong>${maxLoadInForDouble}"</strong> per pallet (${newMaxLayers} layer${newMaxLayers === 1 ? '' : 's'} × ${r.perLayer} per layer = <strong>${newPerPallet.toLocaleString()}</strong> per pallet), two pallets fit vertically inside the 40' HC. Ships <strong>${r.totalQty.toLocaleString()}</strong> units in <strong>${newPalletsNeeded.toLocaleString()}</strong> pallet${newPalletsNeeded === 1 ? '' : 's'} = <strong>${newContainers}</strong> container${newContainers === 1 ? '' : 's'}${fitsInOne ? " (everything fits in a single 40' HC)" : (curContainers > newContainers ? ` (saves ${curContainers - newContainers})` : '')}.`,
          actionLabel: `Apply ${maxLoadInForDouble}"`,
          actionCall:  `applyDimsCalcLoadHeight(${maxLoadInForDouble})`
        });
      }
    }

    // ── Fact: total pallets needed at the entered dims ───────────────
    if (r.totalQty > 0 && r.palletsNeeded > 0) {
      facts.push({
        kind: 'info',
        title: `${r.palletsNeeded.toLocaleString()} pallet${r.palletsNeeded === 1 ? '' : 's'} needed`,
        body: `Shipping <strong>${r.totalQty.toLocaleString()}</strong> units at <strong>${(r.totalPerPallet || 0).toLocaleString()}</strong> per pallet (${r.layoutCols} × ${r.layoutRows} per layer × ${r.maxLayers} layers) at the entered dims.`
      });
    } else if (r.totalQty <= 0) {
      facts.push({
        kind: 'tip',
        title: 'Enter a Total qty to see pallets needed',
        body: `Add a Total qty above and the calculator will tell you how many pallets are required at <strong>${(r.totalPerPallet || 0).toLocaleString()}</strong> ${(r.totalPerPallet || 0) === 1 ? 'unit' : 'units'} per pallet.`
      });
    }

    // ── Fact: estimated 40' HC containers ────────────────────────────
    if (r.totalQty > 0 && r.palletsNeeded > 0) {
      const palletsPerContainer = fitsDouble ? 36 : 18;
      const containers = Math.ceil(r.palletsNeeded / palletsPerContainer);
      facts.push({
        kind: 'info',
        title: `Estimated ${containers} × 40' HC container${containers === 1 ? '' : 's'}`,
        body: `${r.palletsNeeded.toLocaleString()} pallets ÷ ${palletsPerContainer} per container ${fitsDouble ? '(2-stacked vertically)' : '(single layer — stack too tall to double up)'} = <strong>${containers}</strong> 40' HC container${containers === 1 ? '' : 's'}.`
      });
    }

    return [...suggestions, ...facts];
  }

  // Snapshot the current calculator inputs so the operator can Revert
  // back to their original dims after trying a suggestion. Only takes
  // a snapshot the FIRST time an Apply is pressed — repeat applies (try
  // suggestion 2 right after suggestion 1) keep the original baseline
  // intact so Revert always returns to where the user started.
  function _dimsCalcSnapshot() {
    if (window._dimsCalcOriginal) return; // baseline already captured
    const get = (id) => document.getElementById(id)?.value || '';
    window._dimsCalcOriginal = {
      pkgL:        get('dc-pkg-l'),
      pkgW:        get('dc-pkg-w'),
      pkgH:        get('dc-pkg-h'),
      pkgWt:       get('dc-pkg-wt'),
      pkgQty:      get('dc-pkg-qty'),
      loadHeight:  get('dc-load-height'),
      palletPre:   get('dc-pallet-preset'),
      palletL:     get('dc-pallet-l'),
      palletW:     get('dc-pallet-w'),
      unit:        (window._dimsCalc && window._dimsCalc.unit) || 'cm'
    };
  }
  // Apply a recommended load-height value back into the calculator
  // input + immediately rerun so the panel + viz update in place.
  function applyDimsCalcLoadHeight(inches) {
    const el = document.getElementById('dc-load-height');
    if (!el) return;
    _dimsCalcSnapshot();
    el.value = String(inches);
    if (typeof runDimsCalc === 'function') runDimsCalc();
  }
  // Apply a suggested carton footprint (length × width) back into the
  // calculator's package L/W inputs. Values arrive in the active unit
  // (cm or in) so no conversion is needed before assignment.
  function applyDimsCalcCartonDims(newL, newW) {
    const lEl = document.getElementById('dc-pkg-l');
    const wEl = document.getElementById('dc-pkg-w');
    _dimsCalcSnapshot();
    if (lEl) lEl.value = Number(newL).toFixed(2);
    if (wEl) wEl.value = Number(newW).toFixed(2);
    if (typeof runDimsCalc === 'function') runDimsCalc();
  }
  // Revert calculator inputs to whatever the operator had BEFORE their
  // first Apply press, then rerun. Clears the snapshot so the next
  // Apply re-captures from the current state — the user can apply,
  // revert, apply a different suggestion, revert again, etc.
  function revertDimsCalc() {
    const snap = window._dimsCalcOriginal;
    if (!snap) return;
    const set = (id, v) => { const el = document.getElementById(id); if (el) el.value = v; };
    // Restore unit toggle first so the L/W/H values land in the right
    // unit context (setDimsCalcUnit converts in-place; we don't want
    // that — so we bypass it and set window._dimsCalc.unit directly,
    // then update the toggle button styling manually.)
    if (window._dimsCalc) window._dimsCalc.unit = snap.unit;
    const cmBtn = document.getElementById('dc-unit-cm');
    const inBtn = document.getElementById('dc-unit-in');
    if (cmBtn && inBtn) {
      const active = (el) => { el.style.background = 'var(--accent)'; el.style.color = '#fff'; };
      const idle   = (el) => { el.style.background = 'var(--surface2)'; el.style.color = 'var(--text-muted)'; };
      if (snap.unit === 'cm') { active(cmBtn); idle(inBtn); }
      else                    { active(inBtn); idle(cmBtn); }
    }
    set('dc-pkg-l',         snap.pkgL);
    set('dc-pkg-w',         snap.pkgW);
    set('dc-pkg-h',         snap.pkgH);
    set('dc-pkg-wt',        snap.pkgWt);
    set('dc-pkg-qty',       snap.pkgQty);
    set('dc-load-height',   snap.loadHeight);
    set('dc-pallet-preset', snap.palletPre);
    set('dc-pallet-l',      snap.palletL);
    set('dc-pallet-w',      snap.palletW);
    if (typeof onDimsCalcPalletChange === 'function') onDimsCalcPalletChange();
    window._dimsCalcOriginal = null;
    if (typeof runDimsCalc === 'function') runDimsCalc();
  }

  function _renderDimsCalcOptimization(r) {
    const host = document.getElementById('dc-optimization');
    if (!host) return;
    const items = _buildPalletCalcSuggestions(r);
    if (!items.length) { host.innerHTML = ''; return; }
    const colors = {
      good: { bd:'#10b981', bg:'rgba(16,185,129,0.08)', icon:'✓' },
      warn: { bd:'#f59e0b', bg:'rgba(245,158,11,0.08)', icon:'⚠' },
      tip:  { bd:'var(--accent)', bg:'rgba(232,117,26,0.06)', icon:'💡' },
      info: { bd:'#6366f1', bg:'rgba(99,102,241,0.08)', icon:'ℹ' },
    };
    const cards = items.map(it => {
      const c = colors[it.kind] || colors.tip;
      // Real <button> for actionable suggestions — solid accent fill so
      // it reads as a primary CTA, not as inline text. Hover deepens
      // the bg so the click affordance is obvious.
      const actionHtml = it.actionCall
        ? `<div style="margin-top:10px;">
             <button type="button" onclick="${it.actionCall}"
               style="background:${c.bd}; color:#fff; border:none; padding:7px 14px; border-radius:6px; font-size:12px; font-weight:700; cursor:pointer; display:inline-flex; align-items:center; gap:5px;"
               onmouseover="this.style.filter='brightness(0.92)';"
               onmouseout="this.style.filter='';">↻ ${it.actionLabel || 'Apply'}</button>
           </div>`
        : '';
      return `
        <div style="padding:11px 13px; border:1px solid ${c.bd}; border-radius:8px; background:${c.bg}; line-height:1.55;">
          <div style="font-size:12px; font-weight:700; color:${c.bd}; margin-bottom:4px;">
            <span style="margin-right:5px;">${c.icon}</span>${it.title}
          </div>
          <div style="font-size:12px; color:var(--text);">${it.body}</div>
          ${actionHtml}
        </div>`;
    }).join('');
    // Revert banner — surfaced only when the operator has applied at
    // least one suggestion. Lets them flip back to their original
    // dims and try a different suggestion side-by-side.
    const revertBanner = window._dimsCalcOriginal
      ? `<div style="display:flex; align-items:center; justify-content:space-between; gap:10px; padding:9px 13px; margin-bottom:10px; border:1px solid #6366f1; border-radius:8px; background:rgba(99,102,241,0.08); flex-wrap:wrap;">
          <div style="font-size:12px; color:var(--text); line-height:1.5;">
            <strong style="color:#6366f1;">↻ Suggestion applied.</strong> Compare it to the original or try a different one.
          </div>
          <button type="button" onclick="revertDimsCalc()"
            style="background:#6366f1; color:#fff; border:none; padding:6px 14px; border-radius:6px; font-size:12px; font-weight:700; cursor:pointer; white-space:nowrap;"
            onmouseover="this.style.filter='brightness(0.92)';"
            onmouseout="this.style.filter='';">↺ Revert to original</button>
        </div>`
      : '';
    host.innerHTML = `
      <div style="font-size:13px; font-weight:700; color:var(--accent); margin-bottom:10px; padding-top:8px; border-top:1px solid var(--border);">
        Optimization & Stacking Suggestions
      </div>
      ${revertBanner}
      <div style="display:grid; grid-template-columns:1fr 1fr; gap:10px;">
        ${cards}
      </div>
    `;
  }

  // ── Email export helpers ─────────────────────────────────────────────
  function toggleDimsCalcEmailForm(force) {
    const form = document.getElementById('dc-email-form');
    if (!form) return;
    const showing = form.style.display !== 'none';
    const next = (typeof force === 'boolean') ? force : !showing;
    form.style.display = next ? '' : 'none';
    if (next) {
      const status = document.getElementById('dc-email-status');
      if (status) status.textContent = '';
      setTimeout(() => document.getElementById('dc-email-to')?.focus(), 30);
    }
  }

  function sendDimsCalcEmail() {
    const run = window._dimsCalcLastRun;
    const status = document.getElementById('dc-email-status');
    const sendBtn = document.getElementById('dc-email-send-btn');
    if (!run) {
      if (status) status.innerHTML = '<span style="color:#f59e0b;">Run Calculate first to generate a report.</span>';
      return;
    }
    const to = (document.getElementById('dc-email-to')?.value || '').trim();
    if (!to || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(to)) {
      if (status) status.innerHTML = '<span style="color:#f59e0b;">Enter a valid email address.</span>';
      return;
    }
    const canvas = document.getElementById('dc-canvas');
    let imageDataUrl = '';
    try { imageDataUrl = canvas ? canvas.toDataURL('image/png') : ''; } catch (_) {}
    const suggestions = _buildPalletCalcSuggestions(run);
    if (status) status.innerHTML = '<span style="color:var(--text-muted);">Sending…</span>';
    if (sendBtn) sendBtn.disabled = true;
    fetch('api.php?action=email_pallet_calc', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ to, run, image: imageDataUrl, suggestions })
    })
      .then(r => r.json())
      .then(j => {
        if (sendBtn) sendBtn.disabled = false;
        if (j && j.ok) {
          if (status) status.innerHTML = `<span style="color:#10b981;">✓ Sent to ${to}.</span>`;
          setTimeout(() => toggleDimsCalcEmailForm(false), 1500);
        } else {
          const msg = (j && j.error) ? j.error : 'Send failed.';
          if (status) status.innerHTML = `<span style="color:#ef4444;">${msg}</span>`;
        }
      })
      .catch(err => {
        if (sendBtn) sendBtn.disabled = false;
        if (status) status.innerHTML = `<span style="color:#ef4444;">Network error: ${err.message || err}</span>`;
      });
  }

  // Download a PDF of the current Pallet Calc run. Builds the same
  // HTML layout the email export uses, opens it in a hidden new
  // window, and triggers the browser's print-to-PDF dialog. The user
  // picks "Save as PDF" as the destination and the file lands locally
  // — no server round-trip and no extra JS library required.
  function downloadDimsCalcPdf() {
    const r = window._dimsCalcLastRun;
    if (!r) return;
    const palletCanvas    = document.getElementById('dc-canvas');
    const containerCanvas = document.getElementById('dc-container-canvas');
    let palletImg = '', containerImg = '';
    try { if (palletCanvas)    palletImg    = palletCanvas.toDataURL('image/png'); } catch (_) {}
    try { if (containerCanvas) containerImg = containerCanvas.toDataURL('image/png'); } catch (_) {}
    const sug = (typeof _buildPalletCalcSuggestions === 'function')
      ? _buildPalletCalcSuggestions(r) : [];
    const fmtL = (cm) => r.unit === 'in' ? `${(cm/2.54).toFixed(1)}"` : `${cm.toFixed(1)} cm`;
    const fmtKg = (kg) => {
      const lb = kg * 2.20462;
      const r2 = (n) => n < 10 ? n.toFixed(2) : n.toLocaleString('en-US', {maximumFractionDigits:1});
      return `${r2(kg)} kg / ${r2(lb)} lb`;
    };
    const rows = [
      ['Pallet',            r.palLabel || '40 × 48'],
      ['Carton dimensions', `${fmtL(r.pkgL)} × ${fmtL(r.pkgW)} × ${fmtL(r.pkgH)}`],
      ['Layout per layer',  `${r.layoutCols} × ${r.layoutRows} = <strong>${r.perLayer}</strong>`],
      ['Max layers',        `${r.maxLayers} (load height ${r.loadHIn || 60}")`],
      ['Items per pallet',  `<strong>${(r.totalPerPallet || 0).toLocaleString()}</strong>`],
      ['Surface coverage',  `${r.surfaceUse || 0}%`]
    ];
    if (r.palletWtKg)    rows.push(['Weight per pallet', fmtKg(r.palletWtKg)]);
    if (r.totalQty)      rows.push(['Shipment qty',      `${r.totalQty.toLocaleString()} units`]);
    if (r.palletsNeeded) rows.push(['Pallets needed',    `<strong>${r.palletsNeeded.toLocaleString()}</strong>`]);
    if (r.totalWtKg)     rows.push(['Total shipment wt', fmtKg(r.totalWtKg)]);
    const palette = {
      good: '#10b981', warn: '#f59e0b',
      tip:  '#E8751A', info: '#6366f1'
    };
    const sugBlocks = sug.map(it => {
      const color = palette[it.kind] || palette.tip;
      return `<div style="border:1px solid ${color}; border-radius:8px; padding:11px 13px; margin-bottom:10px; background:rgba(0,0,0,0.02);">
        <div style="font-size:12px; font-weight:700; color:${color}; margin-bottom:4px;">${it.title}</div>
        <div style="font-size:13px; color:#1a1d2e; line-height:1.55;">${it.body}</div>
      </div>`;
    }).join('');
    const tableRows = rows.map((row, i) => {
      const bg = i % 2 === 0 ? '#f8f9fb' : '#ffffff';
      return `<tr style="background:${bg};">
        <td style="padding:10px 16px; font-size:12px; font-weight:700; text-transform:uppercase; letter-spacing:0.04em; color:#9ba3c0; width:38%;">${row[0]}</td>
        <td style="padding:10px 16px; font-size:14px; color:#1a1d2e;">${row[1]}</td>
      </tr>`;
    }).join('');
    const html = `<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Pallet Calc Report</title>
      <style>
        @page { size: letter; margin: 0.5in; }
        body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; color:#1a1d2e; margin:0; padding:24px; }
        h1 { color:#181b26; font-size:24px; margin:0 0 4px; }
        h2 { color:#E8751A; font-size:16px; margin:24px 0 12px; border-top:1px solid #e5e7eb; padding-top:14px; }
        .meta { color:#6b7280; font-size:12px; margin-bottom:18px; }
        .viz { text-align:center; margin:14px 0; }
        .viz img { max-width:100%; border-radius:8px; border:1px solid #e5e7eb; }
        table { width:100%; border-collapse:collapse; border:1px solid #e5e7eb; border-radius:8px; overflow:hidden; margin:14px 0; }
        @media print { body { padding:0; } .no-print { display:none; } }
      </style>
    </head><body>
      <h1>Pallet Calculator Report</h1>
      <div class="meta">Generated ${new Date().toLocaleString()}</div>
      ${palletImg ? `<div class="viz"><img src="${palletImg}" alt="Pallet 3D preview" /></div>` : ''}
      <table>${tableRows}</table>
      ${containerImg ? `<h2>Container View — 40' High Cube</h2><div class="viz"><img src="${containerImg}" alt="Container 3D preview" /></div>` : ''}
      ${sugBlocks ? `<h2>Optimization &amp; Stacking Suggestions</h2>${sugBlocks}` : ''}
      <div class="no-print" style="margin-top:30px; padding:14px; background:#f8f9fb; border-radius:8px; text-align:center;">
        <button onclick="window.print()" style="padding:10px 24px; background:#E8751A; color:#fff; border:none; border-radius:6px; font-size:14px; font-weight:700; cursor:pointer;">Save as PDF</button>
        <span style="margin-left:14px; color:#6b7280; font-size:12px;">Tip: in the print dialog, set the destination to "Save as PDF".</span>
      </div>
      <script>setTimeout(function(){window.print();}, 350);<\/script>
    </body></html>`;
    const w = window.open('', '_blank');
    if (!w) {
      alert('Pop-up blocker is preventing the PDF window from opening. Allow pop-ups for this site and try again.');
      return;
    }
    w.document.open();
    w.document.write(html);
    w.document.close();
  }

  // Standalone iso renderer for the calculator modal — independent of
  // the workbook pallet viz (which depends on a lot of workbook state).
  function _drawDimsCalcViz(opts) {
    const c = document.getElementById('dc-canvas');
    if (!c) return;
    const ctx = c.getContext('2d');
    const CW = c.width, CH = c.height;
    ctx.clearRect(0, 0, CW, CH);
    const PALLET_DECK_LOCAL = 15; // cm
    const cos30 = ISO_COS30, sin30 = ISO_SIN30;
    const proj = (wx, wy, wz, s, ox, oy) => ({
      x: ox + (wx - wz) * cos30 * s,
      y: oy + (wx + wz) * sin30 * s - wy * s
    });
    const stackTotal = PALLET_DECK_LOCAL + opts.showLayers * opts.bH;
    const footprintSpan = opts.palL + opts.palW;
    const PAD_L = 130, PAD_R = 40, PAD_T = 30, PAD_B = 90;
    const s = Math.min(
      (CW - PAD_L - PAD_R) / (footprintSpan * cos30),
      (CH - PAD_T - PAD_B)   / (stackTotal + footprintSpan * sin30)
    );
    const ox = PAD_L + opts.palW * cos30 * s;
    const oy = stackTotal * s + PAD_T;
    // Pallet deck
    drawIsoBox(ctx, 0, 0, 0, opts.palL, PALLET_DECK_LOCAL, opts.palW, s, ox, oy, '#a8a8a8');
    // Boxes — centered on pallet base
    const occL = opts.cols * opts.bL;
    const occW = opts.rows * opts.bW;
    const offX = Math.max(0, (opts.palL - occL) / 2);
    const offZ = Math.max(0, (opts.palW - occW) / 2);
    for (let layer = 0; layer < opts.showLayers; layer++) {
      for (let diag = 0; diag <= opts.cols + opts.rows - 2; diag++) {
        for (let col = Math.max(0, diag - opts.rows + 1); col <= Math.min(diag, opts.cols - 1); col++) {
          const row = diag - col;
          drawIsoBox(ctx,
            offX + col * opts.bL, PALLET_DECK_LOCAL + layer * opts.bH, offZ + row * opts.bW,
            opts.bL, opts.bH, opts.bW, s, ox, oy, '#E8751A');
        }
      }
    }
    // Dim labels (L / W / H) — same bracket style as the workbook viz
    const v3 = {
      bbl: proj(0,         0,          0,        s, ox, oy),
      bbr: proj(opts.palL, 0,          0,        s, ox, oy),
      bfl: proj(0,         0,          opts.palW, s, ox, oy),
      bfr: proj(opts.palL, 0,          opts.palW, s, ox, oy),
      tfl: proj(0,         stackTotal, opts.palW, s, ox, oy)
    };
    const allPts = Object.values(v3);
    const cxBox = allPts.reduce((a,p)=>a+p.x,0)/allPts.length;
    const cyBox = allPts.reduce((a,p)=>a+p.y,0)/allPts.length;
    const sxMin = Math.min(...allPts.map(p=>p.x));
    const outwardPerp = (a,b) => {
      const dx=b.x-a.x, dy=b.y-a.y, len=Math.sqrt(dx*dx+dy*dy)||1;
      const px=-dy/len, py=dx/len;
      const mx=(a.x+b.x)/2, my=(a.y+b.y)/2;
      const dot = px*(mx-cxBox) + py*(my-cyBox);
      return dot>=0 ? {x:px,y:py} : {x:-px,y:-py};
    };
    const TICK = 4;
    ctx.fillStyle = '#6b7280';
    ctx.strokeStyle = '#6b7280';
    ctx.lineWidth = 1.2;
    ctx.font = `700 13px -apple-system, sans-serif`;
    const drawDim = (a, b, lp, txt, anchor='center') => {
      ctx.beginPath(); ctx.moveTo(a.x,a.y); ctx.lineTo(b.x,b.y); ctx.stroke();
      const dx=b.x-a.x, dy=b.y-a.y, len=Math.sqrt(dx*dx+dy*dy)||1;
      const tpx=-dy/len*TICK, tpy=dx/len*TICK;
      ctx.beginPath();
      ctx.moveTo(a.x-tpx,a.y-tpy); ctx.lineTo(a.x+tpx,a.y+tpy);
      ctx.moveTo(b.x-tpx,b.y-tpy); ctx.lineTo(b.x+tpx,b.y+tpy);
      ctx.stroke();
      ctx.textAlign = anchor;
      ctx.textBaseline = 'middle';
      ctx.fillText(txt, lp.x, lp.y);
    };
    const fmtL = (cm) => opts.unit === 'cm' ? `${cm.toFixed(1)} cm` : `${(cm/2.54).toFixed(1)}"`;
    // L
    {
      const a0=v3.bfl, b0=v3.bfr, p=outwardPerp(a0,b0);
      const a={x:a0.x+p.x*16,y:a0.y+p.y*16}, b={x:b0.x+p.x*16,y:b0.y+p.y*16};
      const m={x:(a.x+b.x)/2+p.x*36,y:(a.y+b.y)/2+p.y*36};
      drawDim(a,b,m,`L ${fmtL(opts.palL)}`);
    }
    // W
    {
      const a0=v3.bfr, b0=v3.bbr, p=outwardPerp(a0,b0);
      const a={x:a0.x+p.x*16,y:a0.y+p.y*16}, b={x:b0.x+p.x*16,y:b0.y+p.y*16};
      const m={x:(a.x+b.x)/2+p.x*36,y:(a.y+b.y)/2+p.y*36};
      drawDim(a,b,m,`W ${fmtL(opts.palW)}`);
    }
    // H
    {
      const hX = sxMin - 22;
      const a={x:hX,y:v3.tfl.y}, b={x:hX,y:v3.bfl.y};
      drawDim(a,b,{x:hX-12,y:(a.y+b.y)/2},`H ${fmtL(stackTotal)}`,'right');
    }
    // Pallet label top-right
    ctx.fillStyle = '#6b7280';
    ctx.font = `700 11px -apple-system, sans-serif`;
    ctx.textAlign = 'right';
    ctx.textBaseline = 'top';
    ctx.fillText(opts.palLabel, CW - 12, 10);
  }

  // Standalone container preview for the Pallet Calc modal — draws a
  // 40' HC wireframe with the loaded pallet count rendered as solid
  // iso boxes inside, plus a stats line below the canvas (pallets per
  // container, containers needed, double-stack flag). Mirrors the
  // workbook's renderContainerViz at a smaller scale so the modal
  // doesn't depend on workbook state. Reads from window._dimsCalcLastRun.
  function _drawDimsCalcContainerViz(r) {
    const c = document.getElementById('dc-container-canvas');
    if (!c) return;
    const ctx = c.getContext('2d');
    const CW = c.width, CH = c.height;
    ctx.clearRect(0, 0, CW, CH);
    if (!r || !r.palL || !r.palW || !r.pkgH || !r.perLayer) {
      ctx.fillStyle = '#9ca3af';
      ctx.font = '13px -apple-system, sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('Run Calculate to see the container view.', CW/2, CH/2);
      const stats = document.getElementById('dc-container-stats');
      if (stats) stats.innerHTML = '';
      const summary = document.getElementById('dc-container-summary-stat');
      if (summary) summary.innerHTML = '<span style="font-size:13px;">▾</span>';
      return;
    }
    // 40' HC interior dims (cm)
    const HC_L = 1203, HC_W = 235, HC_H = 269;
    const PALLET_DECK_LOCAL = 15;
    const palletStackCm = PALLET_DECK_LOCAL + r.maxLayers * r.pkgH;
    // Pallets per layer — try both pallet rotations on the floor
    const pAcols = Math.floor(HC_L / r.palL), pArows = Math.floor(HC_W / r.palW);
    const pBcols = Math.floor(HC_L / r.palW), pBrows = Math.floor(HC_W / r.palL);
    const useA = (pAcols * pArows) >= (pBcols * pBrows);
    const palCols = useA ? pAcols : pBcols;
    const palRows = useA ? pArows : pBrows;
    const palL_oriented = useA ? r.palL : r.palW;
    const palW_oriented = useA ? r.palW : r.palL;
    const palletsPerLayer = palCols * palRows;
    const verticalLayers = Math.max(1, Math.min(2, Math.floor(HC_H / palletStackCm)));
    const palletsPerContainer = palletsPerLayer * verticalLayers;
    const palletsNeeded = r.palletsNeeded || 0;
    const palletsToShow = palletsNeeded > 0
      ? Math.min(palletsNeeded, palletsPerContainer)
      : palletsPerContainer;
    const containersNeeded = palletsNeeded > 0
      ? Math.ceil(palletsNeeded / palletsPerContainer) : 0;
    // Iso projection setup — same camera as the pallet viz.
    const totalStackCm = Math.min(verticalLayers * palletStackCm, HC_H);
    const footprintSpan = HC_L + HC_W;
    const PAD_L = 110, PAD_R = 120, PAD_T = 30, PAD_B = 60;
    const s = Math.min(
      (CW - PAD_L - PAD_R) / (footprintSpan * ISO_COS30),
      (CH - PAD_T - PAD_B) / (totalStackCm + footprintSpan * ISO_SIN30)
    );
    const ox = (CW + (HC_W - HC_L) * ISO_COS30 * s) / 2;
    const oy = totalStackCm * s + PAD_T;
    // ── Draw loaded pallets (orange) — back-to-front, layer-by-layer
    let drawn = 0;
    outer:
    for (let layer = 0; layer < verticalLayers; layer++) {
      const layerY = layer * palletStackCm;
      // Each pallet rendered as deck + cargo block on top
      for (let diag = 0; diag <= palCols + palRows - 2; diag++) {
        for (let col = Math.max(0, diag - palRows + 1); col <= Math.min(diag, palCols - 1); col++) {
          const row = diag - col;
          if (drawn >= palletsToShow) break outer;
          const px = col * palL_oriented;
          const pz = row * palW_oriented;
          // Pallet deck (grey)
          drawIsoBox(ctx, px, layerY, pz, palL_oriented, PALLET_DECK_LOCAL, palW_oriented, s, ox, oy, '#a8a8a8');
          // Cargo column (orange)
          drawIsoBox(ctx, px, layerY + PALLET_DECK_LOCAL, pz, palL_oriented, palletStackCm - PALLET_DECK_LOCAL, palW_oriented, s, ox, oy, '#E8751A');
          drawn++;
        }
      }
    }
    // ── Wireframe container outline
    const proj = (wx, wy, wz) => ({
      x: ox + (wx - wz) * ISO_COS30 * s,
      y: oy + (wx + wz) * ISO_SIN30 * s - wy * s
    });
    const v = {
      bbl: proj(0, 0, 0),       bbr: proj(HC_L, 0, 0),
      bfl: proj(0, 0, HC_W),    bfr: proj(HC_L, 0, HC_W),
      tbl: proj(0, HC_H, 0),    tbr: proj(HC_L, HC_H, 0),
      tfl: proj(0, HC_H, HC_W), tfr: proj(HC_L, HC_H, HC_W)
    };
    ctx.strokeStyle = '#94a3b8';
    ctx.lineWidth = 1;
    const line = (a, b) => { ctx.beginPath(); ctx.moveTo(a.x, a.y); ctx.lineTo(b.x, b.y); ctx.stroke(); };
    [['bbl','bbr'],['bbr','bfr'],['bfr','bfl'],['bfl','bbl'],
     ['tbl','tbr'],['tbr','tfr'],['tfr','tfl'],['tfl','tbl'],
     ['bbl','tbl'],['bbr','tbr'],['bfr','tfr'],['bfl','tfl']
    ].forEach(([a,b]) => line(v[a], v[b]));
    // Container label top-right
    ctx.fillStyle = '#6b7280';
    ctx.font = `700 11px -apple-system, sans-serif`;
    ctx.textAlign = 'right';
    ctx.textBaseline = 'top';
    ctx.fillText(`40' HC (${verticalLayers}-pallet vertical)`, CW - 12, 10);
    // Stats line below the canvas
    const stats = document.getElementById('dc-container-stats');
    if (stats) {
      const fitsTag = verticalLayers > 1
        ? '<span style="color:#10b981; font-weight:700;">2-pallet vertical stacking enabled</span>'
        : '<span style="color:#f59e0b; font-weight:700;">single-layer only — stack too tall to double up</span>';
      stats.innerHTML = `
        <strong>${palletsPerContainer}</strong> pallets per 40' HC <span style="color:var(--text-muted);">(${palCols} × ${palRows} per floor × ${verticalLayers}-high)</span>
        ${palletsNeeded > 0 ? `&nbsp;·&nbsp; <strong style="color:var(--accent);">${containersNeeded}</strong> container${containersNeeded === 1 ? '' : 's'} needed` : ''}
        <br>${fitsTag}.
      `;
    }
    // Compact summary in the <details> header (visible when collapsed)
    const summary = document.getElementById('dc-container-summary-stat');
    if (summary) {
      const compact = palletsNeeded > 0
        ? `<span style="color:var(--accent); font-weight:700;">${containersNeeded}</span> × 40' HC`
        : `<span style="color:var(--text-muted);">${palletsPerContainer} pallets / 40' HC</span>`;
      summary.innerHTML = `${compact} <span style="font-size:13px;">▾</span>`;
    }
  }

  // Cmd/Ctrl+Shift+D opens the modal as a power-user shortcut.
  document.addEventListener('keydown', (e) => {
    if ((e.metaKey || e.ctrlKey) && e.shiftKey && (e.key === 'D' || e.key === 'd')) {
      e.preventDefault();
      openDimsCalcModal();
    }
  });

  async function fetchLiveRate() {
    // Check localStorage cache first (30-min TTL)
    try {
      const cached = JSON.parse(localStorage.getItem('fx_usd_cny') || 'null');
      if (cached && cached.rate && (Date.now() - cached.ts) < RATE_TTL) {
        applyNewRate(cached.rate, 'cached');
        return;
      }
    } catch(e) {}

    // Cache stale or missing — call PHP proxy (tries XE.com, falls back to open.er-api.com)
    try {
      const data = await apiCall('get_fx_rate');
      if (data && data.rate) {
        localStorage.setItem('fx_usd_cny', JSON.stringify({ rate: data.rate, ts: Date.now() }));
        applyNewRate(data.rate, data.source || 'live');
        return;
      }
    } catch(e) {}

    // Last-resort: fetch open.er-api.com directly from browser
    try {
      const res = await fetch('https://open.er-api.com/v6/latest/USD');
      const data = await res.json();
      if (data.result === 'success' && data.rates && data.rates.CNY) {
        const rate = data.rates.CNY;
        localStorage.setItem('fx_usd_cny', JSON.stringify({ rate, ts: Date.now() }));
        applyNewRate(rate, 'open.er-api');
      }
    } catch(e) {
      console.warn('Exchange rate fetch failed, using fallback:', USD_TO_RMB);
    }
  }

  // Initial fetch + refresh every 30 minutes
  fetchLiveRate();
  setInterval(fetchLiveRate, RATE_TTL);

  // Guard against autofill that fires BEFORE any user interaction — Chrome
  // sometimes silently fills the calc with the logged-in user's name. We run
  // a delayed scrub after first paint so any ghost-fill gets wiped.
  function _scrubFxCalc() {
    ['hdr-calc-rmb', 'hdr-calc-usd'].forEach(id => {
      const el = document.getElementById(id);
      if (el && el.value) _hdrSanitize(el);
    });
  }
  // Multiple scrub passes catch early/late autofill races (Chrome Autofill,
  // 1Password/LastPass extensions). Cheap to do; no visible cost.
  setTimeout(_scrubFxCalc, 50);
  setTimeout(_scrubFxCalc, 500);
  setTimeout(_scrubFxCalc, 2000);

  function convertRmbToUsd() {
    const rmb = parseFloat(document.getElementById('quote-unit-rmb').value);
    const usdEl = document.getElementById('quote-unit');
    usdEl.value = isNaN(rmb) ? '' : _fxUsdFromRmb(rmb).toFixed(2);
  }

  /* ── RFQ Line Items ─────────────────────────────────────────────────── */
  let rfqCount = 0;
  let _rfqVarCount = 0;
  let _wbLocked = false;
  let _draggingVarId = null; // tracks which variant row is being dragged

  function addRfqRow(item = '', sku = '', qty = '', priceRmb = '', leadTime = '', sample = false, variants = []) {
    rfqCount++;
    const id = rfqCount;
    const tbody = document.getElementById('rfq-body');
    const isFirstRow = tbody.querySelectorAll('tr:not([data-rfq-parent]):not([data-rfq-add-for])').length === 0;
    const defaultItem = item;
    const tr = document.createElement('tr');
    tr.id = `rfq-${id}`;
    tr.ondragover = function(e) { e.preventDefault(); tr.style.borderTop='2px solid var(--accent)'; };
    tr.ondragleave = function() { tr.style.borderTop=''; };
    tr.ondrop = function(e) { e.preventDefault(); tr.style.borderTop=''; rfqDropRow(e, id); };
    const usdVal = priceRmb ? _fxUsdFromRmbPrecise(priceRmb).toFixed(3) : '';
    const totalVal = (qty && usdVal) ? (parseFloat(qty) * parseFloat(usdVal)).toFixed(2) : '';
    // Slightly taller row — bumped vertical padding from 10px to 12px so
    // the row has room for the inline "+ Add Variant" link below the
    // Item input without feeling cramped.
    const inputStyle = 'width:100%; border:1px solid var(--border); border-radius:8px; padding:12px 14px; font-size:13px; box-sizing:border-box;';
    if (isFirstRow) {
      tr.style.background = 'rgba(232, 117, 26, 0.08)';
      tr.ondragover = null;
      tr.ondragleave = null;
      tr.ondrop = null;
    }
    if (sample) {
      tr.classList.add('rfq-sample-row');
    }
    const handleAttr = isFirstRow ? '' : `draggable="true" onmousedown="this.closest('tr').draggable=true" onmouseup="this.closest('tr').draggable=false" ondragstart="event.dataTransfer.setData('text/plain','${id}'); this.closest('tr').style.opacity='0.4'" ondragend="this.closest('tr').style.opacity='1'; this.closest('tr').draggable=false"`;
    tr.innerHTML = `
      <td class="tier-col-num" style="color:var(--text-muted); font-weight:600; text-align:center;${isFirstRow ? '' : ' cursor:grab;'}" ${isFirstRow ? '' : 'title="Drag to reorder"'} ${handleAttr}>${isFirstRow ? id : '☰ ' + id}</td>
      <td style="text-align:center; padding:24px 8px 4px;"><label class="rfq-sample-label" title="Mark as sample request"><input type="checkbox" class="rfq-sample-check" ${sample ? 'checked' : ''} onchange="toggleRfqSample(this)" /></label></td>
      <td><input type="text" placeholder="SKU" value="${sku}" title="${sku}" oninput="this.title=this.value; recalcRfqTotals(); _refreshVariantSkusForParent(${id})" style="${inputStyle}" /></td>
      <td>
        <input type="text" placeholder="Enter Item" value="${defaultItem}" oninput="recalcRfqTotals()" style="${inputStyle}" />
        <button type="button" class="rfq-add-variant-link" onclick="addRfqVariantRow(${id})" title="Add a variant (size, color, etc.) under this item">+ Add Variant</button>
      </td>
      <td><input type="text" inputmode="numeric" placeholder="0" value="${qty}" data-num-int="1"
            oninput="recalcRfqRow(${id})"
            onfocus="_msStripCommasOnFocus(this)"
            onblur="_msFmtIntOnBlur(this); recalcRfqRow(${id})"
            style="${inputStyle}" /></td>
      <td><div class="currency-prefix currency-rmb" style="position:relative;"><input type="text" inputmode="decimal" placeholder="0.00" value="${priceRmb}" data-num-dec="1"
            oninput="recalcRfqRow(${id})"
            onfocus="_msStripCommasOnFocus(this)"
            onblur="_msFmtDecOnBlur(this); recalcRfqRow(${id})"
            style="${inputStyle} padding-left:28px;" /></div></td>
      <td class="tier-col-usd" id="rfq-usd-${id}" style="color:var(--text); font-size:13px; text-align:right; font-weight:600;">${usdVal ? '$' + parseFloat(usdVal).toLocaleString('en-US', {minimumFractionDigits:3, maximumFractionDigits:3}) : '—'}</td>
      <td class="total-cell" id="rfq-total-${id}" style="text-align:right;">${totalVal ? '$' + parseFloat(totalVal).toLocaleString('en-US', {minimumFractionDigits:2}) : '—'}</td>
      <td><div class="lead-time-suffix" style="position:relative;"><input type="text" placeholder="0" value="${leadTime}" oninput="recalcRfqTotals()" style="${inputStyle} padding-right:40px;" /></div></td>
      <td style="white-space:nowrap; text-align:center;">
        <span class="remove-tier" onclick="removeRfqRow(${id})" title="Remove line item">&times;</span>
      </td>
    `;
    tbody.appendChild(tr);
    variants.forEach(v => addRfqVariantRow(id, v.variant, v.qty, v.priceRmb, v.leadTime, v.sku || ''));
    _updateVarAddRow(id);   // place trailing button below last variant (or parent if none)
    recalcRfqTotals();
    if (_wbLocked) {
      tr.querySelectorAll('input, select, textarea, button, span.remove-tier').forEach(el => {
        if (el.tagName === 'SPAN') { el.style.pointerEvents = 'none'; el.style.opacity = '0.3'; }
        else { el.disabled = true; el.style.opacity = '0.6'; el.style.cursor = 'not-allowed'; }
      });
    }
  }

  function removeRfqRow(id) {
    const row = document.getElementById(`rfq-${id}`);
    if (row) row.remove();
    document.querySelectorAll(`[data-rfq-parent="${id}"]`).forEach(vr => vr.remove());
    document.querySelector(`[data-rfq-add-for="${id}"]`)?.remove();
    renumberRfqRows();
    // If we just deleted the last RFQ row, drop in a fresh blank row so
    // the table never bottoms out completely (matches what the user
    // expects when they "start over"): there's always at least one row
    // visible to type into.
    const remaining = document.querySelectorAll('#rfq-body tr:not([data-rfq-parent]):not([data-rfq-add-for])');
    if (remaining.length === 0) addRfqRow();
    recalcRfqTotals();
    if (!_filling) autoSaveWorkbook();
  }

  function renumberRfqRows() {
    const rows = document.querySelectorAll('#rfq-body tr:not([data-rfq-parent]):not([data-rfq-add-for])');
    rows.forEach((row, i) => {
      const td = row.querySelector('td');
      if (i === 0) {
        td.textContent = i + 1;
      } else {
        td.textContent = '☰ ' + (i + 1);
      }
    });
  }

  function recalcRfqRow(id) {
    const row = document.getElementById(`rfq-${id}`);
    if (!row) return;
    const inputs = row.querySelectorAll('input:not([type="checkbox"])');
    const qty = _msNumFromInput(inputs[2]);
    const rmb = _msNumFromInput(inputs[3]);
    // Per-unit USD: precise RMB/rate conversion at 3 decimals for
    // accuracy on low-RMB items (¥0.30 → $0.044 instead of being
    // rounded to $0.04). Total is qty × precise per-unit at 2
    // decimals (dollar amount).
    const usd   = _fxUsdFromRmbPrecise(rmb);
    const total = qty > 0 && usd > 0 ? qty * usd : 0;
    const usdEl = document.getElementById(`rfq-usd-${id}`);
    const totalEl = document.getElementById(`rfq-total-${id}`);
    if (usdEl) usdEl.textContent   = rmb ? '$' + usd.toLocaleString('en-US', {minimumFractionDigits:3, maximumFractionDigits:3}) : '—';
    if (totalEl) totalEl.textContent = (qty && rmb) ? '$' + total.toLocaleString('en-US', {minimumFractionDigits:2, maximumFractionDigits:2}) : '—';
    recalcRfqTotals();
    if (!_filling) autoSaveWorkbook();
  }

  function recalcRfqTotals() { try { _recalcRfqTotalsInner(); } catch(e) { console.error('[MS recalcRfqTotals]', e); } }

  // Subtotal-row DOM rebuild scheduler — keeps only the latest pending
  // callback so a burst of recalcRfqTotals calls collapses into one
  // remove-and-reinsert pass on the next animation frame.
  let _rfqSubtotalRaf = null;
  let _rfqSubtotalCb  = null;
  function _scheduleRfqSubtotalRebuild(cb) {
    _rfqSubtotalCb = cb;
    if (_rfqSubtotalRaf) return;
    _rfqSubtotalRaf = requestAnimationFrame(() => {
      _rfqSubtotalRaf = null;
      const fn = _rfqSubtotalCb;
      _rfqSubtotalCb = null;
      try { if (fn) fn(); } catch(e) { console.error('[MS rfqSubtotalRebuild]', e); }
    });
  }

  function _recalcRfqTotalsInner() {
    const fmt = (n, dec = 2) => n.toLocaleString('en-US', {minimumFractionDigits: dec, maximumFractionDigits: dec});

    // ── 1. Collect per-item / per-variant data ────────────────────────────
    // itemSummaries is a flat list: one entry per variant (when variants exist),
    // or one entry per parent row (when no variants). This drives both the
    // breakdown rows and the grand totals — no double-counting.
    // Single-scan grouping. Walking #rfq-body once and bucketing rows
    // into parents vs. variants beats the prior N+1 pattern (one
    // querySelectorAll per parent looking up its variants), which got
    // expensive once we added the variant tier work and the function
    // started running on every RFQ keystroke.
    const allRfqRows = document.querySelectorAll('#rfq-body tr');
    const parentRows = [];
    const variantsByParent = new Map();
    allRfqRows.forEach(r => {
      if (r.hasAttribute('data-rfq-add-for')) return;
      if (r.hasAttribute('data-rfq-parent')) {
        const pid = r.dataset.rfqParent;
        let arr = variantsByParent.get(pid);
        if (!arr) { arr = []; variantsByParent.set(pid, arr); }
        arr.push(r);
      } else {
        parentRows.push(r);
      }
    });
    let grandQty = 0, grandUsd = 0, grandRmb = 0, grandUsdUnit = 0, maxLead = 0;
    // True qty-weighted RMB accumulator — stays in RMB throughout (no
    // USD round-trip, no ceil-to-cent inflation). Used by Tiered
    // Pricing so the per-unit RMB displayed on each tier matches what
    // the operator actually entered on the RFQ. Without this, low-RMB
    // items (e.g. ¥0.30 / unit) got inflated to ¥0.34 because the old
    // path back-calculated RMB from the already-ceiled grandUsd.
    let grandRmbQtyXPrice = 0;   // Σ qty × rmb across priced units
    let grandRmbQty       = 0;   // Σ qty for those same priced units
    const itemSummaries = [];  // { label, qty, rmb, usd, total, lead, isVariant }

    parentRows.forEach(row => {
      const id      = parseInt(row.id.replace('rfq-', ''));
      const inputs  = row.querySelectorAll('input:not([type="checkbox"])');
      const name    = inputs[1]?.value?.trim() || '';
      const qty     = _msNumFromInput(inputs[2]);
      const rmb     = _msNumFromInput(inputs[3]);  // the "original" price
      const lead    = inputs[4]?.value || '';
      const leadNum = parseInt(lead);

      const varRows = variantsByParent.get(String(id)) || [];

      if (varRows.length > 0) {
        // ── Has variants: emit ONE aggregate row for the parent. ─────────
        // Per the operator's UX direction, variants belong on the
        // Inventory left-nav dashboard, NOT exploded into per-line rows
        // here in the RFQ subtotal. We aggregate every variant's qty +
        // USD total under the parent label; the RMB / per-unit USD
        // columns show a single value when every variant is at the same
        // price, or a "¥min–¥max" range when prices vary.
        if (!isNaN(leadNum) && leadNum > maxLead) maxLead = leadNum;

        let totQty = 0, totUsd = 0;
        let minRmb = Infinity, maxRmb = -Infinity;
        varRows.forEach(vr => {
          // Skip the SKU input so positional access (name=0, qty=1,
          // rmb=2, lead=3) stays correct after the variant SKU column.
          const vi       = vr.querySelectorAll('input:not(.rfq-var-sku-input)');
          const vQty     = _msNumFromInput(vi[1]);
          const vRmb     = _msNumFromInput(vi[2]);
          const vLead    = vi[3]?.value || '';
          const vLeadNum = parseInt(vLead);
          if (!isNaN(vLeadNum) && vLeadNum > maxLead) maxLead = vLeadNum;
          if (vQty > 0) totQty += vQty;
          if (vRmb > 0) {
            totUsd += _msCeil2(vQty * _fxUsdFromRmb(vRmb));
            if (vRmb < minRmb) minRmb = vRmb;
            if (vRmb > maxRmb) maxRmb = vRmb;
            // Feed the qty-weighted RMB accumulator — RMB stays RMB.
            if (vQty > 0) {
              grandRmbQtyXPrice += vQty * vRmb;
              grandRmbQty       += vQty;
            }
          }
        });

        // Skip the parent entirely if every variant is empty (no qty
        // AND no price entered yet) — otherwise we'd inject a row of
        // dashes.
        if (totQty > 0 || minRmb !== Infinity) {
          // Build display strings for RMB / USD: single value when all
          // variants share a price, range string when they differ.
          const EPSILON = 0.005;
          let rmbText = '—', usdText = '—', avgUsdForGrand = 0;
          if (minRmb !== Infinity && maxRmb !== -Infinity) {
            if (Math.abs(maxRmb - minRmb) < EPSILON) {
              const u = _fxUsdFromRmb(minRmb);
              rmbText = '¥' + fmt(minRmb);
              usdText = '$' + fmt(u);
              avgUsdForGrand = u;
            } else {
              const uMin = _fxUsdFromRmb(minRmb), uMax = _fxUsdFromRmb(maxRmb);
              rmbText = `¥${fmt(minRmb)}–¥${fmt(maxRmb)}`;
              usdText = `$${fmt(uMin)}–$${fmt(uMax)}`;
              avgUsdForGrand = (uMin + uMax) / 2; // rough avg; only feeds grandUsdUnit
            }
          }
          grandQty     += totQty;
          if (minRmb !== Infinity) grandRmb += minRmb; // keep prior shape
          grandUsdUnit += avgUsdForGrand;
          grandUsd     += totUsd;
          itemSummaries.push({
            label: name || ('Item ' + id),
            qty: totQty,
            rmb: 0, usd: 0,
            rmbText, usdText,
            total: totUsd,
            lead,
            isVariant: false,
          });
        }

      } else {
        // ── No variants: one summary row for the parent ───────────────────
        const usd   = _fxUsdFromRmb(rmb);
        const total = _msCeil2(qty * usd);

        grandQty     += qty;
        grandRmb     += rmb;
        grandUsdUnit += usd;
        if (qty && rmb) {
          grandUsd          += total;
          grandRmbQtyXPrice += qty * rmb;
          grandRmbQty       += qty;
        }
        if (!isNaN(leadNum) && leadNum > maxLead) maxLead = leadNum;

        if (name || qty || rmb) {
          itemSummaries.push({ label: name || ('Item ' + id), qty, rmb, usd, total, lead, isVariant: false });
        }
      }
    });

    // ── 2. Inject per-item subtotal rows — deferred to next frame ────────
    // Removing + re-inserting subtotal rows synchronously on every keystroke
    // triggered layout thrash (50+ ms per stroke with many variants). The
    // data side of this function (grand totals, _lastRfqPriceSummary,
    // applyRfqRmbToTiers) still runs synchronously below so downstream
    // consumers see fresh values immediately. The DOM rebuild coalesces
    // to one rAF — bursts of typing render only the final state.
    const totalsRow = document.getElementById('rfq-totals');
    const showBreakdown = itemSummaries.length > 1
                       || itemSummaries.some(s => s.isVariant);

    // ── 3. Grand total row label (sync — single cell update is cheap) ───
    const totalsLabel = totalsRow?.querySelector('td:nth-child(4)');
    if (totalsLabel) totalsLabel.textContent = showBreakdown ? 'GRAND TOTAL' : 'TOTALS';

    _scheduleRfqSubtotalRebuild(() => {
      document.querySelectorAll('.rfq-item-subtotal').forEach(r => r.remove());
      if (!showBreakdown || !totalsRow) return;
      // Subtotal rows display at 3 decimals to match the per-line
      // UNIT PRICE (USD) cells everywhere else in the RFQ table.
      const fmt3sub = v => v.toLocaleString('en-US', { minimumFractionDigits: 3, maximumFractionDigits: 3 });
      itemSummaries.forEach(item => {
        // Derive precise USD / Total at render time so the subtotal
        // row matches the per-line row and the new TOTALS row (which
        // also use precise math). item.usd / item.total in the data
        // structure stay ceiled — they're consumed by downstream
        // (Pricing tab, Tier USD) and we don't want to silently shift
        // those numbers as a side effect of this display change.
        const itemUsdPrecise = (item.rmb && USD_TO_RMB > 0) ? item.rmb / USD_TO_RMB : 0;
        const itemTotalPrecise = (item.qty > 0 && itemUsdPrecise > 0) ? item.qty * itemUsdPrecise : 0;
        const tr = document.createElement('tr');
        tr.className = 'rfq-item-subtotal';
        tr.style.borderTop = '1px solid var(--border)';
        tr.innerHTML = `
          <td></td><td></td><td></td>
          <td style="font-size:12px;color:var(--text);padding:7px 8px 7px 26px;font-weight:500;">
            ${item.label}
          </td>
          <td style="font-size:12px;color:var(--text);font-weight:700;padding:7px 8px 7px 26px;">
            ${item.qty ? item.qty.toLocaleString('en-US') : '—'}
          </td>
          <td style="font-size:12px;color:var(--text-muted);padding:7px 8px 7px 26px;">
            ${item.rmbText !== undefined ? item.rmbText : (item.rmb ? '¥' + fmt(item.rmb) : '—')}
          </td>
          <td style="font-size:12px;color:var(--text-muted);text-align:right;padding:7px 12px 7px 8px;">
            ${item.usdText !== undefined ? item.usdText : (itemUsdPrecise ? '$' + fmt3sub(itemUsdPrecise) : '—')}
          </td>
          <td style="font-size:12px;color:var(--text);font-weight:700;text-align:right;padding:7px 12px 7px 8px;">
            ${itemTotalPrecise ? '$' + fmt(itemTotalPrecise) : (item.total ? '$' + fmt(item.total) : '—')}
          </td>
          <td style="font-size:12px;color:var(--text-muted);padding:7px 8px 7px 26px;">
            ${item.lead ? item.lead + ' days' : '—'}
          </td>
          <td></td>`;
        totalsRow.before(tr);
      });
    });

    // Variant-aware price summary: when variants exist, the unit-price columns
    // display the price-per (single value) or a range (min–max) instead of a sum.
    // Only consider entries with an actual price for the min/max calculation.
    const hasVariants = !!document.querySelector('#rfq-body tr[data-rfq-parent]');
    const PRICE_EPS   = 0.005;
    const pricedItems = itemSummaries.filter(s => s.rmb > 0);
    let rmbMin = 0, rmbMax = 0, usdMin = 0, usdMax = 0, isRange = false;
    if (pricedItems.length > 0) {
      rmbMin = Math.min(...pricedItems.map(s => s.rmb));
      rmbMax = Math.max(...pricedItems.map(s => s.rmb));
      usdMin = _fxUsdFromRmb(rmbMin);
      usdMax = _fxUsdFromRmb(rmbMax);
      isRange = hasVariants && (rmbMax - rmbMin > PRICE_EPS);
    }

    // grandRmbWeighted = qty-weighted average of the per-unit RMB
    // prices entered on the RFQ. Computed without ever going through
    // USD so ceil-to-cent rounding can't inflate it (e.g. ¥0.30 stays
    // ¥0.30, not ¥0.34). Tiered Pricing reads this directly.
    const grandRmbWeighted = grandRmbQty > 0 ? (grandRmbQtyXPrice / grandRmbQty) : 0;
    _lastRfqPriceSummary = {
      hasVariants, rmbMin, rmbMax, usdMin, usdMax, isRange,
      grandQty, grandRmb, grandRmbWeighted, grandUsdUnit, grandUsd
    };

    document.getElementById('rfq-total-qty').textContent = grandQty ? grandQty.toLocaleString('en-US') : '—';

    // In manual mode, propagate the RFQ Grand Total qty into the
    // "Total Units to Ship" input on the Pallet section so the pallets
    // count is computed automatically. Respects user overrides — see
    // syncManualPalletTotalUnits() for the merge rule.
    if (typeof syncManualPalletTotalUnits === 'function') syncManualPalletTotalUnits();

    // Unit Price (RMB): variant mode → single price or range; else → sum (legacy "insert" behavior)
    const rmbCell = document.getElementById('rfq-total-rmb');
    if (rmbCell) {
      if (hasVariants && pricedItems.length > 0) {
        rmbCell.textContent = isRange
          ? '¥ ' + fmt(rmbMin) + '–¥ ' + fmt(rmbMax)
          : '¥ ' + fmt(rmbMin);
      } else {
        rmbCell.textContent = grandRmb ? '¥ ' + fmt(grandRmb) : '—';
      }
    }

    // Unit Price (USD) — precise (non-ceiled) conversion shown at 3
    // decimals so ¥0.30 reads as $0.044 like the math actually gives,
    // not the cent-ceiled $0.05 the old path produced. Uses the qty-
    // weighted RMB so multi-row / variant workbooks average correctly.
    const fmt3 = v => v.toLocaleString('en-US', { minimumFractionDigits: 3, maximumFractionDigits: 3 });
    const perUnitUsdPrecise = (grandRmbQty > 0 && USD_TO_RMB > 0)
      ? (grandRmbQtyXPrice / grandRmbQty) / USD_TO_RMB
      : 0;
    const grandUsdPrecise = (USD_TO_RMB > 0) ? (grandRmbQtyXPrice / USD_TO_RMB) : 0;
    const usdCell = document.getElementById('rfq-total-usd-sum');
    if (usdCell) {
      if (hasVariants && pricedItems.length > 0 && isRange) {
        // Mixed-price variants — keep the min–max range using the
        // precise per-unit values for both ends, displayed at 3
        // decimals to match the per-line UNIT PRICE (USD) cells.
        const uMinPrecise = (USD_TO_RMB > 0) ? rmbMin / USD_TO_RMB : 0;
        const uMaxPrecise = (USD_TO_RMB > 0) ? rmbMax / USD_TO_RMB : 0;
        usdCell.textContent = '$' + fmt3(uMinPrecise) + '–$' + fmt3(uMaxPrecise);
      } else {
        usdCell.textContent = perUnitUsdPrecise > 0 ? '$' + fmt3(perUnitUsdPrecise) : '—';
      }
    }

    // Total (USD) — qty × precise per-unit, displayed to the cent. Ties
    // out with the per-line totals (which also use precise USD now).
    document.getElementById('rfq-total-usd').textContent = grandUsdPrecise > 0 ? '$' + fmt(grandUsdPrecise) : '—';
    document.getElementById('rfq-max-lead').textContent  = maxLead  ? maxLead + ' days'   : '—';

    applyRfqRmbToTiers(grandRmb);
    // Keep the collapsed RFQ + Tiered Pricing summary lines in sync.
    if (typeof _updateSectionSummary === 'function') {
      _updateSectionSummary('rfq');
      _updateSectionSummary('tiers');
    }
  }  // end _recalcRfqTotalsInner

  function applyRfqRmbToTiers(totalRmb) {
    const rows = document.querySelectorAll('#wb-tier-body tr');
    if (!rows.length) return;
    // Per-unit RMB price stored on each tier row's dataset.price.
    // Single source of truth: ps.grandRmbWeighted — the qty-weighted
    // average of every priced unit (parents + variants) on the RFQ:
    //   weightedRmb = Σ(qty × rmb) / Σ(qty)
    // Stays in RMB throughout — no USD round-trip and no ceil-to-cent
    // inflation, so an entered ¥0.30 displays as ¥0.300 here, not
    // ¥0.34. Falls back to the legacy totalRmb arg only when the price
    // summary hasn't been built yet (first render before
    // _lastRfqPriceSummary is set).
    //
    // Note on the legacy fallback: the prior `totalRmb` (= grandRmb)
    // was the SUM of parent RMB values across all line items. With
    // multiple line items it inflated tier RMB to the sum (e.g. two
    // rows at ¥0.30 → tier showed ¥0.60). The weighted-average path
    // handles every shape correctly: single row, multi-row, variants,
    // mixed prices.
    //
    // 3-decimal precision so sub-cent prices (¥0.075, ¥0.123) aren't
    // silently truncated and re-inflated on the next render.
    const ps = _lastRfqPriceSummary;
    let perUnitRmb = 0;
    if (ps && ps.grandRmbWeighted > 0) {
      perUnitRmb = ps.grandRmbWeighted;
    } else {
      perUnitRmb = parseFloat(totalRmb) || 0;
    }
    const price = perUnitRmb > 0 ? perUnitRmb.toFixed(3) : '';
    // Cascade price to ALL tier rows (all are view-only, all show the same unit cost)
    rows.forEach(row => { row.dataset.price = price; });
    // Sync qty into first tier row from the RFQ Grand Total qty
    // (sum across every line item + every variant). This is the single
    // source of truth — never just "the first row's qty," which was an
    // accidental legacy: a workbook with two RFQ rows summing to 110,000
    // would otherwise paint tier 1 with just the first row's qty.
    // Fallback to first row only when ps hasn't been computed yet.
    let rfqQty = '';
    if (ps && ps.grandQty > 0) {
      rfqQty = String(ps.grandQty);
    } else {
      const rfqFirstRow = document.querySelector('#rfq-body tr:not([data-rfq-parent]):not([data-rfq-add-for]):first-child');
      const rfqInputs = rfqFirstRow ? rfqFirstRow.querySelectorAll('input:not([type="checkbox"])') : [];
      rfqQty = rfqInputs[2]?.value || '';
    }
    // Tier 1 qty input is type="text" with inputmode="numeric" (so it can
    // hold thousands-separator commas). Grab the first <input> in the row
    // — that's always the qty cell. Setting .value on a readonly input
    // from JS is fine; readonly only blocks user typing.
    const firstTierQtyInput = rows[0].querySelector('input');
    if (firstTierQtyInput && rfqQty) {
      const rawQty = parseInt(_msStripCommasStr(rfqQty), 10);
      firstTierQtyInput.value = rawQty > 0 ? rawQty.toLocaleString('en-US') : '';
    }
    // Recalc all rows
    _syncing = true;
    rows.forEach(row => {
      const id = parseInt(row.id.replace('wb-tier-', ''));
      recalcWbTier(id);
    });
    _syncing = false;
    syncTiersToPricing();
    populateTierDropdown();
  }

  // ── Variant SKU auto-suggestion ────────────────────────────────────
  // Builds a candidate variant SKU = parentSku + initials(variantName).
  // Examples (parent "TW"):
  //   "Small"      → "TWS"
  //   "Medium"     → "TWM"
  //   "Red Small"  → "TWRS"
  //   "Red / Small"→ "TWRS"   (slash is a separator)
  // Words split on whitespace and a few common variant separators;
  // first character of each word is uppercased and concatenated. Pure
  // formatting helper — no DOM access.
  function _suggestVariantSku(parentSku, variantName) {
    const base = (parentSku || '').trim().toUpperCase().replace(/\s+/g, '');
    const initials = (variantName || '')
      .split(/[\s,/·\-_|]+/)
      .filter(Boolean)
      .map(w => w.charAt(0))
      .join('')
      .toUpperCase();
    return base + initials;
  }

  // Fill an auto-mode variant SKU input with the current suggestion.
  // No-op when the row is in manual mode (data-auto-suggested="0") or
  // when there's nothing to derive a suggestion from. Reads the parent
  // SKU + the variant-name input live so it always reflects the
  // current state.
  function _autoSuggestVariantSku(vid) {
    const row = document.getElementById(`rfq-var-${vid}`);
    if (!row) return;
    const skuEl = row.querySelector('.rfq-var-sku-input');
    if (!skuEl) return;
    if (skuEl.dataset.autoSuggested === '0') return;
    const parentId = parseInt(row.dataset.rfqParent);
    const parentRow = document.getElementById(`rfq-${parentId}`);
    if (!parentRow) return;
    const parentSkuInput = parentRow.querySelector('input:not([type="checkbox"])');
    const parentSku = parentSkuInput ? parentSkuInput.value : '';
    const nameInputs = row.querySelectorAll('input:not(.rfq-var-sku-input):not([type="checkbox"])');
    const variantName = nameInputs[0]?.value || '';
    const suggestion = _suggestVariantSku(parentSku, variantName);
    // Don't overwrite with an empty suggestion (parent SKU + variant
    // name both blank) — leave whatever placeholder behaviour shows.
    if (suggestion && skuEl.value !== suggestion) {
      skuEl.value = suggestion;
      // Setting .value programmatically does NOT fire oninput, so we
      // also don't trigger autoSave from here — the calling context
      // (variant-name input, parent-SKU input) already does that.
    }
  }

  // Re-suggest SKUs for every auto-mode variant under one parent. Used
  // when the parent SKU changes — propagates the new prefix downward.
  function _refreshVariantSkusForParent(parentId) {
    document.querySelectorAll(`[data-rfq-parent="${parentId}"]`).forEach(vr => {
      const vid = parseInt((vr.id || '').replace('rfq-var-', ''));
      if (vid) _autoSuggestVariantSku(vid);
    });
  }

  // oninput on the variant SKU itself: user typed → mark manual so
  // future name / parent changes don't overwrite. If they clear the
  // field entirely we flip back to auto and immediately re-suggest.
  function _onVariantSkuInput(vid) {
    const row = document.getElementById(`rfq-var-${vid}`);
    if (!row) return;
    const skuEl = row.querySelector('.rfq-var-sku-input');
    if (!skuEl) return;
    if (skuEl.value.trim() === '') {
      skuEl.dataset.autoSuggested = '1';
      _autoSuggestVariantSku(vid);
    } else {
      skuEl.dataset.autoSuggested = '0';
    }
    if (!_filling) autoSaveWorkbook();
  }

  function addRfqVariantRow(parentId, variant = '', qty = '', priceRmb = '', leadTime = '', sku = '') {
    _rfqVarCount++;
    const vid = _rfqVarCount;
    const tbody = document.getElementById('rfq-body');
    // Inherit parent's RMB price if none supplied
    if (!priceRmb) {
      const parentRow = document.getElementById(`rfq-${parentId}`);
      if (parentRow) {
        const parentInputs = parentRow.querySelectorAll('input:not([type="checkbox"])');
        priceRmb = parentInputs[3]?.value || '';
      }
    }
    const usdVal = priceRmb ? _fxUsdFromRmbPrecise(priceRmb).toFixed(3) : '';
    const totalVal = (qty && usdVal) ? (parseFloat(qty) * parseFloat(usdVal)).toFixed(2) : '';
    const inputStyle = 'width:100%; border:1px solid var(--border); border-radius:8px; padding:10px 14px; font-size:13px; box-sizing:border-box; background:var(--surface2); color:var(--text); font-family:inherit;';
    const tr = document.createElement('tr');
    tr.id = `rfq-var-${vid}`;
    tr.classList.add('rfq-variant-row');
    tr.setAttribute('data-rfq-parent', parentId);
    // Inherit the parent row's background so the variant visually reads
    // as part of the same line item (e.g. orange-highlighted first row →
    // orange-tinted variants underneath; plain row → plain variants).
    try {
      const parentRow = document.getElementById(`rfq-${parentId}`);
      const parentBg = parentRow && parentRow.style && parentRow.style.background;
      if (parentBg) tr.style.background = parentBg;
    } catch (_) {}
    // Drag events must live on the <tr> itself because draggable is set on <tr>
    // (dragstart fires on the draggable element, not on child <td>s)
    tr.ondragover  = function(e) { if (_draggingVarId !== null) { e.preventDefault(); tr.style.borderTop = '2px solid var(--accent)'; } };
    tr.ondragleave = function()  { tr.style.borderTop = ''; };
    tr.ondrop      = function(e) { e.preventDefault(); tr.style.borderTop = ''; rfqDropVariant(vid); };
    tr.ondragstart = function()  { _draggingVarId = vid; tr.style.opacity = '0.4'; };
    tr.ondragend   = function()  { _draggingVarId = null; tr.style.opacity = '1'; tr.draggable = false; };
    // Variant SKU input goes in cell 3 (lines up with parent's SKU
    // column). Auto-suggested mode: data-auto-suggested="1" means a
    // future parent-SKU or variant-name change will refresh this field;
    // "0" means the operator typed something custom, so we leave it
    // alone. On load, an existing non-empty SKU is treated as manual
    // (don't surprise the user by rewriting their saved code); only
    // empty-on-load goes into auto mode.
    const _vSkuAuto = (sku == null || String(sku).trim() === '') ? '1' : '0';
    tr.innerHTML = `
      <td title="Drag to reorder" style="cursor:grab; color:var(--text-muted); text-align:center; padding:0 6px; user-select:none; font-size:12px;"
          onmousedown="this.closest('tr').draggable=true"
          onmouseup="this.closest('tr').draggable=false">☰</td>
      <td></td>
      <td><input type="text" class="rfq-var-sku-input" placeholder="SKU"
            value="${sku}" data-auto-suggested="${_vSkuAuto}"
            oninput="_onVariantSkuInput(${vid})"
            title="Auto-suggested from parent SKU + variant name. Type to override; clear to revert to auto."
            style="${inputStyle}" /></td>
      <td><input type="text" placeholder="e.g. Small / Red…" value="${variant}" oninput="_autoSuggestVariantSku(${vid}); recalcRfqVariantRow(${vid})" style="${inputStyle}" /></td>
      <td><input type="text" inputmode="numeric" placeholder="0" value="${qty}" data-num-int="1"
            oninput="recalcRfqVariantRow(${vid})"
            onfocus="_msStripCommasOnFocus(this)"
            onblur="_msFmtIntOnBlur(this); recalcRfqVariantRow(${vid})"
            style="${inputStyle}" /></td>
      <td><div class="currency-prefix currency-rmb" style="position:relative;"><input type="text" inputmode="decimal" placeholder="0.00" value="${priceRmb}" data-num-dec="1"
            oninput="recalcRfqVariantRow(${vid})"
            onfocus="_msStripCommasOnFocus(this)"
            onblur="_msFmtDecOnBlur(this); recalcRfqVariantRow(${vid})"
            style="${inputStyle} padding-left:28px;" /></div></td>
      <td class="tier-col-usd" id="rfq-var-usd-${vid}" style="color:var(--text); font-size:13px; text-align:right; font-weight:600; padding-right:12px;">${usdVal ? '$' + parseFloat(usdVal).toLocaleString('en-US', {minimumFractionDigits:3, maximumFractionDigits:3}) : '—'}</td>
      <td class="total-cell" id="rfq-var-total-${vid}" style="text-align:right; font-size:13px; padding-right:12px;">${totalVal ? '$' + parseFloat(totalVal).toLocaleString('en-US', {minimumFractionDigits:2}) : '—'}</td>
      <td><div class="lead-time-suffix" style="position:relative;"><input type="text" placeholder="0" value="${leadTime}" oninput="recalcRfqTotals()" style="${inputStyle} padding-right:40px;" /></div></td>
      <td style="text-align:center;"><span class="remove-tier" onclick="removeRfqVariantRow(${vid})" title="Remove variant">&times;</span></td>
    `;
    // Insert after parent row and all its existing variants (but before any trailing add-row)
    const existingVars = [...document.querySelectorAll(`[data-rfq-parent="${parentId}"]`)];
    const anchor = existingVars.length ? existingVars[existingVars.length - 1] : document.getElementById(`rfq-${parentId}`);
    anchor.after(tr);
    _updateVarAddRow(parentId);   // move/create the trailing "+ Add Variant" row
    syncParentQtyFromVariants(parentId);
    recalcRfqTotals();
    // Run the auto-suggest once so a fresh variant (or a loaded one
    // with empty SKU) gets prefilled if there's a parent SKU + name
    // to derive from. Manual-mode rows skip cleanly inside the helper.
    _autoSuggestVariantSku(vid);
    if (!_filling) autoSaveWorkbook();
  }

  // The big full-width "+ Add Variant" row was eating space for the
  // 95% of items that don't use variants. Replaced by a small inline
  // "+ Variant" pill in the parent row's actions cell (see addRfqRow
  // above). This function now just clears any stale add-rows that
  // might be lingering from older saves; it never creates new ones.
  function _updateVarAddRow(parentId) {
    document.querySelector(`[data-rfq-add-for="${parentId}"]`)?.remove();
  }

  function syncParentQtyFromVariants(parentId) {
    const variantRows = document.querySelectorAll(`[data-rfq-parent="${parentId}"]`);
    const parentRow = document.getElementById(`rfq-${parentId}`);
    if (!parentRow) return;
    const parentInputs = parentRow.querySelectorAll('input:not([type="checkbox"])');
    const qtyInput = parentInputs[2];
    if (!qtyInput) return;
    if (variantRows.length > 0) {
      let sum = 0;
      variantRows.forEach(vr => {
        const vi = vr.querySelectorAll('input:not(.rfq-var-sku-input)');
        sum += _msNumFromInput(vi[1]);
      });
      // Write the parent qty with thousand-separator commas so the
      // display matches what the variant rows show after blur. Empty
      // when the sum is 0 (no variant qty filled in yet).
      qtyInput.value = sum > 0 ? sum.toLocaleString('en-US') : '';
      qtyInput.readOnly = true;
      qtyInput.style.opacity = '0.6';
      qtyInput.style.cursor = 'default';
      qtyInput.title = 'Auto-summed from variants';
    } else {
      qtyInput.readOnly = false;
      qtyInput.style.opacity = '';
      qtyInput.style.cursor = '';
      qtyInput.title = '';
    }
    recalcRfqRow(parentId);
  }

  function removeRfqVariantRow(vid) {
    const row = document.getElementById(`rfq-var-${vid}`);
    const parentId = row ? parseInt(row.dataset.rfqParent) : null;
    row?.remove();
    if (parentId) {
      _updateVarAddRow(parentId);   // reposition or remove the trailing add-row
      syncParentQtyFromVariants(parentId);
    }
    recalcRfqTotals();
    if (!_filling) autoSaveWorkbook();
  }

  function rfqDropVariant(targetVid) {
    const srcVid = _draggingVarId;
    _draggingVarId = null;
    if (!srcVid || srcVid === targetVid) return;
    const srcRow = document.getElementById(`rfq-var-${srcVid}`);
    const tgtRow = document.getElementById(`rfq-var-${targetVid}`);
    if (!srcRow || !tgtRow) return;
    // Only allow reorder within the same parent line item
    if (srcRow.dataset.rfqParent !== tgtRow.dataset.rfqParent) return;
    tgtRow.before(srcRow);
    if (!_filling) autoSaveWorkbook();
  }

  function recalcRfqVariantRow(vid) {
    const row = document.getElementById(`rfq-var-${vid}`);
    if (!row) return;
    // Exclude the SKU input so the existing index-based access (qty at
    // [1], price at [2]) keeps working after we added SKU as the first
    // cell input.
    const inputs = row.querySelectorAll('input:not(.rfq-var-sku-input)');
    const qty = _msNumFromInput(inputs[1]);
    const rmb = _msNumFromInput(inputs[2]);
    // 3-decimal precise display matches the parent row so the column
    // reads consistently (no more parent $0.078 vs variants $0.08).
    const usd   = _fxUsdFromRmbPrecise(rmb);
    const total = qty > 0 && usd > 0 ? qty * usd : 0;
    const usdEl = document.getElementById(`rfq-var-usd-${vid}`);
    const totalEl = document.getElementById(`rfq-var-total-${vid}`);
    if (usdEl) usdEl.textContent   = rmb ? '$' + usd.toLocaleString('en-US', {minimumFractionDigits:3, maximumFractionDigits:3}) : '—';
    if (totalEl) totalEl.textContent = (qty && rmb) ? '$' + total.toLocaleString('en-US', {minimumFractionDigits:2, maximumFractionDigits:2}) : '—';
    const parentId = parseInt(row.dataset.rfqParent);
    if (parentId) syncParentQtyFromVariants(parentId);
    recalcRfqTotals();
    if (!_filling) autoSaveWorkbook();
  }

  function collectRfqItems() {
    const rows = document.querySelectorAll('#rfq-body tr:not([data-rfq-parent]):not([data-rfq-add-for])');
    const items = [];
    rows.forEach(row => {
      const id = parseInt(row.id.replace('rfq-', ''));
      const inputs = row.querySelectorAll('input:not([type="checkbox"])');
      const sampleCheck = row.querySelector('.rfq-sample-check');
      const variantRows = document.querySelectorAll(`[data-rfq-parent="${id}"]`);
      const variants = [];
      variantRows.forEach(vr => {
        const vi = vr.querySelectorAll('input:not(.rfq-var-sku-input)');
        const vSkuEl = vr.querySelector('.rfq-var-sku-input');
        // Strip the display commas before saving so detail_json holds
        // raw "1234" not "1,234" — keeps the server-side parsers and
        // the front-end recalc in agreement on values either side of
        // a refresh.
        variants.push({
          sku: (vSkuEl && vSkuEl.value || '').trim(),
          variant: vi[0]?.value || '',
          qty: _msStripCommasStr(vi[1]?.value),
          priceRmb: _msStripCommasStr(vi[2]?.value),
          leadTime: vi[3]?.value || ''
        });
      });
      items.push({
        sku: inputs[0]?.value || '',   // SKU is col 3 → inputs[0]
        item: inputs[1]?.value || '',  // Item is col 4 → inputs[1]
        qty: _msStripCommasStr(inputs[2]?.value),
        priceRmb: _msStripCommasStr(inputs[3]?.value),
        leadTime: inputs[4]?.value || '',
        sample: sampleCheck?.checked || false,
        variants
      });
    });
    return items;
  }

  function toggleRfqSample(checkbox) {
    const row = checkbox.closest('tr');
    const iconSpan = checkbox.nextElementSibling;
    if (checkbox.checked) {
      row.classList.add('rfq-sample-row');
    } else {
      row.classList.remove('rfq-sample-row');
      if (iconSpan) iconSpan.textContent = '';
    }
    if (_appReady) autoSaveWorkbook();
  }

  function rfqDropRow(e, targetId) {
    const draggedId = parseInt(e.dataTransfer.getData('text/plain'));
    const tbody = document.getElementById('rfq-body');
    const firstRow = tbody.querySelector('tr');
    const draggedRow = document.getElementById(`rfq-${draggedId}`);
    const targetRow = document.getElementById(`rfq-${targetId}`);
    // Don't allow dropping onto or moving the first row
    if (draggedRow === firstRow || targetRow === firstRow) return;
    if (draggedRow && targetRow && draggedRow !== targetRow) {
      tbody.insertBefore(draggedRow, targetRow);
      // Move variant rows immediately after the dragged parent
      [...document.querySelectorAll(`[data-rfq-parent="${draggedId}"]`)].forEach(vr => draggedRow.after(vr));
      renumberRfqRows();
      recalcRfqTotals();
      if (!_filling) autoSaveWorkbook();
    }
  }

  // Arrow key navigation within RFQ table
  document.addEventListener('keydown', function(e) {
    const el = document.activeElement;
    if (!el || !el.closest('#rfq-body')) return;
    if (!['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].includes(e.key)) return;
    e.preventDefault();
    const row = el.closest('tr');
    const rows = Array.from(document.querySelectorAll('#rfq-body tr'));
    const inputs = Array.from(row.querySelectorAll('input'));
    const colIdx = inputs.indexOf(el);
    const rowIdx = rows.indexOf(row);
    if (e.key === 'ArrowLeft' && colIdx > 0) inputs[colIdx - 1].focus();
    if (e.key === 'ArrowRight' && colIdx < inputs.length - 1) inputs[colIdx + 1].focus();
    if (e.key === 'ArrowUp' && rowIdx > 0) {
      const prevInputs = rows[rowIdx - 1].querySelectorAll('input');
      if (prevInputs[colIdx]) prevInputs[colIdx].focus();
    }
    if (e.key === 'ArrowDown' && rowIdx < rows.length - 1) {
      const nextInputs = rows[rowIdx + 1].querySelectorAll('input');
      if (nextInputs[colIdx]) nextInputs[colIdx].focus();
    }
  });

  /* ── Tiered Pricing ────────────────────────────────────────────────────── */
  let tierCount = 3;
  let _filling = false; // true while fillWorkbook is running, prevents auto-save
  let _appReady = false; // true after init completes — blocks all saves until then

  function addTierRow(qty = '', unitPrice = '') {
    tierCount++;
    const id = tierCount;
    const tbody = document.getElementById('tier-body');
    const tr = document.createElement('tr');
    tr.id = `tier-${id}`;
    tr.innerHTML = `
      <td class="tier-col-num" style="color:var(--text-muted); font-weight:600;">${id}</td>
      <td style="color:var(--text); font-size:13px;">${qty ? parseFloat(qty).toLocaleString('en-US') : '—'}</td>
      <td style="color:var(--text); font-size:13px;">${unitPrice ? '¥ ' + parseFloat(unitPrice).toLocaleString('en-US', {minimumFractionDigits:2, maximumFractionDigits:2}) : '—'}</td>
      <td class="tier-col-usd" id="tier-usd-${id}" style="color:var(--text-muted); font-size:13px;">—</td>
      <td class="total-cell" id="tier-total-${id}">—</td>
      <td></td>
    `;
    // Store values as data attributes for collectTiers
    tr.dataset.qty = qty;
    tr.dataset.price = unitPrice;
    tbody.appendChild(tr);
    recalcTier(id);
    if (!_filling) autoSaveWorkbook();
  }

  function recalcTier(id) {
    const row    = document.getElementById(`tier-${id}`);
    if (!row) return;
    const qty    = parseFloat(row.dataset.qty);
    const rmb    = parseFloat(row.dataset.price);
    const usd    = rmb / USD_TO_RMB;
    const totalEl = document.getElementById(`tier-total-${id}`);
    const usdEl = document.getElementById(`tier-usd-${id}`);
    if (!isNaN(rmb)) {
      usdEl.textContent = '$' + usd.toLocaleString('en-US', {minimumFractionDigits:2, maximumFractionDigits:2});
    } else {
      usdEl.textContent = '—';
    }
    if (!isNaN(qty) && !isNaN(rmb)) {
      totalEl.textContent = '$' + (qty * usd).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    } else {
      totalEl.textContent = '—';
    }
    if (!_filling && !_syncing) {
      syncTiersToWb();
      calcAdditionalFees();
      autoSaveWorkbook();
    }
  }

  function removeTierRow(id) {
    document.getElementById(`tier-${id}`)?.remove();
    syncTiersToWb();
    calcAdditionalFees();
    autoSaveWorkbook();
  }

  // ── Workbook tab tier pricing (synced with Pricing tab) ──
  let wbTierCount = 0;
  let _syncing = false;
  let _selectedTierId = 1;

  // ── RFQ price summary stash (consumed by Pricing tab + Tiered Pricing) ──
  // Computed inside _recalcRfqTotalsInner; null until first run.
  // Shape: { hasVariants, rmbMin, rmbMax, usdMin, usdMax, isRange, grandQty, grandRmb, grandUsdUnit }
  let _lastRfqPriceSummary = null;

  function addWbTierRow(qty = '', unitPrice = '') {
    wbTierCount++;
    const id = wbTierCount;
    const tbody = document.getElementById('wb-tier-body');
    const tr = document.createElement('tr');
    tr.id = `wb-tier-${id}`;
    // First row: read-only (driven by RFQ total). All others: inherit tier-1 price by default.
    const isFirst = (id === 1);
    // For new non-first rows with no saved price, inherit from tier 1
    if (!isFirst && !unitPrice) {
      const tier1 = document.getElementById('wb-tier-1');
      if (tier1 && tier1.dataset.price) unitPrice = tier1.dataset.price;
    }
    tr.dataset.price = unitPrice || '';
    // Tier 1: Unit Price (RMB) is read-only — driven by the RFQ Grand
    // Total (auto-mirrored). All other tiers: Unit Price (RMB) is an
    // input so the operator can dial in quantity-discount pricing for
    // tiers 2, 3, 4… The value writes back to row.dataset.price (the
    // single source of truth for tier pricing).
    const rmbCell = isFirst
      ? `<td id="wb-tier-rmb-${id}" style="font-size:13px; color:var(--text-muted);">
           <span id="wb-tier-rmb-val-${id}">—</span>
         </td>`
      : `<td id="wb-tier-rmb-${id}" style="font-size:13px;">
           <div class="currency-prefix currency-rmb" style="position:relative;">
             <input type="text" inputmode="decimal" placeholder="0.00" data-num-dec="1"
                    id="wb-tier-rmb-input-${id}"
                    value="${unitPrice || ''}"
                    oninput="onWbTierRmbInput(${id})"
                    onfocus="_msStripCommasOnFocus(this)"
                    onblur="_msFmtDecOnBlur(this); onWbTierRmbInput(${id})"
                    style="width:120px; padding-left:24px;"
                    autocomplete="off" data-1p-ignore="true" data-lpignore="true" />
           </div>
         </td>`;
    tr.innerHTML = `
      <td class="tier-col-num" style="color:var(--text-muted); font-weight:600;">${id}</td>
      <td>
        <input type="text" inputmode="numeric" placeholder="e.g. 100" value="${qty}" data-num-int="1"
               oninput="recalcWbTier(${id})"
               onfocus="_msStripCommasOnFocus(this)"
               onblur="_msFmtIntOnBlur(this); recalcWbTier(${id})"
               style="width:110px;${isFirst ? ' background:var(--surface2); color:var(--text-muted); cursor:not-allowed;' : ''}"
               ${isFirst ? 'readonly title="Auto-populated from Quote Details qty"' : ''} />
      </td>
      ${rmbCell}
      <td class="tier-col-usd" id="wb-tier-usd-${id}" style="color:var(--text-muted); font-size:13px;">—</td>
      <td class="total-cell" id="wb-tier-total-${id}">—</td>
      <td>${isFirst ? '' : `<button class="btn btn-danger-ghost" onclick="removeWbTierRow(${id})">✕</button>`}</td>
    `;
    tbody.appendChild(tr);
    recalcWbTier(id);
  }

  function recalcWbTier(id) {
    const row = document.getElementById(`wb-tier-${id}`);
    const inputs = row.querySelectorAll('input');
    // Comma-tolerant reads — qty input can hold "1,234" after blur, and
    // dataset.price gets written by onWbTierRmbInput which also strips
    // before saving so it stays raw on disk.
    const qty = _msNumFromInput(inputs[0]);
    const rmb = parseFloat(_msStripCommasStr(row.dataset.price));
    // USD per-unit ceil-rounded to the cent (consistent with how the
    // Pricing tab Product Cost block displays the same tier).
    const usd = !isNaN(rmb) && rmb > 0 ? _fxUsdFromRmb(rmb) : NaN;
    const rmbValEl = document.getElementById(`wb-tier-rmb-val-${id}`);
    const usdEl = document.getElementById(`wb-tier-usd-${id}`);
    const totalEl = document.getElementById(`wb-tier-total-${id}`);

    // Variant-aware display: when the RFQ has variants at different
    // prices, tier 1 mirrors the RFQ Grand Total range so the auto-
    // populated row reads consistently with the Workbook tab. Tiers
    // 2+ are operator-controlled — the RMB input drives the row's
    // own RMB / USD / total even on variant workbooks. Without this
    // bypass, typing a manual RMB into tier 2/3/4 on a variant
    // workbook left the USD frozen at the variant min/max range
    // because the range-display branch ignored the tier's own price.
    const fmt2 = v => v.toLocaleString('en-US', {minimumFractionDigits:2, maximumFractionDigits:2});
    // Per-unit prices show three decimals here (matches the Pricing
    // tab Product Cost block) so qty × per-unit reconciles to the
    // Tier Total without ceil-to-cent drift on big orders.
    const fmt3 = v => v.toLocaleString('en-US', {minimumFractionDigits:3, maximumFractionDigits:3});
    const ps   = _lastRfqPriceSummary;
    // Be tolerant of either numeric or string id — the tier counter
    // is always a number, but a future caller passing the row id as
    // a string would otherwise silently fall back to the variant-
    // range branch.
    const isFirstTier = (parseInt(id, 10) === 1);
    const useRange = isFirstTier && ps && ps.hasVariants && ps.rmbMin > 0;

    if (rmbValEl) {
      // Only tier 1 has a label-style RMB cell (rmbValEl exists). For
      // tiers 2+ this element is null (the cell is an input the operator
      // controls directly), so skip painting.
      if (useRange) {
        rmbValEl.textContent = ps.isRange
          ? '¥ ' + fmt3(ps.rmbMin) + '–¥ ' + fmt3(ps.rmbMax)
          : '¥ ' + fmt3(ps.rmbMin);
      } else {
        rmbValEl.textContent = (!isNaN(rmb) && rmb > 0) ? '¥ ' + fmt3(rmb) : '—';
      }
    }
    if (usdEl) {
      if (useRange) {
        // Variant USD range — convert from raw RMB so the displayed
        // value reflects the actual per-unit cost at three decimals.
        const rateUsd = USD_TO_RMB > 0 ? USD_TO_RMB : 7.2;
        const _vUsdMin = ps.rmbMin / rateUsd;
        const _vUsdMax = ps.rmbMax / rateUsd;
        usdEl.textContent = ps.isRange
          ? '$' + fmt3(_vUsdMin) + '–$' + fmt3(_vUsdMax)
          : '$' + fmt3(_vUsdMin);
      } else {
        // Single-tier USD — use the raw division so the per-unit
        // display tracks RMB exactly. (`usd` declared above as
        // `_fxUsdFromRmb(rmb)` ceils to cents — bypass it here.)
        const rateUsd = USD_TO_RMB > 0 ? USD_TO_RMB : 7.2;
        usdEl.textContent = (!isNaN(rmb) && rmb > 0) ? '$' + fmt3(rmb / rateUsd) : '—';
      }
    }
    if (totalEl) {
      // Total ceil-rounded to the cent so it ties to the ceil per-unit
      // displayed above (and to the Pricing tab Product Cost total).
      if (useRange && !isNaN(qty) && qty > 0 && ps.grandQty > 0 && ps.grandUsd > 0) {
        const avgUsd = ps.grandUsd / ps.grandQty;
        totalEl.textContent = '$' + fmt2(_msCeil2(qty * avgUsd));
      } else if (!isNaN(qty) && !isNaN(rmb) && rmb > 0) {
        totalEl.textContent = '$' + fmt2(_msCeil2(qty * (rmb / USD_TO_RMB)));
      } else {
        totalEl.textContent = '—';
      }
    }
    if (!_filling && !_syncing) {
      syncTiersToPricing();
      populateTierDropdown();
      autoSaveWorkbook();
    }
  }

  // Manual Unit Price (RMB) input on tier rows 2+ — writes back to the
  // row's dataset.price (single source of truth) and re-runs the
  // standard tier recalc so USD + Total update. dataset.price stays
  // raw (no commas) so downstream parsers see clean numbers; the
  // input display can show "1,234.56" without breaking the math.
  function onWbTierRmbInput(id) {
    const row   = document.getElementById(`wb-tier-${id}`);
    const input = document.getElementById(`wb-tier-rmb-input-${id}`);
    if (!row || !input) return;
    row.dataset.price = _msStripCommasStr(input.value);
    recalcWbTier(id);
  }

  function removeWbTierRow(id) {
    document.getElementById(`wb-tier-${id}`)?.remove();
    syncTiersToPricing();
    populateTierDropdown();
    autoSaveWorkbook();
  }

  // Maps the dropdown's currently-selected value to the underlying
  // tier id for wb-tier-${id} lookups. When a pitch is selected
  // (value "pitch-half" / "pitch-full"), fall back to tier 1 for the
  // per-unit price source — qty comes from pallet-total-cartons via
  // the existing effectiveQty path.
  function _msTierIdForLookup(id) {
    if (typeof id === 'string' && id.indexOf('pitch-') === 0) return 1;
    return id;
  }
  function populateTierDropdown() {
    const sel = document.getElementById('sh-tier-select');
    if (!sel) return;
    const prev = _selectedTierId;
    sel.innerHTML = '<option value="">— Select a tier —</option>';
    // ── Applied-pitch synthetic option ─────────────────────────────
    // When the operator has pressed Apply Half / Apply Full in the
    // Hypothetical Scenarios panel, surface that as the active
    // selection in the Shipping tab so the dropdown reflects what's
    // being quoted instead of staying locked to a stale tier number.
    const snap = window._fullContainerPitchSnap;
    if (snap && snap.pitchKind) {
      const pitchLabel = snap.pitchKind === 'half' ? 'Half Container Pitch (LCL)' : 'Full Container Pitch';
      const pitchQty = parseInt(snap.appliedQty) || 0;
      const opt = document.createElement('option');
      opt.value = 'pitch-' + snap.pitchKind;
      opt.textContent = `★ ${pitchLabel} — ${pitchQty.toLocaleString('en-US')} units (applied)`;
      opt.dataset.qty = pitchQty;
      opt.dataset.pitchKind = snap.pitchKind;
      sel.appendChild(opt);
    }
    document.querySelectorAll('#wb-tier-body tr').forEach(row => {
      const id = parseInt(row.id.replace('wb-tier-', ''));
      const inputs = row.querySelectorAll('input');
      const qty = inputs[0]?.value;
      const rmb = parseFloat(_msStripCommasStr(row.dataset.price));
      const usd = !isNaN(rmb) && rmb > 0 ? rmb / USD_TO_RMB : NaN;
      // Tier qty inputs hold "110,000" after the blur formatter runs.
      // parseInt stops at the comma → 110, which makes the dropdown
      // read "Tier 1 — 110 units" when the real value is 110,000.
      // Strip commas first (same fix that hit the section summary).
      const qtyRaw = qty ? (parseInt(_msStripCommasStr(qty), 10) || 0) : 0;
      let label = `Tier ${id}`;
      if (qtyRaw > 0) label += ` — ${qtyRaw.toLocaleString('en-US')} units`;
      const opt = document.createElement('option');
      opt.value = id;
      opt.textContent = label;
      opt.dataset.qty = qtyRaw;
      sel.appendChild(opt);
    });
    // Auto-select the pitch option whenever a pitch is applied —
    // the operator wants the Shipping tab to reflect the committed
    // pitch without needing to manually click the dropdown.
    if (snap && snap.pitchKind) {
      sel.value = 'pitch-' + snap.pitchKind;
      _selectedTierId = sel.value;
      renderShippingTierDetails(sel.value);
    } else if (prev && sel.querySelector(`option[value="${prev}"]`)) {
      // Restore previous selection if still valid (regular tier).
      // Strip stale pitch-* prefixes left over from a pre-revert state.
      const restoreVal = (typeof prev === 'string' && prev.indexOf('pitch-') === 0) ? null : prev;
      if (restoreVal && sel.querySelector(`option[value="${restoreVal}"]`)) {
        sel.value = restoreVal;
        renderShippingTierDetails(restoreVal);
      } else {
        _selectedTierId = null;
        document.getElementById('sh-tier-details')?.classList.remove('visible');
      }
    } else {
      _selectedTierId = null;
      document.getElementById('sh-tier-details')?.classList.remove('visible');
    }
  }

  function onShippingTierSelect() {
    const sel = document.getElementById('sh-tier-select');
    if (!sel) return;
    const val = sel.value;
    // Pitch sentinel ("pitch-half" / "pitch-full") is stored as a
    // string. Regular tier ids are stored as integers. Downstream
    // wb-tier-${id} lookups go through _msTierIdForLookup() which
    // maps the sentinel back to tier 1 for the per-unit price.
    if (typeof val === 'string' && val.indexOf('pitch-') === 0) {
      _selectedTierId = val;
      renderShippingTierDetails(val);
    } else {
      const id = val ? parseInt(val) : null;
      _selectedTierId = id || null;
      renderShippingTierDetails(id);
    }
    if (_appReady) autoSaveWorkbook();
  }

  function renderShippingTierDetails(id) {
    const detailBar = document.getElementById('sh-tier-details');
    // ── Pitch-applied path ────────────────────────────────────
    // When the synthetic pitch option is selected, source qty from
    // the applied pitch snapshot and per-unit price from tier 1
    // (the baseline RFQ-driven price). Total Product Cost = pitch
    // qty × tier-1 per-unit.
    if (typeof id === 'string' && id.indexOf('pitch-') === 0) {
      const snap = window._fullContainerPitchSnap;
      const tier1 = document.getElementById('wb-tier-1');
      if (!snap || !tier1) {
        if (detailBar) detailBar.classList.remove('visible');
        return;
      }
      const qtyP = parseInt(snap.appliedQty) || 0;
      const rmbP = parseFloat(_msStripCommasStr(tier1.dataset.price)) || 0;
      const usdP = rmbP > 0 ? _fxUsdFromRmb(rmbP) : 0;
      const fmt2P = v => v.toLocaleString('en-US', {minimumFractionDigits:2, maximumFractionDigits:2});
      const psP = _lastRfqPriceSummary;
      const useRangeP = psP && psP.hasVariants && psP.rmbMin > 0;
      let rmbTextP, usdTextP, totalTextP;
      if (useRangeP) {
        rmbTextP = psP.isRange ? '¥ ' + fmt2P(psP.rmbMin) + '–¥ ' + fmt2P(psP.rmbMax) : '¥ ' + fmt2P(psP.rmbMin);
        usdTextP = psP.isRange ? '$' + fmt2P(psP.usdMin) + '–$' + fmt2P(psP.usdMax) : '$' + fmt2P(psP.usdMin);
      } else {
        rmbTextP = rmbP > 0 ? '¥ ' + fmt2P(rmbP) : '—';
        usdTextP = usdP > 0 ? '$' + fmt2P(usdP) : '—';
      }
      if (useRangeP && qtyP > 0 && psP.grandQty > 0 && psP.grandUsd > 0) {
        totalTextP = '$' + fmt2P(qtyP * (psP.grandUsd / psP.grandQty));
      } else if (qtyP > 0 && usdP > 0) {
        totalTextP = '$' + fmt2P(qtyP * usdP);
      } else {
        totalTextP = '—';
      }
      const rmbEl = document.getElementById('sh-td-rmb-full');
      const usdEl = document.getElementById('sh-td-usd-full');
      const totEl = document.getElementById('sh-td-total');
      if (rmbEl) rmbEl.textContent = rmbTextP;
      if (usdEl) usdEl.textContent = usdTextP;
      if (totEl) totEl.textContent = totalTextP;
      if (detailBar) detailBar.classList.add('visible');
      if (typeof renderPricingTab === 'function') renderPricingTab();
      if (typeof calcFreight === 'function') calcFreight();
      return;
    }
    const row = id ? document.getElementById(`wb-tier-${id}`) : null;
    if (!row) {
      if (detailBar) detailBar.classList.remove('visible');
      return;
    }
    const inputs = row.querySelectorAll('input');
    const qty = inputs[0]?.value || '';
    const rmb = parseFloat(_msStripCommasStr(row.dataset.price));
    const usd = !isNaN(rmb) && rmb > 0 ? rmb / USD_TO_RMB : NaN;

    // Variant-aware unit price + total — mirrors RFQ Grand Total + tier rows.
    // Range on the unit price columns when variants vary; total stays a
    // single exact value via the weighted-avg path (tier qty × grandUsd/grandQty).
    // Strip commas before parsing — qty input holds "110,000" after blur
    // formatting, and parseFloat would stop at the comma → 110, making
    // every downstream tier total off by 1000×.
    const fmt2 = v => v.toLocaleString('en-US', {minimumFractionDigits:2, maximumFractionDigits:2});
    const ps   = _lastRfqPriceSummary;
    const useRange = ps && ps.hasVariants && ps.rmbMin > 0;
    const qtyNum   = parseFloat(_msStripCommasStr(qty));

    let rmbText, usdText, totalText;
    if (useRange) {
      rmbText = ps.isRange ? '¥ ' + fmt2(ps.rmbMin) + '–¥ ' + fmt2(ps.rmbMax) : '¥ ' + fmt2(ps.rmbMin);
      usdText = ps.isRange ? '$' + fmt2(ps.usdMin) + '–$' + fmt2(ps.usdMax) : '$' + fmt2(ps.usdMin);
    } else {
      rmbText = (!isNaN(rmb) && rmb > 0) ? '¥ ' + fmt2(rmb) : '—';
      usdText = !isNaN(usd) ? '$' + fmt2(usd) : '—';
    }
    if (useRange && !isNaN(qtyNum) && qtyNum > 0 && ps.grandQty > 0 && ps.grandUsd > 0) {
      totalText = '$' + fmt2(qtyNum * (ps.grandUsd / ps.grandQty));
    } else if (!isNaN(qtyNum) && !isNaN(usd)) {
      totalText = '$' + fmt2(qtyNum * usd);
    } else {
      totalText = '—';
    }

    document.getElementById('sh-td-rmb-full').textContent = rmbText;
    document.getElementById('sh-td-usd-full').textContent = usdText;
    document.getElementById('sh-td-total').textContent    = totalText;
    if (detailBar) detailBar.classList.add('visible');
    renderPricingTab();

    // Recalculate total outer cartons for this tier qty and refresh freight
    const tierQty        = parseInt(_msStripCommasStr(qty), 10) || 0;
    const unitsPerInner  = parseInt(document.getElementById('carton-inner-count')?.value) || 0;
    const innersPerOuter = parseInt(document.getElementById('carton-outer-count')?.value) || 0;
    const unitsPerOuter  = unitsPerInner * innersPerOuter;
    const innerWeightKg  = parseFloat(document.getElementById('carton-inner-weight')?.value) || 0;
    const unitWeightKg   = parseFloat(document.getElementById('dim-weight-kg')?.value) || 0;
    const outerWeightKg  = parseFloat(document.getElementById('carton-outer-weight')?.value) || 0;
    const palletEl = document.getElementById('pallet-total-cartons');

    // Derive effective unit weight: prefer explicit dim-weight-kg, fall back to inner_weight / inner_count
    const effectiveUnitWt = unitWeightKg > 0 ? unitWeightKg :
      (innerWeightKg > 0 && unitsPerInner > 0 ? innerWeightKg / unitsPerInner : 0);

    // The input #pallet-total-cartons is now the "Total Units to
    // Ship" field — the operator's authoritative unit count. This
    // function used to also stomp it with the DERIVED CARTON COUNT
    // (ceil(tierQty / unitsPerOuter)) whenever a tier was picked,
    // which is why the field kept reverting to e.g. "30" instead of
    // the 5,925-unit RFQ Grand Total after a hard refresh.
    // The write is gone; downstream freight / pallet code derives
    // carton count from the units field directly, so nothing else
    // breaks. The unit-weight backfill below is preserved — that's
    // a real ergonomic fill that only writes to carton-outer-weight
    // when both inner_count and a usable outer weight are missing.
    if (tierQty > 0
        && unitsPerOuter <= 0
        && !(effectiveUnitWt > 0 && outerWeightKg > 0 && outerWeightKg >= effectiveUnitWt)
        && effectiveUnitWt > 0) {
      const outerWtEl = document.getElementById('carton-outer-weight');
      if (outerWtEl) {
        outerWtEl.value = effectiveUnitWt.toFixed(3);
        convertWeight('carton-outer-weight', 'carton-outer-weight-lbs', 'kg');
      }
    }
    if (typeof renderPalletViz === 'function') renderPalletViz();
    if (typeof calcFreight === 'function')      calcFreight();
  }

  function collectTiersFrom(tbodyId) {
    const rows = document.querySelectorAll(`#${tbodyId} tr`);
    const tiers = [];
    rows.forEach(row => {
      const inputs = row.querySelectorAll('input');
      if (inputs.length >= 1) {
        // Strip the display commas before saving so detail_json holds
        // raw "1234" — keeps front-end and server-side parsers aligned
        // across a refresh.
        tiers.push({
          qty: _msStripCommasStr(inputs[0].value),
          price: _msStripCommasStr(row.dataset.price)
        });
      }
    });
    return tiers;
  }

  function syncTiersToPricing() {
    if (_syncing) return;
    _syncing = true;
    const tiers = collectTiersFrom('wb-tier-body');
    document.getElementById('tier-body').innerHTML = '';
    tierCount = 0;
    tiers.forEach(t => addTierRow(t.qty, t.price));
    _syncing = false;
  }

  function syncTiersToWb() {
    if (_syncing) return;
    _syncing = true;
    const tiers = collectTiersFrom('tier-body');
    document.getElementById('wb-tier-body').innerHTML = '';
    wbTierCount = 0;
    tiers.forEach(t => addWbTierRow(t.qty, t.price));
    _syncing = false;
  }

  /* ── Shipment Splits ───────────────────────────────────────────────────── */
  let _shipmentSplits = [];
  let _splitCounter = 0;

  const SPLIT_METHOD_LABELS = { slow: 'Slow Boat', fast: 'Fast Boat', airupp: 'Air + UPS', directair: 'Direct Air' };

  function calcSplitCost(method, qty) {
    qty = parseInt(qty) || 0;
    if (qty <= 0) return null;
    const get = id => parseFloat(document.getElementById(id)?.value) || 0;
    const lCm      = get('carton-outer-l-cm');
    const wCm      = get('carton-outer-w-cm');
    const hCm      = get('carton-outer-h-cm');
    const actualKg = get('carton-outer-weight');
    const innerCount = parseInt(document.getElementById('carton-inner-count')?.value) || 0;
    const outerCount = parseInt(document.getElementById('carton-outer-count')?.value) || 0;
    const unitsPerOuter = innerCount * outerCount;
    if (!lCm || !wCm || !hCm || !actualKg || unitsPerOuter <= 0) return null;
    const cartons  = Math.ceil(qty / unitsPerOuter);
    const rate     = freightMethodRates[method] || freightMethodRates.slow;
    const divisor  = freightMethodDivisors[method] || freightMethodDivisors.slow;
    const volWeight = (lCm * wCm * hCm) / divisor;
    const chargePerCarton = Math.max(actualKg, volWeight);
    const totalCharge = chargePerCarton * cartons;
    const rmb = totalCharge * rate;
    const usd = rmb / USD_TO_RMB;
    const fmt2 = v => v.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    // Raw rmb / usd are exposed alongside the formatted strings so the
    // Pricing tab's Shipping Cost block can sum across splits and
    // display a breakdown without having to re-derive the math.
    // chargeableKg is what the Pricing tab calls "Total Weight"; we
    // expose it per split so the Mixed-method breakdown can show
    // weight per split for visual reconciliation with the freight
    // comparison table on the Shipping tab.
    const chargeableKg = chargePerCarton * cartons;
    return {
      rmb, usd, cartons, chargeableKg, rate,
      rmbStr: `¥${fmt2(rmb)}`,
      usdStr: `$${fmt2(usd)}`,
    };
  }

  function addShipmentSplit() {
    _splitCounter++;
    _shipmentSplits.push({ id: _splitCounter, method: 'slow', qty: '' });
    renderShipmentSplits();
    _refreshPricingForSplits();
    autoSaveWorkbook();
  }

  function removeShipmentSplit(id) {
    _shipmentSplits = _shipmentSplits.filter(r => r.id !== id);
    renderShipmentSplits();
    _refreshPricingForSplits();
    autoSaveWorkbook();
  }

  function onSplitChange(id, field, value) {
    const row = _shipmentSplits.find(r => r.id === id);
    if (!row) return;
    row[field] = value;
    // Update the cost span in-place so the qty input doesn't lose focus
    const costEl = document.getElementById(`split-cost-${id}`);
    if (costEl) {
      costEl.innerHTML = _buildSplitCostInline(row, calcSplitCost(row.method, row.qty));
    }
    renderShipmentSplitSummary();
    _refreshPricingForSplits();
    autoSaveWorkbook();
  }

  // Splits feed the Pricing tab's "Added Shipping Cost" upgrade fee
  // (premium = cost(splitMethod, qty) − cost(baseMethod, qty)). When
  // a split changes, recompute calcFreight (its costs shown on the
  // Shipping tab) AND renderPricingTab (which rebuilds the upgrade
  // fee cache + the Additional Fees row + Shipping Cost numbers).
  // Guarded so we don't crash before the renderers are wired.
  function _refreshPricingForSplits() {
    if (typeof calcFreight === 'function') {
      try { calcFreight(); } catch (_) {}
    }
    if (typeof renderPricingTab === 'function') {
      try { renderPricingTab(); } catch (_) {}
    }
  }

  function renderShipmentSplits() {
    const body = document.getElementById('shipment-split-body');
    if (!body) return;
    if (_shipmentSplits.length === 0) {
      body.innerHTML = `<div style="font-size:12px; color:var(--text-muted); font-style:italic; padding:4px 0;">No splits defined — full quantity ships as one.</div>`;
      renderShipmentSplitSummary();
      return;
    }
    body.innerHTML = _shipmentSplits.map(row => {
      const cost = calcSplitCost(row.method, row.qty);
      // _buildSplitCostInline renders the per-split math breakdown
      // (cartons × kg × ¥/kg = ¥total / $total) when the carton specs
      // are complete; falls back to "needs carton specs" when they
      // aren't so the operator can see WHY the cost is blank.
      const costHtml = _buildSplitCostInline(row, cost);
      return `<div style="display:flex; align-items:center; gap:8px; margin-bottom:6px; flex-wrap:wrap;">
        <input type="number" min="0" step="1" value="${row.qty}"
          style="width:80px; height:32px; padding:0 8px; border:1px solid var(--border); border-radius:var(--radius-sm); background:var(--surface2); color:var(--text); font-size:13px; font-family:inherit; outline:none; flex-shrink:0;"
          oninput="onSplitChange(${row.id}, 'qty', this.value)" placeholder="Qty" />
        <span style="font-size:12px; color:var(--text-muted); white-space:nowrap; flex-shrink:0;">units →</span>
        <div class="ship-select-wrap" style="width:140px; flex-shrink:0;">
          <select onchange="onSplitChange(${row.id}, 'method', this.value)"
            style="width:100%; height:32px; padding:0 28px 0 10px; border:1px solid var(--border); border-radius:var(--radius-sm); background:var(--surface2); color:var(--text); font-size:13px; font-family:inherit; outline:none; cursor:pointer; appearance:none; -webkit-appearance:none;">
            ${Object.entries(SPLIT_METHOD_LABELS).map(([k,v]) => `<option value="${k}"${row.method===k?' selected':''}>${v}</option>`).join('')}
          </select>
        </div>
        <span id="split-cost-${row.id}" style="flex:1; min-width:160px; text-align:right; font-size:12px;">${costHtml}</span>
        <button onclick="removeShipmentSplit(${row.id})"
          style="background:none; border:none; cursor:pointer; color:var(--text-muted); font-size:16px; padding:2px 6px; border-radius:var(--radius-sm); transition:color 0.15s; flex-shrink:0;"
          onmouseover="this.style.color='#ef4444'" onmouseout="this.style.color='var(--text-muted)'">×</button>
      </div>`;
    }).join('');
    renderShipmentSplitSummary();
  }

  // Build the inline cost cell for a split row. When calcSplitCost
  // returned a value, show the actual math the cost derives from —
  // "6 ctn × 0.60 kg × ¥48/kg = ¥172.80 / $25.32" — so the operator
  // can sanity-check the number against the comparison table above
  // without doing arithmetic in their head. The math expression is
  // muted; the ¥ + $ totals stay bold and full-color so the eye
  // lands on the headline value first.
  function _buildSplitCostInline(row, cost) {
    if (!cost) {
      const q = parseInt(row.qty) || 0;
      if (q <= 0) return '<span style="color:var(--text-muted); font-style:italic;">enter a qty</span>';
      return '<span style="color:#dc2626; font-style:italic;">add carton specs to compute cost</span>';
    }
    const fmt2 = v => (v || 0).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    const perCarton = cost.cartons > 0 ? (cost.chargeableKg / cost.cartons) : 0;
    const mathStr = `${cost.cartons} ctn × ${fmt2(perCarton)} kg × ¥${fmt2(cost.rate)}/kg`;
    return `<span style="color:var(--text-muted); margin-right:6px; font-family:'SF Mono','Consolas',monospace; font-size:11px;">${mathStr} =</span>`
         + `<span style="color:var(--text); font-weight:700; font-family:'SF Mono','Consolas',monospace;">¥${fmt2(cost.rmb)}</span>`
         + `<span style="color:var(--text-muted); margin:0 6px;">·</span>`
         + `<span style="color:var(--text); font-weight:700; font-family:'SF Mono','Consolas',monospace;">$${fmt2(cost.usd)}</span>`;
  }

  function renderShipmentSplitSummary() {
    const el = document.getElementById('shipment-split-summary');
    if (!el) return;
    if (_shipmentSplits.length === 0) { el.textContent = ''; return; }
    const total = _shipmentSplits.reduce((s, r) => s + (parseInt(r.qty) || 0), 0);
    // Get selected tier qty — read from the data-qty attribute stored on the selected option
    const tierQty = (() => {
      const sel = document.getElementById('sh-tier-select');
      if (!sel || !sel.value) return 0;
      const opt = sel.options[sel.selectedIndex];
      return opt ? (parseInt(opt.dataset.qty) || 0) : 0;
    })();
    const parts = Object.entries(
      _shipmentSplits.reduce((acc, r) => {
        const m = r.method || 'slow';
        acc[m] = (acc[m] || 0) + (parseInt(r.qty) || 0);
        return acc;
      }, {})
    ).map(([m, q]) => `${q.toLocaleString('en-US')} ${SPLIT_METHOD_LABELS[m] || m}`).join(' · ');
    const isOver = tierQty > 0 && total > tierQty;
    const totalStyle = isOver ? 'font-weight:600; color:#ef4444;' : 'font-weight:600;';
    const overMsg = isOver ? ` <span style="color:#ef4444; font-weight:600;">⚠ exceeds tier qty of ${tierQty.toLocaleString('en-US')}</span>` : '';

    // Grand total cost across all splits — sum the per-split rmb/usd
    // figures (calcSplitCost is the same function each row uses to
    // render its inline cost so the headline always ties out).
    let _gtRmb = 0, _gtUsd = 0, _anyMissing = false;
    _shipmentSplits.forEach(r => {
      const q = parseInt(r.qty) || 0;
      if (q <= 0) return;
      const c = calcSplitCost(r.method, q);
      if (!c) { _anyMissing = true; return; }
      _gtRmb += c.rmb;
      _gtUsd += c.usd;
    });
    const fmt2 = v => v.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    const gtRmbStr = _gtUsd > 0 ? `¥${fmt2(_gtRmb)}` : '';
    const gtUsdStr = _gtUsd > 0 ? `$${fmt2(_gtUsd)}` : '';
    const gtHtml = _gtUsd > 0
      ? `<div style="display:flex; justify-content:space-between; align-items:baseline; margin-top:6px; padding-top:6px; border-top:1px solid var(--border); font-size:13px;">
           <span style="font-weight:700;">Splits Grand Total</span>
           <span style="display:flex; gap:12px; align-items:baseline;">
             <span style="font-family:'SF Mono','Consolas',monospace; font-weight:700;">${gtRmbStr}</span>
             <span style="color:var(--text-muted);">·</span>
             <span style="font-family:'SF Mono','Consolas',monospace; font-weight:700;">${gtUsdStr}</span>
           </span>
         </div>`
      : (_anyMissing
          ? `<div style="margin-top:6px; padding-top:6px; border-top:1px solid var(--border); font-size:12px; color:#dc2626;">Carton specs missing on one or more splits — grand total can't be computed yet.</div>`
          : '');

    el.innerHTML = `<div><span style="${totalStyle}">${total.toLocaleString('en-US')} total</span> &nbsp;·&nbsp; ${parts}${overMsg}</div>${gtHtml}`;
    el.style.color = isOver ? '#ef4444' : '';
  }

  function collectShipmentSplits() {
    return _shipmentSplits.map(r => ({ method: r.method, qty: parseInt(r.qty) || 0 })).filter(r => r.qty > 0);
  }

  /* ── Additional Fees ───────────────────────────────────────────────────── */
  let _extraFeeRows = [];
  let _extraFeeCounter = 0;
  // Set of fee IDs that the operator has ticked on the Pricing tab to
  // include in the Total Landed Cost + the Client Quote line items.
  // Standard fees are keyed by their short name ('sample','tooling',
  // 'die','plate','design'); extra fees by 'extra:<id>'. Persisted as
  // an array on workbookDetail.appliedFees.
  let _appliedFees = new Set();
  // Per-fee override amounts (USD). When an operator ticks a fee on the
  // Pricing tab they can also edit its USD amount in-place — the "as is"
  // workbook value stays as a reference, and this map carries whatever
  // they typed. Keyed by fee id (same id space _appliedFees uses, incl.
  // synthetic '__shipup_*' upgrade fees). Empty / cleared input deletes
  // the entry → fee falls back to its source (Workbook tab) amount.
  // Persisted alongside _appliedFees in detail_json.appliedFeeOverrides.
  let _appliedFeeOverrides = Object.create(null);
  function _hasFeeOverride(id) { return Object.prototype.hasOwnProperty.call(_appliedFeeOverrides, id); }
  function _getAppliedFeeAmount(fee) {
    if (!fee) return 0;
    if (_hasFeeOverride(fee.id)) {
      const v = parseFloat(_appliedFeeOverrides[fee.id]);
      return isFinite(v) ? v : 0;
    }
    return parseFloat(fee.usd) || 0;
  }
  // Synthetic "shipment upgrade" fees — the premium of shipping a split
  // via a faster method vs. the base/dropdown method. These aren't
  // entered on the Workbook tab; _renderPricingTabInner recomputes them
  // every render and parks them here so appliedFeesTotalUsd /
  // appliedFeesList can fold them into the Total Landed Cost + Client
  // Quote when their checkbox is ticked. IDs are '__shipup_<methodKey>'
  // (e.g. '__shipup_airupp'); they persist in _appliedFees like any
  // other applied fee but are excluded from the prune step in
  // renderPricingFeesCard (they have no Workbook-tab counterpart).
  let _shipUpgradeFeeCache = [];
  function _shipmentUpgradeFees() { return Array.isArray(_shipUpgradeFeeCache) ? _shipUpgradeFeeCache : []; }
  // Compute the shipment-upgrade premium for every split that ships via
  // a costlier method than the base/dropdown method. One synthetic fee
  // per upgraded method, aggregated across same-method splits:
  //   premium = cost(splitMethod, qty) − cost(baseMethod, qty)
  // Returns [] when there are no splits, a manual shipping override is
  // active, or carton specs are missing (cost can't be derived). Reads
  // only globals (_shipmentSplits, freight-mode, calcSplitCost) so it
  // can run early in _renderPricingTabInner, before the applied-fee
  // totals are read.
  function _computeShipUpgradeFeeCache() {
    const cache = [];
    if (typeof _shipmentSplits === 'undefined' || !Array.isArray(_shipmentSplits)) return cache;
    const overrideUsd = (typeof _getShippingCostOverrideUsd === 'function') ? _getShippingCostOverrideUsd() : null;
    if (overrideUsd !== null) return cache; // override masks computed shipping math
    const baseMethod = document.getElementById('freight-mode')?.value || 'slow';
    const labels = { slow: 'Slow Boat', fast: 'Fast Boat', airupp: 'Air + UPS', directair: 'Direct Air' };
    const byMethod = {};
    _shipmentSplits.forEach(s => {
      const q = parseInt(s.qty) || 0;
      if (q <= 0 || s.method === baseMethod) return;
      const upCost   = calcSplitCost(s.method,  q);
      const baseCost = calcSplitCost(baseMethod, q);
      if (!upCost || !baseCost) return;
      const premUsd = upCost.usd - baseCost.usd;
      const premRmb = upCost.rmb - baseCost.rmb;
      if (premUsd <= 0) return; // base same/cheaper — nothing to upgrade
      const agg = byMethod[s.method] || { qty: 0, premUsd: 0, premRmb: 0, baseUsd: 0, upUsd: 0 };
      agg.qty += q; agg.premUsd += premUsd; agg.premRmb += premRmb;
      agg.baseUsd += baseCost.usd; agg.upUsd += upCost.usd;
      byMethod[s.method] = agg;
    });
    Object.keys(byMethod).forEach(mk => {
      const agg = byMethod[mk];
      cache.push({
        id: '__shipup_' + mk,
        method: mk,
        baseMethod,
        label: 'Added Shipping Cost for ' + (labels[mk] || mk),
        desc: agg.qty.toLocaleString('en-US') + ' units · ' + (labels[baseMethod] || baseMethod) + ' → ' + (labels[mk] || mk),
        rmb: agg.premRmb,
        usd: agg.premUsd,
        baseUsd: agg.baseUsd,
        upUsd: agg.upUsd,
      });
    });
    return cache;
  }
  // Sticky expand-state for the Total Landed Cost card's per-variant
  // breakdown section. Persists across re-renders within a session so
  // clicking expand once doesn't snap closed on the next renderPricingTab.
  let _psLandedExpanded = false;
  function togglePsLandedVariants() {
    _psLandedExpanded = !_psLandedExpanded;
    const box = document.getElementById('ps-landed-variants');
    const chev = document.getElementById('ps-landed-chevron');
    // Only honor the toggle when the variants box has any rows; renderer
    // sets data-has-variants when it has populated content.
    if (!box || box.dataset.hasVariants !== '1') return;
    box.style.display = _psLandedExpanded ? '' : 'none';
    if (chev) chev.style.transform = _psLandedExpanded ? 'rotate(90deg)' : '';
  }

  const FEE_TYPE_LABELS = {
    sample: 'Sample Fee(s)', tooling: 'Tooling Fee(s)', die: 'Die Fee(s)',
    plate: 'Plate Fee(s)', design: 'Design Fee(s)'
  };

  function openAddFeeModal() {
    let modal = document.getElementById('add-fee-modal');
    if (modal) modal.remove();
    modal = document.createElement('div');
    modal.id = 'add-fee-modal';
    modal.className = 'modal-overlay';
    modal.style.cssText = 'display:flex;';
    modal.innerHTML = `
      <div class="modal" style="max-width:420px; width:100%;">
        <div class="modal-header">
          <h3 style="margin:0; font-size:16px;">Add Fee</h3>
          <button onclick="document.getElementById('add-fee-modal').remove()" style="background:none;border:none;font-size:20px;cursor:pointer;color:var(--text-muted);">&times;</button>
        </div>
        <div class="modal-body" style="display:flex;flex-direction:column;gap:14px;">
          <div id="add-fee-error" style="display:none;background:rgba(251,113,133,0.12);border:1px solid rgba(251,113,133,0.35);color:#fb7185;border-radius:8px;padding:8px 12px;font-size:13px;"></div>
          <div>
            <label style="font-size:11px;font-weight:600;text-transform:uppercase;letter-spacing:0.05em;color:var(--text-muted);display:block;margin-bottom:4px;">Fee Type</label>
            <select id="add-fee-type" class="form-input" style="width:100%;" onchange="onAddFeeTypeChange()" autocomplete="off">
              <option value="sample">Sample Fee(s)</option>
              <option value="tooling">Tooling Fee(s)</option>
              <option value="die">Die Fee(s)</option>
              <option value="plate">Plate Fee(s)</option>
              <option value="design">Design Fee(s)</option>
            </select>
          </div>
          <div>
            <label style="font-size:11px;font-weight:600;text-transform:uppercase;letter-spacing:0.05em;color:var(--text-muted);display:block;margin-bottom:4px;">Description</label>
            <input id="add-fee-desc" type="text" class="form-input" style="width:100%;" placeholder="e.g. Rush sample, 2nd colour run…" autocomplete="off" />
          </div>
          <div id="add-fee-rmb-row">
            <label style="font-size:11px;font-weight:600;text-transform:uppercase;letter-spacing:0.05em;color:var(--text-muted);display:block;margin-bottom:4px;">Amount (RMB)</label>
            <div class="currency-prefix currency-rmb">
              <input id="add-fee-rmb" type="text" inputmode="decimal" class="form-input" style="width:100%;padding-left:28px;" placeholder="0.00" oninput="onAddFeeRmbInput()" onfocus="_msFeeFocus(this)" onblur="_msFeeBlur(this)" autocomplete="off" />
            </div>
          </div>
          <div>
            <label style="font-size:11px;font-weight:600;text-transform:uppercase;letter-spacing:0.05em;color:var(--text-muted);display:block;margin-bottom:4px;">Amount (USD)</label>
            <div class="currency-prefix currency-usd">
              <input id="add-fee-usd" type="text" inputmode="decimal" class="form-input" style="width:100%;padding-left:28px;" placeholder="0.00" oninput="onAddFeeUsdInput()" onfocus="_msFeeFocus(this)" onblur="_msFeeBlur(this)" autocomplete="off" />
            </div>
          </div>
          <button class="btn btn-primary" onclick="confirmAddFee()">Add Fee</button>
        </div>
      </div>`;
    document.body.appendChild(modal);
    setTimeout(() => document.getElementById('add-fee-desc')?.focus(), 50);
  }

  function onAddFeeTypeChange() {
    const type = document.getElementById('add-fee-type').value;
    const rmbRow = document.getElementById('add-fee-rmb-row');
    rmbRow.style.display = type === 'design' ? 'none' : '';
    if (type === 'design') {
      document.getElementById('add-fee-rmb').value = '';
    }
  }

  function onAddFeeRmbInput() {
    const rmb = _msFeeNum(document.getElementById('add-fee-rmb'));
    document.getElementById('add-fee-usd').value = rmb > 0 ? _msFeeFmt(_fxUsdFromRmb(rmb)) : '';
  }

  function onAddFeeUsdInput() {
    const type = document.getElementById('add-fee-type').value;
    if (type === 'design') return;
    const usd = _msFeeNum(document.getElementById('add-fee-usd'));
    document.getElementById('add-fee-rmb').value = usd > 0 ? _msFeeFmt(_fxRmbFromUsd(usd)) : '';
  }

  function confirmAddFee() {
    const type  = document.getElementById('add-fee-type').value;
    const desc  = document.getElementById('add-fee-desc').value.trim();
    const rmb   = _msFeeNum(document.getElementById('add-fee-rmb'));
    const usd   = _msFeeNum(document.getElementById('add-fee-usd'));
    const errEl = document.getElementById('add-fee-error');
    errEl.style.display = 'none';
    if (!desc) { errEl.textContent = 'Description is required.'; errEl.style.display = 'block'; return; }
    if (usd <= 0) { errEl.textContent = 'Please enter an amount.'; errEl.style.display = 'block'; return; }
    _extraFeeCounter++;
    _extraFeeRows.push({ id: _extraFeeCounter, type, desc, rmb, usd });
    document.getElementById('add-fee-modal').remove();
    renderExtraFeeRows();
    calcAdditionalFees();
  }

  function openClearFeeModal(name, label) {
    let modal = document.getElementById('clear-fee-modal');
    if (modal) modal.remove();
    modal = document.createElement('div');
    modal.id = 'clear-fee-modal';
    modal.className = 'modal-overlay';
    modal.style.cssText = 'display:flex;';
    modal.innerHTML = `
      <div class="modal" style="max-width:380px; width:100%;">
        <div class="modal-header">
          <h3 style="margin:0; font-size:16px;">Clear Fee</h3>
          <button onclick="document.getElementById('clear-fee-modal').remove()" style="background:none;border:none;font-size:20px;cursor:pointer;color:var(--text-muted);">&times;</button>
        </div>
        <div class="modal-body" style="display:flex;flex-direction:column;gap:16px;">
          <p style="font-size:14px; color:var(--text-muted); margin:0;">
            Clear all values for <strong style="color:var(--text);">${label}</strong>? This cannot be undone.
          </p>
          <div style="display:flex; gap:10px; justify-content:flex-end;">
            <button class="btn btn-ghost" onclick="document.getElementById('clear-fee-modal').remove()">Cancel</button>
            <button class="btn btn-danger-ghost" onclick="confirmClearFee('${name}')">Clear</button>
          </div>
        </div>
      </div>`;
    document.body.appendChild(modal);
  }

  function confirmClearFee(name) {
    ['desc', 'rmb', 'usd'].forEach(field => {
      const el = document.getElementById(`fee-${name}-${field}`);
      if (el) el.value = '';
    });
    document.getElementById('clear-fee-modal').remove();
    calcAdditionalFees();
    autoSaveWorkbook();
  }

  function openDeleteExtraFeeModal(id) {
    const row = _extraFeeRows.find(r => r.id === id);
    if (!row) return;
    const label = `${FEE_TYPE_LABELS[row.type]}${row.desc ? ': ' + row.desc : ''}`;
    let modal = document.getElementById('clear-fee-modal');
    if (modal) modal.remove();
    modal = document.createElement('div');
    modal.id = 'clear-fee-modal';
    modal.className = 'modal-overlay';
    modal.style.cssText = 'display:flex;';
    modal.innerHTML = `
      <div class="modal" style="max-width:380px; width:100%;">
        <div class="modal-header">
          <h3 style="margin:0; font-size:16px;">Remove Fee</h3>
          <button onclick="document.getElementById('clear-fee-modal').remove()" style="background:none;border:none;font-size:20px;cursor:pointer;color:var(--text-muted);">&times;</button>
        </div>
        <div class="modal-body" style="display:flex;flex-direction:column;gap:16px;">
          <p style="font-size:14px; color:var(--text-muted); margin:0;">
            Remove <strong style="color:var(--text);">${label}</strong>? This cannot be undone.
          </p>
          <div style="display:flex; gap:10px; justify-content:flex-end;">
            <button class="btn btn-ghost" onclick="document.getElementById('clear-fee-modal').remove()">Cancel</button>
            <button class="btn btn-danger-ghost" onclick="removeExtraFeeRow(${id})">Remove</button>
          </div>
        </div>
      </div>`;
    document.body.appendChild(modal);
  }

  function removeExtraFeeRow(id) {
    document.getElementById('clear-fee-modal')?.remove();
    _extraFeeRows = _extraFeeRows.filter(r => r.id !== id);
    renderExtraFeeRows();
    calcAdditionalFees();
  }

  function renderExtraFeeRows() {
    // Workbook tab — editable inputs
    const wb = document.getElementById('extra-fee-rows');
    if (wb) {
      wb.innerHTML = _extraFeeRows.map(r => {
        const isDesign = r.type === 'design';
        const typeLabel = FEE_TYPE_LABELS[r.type];
        const descEsc = r.desc.replace(/"/g, '&quot;');
        return `<tr id="extra-fee-tr-${r.id}">
          <td style="padding:6px 12px; font-size:13px; color:var(--text-muted); white-space:nowrap;">${typeLabel}</td>
          <td style="padding:4px 8px;">
            <input type="text" class="form-input" placeholder="Description…" value="${descEsc}"
              oninput="updateExtraFeeField(${r.id},'desc',this.value)" style="width:100%;" autocomplete="off" />
          </td>
          <td style="padding:4px 8px;">
            ${isDesign
              ? `<span style="font-size:12px;color:var(--text-muted);font-style:italic;padding:0 8px;">USD only</span>`
              : `<div class="currency-prefix currency-rmb"><input type="text" inputmode="decimal" data-fee-money="1" placeholder="0.00"
                  value="${r.rmb > 0 ? _msFeeFmt(r.rmb) : ''}" oninput="updateExtraFeeField(${r.id},'rmb',this.value)"
                  onfocus="_msFeeFocus(this)" onblur="_msFeeBlur(this)"
                  style="width:100%;" /></div>`}
          </td>
          <td style="padding:4px 8px;">
            <div class="currency-prefix currency-usd"><input type="text" inputmode="decimal" data-fee-money="1" placeholder="0.00"
              value="${r.usd > 0 ? _msFeeFmt(r.usd) : ''}" oninput="updateExtraFeeField(${r.id},'usd',this.value)"
              onfocus="_msFeeFocus(this)" onblur="_msFeeBlur(this)"
              style="width:100%;" /></div>
          </td>
          <td style="padding:4px 8px; text-align:center;">
            <span class="remove-tier" onclick="openDeleteExtraFeeModal(${r.id})" title="Remove">&times;</span>
          </td>
        </tr>`;
      }).join('');
    }

    // Pricing tab — read-only display
    const pr = document.getElementById('pricing-extra-fee-rows');
    if (pr) {
      pr.innerHTML = _extraFeeRows.map(r => {
        const rmbFmt = r.rmb > 0 ? '¥' + r.rmb.toLocaleString('en-US', {minimumFractionDigits:2}) : '—';
        const usdFmt = r.usd > 0 ? '$' + r.usd.toLocaleString('en-US', {minimumFractionDigits:2}) : '—';
        return `<tr>
          <td style="padding:6px 12px; font-size:13px; color:var(--text-muted); white-space:nowrap;">${FEE_TYPE_LABELS[r.type]}</td>
          <td style="padding:6px 12px; font-size:13px;">${r.desc || ''}</td>
          <td style="padding:6px 12px; text-align:right; font-size:13px;">${rmbFmt}</td>
          <td style="padding:6px 12px; text-align:right; font-size:13px; font-weight:600;">${usdFmt}</td>
        </tr>`;
      }).join('');
    }
  }

  function updateExtraFeeField(id, field, value) {
    const row = _extraFeeRows.find(r => r.id === id);
    if (!row) return;
    // Strip any commas the user pasted/typed into the money field.
    const cleanNum = (v) => {
      const n = parseFloat(String(v == null ? '' : v).replace(/,/g, ''));
      return isNaN(n) ? 0 : n;
    };
    if (field === 'desc') {
      row.desc = value;
    } else if (field === 'rmb') {
      row.rmb = cleanNum(value);
      row.usd = row.rmb > 0 ? _fxUsdFromRmb(row.rmb) : 0;
      // Update the USD input without re-rendering — show comma-formatted
      // (the user is editing the RMB input, not this one)
      const tr = document.getElementById(`extra-fee-tr-${id}`);
      if (tr) { const usdIn = tr.querySelectorAll('input[data-fee-money="1"]')[1]; if (usdIn) usdIn.value = row.usd > 0 ? _msFeeFmt(row.usd) : ''; }
    } else if (field === 'usd') {
      row.usd = cleanNum(value);
      row.rmb = row.usd > 0 ? _fxRmbFromUsd(row.usd) : 0;
      const tr = document.getElementById(`extra-fee-tr-${id}`);
      if (tr) { const rmbIn = tr.querySelector('input[data-fee-money="1"]'); if (rmbIn) rmbIn.value = row.rmb > 0 ? _msFeeFmt(row.rmb) : ''; }
    }
    // Refresh only pricing tab display (don't re-render workbook rows — would lose focus)
    const pr = document.getElementById('pricing-extra-fee-rows');
    if (pr) {
      pr.innerHTML = _extraFeeRows.map(r => {
        const rmbFmt = r.rmb > 0 ? '¥' + r.rmb.toLocaleString('en-US', {minimumFractionDigits:2}) : '—';
        const usdFmt = r.usd > 0 ? '$' + r.usd.toLocaleString('en-US', {minimumFractionDigits:2}) : '—';
        return `<tr>
          <td style="padding:6px 12px;font-size:13px;color:var(--text-muted);white-space:nowrap;">${FEE_TYPE_LABELS[r.type]}</td>
          <td style="padding:6px 12px;font-size:13px;">${r.desc || ''}</td>
          <td style="padding:6px 12px;text-align:right;font-size:13px;">${rmbFmt}</td>
          <td style="padding:6px 12px;text-align:right;font-size:13px;font-weight:600;">${usdFmt}</td></tr>`;
      }).join('');
    }
    calcAdditionalFees();
  }

  // ── Fee input helpers — comma-separated thousands ──────────────────
  // Fee inputs are <input type="text" inputmode="decimal"> instead of
  // type="number" so they can display "1,500.00" while still allowing
  // numeric editing. _msFeeNum strips commas before parsing; the
  // focus/blur pair lets the user type raw digits while focused and
  // see the comma-formatted version on blur.
  function _msFeeNum(el) {
    if (!el) return 0;
    const v = String(el.value || '').replace(/,/g, '').trim();
    const n = parseFloat(v);
    return isNaN(n) ? 0 : n;
  }
  function _msFeeFmt(v) {
    const n = parseFloat(String(v == null ? '' : v).replace(/,/g, ''));
    if (!n || n <= 0 || isNaN(n)) return '';
    return n.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  }
  // ── Shared comma-formatter for qty / money inputs ─────────────────
  // Every numeric workbook input now reads through these helpers so
  // typing flows naturally (raw digits on focus, formatted on blur)
  // and every parser strips commas before parseFloat / parseInt.
  function _msStripCommasStr(s) { return String(s == null ? '' : s).replace(/,/g, ''); }
  function _msNumFromInput(el)  { return parseFloat(_msStripCommasStr(el && el.value)) || 0; }
  function _msIntFromInput(el)  { return parseInt(_msStripCommasStr(el && el.value), 10) || 0; }
  // On focus — drop commas so digit / arrow-key editing is sane and
  // the operator never has to delete a comma to type past it.
  function _msStripCommasOnFocus(el) {
    if (!el) return;
    const stripped = _msStripCommasStr(el.value);
    if (stripped !== el.value) el.value = stripped;
    try { el.select(); } catch (_) {}
  }
  // On blur — re-format with thousand-separator commas. Integer mode
  // for qty fields (no decimals); decimal mode for money fields
  // (preserve the precision the operator actually typed, up to 2dp).
  function _msFmtIntOnBlur(el) {
    if (!el) return;
    const raw = _msStripCommasStr(el.value).trim();
    if (raw === '') { el.value = ''; return; }
    const n = parseInt(raw, 10);
    if (!isFinite(n) || isNaN(n)) return;
    el.value = n.toLocaleString('en-US');
  }
  function _msFmtDecOnBlur(el) {
    if (!el) return;
    const raw = _msStripCommasStr(el.value).trim();
    if (raw === '') { el.value = ''; return; }
    const n = parseFloat(raw);
    if (!isFinite(n) || isNaN(n)) return;
    const dotIdx = raw.indexOf('.');
    const decimals = dotIdx >= 0 ? Math.min(2, raw.length - dotIdx - 1) : 0;
    el.value = n.toLocaleString('en-US', { minimumFractionDigits: decimals, maximumFractionDigits: 2 });
  }
  // Apply blur-formatting to every input in a subtree — used after a
  // workbook loads so saved raw values render with commas immediately.
  function _msReformatAllNumericInputs(rootEl) {
    if (!rootEl) return;
    rootEl.querySelectorAll('input[data-num-int="1"]').forEach(_msFmtIntOnBlur);
    rootEl.querySelectorAll('input[data-num-dec="1"]').forEach(_msFmtDecOnBlur);
  }
  // ── FX rounding ──────────────────────────────────────────────────
  // RMB↔USD conversions always round UP to the hundredth (so the
  // converted value never under-quotes the cost, even by a fraction
  // of a cent). Wraps both RMB-from-USD and USD-from-RMB paths plus
  // the USD_TO_RMB variants used on the shipping side.
  function _msCeil2(n) {
    const v = Number(n);
    if (!isFinite(v)) return 0;
    return Math.ceil(v * 100) / 100;
  }
  function _fxUsdFromRmb(rmb)  { return _msCeil2((Number(rmb) || 0) / USD_TO_RMB); }
  // Precise (non-ceiled, non-rounded) RMB→USD — for display rows
  // where the operator expects to see the exact mathematical
  // conversion (e.g. ¥0.30 → $0.0441), not the rounded-up margin-safe
  // value _fxUsdFromRmb produces. Cost-side math should still use
  // _fxUsdFromRmb to keep landed totals on the safe side of rounding.
  function _fxUsdFromRmbPrecise(rmb) { return (Number(rmb) || 0) / (USD_TO_RMB || 1); }
  function _fxRmbFromUsd(usd)  { return _msCeil2((Number(usd) || 0) * USD_TO_RMB); }
  function _fxFreightUsdFromRmb(rmb) { return _msCeil2((Number(rmb) || 0) / USD_TO_RMB); }
  function _fxFreightRmbFromUsd(usd) { return _msCeil2((Number(usd) || 0) * USD_TO_RMB); }
  function _msFeeFocus(el) {
    if (!el) return;
    const n = _msFeeNum(el);
    el.value = n > 0 ? n.toFixed(2) : '';
    try { el.select(); } catch (_) {}
  }
  function _msFeeBlur(el) {
    if (!el) return;
    el.value = _msFeeFmt(el.value);
  }
  // Format every Additional Fees money input on the workbook tab —
  // called after a workbook loads so saved values get pretty commas.
  function _msFormatAllFeeInputs() {
    document.querySelectorAll('#wb-tab-workbook input[data-fee-money="1"]').forEach(_msFeeBlur);
  }

  function convertFee(name, from) {
    const rmbEl = document.getElementById(`fee-${name}-rmb`);
    const usdEl = document.getElementById(`fee-${name}-usd`);
    if (!rmbEl || !usdEl) return;
    if (from === 'rmb') {
      const rmb = _msFeeNum(rmbEl);
      // RMB→USD always rounds UP to the cent so quotes never under-
      // represent the dollar cost by a fractional cent.
      usdEl.value = rmb > 0 ? _msFeeFmt(_fxUsdFromRmb(rmb)) : '';
    } else {
      const usd = _msFeeNum(usdEl);
      rmbEl.value = usd > 0 ? _msFeeFmt(_fxRmbFromUsd(usd)) : '';
    }
    calcAdditionalFees();
  }

  function toggleSection(card) {
    card.classList.toggle('collapsed');
    // The summary line only renders while the section is collapsed,
    // so refresh it whenever the section is toggled — picks up any
    // edits the operator made in the body before collapsing.
    const sec = card.getAttribute && card.getAttribute('data-section');
    if (sec) _updateSectionSummary(sec);
  }

  // ── Collapsed-section summary engine ───────────────────────────────────
  // Each of the long workbook sections (RFQ, Tiered Pricing, Additional
  // Fees, Dimensions, Pallet) gets a tiny one-liner in its header that
  // shows the most important numbers when the section is collapsed.
  // Refreshed on workbook fill, on section toggle, and via hooks in the
  // existing recalc paths (recalcRfqTotals / autoCalcCartons / etc.).
  // No-op if the target span isn't present on the page (e.g. section
  // markup hasn't been rendered yet during the initial mount race).
  function _setSectionSummary(name, html) {
    const el = document.querySelector(`.section-summary[data-section-summary="${name}"]`);
    if (el) el.innerHTML = html || '';
  }
  const _ssFmtUsd = v => '$' + (v || 0).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  const _ssFmtInt = v => (v || 0).toLocaleString('en-US');

  function _updateSectionSummary(name) {
    try {
      switch (name) {
        case 'overview': {
          // When the operator manually collapses Product Overview,
          // show the at-a-glance trio: Client Name → Product Name →
          // Product Description (truncated). All three reads pull
          // from the live form inputs so a typed edit shows up the
          // moment the section is collapsed.
          const escHtml = s => String(s == null ? '' : s)
            .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
          const client  = (document.getElementById('client-name')?.value  || '').trim();
          const product = (document.getElementById('product-name')?.value || '').trim();
          const desc    = (document.getElementById('product-desc')?.value || '').trim();
          if (!client && !product && !desc) { _setSectionSummary('overview', ''); break; }
          const parts = [];
          if (client)  parts.push(`<span class="ss-value">${escHtml(client)}</span>`);
          if (product) parts.push(`<span class="ss-value ss-value--accent">${escHtml(product)}</span>`);
          if (desc)    parts.push(`<span class="ss-value ss-overview-desc" title="${escHtml(desc)}">${escHtml(desc)}</span>`);
          _setSectionSummary('overview',
            `<div class="ss-row">` + parts.join('<span class="ss-divider">·</span>') + `</div>`
          );
          break;
        }
        case 'rfq': {
          // Walk parent rows; for each parent compute group-level
          // stats from its variants (or fall back to the parent's
          // own qty/price when no variants). One ss-rfq-line is
          // emitted per parent so the operator sees every item with
          // its own qty / RMB range / USD range / total / lead.
          // Grand totals at the top are derived from the per-item
          // sums — no double-counting (parent qty is ignored when
          // variants exist).
          const fmt2  = v => v.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
          const items = [];
          let grandTotal = 0, grandQty = 0, grandLead = 0;
          const parents = document.querySelectorAll('#rfq-body tr:not([data-rfq-parent]):not([data-rfq-add-for])');
          parents.forEach((parent, idx) => {
            const pIns = parent.querySelectorAll('input:not([type="checkbox"])');
            // Parent inputs: sku(0), item(1), qty(2), rmb(3), lead(4)
            const itemName = (pIns[1]?.value || '').trim() || `Item ${idx + 1}`;
            const pQty     = _msNumFromInput(pIns[2]);
            const pRmb     = _msNumFromInput(pIns[3]);
            const pLead    = parseInt(pIns[4]?.value)   || 0;
            const id       = parseInt(parent.id.replace('rfq-', ''));
            const variantRows = document.querySelectorAll(`[data-rfq-parent="${id}"]`);

            let qty = 0, rmbMin = Infinity, rmbMax = -Infinity, total = 0, maxLead = pLead;
            // Count variants with actual content (name / qty / rmb) so
            // empty placeholder variant rows don't inflate the badge.
            let variantCount = 0;
            if (variantRows.length === 0) {
              // No variants — parent IS the line. Ceil per-unit USD to
              // the cent so the collapsed summary line matches the
              // expanded section (which also uses _fxUsdFromRmb).
              qty = pQty;
              if (pRmb > 0) { rmbMin = pRmb; rmbMax = pRmb; }
              total = _msCeil2(pQty * _fxUsdFromRmb(pRmb));
            } else {
              // Has variants — parent qty is ignored to avoid
              // double-counting against the variant qtys.
              variantRows.forEach(vr => {
                // Skip the SKU input — it's the first input in each
                // variant row but it's NOT in the positional layout
                // (name=0, qty=1, rmb=2, lead=3) the rest of this
                // function relies on. Without this exclusion every
                // value reads from the wrong cell (vName → SKU,
                // vQty → variant name → 0, vRmb → qty, vLead → price),
                // which is exactly the "numbers don't match" bug in
                // the collapsed RFQ summary.
                const vIns  = vr.querySelectorAll('input:not(.rfq-var-sku-input)');
                // Variant inputs: name(0), qty(1), rmb(2), lead(3)
                const vName = (vIns[0]?.value || '').trim();
                const vQty  = _msNumFromInput(vIns[1]);
                const vRmb  = _msNumFromInput(vIns[2]);
                const vLead = parseInt(_msStripCommasStr(vIns[3]?.value)) || 0;
                if (!vName && !vQty && !vRmb) return; // skip empty placeholder
                variantCount++;
                qty   += vQty;
                if (vRmb > 0) {
                  if (vRmb < rmbMin) rmbMin = vRmb;
                  if (vRmb > rmbMax) rmbMax = vRmb;
                }
                total += _msCeil2(vQty * _fxUsdFromRmb(vRmb));
                if (vLead > maxLead) maxLead = vLead;
              });
            }
            // Skip rows that have nothing meaningful in them
            if (qty === 0 && rmbMin === Infinity && total === 0) return;

            items.push({
              name:  itemName,
              variantCount,
              qty,
              rmbMin: rmbMin === Infinity ? 0 : rmbMin,
              rmbMax: rmbMax === -Infinity ? 0 : rmbMax,
              total,
              lead:  maxLead,
            });
            grandTotal += total;
            grandQty   += qty;
            if (maxLead > grandLead) grandLead = maxLead;
          });
          if (items.length === 0) { _setSectionSummary('rfq', ''); break; }

          // Single grid wraps everything so columns line up across:
          //   • column-header row at top
          //   • one row per parent line item
          //   • grand-total row at bottom (bookend to the top ss-row)
          // Range cells (RMB / USD) render a single value when
          // min == max so non-variable items don't show fake "x–x" ranges.
          const cellEsc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
          const headerCells =
            `<div class="ss-rfq-th ss-rfq-th--left">Item</div>` +
            `<div class="ss-rfq-th">Qty</div>` +
            `<div class="ss-rfq-th">Unit (RMB)</div>` +
            `<div class="ss-rfq-th">Unit (USD)</div>` +
            `<div class="ss-rfq-th">Total</div>` +
            `<div class="ss-rfq-th">Lead</div>`;
          const itemCells = items.map(it => {
            const isRange = (it.rmbMax - it.rmbMin) > 0.005;
            const rmbCell = it.rmbMin > 0
              ? (isRange ? `¥${fmt2(it.rmbMin)}–¥${fmt2(it.rmbMax)}` : `¥${fmt2(it.rmbMin)}`)
              : '—';
            const usdMin = _fxUsdFromRmb(it.rmbMin);
            const usdMax = _fxUsdFromRmb(it.rmbMax);
            const usdCell = it.rmbMin > 0
              ? (isRange ? `$${fmt2(usdMin)}–$${fmt2(usdMax)}` : `$${fmt2(usdMin)}`)
              : '—';
            // Variant count badge — appears next to the item name when
            // the line has any variants, e.g. "Tank (White) — 5 variants".
            const variantBadge = it.variantCount > 0
              ? ` <span class="ss-rfq-variant-count">— ${it.variantCount} variant${it.variantCount === 1 ? '' : 's'}</span>`
              : '';
            const titleAttr = it.variantCount > 0
              ? `${it.name} (${it.variantCount} variant${it.variantCount === 1 ? '' : 's'})`
              : it.name;
            return (
              `<div class="ss-rfq-name" title="${cellEsc(titleAttr)}">${cellEsc(it.name)}${variantBadge}</div>` +
              `<div>${_ssFmtInt(it.qty)}</div>` +
              `<div>${rmbCell}</div>` +
              `<div>${usdCell}</div>` +
              `<div class="ss-rfq-accent">${_ssFmtUsd(it.total)}</div>` +
              `<div>${it.lead > 0 ? it.lead + 'd' : '—'}</div>`
            );
          }).join('');
          // Divider grid item — spans all columns so the border above
          // the Grand Total row is continuous edge-to-edge (no breaks
          // at the column gaps that per-cell borders would produce).
          const dividerCell = `<div class="ss-rfq-divider"></div>`;
          const grandCells =
            `<div class="ss-rfq-grand-cell ss-rfq-grand-cell--label">Grand Total</div>` +
            `<div class="ss-rfq-grand-cell">${_ssFmtInt(grandQty)}</div>` +
            `<div class="ss-rfq-grand-cell"></div>` +
            `<div class="ss-rfq-grand-cell"></div>` +
            `<div class="ss-rfq-grand-cell ss-rfq-accent">${_ssFmtUsd(grandTotal)}</div>` +
            `<div class="ss-rfq-grand-cell">${grandLead > 0 ? grandLead + 'd' : '—'}</div>`;

          const tableHtml = `<div class="ss-rfq-table">${headerCells}${itemCells}${dividerCell}${grandCells}</div>`;
          _setSectionSummary('rfq', tableHtml);
          break;
        }
        case 'tiers': {
          // Show: tier count + the FIRST filled tier's qty/unit/total.
          // Tier rows have ONE input (qty); price lives on
          // row.dataset.price (the auto-driven RFQ unit RMB). Reading
          // inputs[1] would always be null/0 → that's why the summary
          // never appeared. Use dataset.price like recalcWbTier does.
          const rows = document.querySelectorAll('#wb-tier-body tr');
          if (!rows.length) { _setSectionSummary('tiers', ''); break; }
          let first = null, filledCount = 0;
          rows.forEach(r => {
            const qInput = r.querySelector('input');
            // Tier qty inputs show "110,000" after blur formatting — bare
            // parseFloat stops at the comma and yields 110, so the
            // collapsed header reads "Tier 1: 110" instead of "110,000".
            // Strip commas first, like _msNumFromInput does elsewhere.
            const q = parseFloat(_msStripCommasStr(qInput?.value)) || 0;
            const p = parseFloat(_msStripCommasStr(r.dataset.price)) || 0;
            if (q > 0 && p > 0) {
              filledCount++;
              if (!first) first = { q, rmb: p };
            }
          });
          if (!first) { _setSectionSummary('tiers', ''); break; }
          const usd = first.rmb / USD_TO_RMB;
          _setSectionSummary('tiers',
            `<div class="ss-row">` +
              `<span class="ss-label">${filledCount} tier${filledCount === 1 ? '' : 's'}</span>` +
              `<span class="ss-divider">·</span>` +
              `<span class="ss-value">Tier 1: ${_ssFmtInt(first.q)} @ ${_ssFmtUsd(usd)}</span>` +
              `<span class="ss-divider">·</span>` +
              `<span class="ss-value ss-value--accent">${_ssFmtUsd(first.q * usd)}</span>` +
            `</div>`
          );
          break;
        }
        case 'fees': {
          // Sum every fee currently entered on the Workbook tab.
          // collectWorkbookFees() returns the same list the Pricing tab
          // and Client Quote consume, so the summary number lines up
          // exactly with what shows there.
          if (typeof collectWorkbookFees !== 'function') { _setSectionSummary('fees', ''); break; }
          const fees = collectWorkbookFees() || [];
          let total = 0;
          fees.forEach(f => { total += parseFloat(f.usd) || 0; });
          // Always show count first so the layout is consistent even
          // when there are no fees yet (renders "0 fees · $0.00").
          _setSectionSummary('fees',
            `<div class="ss-row">` +
              `<span class="ss-label">${fees.length} fee${fees.length === 1 ? '' : 's'}</span>` +
              `<span class="ss-divider">·</span>` +
              `<span class="ss-value ss-value--accent">${_ssFmtUsd(total)}</span>` +
            `</div>`
          );
          break;
        }
        case 'dimensions': {
          // The summary line bends to the operator's input mode:
          //   - Case Only Override active → case dims + total units
          //     (products/case × cases/order) + total weight
          //   - Weight Only Override active → case qty + per-case
          //     weight + total weight (qty × per-case)
          //   - Default → product / inner carton / outer carton dims
          // Each branch renders only the values that are actually
          // filled in so a partial workbook doesn't surface noise.
          const v = id => parseFloat(document.getElementById(id)?.value) || 0;
          const vInt = id => {
            const raw = document.getElementById(id)?.value;
            if (raw == null) return 0;
            return parseInt(String(raw).replace(/,/g, ''), 10) || 0;
          };
          const fmt    = n => (Math.round(n * 10) / 10).toString();
          const fmtInt = n => (n || 0).toLocaleString('en-US');
          const fmtKg  = n => (n || 0).toLocaleString('en-US', {maximumFractionDigits: 1}) + ' kg';
          const dim = (lid, wid, hid) => {
            const L = v(lid), W = v(wid), H = v(hid);
            return (L > 0 && W > 0 && H > 0) ? `${fmt(L)} × ${fmt(W)} × ${fmt(H)} cm` : '';
          };

          const caseOnOn   = !!document.getElementById('case-only-override')?.checked;
          const weightOnOn = !!document.getElementById('weight-only-override')?.checked;
          const parts = [];

          if (caseOnOn) {
            parts.push(`<span class="ss-label">Case Only</span>`);
            const caseDim = dim('case-only-l-cm', 'case-only-w-cm', 'case-only-h-cm');
            if (caseDim) parts.push(`<span class="ss-value">${caseDim}</span>`);
            const productsPer = vInt('case-only-products-per');
            const casesOrder  = vInt('case-only-cases-order');
            const caseWeight  = v('case-only-weight-kg');
            const totalUnits  = productsPer > 0 && casesOrder > 0 ? productsPer * casesOrder : 0;
            const totalWeight = caseWeight  > 0 && casesOrder > 0 ? caseWeight  * casesOrder : 0;
            if (totalUnits  > 0) parts.push(`<span class="ss-value ss-value--accent">${fmtInt(totalUnits)} units</span>`);
            if (casesOrder  > 0) parts.push(`<span class="ss-value">${fmtInt(casesOrder)} cases</span>`);
            if (totalWeight > 0) parts.push(`<span class="ss-value">${fmtKg(totalWeight)}</span>`);
          } else if (weightOnOn) {
            parts.push(`<span class="ss-label">Weight Only</span>`);
            const cases       = vInt('weight-only-qty');
            const perCaseKg   = v('weight-only-kg');
            const totalWeight = cases > 0 && perCaseKg > 0 ? cases * perCaseKg : 0;
            if (cases       > 0) parts.push(`<span class="ss-value">${fmtInt(cases)} cases</span>`);
            if (perCaseKg   > 0) parts.push(`<span class="ss-value">${fmtKg(perCaseKg)}/case</span>`);
            if (totalWeight > 0) parts.push(`<span class="ss-value ss-value--accent">${fmtKg(totalWeight)} total</span>`);
          } else {
            const product = dim('dim-cm-l',          'dim-cm-w',          'dim-cm-h');
            const inner   = dim('carton-inner-l-cm', 'carton-inner-w-cm', 'carton-inner-h-cm');
            const outer   = dim('carton-outer-l-cm', 'carton-outer-w-cm', 'carton-outer-h-cm');
            if (product) parts.push(`<span class="ss-label">Product</span><span class="ss-value">${product}</span>`);
            if (inner)   parts.push(`<span class="ss-label">Inner</span><span class="ss-value">${inner}</span>`);
            if (outer)   parts.push(`<span class="ss-label">Outer</span><span class="ss-value">${outer}</span>`);
          }

          if (parts.length === 0) { _setSectionSummary('dimensions', ''); break; }
          _setSectionSummary('dimensions',
            `<div class="ss-row">` + parts.join('<span class="ss-divider">·</span>') + `</div>`
          );
          break;
        }
        case 'pallet': {
          // Pallet stats are computed by the existing pallet renderer
          // and stashed on window._palletStats. Show items/pallet +
          // layer count + total pallets needed if all are available.
          // Label varies by mode: cases (case-only), units (manual),
          // cartons (default).
          const ps = window._palletStats;
          if (!ps) { _setSectionSummary('pallet', ''); break; }
          const perPallet  = parseInt(ps.totalPerPallet || 0);
          const layers     = parseInt(ps.maxLayers || 0);
          const palletsNeeded = parseInt(ps.palletsNeeded || 0);
          if (!perPallet) { _setSectionSummary('pallet', ''); break; }
          const _caseOn   = !!document.getElementById('case-only-override')?.checked;
          const _manualOn = !_caseOn && !!document.getElementById('pallet-manual')?.checked;
          const perPalletLabel = _caseOn ? 'Cases / Pallet' : (_manualOn ? 'Units / Pallet' : 'Cartons / Pallet');
          _setSectionSummary('pallet',
            `<div class="ss-row">` +
              `<span class="ss-label">${perPalletLabel}</span>` +
              `<span class="ss-value ss-value--accent">${_ssFmtInt(perPallet)}</span>` +
              (layers > 0 ? `<span class="ss-divider">·</span><span class="ss-value">${layers} layer${layers === 1 ? '' : 's'}</span>` : '') +
              (palletsNeeded > 0 ? `<span class="ss-divider">·</span><span class="ss-value">${palletsNeeded} pallet${palletsNeeded === 1 ? '' : 's'} needed</span>` : '') +
            `</div>`
          );
          break;
        }
      }
    } catch (e) {
      // Summary is decorative — never let an edge case break the
      // workbook itself. Log + silently skip.
      console.error('[MS section summary]', name, e);
    }
  }

  // Refresh every section summary in one call. Used on workbook fill +
  // tab switches when the operator might have edits queued in any of
  // them. Per-section recalcs (recalcRfqTotals etc.) call _updateSection-
  // Summary directly with a single name to stay fast.
  function _updateAllSectionSummaries() {
    ['overview', 'rfq', 'tiers', 'fees', 'dimensions', 'pallet'].forEach(_updateSectionSummary);
  }

  // Auto-collapse the data-heavy sections (RFQ, Tiered Pricing,
  // Additional Fees, Dimensions, Pallet) on every workbook open so the
  // operator lands on a clean Product Overview view. The sections are
  // still ONE click away — the chevron in each header expands them.
  function _collapseHeavySectionsOnOpen() {
    ['rfq', 'tiers', 'fees', 'dimensions', 'pallet'].forEach(name => {
      const card = document.querySelector(`.section-card[data-section="${name}"]`);
      if (card) card.classList.add('collapsed');
    });
  }

  // Walk every fee currently entered on the Workbook tab and return them
  // as a flat list. Each entry has { id, label, desc, usd, rmb }.
  // - Standard fees (sample/tooling/die/plate/design) are included only
  //   when the user has typed a USD amount or a description.
  // - Extra rows pull from _extraFeeRows directly.
  // The Pricing-tab Additional Fees card and the Client Quote both
  // consume this list, so any fee that's "real" on the Workbook tab is
  // available to apply.
  function collectWorkbookFees() {
    // Fee inputs are now comma-formatted text inputs (e.g. "7,500.00"),
    // so plain parseFloat would read "7" and stop at the comma. Route
    // every read through _msFeeNum which strips commas first.
    const get = (id) => _msFeeNum(document.getElementById(id));
    const txt = (id) => (document.getElementById(id)?.value || '').trim();
    const std = [
      { id: 'sample',  label: 'Sample Fee(s)',  rmb: get('fee-sample-rmb'),  usd: get('fee-sample-usd'),  desc: txt('fee-sample-desc')  },
      { id: 'tooling', label: 'Tooling Fee(s)', rmb: get('fee-tooling-rmb'), usd: get('fee-tooling-usd'), desc: txt('fee-tooling-desc') },
      { id: 'die',     label: 'Die Fee(s)',     rmb: get('fee-die-rmb'),     usd: get('fee-die-usd'),     desc: txt('fee-die-desc')     },
      { id: 'plate',   label: 'Plate Fee(s)',   rmb: get('fee-plate-rmb'),   usd: get('fee-plate-usd'),   desc: txt('fee-plate-desc')   },
      { id: 'design',  label: 'Design Fee(s)',  rmb: 0,                       usd: get('fee-design-usd'),  desc: txt('fee-design-desc')  }
    ].filter(f => f.usd > 0 || f.rmb > 0 || f.desc !== '');
    const extras = _extraFeeRows.map(r => ({
      id: 'extra:' + r.id,
      label: r.type || 'Custom Fee',
      desc:  r.desc || '',
      rmb:   r.rmb || 0,
      usd:   r.usd || 0,
    })).filter(f => f.usd > 0 || f.rmb > 0 || f.desc !== '');
    return std.concat(extras);
  }

  // Sum of every applied fee's USD amount. Drives both the Total Landed
  // Cost addition and the Client Quote line items. Includes synthetic
  // shipment-upgrade fees (see _shipmentUpgradeFees) when ticked. Each
  // fee's effective amount is the per-fee override when set, else the
  // source ("as is") amount from the Workbook tab.
  function appliedFeesTotalUsd() {
    const fees = collectWorkbookFees();
    let t = fees.reduce((s, f) => s + (_appliedFees.has(f.id) ? _getAppliedFeeAmount(f) : 0), 0);
    _shipmentUpgradeFees().forEach(f => { if (_appliedFees.has(f.id)) t += _getAppliedFeeAmount(f); });
    return t;
  }

  // List of currently-applied fees (filtered + ordered the way they
  // appear in the picker). Used by the Client Quote renderer. Each
  // entry's .usd carries the EFFECTIVE amount (override or as-is) so
  // downstream consumers don't need to know about the override map;
  // .originalUsd preserves the source amount for any consumer that
  // wants to show 'as is' vs current. Synthetic shipment-upgrade fees
  // appended so they show as their own line item in the client quote.
  function appliedFeesList() {
    const _wrap = f => ({ ...f, originalUsd: f.usd, usd: _getAppliedFeeAmount(f) });
    const list = collectWorkbookFees().filter(f => _appliedFees.has(f.id)).map(_wrap);
    _shipmentUpgradeFees().forEach(f => { if (_appliedFees.has(f.id)) list.push(_wrap(f)); });
    return list;
  }

  // Build the Apply Additional Fees picker on the Pricing tab. One row
  // per fee that exists on the Workbook tab, with a checkbox bound to
  // _appliedFees. Empty state shown when no fees have been entered.
  function renderPricingFeesCard() {
    const body = document.getElementById('pricing-fees-body');
    if (!body) return;
    const fees = collectWorkbookFees();
    const totalEl = document.getElementById('pricing-fees-applied-total');

    const fmtUsd = v => v > 0 ? '$' + v.toLocaleString('en-US', {minimumFractionDigits:2, maximumFractionDigits:2}) : '—';
    const fmtRmb = v => v > 0 ? '¥' + v.toLocaleString('en-US', {minimumFractionDigits:2, maximumFractionDigits:2}) : '';

    // BAIL-OUT: if the operator is actively typing in a fee override
    // input, don't re-render the body — that would destroy the input
    // element they're focused on and clobber their cursor mid-keystroke.
    // Just refresh the header chip so the '+ $XXX applied' total
    // reflects the new override; everything else updates live via
    // _onAppliedFeeOverrideInput.
    const active = document.activeElement;
    if (active && active.matches && active.matches('input[data-fee-override-id]')) {
      const tot = appliedFeesTotalUsd();
      if (totalEl) totalEl.textContent = tot > 0 ? `+ ${fmtUsd(tot)} applied` : '';
      return;
    }

    // Drop any applied-fee IDs that no longer correspond to a real fee
    // (e.g. user deleted an extra row on the Workbook tab).
    const validIds = new Set(fees.map(f => f.id));
    let pruned = false;
    // '__shipup_*' are synthetic shipment-upgrade fees with no Workbook-
    // tab row — never prune them here (they're managed by renderPricingTab).
    [..._appliedFees].forEach(id => { if (!validIds.has(id) && !String(id).startsWith('__shipup_')) { _appliedFees.delete(id); pruned = true; } });

    if (fees.length === 0) {
      body.innerHTML = `<div style="padding:14px 4px; font-size:12px; color:var(--text-muted); font-style:italic;">No fees entered on the Workbook tab. Add Sample / Tooling / Die / Plate / Design or custom fees there to make them available here.</div>`;
      // Even with no Workbook-tab fees, a shipment-upgrade fee may be
      // applied — reflect it in the header chip so the total isn't blank.
      const upTot = appliedFeesTotalUsd();
      if (totalEl) totalEl.textContent = upTot > 0 ? `+ ${fmtUsd(upTot)} applied` : '';
      if (pruned && !_filling) autoSaveWorkbook();
      return;
    }

    const escHtmlSafe = v => String(v == null ? '' : v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
    const rows = fees.map(f => {
      const isApplied = _appliedFees.has(f.id);
      const checked   = isApplied ? 'checked' : '';
      const idAttr    = escHtmlSafe(f.id);
      const descLine  = f.desc ? `<div style="font-size:11px; color:var(--text-muted); margin-top:1px;">${escHtmlSafe(f.desc)}</div>` : '';
      const asIsRmb   = parseFloat(f.rmb) || 0;
      const asIsUsd   = parseFloat(f.usd) || 0;
      const effective = _getAppliedFeeAmount(f);
      const hasOver   = isApplied && _hasFeeOverride(f.id);
      // RMB displayed under the override input — derived from the
      // EFFECTIVE USD (× FX rate) when the operator has overridden the
      // amount, so editing $590 → $600 immediately shows the new ¥
      // figure beneath it. Falls back to the source ¥ when the fee
      // hasn't been overridden (preserves the workbook-tab rmb when
      // available; otherwise derives from the as-is USD).
      const liveRmb = hasOver
        ? (effective * (USD_TO_RMB || 0))
        : (asIsRmb > 0 ? asIsRmb : asIsUsd * (USD_TO_RMB || 0));
      const liveRmbStr = liveRmb > 0 ? fmtRmb(liveRmb) : '';
      const sourceRmbStr = fmtRmb(asIsRmb);
      // Right-side amount column. When the fee is NOT applied → static
      // 'as is' amount only. When APPLIED → 'as is' label above an
      // editable override input + live RMB. Clearing the input reverts.
      const amountColHtml = isApplied
        ? `<div style="display:flex; flex-direction:column; align-items:flex-end; gap:4px; min-width:140px;">
             <div style="font-size:10px; color:var(--text-muted); white-space:nowrap;">As is: <span style="font-weight:600;">${fmtUsd(asIsUsd)}</span>${hasOver ? ` <button type="button" onclick="event.preventDefault(); event.stopPropagation(); _clearAppliedFeeOverride('${idAttr}');" title="Revert to as-is amount" style="background:none; border:none; color:var(--accent); font-size:10px; font-weight:600; cursor:pointer; padding:0 0 0 4px; font-family:inherit; text-decoration:underline;">revert</button>` : ''}</div>
             <div style="display:inline-flex; align-items:center; gap:4px;">
               <span style="font-size:12px; color:var(--text-muted);">\$</span>
               <input type="text" inputmode="decimal" pattern="[0-9]*\\.?[0-9]*" value="${effective.toFixed(2)}"
                 data-fee-override-id="${idAttr}"
                 onfocus="this.select()"
                 oninput="_onAppliedFeeOverrideInput('${idAttr}', this.value)"
                 onblur="_formatAppliedFeeOverrideInput(this)"
                 style="width:90px; padding:4px 6px; font-size:13px; font-weight:700; text-align:right; border:1px solid ${hasOver ? 'var(--accent)' : 'var(--border)'}; border-radius:5px; background:var(--surface); color:var(--text); font-family:inherit;" />
             </div>
             <div data-fee-rmb-id="${idAttr}" style="font-size:10px; color:var(--text-muted); min-height:14px;">${liveRmbStr}</div>
           </div>`
        : `<div style="text-align:right; flex-shrink:0;">
             <div style="font-size:13px; font-weight:700; color:var(--text);">${fmtUsd(asIsUsd)}</div>
             ${sourceRmbStr ? `<div style="font-size:11px; color:var(--text-muted);">${sourceRmbStr}</div>` : ''}
           </div>`;
      // Row container is a plain <div> (NOT a <label>) — the label
      // wrapped the override input causing the browser's label-to-first-
      // form-control focus-transfer rule to blur the input on every
      // keystroke (cursor leaving after typing one character). The
      // checkbox-toggle UX is preserved by wrapping ONLY the checkbox +
      // label text in a real <label>; the amount column (with the
      // editable input) sits outside, unaffected.
      return `<div style="display:flex; align-items:flex-start; gap:12px; padding:10px 0; border-bottom:1px solid var(--border);">
        <label style="display:flex; align-items:flex-start; gap:12px; cursor:pointer; flex:1; min-width:0;">
          <input type="checkbox" ${checked} onchange="toggleFeeApplied('${idAttr}', this.checked)"
                 style="width:16px; height:16px; accent-color:#E8751A; cursor:pointer; flex-shrink:0; margin-top:2px;" />
          <div style="flex:1; min-width:0;">
            <div style="font-size:13px; font-weight:600; color:var(--text);">${escHtmlSafe(f.label)}</div>
            ${descLine}
          </div>
        </label>
        ${amountColHtml}
      </div>`;
    }).join('');

    body.innerHTML = rows;
    const tot = appliedFeesTotalUsd();
    if (totalEl) totalEl.textContent = tot > 0 ? `+ ${fmtUsd(tot)} applied` : '';

    if (pruned && !_filling) autoSaveWorkbook();
  }

  // Client Quote — expand/collapse a variant group's sub-rows. Hidden
  // by default; clicking the parent row reveals every variant's SKU,
  // qty, sale price, and line total. Mirrors the same hide/show
  // pattern the Inventory page uses for nested variant SKUs.
  function _cqToggleVariants(parentId) {
    if (!parentId) return;
    const parent = document.querySelector(`tr.cq-parent-row[data-cq-parent="${CSS.escape(parentId)}"]`);
    if (!parent) return;
    const expanded = parent.classList.toggle('expanded');
    // Rotate chevron via class transform from the CSS rule.
    document.querySelectorAll(`tr.cq-variant-row[data-cq-variant-of="${CSS.escape(parentId)}"]`).forEach(vr => {
      vr.classList.toggle('hidden', !expanded);
    });
  }

  function toggleFeeApplied(id, isChecked) {
    if (isChecked) {
      _appliedFees.add(id);
    } else {
      _appliedFees.delete(id);
      // Clearing the toggle also clears any per-fee override — re-
      // checking later starts from the as-is amount again.
      if (_hasFeeOverride(id)) delete _appliedFeeOverrides[id];
    }
    if (typeof _schedulePricingTabRender === 'function') _schedulePricingTabRender();
    renderPricingFeesCard();
    if (!_filling) autoSaveWorkbook();
  }

  // oninput on a fee's override-amount input. Empty value reverts the
  // fee back to its as-is amount (delete from the override map).
  // Otherwise stash the numeric value so appliedFeesTotalUsd /
  // appliedFeesList pick it up. Triggers the Pricing-tab re-render so
  // Total Landed Cost + Client Quote reflect the new amount live —
  // renderPricingFeesCard's own bail-out check keeps the body from
  // being rewritten while the operator is focused on the input, so the
  // cursor doesn't get clobbered mid-keystroke.
  function _onAppliedFeeOverrideInput(id, value) {
    const trimmed = String(value == null ? '' : value).trim();
    if (trimmed === '') {
      if (_hasFeeOverride(id)) delete _appliedFeeOverrides[id];
    } else {
      const v = parseFloat(trimmed);
      _appliedFeeOverrides[id] = isFinite(v) && v >= 0 ? v : 0;
    }
    // Update the in-row RMB display + input border color in-place so
    // the operator sees the change without us needing to re-render
    // (re-rendering would destroy the input element they're typing in).
    try {
      const safeId = (typeof CSS !== 'undefined' && CSS.escape) ? CSS.escape(id) : id.replace(/"/g, '\\"');
      const inputEl = document.querySelector(`input[data-fee-override-id="${safeId}"]`);
      const rmbEl   = document.querySelector(`[data-fee-rmb-id="${safeId}"]`);
      const effective = parseFloat(_appliedFeeOverrides[id]);
      const hasOver   = _hasFeeOverride(id);
      const usdNum    = isFinite(effective) ? effective : 0;
      if (rmbEl) {
        const rmbNum = usdNum * (USD_TO_RMB || 0);
        rmbEl.textContent = rmbNum > 0
          ? '¥' + rmbNum.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })
          : '';
      }
      if (inputEl) inputEl.style.borderColor = hasOver ? 'var(--accent)' : 'var(--border)';
    } catch (_) {}
    if (typeof _schedulePricingTabRender === 'function') _schedulePricingTabRender();
    if (!_filling) autoSaveWorkbook();
  }

  // Explicit revert link next to the 'As is' label — clears the
  // override and re-renders so the input snaps back to the source
  // amount.
  function _clearAppliedFeeOverride(id) {
    if (_hasFeeOverride(id)) delete _appliedFeeOverrides[id];
    if (typeof _schedulePricingTabRender === 'function') _schedulePricingTabRender();
    renderPricingFeesCard();
    if (!_filling) autoSaveWorkbook();
  }

  // onblur formatter — re-pads the override input to 2 decimals so a
  // typed "750" reads back as "750.00".
  function _formatAppliedFeeOverrideInput(el) {
    if (!el) return;
    const v = parseFloat(el.value);
    if (isFinite(v) && v >= 0) el.value = v.toFixed(2);
  }

  function calcAdditionalFees() {
    const get    = id => _msFeeNum(document.getElementById(id));
    const sample  = get('fee-sample-usd');
    const tooling = get('fee-tooling-usd');
    const die     = get('fee-die-usd');
    const plate   = get('fee-plate-usd');
    const design  = get('fee-design-usd');
    const sampleRmb  = get('fee-sample-rmb');
    const toolingRmb = get('fee-tooling-rmb');
    const dieRmb     = get('fee-die-rmb');
    const plateRmb   = get('fee-plate-rmb');

    const extraUsd = _extraFeeRows.reduce((s, r) => s + r.usd, 0);
    const extraRmb = _extraFeeRows.reduce((s, r) => s + r.rmb, 0);
    const totalUsd = sample + tooling + die + plate + design + extraUsd;
    const totalRmb = sampleRmb + toolingRmb + dieRmb + plateRmb + extraRmb;

    const fmtUsd = v => v > 0 ? '$' + v.toLocaleString('en-US', {minimumFractionDigits:2, maximumFractionDigits:2}) : '—';
    const fmtRmb = v => v > 0 ? '¥' + v.toLocaleString('en-US', {minimumFractionDigits:2, maximumFractionDigits:2}) : '—';

    // Sync descriptions to pricing tab description cells
    ['sample','tooling','die','plate','design'].forEach(id => {
      const d = document.getElementById(`fee-${id}-desc`)?.value.trim() || '';
      const el = document.getElementById(`pricing-fee-${id}-desc`);
      if (el) el.textContent = d;
    });

    document.getElementById('pricing-fee-sample').textContent      = fmtUsd(sample);
    document.getElementById('pricing-fee-sample-rmb').textContent  = fmtRmb(sampleRmb);
    document.getElementById('pricing-fee-tooling').textContent     = fmtUsd(tooling);
    document.getElementById('pricing-fee-tooling-rmb').textContent = fmtRmb(toolingRmb);
    document.getElementById('pricing-fee-die').textContent         = fmtUsd(die);
    document.getElementById('pricing-fee-die-rmb').textContent     = fmtRmb(dieRmb);
    document.getElementById('pricing-fee-plate').textContent       = fmtUsd(plate);
    document.getElementById('pricing-fee-plate-rmb').textContent   = fmtRmb(plateRmb);
    document.getElementById('pricing-fee-design').textContent      = fmtUsd(design);
    document.getElementById('pricing-fee-total').textContent       = fmtUsd(totalUsd);
    document.getElementById('pricing-fee-total-rmb').textContent   = fmtRmb(totalRmb);

    // Grand total per tier
    const tbody = document.getElementById('pricing-grand-total-body');
    if (!tbody) return;
    tbody.innerHTML = '';
    document.querySelectorAll('#tier-body tr').forEach(row => {
      const qty   = parseFloat(row.dataset.qty);
      const price = parseFloat(row.dataset.price);
      if (isNaN(qty) || isNaN(price)) return;
      const tierTotal = qty * (price / USD_TO_RMB);
      const grand = tierTotal + totalUsd;
      const tr = document.createElement('tr');
      tr.innerHTML = `
        <td style="padding:8px 12px; font-size:13px;">${qty.toLocaleString()}</td>
        <td style="padding:8px 12px; text-align:right; font-size:13px;">$${tierTotal.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})}</td>
        <td style="padding:8px 12px; text-align:right; font-size:13px; color:var(--text-muted);">${fmtUsd(totalUsd)}</td>
        <td style="padding:8px 12px; text-align:right; font-size:13px; font-weight:700; color:var(--accent);">$${grand.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})}</td>
      `;
      tbody.appendChild(tr);
    });

    // Re-render the Pricing-tab Apply Additional Fees picker so values
    // and the empty state stay in sync as the operator types fees on
    // the Workbook tab. Also re-render the Pricing tab so the applied
    // fees flow into Total Landed Cost / Client Quote in real time.
    if (typeof renderPricingFeesCard === 'function') renderPricingFeesCard();
    if (typeof _schedulePricingTabRender === 'function') _schedulePricingTabRender();
    // Keep the collapsed Additional Fees header summary in sync
    if (typeof _updateSectionSummary === 'function') _updateSectionSummary('fees');

    if (!_filling) autoSaveWorkbook();
  }

  /* ── Field Fill State ───────────────────────────────────────────────────── */
  function updateFilled(el) {
    const field = el.closest('.field, .dim-field, .karen-cell');
    if (!field) return;
    field.classList.toggle('field-filled', el.value.trim() !== '');
  }

  document.addEventListener('input', e => {
    if (e.target.matches('input, textarea, select')) updateFilled(e.target);
  });

  /* ── API Layer ────────────────────────────────────────────────────────── */
  const API_URL = 'api.php';

  async function apiCall(action, data = null) {
    try {
      const opts = data
        ? { method: 'POST', headers: {'Content-Type':'application/json', 'Accept':'application/json'}, body: JSON.stringify(data) }
        : { method: 'GET', headers: {'Accept':'application/json'} };
      const res = await fetch(`${API_URL}?action=${action}`, opts);
      if (res.status === 401) { window.location.href = 'login.php'; return { success: false }; }
      const json = await res.json();
      if (json.success) {
        // Cache to LocalStorage
        saveToLocalStorage();
      }
      return json;
    } catch (e) {
      console.warn('API call failed, using local data:', e);
      return { success: false, error: e.message };
    }
  }

  function saveToLocalStorage() {
    try {
      localStorage.setItem('ms_clientData', JSON.stringify(clientData));
      localStorage.setItem('ms_workbookDetail', JSON.stringify(workbookDetail));
      localStorage.setItem('ms_dbClientMap', JSON.stringify(dbClientMap));
      localStorage.setItem('ms_dbWorkbookMap', JSON.stringify(dbWorkbookMap));
      localStorage.setItem('ms_lastSaved', new Date().toISOString());
    } catch(e) { console.warn('LocalStorage save failed:', e); }
  }

  function loadFromLocalStorage() {
    try {
      const cd = localStorage.getItem('ms_clientData');
      const wd = localStorage.getItem('ms_workbookDetail');
      const cm = localStorage.getItem('ms_dbClientMap');
      const wm = localStorage.getItem('ms_dbWorkbookMap');
      if (cd) Object.assign(clientData, JSON.parse(cd));
      if (wd) {
        const parsed = JSON.parse(wd);
        // Skip empty arrays from bad saves
        for (const [k, v] of Object.entries(parsed)) {
          if (v && !Array.isArray(v) && typeof v === 'object' && v.client) {
            workbookDetail[k] = v;
          }
        }
      }
      if (cm) Object.assign(dbClientMap, JSON.parse(cm));
      if (wm) Object.assign(dbWorkbookMap, JSON.parse(wm));
      return !!cd;
    } catch(e) { return false; }
  }

  // Maps local client names to DB ids, and local "client|wbId" to DB workbook ids
  let dbClientMap = {};
  let dbWorkbookMap = {};
  // Stores per-client detail fields (email, phone, etc.)
  let clientDetails = {};

  // Tri-state return: true = DB loaded with workbooks, 'empty' = DB reachable but empty,
  // false = API call failed (network/server). Only 'empty' should trigger seeding.
  async function loadFromDatabase() {
    const result = await apiCall('get_all_data');
    if (!result.success) return false; // API failure — DO NOT seed, data may still exist

    // Only clear local data if DB has workbooks, otherwise keep hardcoded sample data
    const hasWorkbooks = result.workbooks && result.workbooks.length > 0;

    if (hasWorkbooks) {
      for (const key of Object.keys(clientData)) delete clientData[key];
      for (const key of Object.keys(workbookDetail)) delete workbookDetail[key];
    }

    // Rebuild client list (always update client map)
    result.clients.forEach(c => {
      dbClientMap[c.name] = c.id;
      if (!clientData[c.name]) clientData[c.name] = [];
      clientDetails[c.name] = {
        id: c.id,
        email: c.email || '',
        phone: c.phone || '',
        primary_contact: c.primary_contact || '',
        // Optional secondary POC — null/blank when not set, just like the
        // primary fields. Always defined locally so input handlers don't
        // have to existence-check before writing.
        email2:           c.email2           || '',
        phone2:           c.phone2           || '',
        primary_contact2: c.primary_contact2 || '',
        billing_address: c.billing_address || '',
        shipping_address: c.shipping_address || '',
        notes: c.notes || '',
        account_manager:   c.account_manager   || '',
        salesperson:       c.salesperson       || '',
        operations_person: c.operations_person || '',
        // Per-role commission rate overrides. NULL on the server → '' here →
        // empSelect renders an empty input → server falls back to the role's
        // default rate (AM/SP → 0%, Operations → 5%).
        account_manager_pct: (c.account_manager_pct === null || c.account_manager_pct === undefined) ? '' : c.account_manager_pct,
        salesperson_pct:     (c.salesperson_pct     === null || c.salesperson_pct     === undefined) ? '' : c.salesperson_pct,
        operations_pct:      (c.operations_pct      === null || c.operations_pct      === undefined) ? '' : c.operations_pct,
        // Per-client default profit margin (%). NULL → '' here → UI treats as 50%.
        default_margin_pct:  (c.default_margin_pct  === null || c.default_margin_pct  === undefined) ? '' : c.default_margin_pct
      };
    });

    if (!hasWorkbooks) return 'empty'; // DB reachable but no workbooks — safe to seed

    // Rebuild workbook data
    result.workbooks.forEach(wb => {
      let flowStep = parseInt(wb.flow_step) || 0;
      const flow = {};
      flowSteps.forEach((s, i) => { flow[s] = i < flowStep; });

      const item = {
        id: parseInt(wb.id),
        product: wb.product_name,
        description: wb.description || '',
        dateCreated: new Date(wb.created_at).toLocaleDateString('en-GB', {day:'numeric', month:'short', year:'2-digit'}),
        dateSubmitted: '',
        flow: flow
      };

      if (!clientData[wb.client_name]) clientData[wb.client_name] = [];
      clientData[wb.client_name].push(item);

      // Rebuild detail if stored (skip empty arrays from bad saves)
      const detail = wb.detail;
      if (detail && !Array.isArray(detail) && typeof detail === 'object' && Object.keys(detail).length > 0) {
        workbookDetail[`${wb.client_name}|${wb.id}`] = detail;
      }

      dbWorkbookMap[`${wb.client_name}|${wb.id}`] = wb.id;
    });

    // Once we've confirmed the DB has workbooks, lock out seedDatabase permanently
    // on this device. This prevents duplication if a future get_all_data call
    // transiently returns an empty workbook list.
    try { localStorage.setItem('ms_db_seeded', '1'); } catch(e) {}

    // Rebuild sidebar
    rebuildSidebar();
    saveToLocalStorage();
    return true;
  }

  /* ── Starred Clients ─────────────────────────────────────────────────── */
  let _starredClients = new Set(JSON.parse(localStorage.getItem('ms_starred_clients') || '[]'));

  function toggleNavSection(sectionId) {
    const section = document.getElementById(sectionId);
    if (!section) return;
    section.classList.toggle('collapsed');
    // Persist collapsed state
    const collapsed = JSON.parse(localStorage.getItem('ms_nav_collapsed') || '{}');
    collapsed[sectionId] = section.classList.contains('collapsed');
    localStorage.setItem('ms_nav_collapsed', JSON.stringify(collapsed));
  }

  function toggleStarClient(name, e) {
    e.preventDefault();
    e.stopPropagation();
    if (_starredClients.has(name)) {
      _starredClients.delete(name);
    } else {
      _starredClients.add(name);
    }
    localStorage.setItem('ms_starred_clients', JSON.stringify([..._starredClients]));
    rebuildSidebar();
    // Re-apply active state
    const hash = location.hash;
    const m = hash.match(/^#\/client\/([^/]+)/);
    if (m) updateSidebarActive(decodeURIComponent(m[1]));
  }

  function restoreNavSectionStates() {
    const collapsed = JSON.parse(localStorage.getItem('ms_nav_collapsed') || '{}');
    Object.entries(collapsed).forEach(([id, isCollapsed]) => {
      const el = document.getElementById(id);
      if (!el) return;
      el.classList.toggle('collapsed', isCollapsed);
    });
  }

  function rebuildSidebar() {
    const searchEl = document.getElementById('sidebar-search');
    if (searchEl) { searchEl.textContent = ''; document.getElementById('sidebar-search-ph').style.display = ''; }
    const sorted = Object.keys(clientData).sort();

    // ── Starred list ──
    const starredList = document.getElementById('starred-list');
    starredList.innerHTML = '';
    const starredSection = document.getElementById('nav-section-starred');
    const starredNames = sorted.filter(n => _starredClients.has(n));
    if (starredNames.length === 0) {
      starredSection.style.display = 'none';
    } else {
      starredSection.style.display = '';
      starredNames.forEach(name => starredList.appendChild(makeClientNavItem(name)));
    }
    // Starred/Clients do not show badges — badges are reserved for actionable items only
    const starredBadge = document.getElementById('badge-starred');
    if (starredBadge) { starredBadge.textContent = ''; starredBadge.classList.remove('attention'); }

    // ── Full client list ──
    const clientList = document.getElementById('client-list');
    clientList.innerHTML = '';
    sorted.forEach(name => clientList.appendChild(makeClientNavItem(name)));
    const clientBadge = document.getElementById('badge-clients');
    if (clientBadge) { clientBadge.textContent = ''; clientBadge.classList.remove('attention'); }

    // ── Samples nav ──
    rebuildSamplesNav();

    // ── Orders nav ──
    rebuildOrdersNav();

    // Rebuild modal dropdown
    const select = document.getElementById('modal-client');
    if (select) {
      const firstOpt = select.options[0] ? select.options[0].cloneNode(true) : null;
      select.innerHTML = '';
      if (firstOpt) select.appendChild(firstOpt);
      sorted.forEach(name => {
        const opt = document.createElement('option');
        opt.textContent = name;
        select.appendChild(opt);
      });
    }
  }

  function filterSidebarSearch(query) {
    const q = query.trim().toLowerCase();
    const starredSection = document.getElementById('nav-section-starred');
    const clientSection = document.getElementById('nav-section-clients');

    // Filter starred list
    document.querySelectorAll('#starred-list .nav-item').forEach(el => {
      const name = el.querySelector('span')?.textContent?.toLowerCase() || '';
      el.style.display = (!q || name.includes(q)) ? '' : 'none';
    });

    // Filter client list
    document.querySelectorAll('#client-list .nav-item').forEach(el => {
      const name = el.querySelector('span')?.textContent?.toLowerCase() || '';
      el.style.display = (!q || name.includes(q)) ? '' : 'none';
    });

    // Expand clients section when searching so results are visible
    if (q) {
      clientSection.classList.remove('collapsed');
      if (starredSection.style.display !== 'none') starredSection.classList.remove('collapsed');
    }
  }

  /* ── Recent Nav ─────────────────────────────────────────────────────── */
  const RECENT_NAV_KEY = 'ms_recent_nav';
  const RECENT_NAV_MAX = 10;

  function getRecentNav() {
    try { return JSON.parse(localStorage.getItem(RECENT_NAV_KEY) || '[]'); } catch { return []; }
  }

  function addRecentNav(item) {
    let list = getRecentNav();
    // Remove duplicate
    list = list.filter(r => !(r.type === item.type && r.label === item.label && r.href === item.href));
    list.unshift(item);
    if (list.length > RECENT_NAV_MAX) list = list.slice(0, RECENT_NAV_MAX);
    localStorage.setItem(RECENT_NAV_KEY, JSON.stringify(list));
  }

  function showRecentNav() {
    const dropdown = document.getElementById('sidebar-recent-dropdown');
    if (!dropdown) return;
    const list = getRecentNav();
    if (!list.length) { dropdown.style.display = 'none'; return; }
    dropdown.innerHTML = list.map((r, i) => {
      const avatarClient = r.type === 'workbook' ? r.sub : r.label;
      const avatar = clientAvatarHTML(avatarClient, 20);
      return `
        <a href="${r.href}" onclick="hideRecentNav(); resetSidebarSearch();" style="display:flex; align-items:center; gap:8px; padding:7px 12px; font-size:12px; color:var(--text); text-decoration:none; border-radius:6px; margin:2px 4px;">
          ${avatar}
          <span style="overflow:hidden; text-overflow:ellipsis; white-space:nowrap;">${r.label}</span>
          ${r.sub ? `<span style="font-size:11px; color:var(--text-muted); margin-left:auto; flex-shrink:0; padding-left:6px;">${r.sub}</span>` : ''}
        </a>`;
    }).join('');
    dropdown.style.display = 'block';
  }

  function hideRecentNav() {
    const dropdown = document.getElementById('sidebar-recent-dropdown');
    if (dropdown) dropdown.style.display = 'none';
  }

  function resetSidebarSearch() {
    const el = document.getElementById('sidebar-search');
    const ph = document.getElementById('sidebar-search-ph');
    if (el) el.textContent = '';
    if (ph) ph.style.display = '';
    filterSidebarSearch('');
  }

  /* ── Sidebar Search Engine ────────────────────────────────────────────
     Drop-in replacement for the old "filter visible nav items" search.
     When the operator types into #sidebar-search, this runs a fuzzy
     token-match scan over EVERY entity in memory (clients, workbooks,
     orders, shipments, samples, inventory, commissions, users) and
     renders the top 10 hits as a grouped dropdown. Soft-deleted /
     archived items always render as a separate "Archived" group at the
     bottom regardless of score.

     Permission rule: non-admin sessions never see commissions or users.

     The dropdown reuses #sidebar-recent-dropdown so the recent-nav
     dropdown and the search dropdown never overlap or fight for the
     same screen real estate. */

  // Active highlighted index for keyboard nav. Reset whenever the
  // dropdown re-renders.
  let _sidebarSearchHighlight = -1;

  // Build a fresh entry list from current globals every keystroke. The
  // dataset is small enough (typically a few hundred rows total) that
  // a full rebuild beats any cache-invalidation logic.
  function _buildSearchIndex() {
    const idx = [];
    const isAdmin = !!(window.MS_SESSION && window.MS_SESSION.role === 'admin');
    const enc = encodeURIComponent;
    // The data globals are top-level `let` bindings in the same script
    // scope, so they're NOT on `window` — reference them directly.
    const _clientData     = (typeof clientData     !== 'undefined') ? clientData     : {};
    const _clientDetails  = (typeof clientDetails  !== 'undefined') ? clientDetails  : {};
    const _workbookDetail = (typeof workbookDetail !== 'undefined') ? workbookDetail : {};
    const _orderData      = (typeof orderData      !== 'undefined') ? orderData      : {};
    const _shipmentData   = (typeof shipmentData   !== 'undefined') ? shipmentData   : {};
    const _inventoryData  = (typeof inventoryData  !== 'undefined') ? inventoryData  : [];
    const _commissionsData= (typeof commissionsData!== 'undefined') ? commissionsData: [];
    const _usersCacheLocal= (typeof _usersCache    !== 'undefined') ? _usersCache    : [];

    // ── Clients
    Object.keys(_clientData || {}).forEach(name => {
      const d = _clientDetails[name] || {};
      const fields = [name, d.email, d.phone, d.primary_contact, d.email2, d.phone2, d.primary_contact2, d.notes, d.account_manager, d.salesperson]
        .filter(Boolean).join(' ').toLowerCase();
      idx.push({
        type: 'client', label: name,
        sub: d.primary_contact || d.email || '',
        href: '#/client/' + enc(name),
        archived: false, recencyTs: 0,
        searchText: fields,
        clientName: name
      });
    });

    // ── Workbooks (active + archived). dateCreated is "DD MMM YY"; we
    // approximate recency from the workbook id which auto-increments.
    Object.entries(_clientData || {}).forEach(([clientName, items]) => {
      (items || []).forEach(wb => {
        const detail = _workbookDetail[`${clientName}|${wb.id}`] || {};
        const rfqText = (detail.rfqItems || []).flatMap(i => {
          const variants = (i.variants || []).map(v => v.variant);
          return [i.item, i.sku, ...variants];
        });
        const fields = [wb.product, detail.product, detail.desc, clientName, detail.materials, detail.pantone, detail.cmyk, ...rfqText]
          .filter(Boolean).join(' ').toLowerCase();
        idx.push({
          type: 'workbook',
          label: wb.product || detail.product || 'Untitled workbook',
          sub: clientName,
          href: `#/client/${enc(clientName)}/workbook/${wb.id}`,
          archived: !!wb.deleted_at,
          recencyTs: parseInt(wb.id) || 0,
          searchText: fields,
          clientName, workbookId: wb.id
        });
      });
    });

    // ── Orders
    Object.values(_orderData || {}).forEach(o => {
      const orderItems = (o.entries || []).flatMap(e => {
        const k = `${e.clientName}|${e.workbookId}`;
        const det = _workbookDetail[k] || {};
        return [det.product, ...((det.rfqItems || []).map(r => r.item))];
      });
      const fields = [o.name, o.clientName, o.status, o.poNumber, ...orderItems]
        .filter(Boolean).join(' ').toLowerCase();
      idx.push({
        type: 'order',
        label: o.name || `Order #${o.id}`,
        sub: o.clientName || '',
        href: `#/order/${o.id}`,
        archived: !!o.archived || o.status === 'archived',
        recencyTs: parseInt(o.id) || 0,
        searchText: fields
      });
    });

    // ── Shipments
    Object.values(_shipmentData || {}).forEach(s => {
      idx.push({
        type: 'shipment',
        label: s.name || `Shipment #${s.id}`,
        sub: s.status || '',
        href: `#/shipment/${s.id}`,
        archived: !!s.archived,
        recencyTs: parseInt(s.id) || 0,
        searchText: [s.name, s.status, s.notes].filter(Boolean).join(' ').toLowerCase()
      });
    });

    // ── Samples (RFQ rows flagged as samples)
    if (typeof collectAllSamples === 'function') {
      try {
        collectAllSamples().forEach(sm => {
          idx.push({
            type: 'sample',
            label: sm.item || '(unnamed sample)',
            sub: `${sm.clientName} · ${sm.product}`,
            href: `#/client/${enc(sm.clientName)}/workbook/${sm.workbookId}`,
            archived: false,
            recencyTs: parseInt(sm.workbookId) || 0,
            searchText: [sm.item, sm.product, sm.clientName, sm.status].filter(Boolean).join(' ').toLowerCase()
          });
        });
      } catch (e) { /* collectAllSamples failed — skip samples for now */ }
    }

    // ── Inventory (loaded async; may be empty until the operator opens
    // the Inventory view at least once)
    (_inventoryData || []).forEach(i => {
      const href = (i.client_name && i.workbook_id)
        ? `#/client/${enc(i.client_name)}/workbook/${i.workbook_id}`
        : '#/inventory';
      idx.push({
        type: 'inventory',
        label: i.sku || i.product_name || 'SKU',
        sub: [i.client_name, i.variant_name].filter(Boolean).join(' · '),
        href,
        archived: false,
        recencyTs: i.promoted_at ? new Date(i.promoted_at).getTime() : 0,
        searchText: [i.sku, i.product_name, i.variant_name, i.client_name].filter(Boolean).join(' ').toLowerCase()
      });
    });

    // ── Admin-only: commissions and users
    if (isAdmin) {
      (_commissionsData || []).forEach(c => {
        idx.push({
          type: 'commission',
          label: `${c.employee || 'Unknown'} · ${c.role || ''}`,
          sub: `${c.client_name || ''}${c.commission_amount != null ? ' · $' + parseFloat(c.commission_amount).toFixed(2) : ''}`,
          href: '#/commissions',
          archived: false,
          recencyTs: c.created_at ? new Date(c.created_at).getTime() : 0,
          searchText: [c.employee, c.role, c.client_name, c.product_name, c.sku, c.status].filter(Boolean).join(' ').toLowerCase()
        });
      });
      (_usersCacheLocal || []).forEach(u => {
        idx.push({
          type: 'user',
          label: u.display_name || u.username,
          sub: u.email || u.username || '',
          href: '__open-users-modal__',
          archived: false, recencyTs: 0,
          searchText: [u.username, u.display_name, u.email].filter(Boolean).join(' ').toLowerCase()
        });
      });
    }

    return idx;
  }

  // Score a single token against an entry's searchText. Substring with a
  // word-start boost beats a fuzzy character-skip match.
  function _searchTokenScore(token, text) {
    if (!token) return 0;
    const idxOf = text.indexOf(token);
    if (idxOf >= 0) {
      const wordStart = idxOf === 0 || /[\s·\-\/|]/.test(text.charAt(idxOf - 1));
      return wordStart ? 1.0 : 0.85;
    }
    // Fuzzy: every char of the token must appear in text in order.
    // Score by gap density so contiguous matches outrank scattered ones.
    let i = 0, j = 0, lastIdx = -1, gapPenalty = 0;
    while (i < token.length && j < text.length) {
      if (token.charAt(i) === text.charAt(j)) {
        if (lastIdx !== -1) gapPenalty += (j - lastIdx - 1);
        lastIdx = j;
        i++;
      }
      j++;
    }
    if (i < token.length) return 0;
    return Math.max(0.15, 0.55 - (gapPenalty / (text.length || 1)) * 0.4);
  }

  function _searchEntryScore(query, entry) {
    const tokens = query.split(/\s+/).filter(Boolean);
    if (!tokens.length) return 0;
    let total = 0;
    for (const tok of tokens) {
      const s = _searchTokenScore(tok, entry.searchText);
      if (s === 0) return 0; // strict AND across tokens
      total += s;
    }
    // Small label-prefix bonus so "fre" prefers a client called Fresh
    // Her over a workbook whose RFQ contains "fresh" deep inside.
    const labelLower = (entry.label || '').toLowerCase();
    const labelBonus = (tokens.some(t => labelLower.startsWith(t))) ? 0.4 : 0;
    return (total / tokens.length) + labelBonus;
  }

  const _SEARCH_TYPE_ORDER = ['client', 'workbook', 'order', 'shipment', 'sample', 'inventory', 'commission', 'user'];
  const _SEARCH_TYPE_LABEL = {
    client: 'Clients', workbook: 'Workbooks', order: 'Orders',
    shipment: 'Shipments', sample: 'Samples', inventory: 'Inventory',
    commission: 'Commissions', user: 'Users'
  };
  const _SEARCH_TYPE_ICON = {
    client: '👤', workbook: '📓', order: '🧾', shipment: '📦',
    sample: '🔖', inventory: '🏷️', commission: '💰', user: '👥'
  };

  // Top-level entry point: called from the search box's oninput. Handles
  // both the "empty query → recent searches" and the "non-empty → search
  // results" cases, plus updates the inline starred/client nav filter.
  function sidebarSearchUpdate(query) {
    const q = (query || '').trim();
    // Keep the legacy inline-filter behavior so the visible sidebar nav
    // also narrows down. Cheap and additive.
    if (typeof filterSidebarSearch === 'function') filterSidebarSearch(q);
    if (!q) {
      _showRecentSearches();
      return;
    }
    _sidebarSearchHighlight = 0;
    _renderSidebarSearchResults(q);
  }

  // ── Recent searches (replaces "recent nav" in this dropdown) ─────────
  // Queries the operator has actually committed (i.e. clicked a result
  // or hit Enter on a result) get saved to localStorage. Most recent
  // first, deduped, capped at 10. On focus with an empty input we render
  // these as a clickable list — click a query to refill the box and
  // re-run the search.
  const RECENT_SEARCH_KEY = 'ms_recent_searches';
  const RECENT_SEARCH_MAX = 10;

  function _getRecentSearches() {
    try { return JSON.parse(localStorage.getItem(RECENT_SEARCH_KEY) || '[]'); }
    catch { return []; }
  }
  function _addRecentSearch(q) {
    const trimmed = (q || '').trim();
    if (!trimmed) return;
    let list = _getRecentSearches().filter(r => r.toLowerCase() !== trimmed.toLowerCase());
    list.unshift(trimmed);
    if (list.length > RECENT_SEARCH_MAX) list = list.slice(0, RECENT_SEARCH_MAX);
    localStorage.setItem(RECENT_SEARCH_KEY, JSON.stringify(list));
  }
  function _removeRecentSearch(q) {
    const list = _getRecentSearches().filter(r => r !== q);
    localStorage.setItem(RECENT_SEARCH_KEY, JSON.stringify(list));
    _showRecentSearches();
  }
  function _clearRecentSearches() {
    localStorage.removeItem(RECENT_SEARCH_KEY);
    _showRecentSearches();
  }
  function _showRecentSearches() {
    const dropdown = document.getElementById('sidebar-recent-dropdown');
    if (!dropdown) return;
    const list = _getRecentSearches();
    _sidebarSearchEntries = []; // recent-search rows are NOT entry rows
    if (list.length === 0) {
      dropdown.style.display = 'none';
      return;
    }
    const escQ = q => String(q).replace(/[<&>"']/g, c => ({'<':'&lt;','&':'&amp;','>':'&gt;','"':'&quot;',"'":'&#39;'})[c]);
    let html = `<div style="display:flex; align-items:center; padding:8px 12px 4px; font-size:9.5px; font-weight:800; text-transform:uppercase; letter-spacing:0.07em; color:var(--text-muted);">
      <span style="flex:1;">Recent Searches</span>
      <a href="#" onmousedown="event.preventDefault(); _clearRecentSearches();" style="color:var(--text-muted); text-decoration:none; font-weight:600; font-size:10px; opacity:0.7;">Clear</a>
    </div>`;
    list.forEach(q => {
      const safe = escQ(q);
      html += `<a href="#"
                  onmousedown="event.preventDefault(); _runRecentSearch(this.dataset.q);"
                  data-q="${safe}"
                  style="display:flex; align-items:center; gap:8px; padding:7px 12px; font-size:12px; color:var(--text); text-decoration:none; border-radius:6px; margin:1px 4px; cursor:pointer;">
        <span style="width:18px; flex-shrink:0; text-align:center; font-size:11px; opacity:0.6;">↻</span>
        <span style="flex:1; min-width:0; overflow:hidden; white-space:nowrap; text-overflow:ellipsis;">${safe}</span>
        <span onmousedown="event.stopPropagation(); event.preventDefault(); _removeRecentSearch(this.parentElement.dataset.q);"
              style="font-size:13px; color:var(--text-muted); padding:0 4px; opacity:0.5; flex-shrink:0;"
              title="Remove from recent">×</span>
      </a>`;
    });
    dropdown.innerHTML = html;
    dropdown.style.display = 'block';
    dropdown.style.maxHeight = '60vh';
    dropdown.style.overflowY = 'auto';
  }
  function _runRecentSearch(q) {
    const el = document.getElementById('sidebar-search');
    const ph = document.getElementById('sidebar-search-ph');
    if (el) { el.textContent = q; el.focus(); }
    if (ph) ph.style.display = 'none';
    sidebarSearchUpdate(q);
  }

  // Stash entries in render order so click + keyboard handlers can map
  // a row index back to its entry without globals.
  let _sidebarSearchEntries = [];

  function _renderSidebarSearchResults(q) {
    const dropdown = document.getElementById('sidebar-recent-dropdown');
    if (!dropdown) return;
    const lc = q.toLowerCase();
    const idx = _buildSearchIndex();
    // Score every entry; keep matches only.
    const scored = [];
    for (const entry of idx) {
      const score = _searchEntryScore(lc, entry);
      if (score > 0) scored.push({ entry, score });
    }
    // Tiebreak by recency desc.
    scored.sort((a, b) => (b.score - a.score) || (b.entry.recencyTs - a.entry.recencyTs));

    // Split active vs archived. Active uses top 10 by score. Archived
    // shows up to 10 of its own at the very bottom regardless.
    const active   = scored.filter(s => !s.entry.archived).slice(0, 10);
    const archived = scored.filter(s =>  s.entry.archived).slice(0, 10);

    if (active.length === 0 && archived.length === 0) {
      _sidebarSearchEntries = [];
      dropdown.innerHTML = `<div style="padding:14px 12px; font-size:12px; color:var(--text-muted); font-style:italic; text-align:center;">No matches for "${q.replace(/[<&>"]/g, c => ({'<':'&lt;','&':'&amp;','>':'&gt;','"':'&quot;'})[c])}"</div>`;
      dropdown.style.display = 'block';
      return;
    }

    // Group active hits by type. Track flattened render order so click
    // handlers can resolve rowIdx → entry.
    const byType = new Map();
    active.forEach(({ entry }) => {
      if (!byType.has(entry.type)) byType.set(entry.type, []);
      byType.get(entry.type).push(entry);
    });

    const flat = [];
    let html = '';
    _SEARCH_TYPE_ORDER.forEach(type => {
      if (!byType.has(type)) return;
      html += `<div style="padding:8px 12px 4px; font-size:9.5px; font-weight:800; text-transform:uppercase; letter-spacing:0.07em; color:var(--text-muted);">${_SEARCH_TYPE_LABEL[type]}</div>`;
      byType.get(type).forEach(entry => {
        html += _renderSearchRow(entry, flat.length);
        flat.push(entry);
      });
    });

    if (archived.length > 0) {
      html += `<div style="padding:10px 12px 4px; margin-top:4px; font-size:9.5px; font-weight:800; text-transform:uppercase; letter-spacing:0.07em; color:var(--text-muted); border-top:1px solid var(--border);">Archived</div>`;
      archived.forEach(({ entry }) => {
        html += _renderSearchRow(entry, flat.length, /*muted=*/true);
        flat.push(entry);
      });
    }

    _sidebarSearchEntries = flat;
    dropdown.innerHTML = html;
    dropdown.style.display = 'block';
    dropdown.style.maxHeight = '60vh';
    dropdown.style.overflowY = 'auto';
    _sidebarSearchHighlightRefresh();
  }

  function _renderSearchRow(entry, rowIdx, muted) {
    const labelEsc = String(entry.label || '').replace(/[<&>]/g, c => ({'<':'&lt;','&':'&amp;','>':'&gt;'})[c]);
    const subEsc   = String(entry.sub   || '').replace(/[<&>]/g, c => ({'<':'&lt;','&':'&amp;','>':'&gt;'})[c]);
    const icon = _SEARCH_TYPE_ICON[entry.type] || '·';
    const opacity = muted ? '0.6' : '1';
    // Use mousedown (not click) so the row fires before the search box's
    // onblur tears down the dropdown.
    return `<a href="#" onmousedown="event.preventDefault(); _sidebarSearchClick(${rowIdx});"
              data-search-row="${rowIdx}"
              style="display:flex; align-items:center; gap:8px; padding:7px 12px; font-size:12px; color:var(--text); text-decoration:none; border-radius:6px; margin:1px 4px; opacity:${opacity}; cursor:pointer;">
      <span style="width:18px; flex-shrink:0; text-align:center; font-size:12px;">${icon}</span>
      <span style="flex:1; min-width:0; overflow:hidden;">
        <span style="display:block; font-weight:600; white-space:nowrap; text-overflow:ellipsis; overflow:hidden;">${labelEsc}</span>
        ${entry.sub ? `<span style="display:block; font-size:10.5px; color:var(--text-muted); white-space:nowrap; text-overflow:ellipsis; overflow:hidden;">${subEsc}</span>` : ''}
      </span>
    </a>`;
  }

  function _sidebarSearchClick(rowIdx) {
    const entry = _sidebarSearchEntries[rowIdx];
    if (!entry) return;
    // Persist the query that led to this click so the operator can
    // re-run it from the dropdown later.
    const currentQuery = (document.getElementById('sidebar-search')?.textContent || '').trim();
    if (currentQuery) _addRecentSearch(currentQuery);
    resetSidebarSearch();
    hideRecentNav();
    if (entry.href === '__open-users-modal__') {
      if (typeof openUsersModal === 'function') openUsersModal();
      return;
    }
    if (entry.href) location.hash = entry.href;
  }

  function _sidebarSearchHighlightRefresh() {
    const dropdown = document.getElementById('sidebar-recent-dropdown');
    if (!dropdown) return;
    dropdown.querySelectorAll('[data-search-row]').forEach(el => {
      const idx = parseInt(el.dataset.searchRow);
      if (idx === _sidebarSearchHighlight) {
        el.style.background = 'var(--accent-glow)';
        el.scrollIntoView({ block: 'nearest' });
      } else {
        el.style.background = '';
      }
    });
  }

  function sidebarSearchKeydown(e) {
    if (e.key === 'Enter') {
      e.preventDefault();
      if (_sidebarSearchHighlight >= 0 && _sidebarSearchEntries[_sidebarSearchHighlight]) {
        _sidebarSearchClick(_sidebarSearchHighlight);
      }
      return;
    }
    if (e.key === 'Escape') {
      e.preventDefault();
      hideRecentNav();
      e.target.blur();
      return;
    }
    if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
      const total = _sidebarSearchEntries.length;
      if (total === 0) return;
      e.preventDefault();
      if (e.key === 'ArrowDown') _sidebarSearchHighlight = (_sidebarSearchHighlight + 1) % total;
      else _sidebarSearchHighlight = (_sidebarSearchHighlight - 1 + total) % total;
      _sidebarSearchHighlightRefresh();
    }
  }

  function getClientLogo(clientName) {
    const workbooks = clientData[clientName] || [];
    // Prefer dedicated clientLogo first
    for (const wb of workbooks) {
      const detail = workbookDetail[`${clientName}|${wb.id}`];
      if (detail && detail.clientLogo) return detail.clientLogo;
    }
    // Fall back to first art image
    for (const wb of workbooks) {
      const detail = workbookDetail[`${clientName}|${wb.id}`];
      if (detail && detail.artImages && detail.artImages.length > 0) return detail.artImages[0];
    }
    return null;
  }

  function clientAvatarHTML(clientName, size = 20) {
    const logo = getClientLogo(clientName);
    if (logo) {
      return `<img src="${logo}" style="width:${size}px; height:${size}px; border-radius:4px; object-fit:contain; flex-shrink:0; background:var(--surface);" />`;
    }
    const initials = clientName.trim().charAt(0).toUpperCase();
    return `<span style="width:${size}px; height:${size}px; border-radius:4px; background:var(--accent); color:#fff; font-size:${Math.round(size*0.55)}px; font-weight:700; display:flex; align-items:center; justify-content:center; flex-shrink:0;">${initials}</span>`;
  }

  function makeClientNavItem(name) {
    const a = document.createElement('a');
    a.className = 'nav-item';
    a.href = `#/client/${encodeURIComponent(name)}`;

    const avatar = document.createElement('span');
    avatar.innerHTML = clientAvatarHTML(name, 20);
    avatar.style.display = 'flex';
    avatar.style.flexShrink = '0';
    a.appendChild(avatar.firstElementChild || avatar);

    const span = document.createElement('span');
    span.textContent = name;
    span.style.flex = '1';
    span.style.overflow = 'hidden';
    span.style.textOverflow = 'ellipsis';
    span.style.whiteSpace = 'nowrap';
    a.appendChild(span);

    const starBtn = document.createElement('button');
    starBtn.className = 'nav-star-btn' + (_starredClients.has(name) ? ' starred' : '');
    starBtn.title = _starredClients.has(name) ? 'Unstar' : 'Star';
    starBtn.textContent = '★';
    starBtn.addEventListener('click', (e) => toggleStarClient(name, e));
    a.appendChild(starBtn);

    const delBtn = document.createElement('button');
    delBtn.className = 'client-delete-btn';
    delBtn.title = 'Delete client';
    delBtn.textContent = '✕';
    delBtn.addEventListener('click', (e) => {
      e.preventDefault();
      e.stopPropagation();
      openDeleteClientModal(name);
    });
    a.appendChild(delBtn);

    return a;
  }

  function flowToStep(flow) {
    let step = 0;
    for (let i = 0; i < flowSteps.length; i++) {
      if (flow[flowSteps[i]]) step = i + 1;
      else break;
    }
    return step;
  }

