  /* ── Status Bar ──────────────────────────────────────────────────────────── */
  const flowSteps = ['quoteChina', 'quoteSubmitted', 'quoteClient', 'clientApproved', 'officeInvoice', 'confirmedPayment', 'orderChina'];
  const flowLabels = ['Quote', 'Quote Submitted', 'Quote to Client', 'Client Approved', 'Office Invoice', 'Confirmed Payment', 'Ordered'];
  const flowLabelsShort = ['Quote', 'Submitted', 'Quote', 'Approved', 'Invoice', 'Payment', 'Ordered'];
  let currentClient = '';
  let currentWorkbookId = '';
  let _wbBackHash  = null;  // set before navigating into a workbook from a non-client context
  let _wbBackLabel = null;

  function renderStatusBar(flow) {
    flow = flow || {};  // defensive: never crash on missing flow
    const statusFlow = document.getElementById('status-flow');
    if (!statusFlow) return;
    statusFlow.innerHTML = flowSteps.map((s, i) => `
      <div class="status-step">
        <div class="status-step-bar ${flow[s] ? 'filled' : ''}"></div>
        <span class="status-step-label"><span class="label-full">${flowLabels[i]}</span><span class="label-short">${flowLabelsShort[i]}</span></span>
      </div>
    `).join('');

    // Find current status and next step
    let currentIdx = -1;
    for (let i = flowSteps.length - 1; i >= 0; i--) {
      if (flow[flowSteps[i]]) { currentIdx = i; break; }
    }

    const advanceBtn = document.getElementById('btn-advance');
    const backBtn = document.getElementById('btn-back-step');
    backBtn.disabled = currentIdx < 0;

    if (currentIdx < flowSteps.length - 1) {
      advanceBtn.textContent = flowLabels[currentIdx + 1];
      advanceBtn.disabled = false;
    } else {
      advanceBtn.textContent = 'Completed';
      advanceBtn.disabled = true;
    }

    // Show "Notify Client" button ONLY while the workbook is at the
    // Quote-to-Client stage — i.e. that step has just been marked
    // complete but the next one (Client Approved) hasn't yet. Clears
    // the button from every other stage so the operator can't
    // accidentally re-send the quote email after the order has moved on.
    const notifyBtn = document.getElementById('btn-notify-quote');
    if (notifyBtn) {
      const show = !!flow.quoteClient && !flow.clientApproved;
      notifyBtn.style.display = show ? 'inline-flex' : 'none';
    }

    // Stack wrapper visible while we have at least one workflow-stage
    // action to show — covers stages 1 (Sent to RFQ + Send for Review)
    // and 2 (Notify Client). Inner buttons handle their own narrower
    // windows so only the applicable buttons render inside.
    const sendRfqBtn   = document.getElementById('btn-send-rfq');
    const rfqStackWrap = document.getElementById('rfq-btn-stack');
    if (rfqStackWrap) {
      const showStack = !!flow.quoteSubmitted && !flow.clientApproved;
      rfqStackWrap.style.display = showStack ? 'flex' : 'none';
      if (sendRfqBtn) {
        // Sent-to-RFQ only applies at stage 1 (quoteSubmitted, not yet
        // quoteClient). Once sent, the button locks itself — the
        // operator has to use the status-bar back button to drop the
        // flag before they can re-send. Prevents accidental re-fires.
        const rfqApplicable = !!flow.quoteSubmitted && !flow.quoteClient;
        sendRfqBtn.style.display = rfqApplicable ? 'inline-flex' : 'none';
        if (rfqApplicable) {
          const detail = workbookDetail[`${currentClient}|${currentWorkbookId}`] || {};
          const sent = !!detail.sentToRfq;
          const label = document.getElementById('btn-send-rfq-label');
          if (label) label.textContent = sent ? '✓ Sent to RFQ' : 'RFQ';
          sendRfqBtn.style.background = sent ? 'var(--accent)' : 'none';
          sendRfqBtn.style.color = sent ? '#fff' : 'var(--accent)';
          sendRfqBtn.disabled = sent;
          sendRfqBtn.style.cursor = sent ? 'not-allowed' : 'pointer';
          sendRfqBtn.style.opacity = sent ? '0.85' : '1';
          sendRfqBtn.title = sent
            ? 'Already in the RFQ queue. Use the back button (←) to undo and re-send.'
            : 'Send this workbook to the RFQ queue for review';
        }
      }
    }

    // "Send for Review" — visible only at stage 1 (quoteSubmitted, not
    // yet advanced past). Because submit_for_review no longer auto-
    // advances the flow_step, the workbook STAYS at stage 1 after Karen
    // clicks the button — so the button stays on screen (in its filled
    // 'Sent ✓' state) until the operator manually advances the flow.
    //   • detail.sentForReview === false  → outlined, paper-plane icon,
    //                                        label 'Send for Review'.
    //   • detail.sentForReview === true   → filled success-green, check
    //                                        icon, label 'Sent for Review'.
    // Clicking when already sent re-fires the email (server is
    // idempotent — see submit_for_review).
    const sendReviewBtn = document.getElementById('btn-submit-review');
    if (sendReviewBtn) {
      const detail = workbookDetail[`${currentClient}|${currentWorkbookId}`] || {};
      const inReviewWindow = !!flow.quoteSubmitted && !flow.quoteClient;
      sendReviewBtn.style.display = inReviewWindow ? 'inline-flex' : 'none';
      if (inReviewWindow) {
        const alreadySent = !!detail.sentForReview;
        const iconSend = sendReviewBtn.querySelector('.btn-submit-review-icon-send');
        const iconSent = sendReviewBtn.querySelector('.btn-submit-review-icon-sent');
        const label    = document.getElementById('btn-submit-review-label');
        // Once sent, the button locks. Same model as Sent to RFQ —
        // operator goes back via the status-bar back button (←) to
        // re-enable it (revertStatus clears the flag).
        sendReviewBtn.disabled = alreadySent;
        sendReviewBtn.style.cursor = alreadySent ? 'not-allowed' : 'pointer';
        sendReviewBtn.style.opacity = alreadySent ? '0.85' : '1';
        if (alreadySent) {
          sendReviewBtn.style.background   = 'var(--success, #10b981)';
          sendReviewBtn.style.color        = '#fff';
          sendReviewBtn.style.borderColor  = 'var(--success, #10b981)';
          sendReviewBtn.title              = 'Already sent to Jackson + Parker. Use the back button (←) to undo and re-send.';
          if (iconSend) iconSend.style.display = 'none';
          if (iconSent) iconSent.style.display = '';
          if (label)    label.textContent      = 'Sent for Review';
        } else {
          sendReviewBtn.style.background   = 'none';
          sendReviewBtn.style.color        = 'var(--accent)';
          sendReviewBtn.style.borderColor  = 'var(--accent)';
          sendReviewBtn.title              = 'Mark this workbook as ready for review — emails Jackson + Parker.';
          if (iconSend) iconSend.style.display = '';
          if (iconSent) iconSent.style.display = 'none';
          if (label)    label.textContent      = 'Send for Review';
        }
      }
    }

    // Lock Product Overview tab once Quote to Client (index 2) or beyond
    lockWorkbookTab(currentIdx >= 2);
  }

  /* ── Notification system ─────────────────────────────────────────────────── */
  let _notifyPayload = null; // stores the data ready to send

  // Tiny HTML-escape helper for the email preview iframe — keeps client
  // names / product names / item names from breaking out of attributes
  // or injecting script tags into the preview document.
  function _escHtml(s) {
    return String(s == null ? '' : s)
      .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
  }

  // Build the quote preview HTML for the iframe — mirrors the on-screen
  // Client Quote section on the Pricing tab (same blue header/footer
  // bars, same stat cards, same rolled-up parent + variant-SKU rows,
  // same Additional Fees section). Values read live from the rendered
  // page so the preview always ties out to what the operator just
  // approved before pressing 'Send to Client'.
  //
  // Pricing math (matches the on-screen Client Quote):
  //   • Sale Price (USD) read from the qrs-usd stat in the header bar.
  //   • Per-row line totals = rowQty × salePerUsd (qty from rfqItems —
  //     blank when the operator hasn't entered a row qty, same as the
  //     on-screen table).
  //   • TOTAL ORDER stat read straight from qrs-total — that's the
  //     authoritative tier-qty × Sale Per + applied fees computation
  //     and is what the customer is being quoted.
  // Generate a quote number like "Q-2026-0072". 4-digit year + the
  // workbook id zero-padded to 4 digits. Stable for a given workbook,
  // so the same quote always shows the same Q-number in the preview /
  // emails / portal.
  function _quoteNumberFor(year, wbId) {
    const y = year || new Date().getFullYear();
    const id = parseInt(wbId, 10) || 0;
    return `Q-${y}-${String(id).padStart(4, '0')}`;
  }

  // Pull a stat value from the on-screen Client Quote header bar
  // (#pricing-quote-ref-card). The header bar is populated by
  // renderPricingTab so the value is always up to date. Returns
  // '—' when the element / value isn't there.
  function _readQuoteStat(key) {
    const el = document.querySelector(`.cq-summary-bar--header [data-qrs="${key}"]`);
    return el && el.textContent ? el.textContent.trim() : '—';
  }

  // Render the rich quote preview directly into the modal body (no
  // iframe). Matches the design reference — light grey backdrop,
  // white email card with subject + from/to/date + greeting + body
  // copy + embedded Client Quote card + Approve quote CTA.
  function _renderQuotePreviewModal(payload, wbId) {
    const host = document.getElementById('notify-modal-body');
    if (!host) return;
    const d            = payload && payload.details ? payload.details : {};
    const product      = _escHtml(d.product || 'your product');
    const contact      = _escHtml(payload.contact_name || '');
    const clientEmail  = _escHtml(payload.client_email || '');
    const contactFirst = (payload.contact_name || '').trim().split(/\s+/)[0] || '';
    const greeting     = contactFirst ? `Hi ${_escHtml(contactFirst)},` : 'Hi there,';
    const items        = Array.isArray(d.rfqItems) ? d.rfqItems.filter(i => i && (i.item || i.qty || (i.variants||[]).length)) : [];
    const fmt2         = v => Number(v || 0).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    const intFmt       = v => Number(v || 0).toLocaleString('en-US');

    // Pull live values from the on-screen Client Quote header — these
    // are populated by renderPricingTab so they're already correct.
    const stats = {
      salePrice:      _readQuoteStat('usd'),
      totalOrder:     _readQuoteStat('total'),
      productionLead: _readQuoteStat('lead'),
      shippingLead:   _readQuoteStat('ship-lead'),
      totalLead:      _readQuoteStat('total-lead'),
    };
    // Parse Sale Per back to a number for the per-row line totals.
    const salePerUsd = parseFloat(String(stats.salePrice).replace(/[^\d.]/g, '')) || 0;

    // Build one row per parent SKU. The Item cell shows the parent
    // name (bold) with the variant SKUs listed inline in muted mono
    // type. If a qty was entered we append ' = N' to match the on-
    // screen design. Variant qtys roll up to the parent row's Qty cell.
    const lineRows = items.map((it, idx) => {
      const parentName = (it.item || `Item ${idx + 1}`).trim();
      const variants   = Array.isArray(it.variants) ? it.variants.filter(v => v && (v.variant || v.qty || v.priceRmb || v.sku)) : [];
      let qty = 0;
      const variantSkus = [];
      if (variants.length) {
        variants.forEach(v => {
          qty += parseFloat(String(v.qty || '').replace(/,/g, '')) || 0;
          const code = String(v.sku || v.variant || '').trim();
          if (code) variantSkus.push(code);
        });
      } else {
        qty = parseFloat(String(it.qty || '').replace(/,/g, '')) || 0;
      }
      const lineTotal = qty > 0 && salePerUsd > 0 ? qty * salePerUsd : 0;
      return { idx: idx + 1, parentName, variantSkus, qty, lineTotal };
    });

    // Applied additional fees (Added Shipping Cost for Air + UPS,
    // tooling fees, etc.) read via the same appliedFeesList helper the
    // on-screen Client Quote uses.
    const fees = (typeof appliedFeesList === 'function') ? appliedFeesList() : [];

    // Quote number + date for the email subject / metadata row.
    const now = new Date();
    const quoteNum = _quoteNumberFor(now.getFullYear(), wbId);
    const monthNames = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
    const dateStr = `${monthNames[now.getMonth()]} ${now.getDate()}, ${now.getFullYear()}`;
    const productNameRaw = d.product || 'your product';

    const subject = `Your Market Sculpt quote is ready · ${quoteNum}`;

    // ── Render the modal body ─────────────────────────────────────────
    const lineRowsHtml = lineRows.length === 0
      ? `<tr><td colspan="5" style="padding:18px 14px; text-align:center; color:#92400e; background:#fef3c7; font-size:13px;">⚠️ No line items entered yet — the client will receive an email with no quote table. Add RFQ items before sending.</td></tr>`
      : lineRows.map(r => {
          const variantList = r.variantSkus.length
            ? `<span class="nq-item-variants">: ${_escHtml(r.variantSkus.join(', '))}</span>${r.qty > 0 ? `<span class="nq-item-qty-suffix">= ${intFmt(r.qty)}</span>` : ''}`
            : '';
          return `<tr>
            <td class="nq-num-cell">${r.idx}</td>
            <td><span class="nq-item-parent">${_escHtml(r.parentName)}</span>${variantList}</td>
            <td class="nq-right" style="font-weight:600;">${r.qty > 0 ? intFmt(r.qty) : '—'}</td>
            <td class="nq-right">${salePerUsd > 0 ? '$' + fmt2(salePerUsd) : '—'}</td>
            <td class="nq-right nq-total-cell">${r.lineTotal > 0 ? '$' + fmt2(r.lineTotal) : '—'}</td>
          </tr>`;
        }).join('');

    const feesRows = fees.length === 0 ? '' :
      `<tr class="nq-fees-header"><td colspan="5">Additional Fees</td></tr>` +
      fees.map(f => {
        const desc = f.desc ? ` — <span style="color:var(--text-muted); font-weight:400;">${_escHtml(f.desc)}</span>` : '';
        return `<tr class="nq-fee-row">
          <td class="nq-num-cell">+</td>
          <td>${_escHtml(f.label)}${desc}</td>
          <td class="nq-right" style="color:var(--text-muted);">—</td>
          <td class="nq-right" style="color:var(--text-muted);">—</td>
          <td class="nq-right nq-total-cell">${f.usd > 0 ? '$' + fmt2(f.usd) : '—'}</td>
        </tr>`;
      }).join('');

    const statsHtml = `
      <div class="nq-stat-row">
        <div class="nq-stat"><div class="nq-stat-label">Sale Price (USD)</div><div class="nq-stat-value">${_escHtml(stats.salePrice)}</div></div>
        <div class="nq-stat nq-stat--total"><div class="nq-stat-label">Total Order</div><div class="nq-stat-value">${_escHtml(stats.totalOrder)}</div></div>
        <div class="nq-stat"><div class="nq-stat-label">Production Lead</div><div class="nq-stat-value">${_escHtml(stats.productionLead)}</div></div>
        <div class="nq-stat"><div class="nq-stat-label">Shipping Lead</div><div class="nq-stat-value">${_escHtml(stats.shippingLead)}</div></div>
        <div class="nq-stat"><div class="nq-stat-label">Total Lead</div><div class="nq-stat-value">${_escHtml(stats.totalLead)}</div></div>
      </div>`;

    const recipientHtml = clientEmail
      ? `<strong>${contact || 'Client'}</strong> <span class="nq-email-addr">&lt;${clientEmail}&gt;</span>`
      : `<span style="color:#fb7185;">⚠️ No client email on file — internal only.</span>`;

    host.innerHTML = `
      <div class="nq-email">
        <div class="nq-email-head">
          <h2 class="nq-email-subject">${_escHtml(subject)}</h2>
          <div class="nq-email-from">
            <div class="nq-email-avatar">MS</div>
            <div class="nq-email-meta">
              <div class="nq-email-from-name"><strong>Market Sculpt</strong> <span class="nq-email-addr">&lt;quotes@marketsculpt.com&gt;</span></div>
              <div class="nq-email-to">to ${recipientHtml}</div>
            </div>
            <div class="nq-email-date">${_escHtml(dateStr)}</div>
          </div>
        </div>
        <div class="nq-email-body">
          <p class="nq-greeting">${_escHtml(greeting)}</p>
          <p class="nq-paragraph">Thanks for the opportunity — here's the quote for your ${_escHtml(productNameRaw)} order. Everything's itemized below with current pricing and lead times. Let me know if you'd like any adjustments and I'll get production scheduled right away.</p>
          <p class="nq-signoff">Best,<br>The Market Sculpt Team</p>

          <div class="nq-quote-card">
            <div class="nq-quote-head">
              <span class="nq-quote-head-title">Client Quote</span>
              <span class="nq-quote-head-total">Total ${_escHtml(stats.totalOrder)}</span>
            </div>
            ${statsHtml}
            <table class="nq-quote-table">
              <thead>
                <tr>
                  <th class="nq-num">#</th>
                  <th>Item</th>
                  <th class="nq-right">Qty</th>
                  <th class="nq-right">Sale Price</th>
                  <th class="nq-right">Total (USD)</th>
                </tr>
              </thead>
              <tbody>${lineRowsHtml}${feesRows}</tbody>
            </table>
          </div>

          <div class="nq-approve-wrap">
            <button type="button" class="nq-approve-btn" aria-disabled="true" tabindex="-1">
              Approve quote
              <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><polyline points="9 18 15 12 9 6"/></svg>
            </button>
            <div class="nq-approve-note">Questions? Just reply to this email.</div>
          </div>
        </div>
      </div>`;
  }

  // Order-status preview — keeps the simpler text summary since the
  // server-side template for orders is more complex (multi-workbook,
  // per-variant sale-price flatten) and isn't worth duplicating
  // client-side. Same modal body slot as the rich quote preview.
  function _renderOrderStatusPreviewModal(payload, label, summaryText) {
    const host = document.getElementById('notify-modal-body');
    if (!host) return;
    const clientEmail = _escHtml(payload.client_email || '');
    const contact     = _escHtml(payload.contact_name || '');
    const recipientHtml = clientEmail
      ? `<strong>${contact || 'Client'}</strong> <span class="nq-email-addr">&lt;${clientEmail}&gt;</span>`
      : `<span style="color:#fb7185;">⚠️ No client email on file — internal only.</span>`;
    host.innerHTML = `
      <div class="nq-order-summary">
        <h2>Notify Client — ${_escHtml(label)}</h2>
        <div style="font-size:12px; color:var(--text-muted); margin-bottom:14px;">to ${recipientHtml}</div>
        <div class="nq-body-text">${_escHtml(summaryText || '')}</div>
      </div>`;
  }

  function openNotifyModal(triggerType) {
    _notifyPayload = null;

    // Hide the CSV / PDF / Edit buttons by default — they only make
    // sense for the quote_ready preview. Re-enable inside the relevant
    // branch.
    const exportCsv = document.getElementById('nq-export-csv');
    const exportPdf = document.getElementById('nq-export-pdf');
    if (exportCsv) exportCsv.style.display = 'none';
    if (exportPdf) exportPdf.style.display = 'none';

    if (triggerType === 'quote_ready') {
      const detail    = workbookDetail[`${currentClient}|${currentWorkbookId}`] || {};
      const clientDet = clientDetails[currentClient] || {};
      const clientEmail = clientDet.email || '';
      const contactName = clientDet.primary_contact || '';
      const product   = detail.product || document.getElementById('product-name')?.value || 'Product';
      const rfqItems  = (detail.rfqItems || collectRfqItems()).filter(i => i.item || i.qty || i.priceRmb);

      const wbDbId  = dbWorkbookMap[`${currentClient}|${currentWorkbookId}`] || currentWorkbookId;
      const quoteAppUrl = `${window.location.origin}/#/client/${encodeURIComponent(currentClient)}/workbook/${wbDbId}`;

      _notifyPayload = {
        type: 'quote_ready', client_email: clientEmail, contact_name: contactName,
        client_name: currentClient, rate: USD_TO_RMB,
        details: { product, rfqItems, app_url: quoteAppUrl }
      };

      if (exportCsv) exportCsv.style.display = '';
      if (exportPdf) exportPdf.style.display = '';

      _renderQuotePreviewModal(_notifyPayload, wbDbId);
    }

    else if (triggerType === 'order_status') {
      const o = orderData[_currentOrderId];
      if (!o) return;
      const clientDet   = clientDetails[o.clientName] || {};
      const clientEmail = clientDet.email || '';
      const contactName = clientDet.primary_contact || '';
      const statusMap   = { draft:'order_confirmed', confirmed:'order_confirmed', in_production:'order_in_production', complete:'order_complete' };
      const notifType   = statusMap[o.status] || 'order_confirmed';
      const labelMap    = { order_confirmed:'Order Confirmed', order_in_production:'Order In Production', order_complete:'Order Complete' };
      const label       = labelMap[notifType];
      const tot         = orderTotals(o);

      // Build full entries with rfqItems for detailed emails and
      // portal. saleUsdPerUnit = the workbook's Client Quote Total
      // Order ÷ total qty (variant qtys summed) — what the customer
      // is actually charged per unit. The server uses it to render
      // every variant as its own line at the SALE price (not the
      // RMB-cost-derived one). 0 when Sale Per hasn't been typed
      // yet, in which case the server falls back to priceRmb/rate.
      const entriesWithDetail = (o.entries || []).map(e => {
        const key    = `${e.clientName}|${e.workbookId}`;
        const detail = workbookDetail[key] || {};
        const rfqItems = (detail.rfqItems || []).filter(i => i.item || i.qty || i.priceRmb);
        const _vQty = it => {
          const vs = Array.isArray(it.variants) ? it.variants.filter(v => v && (v.variant || v.qty)) : [];
          if (vs.length) return vs.reduce((s, v) => s + (parseFloat(String(v.qty||'').replace(/,/g,'')) || 0), 0);
          return parseFloat(String(it.qty||'').replace(/,/g,'')) || 0;
        };
        const wbQty   = rfqItems.reduce((s, it) => s + _vQty(it), 0);
        const wbQuote = parseFloat(detail.pricingClientQuoteTotal) || 0;
        const saleUsdPerUnit = (wbQuote > 0 && wbQty > 0) ? (wbQuote / wbQty) : 0;
        return {
          clientName: e.clientName,
          workbookId: e.workbookId,
          product:    detail.product || `Workbook #${e.workbookId}`,
          saleUsdPerUnit,
          rfqItems
        };
      });

      const itemCount = entriesWithDetail.reduce((acc, e) => acc + e.rfqItems.length, 0);
      const summaryText =
        `Hi ${contactName || clientEmail || 'Client'},\n\nUpdate on ${o.name}` +
        (o.poNumber ? ` (PO: ${o.poNumber})` : '') +
        (itemCount > 0 ? ` · ${itemCount} line item${itemCount !== 1 ? 's' : ''}` : '') +
        (tot.totalUsd > 0 ? ` · $${tot.totalUsd.toLocaleString('en-US', {minimumFractionDigits:2})} USD` : '') + '.';

      const orderAppUrl = `${window.location.origin}/#/order/${_currentOrderId}`;

      _notifyPayload = {
        type: notifType, client_email: clientEmail, contact_name: contactName,
        client_name: o.clientName, rate: USD_TO_RMB,
        details: {
          order_name: o.name, po_number: o.poNumber || '',
          entries: entriesWithDetail,
          app_url: orderAppUrl
        }
      };

      _renderOrderStatusPreviewModal(_notifyPayload, label, summaryText);
    }

    document.getElementById('modal-notify').classList.add('open');
  }

  function closeNotifyModal() {
    document.getElementById('modal-notify').classList.remove('open');
    _notifyPayload = null;
    // Clear the body so re-opening doesn't flash the previous preview
    // before the new one renders in.
    const body = document.getElementById('notify-modal-body');
    if (body) body.innerHTML = '';
  }

  // ── Watchers (per-step subscription on a workbook) ─────────────────────
  // Detail-side persistence:
  //   detail.watchers = { quoteChina: ['Karen'], clientApproved: [...] }
  // The modal pulls candidate users from the users table (cached in
  // _watchersUserList) so adding a teammate to "Manage Users" makes
  // them immediately available to tag here without a code change.
  // _watchersUserList is invalidated whenever Manage Users persists a
  // change (handled by clearing the cache from the user-management
  // save path — see _watchersUserListInvalidate calls if added later).
  let _watchersUserList = null;

  async function _ensureWatcherUsersLoaded(force) {
    if (_watchersUserList && !force) return _watchersUserList;
    try {
      const r = await apiCall('get_users');
      _watchersUserList = (r && r.success && Array.isArray(r.data)) ? r.data : [];
    } catch (e) {
      _watchersUserList = [];
    }
    return _watchersUserList;
  }

  async function openWatchersModal() {
    if (!currentClient || !currentWorkbookId) return;
    await _ensureWatcherUsersLoaded();
    document.getElementById('modal-watchers').classList.add('open');
    renderWatchersModal();
    _refreshWatchersNotifPrompt();
  }

  function closeWatchersModal() {
    document.getElementById('modal-watchers').classList.remove('open');
  }

  // Show / hide the "Enable browser notifications" opt-in based on
  // current permission state. Default → show enable button; granted →
  // hide everything (it's already on); denied → show the "blocked" hint.
  function _refreshWatchersNotifPrompt() {
    const enable  = document.getElementById('watchers-notif-prompt');
    const blocked = document.getElementById('watchers-notif-blocked');
    if (!enable || !blocked) return;
    if (!_notifSupported()) {
      enable.style.display = 'none';
      blocked.style.display = 'none';
      return;
    }
    const p = _notifPermission();
    enable.style.display  = (p === 'default') ? '' : 'none';
    blocked.style.display = (p === 'denied')  ? '' : 'none';
  }

  // Triggered by the "Enable browser notifications" button inside the
  // Watchers modal. Permission requests must be tied to a user gesture
  // (click) so we never auto-prompt — the operator opts in here.
  async function watchersEnableBrowserNotif() {
    const result = await requestBrowserNotifPermission();
    _refreshWatchersNotifPrompt();
    if (result === 'granted') {
      // Fire a quick "you're set" notification so the user actually
      // sees one immediately and knows it's working.
      try {
        new Notification('Notifications enabled', {
          body: 'Milestone alerts will pop up in this browser.',
          icon: '/favicon.svg',
        });
      } catch (e) {}
      if (typeof _msToast === 'function') _msToast('Browser notifications enabled.', 'success');
    } else if (result === 'denied') {
      if (typeof _msToast === 'function') _msToast('Browser notifications were blocked.', 'error');
    }
  }

  function renderWatchersModal() {
    const key   = `${currentClient}|${currentWorkbookId}`;
    const detail = workbookDetail[key] || {};
    const items  = clientData[currentClient] || [];
    const item   = items.find(i => i.id === parseInt(currentWorkbookId)) || {};
    const flow   = item.flow || {};
    const watchers = detail.watchers || {};

    const usersWithEmail = (_watchersUserList || []).filter(u => u && u.display_name && u.email);
    const emptyUsersEl = document.getElementById('watchers-empty-users');
    if (emptyUsersEl) emptyUsersEl.style.display = usersWithEmail.length === 0 ? 'block' : 'none';

    const esc = s => String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;');

    const rows = flowSteps.map((stepKey, i) => {
      const stepLabel = flowLabels[i];
      const stepDone  = !!flow[stepKey];
      const watchList = Array.isArray(watchers[stepKey]) ? watchers[stepKey] : [];

      const pills = watchList.length === 0
        ? `<span class="watcher-row-empty">No watchers</span>`
        : watchList.map(name => `
            <span class="watcher-pill" title="Watching ${esc(stepLabel)}">
              <span>${esc(name)}</span>
              <button class="watcher-pill-x" onclick="removeWatcher('${esc(stepKey)}','${esc(name)}')" title="Remove">&times;</button>
            </span>
          `).join('');

      const availableUsers = usersWithEmail.filter(u => !watchList.includes(u.display_name));
      const addCtrl = stepDone
        ? `<span style="font-size:11px; color:var(--text-muted);">Step already completed</span>`
        : (availableUsers.length === 0
            ? ``
            : `<select class="watcher-row-add" onchange="addWatcher('${esc(stepKey)}', this.value); this.value=''">
                 <option value="">+ Add watcher</option>
                 ${availableUsers.map(u => `<option value="${esc(u.display_name)}">${esc(u.display_name)}</option>`).join('')}
               </select>`);

      return `
        <div class="watcher-row${stepDone ? ' is-done' : ''}">
          <div class="watcher-row-step">
            <span class="watcher-row-bar${stepDone ? ' filled' : ''}"></span>
            <span class="watcher-row-label">${esc(stepLabel)}</span>
            ${stepDone ? '<span class="watcher-row-done-badge">Completed</span>' : ''}
          </div>
          <div class="watcher-row-pills">${pills}</div>
          ${addCtrl}
        </div>
      `;
    }).join('');

    document.getElementById('watchers-table-body').innerHTML = rows;
    _updateWatchersCountBadge();
  }

  function addWatcher(stepKey, displayName) {
    if (!displayName || !currentClient || !currentWorkbookId) return;
    const key = `${currentClient}|${currentWorkbookId}`;
    const detail = workbookDetail[key] || (workbookDetail[key] = {});
    if (!detail.watchers) detail.watchers = {};
    if (!Array.isArray(detail.watchers[stepKey])) detail.watchers[stepKey] = [];
    if (!detail.watchers[stepKey].includes(displayName)) {
      detail.watchers[stepKey].push(displayName);
    }
    if (!_filling) autoSaveWorkbook();
    renderWatchersModal();
  }

  function removeWatcher(stepKey, displayName) {
    if (!currentClient || !currentWorkbookId) return;
    const key = `${currentClient}|${currentWorkbookId}`;
    const detail = workbookDetail[key];
    if (!detail || !detail.watchers || !Array.isArray(detail.watchers[stepKey])) return;
    detail.watchers[stepKey] = detail.watchers[stepKey].filter(n => n !== displayName);
    if (detail.watchers[stepKey].length === 0) delete detail.watchers[stepKey];
    if (!_filling) autoSaveWorkbook();
    renderWatchersModal();
  }

  // Status-bar Watchers button: shows the initials of the people tagged
  // on the NEXT step (the one the Advance button is about to mark
  // complete). Other steps' watchers stay hidden here — the modal is
  // where the full list lives. This keeps the button a glance-able
  // "who gets emailed if I click Advance now?" signal without cluttering
  // the bar. If no watchers on the next step, falls back to a generic
  // "Watchers" label.
  //
  // Compute single-letter initials of a display name. "Parker Low" → "PL",
  // "Karen" → "K". Capped at 2 chars per pill so the chip stays compact.
  function _watcherInitials(displayName) {
    if (!displayName) return '?';
    return String(displayName).trim().split(/\s+/).slice(0, 2).map(p => p.charAt(0).toUpperCase()).join('') || '?';
  }

  function _updateWatchersCountBadge() {
    if (!currentClient || !currentWorkbookId) return;
    const detail = workbookDetail[`${currentClient}|${currentWorkbookId}`] || {};
    const w = detail.watchers || {};
    const items = (clientData[currentClient] || []);
    const item  = items.find(i => i.id === parseInt(currentWorkbookId)) || {};
    const flow  = item.flow || {};
    // Determine the upcoming step (the one Advance will fire next). If
    // the workbook is complete (no upcoming step), there's nothing left
    // to notify on, so we fall back to the generic label.
    let currentIdx = -1;
    for (let i = flowSteps.length - 1; i >= 0; i--) {
      if (flow[flowSteps[i]]) { currentIdx = i; break; }
    }
    const nextIdx = currentIdx + 1;
    const nextStepKey = (nextIdx < flowSteps.length) ? flowSteps[nextIdx] : null;
    const nextStepLabel = nextStepKey ? flowLabels[nextIdx] : null;

    const nextWatchers = (nextStepKey && Array.isArray(w[nextStepKey])) ? w[nextStepKey] : [];
    const totalWatchers = Object.values(w).reduce((s, arr) => s + (Array.isArray(arr) ? arr.length : 0), 0);

    const badge = document.getElementById('watchers-count');
    const btn   = document.getElementById('btn-watchers');
    if (!badge || !btn) return;

    if (nextWatchers.length > 0) {
      // Render each watcher as a tiny initials pill stack inside the
      // badge slot. Tooltip on the button explains which step these
      // are watching so the abbreviation isn't ambiguous.
      badge.innerHTML = nextWatchers.map(name =>
        `<span class="wb-watcher-initials" title="${String(name).replace(/"/g,'&quot;')}">${_watcherInitials(name)}</span>`
      ).join('');
      btn.title = `${nextWatchers.length} watcher${nextWatchers.length === 1 ? '' : 's'} for "${nextStepLabel}"${totalWatchers > nextWatchers.length ? ` · ${totalWatchers - nextWatchers.length} more on later steps` : ''}`;
    } else {
      badge.textContent = '';
      btn.title = nextStepLabel
        ? `No watchers tagged for "${nextStepLabel}". Click to manage.`
        : 'Manage milestone watchers';
    }
    btn.classList.toggle('has-watchers', nextWatchers.length > 0);
    btn.classList.toggle('no-watchers',  nextWatchers.length === 0);
  }

  // Fires the "now at this stage" notification (email + browser) to
  // anyone watching the step that JUST became active, then clears the
  // watch list for that step (one-shot semantics — operator must re-tag
  // to be notified again). Called from advanceStatus() right after the
  // flow flag has flipped true — i.e., the moment the workbook MOVES
  // INTO that stage, not when it leaves.
  async function _fireWatcherNotifications(stepKey) {
    if (!stepKey || !currentClient || !currentWorkbookId) return;
    const key = `${currentClient}|${currentWorkbookId}`;
    const detail = workbookDetail[key] || {};
    const list = (detail.watchers && Array.isArray(detail.watchers[stepKey])) ? detail.watchers[stepKey].slice() : [];
    if (list.length === 0) return;

    const stepIdx = flowSteps.indexOf(stepKey);
    const stepLabel = flowLabels[stepIdx] || stepKey;
    const product = (detail.product || document.getElementById('product-name')?.value || 'Workbook').trim();
    const wbDbId = dbWorkbookMap[key] || currentWorkbookId;
    const appUrl = `${location.origin}${location.pathname}#/client/${encodeURIComponent(currentClient)}/workbook/${wbDbId}`;

    try {
      const r = await apiCall('notify_watchers', {
        workbook_id: wbDbId,
        step_key:    stepKey,
        step_label:  stepLabel,
        product_name: product,
        client_name:  currentClient,
        app_url:      appUrl,
        watchers:     list,
      });
      // Clear the watchers for this step regardless of email outcome —
      // re-firing on the next advance would re-spam, and the operator
      // can always re-tag if delivery failed.
      if (detail.watchers) {
        delete detail.watchers[stepKey];
        if (Object.keys(detail.watchers).length === 0) delete detail.watchers;
      }
      if (!_filling) autoSaveWorkbook();
      _updateWatchersCountBadge();
      if (typeof _msToast === 'function') {
        const ok = !!(r && r.success);
        const sentTo = (r && r.recipients) || [];
        const msg = ok
          ? `Notified ${sentTo.length || list.length} watcher${(sentTo.length || list.length) === 1 ? '' : 's'} that the workbook just moved into ${stepLabel}.`
          : `Watchers cleared but email may not have sent. Check console.`;
        _msToast(msg, ok ? 'success' : 'error');
      }
    } catch (e) {
      console.error('[MS notify_watchers]', e);
    }
  }

  async function sendNotification() {
    if (!_notifyPayload) return;
    const btn = document.getElementById('btn-notify-send');
    btn.disabled = true;
    btn.textContent = 'Sending…';
    try {
      const res = await apiCall('send_notification', _notifyPayload);
      if (res.success) {
        // Store portal token so we can poll for change requests later
        if (res.portal_token && _notifyPayload?.type === 'order_confirmed' && _currentOrderId) {
          orderData[_currentOrderId].portalToken = res.portal_token;
          orderData[_currentOrderId].changeRequested = false;
          saveOrders();
        }
        closeNotifyModal();
        const s = document.getElementById('save-status');
        if (s) { s.textContent = '✓ Notification sent'; s.style.color = 'var(--success)'; s.style.opacity = '1'; setTimeout(() => { s.style.opacity = '0'; s.textContent = ''; }, 4000); }
      } else {
        const err = res.results?.internal?.error || res.results?.client?.error || 'Unknown error';
        alert(`Failed to send: ${err}\n\nCheck that the Gmail App Password is correct.`);
      }
    } catch(e) {
      alert('Send failed: ' + e.message);
    }
    btn.disabled = false;
    btn.innerHTML = '<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="22" y1="2" x2="11" y2="13"/><polygon points="22 2 15 22 11 13 2 9 22 2"/></svg> Send Notification';
  }

  function _showPortalUrl(url) {
    // Show a modal with the portal link so it can be copied/shared
    const existing = document.getElementById('portal-url-modal');
    if (existing) existing.remove();
    const m = document.createElement('div');
    m.id = 'portal-url-modal';
    m.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.55);z-index:1200;display:flex;align-items:center;justify-content:center;padding:20px;';
    m.innerHTML = `
      <div style="background:var(--surface);border:1px solid var(--border);border-radius:14px;padding:32px;max-width:520px;width:100%;box-shadow:0 20px 60px rgba(0,0,0,0.5);">
        <div style="display:flex;align-items:center;gap:10px;margin-bottom:6px;">
          <div style="width:32px;height:32px;border-radius:50%;background:rgba(39,174,96,0.15);display:flex;align-items:center;justify-content:center;flex-shrink:0;">
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#27ae60" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M20 6L9 17l-5-5"/></svg>
          </div>
          <div style="font-size:16px;font-weight:800;color:var(--text);">Notification Sent</div>
        </div>
        <p style="font-size:13px;color:var(--text-muted);margin:0 0 20px;line-height:1.6;">The client email has been sent. A unique approval portal link has been created — share it with your client or use it as a reference.</p>
        <div style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.06em;color:var(--text-muted);margin-bottom:6px;">Client Portal Link</div>
        <div style="display:flex;gap:8px;align-items:stretch;">
          <input id="portal-url-input" type="text" value="${url}" readonly
            style="flex:1;background:var(--surface2);border:1px solid var(--border);border-radius:8px;padding:10px 12px;font-size:12px;font-family:ui-monospace,monospace;color:var(--text);outline:none;min-width:0;" />
          <button onclick="(function(){const el=document.getElementById('portal-url-input');el.select();document.execCommand('copy');const b=document.getElementById('copy-portal-btn');b.textContent='Copied!';b.style.background='var(--success)';setTimeout(()=>{b.textContent='Copy';b.style.background='var(--accent)';},2000);})()"
            id="copy-portal-btn"
            style="background:var(--accent);color:#fff;border:none;border-radius:8px;font-size:13px;font-weight:700;padding:0 16px;cursor:pointer;font-family:inherit;white-space:nowrap;flex-shrink:0;">
            Copy
          </button>
        </div>
        <div style="display:flex;justify-content:flex-end;margin-top:20px;">
          <button onclick="document.getElementById('portal-url-modal').remove()"
            style="background:none;border:1px solid var(--border);border-radius:8px;color:var(--text-muted);font-size:13px;font-weight:600;padding:8px 18px;cursor:pointer;font-family:inherit;">
            Done
          </button>
        </div>
      </div>`;
    document.body.appendChild(m);
    m.addEventListener('click', e => { if (e.target === m) m.remove(); });
    // Auto-select the URL
    setTimeout(() => { const el = document.getElementById('portal-url-input'); if (el) el.select(); }, 50);
  }

  function lockWorkbookTab(locked) {
    _wbLocked = locked;
    const tab = document.getElementById('wb-tab-workbook');
    if (!tab) return;
    const fields = tab.querySelectorAll('input:not([type="hidden"]), textarea, select');
    fields.forEach(el => {
      el.disabled = locked;
      el.style.opacity = locked ? '0.6' : '';
      el.style.cursor = locked ? 'not-allowed' : '';
    });
    // Also disable RFQ table add/remove buttons and image upload
    tab.querySelectorAll('button:not(.wb-tab)').forEach(btn => {
      btn.disabled = locked;
      btn.style.opacity = locked ? '0.6' : '';
      btn.style.cursor = locked ? 'default' : '';
    });
    // Show/hide lock banner
    let banner = document.getElementById('wb-lock-banner');
    if (locked) {
      if (!banner) {
        banner = document.createElement('div');
        banner.id = 'wb-lock-banner';
        banner.style.cssText = 'background:rgba(251,113,133,0.1); border:1px solid rgba(251,113,133,0.3); color:var(--text-muted); font-size:12px; padding:6px 14px; border-radius:6px; margin-bottom:12px; text-align:center;';
        banner.textContent = '🔒 Fields are locked after Quote to Client. Use ← to go back and unlock.';
        tab.insertBefore(banner, tab.firstChild);
      }
    } else {
      if (banner) banner.remove();
    }
  }

  function revertStatus() {
    const items = clientData[currentClient];
    if (!items) return;
    const item = items.find(i => i.id === parseInt(currentWorkbookId));
    if (!item) return;

    for (let i = flowSteps.length - 1; i >= 0; i--) {
      if (item.flow[flowSteps[i]]) {
        item.flow[flowSteps[i]] = false;
        break;
      }
    }

    // Back-stepping the status also clears the one-shot flags that
    // gate Sent to RFQ + Send for Review. Without this the buttons
    // would stay locked in their 'Sent ✓' state forever, even after
    // the operator backed out and wanted to re-send. Per UX direction:
    // 'go back in the status flow and make sure the buttons are
    // deactivated again' — so deactivate them here.
    const key = `${currentClient}|${currentWorkbookId}`;
    const dbId = dbWorkbookMap[key] || currentWorkbookId;
    const detail = workbookDetail[key];
    let detailChanged = false;
    if (detail) {
      if (detail.sentToRfq || detail.sentToRfqAt) {
        detail.sentToRfq   = false;
        detail.sentToRfqAt = null;
        detailChanged = true;
      }
      if (detail.sentForReview || detail.sentForReviewAt) {
        detail.sentForReview   = false;
        detail.sentForReviewAt = null;
        detailChanged = true;
      }
      if (detailChanged) {
        try { apiCall('save_workbook_detail', { id: dbId, detail, changed_by: getCurrentUser() }); }
        catch (e) { console.error('[revertStatus] save_workbook_detail failed', e); }
      }
    }

    renderStatusBar(item.flow);
    apiCall('update_flow', { id: dbId, flow_step: flowToStep(item.flow) });
    saveToLocalStorage();
    rebuildRfqNav();      // status moved — may enter/leave RFQ queue
    rebuildReviewNav();   // …same for the Ready-for-Review queue
    // Refresh the Watchers button — the upcoming step has changed, so
    // the displayed initials should track the new "next" step.
    if (typeof _updateWatchersCountBadge === 'function') _updateWatchersCountBadge();
  }

  function advanceStatus() {
    const items = clientData[currentClient];
    if (!items) return;
    const item = items.find(i => i.id === parseInt(currentWorkbookId));
    if (!item) return;

    // Track which step just flipped true so we can fire watcher emails
    // for that step *after* the flag has been written. (Watchers are
    // one-shot: drained when fired so they don't re-trigger if the
    // operator goes back and forward again.)
    let advancedStepKey = null;
    for (let i = 0; i < flowSteps.length; i++) {
      if (!item.flow[flowSteps[i]]) {
        item.flow[flowSteps[i]] = true;
        advancedStepKey = flowSteps[i];
        break;
      }
    }

    renderStatusBar(item.flow);
    // Save flow to DB
    const dbId = dbWorkbookMap[`${currentClient}|${currentWorkbookId}`] || currentWorkbookId;
    apiCall('update_flow', { id: dbId, flow_step: flowToStep(item.flow) });
    saveToLocalStorage();
    rebuildRfqNav();      // status moved — may enter/leave RFQ queue
    rebuildReviewNav();   // …same for the Ready-for-Review queue

    // Fire-and-forget watcher notification for the step that just
    // completed. Failures are logged but never block the advance.
    if (advancedStepKey) {
      try { _fireWatcherNotifications(advancedStepKey); } catch (e) { console.error('[MS watcher fire]', e); }
    }
    // Refresh the Watchers button — the upcoming step has changed, so
    // the displayed initials should track the new "next" step.
    if (typeof _updateWatchersCountBadge === 'function') _updateWatchersCountBadge();
  }

  /* ── Workbook Tabs ────────────────────────────────────────────────────────── */
  function switchWbTab(tabName, btn) {
    document.querySelectorAll('.wb-tab-content').forEach(el => el.classList.remove('active'));
    document.querySelectorAll('.wb-tab').forEach(el => el.classList.remove('active'));
    document.getElementById('wb-tab-' + tabName).classList.add('active');
    btn.classList.add('active');
    if (tabName === 'shipping') { syncShippingDims(); syncShippingPalletStats(); calcFreight(); }
    if (tabName === 'pricing')  { renderPricingTab(); }
  }

  /* ── Shipping Calculator ─────────────────────────────────────────────────── */
  // Per-mode ¥/kg rates. `freightMethodRates` is the LIVE object
  // mutated in place when the operator edits the rate inputs on the
  // Shipping tab — every freight / pricing reader (calcFreight,
  // renderPricingTab, the Client Quote, Hypothetical Scenarios)
  // reads from this object so a single edit ripples everywhere.
  // _FREIGHT_DEFAULT_RATES is the seed for new workbooks AND the
  // restore target when an empty input is left behind.
  const _FREIGHT_DEFAULT_RATES = { slow: 12, fast: 14, airupp: 44, directair: 65 };
  const freightMethodRates     = { ..._FREIGHT_DEFAULT_RATES };

  // Apply a per-workbook saved overrides object onto the live rates
  // and (optionally) re-paint the rate inputs to match. Empty/zero
  // values revert to defaults so a saved {fast: 0} doesn't zero out
  // the freight on load.
  function _applyFreightRates(overrides, paintInputs) {
    Object.assign(freightMethodRates, _FREIGHT_DEFAULT_RATES);
    if (overrides && typeof overrides === 'object') {
      Object.keys(_FREIGHT_DEFAULT_RATES).forEach(k => {
        const v = parseFloat(overrides[k]);
        if (!isNaN(v) && v > 0) freightMethodRates[k] = v;
      });
    }
    if (paintInputs !== false) {
      Object.keys(_FREIGHT_DEFAULT_RATES).forEach(k => {
        const el = document.getElementById('freight-rate-input-' + k);
        if (el && el !== document.activeElement) el.value = freightMethodRates[k].toFixed(2);
      });
    }
  }

  // Edit handler: parses the input, writes back to the live rate
  // object, then re-runs the freight panel + pricing tab so every
  // dependent display (the ¥/$ rate chip beside the dropdown, the
  // per-mode comparison cells, the Pricing tab's Total Shipping,
  // the Client Quote header) updates in lockstep. Autosaves.
  function onFreightRateInput(mode) {
    if (!_FREIGHT_DEFAULT_RATES.hasOwnProperty(mode)) return;
    const el = document.getElementById('freight-rate-input-' + mode);
    if (!el) return;
    const raw = (el.value || '').trim();
    const v = parseFloat(raw);
    freightMethodRates[mode] = (raw === '' || isNaN(v) || v <= 0)
      ? _FREIGHT_DEFAULT_RATES[mode]
      : v;
    if (typeof updateFreightRate === 'function') updateFreightRate();
    if (typeof calcFreight       === 'function') calcFreight();
    if (typeof renderPricingTab  === 'function') renderPricingTab();
    if (typeof autoSaveWorkbook  === 'function' && !_filling) autoSaveWorkbook();
  }
  const freightMethodDivisors = { slow: 6000, fast: 6000, airupp: 5000, directair: 5000 };

  // The shipping side used to ship through a hardcoded
  // USD_TO_RMB = 7.2. That made $16,500 override render as
  // ¥118,800 even though today's live rate is ~6.806. All freight
  // conversions now read USD_TO_RMB directly so the shipping tab
  // matches the header CNY↔USD calc.

  function updateFreightRate() {
    const rawMode = document.getElementById('freight-mode').value;
    const mode = freightMethodRates[rawMode] ? rawMode : 'slow';
    const r = freightMethodRates[mode];
    const rmbEl = document.getElementById('freight-rate-rmb-display');
    const usdEl = document.getElementById('freight-rate-usd-display');
    if (rmbEl) rmbEl.textContent = r.toFixed(2);
    if (usdEl) usdEl.textContent = (r / USD_TO_RMB).toFixed(2);
    renderPricingTab();
  }

  function toggleFreightShipping() {
    const header = document.getElementById('freight-shipping-header');
    const body   = document.getElementById('freight-shipping-body');
    header.classList.toggle('collapsed');
    body.classList.toggle('collapsed');
  }

  /* ── Pricing Tab Summary Renderer ──────────────────────────────────────── */
  // Outer try/catch wrapper — if anything in the pricing render throws
  // (e.g. a refactor introduces a TDZ from referencing a const before
  // its declaration site), we LOG to the console instead of letting
  // the error bubble all the way up to _fillWorkbookInner and break
  // workbook loading entirely. The pricing tab might end up in a
  // half-rendered state, but the rest of the workbook stays usable.
  function renderPricingTab() {
    try { _renderPricingTabInner(); }
    catch (e) { try { console.error('[MS renderPricingTab]', e); } catch (_) {} }
  }
  function _renderPricingTabInner() {
    // RFQ input handlers + workbook-load already keep _lastRfqPriceSummary
    // fresh, so we only run the (expensive) recalc here as a defensive
    // first-time prime. Skipping the redundant call cuts the per-keystroke
    // cost on Margin / Sale Per / Ship Lead inputs roughly in half.
    if (!_lastRfqPriceSummary) recalcRfqTotals();

    // Rebuild the synthetic shipment-upgrade fee cache BEFORE we read the
    // applied-fee totals/list below — otherwise the Client Quote line
    // items + Total Landed Cost would lag one render behind whenever an
    // upgrade fee is ticked. The premium depends only on each split's
    // qty + method (not the tier total), so it can be computed here from
    // globals without the shipping-section locals.
    _shipUpgradeFeeCache = _computeShipUpgradeFeeCache();

    // Refresh the Apply Additional Fees picker every render so values /
    // descriptions stay in sync with the Workbook tab inputs.
    renderPricingFeesCard();
    const _appliedFeesArr   = appliedFeesList();
    const _appliedFeesTotal = appliedFeesTotalUsd();

    // ── Pricing context computed upfront ───────────────────────────────
    // Both the Client Quote table and the Total Landed Cost block below
    // need shipPerUnit + wbMarginMul + shipLeadMax. Hoisting them here
    // lets the table render even when no tier is selected (values fall
    // back to 0 / defaults gracefully).
    // Map the pitch sentinel ("pitch-half" / "pitch-full") back to
    // tier 1 for the underlying per-unit price lookup. The qty
    // override flows through effectiveQty below.
    const _ctxTierIdLookup = (typeof _msTierIdForLookup === 'function') ? _msTierIdForLookup(_selectedTierId) : _selectedTierId;
    const _ctxTierRow   = _ctxTierIdLookup ? document.getElementById(`wb-tier-${_ctxTierIdLookup}`) : null;
    const _ctxTierQty   = parseInt(_ctxTierRow?.querySelectorAll('input')[0]?.value) || 0;
    const _ctxFreightMode = document.getElementById('freight-mode')?.value || 'slow';
    const _ctxRateRmb     = freightMethodRates[_ctxFreightMode] || 0;
    const _ctxWeightText  = document.getElementById('freight-wt-' + _ctxFreightMode)?.textContent || '—';
    const _ctxChargeKg    = parseFloat(_ctxWeightText) || 0;
    const _ctxShippingUsd = (_ctxChargeKg > 0 && _ctxRateRmb > 0)
      ? (_ctxChargeKg * _ctxRateRmb) / USD_TO_RMB
      : 0;
    const _ctxShipPerUnit = (_ctxTierQty > 0 && _ctxShippingUsd > 0) ? _ctxShippingUsd / _ctxTierQty : 0;

    const _ctxClientD = (typeof currentClient === 'string' && clientDetails[currentClient]) || {};
    const _ctxCmRaw   = _ctxClientD.default_margin_pct;
    const _ctxClientMarginPct = (_ctxCmRaw === '' || _ctxCmRaw === null || _ctxCmRaw === undefined || isNaN(parseFloat(_ctxCmRaw))) ? 50 : parseFloat(_ctxCmRaw);
    const _ctxWbMarginRaw = (document.getElementById('ps-margin-pct')?.value || '').trim();
    const _ctxWbMarginPct = (_ctxWbMarginRaw !== '' && !isNaN(parseFloat(_ctxWbMarginRaw))) ? parseFloat(_ctxWbMarginRaw) : _ctxClientMarginPct;
    const _ctxWbMarginMul = 1 + (_ctxWbMarginPct / 100);

    // Shipping lead — pulled from the SELECTED freight mode's input only.
    // Inputs accept either a single value ("10") or a range ("7-10"); both
    // flow into the Client Quote header and per-row Shipping column.
    const _ctxShipLeadRaw = (document.getElementById('ship-lead-' + _ctxFreightMode)?.value || '').trim();
    const _ctxShipLeadRange = _parseLeadRange(_ctxShipLeadRaw);
    const _ctxShipLeadText  = _formatLeadRange(_ctxShipLeadRange);

    // ── Client Quote line items — collapsible by parent SKU ─────────────
    // Group rfq-body rows by parent. Each group renders as:
    //   • a clickable parent summary row (totals across its variants)
    //   • hidden variant rows revealed by toggleClientQuoteParent()
    // Add-Variant placeholder rows are skipped.
    const _fmt2 = v => v.toLocaleString('en-US', {minimumFractionDigits:2, maximumFractionDigits:2});
    // Full Container Pitch scaling — when applied, the workbook's
    // pallet-total-cartons holds the bumped qty. We scale every RFQ
    // line's qty by (pitchUnits / grandRfqQty) so the Client Quote
    // line items + summary bars match the rolled-up Delivered Cost
    // Summary. Self-contained so it doesn't depend on `effectiveQty`
    // (which is declared further down the function — referencing it
    // here would land in the const-TDZ and blow up workbook load).
    const _pitchOnCq          = !!window._fullContainerPitchSnap;
    const _pitchTotalUnitsCq  = _pitchOnCq ? (_msIntFromInput(document.getElementById('pallet-total-cartons'))) : 0;
    const _rfqGrandQty        = (typeof _lastRfqPriceSummary !== 'undefined' && _lastRfqPriceSummary && _lastRfqPriceSummary.grandQty) || 0;
    const _cqQtyScale = (_pitchOnCq && _pitchTotalUnitsCq > 0 && _rfqGrandQty > 0 && _pitchTotalUnitsCq !== _rfqGrandQty)
      ? (_pitchTotalUnitsCq / _rfqGrandQty) : 1;
    const _scaleQty = (q) => _cqQtyScale === 1 ? q : Math.round(q * _cqQtyScale);

    // Sale Per is the operator's "ultimate say" for what the client
    // sees. When typed, every Client Quote line item displays it as
    // the per-unit Sale Price and uses it for the row total. No range
    // collapse, no "Variable" pill — one number across the table that
    // exactly matches the Sale Price (USD) in the header summary bar
    // and the Sale Per input on the Landed Cost card. When Sale Per
    // is blank, fall back to the landed×margin per-row formula so
    // the table still has sensible values during the build-out phase.
    const _cqSalePerRaw = (document.getElementById('ps-sale-per')?.value || '').trim();
    const _cqSalePer    = _cqSalePerRaw === '' ? NaN : parseFloat(_cqSalePerRaw);
    const _cqHaveSalePer = !isNaN(_cqSalePer) && _cqSalePer > 0;
    const refEl = document.getElementById('pricing-quote-ref-body');
    if (refEl) {
      const allRows = document.querySelectorAll('#rfq-body tr');
      const groups = [];
      let curGroup = null;
      allRows.forEach(row => {
        if (row.hasAttribute('data-rfq-add-for')) return;
        if (row.hasAttribute('data-rfq-parent')) {
          if (curGroup) curGroup.variants.push(row);
        } else {
          // Stash parent inputs once so the filter below + the per-group
          // render loop don't both re-query the same DOM subtree.
          curGroup = {
            parent: row,
            parentInputs: row.querySelectorAll('input:not([type="checkbox"])'),
            variants: []
          };
          groups.push(curGroup);
        }
      });

      // Filter empty groups (parent row never filled in)
      const realGroups = groups.filter(g => {
        const inputs = g.parentInputs;
        const hasName = (inputs[1]?.value || '').trim();
        const hasQty  = (inputs[2]?.value || '').trim();
        const hasRmb  = (inputs[3]?.value || '').trim();
        return hasName || hasQty || hasRmb || g.variants.length > 0;
      });

      if (realGroups.length === 0 && _appliedFeesArr.length === 0) {
        refEl.innerHTML = '<span class="pricing-no-selection">Add items to Quote Details on the Workbook tab.</span>';
      } else {
        // Pre-pass: figure out if ANY RFQ row carries a qty. When the
        // workbook is fee-only (operator using it to quote tooling /
        // sample / design with no per-unit product), the Sale Price
        // column would just show "—" everywhere — we hide it via a
        // CSS class so the fee total reads cleanly as the only number.
        let hasAnyQty = false;
        realGroups.forEach(group => {
          const pInputs = group.parentInputs;
          if (group.variants.length === 0) {
            if (_scaleQty(_msIntFromInput(pInputs[2])) > 0) hasAnyQty = true;
          } else {
            group.variants.forEach(vr => {
              const vi = vr.querySelectorAll('input:not(.rfq-var-sku-input):not([type="checkbox"])');
              if (_scaleQty(_msIntFromInput(vi[1])) > 0) hasAnyQty = true;
            });
          }
        });
        const tableClass = hasAnyQty
          ? 'pricing-quote-ref-table'
          : 'pricing-quote-ref-table no-sale-col';
        let html = `<div style="overflow-x:auto;">
          <table class="${tableClass}">
            <thead><tr>
              <th></th>
              <th>Item</th>
              <th style="text-align:right;">Qty</th>
              <th style="text-align:right;">Sale Price (USD)</th>
              <th style="text-align:right;">Total (USD)</th>
            </tr></thead><tbody>`;

        let groupIdx = 0;
        realGroups.forEach(group => {
          groupIdx++;
          const pInputs = group.parentInputs;
          const parentId    = group.parent.id.replace('rfq-', '');
          const parentName  = (pInputs[1]?.value || '').trim() || `Item ${groupIdx}`;
          const parentLead  = parseInt(pInputs[4]?.value) || 0;

          if (group.variants.length === 0) {
            // Single-line item (no variants) — non-expandable row.
            const pRawQty = _msIntFromInput(pInputs[2]);
            const pQty   = _scaleQty(pRawQty);
            // When Sale Per is typed, mirror it directly so the line
            // matches the header. Otherwise fall back to the computed
            // landed×margin path.
            let pSale, pTotal;
            if (_cqHaveSalePer) {
              pSale  = _cqSalePer;
              pTotal = pQty > 0 ? _msCeil2(pQty * pSale) : 0;
            } else {
              const pRmb    = _msNumFromInput(pInputs[3]);
              const pUsd    = _fxUsdFromRmb(pRmb);
              const pLanded = pUsd + _ctxShipPerUnit;
              pSale  = pLanded * _ctxWbMarginMul;
              pTotal = _msCeil2(pQty * pSale);
            }
            const pitchBadge = (_cqQtyScale !== 1 && pQty > pRawQty)
              ? ` <span style="color:#10b981; font-weight:700; font-size:10px;">(+${(pQty - pRawQty).toLocaleString('en-US')})</span>`
              : '';

            html += `<tr class="cq-parent-row no-variants">
              <td style="color:var(--text-muted); width:24px;">${groupIdx}</td>
              <td style="font-weight:500;">${parentName}</td>
              <td style="text-align:right;">${pQty > 0 ? pQty.toLocaleString('en-US') + pitchBadge : '—'}</td>
              <td style="text-align:right;">${pSale > 0 ? '$' + _fmt2(pSale) : '—'}</td>
              <td style="text-align:right; font-weight:600; color:var(--accent);">${pTotal > 0 ? '$' + _fmt2(pTotal) : '—'}</td>
            </tr>`;
          } else {
            // Variant group — collapsible
            let totalQty = 0, totalSale = 0;
            let saleMin = Infinity, saleMax = -Infinity;
            let maxLead = parentLead;
            const variantNames = [];
            const variantData = [];

            group.variants.forEach(vr => {
              // Skip the SKU input — same shift-by-one fix applied at
              // three other sites earlier. Without this, vi[0] reads
              // the SKU (e.g. 'TN1L') instead of the variant name and
              // vi[1] reads the variant NAME as qty (parses to 0 for
              // 'X-Small', to 1 for '1XL', etc.), which produced the
              // bogus 'Tank (Nude) qty = 6' the operator just flagged.
              const vi = vr.querySelectorAll('input:not(.rfq-var-sku-input):not([type="checkbox"])');
              const vSkuInput = vr.querySelector('.rfq-var-sku-input');
              const vSku  = (vSkuInput && vSkuInput.value || '').trim();
              const vName = (vi[0]?.value || '').trim();
              const vQty  = _scaleQty(_msIntFromInput(vi[1]));
              const vLead = parseInt(_msStripCommasStr(vi[3]?.value)) || 0;
              // When Sale Per is typed, every variant uses it as the
              // per-unit price. Otherwise fall back to the per-row
              // landed×margin computation.
              let vSale;
              if (_cqHaveSalePer) {
                vSale = _cqSalePer;
              } else {
                const vRmb    = _msNumFromInput(vi[2]);
                const vUsd    = _fxUsdFromRmb(vRmb);
                const vLanded = vUsd + _ctxShipPerUnit;
                vSale         = vLanded * _ctxWbMarginMul;
              }
              const vTotal  = vQty > 0 && vSale > 0 ? _msCeil2(vQty * vSale) : 0;

              totalQty += vQty;
              totalSale += vTotal;
              if (vSale > 0) {
                if (vSale < saleMin) saleMin = vSale;
                if (vSale > saleMax) saleMax = vSale;
              }
              if (vLead > maxLead) maxLead = vLead;
              // Prefer the variant SKU (auto-suggested or manual) for the
              // inline list — falls back to the variant name only when no
              // SKU was set.
              const labelForList = vSku || vName;
              if (labelForList) variantNames.push(labelForList);
              variantData.push({ name: vName, sku: vSku, qty: vQty, sale: vSale, total: vTotal, lead: vLead });
            });

            // When Sale Per is typed, every variant shares the same
            // price so there's no range to display — force isRange
            // off regardless of any rounding-derived spread.
            const isRange = !_cqHaveSalePer && saleMin !== Infinity && (saleMax - saleMin > 0.005);
            // Sale Price column: when variants share one price, just
            // show that price. When they differ, show a min–max range
            // AND prefix it with a "Variable" pill so the operator can
            // tell at a glance that the breakdown matters.
            const variablePill = isRange
              ? `<span style="display:inline-block; vertical-align:middle; margin-right:6px; padding:2px 7px; background:rgba(232,117,26,0.14); color:#E8751A; border:1px solid rgba(232,117,26,0.45); border-radius:10px; font-size:9.5px; font-weight:800; letter-spacing:0.05em; text-transform:uppercase; line-height:1;">Variable</span>`
              : '';
            const saleText = saleMin === Infinity ? '—'
              : (isRange ? `${variablePill}$${_fmt2(saleMin)}–$${_fmt2(saleMax)}` : '$' + _fmt2(saleMin));

            // Parent row — clickable chevron toggles sub-variant rows
            // below. Index cell carries a small ▸/▾ chevron so the
            // operator can tell at a glance which rows are expandable.
            // Subtitle shows variant count when collapsed; the SKU
            // list is no longer inline (it lives in the sub-rows).
            const variantCountTxt = group.variants.length === 1
              ? '1 variant'
              : `${group.variants.length} variants`;
            const escCq = v => String(v == null ? '' : v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
            html += `<tr class="cq-parent-row" data-cq-parent="${parentId}" onclick="_cqToggleVariants('${parentId}')">
              <td style="color:var(--text-muted); width:32px;">
                <span class="cq-chevron" style="display:inline-block; margin-right:4px; color:var(--text-muted); font-size:10px; transition:transform 0.15s;">▸</span>${groupIdx}
              </td>
              <td>
                <span style="font-weight:700;">${parentName}</span>
                <span style="color:var(--text-muted); font-size:11px; margin-left:8px; font-weight:500;">· ${variantCountTxt}</span>
              </td>
              <td style="text-align:right;">${totalQty > 0 ? totalQty.toLocaleString('en-US') : '—'}</td>
              <td style="text-align:right;">${saleText}</td>
              <td style="text-align:right; font-weight:600; color:var(--accent);">${totalSale > 0 ? '$' + _fmt2(totalSale) : '—'}</td>
            </tr>`;

            // Variant sub-rows — hidden by default, revealed by clicking
            // the parent. Each row shows SKU (mono) + variant name + the
            // per-variant qty / sale / total. Indent on the Item cell
            // makes the hierarchy obvious without an extra column.
            variantData.forEach((v, vIdx) => {
              const isLast = vIdx === variantData.length - 1;
              const branch = isLast ? '└' : '├';
              const skuChip = v.sku
                ? `<span style="font-family:'SF Mono','Consolas',monospace; font-size:11px; color:#E8751A; background:rgba(232,117,26,0.08); border:1px solid rgba(232,117,26,0.25); border-radius:4px; padding:1px 6px; margin-right:8px; font-weight:600;">${escCq(v.sku)}</span>`
                : '';
              const nameTxt = v.name ? `<span style="color:var(--text);">${escCq(v.name)}</span>` : `<span style="color:var(--text-muted); font-style:italic;">(unnamed)</span>`;
              html += `<tr class="cq-variant-row hidden" data-cq-variant-of="${parentId}">
                <td></td>
                <td style="padding-left:32px;">
                  <span style="color:var(--text-muted); font-family:'SF Mono','Consolas',monospace; margin-right:8px;">${branch}</span>
                  ${skuChip}${nameTxt}
                </td>
                <td style="text-align:right; color:var(--text-muted);">${v.qty > 0 ? v.qty.toLocaleString('en-US') : '—'}</td>
                <td style="text-align:right; color:var(--text-muted);">${v.sale > 0 ? '$' + _fmt2(v.sale) : '—'}</td>
                <td style="text-align:right; color:var(--text-muted); font-weight:500;">${v.total > 0 ? '$' + _fmt2(v.total) : '—'}</td>
              </tr>`;
            });
          }
        });

        // Additional Fees section — ALWAYS present at the bottom of the
        // Client Quote table so the client sees an explicit "$0.00"
        // when no fees were charged (rather than wondering whether fees
        // were silently included). When fees ARE applied, each ticked
        // fee gets its own indented line item under the divider.
        html += `<tr class="cq-fees-divider-row"><td colspan="5" style="padding:6px 12px; font-size:10px; font-weight:700; text-transform:uppercase; letter-spacing:0.06em; color:#E8751A; background:rgba(232,117,26,0.06); border-top:2px solid rgba(232,117,26,0.25);">Additional Fees</td></tr>`;
        if (_appliedFeesArr.length === 0) {
          // No fees applied — emit a single zero-value row so the client
          // can see "$0.00" plainly.
          html += `<tr class="cq-fee-row cq-fee-zero-row" style="background:rgba(232,117,26,0.04);">
            <td style="color:var(--text-muted); width:24px; font-weight:700;">—</td>
            <td style="font-weight:500; color:var(--text-muted);">No additional fees</td>
            <td style="text-align:right; color:var(--text-muted);">—</td>
            <td style="text-align:right; color:var(--text-muted);">—</td>
            <td style="text-align:right; font-weight:600; color:var(--accent);">$0.00</td>
          </tr>`;
        } else {
          _appliedFeesArr.forEach(f => {
            const escFee = v => String(v == null ? '' : v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
            const desc = f.desc ? `<span style="color:var(--text-muted); font-weight:400;"> — ${escFee(f.desc)}</span>` : '';
            html += `<tr class="cq-fee-row" style="background:rgba(232,117,26,0.04);">
              <td style="color:#E8751A; width:24px; font-weight:700;">+</td>
              <td style="font-weight:500;">${escFee(f.label)}${desc}</td>
              <td style="text-align:right; color:var(--text-muted);">—</td>
              <td style="text-align:right; color:var(--text-muted);">—</td>
              <td style="text-align:right; font-weight:600; color:var(--accent);">${f.usd > 0 ? '$' + _fmt2(f.usd) : '—'}</td>
            </tr>`;
          });
        }

        html += '</tbody></table></div>';
        refEl.innerHTML = html;
      }
    }

    // Client Quote header summary is populated AFTER the Total Landed Cost
    // block below so we can use suggestedMin/Max + landedTotal (and the freight
    // lead-time inputs) as sources of truth.

    // Delivered Cost Summary
    const noSelEl  = document.getElementById('pricing-no-selection-msg');
    const summaryEl = document.getElementById('pricing-summary-view');
    if (!_selectedTierId) {
      if (noSelEl)  noSelEl.style.display  = '';
      if (summaryEl) summaryEl.style.display = 'none';
      return;
    }
    if (noSelEl)  noSelEl.style.display  = 'none';
    if (summaryEl) summaryEl.style.display = '';

    const e = id => document.getElementById(id);
    const fmtUsd = v => v > 0 ? '$' + v.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2}) : '—';
    const fmtRmb = v => v > 0 ? '¥' + v.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2}) : '—';

    // Tier data from Workbook tab — strip commas before parseInt so
    // "110,000" doesn't truncate to 110 and tank every downstream
    // Pricing tab figure. When the pitch sentinel is selected,
    // _msTierIdForLookup remaps it to tier 1 so the per-unit price
    // still resolves; qty is overridden via effectiveQty below.
    const _tierIdForLookup = (typeof _msTierIdForLookup === 'function') ? _msTierIdForLookup(_selectedTierId) : _selectedTierId;
    const tierRow    = document.getElementById(`wb-tier-${_tierIdForLookup}`);
    const tierInputs = tierRow?.querySelectorAll('input');
    const tierQty    = parseInt(_msStripCommasStr(tierInputs?.[0]?.value), 10) || 0;
    const tierRmb    = parseFloat(_msStripCommasStr(tierRow?.dataset.price)) || 0;
    const tierUsd    = tierRmb > 0 ? _fxUsdFromRmb(tierRmb) : 0;
    // Full Container Pitch override — when the operator has pressed
    // Apply Full Container Pitch on the workbook, the snapshot lives
    // on window and pallet-total-cartons holds the bumped qty. Push
    // that through the Delivered Cost Summary so Product Cost +
    // Shipping Per + Total Landed all reflect the higher qty quote
    // the client will see. Hitting Revert clears the snapshot, which
    // drops effectiveQty back to the tier qty automatically.
    const _pitchOn    = !!window._fullContainerPitchSnap;
    const _pitchQty   = _pitchOn ? (_msIntFromInput(document.getElementById('pallet-total-cartons'))) : 0;
    const effectiveQty = (_pitchOn && _pitchQty > tierQty) ? _pitchQty : tierQty;
    const _pitchDelta  = effectiveQty - tierQty;

    // Product Cost block represents COST, not SALE — it's the
    // workbook-internal view. Unit Price Per (RMB/USD) and Total
    // Product Cost mirror the Shipping tab's selected pricing tier
    // header exactly (variant range when RFQ prices are variable,
    // single-tier RMB otherwise). USD per-unit is ceil-rounded to
    // the cent (_fxUsdFromRmb), matching the Shipping tab tier USD
    // cell — both round UP so any margin nudge moves the displayed
    // price by at least a cent. Sale Per is a manual Client Quote
    // override and intentionally does NOT bleed into this block.
    const fmt2 = v => v.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
    // Per-unit prices on the Pricing tab show three decimal places
    // (the "thousandth") because ceiling to the cent on a per-unit
    // value can drift the displayed × qty math from the actual total
    // by hundreds of dollars on big orders. Raw value, rounds-
    // nearest, so per-unit × qty ≈ total within fractional cents.
    // Totals (Product, Shipping, Grand Total, Total USD, Profit)
    // stay at fmt2 because cents are settled money — no need for an
    // illusory third-decimal precision there.
    const fmt3 = v => v.toLocaleString('en-US',{minimumFractionDigits:3,maximumFractionDigits:3});
    const psSummary = _lastRfqPriceSummary;
    // tierUsdPlain kept as the raw (un-ceiled) per-unit USD for the
    // Grand Total Cost per-unit math below. Display paths use
    // _fxUsdFromRmb(tierRmb) so the operator sees the ceil-rounded
    // value, but raw is what feeds the Grand Total Cost computation.
    const tierUsdPlain = tierRmb > 0 ? (tierRmb / USD_TO_RMB) : 0;
    const tierUsdCeil  = tierRmb > 0 ? _fxUsdFromRmb(tierRmb) : 0;
    let productTotal;
    let unitRmbText = '—', unitUsdText = '—';

    if (psSummary && psSummary.hasVariants && psSummary.rmbMin > 0) {
      // Variant range — render at 3 decimals from raw RMB and convert
      // RMB→USD on the fly (raw division) so the per-unit displayed
      // value reflects the actual cost, not the ceil-to-cent version
      // that the totals back out from on big orders.
      const _vUsdMinRaw = psSummary.rmbMin / USD_TO_RMB;
      const _vUsdMaxRaw = psSummary.rmbMax / USD_TO_RMB;
      unitRmbText = psSummary.isRange ? '¥' + fmt3(psSummary.rmbMin) + '–¥' + fmt3(psSummary.rmbMax) : '¥' + fmt3(psSummary.rmbMin);
      unitUsdText = psSummary.isRange ? '$' + fmt3(_vUsdMinRaw) + '–$' + fmt3(_vUsdMaxRaw) : '$' + fmt3(_vUsdMinRaw);
    } else if (tierRmb > 0) {
      unitRmbText = '¥' + fmt3(tierRmb);
      unitUsdText = '$' + fmt3(tierUsdPlain);
    }

    // Product Cost totals — derived from the qty-weighted RMB
    // (psSummary.grandRmbWeighted) which is computed in RMB without
    // any USD round-trip or cent-ceil. Both USD and RMB totals stay in
    // sync with the per-unit displayed above (¥0.300 → $0.044, total
    // 75,000 units = ¥22,500 / $3,303.50, not the inflated $3,750
    // the old grandUsd-back-calc was producing).
    if (psSummary && psSummary.hasVariants && psSummary.grandRmbWeighted > 0 && effectiveQty > 0) {
      productTotal = effectiveQty * (psSummary.grandRmbWeighted / USD_TO_RMB);
    } else {
      // Single-tier total = qty × precise per-unit (no cent-ceil — same
      // precision the Unit Price (USD) row displays just above).
      productTotal = (effectiveQty > 0 && tierRmb > 0) ? effectiveQty * tierUsdPlain : 0;
    }

    // Pitch badge on the Quantity row — surfaces the delta vs the
    // tier qty so the operator can see the override is active.
    const pitchSuffix = (_pitchOn && _pitchDelta > 0)
      ? ` <span style="color:#10b981; font-weight:700; font-size:11px;">(Full Container +${_pitchDelta.toLocaleString()})</span>`
      : '';
    if (e('ps-qty'))          e('ps-qty').innerHTML          = effectiveQty > 0 ? effectiveQty.toLocaleString('en-US') + ' units' + pitchSuffix : '—';
    if (e('ps-product-total')) e('ps-product-total').textContent = fmtUsd(productTotal);
    // Total Product Cost (RMB) = qty × precise per-unit RMB. Stays
    // entirely in RMB so a 75,000 × ¥0.30 entry shows the honest
    // ¥22,500, not ¥25,397 (which was qty × ceiled USD × FX rate).
    let productTotalRmb;
    if (psSummary && psSummary.hasVariants && psSummary.grandRmbWeighted > 0 && effectiveQty > 0) {
      productTotalRmb = effectiveQty * psSummary.grandRmbWeighted;
    } else {
      productTotalRmb = (effectiveQty > 0 && tierRmb > 0) ? effectiveQty * tierRmb : 0;
    }
    if (e('ps-product-total-rmb')) e('ps-product-total-rmb').textContent = productTotalRmb > 0 ? fmtRmb(productTotalRmb) : '—';
    if (e('ps-unit-rmb')) e('ps-unit-rmb').textContent = unitRmbText;
    if (e('ps-unit-usd')) e('ps-unit-usd').textContent = unitUsdText;

    // Shipping data from freight results
    const mode = document.getElementById('freight-mode')?.value || 'slow';
    const modeNames = { slow: 'Slow Boat', fast: 'Fast Boat', airupp: 'Air + UPS', directair: 'Direct Air' };
    const rateRmb = freightMethodRates[mode] || 0;
    const rateUsd = rateRmb / USD_TO_RMB;
    const weightText   = e('freight-wt-' + mode)?.textContent || '—';
    const chargeableKg = parseFloat(weightText) || 0;
    // Manual override: if the operator typed a fixed shipping cost on
    // the Shipping tab, that value supersedes the computed
    // chargeable-weight × rate math here.
    const _shipOverrideUsd = (typeof _getShippingCostOverrideUsd === 'function')
      ? _getShippingCostOverrideUsd() : null;

    // ── Base shipping = full quantity via the selected method ──────────
    // Shipping Cost ALWAYS quotes the whole tier on the dropdown method
    // (e.g. all 5,925 units on Fast Boat). Splits to a faster method are
    // NOT blended into this number — instead each becomes an optional
    // "Added Shipping Cost" upgrade fee (computed in _computeShipUpgrade-
    // FeeCache, surfaced with a checkbox in Additional Fees). This keeps
    // the headline shipping number stable and lets the operator decide
    // whether the air premium rides on top of the order.
    // NOTE: _fmt2 is already declared earlier in this function — reuse
    // it. Do NOT declare a second `const _fmt2` here (duplicate-const
    // SyntaxError would blank the whole bundle).
    let _methodRows = [];
    let shippingRmb = 0, shippingUsd = 0;

    if (_shipOverrideUsd !== null) {
      // Manual override wins — single row, fixed total.
      shippingRmb = _shipOverrideUsd * USD_TO_RMB;
      shippingUsd = _shipOverrideUsd;
      _methodRows.push({
        qty: effectiveQty,
        method: (modeNames[mode] || '—') + ' (override)',
        rateRmb: rateRmb,
        rmb: shippingRmb,
        usd: shippingUsd,
        chargeableKg: chargeableKg,
        missing: false,
        override: true,
      });
    } else {
      // Single base-method row for the whole tier. chargeableKg is the
      // comparison-table weight for the selected mode (full qty, since
      // calcFreight no longer subtracts splits).
      shippingRmb = chargeableKg > 0 ? chargeableKg * rateRmb : 0;
      shippingUsd = shippingRmb > 0 ? shippingRmb / USD_TO_RMB : 0;
      _methodRows.push({
        qty: effectiveQty,
        method: modeNames[mode] || '—',
        rateRmb: rateRmb,
        rmb: shippingRmb,
        usd: shippingUsd,
        chargeableKg: chargeableKg,
        missing: shippingUsd <= 0,
      });
    }

    const _totalChargeableKg = chargeableKg;

    // ── Shipment-upgrade premium → Additional Fees ─────────────────────
    // For every split that ships via a method DIFFERENT from the base
    // (the dropdown method), compute the EXTRA cost of that upgrade vs.
    // shipping the same qty on the base method:
    //   premium = cost(splitMethod, qty) − cost(baseMethod, qty)
    // e.g. 1,200 units Air + UPS vs. those same 1,200 on Fast Boat.
    // This is the "what does expediting cost me?" number. Shipping Cost
    // above ALWAYS stays at base (all units on the dropdown method); the
    // premium is purely ADDITIVE — tick the checkbox to add it on top of
    // the order (Total Landed Cost + Client Quote), leave it unchecked to
    // ignore the upgrade. The cache (_shipUpgradeFeeCache) was computed at
    // the top of this render, so the checkbox state + landed totals stay
    // in sync within the same render.
    (function renderShipmentUpgradePremium() {
      const host = e('pricing-shipping-upgrade-body');
      if (!host) return;
      const cache = _shipmentUpgradeFees();
      if (!cache.length) { host.style.display = 'none'; host.innerHTML = ''; return; }
      const f2 = v => (v || 0).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
      const baseLabelOf = bm => ({ slow:'Slow Boat', fast:'Fast Boat', airupp:'Air + UPS', directair:'Direct Air' }[bm] || bm);
      let anyApplied = false;
      const rows = cache.map(f => {
        const applied = _appliedFees.has(f.id);
        if (applied) anyApplied = true;
        const idAttr = String(f.id).replace(/'/g, "\\'");
        return `<label style="display:flex; align-items:flex-start; gap:12px; padding:8px 0; border-bottom:1px solid var(--border); cursor:pointer;">
          <input type="checkbox" ${applied ? 'checked' : ''} onchange="toggleFeeApplied('${idAttr}', this.checked)"
                 style="width:16px; height:16px; accent-color:#E8751A; cursor:pointer; flex-shrink:0; margin-top:1px;" />
          <div style="flex:1; min-width:0;">
            <div style="font-size:13px; font-weight:600; color:var(--text);">${f.label}</div>
            <div style="font-size:11px; color:var(--text-muted); margin-top:1px;">
              ${f.desc} &nbsp;·&nbsp; $${f2(f.baseUsd)} → $${f2(f.upUsd)}
            </div>
          </div>
          <div style="text-align:right; flex-shrink:0;">
            <div style="font-size:13px; font-weight:700; color:#E8751A;">+ $${f2(f.usd)}</div>
            <div style="font-size:11px; color:var(--text-muted);">+ ¥${f2(f.rmb)}</div>
          </div>
        </label>`;
      }).join('');
      const note = anyApplied
        ? `Added on top of the order as an Additional Fee. Total Shipping Cost above stays at base (${baseLabelOf(cache[0].baseMethod)} for all units) — this premium is the cost to expedite, billed separately.`
        : `Shipping Cost above is quoted at base (${baseLabelOf(cache[0].baseMethod)} for all units). Tick a box to add the upgrade premium on top of the order (Total Landed Cost + Client Quote).`;
      host.innerHTML = `<div style="padding:8px 14px 10px; border-bottom:1px solid var(--border); background:rgba(232,117,26,0.04);">
        <div style="font-size:10px; font-weight:700; text-transform:uppercase; letter-spacing:0.06em; color:var(--text-muted); margin-bottom:2px;">Shipment Upgrades</div>
        ${rows}
        <div style="font-size:10px; color:var(--text-muted); font-style:italic; margin-top:6px;">${note}</div>
      </div>`;
      host.style.display = '';
    })();

    const _methodBody = e('ps-sh-method-body');
    if (_methodBody) {
      _methodBody.innerHTML = _methodRows.map(r => {
        const qtyCell = r.qty > 0 ? r.qty.toLocaleString('en-US') : '—';
        const rateCell = r.rateRmb > 0 ? `¥${_fmt2(r.rateRmb)}` : '—';
        if (r.missing) {
          return `<tr style="border-top:1px solid var(--border);">
            <td style="padding:6px 8px; font-weight:600;">${qtyCell}</td>
            <td style="padding:6px 8px;">${r.method}</td>
            <td style="padding:6px 8px; text-align:right; font-family:'SF Mono','Consolas',monospace;">${rateCell}</td>
            <td colspan="2" style="padding:6px 8px; text-align:right; color:#dc2626; font-style:italic;">specs missing</td>
          </tr>`;
        }
        return `<tr style="border-top:1px solid var(--border);">
          <td style="padding:6px 8px; font-weight:600;">${qtyCell}</td>
          <td style="padding:6px 8px;">${r.method}</td>
          <td style="padding:6px 8px; text-align:right; font-family:'SF Mono','Consolas',monospace;">${rateCell}</td>
          <td style="padding:6px 8px; text-align:right; font-family:'SF Mono','Consolas',monospace;">¥${_fmt2(r.rmb)}</td>
          <td style="padding:6px 8px; text-align:right; font-family:'SF Mono','Consolas',monospace;">$${_fmt2(r.usd)}</td>
        </tr>`;
      }).join('') || `<tr><td colspan="5" style="padding:8px; text-align:center; color:var(--text-muted); font-style:italic;">—</td></tr>`;
    }

    if (e('ps-sh-weight')) {
      e('ps-sh-weight').textContent = _totalChargeableKg > 0
        ? _totalChargeableKg.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2}) + ' kg'
        : '—';
    }

    // ── Shipping Per (USD) — plain view-only row, value only ──────────
    // Just the per-unit price ($X.XXX / unit). The qty / ¥cost math hint
    // was dropped per UX feedback — the per-unit number stands on its
    // own next to the "Shipping Per (USD)" label.
    const _perList = e('ps-sh-per-list');
    if (_perList) {
      const _perRows = _methodRows.filter(r => !r.missing && r.qty > 0 && r.usd > 0);
      if (_perRows.length === 0) {
        _perList.textContent = '—';
      } else {
        _perList.innerHTML = _perRows.map(r => {
          const perUnit = r.usd / r.qty;
          return `$${fmt3(perUnit)} / unit`;
        }).join('<br/>');
      }
    }
    // shipPerUsd kept as a raw weighted-avg value for downstream
    // landed-cost math (Total Landed Cost block reads it). When splits
    // exist this is the blended per-unit; for single-mode it's just
    // total ÷ qty as before.
    const shipPerUsd = (effectiveQty > 0 && shippingUsd > 0) ? (shippingUsd / effectiveQty) : 0;

    if (e('ps-sh-total-rmb')) e('ps-sh-total-rmb').textContent = shippingRmb > 0 ? fmtRmb(shippingRmb) : '—';
    if (e('ps-sh-total'))     e('ps-sh-total').textContent     = shippingUsd > 0 ? fmtUsd(shippingUsd) : '—';

    // Grand Total Cost (USD) = Total Product Cost + Total Shipping. This
    // is OUR cost to land the order — internal view, no margin, no fees.
    // Additional Fees (below) are extras layered on top of this number;
    // Sale Per (Landed Cost card) is what we charge the client. Both are
    // intentionally separate from this base acquisition cost.
    // Sum is ceil-rounded to the cent so the bar's headline total
    // matches the ceil-rounded per-unit math below it.
    const grandTotalCostUsd = _msCeil2((productTotal || 0) + (shippingUsd || 0));
    if (e('ps-grand-total')) e('ps-grand-total').textContent = grandTotalCostUsd > 0 ? fmtUsd(grandTotalCostUsd) : '—';
    // Cache the Grand Total Cost (USD) bar value so the Add to Order
    // / Add to Shipment / Orders list cards can display "Cost (ours)"
    // as exactly what the operator sees on the Pricing tab here.
    // This is product cost + shipping cost only — no fees, no margin,
    // no Sale Per. Distinct from pricingLandedTotal (which adds fees
    // and is read by the Financial Summary / legacy paths).
    if (currentClient && currentWorkbookId) {
      const _wbKeyG = `${currentClient}|${currentWorkbookId}`;
      if (!workbookDetail[_wbKeyG]) workbookDetail[_wbKeyG] = {};
      workbookDetail[_wbKeyG].pricingGrandTotalCost = grandTotalCostUsd > 0 ? grandTotalCostUsd : 0;
      // Cache the shipping component on its own so the Orders page can
      // surface "Shipping" as a discrete column without re-running
      // calcFreight. Includes manual overrides (since shippingUsd above
      // already honors _shipOverrideUsd).
      workbookDetail[_wbKeyG].pricingShippingCostUsd = shippingUsd > 0 ? shippingUsd : 0;
      // Cache the product component separately so the Orders strip can
      // read product cost directly instead of subtracting one cache
      // from another (which drifts when the shipping cache is missing
      // and the fallback recomputes shipping at a different rate than
      // what was originally baked into pricingGrandTotalCost).
      workbookDetail[_wbKeyG].pricingProductCostUsd = (productTotal > 0) ? productTotal : 0;
    }

    // Per-unit breakdown line beneath the label — shows the math the
    // grand total derives from: product per-unit USD + shipping per-unit
    // USD = total per-unit USD. Uses the precise per-unit math (qty-
    // weighted RMB / FX rate) so the displayed components × qty tie
    // exactly to the Grand Total Cost above. Single-tier branch already
    // used tierUsdPlain (precise) — variants now also use the precise
    // grandRmbWeighted path so a ¥0.30 entry reads as $0.044, not the
    // ceiled $0.050 from grandUsd.
    let _gtPerProductRaw = 0;
    if (psSummary && psSummary.hasVariants && psSummary.grandRmbWeighted > 0 && USD_TO_RMB > 0) {
      _gtPerProductRaw = psSummary.grandRmbWeighted / USD_TO_RMB;
    } else if (tierUsdPlain > 0) {
      _gtPerProductRaw = tierUsdPlain;
    }
    // Display each component at three decimals (raw, rounds-nearest)
    // and the displayed total = sum of the displayed components — so
    // the math always ties exactly. shipPerUsd is raw upstream so
    // both summands and the sum stay consistent at the thousandth.
    const _gtPerShipRaw  = shipPerUsd || 0;
    const _gtPerTotalRaw = _gtPerProductRaw + _gtPerShipRaw;
    if (e('ps-grand-total-per')) {
      e('ps-grand-total-per').textContent = _gtPerTotalRaw > 0
        ? `$${fmt3(_gtPerProductRaw)} + $${fmt3(_gtPerShipRaw)} = $${fmt3(_gtPerTotalRaw)} per unit`
        : '—';
    }

    // ── Total Landed Cost card ──────────────────────────────────────────
    // qty   ← selected pricing tier (tierQty, already resolved above)
    // price ← per-unit RFQ data from Workbook tab (_lastRfqPriceSummary)
    // Shipping per unit = total shipping ÷ tier qty (avoids over/undercounting
    // when tier qty differs from grand qty).
    //
    // Margin % default chain: workbook override → client default → 50.
    // Sale Per is manually entered; entering a value back-solves margin so
    // Suggested + Sale stay in sync.

    // Per-unit USD (single value or [min,max]). Same precise path the
    // Product Cost block + Grand Total Cost use so Landed Per ties out
    // exactly to those displays (no cent-ceil inflation). For variants
    // we read rmbMin/Max + grandRmbWeighted from psSummary and divide
    // by the FX rate live; for single-tier we use tierUsdPlain (also
    // precise). Without this, a 75,000 × ¥0.30 entry showed Grand
    // Total Cost \$4,128 but Landed Cost \$4,556 — different per-unit
    // math in each block.
    let perUnitMin, perUnitMax, avgPerUnitUsd;
    if (psSummary && psSummary.hasVariants && psSummary.rmbMin > 0 && USD_TO_RMB > 0) {
      perUnitMin    = psSummary.rmbMin / USD_TO_RMB;
      perUnitMax    = psSummary.rmbMax / USD_TO_RMB;
      avgPerUnitUsd = (psSummary.grandRmbWeighted > 0) ? psSummary.grandRmbWeighted / USD_TO_RMB : perUnitMin;
    } else {
      perUnitMin = perUnitMax = avgPerUnitUsd = tierUsdPlain;
    }

    // Shipping per unit — the cost of moving one unit at the chosen freight mode
    const shipPerUnit = (tierQty > 0 && shippingUsd > 0) ? shippingUsd / tierQty : 0;

    // Landed Per (USD) — what one unit costs us all-in
    const landedMin = perUnitMin + shipPerUnit;
    const landedMax = perUnitMax + shipPerUnit;
    const landedAvg = avgPerUnitUsd + shipPerUnit;
    const landedIsRange = landedMax - landedMin > 0.005;

    // wbMarginPct drives the Suggested Price Per row — the operator
    // tweaks Margin and watches Suggested move in lockstep. clientMarginPct
    // (the client default) is read here only as the fallback when the
    // workbook hasn't set its own override yet.
    const clientD = (typeof currentClient === 'string' && clientDetails[currentClient]) || {};
    const cmRaw   = clientD.default_margin_pct;
    const clientMarginPct = (cmRaw === '' || cmRaw === null || cmRaw === undefined || isNaN(parseFloat(cmRaw))) ? 50 : parseFloat(cmRaw);

    const wbMarginRaw = (e('ps-margin-pct')?.value || '').trim();
    let wbMarginPct;
    if (wbMarginRaw !== '' && !isNaN(parseFloat(wbMarginRaw))) {
      wbMarginPct = parseFloat(wbMarginRaw);
    } else {
      wbMarginPct = clientMarginPct;
      // Reflect inherited value into the input so the user sees it.
      const mInput = e('ps-margin-pct');
      if (mInput && mInput !== document.activeElement) mInput.value = wbMarginPct;
    }
    const wbMarginMul = 1 + (wbMarginPct / 100);

    // Suggested Price Per (USD): Landed × (1 + workbookMargin). Reacts
    // to the Margin input — changing Margin re-renders Suggested in
    // place so the operator can dial in a target margin and see what
    // it implies for sale price. (Used to be locked to the client
    // default; flipped on 2026-05-05 so Margin actively drives the
    // Suggested row instead of silently overwriting Sale Per.)
    const suggestedMin = landedMin * wbMarginMul;
    const suggestedMax = landedMax * wbMarginMul;
    const suggestedIsRange = suggestedMax - suggestedMin > 0.005;

    // Sale Per is fully manual, fully independent — operator's "ultimate
    // say". Nothing here touches it: not Margin changes, not landed cost
    // moves, not the initial render. The only person who writes to
    // ps-sale-per is the operator typing in it. Total USD downstream
    // calculates strictly as salePer × tierQty + appliedFees.
    const saleInput  = e('ps-sale-per');
    const salePerRaw = (saleInput?.value || '').trim();
    const salePer    = salePerRaw === '' ? NaN : parseFloat(salePerRaw);

    // Margin drift detection — when the typed Sale Per implies a
    // margin that's meaningfully different from the configured
    // Margin %, surface a small warning beneath the input. The most
    // common cause is the RFQ price moved (or shipping changed) but
    // Sale Per wasn't re-typed. Thresholds: ≥ 2 pp drift = amber
    // "target X% vs actual Y%"; Sale Per ≤ landed = red "Below cost
    // by $Z" (a real money loss the operator needs to see).
    const driftEl     = e('ps-sale-drift');
    const driftRowEl  = e('ps-sale-drift-row');
    if (driftEl && driftRowEl) {
      if (!isNaN(salePer) && salePer > 0 && landedAvg > 0) {
        const impliedPct = ((salePer - landedAvg) / landedAvg) * 100;
        const driftPp    = impliedPct - wbMarginPct;
        if (salePer <= landedAvg) {
          driftRowEl.style.display = '';
          driftEl.style.color      = 'var(--danger, #dc2626)';
          driftEl.textContent      = `⚠ Below cost by $${(landedAvg - salePer).toLocaleString('en-US', {minimumFractionDigits:3, maximumFractionDigits:3})}/unit — you're losing money on every unit sold.`;
        } else if (Math.abs(driftPp) >= 2) {
          driftRowEl.style.display = '';
          driftEl.style.color      = '#d97706';
          const fmtPct = v => (Math.round(v * 10) / 10).toLocaleString('en-US', {minimumFractionDigits:1, maximumFractionDigits:1});
          driftEl.textContent      = `⚠ Margin drift — Sale Per implies ${fmtPct(impliedPct)}% margin vs target ${fmtPct(wbMarginPct)}% (off by ${driftPp > 0 ? '+' : ''}${fmtPct(driftPp)} pp). Re-type Sale Per to realign.`;
        } else {
          driftRowEl.style.display = 'none';
        }
      } else {
        driftRowEl.style.display = 'none';
      }
    }

    // Landed Total (deterministic): tier qty × weighted-avg landed,
    // plus any one-time Additional Fees the operator has applied above.
    const landedTotalBase = tierQty > 0 ? tierQty * landedAvg : 0;
    const landedTotal     = landedTotalBase + _appliedFeesTotal;

    // Cache on the workbook so Total Pipeline (Financial Summary) can read
    // it without re-running the freight calc. Only writes when we have a
    // current workbook context.
    if (currentClient && currentWorkbookId) {
      const _wbKey = `${currentClient}|${currentWorkbookId}`;
      if (!workbookDetail[_wbKey]) workbookDetail[_wbKey] = {};
      workbookDetail[_wbKey].pricingLandedTotal = landedTotal > 0 ? landedTotal : 0;
    }

    // Total USD: Sale Per × effective qty + applied fees. effectiveQty
    // rolls up to the Full Container Pitch when applied so the Client
    // Quote header + footer + line items all reflect the bumped qty.
    // Fee-only workbook support: if there's no product sale (no Sale
    // Per × qty), the total still populates from applied fees alone —
    // operator can use a workbook as 'tooling fee only' without
    // forcing an RFQ line item.
    const saleProductTotal = (!isNaN(salePer) && salePer > 0 && effectiveQty > 0) ? _msCeil2(salePer * effectiveQty) : NaN;
    let totalUsd;
    if (!isNaN(saleProductTotal)) {
      totalUsd = _msCeil2(saleProductTotal + _appliedFeesTotal);
    } else if (_appliedFeesTotal > 0) {
      totalUsd = _msCeil2(_appliedFeesTotal);
    } else {
      totalUsd = NaN;
    }

    // Cache the Client Quote Total (sale × qty + fees) so the Add to
    // Order picker can sum customer-facing totals across selected
    // workbooks without re-running the Pricing render per workbook.
    if (currentClient && currentWorkbookId) {
      const _wbKey2 = `${currentClient}|${currentWorkbookId}`;
      if (!workbookDetail[_wbKey2]) workbookDetail[_wbKey2] = {};
      workbookDetail[_wbKey2].pricingClientQuoteTotal = !isNaN(totalUsd) && totalUsd > 0 ? totalUsd : 0;
    }

    // Applied-fees "as-is" total — sum of each applied fee's SOURCE
    // amount (Workbook-tab value), ignoring any per-fee override the
    // operator typed on the Pricing tab. This is our actual cost of
    // those fees; the difference between override and as-is is markup
    // (= additional profit). Cached for the Order Sheet so per-line
    // profit reflects fee markup correctly.
    const _appliedFeesAsIsTotal = _appliedFeesArr.reduce((s, f) => {
      const asIs = parseFloat(f.originalUsd);
      return s + (isFinite(asIs) ? asIs : (parseFloat(f.usd) || 0));
    }, 0);
    if (currentClient && currentWorkbookId) {
      const _wbKeyFA = `${currentClient}|${currentWorkbookId}`;
      if (!workbookDetail[_wbKeyFA]) workbookDetail[_wbKeyFA] = {};
      workbookDetail[_wbKeyFA].pricingAppliedFeesAsIs = _appliedFeesAsIsTotal > 0 ? _appliedFeesAsIsTotal : 0;
    }

    // Order Profit = Sale Total − TRUE cost basis. The override fees
    // were added to BOTH sides (landedTotal includes _appliedFeesTotal
    // which uses overrides), so they cancel out — leaving only product
    // margin. To surface fee markup as profit, subtract the as-is
    // portion from landedTotal: cost basis becomes
    //     landedBase + fees AT AS-IS
    // and Sale − Cost = product margin + (override − as-is) per fee
    // = product margin + fee markup.
    // Total Landed Cost displayed on the card stays at landedTotal
    // (override amount) — that's "what gets billed", not the cost
    // basis. Profit reflects the markup separately, here.
    const _trueLandedCost = landedTotalBase + _appliedFeesAsIsTotal;
    const orderProfit     = !isNaN(totalUsd) ? totalUsd - _trueLandedCost : NaN;

    // ─── Render cells ────────────────────────────────────────────────
    // fmtRange formats per-unit prices at three decimals (raw value,
    // rounds-nearest) so the per-unit × qty math reconciles to the
    // settled total without the per-cent ceil drift that becomes
    // visible on big orders. Used by both Landed Per and Suggested
    // Price Per below.
    const fmtRange = (lo, hi, isRange) => isRange
      ? '$' + fmt3(lo) + '–$' + fmt3(hi)
      : '$' + fmt3(lo);

    if (e('ps-landed-per'))    e('ps-landed-per').textContent    = landedMin > 0 ? fmtRange(landedMin, landedMax, landedIsRange) : '—';

    // ── Per-variant landed breakdown ─────────────────────────────────
    // When variants on the RFQ carry distinct RMB prices, expose a
    // collapsible breakdown with one row per distinct-price group so
    // the operator can see exactly what the Landed Per range
    // represents. Hidden by default; the operator clicks the Landed
    // Per row to expand.
    const variantsBox = e('ps-landed-variants');
    const landedRow   = e('ps-landed-per-row');
    const landedChev  = e('ps-landed-chevron');
    if (variantsBox) {
      let variantHtml = '';
      if (psSummary && psSummary.hasVariants && psSummary.isRange) {
        // Walk the RFQ rows directly so we can group variants by their
        // exact RMB price. Use the parent's name + the variant name as
        // the row label; same-price variants under one parent merge.
        const PRICE_EPS = 0.005;
        const groups = new Map(); // key = rmb (rounded), val = { rmb, names: [], qty }
        const parents = document.querySelectorAll('#rfq-body tr:not([data-rfq-parent]):not([data-rfq-add-for])');
        parents.forEach(row => {
          const id     = parseInt(row.id.replace('rfq-', ''));
          const pIns   = row.querySelectorAll('input:not([type="checkbox"])');
          const pName  = (pIns[1]?.value || '').trim();
          const pRmb   = parseFloat(pIns[3]?.value) || 0;
          const pQty   = parseFloat(pIns[2]?.value) || 0;
          const vRows  = document.querySelectorAll(`[data-rfq-parent="${id}"]`);
          if (vRows.length === 0) {
            if (pRmb > 0 && pQty > 0) {
              const k = pRmb.toFixed(2);
              const g = groups.get(k) || { rmb: pRmb, names: [], qty: 0 };
              g.names.push(pName || `Item ${id}`);
              g.qty += pQty;
              groups.set(k, g);
            }
            return;
          }
          // Has variants — split by distinct prices.
          const samePriceQty = { qty: 0, names: [] };
          const diffPrice   = []; // { name, rmb, qty }
          vRows.forEach(vr => {
            // Skip the SKU input so name=0, qty=1, rmb=2 keep working
            // — the variant SKU is now the first input in the row.
            const vIns = vr.querySelectorAll('input:not(.rfq-var-sku-input)');
            const vName = (vIns[0]?.value || '').trim();
            const vQty  = parseFloat(vIns[1]?.value) || 0;
            const vRmb  = parseFloat(vIns[2]?.value) || 0;
            if (vRmb <= 0 || vQty <= 0) return;
            if (Math.abs(vRmb - pRmb) < PRICE_EPS) {
              samePriceQty.qty += vQty;
              samePriceQty.names.push(vName || 'Variant');
            } else {
              diffPrice.push({ name: vName || 'Variant', rmb: vRmb, qty: vQty });
            }
          });
          if (samePriceQty.qty > 0 && pRmb > 0) {
            const k = pRmb.toFixed(2);
            const g = groups.get(k) || { rmb: pRmb, names: [], qty: 0 };
            const lbl = pName ? pName : (samePriceQty.names[0] || 'Variant');
            g.names.push(lbl);
            g.qty += samePriceQty.qty;
            groups.set(k, g);
          }
          diffPrice.forEach(d => {
            const k = d.rmb.toFixed(2);
            const g = groups.get(k) || { rmb: d.rmb, names: [], qty: 0 };
            const lbl = pName ? `${pName} — ${d.name}` : d.name;
            g.names.push(lbl);
            g.qty += d.qty;
            groups.set(k, g);
          });
        });

        // Sort groups by price ascending so the cheapest lands at the
        // top — easier to reconcile with the Landed Per "min–max" range.
        const sorted = [...groups.values()].sort((a, b) => a.rmb - b.rmb);
        if (sorted.length > 1) {
          variantHtml = sorted.map(g => {
            const usdPerUnit  = g.rmb / USD_TO_RMB;
            const landedUnit  = usdPerUnit + shipPerUnit;
            const namesText   = g.names.length === 1 ? g.names[0]
                              : g.names.length <= 3 ? g.names.join(', ')
                              : g.names.slice(0, 2).join(', ') + ` +${g.names.length - 2} more`;
            const qtyText     = g.qty.toLocaleString('en-US');
            return `<div class="pricing-landed-row" style="padding-left:16px; border-left:2px solid rgba(232,117,26,0.35); margin-left:4px;">
              <div class="landed-per-stack">
                <span class="label" style="font-size:12px;">${namesText}</span>
                <span class="landed-per-math">${qtyText} units · ¥${fmt2(g.rmb)}/unit</span>
              </div>
              <span class="value" style="font-size:13px;">$${fmt2(landedUnit)}</span>
            </div>`;
          }).join('');
        }
      }
      variantsBox.innerHTML = variantHtml;
      const hasVariants = !!variantHtml;
      variantsBox.dataset.hasVariants = hasVariants ? '1' : '0';
      // Show a chevron + cursor:pointer on the Landed Per row only when
      // we actually have variants to expand.
      if (landedChev) landedChev.style.display = hasVariants ? 'inline-block' : 'none';
      if (landedRow) {
        landedRow.style.cursor = hasVariants ? 'pointer' : '';
        landedRow.title = hasVariants ? 'Click to see each variant\'s landed cost' : '';
      }
      // Visibility honors the user's last toggle. If there are no
      // variants, force collapsed.
      const expanded = hasVariants && _psLandedExpanded;
      variantsBox.style.display = expanded ? '' : 'none';
      if (landedChev) landedChev.style.transform = expanded ? 'rotate(90deg)' : '';
    }

    if (e('ps-suggested-per')) e('ps-suggested-per').textContent = suggestedMin > 0 ? fmtRange(suggestedMin, suggestedMax, suggestedIsRange) : '—';
    if (e('ps-landed-total'))  e('ps-landed-total').textContent  = landedTotal > 0 ? '$' + fmt2(landedTotal) : '—';
    // Additional Fees row: only shown when at least one fee is applied.
    const feesRow = e('ps-fees-row');
    if (feesRow) {
      if (_appliedFeesTotal > 0) {
        feesRow.style.display = '';
        const feesEl = e('ps-fees-applied');
        if (feesEl) {
          const labels = _appliedFeesArr.map(f => f.label.replace(/\s*Fee\(s\)$/i, '')).join(', ');
          feesEl.innerHTML = `<span style="font-size:11px; color:var(--text-muted); margin-right:8px; font-weight:500;">${labels}</span>+ $${fmt2(_appliedFeesTotal)}`;
        }
      } else {
        feesRow.style.display = 'none';
      }
    }
    // Inline math under the Landed Per label: "$prodTotal/qty + $shipTotal/qty"
    if (e('ps-landed-math')) {
      const productTotalForLanded = tierQty > 0 ? tierQty * avgPerUnitUsd : 0;
      const fmtCompact = v => '$' + v.toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2});
      const fmtQty     = q => q.toLocaleString('en-US');
      e('ps-landed-math').textContent = (tierQty > 0 && productTotalForLanded > 0)
        ? `${fmtCompact(productTotalForLanded)} / ${fmtQty(tierQty)} + ${fmtCompact(shippingUsd)} / ${fmtQty(tierQty)}`
        : '';
    }
    if (e('ps-total-usd'))     e('ps-total-usd').textContent     = !isNaN(totalUsd) ? '$' + fmt2(totalUsd) : '—';
    if (e('ps-order-profit')) {
      const profitEl = e('ps-order-profit');
      if (!isNaN(orderProfit)) {
        profitEl.textContent = (orderProfit < 0 ? '−$' : '$') + fmt2(Math.abs(orderProfit));
        profitEl.classList.toggle('negative', orderProfit < 0);
      } else {
        profitEl.textContent = '—';
        profitEl.classList.remove('negative');
      }
    }

    // Stash the weighted-avg landed for input handlers (so Sale Per can
    // back-solve margin without re-deriving everything from the table)
    _landedAvgForMargin = landedAvg > 0 ? landedAvg : 0;

    // ── Client Quote summary bar (header AND footer) ───────────────────
    //   Sale Price Range  ← Suggested Price Per (locked to client default)
    //   Total Order       ← Total Landed Cost (deterministic)
    //   Production Lead   ← max RFQ lead time (already computed in rfq-max-lead)
    //   Shipping Lead     ← max of freight Lead Time inputs
    //   Total Lead        ← Production + Shipping
    // querySelectorAll on data-qrs attributes writes to BOTH the header
    // bar at the top of the section card and the footer bar at the
    // bottom of the body in a single pass — the same data renders in
    // both places without the renderer having to know they exist.
    const setQrs = (key, value) => {
      document.querySelectorAll(`[data-qrs="${key}"]`).forEach(el => { el.textContent = value; });
    };

    // Sale Price (USD) reads directly from the operator's Sale Per
    // input — it's the "ultimate say". Total Order = Sale Per × tier
    // qty + applied fees (computed above as totalUsd). When Sale Per
    // is blank, both stats render as "—" so the header doesn't lie
    // about a value the operator hasn't committed to yet.
    setQrs('usd',   (!isNaN(salePer) && salePer > 0) ? '$' + fmt2(salePer) : '—');
    setQrs('total', !isNaN(totalUsd)                 ? '$' + fmt2(totalUsd) : '—');

    const prodLeadDays = parseInt(document.getElementById('rfq-max-lead')?.textContent) || 0;
    setQrs('lead', prodLeadDays > 0 ? prodLeadDays + ' days' : '—');

    // Shipping Lead = SELECTED freight mode's lead time (range or single).
    // _ctxShipLeadRange/_ctxShipLeadText are computed at the top of this fn.
    setQrs('ship-lead', _ctxShipLeadText);

    // Total Lead = Production + Shipping. When shipping is a range, total
    // is also a range (production + min … production + max).
    let totalLeadText;
    if (prodLeadDays === 0 && !_ctxShipLeadRange.hasValue) {
      totalLeadText = '—';
    } else {
      const tMin = prodLeadDays + (_ctxShipLeadRange.hasValue ? _ctxShipLeadRange.min : 0);
      const tMax = prodLeadDays + (_ctxShipLeadRange.hasValue ? _ctxShipLeadRange.max : 0);
      totalLeadText = (tMin === tMax) ? tMin + ' days' : tMin + '-' + tMax + ' days';
    }
    setQrs('total-lead', totalLeadText);
  }

  // Parse a lead-time field — accepts "10" (single) or "7-10" (range).
  function _parseLeadRange(s) {
    if (!s) return { min: 0, max: 0, hasValue: false };
    const m = String(s).trim().match(/^(\d+)\s*[-–—]\s*(\d+)$/);
    if (m) {
      const a = parseInt(m[1]), b = parseInt(m[2]);
      return { min: Math.min(a, b), max: Math.max(a, b), hasValue: a > 0 || b > 0 };
    }
    const n = parseInt(String(s).trim());
    if (!isNaN(n) && n > 0) return { min: n, max: n, hasValue: true };
    return { min: 0, max: 0, hasValue: false };
  }

  // Format a parsed lead range for display: "7-10 days" or "10 days" or "—".
  function _formatLeadRange(r) {
    if (!r || !r.hasValue) return '—';
    if (r.min === r.max) return r.min + ' days';
    return r.min + '-' + r.max + ' days';
  }

  // Module-scope: weighted-avg landed (USD) cached by renderPricingTab so the
  // Sale Per input handler can derive margin % without a full re-render.
  let _landedAvgForMargin = 0;

  // Debounced renderPricingTab — coalesces rapid keystrokes in margin /
  // sale per / ship lead inputs so we don't rebuild the Client Quote table
  // and re-run recalcRfqTotals on every character. ~80 ms is fast enough to
  // feel instant but slow enough to skip all but the last render in a burst.
  let _pricingTabRenderTimer = null;
  function _schedulePricingTabRender() {
    if (_pricingTabRenderTimer) clearTimeout(_pricingTabRenderTimer);
    _pricingTabRenderTimer = setTimeout(() => {
      _pricingTabRenderTimer = null;
      if (typeof renderPricingTab === 'function') renderPricingTab();
    }, 80);
  }

  // Margin % input handler — schedules a Pricing tab re-render and triggers
  // (debounced) autosave so the workbook keeps the override.
  function onPricingMarginInput() {
    _schedulePricingTabRender();
    if (!_filling) autoSaveWorkbook();
  }

  // Freight lead-time input handler — schedules a Pricing tab re-render so
  // the Client Quote header updates, and persists the new value.
  function onShipLeadInput() {
    _schedulePricingTabRender();
    if (!_filling) autoSaveWorkbook();
  }

  // Toggle a Client Quote parent row open/closed, revealing or hiding its
  // variant rows. Called from the parent row's onclick.
  function toggleClientQuoteParent(parentId) {
    const root = document.getElementById('pricing-quote-ref-body');
    if (!root) return;
    const parentRow = root.querySelector(`tr[data-cq-parent="${parentId}"]`);
    if (parentRow) parentRow.classList.toggle('expanded');
    root.querySelectorAll(`tr[data-cq-variant-of="${parentId}"]`).forEach(r => {
      r.classList.toggle('hidden');
    });
  }

  // ── Client Quote export (CSV + PDF) ────────────────────────────────
  // Walks the rendered Client Quote table + summary bar and returns a
  // canonical { meta, header, lineItems, fees, summary } payload that
  // both the CSV and PDF exporters consume. Reading the rendered DOM
  // (rather than re-deriving from rfq inputs) keeps the export visually
  // identical to what the operator sees on screen — including range-
  // priced "Variable" groups, applied fees, and the zero-fee row.
  function _collectClientQuoteForExport() {
    const root = document.getElementById('pricing-quote-ref-body');
    if (!root) return null;
    const table = root.querySelector('.pricing-quote-ref-table');
    if (!table) return null;

    const lineItems = []; // { kind: 'parent'|'variant'|'fee'|'feeZero', label, qty, sale, total }
    const variantParents = {};

    // Parent + variant rows
    table.querySelectorAll('tbody > tr').forEach(tr => {
      const parentId = tr.getAttribute('data-cq-parent');
      const variantOf = tr.getAttribute('data-cq-variant-of');
      const cells = tr.querySelectorAll('td');
      if (cells.length < 5) return;

      const cellText = i => (cells[i]?.innerText || '').replace(/\s+/g, ' ').trim();

      if (tr.classList.contains('cq-fees-divider-row')) {
        return; // skip pure header
      }
      if (tr.classList.contains('cq-fee-zero-row')) {
        lineItems.push({ kind: 'feeZero', label: cellText(1), qty: '', sale: '', total: cellText(4) });
        return;
      }
      if (tr.classList.contains('cq-fee-row')) {
        lineItems.push({ kind: 'fee', label: cellText(1), qty: '', sale: '', total: cellText(4) });
        return;
      }
      if (tr.classList.contains('cq-parent-row')) {
        const isExpandable = !tr.classList.contains('no-variants');
        const item = { kind: 'parent', label: cellText(1), qty: cellText(2), sale: cellText(3), total: cellText(4) };
        lineItems.push(item);
        if (isExpandable && parentId) variantParents[parentId] = item;
        return;
      }
      if (tr.classList.contains('cq-variant-row') && variantOf) {
        lineItems.push({ kind: 'variant', label: cellText(1), qty: cellText(2), sale: cellText(3), total: cellText(4) });
        return;
      }
    });

    // Header summary stats (same data attrs the renderer populates)
    const stat = key => {
      const el = document.querySelector(`.cq-summary-bar--header [data-qrs="${key}"]`);
      return (el?.innerText || '').replace(/\s+/g, ' ').trim();
    };
    const summary = {
      salePrice:     stat('usd'),
      totalOrder:    stat('total'),
      productionLead:stat('lead'),
      shippingLead:  stat('ship-lead'),
      totalLead:     stat('total-lead'),
    };

    // Quote meta
    const today    = new Date();
    const dateStr  = today.toISOString().slice(0, 10);
    const meta = {
      clientName:  (typeof currentClient !== 'undefined' && currentClient) ? currentClient : (document.getElementById('client-name')?.value || ''),
      productName: (document.getElementById('product-name')?.value || '').trim(),
      productDesc: (document.getElementById('product-desc')?.value || '').trim(),
      quoteDate:   (document.getElementById('quote-date')?.value || '').trim() || dateStr,
      quoteValid:  (document.getElementById('quote-valid-until')?.value || '').trim(),
      generated:   today.toLocaleString('en-US'),
    };

    return { meta, lineItems, summary };
  }

  // CSV escaping: wrap in quotes and double any embedded quotes per
  // RFC 4180 so values with commas/newlines round-trip cleanly into
  // Excel/Sheets.
  function _csvEscape(v) {
    const s = String(v == null ? '' : v);
    return '"' + s.replace(/"/g, '""') + '"';
  }

  function exportClientQuoteCSV() {
    const data = _collectClientQuoteForExport();
    if (!data || data.lineItems.length === 0) {
      _msToast('No quote items to export. Add items on the Workbook tab first.', 'error');
      return;
    }

    const lines = [];
    // Meta header (first few rows are key/value, easy to read in Excel)
    lines.push(_csvEscape('Market Sculpt Client Quote'));
    lines.push([_csvEscape('Client'),       _csvEscape(data.meta.clientName)].join(','));
    lines.push([_csvEscape('Product'),      _csvEscape(data.meta.productName)].join(','));
    if (data.meta.productDesc) lines.push([_csvEscape('Description'), _csvEscape(data.meta.productDesc)].join(','));
    lines.push([_csvEscape('Quote Date'),   _csvEscape(data.meta.quoteDate)].join(','));
    if (data.meta.quoteValid)  lines.push([_csvEscape('Valid Until'), _csvEscape(data.meta.quoteValid)].join(','));
    lines.push([_csvEscape('Generated'),    _csvEscape(data.meta.generated)].join(','));
    lines.push(''); // blank separator

    // Summary block
    lines.push(_csvEscape('Summary'));
    lines.push([_csvEscape('Sale Price (USD)'),    _csvEscape(data.summary.salePrice)].join(','));
    lines.push([_csvEscape('Total Order'),         _csvEscape(data.summary.totalOrder)].join(','));
    lines.push([_csvEscape('Production Lead'),     _csvEscape(data.summary.productionLead)].join(','));
    lines.push([_csvEscape('Shipping Lead'),       _csvEscape(data.summary.shippingLead)].join(','));
    lines.push([_csvEscape('Total Lead'),          _csvEscape(data.summary.totalLead)].join(','));
    lines.push('');

    // Line items
    lines.push(['Type','Item','Quantity','Sale Price (USD)','Total (USD)'].map(_csvEscape).join(','));
    data.lineItems.forEach(it => {
      let kindLabel = '';
      let label = it.label;
      if (it.kind === 'parent')   kindLabel = 'Item';
      if (it.kind === 'variant')  { kindLabel = 'Variant'; label = label.replace(/^└\s*/, ''); }
      if (it.kind === 'fee')      kindLabel = 'Fee';
      if (it.kind === 'feeZero')  kindLabel = 'Fee';
      lines.push([
        _csvEscape(kindLabel),
        _csvEscape(label),
        _csvEscape(it.qty),
        _csvEscape(it.sale),
        _csvEscape(it.total),
      ].join(','));
    });

    // BOM so Excel detects UTF-8 (the ¥ and en-dash characters in some
    // existing values would otherwise mojibake on Windows Excel).
    const csv = '﻿' + lines.join('\r\n');
    const fname = `client-quote_${(data.meta.clientName || 'workbook').replace(/[^a-z0-9]+/gi, '-')}_${data.meta.quoteDate}.csv`.toLowerCase();

    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const url  = URL.createObjectURL(blob);
    const a    = document.createElement('a');
    a.href = url;
    a.download = fname;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    setTimeout(() => URL.revokeObjectURL(url), 1000);
    _msToast('Quote CSV downloaded.', 'success');
  }

  function exportClientQuotePDF() {
    const data = _collectClientQuoteForExport();
    if (!data || data.lineItems.length === 0) {
      _msToast('No quote items to export. Add items on the Workbook tab first.', 'error');
      return;
    }

    // Build line-item rows with light visual grouping that matches the
    // on-screen layout: parent rows bold, variant rows indented and
    // muted, fee rows in the accent color with a + prefix.
    const escHtml = s => String(s == null ? '' : s)
      .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;');

    const itemRows = data.lineItems.map(it => {
      const labelEsc = escHtml(it.label);
      if (it.kind === 'variant') {
        // Strip any legacy "└ " prefix that older renders may have
        // baked into the label, then render the variant name on its
        // own indented line — no corner-bracket character.
        const inner = labelEsc.replace(/^└\s*/, '');
        return `<tr class="row-variant"><td></td><td class="lbl indent">${inner}</td><td class="r">${escHtml(it.qty)}</td><td class="r">${escHtml(it.sale)}</td><td class="r">${escHtml(it.total)}</td></tr>`;
      }
      if (it.kind === 'fee' || it.kind === 'feeZero') {
        const sign = it.kind === 'fee' ? '+' : '';
        return `<tr class="row-fee"><td class="r" style="color:#E8751A;font-weight:700;">${sign}</td><td class="lbl">${labelEsc}</td><td class="r">${escHtml(it.qty)}</td><td class="r">${escHtml(it.sale)}</td><td class="r accent">${escHtml(it.total)}</td></tr>`;
      }
      // parent
      return `<tr class="row-parent"><td></td><td class="lbl"><strong>${labelEsc}</strong></td><td class="r">${escHtml(it.qty)}</td><td class="r">${escHtml(it.sale)}</td><td class="r accent"><strong>${escHtml(it.total)}</strong></td></tr>`;
    }).join('');

    const validRow = data.meta.quoteValid
      ? `<div class="meta-row"><span class="meta-label">Valid Until</span><span class="meta-value">${escHtml(data.meta.quoteValid)}</span></div>`
      : '';
    const descRow = data.meta.productDesc
      ? `<p class="desc">${escHtml(data.meta.productDesc)}</p>`
      : '';

    const html = `<!DOCTYPE html><html lang="en"><head>
<meta charset="UTF-8">
<title>Client Quote — ${escHtml(data.meta.productName || data.meta.clientName)}</title>
<style>
  *,*::before,*::after { box-sizing: border-box; margin: 0; padding: 0; }
  body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif; color: #1a1d2e; background: #fff; padding: 32px; font-size: 13px; line-height: 1.5; }
  .header { display: flex; justify-content: space-between; align-items: flex-start; border-bottom: 3px solid #E8751A; padding-bottom: 16px; margin-bottom: 22px; }
  .brand { font-size: 22px; font-weight: 800; color: #E8751A; border-left: 3px solid #E8751A; padding-left: 12px; letter-spacing: -0.3px; }
  .brand-sub { font-size: 11px; font-weight: 500; color: #6b7280; letter-spacing: 0.04em; text-transform: uppercase; margin-top: 4px; }
  .meta-block { text-align: right; }
  .meta-row { font-size: 12px; color: #374151; margin-bottom: 4px; }
  .meta-label { font-weight: 700; color: #9ba3c0; text-transform: uppercase; letter-spacing: 0.05em; font-size: 10px; margin-right: 6px; }
  .meta-value { color: #1a1d2e; }
  h1 { font-size: 22px; font-weight: 800; margin-bottom: 4px; color: #1a1d2e; }
  .for-client { font-size: 13px; color: #6b7280; margin-bottom: 14px; }
  .desc { font-size: 12px; color: #6b7280; margin-bottom: 18px; padding: 10px 12px; background: #f8f9fb; border-left: 3px solid #6b93ff; border-radius: 4px; line-height: 1.6; }
  .summary-grid { display: grid; grid-template-columns: repeat(5, 1fr); gap: 8px; margin: 22px 0 26px; }
  .stat { background: linear-gradient(135deg, rgba(107,147,255,0.10) 0%, rgba(107,147,255,0.04) 100%); border: 1px solid rgba(107,147,255,0.25); border-radius: 8px; padding: 10px 12px; }
  .stat-label { font-size: 9px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.06em; color: #6b93ff; margin-bottom: 4px; }
  .stat-value { font-size: 14px; font-weight: 700; color: #1a1d2e; }
  .stat-total { background: linear-gradient(135deg, rgba(232,117,26,0.14) 0%, rgba(232,117,26,0.05) 100%); border-color: rgba(232,117,26,0.4); }
  .stat-total .stat-label { color: #E8751A; }
  table.items { width: 100%; border-collapse: collapse; font-size: 13px; }
  table.items thead th { padding: 10px 12px; font-size: 10px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.05em; color: #9ba3c0; background: #f8f9fb; border-bottom: 1px solid #e5e7eb; text-align: left; }
  table.items thead th.r { text-align: right; }
  table.items tbody td { padding: 9px 12px; border-bottom: 1px solid #f0f2f5; vertical-align: middle; }
  table.items tbody td.r { text-align: right; }
  table.items tbody td.accent { color: #E8751A; }
  table.items tbody tr.row-variant td { color: #6b7280; font-size: 12px; }
  table.items tbody td.lbl.indent { padding-left: 28px; }
  table.items tbody tr.row-fee td { background: rgba(232,117,26,0.04); }
  .total-row { background: #f8f9fb; }
  .total-row td { padding: 12px; font-weight: 700; font-size: 14px; border-top: 2px solid #E8751A !important; }
  .total-row td.accent { color: #E8751A; }
  .footer { margin-top: 28px; padding-top: 16px; border-top: 1px solid #e5e7eb; text-align: center; font-size: 11px; color: #9ba3c0; line-height: 1.7; }
  .footer a { color: #E8751A; text-decoration: none; }
  .print-controls { position: fixed; top: 16px; right: 16px; display: flex; gap: 8px; z-index: 100; }
  .print-controls button { background: #E8751A; color: #fff; border: none; border-radius: 6px; padding: 7px 14px; font-size: 12px; font-weight: 700; cursor: pointer; font-family: inherit; box-shadow: 0 2px 6px rgba(0,0,0,0.15); }
  .print-controls button.secondary { background: #fff; color: #6b7280; border: 1px solid #d1d5db; }
  @media print {
    body { padding: 0; }
    .print-controls { display: none !important; }
    .summary-grid { page-break-inside: avoid; }
    table.items { page-break-inside: auto; }
    table.items tr { page-break-inside: avoid; page-break-after: auto; }
  }
</style>
</head><body>
  <div class="print-controls">
    <button onclick="window.print()">Print / Save as PDF</button>
    <button class="secondary" onclick="window.close()">Close</button>
  </div>
  <div class="header">
    <div>
      <div class="brand">Market Sculpt</div>
      <div class="brand-sub">Client Quote</div>
    </div>
    <div class="meta-block">
      <div class="meta-row"><span class="meta-label">Quote Date</span><span class="meta-value">${escHtml(data.meta.quoteDate)}</span></div>
      ${validRow}
      <div class="meta-row"><span class="meta-label">Generated</span><span class="meta-value">${escHtml(data.meta.generated)}</span></div>
    </div>
  </div>

  <h1>${escHtml(data.meta.productName || 'Quote')}</h1>
  <div class="for-client">Prepared for <strong>${escHtml(data.meta.clientName)}</strong></div>
  ${descRow}

  <div class="summary-grid">
    <div class="stat"><div class="stat-label">Sale Price (USD)</div><div class="stat-value">${escHtml(data.summary.salePrice || '—')}</div></div>
    <div class="stat stat-total"><div class="stat-label">Total Order</div><div class="stat-value">${escHtml(data.summary.totalOrder || '—')}</div></div>
    <div class="stat"><div class="stat-label">Production Lead</div><div class="stat-value">${escHtml(data.summary.productionLead || '—')}</div></div>
    <div class="stat"><div class="stat-label">Shipping Lead</div><div class="stat-value">${escHtml(data.summary.shippingLead || '—')}</div></div>
    <div class="stat"><div class="stat-label">Total Lead</div><div class="stat-value">${escHtml(data.summary.totalLead || '—')}</div></div>
  </div>

  <table class="items">
    <thead>
      <tr>
        <th style="width:24px;"></th>
        <th>Item</th>
        <th class="r" style="width:90px;">Qty</th>
        <th class="r" style="width:140px;">Sale Price (USD)</th>
        <th class="r" style="width:130px;">Total (USD)</th>
      </tr>
    </thead>
    <tbody>${itemRows}</tbody>
    <tfoot>
      <tr class="total-row">
        <td colspan="4" class="r">Order Total</td>
        <td class="r accent">${escHtml(data.summary.totalOrder || '—')}</td>
      </tr>
    </tfoot>
  </table>

  <div class="footer">
    Market Sculpt LLC &nbsp;·&nbsp; <a href="https://marketsculpt.com">marketsculpt.com</a><br>
    Questions? <a href="mailto:parker@marketsculpt.com">parker@marketsculpt.com</a>
  </div>

  <script>
    // Auto-open the system print dialog so "Save as PDF" is one click
    // away. User can cancel if they only wanted to read the page.
    window.addEventListener('load', () => setTimeout(() => window.print(), 350));
  <\/script>
</body></html>`;

    const win = window.open('', '_blank');
    if (!win) {
      _msToast('Pop-up blocked. Allow pop-ups for this site to use PDF export.', 'error');
      return;
    }
    win.document.open();
    win.document.write(html);
    win.document.close();
  }

  // Sale Per input handler — pure pass-through. Sale Per is the
  // operator's "ultimate say", fully independent from Margin. Typing
  // here does NOT back-solve margin and does NOT touch Suggested
  // Price. Just re-renders so Total USD / Order Profit pick up the
  // new salePer × tierQty, and autosaves.
  function onPricingSalePerInput() {
    _schedulePricingTabRender();
    if (!_filling) autoSaveWorkbook();
  }

  // Render pallet stats into the shipping tab panel
  function syncShippingPalletStats() {
    const el = document.getElementById('sh-pallet-stats-body');
    if (!el) return;
    const ps = window._palletStats;
    const manualOn = !!document.getElementById('pallet-manual')?.checked;
    if (!ps) {
      el.innerHTML = `<span style="font-size:12px; color:var(--text-muted); font-style:italic;">Enter ${manualOn ? 'product' : 'outer carton'} dimensions on the Workbook tab to see pallet stats.</span>`;
      return;
    }
    const stat = (val, lbl, accent) =>
      `<div class="sh-pallet-stat">
        <div class="sh-pallet-stat-val${accent ? ' accent' : ''}">${val}</div>
        <div class="sh-pallet-stat-lbl">${lbl}</div>
      </div>`;

    // Per-pallet item label flips with mode — products in manual,
    // outer cartons in carton mode.
    const itemP = manualOn ? 'units' : 'outer cartons';
    let html = `<div class="sh-pallet-grid">
      ${stat(ps.perLayer,       `${itemP} / layer`)}
      ${stat(ps.maxLayers,      'max layers')}
      ${stat(ps.totalPerPallet, `${itemP} / pallet`)}
      ${stat(ps.surfaceUse + '%', 'surface coverage')}
      ${!manualOn && ps.productsPerOuter > 0 ? stat(ps.outerQtyVal, 'inner cartons / outer') + stat(ps.productsPerOuter, 'products / outer carton') : ''}`;

    if (ps.totalCartons > 0) {
      const shipmentLabel = manualOn
        ? `Shipment of ${ps.totalCartons.toLocaleString()} units`
        : `Shipment of ${ps.totalCartons.toLocaleString()} outer cartons`;
      html += `<hr class="sh-pallet-divider">
        <div class="sh-pallet-section-label">${shipmentLabel}</div>
        ${stat(ps.palletsNeeded, 'pallets needed', true)}
        ${!manualOn && ps.totalInners > 0 ? stat(ps.totalInners, 'total inner cartons') : '<div></div>'}
        ${ps.totalProducts > 0 ? `<div class="sh-pallet-stat" style="grid-column:span 2;"><div class="sh-pallet-stat-val">${ps.totalProducts.toLocaleString()}</div><div class="sh-pallet-stat-lbl">total products</div></div>` : ''}`;
    }
    html += '</div>';
    el.innerHTML = html;
  }

  // Sync outer carton dims/weight display from workbook fields
  // Shipping-tab "ship unit" resolver. In carton mode the freight is
  // calculated against the OUTER CARTON dims/weight × carton count.
  // In manual mode (pallet view fits products directly on the pallet,
  // no cartons), the shipping math has to fall back to PRODUCT dims/
  // weight × unit count — otherwise the shipping tab is just blank.
  function _shipUnit() {
    const manualOn = !!document.getElementById('pallet-manual')?.checked;
    const get = id => parseFloat(document.getElementById(id)?.value) || 0;
    const totalUnits = _msIntFromInput(document.getElementById('pallet-total-cartons'));
    // Weight-only override: skip dim-driven math entirely and pass
    // through the operator's Case Qty + per-case Weight as the ship
    // unit. Dims = 0 so volumetric weight collapses to 0; chargeable
    // weight ends up equal to actual.
    const weightOnly = !!document.getElementById('weight-only-override')?.checked;
    if (weightOnly) {
      const caseQty = parseInt(document.getElementById('weight-only-qty')?.value) || 0;
      const caseKg  = parseFloat(document.getElementById('weight-only-kg')?.value) || 0;
      return {
        mode: 'weight-only',
        unitLabel: 'case', unitLabelP: 'cases',
        lCm: 0, wCm: 0, hCm: 0,
        wtKg: caseKg,
        count: caseQty
      };
    }
    // Case Only Override: ship unit is the CASE — case dims feed the
    // volumetric / freight math, cases-per-order drives the count.
    const caseOnly = !!document.getElementById('case-only-override')?.checked;
    if (caseOnly) {
      return {
        mode: 'case-only',
        unitLabel: 'case', unitLabelP: 'cases',
        lCm: get('case-only-l-cm'),
        wCm: get('case-only-w-cm'),
        hCm: get('case-only-h-cm'),
        wtKg: get('case-only-weight-kg'),
        count: _msIntFromInput(document.getElementById('case-only-cases-order'))
      };
    }
    if (manualOn) {
      return {
        mode: 'manual',
        unitLabel: 'product',
        unitLabelP: 'products',
        lCm: get('dim-cm-l'),
        wCm: get('dim-cm-w'),
        hCm: get('dim-cm-h'),
        wtKg: get('dim-weight-kg'),
        count: totalUnits, // 1 product per pallet item
      };
    }
    // Carton mode — derive carton count from total units / per-outer
    const innerQty = parseInt(document.getElementById('carton-inner-count')?.value) || 0;
    const outerQty = parseInt(document.getElementById('carton-outer-count')?.value) || 0;
    const productsPerOuter = (innerQty > 0 && outerQty > 0) ? innerQty * outerQty : 0;
    const cartonCount = productsPerOuter > 0 ? Math.ceil(totalUnits / productsPerOuter) : 0;
    return {
      mode: 'carton',
      unitLabel: 'outer carton',
      unitLabelP: 'outer cartons',
      lCm: get('carton-outer-l-cm'),
      wCm: get('carton-outer-w-cm'),
      hCm: get('carton-outer-h-cm'),
      wtKg: get('carton-outer-weight'),
      count: cartonCount,
    };
  }

  function syncShippingDims() {
    const fmt = v => v > 0 ? v.toFixed(2) : '—';
    const ship = _shipUnit();

    // Items in shipment — either total cartons (carton mode) or total
    // units / products (manual mode). Label flips accordingly.
    const cartonsEl = document.getElementById('sh-cartons-val');
    if (cartonsEl) cartonsEl.textContent = ship.count > 0 ? ship.count.toLocaleString() : '—';
    const cartonsLbl = document.getElementById('sh-cartons-label');
    if (cartonsLbl) cartonsLbl.textContent = ship.mode === 'manual' ? 'units in shipment' : 'cartons in shipment';

    const lIn = ship.lCm ? ship.lCm / 2.54 : 0;
    const wIn = ship.wCm ? ship.wCm / 2.54 : 0;
    const hIn = ship.hCm ? ship.hCm / 2.54 : 0;
    const wtLbs = ship.wtKg ? ship.wtKg * 2.20462 : 0;

    document.getElementById('sh-l-cm').textContent  = fmt(ship.lCm);
    document.getElementById('sh-l-in').textContent  = fmt(lIn);
    document.getElementById('sh-w-cm').textContent  = fmt(ship.wCm);
    document.getElementById('sh-w-in').textContent  = fmt(wIn);
    document.getElementById('sh-h-cm').textContent  = fmt(ship.hCm);
    document.getElementById('sh-h-in').textContent  = fmt(hIn);
    document.getElementById('sh-wt-kg').textContent  = fmt(ship.wtKg);
    document.getElementById('sh-wt-lbs').textContent = fmt(wtLbs);

    // Inner / units per outer only meaningful in carton mode.
    const ipo = document.getElementById('sh-inner-per-outer');
    const upo = document.getElementById('sh-units-per-outer');
    if (ship.mode === 'carton') {
      const innerPerOuter  = parseInt(document.getElementById('carton-outer-count')?.value) || 0;
      const unitsPerInner  = parseInt(document.getElementById('carton-inner-count')?.value) || 0;
      const unitsPerOuter  = innerPerOuter > 0 && unitsPerInner > 0 ? innerPerOuter * unitsPerInner : 0;
      if (ipo) ipo.textContent = innerPerOuter > 0 ? innerPerOuter : '—';
      if (upo) upo.textContent = unitsPerOuter > 0 ? unitsPerOuter : '—';
    } else {
      if (ipo) ipo.textContent = '—';
      if (upo) upo.textContent = '1'; // each unit IS the ship unit
    }
  }

  // ── Shipping Cost Manual Override ──────────────────────────────────
  // Tick the Override box under Estimated Shipping Cost and type a
  // USD value. _getShippingCostOverrideUsd() returns that override (or
  // null when inactive), and every freight-cost consumer downstream
  // (calcFreight display, Total Landed Cost block, Hypothetical
  // Scenarios panel) reads through this helper so they all stay in
  // sync with whatever the operator typed.
  function _getShippingCostOverrideUsd() {
    const cb = document.getElementById('freight-cost-override-toggle');
    if (!cb || !cb.checked) return null;
    // Strip the thousand-separator commas before parsing so the
    // formatted display ("12,345.67") still resolves to 12345.67.
    const raw = (document.getElementById('freight-cost-override')?.value || '').replace(/,/g, '').trim();
    const v = parseFloat(raw);
    if (!isFinite(v) || v < 0) return null;
    return v;
  }
  // Format helpers for the override input — commas while idle, raw
  // digits while editing so deletion / arrow-key nav stay sane.
  function _formatShippingOverride(el) {
    if (!el) return;
    const raw = (el.value || '').replace(/,/g, '').trim();
    if (raw === '') return;
    const v = parseFloat(raw);
    if (!isFinite(v)) return;
    // Preserve the decimal portion the operator typed (or default to
    // no decimals when they typed a whole number).
    const dotIdx = raw.indexOf('.');
    const decimals = dotIdx >= 0 ? Math.min(2, raw.length - dotIdx - 1) : 0;
    el.value = v.toLocaleString('en-US', {
      minimumFractionDigits: decimals,
      maximumFractionDigits: 2
    });
  }
  function _unformatShippingOverride(el) {
    if (!el) return;
    el.value = (el.value || '').replace(/,/g, '');
  }
  function onShippingCostOverrideToggle() {
    const cb    = document.getElementById('freight-cost-override-toggle');
    const input = document.getElementById('freight-cost-override');
    if (!cb || !input) return;
    const on = !!cb.checked;
    input.disabled = !on;
    if (on && !input.value) {
      // Pre-fill with the currently-computed cost so the operator
      // sees the starting baseline they're about to adjust. Format
      // with commas right away.
      const costStr = document.getElementById('freight-out-cost')?.textContent || '';
      const m = costStr.match(/\$\s*([\d,]+(?:\.\d+)?)/);
      if (m) {
        const raw = m[1].replace(/,/g, '');
        input.value = raw;
        _formatShippingOverride(input);
      }
    } else if (on) {
      // Re-format an existing value that came in unformatted (load,
      // paste, etc.) so the display stays consistent.
      _formatShippingOverride(input);
    }
    if (typeof calcFreight === 'function') calcFreight();
    if (typeof renderPalletViz === 'function') renderPalletViz();
    if (typeof renderPricingTab === 'function') renderPricingTab();
    if (typeof autoSaveWorkbook === 'function' && !_filling) autoSaveWorkbook();
  }
  function onShippingCostOverrideInput() {
    if (typeof calcFreight === 'function') calcFreight();
    if (typeof renderPalletViz === 'function') renderPalletViz();
    if (typeof renderPricingTab === 'function') renderPricingTab();
    if (typeof autoSaveWorkbook === 'function' && !_filling) autoSaveWorkbook();
  }

  function calcFreight() {
    syncShippingDims();

    // Shipping unit — outer carton in carton mode, individual product
    // in manual mode. Freight cost scales with whichever the shipper
    // is actually packing.
    const ship     = _shipUnit();
    const lCm      = ship.lCm;
    const wCm      = ship.wCm;
    const hCm      = ship.hCm;
    const actualKg = ship.wtKg;

    const rawMode  = document.getElementById('freight-mode').value;
    const mode     = freightMethodRates[rawMode] ? rawMode : 'slow'; // fallback to slow if mode unknown/empty
    const rate     = freightMethodRates[mode];
    // Carton count comes from _shipUnit(). In carton mode it's
    // computed as ceil(totalUnits / (innerCount × outerCount)) — when
    // either count is missing the helper returns 0. We used to fall
    // back to "1 carton" here, which silently produced a single-
    // carton freight quote even when the operator was shipping
    // thousands of units (e.g. Tank workbook → 5,925 units showed
    // $36.99 instead of the real ~$200+). Honest behavior: cartons=0
    // when specs are missing, freight totals collapse to 0, and the
    // panel surfaces a banner telling the operator what's missing.
    // Base shipping is ALWAYS the full quantity via the selected method
    // — splits don't reduce the comparison-table qty anymore. The model:
    // quote everything at the base method (e.g. all 5,925 on Fast Boat),
    // and treat any faster-method split as an OPTIONAL upgrade whose
    // extra cost is surfaced (and optionally billed) as an Additional
    // Fee on the Pricing tab. This keeps the headline shipping number
    // stable and predictable; the air upgrade is a deliberate add-on.
    const cartons   = ship.count > 0 ? ship.count : 0;
    const exchange  = USD_TO_RMB;
    // Why carton count is 0 (if it is) — drives the warning banner.
    let missingMsg = '';
    if (cartons === 0 && ship.mode === 'carton') {
      const innerQty   = parseInt(document.getElementById('carton-inner-count')?.value) || 0;
      const outerQty   = parseInt(document.getElementById('carton-outer-count')?.value) || 0;
      const totalUnits = _msIntFromInput(document.getElementById('pallet-total-cartons'));
      const missing = [];
      if (innerQty <= 0)   missing.push('Inner Carton qty');
      if (outerQty <= 0)   missing.push('Outer Carton qty');
      if (totalUnits <= 0) missing.push('Total Units to Ship');
      missingMsg = missing.length
        ? `Add ${missing.join(' + ')} on the Workbook tab to compute freight for the full shipment.`
        : '';
    }
    // Paint or clear the warning banner. Lives in a single <div>
    // injected just above the freight results, so the operator sees
    // it without scrolling.
    (function paintFreightWarning() {
      const host = document.getElementById('freight-out-actual')?.closest('.freight-results, .section-card, .section-body, .freight-panel')
                ?? document.getElementById('freight-out-actual')?.parentElement;
      if (!host) return;
      let warn = document.getElementById('freight-missing-specs-warning');
      if (!missingMsg) { if (warn) warn.remove(); return; }
      if (!warn) {
        warn = document.createElement('div');
        warn.id = 'freight-missing-specs-warning';
        warn.style.cssText = 'margin:0 0 12px; padding:10px 14px; border-radius:8px; background:rgba(217,119,6,0.10); border:1px solid rgba(217,119,6,0.35); color:#d97706; font-size:12px; font-weight:600;';
        host.parentNode.insertBefore(warn, host);
      }
      warn.textContent = '⚠ ' + missingMsg;
    })();

    // Update rate chip displays
    const rmbEl = document.getElementById('freight-rate-rmb-display');
    const usdEl = document.getElementById('freight-rate-usd-display');
    if (rmbEl) rmbEl.textContent = rate.toFixed(2);
    if (usdEl) usdEl.textContent = (rate / exchange).toFixed(2);

    // The comparison table now always reflects the full quantity at each
    // method, so the old "x of y units split off" remainder hint no
    // longer applies — keep it hidden.
    const _hintEl = document.getElementById('freight-remainder-hint');
    if (_hintEl) { _hintEl.style.display = 'none'; _hintEl.textContent = ''; }

    if (!lCm || !wCm || !hCm) {
      // Weight-driven path: no dims means no volumetric weight, so
      // chargeable weight collapses to Actual. Used by:
      //   • Weight-Only Override  — operator skipped dims entirely
      //   • Case-Only Override w/o dims — same situation, case-shaped
      //     freight where the dim fields were left blank
      // Both render the headline + comparison table off actualKg×count.
      const weightDriven = (ship.mode === 'weight-only' || ship.mode === 'case-only')
                           && actualKg > 0 && cartons > 0;
      if (weightDriven) {
        const totalActual = actualKg * cartons;
        const modeLabel = ship.mode === 'weight-only' ? 'weight-only mode' : 'case-only mode (no dims)';
        const fmt = (kg) => kg.toFixed(2) + ' kg  /  ' + (kg * 2.20462).toFixed(2) + ' lbs';
        const set = (id, val) => { const el = document.getElementById(id); if (el) el.textContent = val; };
        set('freight-out-actual',  fmt(totalActual));
        set('freight-out-vol',     'N/A — ' + modeLabel);
        set('freight-out-charge',  fmt(totalActual));
        set('freight-out-formula', `${cartons.toLocaleString()} ${ship.unitLabelP} × ${actualKg} kg`);
        const costEl = document.getElementById('freight-out-cost');
        if (costEl) costEl.textContent = '¥ ' + (totalActual * rate).toLocaleString('en-US', {minimumFractionDigits:2, maximumFractionDigits:2}) + '  /  $ ' + ((totalActual * rate) / exchange).toLocaleString('en-US', {minimumFractionDigits:2, maximumFractionDigits:2});
        // Bars — Actual full, Volumetric blank, Chargeable = Actual.
        const setBar = (valId, barId, val, h) => {
          const v = document.getElementById(valId), b = document.getElementById(barId);
          if (v) v.textContent = val;
          if (b) b.style.height = h;
        };
        setBar('freight-bar-actual-val', 'freight-bar-actual', totalActual.toFixed(0) + ' kg', '100%');
        setBar('freight-bar-vol-val',    'freight-bar-vol',    '—',                              '0%');
        setBar('freight-bar-charge-val', 'freight-bar-charge', totalActual.toFixed(0) + ' kg', '100%');
        // Verdict — without dims there's no volumetric to lose to; the
        // shipper bills off actual weight straight up.
        const verdictEl = document.getElementById('freight-verdict');
        const extraEl   = document.getElementById('freight-extra');
        if (verdictEl) {
          verdictEl.className = 'freight-verdict actual';
          verdictEl.textContent = 'Actual weight applies — no dims supplied, no volumetric comparison.';
        }
        if (extraEl) extraEl.style.display = 'none';
        // Method comparison — chargeable weight is identical across
        // methods (volumetric = 0 everywhere), but the per-kg rate
        // differs, so Cost (¥) / Cost ($) DO vary by row. Populate the
        // 5-column table + results-panel chips so the operator can
        // still compare methods on price.
        [
          { key: 'slow',      r: freightMethodRates.slow },
          { key: 'fast',      r: freightMethodRates.fast },
          { key: 'airupp',    r: freightMethodRates.airupp },
          { key: 'directair', r: freightMethodRates.directair },
        ].forEach(m => {
          const cw = totalActual;             // chargeable = actual
          const cr = cw * m.r;
          const cu = exchange > 0 ? cr / exchange : 0;
          const combinedVal = '¥ ' + cr.toLocaleString('en-US', {minimumFractionDigits:2, maximumFractionDigits:2}) + '  /  $ ' + cu.toLocaleString('en-US', {minimumFractionDigits:2, maximumFractionDigits:2});
          const wtEl  = document.getElementById('freight-wt-'  + m.key);
          const rmbEl = document.getElementById('freight-rmb-' + m.key);
          const usdEl = document.getElementById('freight-usd-' + m.key);
          if (wtEl)  wtEl.textContent  = cw.toFixed(2) + ' kg';
          if (rmbEl) rmbEl.textContent = '¥ ' + cr.toLocaleString('en-US', {minimumFractionDigits:2, maximumFractionDigits:2});
          if (usdEl) usdEl.textContent = '$ ' + cu.toLocaleString('en-US', {minimumFractionDigits:2, maximumFractionDigits:2});
          const resEl = document.getElementById('freight-res-' + m.key);
          if (resEl) resEl.textContent = combinedVal;
        });
        // No dims → no CBM to report.
        const cmpSea = document.getElementById('freight-cmp-sea');
        if (cmpSea) cmpSea.textContent = 'N/A — no dims';
        // Cache total shipment weight on the workbook so the Orders
        // page (and Add Workbook to Order picker) can display weight
        // for Case-Only / Weight-Only workbooks that never run the
        // pallet calc. Mirrors the same field written from
        // renderPalletViz at line ~11989 — same key, same units (kg).
        // Without this, the Orders summary reads 0 and renders "—".
        if (typeof currentClient === 'string' && currentWorkbookId) {
          const _wbWtKey = `${currentClient}|${currentWorkbookId}`;
          if (!workbookDetail[_wbWtKey]) workbookDetail[_wbWtKey] = {};
          workbookDetail[_wbWtKey].pricingShipmentWeightKg = totalActual > 0 ? totalActual : 0;
          if (typeof autoSaveWorkbook === 'function' && !_filling) autoSaveWorkbook();
        }
        return;
      }
      ['freight-out-actual','freight-out-vol','freight-out-charge','freight-out-formula','freight-out-cost'].forEach(id => {
        const el = document.getElementById(id);
        if (el) el.textContent = '—';
      });
      return;
    }

    const volume    = lCm * wCm * hCm;  // cm³
    const divisor   = freightMethodDivisors[mode];
    const volWeight = volume / divisor;  // kg per carton (volumetric)

    const chargePerCarton = Math.max(actualKg, volWeight);
    const totalActual     = actualKg * cartons;
    const totalVol        = volWeight * cartons;
    const totalCharge     = chargePerCarton * cartons;
    const computedCostRmb = totalCharge * rate;
    const computedCostUsd = exchange > 0 ? computedCostRmb / exchange : 0;
    // Manual override (if active) replaces both display values + the
    // numbers the downstream cards (Total Landed Cost, Hypothetical
    // Scenarios) read back from these elements.
    const overrideUsd = _getShippingCostOverrideUsd();
    const totalCostUsd = (overrideUsd !== null) ? overrideUsd : computedCostUsd;
    const totalCostRmb = (overrideUsd !== null) ? overrideUsd * exchange : computedCostRmb;

    const formulaStr = `(${lCm.toFixed(0)} × ${wCm.toFixed(0)} × ${hCm.toFixed(0)}) ÷ ${divisor.toLocaleString()}`;

    // Results (total for shipment, dual units)
    document.getElementById('freight-out-actual').textContent  = totalActual.toFixed(2)  + ' kg  /  ' + (totalActual  * 2.20462).toFixed(2) + ' lbs';
    document.getElementById('freight-out-vol').textContent     = totalVol.toFixed(2)     + ' kg  /  ' + (totalVol     * 2.20462).toFixed(2) + ' lbs';
    document.getElementById('freight-out-charge').textContent  = totalCharge.toFixed(2)  + ' kg  /  ' + (totalCharge  * 2.20462).toFixed(2) + ' lbs';
    document.getElementById('freight-out-formula').textContent = formulaStr;
    document.getElementById('freight-out-cost').textContent    = '¥ ' + totalCostRmb.toLocaleString('en-US', {minimumFractionDigits:2, maximumFractionDigits:2}) + '  /  $ ' + totalCostUsd.toLocaleString('en-US', {minimumFractionDigits:2, maximumFractionDigits:2}) + (overrideUsd !== null ? '  *' : '');

    // Bar chart
    const maxWt = Math.max(totalActual, totalVol, 0.01);
    document.getElementById('freight-bar-actual').style.height = ((totalActual / maxWt) * 100) + '%';
    document.getElementById('freight-bar-vol').style.height    = ((totalVol    / maxWt) * 100) + '%';
    document.getElementById('freight-bar-charge').style.height = ((totalCharge / maxWt) * 100) + '%';
    document.getElementById('freight-bar-actual-val').textContent = totalActual.toFixed(1);
    document.getElementById('freight-bar-vol-val').textContent    = totalVol.toFixed(1);
    document.getElementById('freight-bar-charge-val').textContent = totalCharge.toFixed(1);

    // Verdict
    const verdictEl = document.getElementById('freight-verdict');
    const extraEl   = document.getElementById('freight-extra');

    if (volWeight > actualKg) {
      verdictEl.className = 'freight-verdict volumetric';
      verdictEl.textContent = 'Volumetric weight applies — package is bulky/light.';
      const extraCostRmb = (volWeight - actualKg) * rate * cartons;
      extraEl.innerHTML = 'Extra cost due to volumetric: <span>¥ ' + extraCostRmb.toLocaleString('en-US', {minimumFractionDigits:2, maximumFractionDigits:2}) + '  /  $ ' + (extraCostRmb / exchange).toLocaleString('en-US', {minimumFractionDigits:2, maximumFractionDigits:2}) + '</span>';
      extraEl.style.display = 'block';
    } else if (actualKg > volWeight) {
      verdictEl.className = 'freight-verdict actual';
      verdictEl.textContent = 'Actual weight applies — package is dense.';
      extraEl.style.display = 'none';
    } else {
      verdictEl.className = 'freight-verdict equal';
      verdictEl.textContent = 'Weights are equal — no volumetric surcharge.';
      extraEl.style.display = 'none';
    }

    // Method comparison — 5-column table + results panel. When
    // cartons is 0 (carton specs missing) every cell renders "—"
    // instead of "0.00 kg / $ 0.00", which would mislead the
    // operator into thinking the freight quote was successfully
    // computed and just happened to be zero.
    [
      { key: 'slow',      div: 6000, r: freightMethodRates.slow },
      { key: 'fast',      div: 6000, r: freightMethodRates.fast },
      { key: 'airupp',    div: 5000, r: freightMethodRates.airupp },
      { key: 'directair', div: 5000, r: freightMethodRates.directair },
    ].forEach(m => {
      const vw = volume / m.div;
      const cw = Math.max(actualKg, vw) * cartons;  // total chargeable kg
      const cr = cw * m.r;
      const cu = cr / exchange;
      const haveData = cartons > 0 && cw > 0;
      const combinedVal = haveData
        ? ('¥ ' + cr.toLocaleString('en-US', {minimumFractionDigits:2, maximumFractionDigits:2}) + '  /  $ ' + cu.toLocaleString('en-US', {minimumFractionDigits:2, maximumFractionDigits:2}))
        : '—';
      // 5-column breakdown table
      const wtEl  = document.getElementById('freight-wt-'  + m.key);
      const rmbEl = document.getElementById('freight-rmb-' + m.key);
      const usdEl = document.getElementById('freight-usd-' + m.key);
      if (wtEl)  wtEl.textContent  = haveData ? (cw.toFixed(2) + ' kg') : '—';
      if (rmbEl) rmbEl.textContent = haveData ? ('¥ ' + cr.toLocaleString('en-US', {minimumFractionDigits:2, maximumFractionDigits:2})) : '—';
      if (usdEl) usdEl.textContent = haveData ? ('$ ' + cu.toLocaleString('en-US', {minimumFractionDigits:2, maximumFractionDigits:2})) : '—';
      // Results panel comparison
      const resEl = document.getElementById('freight-res-' + m.key);
      if (resEl) resEl.textContent = combinedVal;
    });

    const cbm = volume / 1000000;
    document.getElementById('freight-cmp-sea').textContent = (cbm * cartons).toFixed(2) + ' CBM';
  }

  /* ── Quote & Invoice Calcs ───────────────────────────────────────────────── */
  function calcQuoteTotal() {
    const qty = parseFloat(document.getElementById('quote-cl-qty')?.value) || 0;
    const unit = parseFloat(document.getElementById('quote-cl-unit-price')?.value) || 0;
    const shipping = parseFloat(document.getElementById('quote-cl-shipping')?.value) || 0;
    const total = (qty * unit) + shipping;
    document.getElementById('quote-cl-total').value = total > 0 ? '$' + total.toLocaleString('en-US', {minimumFractionDigits:2, maximumFractionDigits:2}) : '';
  }

  function emailQuote() {
    const client = document.getElementById('quote-client-name').value || 'Client';
    const product = document.getElementById('quote-product-name').value || 'Product';
    const quoteDate = document.getElementById('quote-date').value || '';
    const validUntil = document.getElementById('quote-valid-until').value || '';
    const qty = document.getElementById('quote-cl-qty').value || '';
    const unitPrice = document.getElementById('quote-cl-unit-price').value || '';
    const shipping = document.getElementById('quote-cl-shipping').value || '';
    const total = document.getElementById('quote-cl-total').value || '';
    const notes = document.getElementById('quote-cl-notes').value || '';

    const subject = encodeURIComponent(`Quote for ${product} - ${client}`);
    const body = encodeURIComponent(
      `Hi ${client},\n\nWe have finalized your quote for the following product. We are ready to move forward, let us know when you would like to meet and discuss.\n\nProduct: ${product}\nQuantity: ${qty}\nUnit Price: $${unitPrice}\nShipping: $${shipping}\n\nTOTAL: ${total}\n\nThanks,\nMarket Sculpt`
    );
    window.location.href = `mailto:?subject=${subject}&body=${body}`;
  }

  function calcInvoiceTotal() {
    const qty = parseFloat(document.getElementById('inv-qty')?.value) || 0;
    const unit = parseFloat(document.getElementById('inv-unit-price')?.value) || 0;
    const shipping = parseFloat(document.getElementById('inv-shipping')?.value) || 0;
    const subtotal = qty * unit;
    const total = subtotal + shipping;
    document.getElementById('inv-subtotal').value = subtotal > 0 ? '$' + subtotal.toLocaleString('en-US', {minimumFractionDigits:2, maximumFractionDigits:2}) : '';
    document.getElementById('inv-total').value = total > 0 ? '$' + total.toLocaleString('en-US', {minimumFractionDigits:2, maximumFractionDigits:2}) : '';
  }

  function fillQuoteInvoice(clientName, productName) {
    document.getElementById('quote-client-name').value = clientName || '';
    document.getElementById('quote-product-name').value = productName || '';
    document.getElementById('inv-bill-to').value = clientName || '';
    document.getElementById('inv-product').value = productName || '';
  }

  /* ── New Workbook Modal ──────────────────────────────────────────────────── */
  /* ── New Workbook category suggestions ─────────────────────────────────── */
  const CATEGORY_KEYWORDS = {
    packaging:      ['bag','bags','pouch','pouches','box','boxes','container','bottle','jar','jars','wrap','tube','tubes','sachet','envelope','mailer','packaging','package','zipper','mylar','poly bag','stand-up','flat pack'],
    apparel:        ['shirt','tee','t-shirt','hoodie','jacket','pants','dress','hat','cap','sock','socks','clothing','wear','uniform','jersey','sweater','shorts','leggings','polo','vest','gloves','scarf','beanie'],
    furniture:      ['chair','table','desk','shelf','shelving','cabinet','sofa','bench','wardrobe','drawer','stool','rack','stand','bookcase','ottoman','furniture'],
    electronics:    ['speaker','headphone','headphones','charger','cable','case','earbuds','led','battery','wireless','bluetooth','electronic','device','adapter','hub','power bank','watch','camera'],
    promotional:    ['pen','pens','mug','mugs','keychain','lanyard','badge','award','promo','promotional','giveaway','branded','merchandise','swag','corporate gift','logo'],
    'food-beverage':['food','beverage','drink','snack','coffee','water bottle','lunch box','meal','bento','thermos','flask','cutlery','utensil','edible','food-grade'],
    toys:           ['toy','toys','game','puzzle','doll','plush','stuffed animal','play','kids','children','baby','infant','educational','building blocks','action figure','fidget'],
    beauty:         ['cream','serum','lotion','makeup','cosmetic','cosmetics','brush','skincare','haircare','perfume','beauty','lipstick','foundation','mascara','nail','spa','facial','moisturizer'],
    'home-garden':  ['candle','vase','pillow','cushion','towel','mat','rug','plant','garden','kitchen','home decor','decoration','frame','clock','curtain','coaster','tray','basket','planter'],
    sports:         ['gym','fitness','yoga','sport','sports','workout','outdoor','camping','hiking','exercise','training','athletic','running','cycling','swim','ball','racket','resistance band'],
    stationery:     ['notebook','notepad','pencil','planner','journal','calendar','sticky','clipboard','folder','binder','stationery','office','school supply','marker','highlighter','agenda']
  };

  const CATEGORY_LABELS = {
    packaging:'Packaging', apparel:'Apparel', furniture:'Furniture',
    electronics:'Electronics', promotional:'Promotional', 'food-beverage':'Food & Beverage',
    toys:'Toys & Games', beauty:'Beauty', 'home-garden':'Home & Garden',
    sports:'Sports & Outdoor', stationery:'Stationery'
  };

  let _modalSuggestedCat = null;
  let _modalSuggestedSub = null;
  let _suggestTimer = null;
  let _pendingWorkbookCategory = null; // applied after navigation to new workbook

  function debounceSuggestCategories() {
    clearTimeout(_suggestTimer);
    _suggestTimer = setTimeout(renderWorkbookSuggestions, 300);
  }

  function scoreSuggestions() {
    const name = (document.getElementById('modal-product')?.value || '').toLowerCase();
    const desc = (document.getElementById('modal-desc')?.value || '').toLowerCase();
    const text = name + ' ' + desc;
    if (text.trim().length < 4) return [];
    const scores = {};
    Object.entries(CATEGORY_KEYWORDS).forEach(([cat, keywords]) => {
      let score = 0;
      keywords.forEach(kw => { if (text.includes(kw)) score += kw.includes(' ') ? 2 : 1; });
      if (score > 0) scores[cat] = score;
    });
    return Object.entries(scores).sort((a, b) => b[1] - a[1]).map(([cat]) => cat);
  }

  function suggestSubs(cats) {
    const name = (document.getElementById('modal-product')?.value || '').toLowerCase();
    const desc = (document.getElementById('modal-desc')?.value || '').toLowerCase();
    const text = name + ' ' + desc;
    const seen = new Set();
    const result = [];
    cats.slice(0, 2).forEach(cat => {
      (SUBCATEGORIES[cat] || []).forEach(sub => {
        const key = sub.toLowerCase();
        const firstWord = key.split(/[\s(]/)[0];
        if (!seen.has(sub) && (text.includes(firstWord) || text.includes(key))) {
          seen.add(sub);
          result.push(sub);
        }
      });
    });
    return result.slice(0, 4);
  }

  function renderWorkbookSuggestions() {
    const area = document.getElementById('modal-suggest-area');
    if (!area) return;
    const cats = scoreSuggestions();
    if (cats.length === 0) { area.innerHTML = ''; return; }
    const subs = suggestSubs(cats);
    const chip = (label, selected, onclick) =>
      `<button type="button" onclick="${onclick}"
        style="padding:4px 12px; border-radius:20px; font-size:12px; font-weight:600; cursor:pointer; transition:all 0.15s; font-family:inherit;
        ${selected
          ? 'background:var(--accent); color:#fff; border:1px solid var(--accent);'
          : 'background:var(--surface2); color:var(--text); border:1px solid var(--border);'}">${label}</button>`;
    let html = `<div style="padding:10px 12px; background:var(--surface2); border:1px solid var(--border); border-radius:var(--radius-sm);">
      <div style="font-size:10px; font-weight:700; text-transform:uppercase; letter-spacing:0.07em; color:var(--text-muted); margin-bottom:6px;">✦ Suggested Category</div>
      <div style="display:flex; flex-wrap:wrap; gap:6px; margin-bottom:${subs.length ? '10px' : '0'};">`;
    cats.slice(0, 3).forEach(cat => {
      html += chip(CATEGORY_LABELS[cat] || cat, _modalSuggestedCat === cat, `selectModalCat('${cat}')`);
    });
    html += `</div>`;
    if (subs.length) {
      html += `<div style="font-size:10px; font-weight:700; text-transform:uppercase; letter-spacing:0.07em; color:var(--text-muted); margin-bottom:6px;">Material Type</div>
        <div style="display:flex; flex-wrap:wrap; gap:6px;">`;
      subs.forEach(sub => {
        html += chip(sub, _modalSuggestedSub === sub, `selectModalSub('${sub.replace(/'/g,"\\'")}')`)
      });
      html += `</div>`;
    }
    html += `</div>`;
    area.innerHTML = html;
  }

  function selectModalCat(cat) {
    _modalSuggestedCat = _modalSuggestedCat === cat ? null : cat;
    renderWorkbookSuggestions();
  }

  function selectModalSub(sub) {
    _modalSuggestedSub = _modalSuggestedSub === sub ? null : sub;
    renderWorkbookSuggestions();
  }

  function openNewWorkbookModal() {
    document.getElementById('new-workbook-form').reset();

    const sel = document.getElementById('modal-client');
    const dropdownField = document.getElementById('modal-client-field');
    const displayField  = document.getElementById('modal-client-display');
    const displayLabel  = document.getElementById('modal-client-label');

    // Populate dropdown from live client list
    sel.innerHTML = '<option value="">Select a client…</option>';
    Object.keys(clientData).sort().forEach(name => {
      const opt = document.createElement('option');
      opt.value = name;
      opt.textContent = name;
      sel.appendChild(opt);
    });

    // Resolve the client context from the URL, not the `currentClient`
    // global. `currentClient` only updates when opening a workbook detail —
    // it stays stale when the user navigates between client dashboards, which
    // would prefill the modal with the wrong client.
    const ctxClient = (() => {
      const m = location.hash.match(/^#\/client\/([^/]+)/);
      if (m) return decodeURIComponent(m[1]);
      return currentClient || '';
    })();

    if (ctxClient && clientData[ctxClient]) {
      // Already on a client — pre-fill and hide the dropdown
      sel.value = ctxClient;
      sel.required = false;
      dropdownField.style.display = 'none';
      displayField.style.display  = '';
      displayLabel.textContent    = ctxClient;
    } else {
      // No client context — show the dropdown
      sel.required = true;
      dropdownField.style.display = '';
      displayField.style.display  = 'none';
    }

    // Reset suggestions
    _modalSuggestedCat = null;
    _modalSuggestedSub = null;
    document.getElementById('modal-suggest-area').innerHTML = '';

    document.getElementById('modal-overlay').classList.add('open');
    setTimeout(() => document.getElementById('modal-product').focus(), 50);
  }

  function closeModal() {
    document.getElementById('modal-overlay').classList.remove('open');
  }

  async function createWorkbook(e) {
    e.preventDefault();
    const product = document.getElementById('modal-product').value.trim();
    const desc    = document.getElementById('modal-desc').value.trim();

    // Resolve client from the dropdown when visible, otherwise from the
    // pinned client context (modal-client-label) — when the operator
    // opens this modal from a client dashboard, the dropdown is hidden
    // and `modal-client.value` could be empty even though the modal
    // header shows the client name. Fall back to the displayed label
    // so we never silent-fail on the "create from client view" path.
    const dropdownEl = document.getElementById('modal-client');
    const labelEl    = document.getElementById('modal-client-label');
    let client = (dropdownEl?.value || '').trim();
    if (!client) client = (labelEl?.textContent || '').trim();
    if (!client) {
      // Last-ditch: pull from URL hash so the function never silently
      // exits without telling the operator what's wrong.
      const m = location.hash.match(/^#\/client\/([^/]+)/);
      if (m) { try { client = decodeURIComponent(m[1]); } catch(e) { client = m[1]; } }
    }

    // Validate — but ALERT instead of silent-returning so the operator
    // sees what's missing. The previous silent-return is exactly why
    // "Night Lights" looked like it didn't save: dropdown was hidden,
    // value was empty, function exited with no UI feedback.
    if (!product) { alert('Product name is required.'); return; }
    if (!client)  { alert('Pick a client first (or open this from a client dashboard).'); return; }
    if (!desc)    { alert('Description is required.'); return; }

    // Disable the submit button to prevent double-clicks while the API
    // call is in flight. Re-enable on any failure path.
    const submitBtn = e.target.querySelector('button[type="submit"]');
    if (submitBtn) { submitBtn.disabled = true; submitBtn.textContent = 'Creating…'; }
    const _restoreBtn = () => { if (submitBtn) { submitBtn.disabled = false; submitBtn.textContent = 'Create Workbook'; } };

    // Save to DB
    const clientId = dbClientMap[client];
    let newId;
    if (clientId) {
      try {
        // allow_duplicate:true — user explicitly created this from the UI.
        // The server-side dedup guard is intended to block seed-retry
        // loops, not legitimate user creations.
        // Seed palletMaxHeight from the user's localStorage default
        // (set the last time they changed it on any workbook). This is
        // the ONLY place the localStorage seed flows in — opening an
        // existing workbook never reads it. Lets a recent "47" default
        // apply to new workbooks without rewriting old ones.
        const _palletSeed = (typeof getPalletMaxHeightSeed === 'function') ? getPalletMaxHeightSeed() : null;
        const _newWbDetail = _palletSeed ? { palletMaxHeight: _palletSeed } : {};
        const result = await apiCall('add_workbook', {
          client_id: clientId,
          product_name: product,
          description: desc,
          allow_duplicate: true,
          detail: _newWbDetail
        });
        if (result && result.success) {
          newId = parseInt(result.id);
        } else {
          alert('Could not create workbook: ' + ((result && result.error) || 'unknown error'));
          _restoreBtn();
          return;
        }
      } catch (err) {
        alert('Could not create workbook: ' + (err && err.message ? err.message : 'network error'));
        _restoreBtn();
        return;
      }
    } else {
      // No clientId in dbClientMap means the client hasn't been synced
      // to the DB yet. Tell the operator instead of silently creating
      // a local-only workbook that won't persist past a refresh.
      alert(`Client "${client}" hasn't been synced to the database yet. Save the client (re-open the client dashboard) and try again.`);
      _restoreBtn();
      return;
    }

    // Add to local data
    const items = clientData[client] || [];
    const today = new Date();
    const dateStr = today.getDate() + ' ' + today.toLocaleString('en-US', { month: 'short' }) + ' ' + String(today.getFullYear()).slice(2);

    items.push({
      id: newId,
      product: product,
      description: desc,
      dateCreated: dateStr,
      dateSubmitted: '',
      flow: { prepChina: true, chinaSubmits: false, shippingDims: false, quoteClient: false, clientApproved: false, officeInvoice: false, confirmedPayment: false, orderChina: false }
    });

    clientData[client] = items;
    dbWorkbookMap[`${client}|${newId}`] = newId;
    saveToLocalStorage();

    // Store any suggested category to apply after navigation
    if (_modalSuggestedCat || _modalSuggestedSub) {
      _pendingWorkbookCategory = { cat: _modalSuggestedCat, sub: _modalSuggestedSub };
    }

    closeModal();
    _restoreBtn();

    // Toast confirmation, then jump to the new workbook so the operator
    // lands directly on the editable surface.
    if (typeof _msToast === 'function') {
      _msToast(`"${product}" created — opening workbook…`, 'success');
    }
    location.hash = `#/client/${encodeURIComponent(client)}/workbook/${newId}`;
  }

  /* ── Add Client Modal ───────────────────────────────────────────────────── */
  function openAddClientModal() {
    document.getElementById('add-client-form').reset();
    // Reset shipping textarea state in case checkbox was left checked
    const shipTa = document.getElementById('modal-client-shipping');
    if (shipTa) { shipTa.disabled = false; shipTa.style.opacity = ''; }
    document.getElementById('client-modal-overlay').classList.add('open');
    setTimeout(() => document.getElementById('modal-client-name').focus(), 50);
  }

  function closeClientModal() {
    document.getElementById('client-modal-overlay').classList.remove('open');
  }

  async function createClient(e) {
    e.preventDefault();
    const name    = document.getElementById('modal-client-name').value.trim();
    const contact = document.getElementById('modal-client-contact').value.trim();
    const email   = document.getElementById('modal-client-email').value.trim();
    const phone   = document.getElementById('modal-client-phone').value.trim();
    const billing = document.getElementById('modal-client-billing').value.trim();
    const sameChk = document.getElementById('modal-ship-same');
    const shipping= sameChk && sameChk.checked ? billing : document.getElementById('modal-client-shipping').value.trim();
    const am      = (document.getElementById('modal-client-am')?.value || '').trim();
    const sp      = (document.getElementById('modal-client-sp')?.value || '').trim();
    if (!name) return;

    // Check if client already exists
    if (clientData[name]) {
      alert('Client "' + name + '" already exists.');
      return;
    }

    // ── Populate local state immediately so the UI renders right away ──
    clientData[name] = [];
    clientDetails[name] = { id: null, email, phone, primary_contact: contact, email2: '', phone2: '', primary_contact2: '', billing_address: billing, shipping_address: shipping, notes: '', account_manager: am, salesperson: sp, operations_person: '', account_manager_pct: '', salesperson_pct: '', operations_pct: '', default_margin_pct: '' };
    rebuildSidebar(); // handles nav items (with avatar/star/delete) + modal dropdown

    // ── Close modal and navigate immediately — user sees the page now ──
    closeClientModal();
    location.hash = `#/client/${encodeURIComponent(name)}`;

    // ── Save to DB and show toast ──
    const result = await apiCall('add_client', { name, account_manager: am, salesperson: sp });
    const s = document.getElementById('save-status');
    if (result.success) {
      dbClientMap[name] = result.id;
      clientDetails[name].id = result.id;
      if (contact || email || phone || billing || shipping) {
        await apiCall('save_client_detail', { id: result.id, email, phone, primary_contact: contact, billing_address: billing, shipping_address: shipping, notes: '' });
      }
      if (s) { s.textContent = `✓ Client "${name}" created`; s.style.color = 'var(--success)'; s.style.opacity = '1'; setTimeout(() => { s.style.opacity = '0'; s.textContent = ''; }, 3500); }
    } else {
      const errMsg = result.error || 'Unknown error';
      if (s) { s.textContent = `⚠ ${errMsg}`; s.style.color = 'var(--danger)'; s.style.opacity = '1'; setTimeout(() => { s.style.opacity = '0'; s.textContent = ''; }, 5000); }
      // If the client already exists in the DB (e.g. from a previous attempt),
      // try to recover by reloading from DB so it shows up properly
      if (errMsg.toLowerCase().includes('already exists')) {
        await loadFromDatabase();
        rebuildSidebar();
        updateSidebarActive(name);
      }
    }

    saveToLocalStorage();
  }

  /* ── Delete Workbook Modal ─────────────────────────────────────────────── */
  let pendingDelete = null;

  async function duplicateWorkbook(clientName, workbookId) {
    document.querySelectorAll('.action-menu.open').forEach(m => m.classList.remove('open'));
    const dbId = dbWorkbookMap[`${clientName}|${workbookId}`] || workbookId;
    // Get source product name and detail
    const srcItem = (clientData[clientName] || []).find(i => i.id === parseInt(workbookId));
    const srcName = srcItem ? srcItem.product + ' (Copy)' : 'Workbook (Copy)';
    const srcDetail = workbookDetail[`${clientName}|${workbookId}`] || {};
    const srcQty       = srcDetail.quoteClQty       || '';
    const srcUnitPrice = srcDetail.quoteClUnitPrice  || '';
    const srcCost      = srcDetail.quoteClShipping   || '';
    const _q = parseFloat(srcQty) || 0;
    const _u = parseFloat(srcUnitPrice) || 0;
    const _s = parseFloat(srcCost) || 0;
    const srcTotal = (_q * _u + _s) > 0
      ? '$' + (_q * _u + _s).toLocaleString('en-US', {minimumFractionDigits:2, maximumFractionDigits:2})
      : '—';

    // Build client options
    const clientOptions = Object.keys(clientData).sort().map(n =>
      `<option value="${n.replace(/"/g,'&quot;')}"${n === clientName ? ' selected' : ''}>${n}</option>`
    ).join('');

    // Show modal
    let modal = document.getElementById('duplicate-modal');
    if (modal) modal.remove();
    modal = document.createElement('div');
    modal.id = 'duplicate-modal';
    modal.className = 'modal-overlay';
    modal.style.cssText = 'display:flex;';
    modal.innerHTML = `
      <div class="modal" style="max-width:460px; width:100%;">
        <div style="display:flex; align-items:flex-start; justify-content:space-between; margin-bottom:18px;">
          <h3 style="margin:0; font-size:18px; font-weight:700;">Duplicate Workbook</h3>
          <button onclick="document.getElementById('duplicate-modal').remove()" style="background:none;border:none;font-size:22px;line-height:1;cursor:pointer;color:var(--text-muted);padding:0;margin:-2px -2px 0 0;">&times;</button>
        </div>
        <div class="modal-body" style="display:flex;flex-direction:column;gap:14px;">
          <div id="dup-error" style="display:none;background:rgba(251,113,133,0.12);border:1px solid rgba(251,113,133,0.35);color:#fb7185;border-radius:8px;padding:8px 12px;font-size:13px;"></div>
          <div>
            <label style="font-size:11px;font-weight:600;text-transform:uppercase;letter-spacing:0.05em;color:var(--text-muted);display:block;margin-bottom:4px;">Client</label>
            <select id="dup-client" class="form-input" style="width:100%;" autocomplete="off">${clientOptions}</select>
          </div>
          <div>
            <label style="font-size:11px;font-weight:600;text-transform:uppercase;letter-spacing:0.05em;color:var(--text-muted);display:block;margin-bottom:4px;">Product Name</label>
            <input id="dup-name" type="text" class="form-input" style="width:100%;" placeholder="${srcName.replace(/"/g,'&quot;')}" autocomplete="off" />
          </div>
          <div style="border:1px solid var(--border);border-radius:var(--radius);overflow:hidden;">
            <div style="display:grid;grid-template-columns:1fr 1fr;">
              <div style="padding:12px 16px;border-right:1px solid var(--border);border-bottom:1px solid var(--border);">
                <div style="font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:0.06em;color:var(--text-muted);margin-bottom:5px;">Quantity</div>
                <div id="dup-qty" style="font-size:15px;color:var(--text);">${srcQty || '—'}</div>
              </div>
              <div style="padding:12px 16px;border-bottom:1px solid var(--border);">
                <div style="font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:0.06em;color:var(--text-muted);margin-bottom:5px;">Unit Price (USD)</div>
                <div style="font-size:15px;color:var(--text);">${srcUnitPrice ? '$' + srcUnitPrice : '—'}</div>
              </div>
              <div style="padding:12px 16px;border-right:1px solid var(--border);">
                <div style="font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:0.06em;color:var(--text-muted);margin-bottom:5px;">Shipping Cost (USD)</div>
                <div id="dup-cost" style="font-size:15px;color:var(--text);">${srcCost ? '$' + srcCost : '—'}</div>
              </div>
              <div style="padding:12px 16px;">
                <div style="font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:0.06em;color:var(--text-muted);margin-bottom:5px;">Total Quote (USD)</div>
                <div style="font-size:16px;font-weight:700;color:var(--text);">${srcTotal}</div>
              </div>
            </div>
          </div>
          <button class="btn btn-primary" onclick="confirmDuplicate('${clientName.replace(/'/g,"\\'")}', ${dbId})">Create Workbook</button>
        </div>
      </div>`;
    document.body.appendChild(modal);
    setTimeout(() => document.getElementById('dup-name')?.focus(), 50);
  }

  async function confirmDuplicate(originalClient, srcDbId) {
    const newClient = document.getElementById('dup-client').value;
    const nameEl    = document.getElementById('dup-name');
    const newName   = nameEl.value.trim() || nameEl.placeholder;
    const qty       = document.getElementById('dup-qty').textContent.replace('—','').trim();
    const cost      = document.getElementById('dup-cost').textContent.replace('$','').replace('—','').trim();
    const errEl     = document.getElementById('dup-error');
    errEl.style.display = 'none';
    if (!newName) { errEl.textContent = 'Product name is required.'; errEl.style.display = 'block'; return; }

    // Create duplicate with flow reset to 0
    const r = await apiCall('duplicate_workbook', { id: srcDbId, target_client: newClient, product_name: newName, qty, cost });
    if (!r.success) { errEl.textContent = r.error || 'Duplicate failed.'; errEl.style.display = 'block'; return; }

    document.getElementById('duplicate-modal').remove();
    await loadFromDatabase();
    rebuildSidebar();
    location.hash = `#/client/${encodeURIComponent(newClient)}/workbook/${r.id}`;
  }

  function openDeleteModal(clientName, workbookId, productName) {
    document.querySelectorAll('.action-menu.open').forEach(m => m.classList.remove('open'));
    document.getElementById('delete-product-name').textContent = productName;
    pendingDelete = { clientName, workbookId };
    document.getElementById('delete-modal-overlay').classList.add('open');
  }

  function closeDeleteModal() {
    document.getElementById('delete-modal-overlay').classList.remove('open');
    pendingDelete = null;
  }

  document.getElementById('confirm-delete-btn').addEventListener('click', async function() {
    if (!pendingDelete) return;
    const { clientName, workbookId } = pendingDelete;

    // Call API to delete
    try {
      const dbId = dbWorkbookMap[`${clientName}|${workbookId}`] || workbookId;
      await apiCall('delete_workbook', { id: dbId });
    } catch (e) {
      console.log('API delete failed, removing locally:', e);
    }

    // Remove from clientData
    if (clientData[clientName]) {
      clientData[clientName] = clientData[clientName].filter(item => String(item.id) !== String(workbookId));
    }

    // Remove from workbookDetail
    delete workbookDetail[`${clientName}|${workbookId}`];
    delete dbWorkbookMap[`${clientName}|${workbookId}`];

    saveToLocalStorage();
    closeDeleteModal();

    // Re-render current view
    const hash = location.hash;
    if (hash.startsWith('#/client/') && !hash.includes('/workbook/')) {
      renderDashboard(clientName);
    } else {
      renderRecentWorkbooks();
      showView('view-home');
    }
  });

  /* ── Delete Client Modal ──────────────────────────────────────────────── */
  let pendingClientDelete = null;

  function openDeleteClientModal(clientName) {
    document.getElementById('delete-client-name').textContent = clientName;
    pendingClientDelete = clientName;
    document.getElementById('delete-client-modal-overlay').classList.add('open');
  }

  function closeDeleteClientModal() {
    document.getElementById('delete-client-modal-overlay').classList.remove('open');
    pendingClientDelete = null;
  }

  document.getElementById('confirm-delete-client-btn').addEventListener('click', async function() {
    if (!pendingClientDelete) return;
    const clientName = pendingClientDelete;

    // Delete all workbooks for this client from API
    try {
      const items = clientData[clientName] || [];
      for (const item of items) {
        const dbId = dbWorkbookMap[`${clientName}|${item.id}`] || item.id;
        await apiCall('delete_workbook', { id: dbId });
      }
      // Delete the client itself
      const clientDbId = dbClientMap[clientName];
      if (clientDbId) {
        await apiCall('delete_client', { id: clientDbId });
      }
    } catch (e) {
      console.log('API client delete failed, removing locally:', e);
    }

    // Remove from local data
    const items = clientData[clientName] || [];
    items.forEach(item => {
      delete workbookDetail[`${clientName}|${item.id}`];
      delete dbWorkbookMap[`${clientName}|${item.id}`];
    });
    delete clientData[clientName];
    delete dbClientMap[clientName];

    saveToLocalStorage();
    closeDeleteClientModal();
    rebuildSidebar();

    // Navigate to home
    location.hash = '';
    renderRecentWorkbooks();
    showView('view-home');
  });

  /* ── History Modal ──────────────────────────────────────────────────────── */
  const FIELD_LABELS = {
    client:'Client', product:'Product', desc:'Description', productCategory:'Category', productSubcategory:'Material Type',
    dimInL:'Length', dimInW:'Width', dimInH:'Height',
    materials:'Materials', pantone:'Pantone', cmyk:'CMYK', colorNotes:'Color Notes',
    rfqItems:'RFQ Line Items', qcNotes:'Quote Notes',
    cartonUnitWeight:'Unit Weight', cartonInnerWeight:'Inner Carton Weight', cartonInnerCount:'Inner Carton Qty',
    cartonOuterWeight:'Outer Carton Weight', cartonOuterCount:'Outer Carton Qty',
    freightMode:'Shipping Method', freightHsCode:'HS Code',
    quoteDate:'Quote Date', quoteValidUntil:'Valid Until', quoteClQty:'Quote Qty',
    quoteClUnitPrice:'Quote Unit Price', quoteClShipping:'Quote Shipping', quoteClNotes:'Quote Notes',
    invNumber:'Invoice #', invDate:'Invoice Date', invDueDate:'Due Date',
    invQty:'Invoice Qty', invUnitPrice:'Invoice Unit Price', invShipping:'Invoice Shipping',
    invStatus:'Payment Status', invMethod:'Payment Method', invNotes:'Invoice Notes',
    artStatus:'Art Status', artDueDate:'Art Due Date', artNotes:'Art Notes'
  };

  let _historyRevisions = []; // store fetched revisions for diff comparison

  function openHistoryModal() {
    const overlay = document.getElementById('history-modal-overlay');
    overlay.style.display = 'flex';
    const list = document.getElementById('history-list');
    if (!currentWorkbookId) {
      list.innerHTML = '<p style="color:var(--text-muted); text-align:center; padding:20px;">Open a workbook to view its revision history.</p>';
      return;
    }
    list.innerHTML = '<p style="color:var(--text-muted); text-align:center;">Loading...</p>';

    const dbId = dbWorkbookMap[`${currentClient}|${currentWorkbookId}`] || currentWorkbookId;
    fetch(`api.php?action=get_revisions&workbook_id=${dbId}`)
      .then(r => r.json())
      .then(data => {
        if (!data.success || !data.data.length) {
          list.innerHTML = '<p style="color:var(--text-muted); text-align:center; padding:20px;">No revision history yet. Changes are tracked automatically as you edit.</p>';
          return;
        }
        _historyRevisions = data.data;
        list.innerHTML = data.data.map((rev, idx) => {
          const summary = (rev.summary || []).slice(0, 6).map(s =>
            `<span style="display:inline-block; background:var(--surface2); border-radius:4px; padding:2px 6px; font-size:10px; color:var(--text-muted); margin:2px 2px 0 0;">${s.field}: ${s.value.length > 20 ? s.value.substring(0, 20) + '…' : s.value}</span>`
          ).join('');
          const moreCount = (rev.summary || []).length - 6;
          const moreTag = moreCount > 0 ? `<span style="font-size:10px; color:var(--text-muted);">+${moreCount} more</span>` : '';
          return `
          <div style="padding:10px 0; border-bottom:1px solid var(--border);">
            <div style="display:flex; justify-content:space-between; align-items:flex-start;">
              <div style="flex:1; min-width:0;">
                <div style="font-size:13px; font-weight:600;">${new Date(rev.created_at).toLocaleString()}</div>
                <div style="font-size:11px; color:var(--text-muted); margin-bottom:4px;">${rev.changed_by || 'Unknown user'}</div>
                <div style="line-height:1.6;">${summary}${moreTag}</div>
                <button class="diff-toggle" onclick="toggleDiff(${rev.id}, ${idx})">&#9654; View Changes</button>
                <div class="diff-panel" id="diff-panel-${rev.id}"><p style="color:var(--text-muted);font-size:11px;">Loading...</p></div>
              </div>
              <button class="btn-back-step" onclick="restoreRevision(${rev.id}, ${rev.workbook_id})" title="Restore this version" style="font-size:11px; width:auto; padding:4px 10px; flex-shrink:0; margin-left:8px;">Restore</button>
            </div>
          </div>`;
        }).join('');
      })
      .catch(() => {
        list.innerHTML = '<p style="color:var(--text-muted); text-align:center;">Failed to load history.</p>';
      });
  }

  async function toggleDiff(revId, idx) {
    const panel = document.getElementById(`diff-panel-${revId}`);
    if (panel.classList.contains('open')) {
      panel.classList.remove('open');
      return;
    }
    panel.classList.add('open');
    panel.innerHTML = '<p style="color:var(--text-muted);font-size:11px;">Loading...</p>';

    try {
      // This revision (the OLD version — what was saved before the change)
      const oldRes = await fetch(`api.php?action=get_revision_detail&revision_id=${revId}`).then(r => r.json());
      const oldDetail = oldRes.data?.detail || {};

      // The NEWER version: previous revision in the list (idx-1), or current workbook data
      let newDetail;
      if (idx === 0) {
        // Most recent revision — compare against current live data
        const key = `${currentClient}|${currentWorkbookId}`;
        newDetail = workbookDetail[key] || {};
      } else {
        const newerRevId = _historyRevisions[idx - 1].id;
        const newRes = await fetch(`api.php?action=get_revision_detail&revision_id=${newerRevId}`).then(r => r.json());
        newDetail = newRes.data?.detail || {};
      }

      const diffs = buildDiff(oldDetail, newDetail);
      if (diffs.length === 0) {
        panel.innerHTML = '<p style="color:var(--text-muted);font-size:11px;">No changes detected.</p>';
      } else {
        panel.innerHTML = diffs.map(d => `
          <div class="diff-row">
            <span class="diff-label">${d.label}</span>
            <span><span class="diff-old">${escHtml(d.old || '—')}</span> <span class="diff-arrow">&rarr;</span> <span class="diff-new">${escHtml(d.new || '—')}</span></span>
          </div>
        `).join('');
      }
    } catch (e) {
      panel.innerHTML = '<p style="color:#c0392b;font-size:11px;">Failed to load diff.</p>';
    }
  }

  function buildDiff(oldD, newD) {
    const diffs = [];
    const allKeys = new Set([...Object.keys(oldD), ...Object.keys(newD)]);

    for (const key of allKeys) {
      if (key === 'productImage' || key === 'productImages' || key === 'artImages') {
        if (key === 'productImages') {
          const oldImgs = Array.isArray(oldD.productImages) ? oldD.productImages.length : 0;
          const newImgs = Array.isArray(newD.productImages) ? newD.productImages.length : 0;
          if (oldImgs !== newImgs) {
            diffs.push({ label: 'Product Images', old: oldImgs + ' image(s)', new: newImgs + ' image(s)' });
          }
        }
        if (key === 'artImages') {
          const oldArt = Array.isArray(oldD.artImages) ? oldD.artImages.length : 0;
          const newArt = Array.isArray(newD.artImages) ? newD.artImages.length : 0;
          if (oldArt !== newArt) {
            diffs.push({ label: 'Art Files', old: oldArt + ' file(s)', new: newArt + ' file(s)' });
          }
        }
        continue;
      }
      if (key === 'tiers') {
        const oldTiers = Array.isArray(oldD.tiers) ? oldD.tiers : [];
        const newTiers = Array.isArray(newD.tiers) ? newD.tiers : [];
        const maxLen = Math.max(oldTiers.length, newTiers.length);
        for (let i = 0; i < maxLen; i++) {
          const oq = oldTiers[i]?.qty?.toString() || '';
          const nq = newTiers[i]?.qty?.toString() || '';
          const op = oldTiers[i]?.price?.toString() || '';
          const np = newTiers[i]?.price?.toString() || '';
          if (oq !== nq) diffs.push({ label: `Tier ${i+1} Qty`, old: oq, new: nq });
          if (op !== np) diffs.push({ label: `Tier ${i+1} Price`, old: op, new: np });
        }
        continue;
      }
      const oldVal = (oldD[key] || '').toString();
      const newVal = (newD[key] || '').toString();
      if (oldVal !== newVal) {
        diffs.push({ label: FIELD_LABELS[key] || key, old: oldVal, new: newVal });
      }
    }
    return diffs;
  }

  function escHtml(str) {
    const div = document.createElement('div');
    div.textContent = str;
    return div.innerHTML;
  }

  // ── User Management modal ────────────────────────────────────────────
  // The modal hosts two views — list and per-user detail. _usersCache is
  // the last server response so the detail view can render synchronously
  // after a row click; refreshed every time the list view is shown so
  // edits made elsewhere don't go stale.
  let _usersCache = [];
  let _userDetailCurrent = null; // currently-selected user object in detail view

  // Show/hide toggle for password inputs. Stored bcrypt hashes can't be
  // reversed so we can't reveal an existing password — this only flips
  // the input type so the operator can verify what they just typed in
  // a new-password field. Mirrors the login.php toggle exactly so the
  // eye icons feel identical across pages: same 15px SVGs, same path,
  // same display attribute swap pattern.
  function togglePasswordField(btn) {
    const wrap = btn.closest('.pw-wrap');
    if (!wrap) return;
    const input = wrap.querySelector('input');
    if (!input) return;
    const wasHidden = (input.type === 'password');
    input.type = wasHidden ? 'text' : 'password';
    const showEye = btn.querySelector('.eye-show');
    const hideEye = btn.querySelector('.eye-hide');
    if (showEye) showEye.style.display = wasHidden ? 'none' : 'block';
    if (hideEye) hideEye.style.display = wasHidden ? 'block' : 'none';
    btn.setAttribute('aria-label', wasHidden ? 'Hide password' : 'Show password');
  }

  function openUsersModal() {
    document.getElementById('users-modal-overlay').style.display = 'flex';
    showUsersList();
  }
  function closeUsersModal() {
    document.getElementById('users-modal-overlay').style.display = 'none';
  }

  // Swap to the list pane. Re-fetches so newly-added/edited rows appear.
  function showUsersList() {
    document.getElementById('users-list-view').style.display = '';
    document.getElementById('users-detail-view').style.display = 'none';
    document.getElementById('users-back-btn').style.display = 'none';
    document.getElementById('users-title-text').textContent = 'User Management';
    _userDetailCurrent = null;
    loadUsers();
  }

  // Swap to the detail pane for the user with the given id. Pulls from
  // _usersCache (populated by loadUsers) so the click → render hop is
  // instant and we don't blink a Loading… state for data we already have.
  function showUserDetail(id) {
    const u = _usersCache.find(x => x.id === id);
    if (!u) { showUsersList(); return; }
    _userDetailCurrent = u;
    document.getElementById('users-list-view').style.display = 'none';
    document.getElementById('users-detail-view').style.display = '';
    document.getElementById('users-back-btn').style.display = '';
    document.getElementById('users-title-text').textContent = u.display_name || u.username;
    renderUserDetail();
  }

  function loadUsers() {
    const list = document.getElementById('users-list');
    list.innerHTML = '<p style="color:var(--text-muted); font-size:13px;">Loading…</p>';
    apiCall('get_users').then(data => {
      if (!data.success) { list.innerHTML = '<p style="color:var(--danger);">Failed to load users.</p>'; return; }
      _usersCache = data.data || [];
      if (!_usersCache.length) { list.innerHTML = '<p style="color:var(--text-muted);">No users yet.</p>'; return; }
      const sessionId = (window.MS_SESSION && window.MS_SESSION.id);
      list.innerHTML = `
        <div style="font-size:13px; font-weight:600; margin-bottom:8px;">Current Users</div>
        ${_usersCache.map(u => `
          <div onclick="showUserDetail(${u.id})" style="display:flex; align-items:center; gap:8px; padding:10px 8px; border-bottom:1px solid var(--border); cursor:pointer; border-radius:4px;" onmouseover="this.style.background='var(--surface2)'" onmouseout="this.style.background='transparent'">
            <span style="flex:1; font-size:13px;">
              ${escHtml(u.display_name || u.username)}
              <span style="color:var(--text-muted); font-size:11px;"> (${escHtml(u.username)})</span>
              ${u.email ? `<div style="color:var(--text-muted); font-size:11px; margin-top:2px;">${escHtml(u.email)}</div>` : ''}
            </span>
            <span style="font-size:11px; background:var(--surface2); padding:2px 8px; border-radius:4px; color:${u.role==='admin'?'var(--accent)':'var(--text-muted)'};">${u.role}</span>
            <span style="color:var(--text-muted); font-size:14px;">›</span>
          </div>`).join('')}`;
    });
  }

  // Render the per-user detail pane. Pulls from _userDetailCurrent — set
  // by showUserDetail so we don't have to refetch on every keystroke
  // (each input writes back into _userDetailCurrent on blur via Save).
  function renderUserDetail() {
    const u = _userDetailCurrent;
    if (!u) return;
    const sessionId = (window.MS_SESSION && window.MS_SESSION.id);
    const isSelf = (u.id === sessionId);
    const created  = u.created_at ? new Date(u.created_at).toLocaleDateString() : '—';
    const lastSeen = u.last_login ? new Date(u.last_login).toLocaleString()      : 'Never';
    const body = document.getElementById('users-detail-body');
    body.innerHTML = `
      <!-- Profile fields. Username is read-only after creation; touching
           it would orphan login attempts. Role is locked when editing
           your own row so an admin can't accidentally demote themselves. -->
      <div style="display:grid; grid-template-columns:1fr; gap:12px; margin-bottom:18px;">
        <div>
          <label style="font-size:12px; font-weight:600; color:var(--text-muted); display:block; margin-bottom:4px;">Username</label>
          <input type="text" value="${escHtml(u.username)}" class="field-input" style="font-size:13px; background:var(--surface2); color:var(--text-muted);" readonly />
        </div>
        <div>
          <label style="font-size:12px; font-weight:600; color:var(--text-muted); display:block; margin-bottom:4px;">Display Name</label>
          <input id="udetail-display" type="text" value="${escHtml(u.display_name || '')}" class="field-input" style="font-size:13px;" />
        </div>
        <div>
          <label style="font-size:12px; font-weight:600; color:var(--text-muted); display:block; margin-bottom:4px;">Email</label>
          <input id="udetail-email" type="email" value="${escHtml(u.email || '')}" placeholder="user@example.com" class="field-input" style="font-size:13px;" />
        </div>
        <!-- Phone (E.164) — used by the milestone-watcher SMS pipeline.
             Optional; SMS is skipped when blank. Light front-end hint
             ("+18885551234") to nudge users toward the right format,
             but the server normalizes/validates on save. -->
        <div>
          <label style="font-size:12px; font-weight:600; color:var(--text-muted); display:block; margin-bottom:4px;">Phone <span style="font-weight:400; font-style:italic;">(for milestone SMS)</span></label>
          <input id="udetail-phone" type="tel" value="${escHtml(u.phone || '')}" placeholder="+18885551234" class="field-input" style="font-size:13px;" />
          <div style="font-size:11px; color:var(--text-muted); margin-top:4px;">Include country code, e.g. <code>+1</code> for US/Canada. Leave blank to skip SMS for this user.</div>
        </div>
        <div>
          <label style="font-size:12px; font-weight:600; color:var(--text-muted); display:block; margin-bottom:4px;">Role${isSelf ? ' <span style="font-weight:400; font-style:italic;">(can&#39;t change your own role)</span>' : ''}</label>
          <span class="ship-select-wrap" style="display:block;">
            <select id="udetail-role" class="field-input" style="font-size:13px; appearance:none; -webkit-appearance:none; -moz-appearance:none; padding-right:32px; cursor:pointer; width:100%;" ${isSelf ? 'disabled' : ''}>
              <option value="user"  ${u.role==='user'  ? 'selected' : ''}>User</option>
              <option value="admin" ${u.role==='admin' ? 'selected' : ''}>Admin</option>
            </select>
          </span>
        </div>
        <!-- Commission %: applies globally across all clients where this
             user is assigned to the Operations role. Blank = role default
             (10%). Replaces the per-client commission input that used to
             live next to Operations on Client Details. -->
        <div>
          <label style="font-size:12px; font-weight:600; color:var(--text-muted); display:block; margin-bottom:4px;">Commission %</label>
          <div style="position:relative;">
            <input id="udetail-commission" type="number" step="0.01" min="0" max="100"
                   value="${u.commission_pct === null || u.commission_pct === undefined || u.commission_pct === '' ? '' : String(parseFloat(u.commission_pct))}"
                   placeholder="10"
                   class="field-input" style="font-size:13px; padding-right:24px; font-variant-numeric:tabular-nums;" />
            <span style="position:absolute; right:9px; top:50%; transform:translateY(-50%); font-size:12px; color:var(--text-muted); pointer-events:none;">%</span>
          </div>
          <div style="font-size:11px; color:var(--text-muted); margin-top:4px;">Default 10% — applies to every client this user is assigned to.</div>
        </div>
      </div>

      <!-- Read-only meta — quick context for who this user actually is. -->
      <div style="font-size:11px; color:var(--text-muted); margin-bottom:18px; display:flex; gap:16px; flex-wrap:wrap;">
        <span>Created: ${created}</span>
        <span>Last login: ${lastSeen}</span>
      </div>

      <!-- Save button for the profile fields above. Password is its own
           section below so a typo in display name doesn't reset the
           password input mid-edit. -->
      <div style="display:flex; gap:8px; margin-bottom:24px;">
        <button class="btn-create" onclick="saveUserDetail()" style="font-size:13px; padding:8px 16px;">Save Changes</button>
        <button class="btn-cancel" onclick="showUsersList()" style="font-size:13px; padding:8px 16px;">Cancel</button>
      </div>

      <!-- Change password — separate form, separate save. Cleared after
           a successful update so the new value doesn't linger in the DOM.
           Each input gets an eyeball toggle (togglePasswordField) so the
           operator can verify what they typed before clicking Update. -->
      <div style="border-top:1px solid var(--border); padding-top:16px; margin-bottom:24px;">
        <div style="font-size:13px; font-weight:600; margin-bottom:10px;">Change Password</div>
        <div style="display:grid; grid-template-columns:1fr 1fr; gap:8px; margin-bottom:10px;">
          <span class="pw-wrap" style="display:block; position:relative;">
            <input id="udetail-newpw" type="password" placeholder="New password" class="field-input" style="font-size:13px; width:100%; padding-right:36px;"
              autocomplete="new-password" data-1p-ignore="true" data-lpignore="true" data-form-type="other" />
            <button type="button" onclick="togglePasswordField(this)" aria-label="Toggle password visibility" style="position:absolute; right:10px; top:50%; transform:translateY(-50%); background:none; border:none; cursor:pointer; color:#9ba3c0; padding:2px; line-height:0; display:flex; align-items:center;">
              <svg class="eye-show" xmlns="http://www.w3.org/2000/svg" width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" display="block"><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/></svg>
              <svg class="eye-hide" xmlns="http://www.w3.org/2000/svg" width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" display="none"><path d="M17.94 17.94A10.07 10.07 0 0 1 12 20c-7 0-11-8-11-8a18.45 18.45 0 0 1 5.06-5.94M9.9 4.24A9.12 9.12 0 0 1 12 4c7 0 11 8 11 8a18.5 18.5 0 0 1-2.16 3.19"/><line x1="1" y1="1" x2="23" y2="23"/></svg>
            </button>
          </span>
          <span class="pw-wrap" style="display:block; position:relative;">
            <input id="udetail-newpw-conf" type="password" placeholder="Confirm password" class="field-input" style="font-size:13px; width:100%; padding-right:36px;"
              autocomplete="new-password" data-1p-ignore="true" data-lpignore="true" data-form-type="other" />
            <button type="button" onclick="togglePasswordField(this)" aria-label="Toggle password visibility" style="position:absolute; right:10px; top:50%; transform:translateY(-50%); background:none; border:none; cursor:pointer; color:#9ba3c0; padding:2px; line-height:0; display:flex; align-items:center;">
              <svg class="eye-show" xmlns="http://www.w3.org/2000/svg" width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" display="block"><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/></svg>
              <svg class="eye-hide" xmlns="http://www.w3.org/2000/svg" width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" display="none"><path d="M17.94 17.94A10.07 10.07 0 0 1 12 20c-7 0-11-8-11-8a18.45 18.45 0 0 1 5.06-5.94M9.9 4.24A9.12 9.12 0 0 1 12 4c7 0 11 8 11 8a18.5 18.5 0 0 1-2.16 3.19"/><line x1="1" y1="1" x2="23" y2="23"/></svg>
            </button>
          </span>
        </div>
        <button class="btn-create" onclick="saveUserPassword()" style="font-size:13px; padding:8px 16px;">Update Password</button>
      </div>

      ${isSelf ? '' : `
        <!-- Delete user — admin-only operation, hidden when viewing own
             row (the API blocks self-delete anyway, but no point showing
             the button if it can't fire). -->
        <div style="border-top:1px solid var(--border); padding-top:16px;">
          <div style="font-size:13px; font-weight:600; color:var(--danger); margin-bottom:8px;">Danger Zone</div>
          <button class="btn-danger" onclick="deleteUser(${u.id})" style="font-size:13px; padding:8px 16px;">Delete User</button>
        </div>
      `}
    `;
  }

  // Persist display_name / email / role for the detail-pane user. Role
  // change is sent only when not editing self; the API enforces this too
  // but we mirror the rule client-side so we don't send obvious no-ops.
  function saveUserDetail() {
    const u = _userDetailCurrent;
    if (!u) return;
    const sessionId = (window.MS_SESSION && window.MS_SESSION.id);
    const payload = {
      id: u.id,
      display_name: document.getElementById('udetail-display').value.trim(),
      email:        document.getElementById('udetail-email').value.trim(),
      phone:        (document.getElementById('udetail-phone')?.value || '').trim(),
      // Empty string clears the override (server stores NULL → role default).
      commission_pct: (document.getElementById('udetail-commission')?.value || '').trim()
    };
    if (u.id !== sessionId) {
      payload.role = document.getElementById('udetail-role').value;
    }
    const commissionChanged = String(u.commission_pct ?? '') !== String(payload.commission_pct);
    apiCall('update_user', payload).then(r => {
      if (r.success) {
        // Mutate the cache entry so the list view reflects the change
        // when we navigate back without a refetch round-trip.
        Object.assign(u, payload);
        // Rate change → recompute pending commission rows so existing
        // workbooks pick up the new % (paid rows stay frozen server-side).
        if (commissionChanged) {
          apiCall('recompute_commissions').then(() => {
            if (typeof loadCommissions === 'function') loadCommissions();
          });
        }
        showUsersList();
      } else {
        alert(r.error || 'Failed to update user.');
      }
    });
  }

  function saveUserPassword() {
    const u = _userDetailCurrent;
    if (!u) return;
    const pw1 = document.getElementById('udetail-newpw').value;
    const pw2 = document.getElementById('udetail-newpw-conf').value;
    if (!pw1)            { alert('Enter a new password.'); return; }
    if (pw1.length < 6)  { alert('Password must be at least 6 characters.'); return; }
    if (pw1 !== pw2)     { alert('Passwords do not match.'); return; }
    apiCall('change_password', { user_id: u.id, new_password: pw1 }).then(r => {
      if (r.success) {
        document.getElementById('udetail-newpw').value      = '';
        document.getElementById('udetail-newpw-conf').value = '';
        alert('Password updated.');
      } else {
        alert(r.error || 'Failed to update password.');
      }
    });
  }

  function addUser() {
    const username = document.getElementById('new-user-username').value.trim();
    const display  = document.getElementById('new-user-display').value.trim();
    const email    = document.getElementById('new-user-email').value.trim();
    const password = document.getElementById('new-user-password').value;
    const role     = document.getElementById('new-user-role').value;
    if (!username || !password) { alert('Username and password are required.'); return; }
    apiCall('add_user', { username, display_name: display || username, email, password, role }).then(r => {
      if (r.success) {
        document.getElementById('new-user-username').value = '';
        document.getElementById('new-user-display').value  = '';
        document.getElementById('new-user-email').value    = '';
        document.getElementById('new-user-password').value = '';
        loadUsers();
      } else { alert(r.error || 'Failed to add user.'); }
    });
  }

  function deleteUser(id) {
    if (!confirm('Delete this user?')) return;
    apiCall('delete_user', { id }).then(r => {
      if (r.success) showUsersList();
      else alert(r.error || 'Failed to delete user.');
    });
  }

  function closeHistoryModal() {
    document.getElementById('history-modal-overlay').style.display = 'none';
  }

  async function restoreRevision(revisionId, workbookId) {
    if (!confirm('Restore this version? Your current data will be saved as a revision before restoring.')) return;
    try {
      await apiCall('restore_revision', { revision_id: revisionId, workbook_id: workbookId, changed_by: '' });
      closeHistoryModal();
      // Reload the workbook data
      await loadFromDatabase();
      router();
    } catch (e) {
      alert('Failed to restore revision.');
    }
  }

  /* ── Archive Modal ─────────────────────────────────────────────────────── */
  let archiveData = { workbooks: [], clients: [] };
  let archiveTab = 'workbooks';

  function openArchiveModal() {
    const overlay = document.getElementById('archive-modal-overlay');
    overlay.style.display = 'flex';
    archiveTab = 'workbooks';
    loadArchiveData();
  }

  function closeArchiveModal() {
    document.getElementById('archive-modal-overlay').style.display = 'none';
  }

  function switchArchiveTab(tab, btn) {
    archiveTab = tab;
    document.querySelectorAll('.archive-tab').forEach(t => t.classList.remove('active'));
    btn.classList.add('active');
    renderArchiveList();
  }

  async function loadArchiveData() {
    const list = document.getElementById('archive-list');
    list.innerHTML = '<p style="color:var(--text-muted); text-align:center;">Loading...</p>';
    try {
      const res = await fetch('api.php?action=get_archived');
      const data = await res.json();
      if (data.success) {
        archiveData = data;
        renderArchiveList();
      }
    } catch (e) {
      list.innerHTML = '<p style="color:var(--text-muted); text-align:center;">Failed to load archive.</p>';
    }
  }

  function renderArchiveList() {
    const list = document.getElementById('archive-list');
    const items = archiveTab === 'workbooks' ? archiveData.workbooks : archiveData.clients;

    if (!items || !items.length) {
      list.innerHTML = '<p style="color:var(--text-muted); text-align:center; padding:20px;">No archived items.</p>';
      return;
    }

    const actionStyle = 'background:none; border:none; cursor:pointer; font-size:12px; font-weight:600; font-family:inherit; padding:0;';

    if (archiveTab === 'workbooks') {
      list.innerHTML = items.map(wb => `
        <div class="archive-item">
          <div style="flex:1; min-width:0;">
            <div style="font-size:13px; font-weight:600; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;">${wb.product_name}</div>
            <div style="font-size:11px; color:var(--text-muted); margin-top:2px;">${wb.client_name} &middot; Deleted ${new Date(wb.deleted_at).toLocaleDateString()}${wb.deleted_by ? ' by ' + wb.deleted_by : ''}</div>
          </div>
          <div style="display:flex; gap:14px; flex-shrink:0; margin-left:16px;">
            <button onclick="restoreArchivedWorkbook(${wb.id})" style="${actionStyle} color:var(--success);" title="Restore workbook">Restore</button>
            <button onclick="permanentDeleteWorkbook(${wb.id})" style="${actionStyle} color:var(--danger);" title="Permanently delete">Delete</button>
          </div>
        </div>
      `).join('');
    } else {
      list.innerHTML = items.map(cl => `
        <div class="archive-item">
          <div style="flex:1; min-width:0;">
            <div style="font-size:13px; font-weight:600;">${cl.name}</div>
            <div style="font-size:11px; color:var(--text-muted); margin-top:2px;">Deleted ${new Date(cl.deleted_at).toLocaleDateString()}${cl.deleted_by ? ' by ' + cl.deleted_by : ''}</div>
          </div>
          <div style="display:flex; gap:14px; flex-shrink:0; margin-left:16px;">
            <button onclick="restoreArchivedClient(${cl.id})" style="${actionStyle} color:var(--success);" title="Restore client">Restore</button>
            <button onclick="permanentDeleteClient(${cl.id})" style="${actionStyle} color:var(--danger);" title="Permanently delete">Delete</button>
          </div>
        </div>
      `).join('');
    }
  }

  async function restoreArchivedWorkbook(id) {
    if (!confirm('Restore this workbook?')) return;
    try {
      await apiCall('restore_workbook', { id });
      await loadFromDatabase();
      rebuildSidebar();
      loadArchiveData();
    } catch (e) {
      alert('Failed to restore workbook.');
    }
  }

  async function restoreArchivedClient(id) {
    if (!confirm('Restore this client and all its workbooks?')) return;
    try {
      await apiCall('restore_client', { id });
      await loadFromDatabase();
      rebuildSidebar();
      renderRecentWorkbooks();
      loadArchiveData();
    } catch (e) {
      alert('Failed to restore client.');
    }
  }

  async function permanentDeleteWorkbook(id) {
    if (!confirm('Permanently delete this workbook? This cannot be undone.')) return;
    try {
      await apiCall('permanent_delete_workbook', { id });
      loadArchiveData();
    } catch (e) {
      alert('Failed to delete workbook.');
    }
  }

  async function permanentDeleteClient(id) {
    if (!confirm('Permanently delete this client and ALL its workbooks? This cannot be undone.')) return;
    try {
      await apiCall('permanent_delete_client', { id });
      loadArchiveData();
    } catch (e) {
      alert('Failed to delete client.');
    }
  }

  /* ── Router ─────────────────────────────────────────────────────────────── */
  function showView(viewId) {
    document.querySelectorAll('.view').forEach(v => v.classList.remove('active'));
    document.getElementById(viewId).classList.add('active');
  }

  function updateSidebarActive(clientName) {
    document.querySelectorAll('.sidebar-nav .nav-item').forEach(a => {
      const nameSpan = a.querySelector('span');
      const name = nameSpan ? nameSpan.textContent.trim() : a.textContent.trim();
      a.classList.toggle('active', name === clientName);
    });

    // If the active client lives inside a collapsed section, expand it so it's visible
    ['nav-section-clients', 'nav-section-starred'].forEach(sectionId => {
      const section = document.getElementById(sectionId);
      if (!section || !section.classList.contains('collapsed')) return;
      const body = section.querySelector('.nav-section-body');
      if (body && body.querySelector('.nav-item.active')) {
        section.classList.remove('collapsed');
        // Persist the expanded state
        const saved = JSON.parse(localStorage.getItem('ms_nav_collapsed') || '{}');
        saved[sectionId] = false;
        localStorage.setItem('ms_nav_collapsed', JSON.stringify(saved));
      }
    });
  }

  /* ── Action Menu ──────────────────────────────────────────────────────────── */
  function toggleActionMenu(btn) {
    const menu = btn.nextElementSibling;
    const wasOpen = menu.classList.contains('open');
    // Close all menus first
    document.querySelectorAll('.action-menu.open').forEach(m => {
      m.classList.remove('open');
      m.style.top = '';
      m.style.right = '';
    });
    if (!wasOpen) {
      const rect = btn.getBoundingClientRect();
      menu.classList.add('open');
      const menuH = menu.offsetHeight;
      // Flip upward if menu would overflow viewport bottom
      if (rect.bottom + 4 + menuH > window.innerHeight) {
        menu.style.top = (rect.top - menuH - 4) + 'px';
      } else {
        menu.style.top = (rect.bottom + 4) + 'px';
      }
      menu.style.right = (window.innerWidth - rect.right) + 'px';
    }
  }

  document.addEventListener('click', () => {
    document.querySelectorAll('.action-menu.open').forEach(m => m.classList.remove('open'));
  });

  function isFlowComplete(flow) {
    return flowSteps.every(s => flow[s]);
  }

  function shortDate(dateStr) {
    const months = {Jan:1,Feb:2,Mar:3,Apr:4,May:5,Jun:6,Jul:7,Aug:8,Sep:9,Oct:10,Nov:11,Dec:12};
    const parts = dateStr.split(' ');
    return months[parts[1]] + '/' + parseInt(parts[0]);
  }

  function getCurrentStepName(flow) {
    if (isFlowComplete(flow)) return 'Complete';
    for (let i = flowSteps.length - 1; i >= 0; i--) {
      if (flow[flowSteps[i]]) return flowLabelsShort[i];
    }
    return 'Not Started';
  }

  /* ── Client Default Margin Modal ─────────────────────────────────────────
     Tracks the in-flight client name on a module-scope variable so the Save /
     Reset / Cancel buttons don't have to round-trip the value through DOM
     attributes. closeModal() clears it. */
  let _marginModalClient = null;

  /* ── Clear-section modal (Product Dimensions / Inner Carton / Outer Carton).
     Tracks which column to wipe; modal Cancel keeps everything untouched. */
  const _CLEAR_SECTION_FIELDS = {
    product: {
      label: 'Product Dimensions',
      inputs: ['dim-cm-l','dim-in-l','dim-cm-w','dim-in-w','dim-cm-h','dim-in-h',
               'dim-weight-kg','dim-weight-lbs','dim-packaging']
    },
    inner: {
      label: 'Inner Carton',
      inputs: ['carton-inner-l-cm','carton-inner-l-in','carton-inner-w-cm','carton-inner-w-in',
               'carton-inner-h-cm','carton-inner-h-in','carton-inner-weight','carton-inner-weight-lbs',
               'carton-inner-count','carton-inner-row','carton-inner-side','carton-inner-stack'],
      // Single-wall by default for inner cartons
      selects: { 'carton-inner-wall': '1' }
    },
    outer: {
      label: 'Outer Carton',
      inputs: ['carton-outer-l-cm','carton-outer-l-in','carton-outer-w-cm','carton-outer-w-in',
               'carton-outer-h-cm','carton-outer-h-in','carton-outer-weight','carton-outer-weight-lbs',
               'carton-outer-count','carton-outer-units','carton-outer-row','carton-outer-side','carton-outer-stack'],
      // Double-wall by default for outer/shipping cartons
      selects: { 'carton-outer-wall': '2' }
    }
  };
  let _clearSectionTarget = null;

  function openClearSectionModal(section) {
    if (!_CLEAR_SECTION_FIELDS[section]) return;
    _clearSectionTarget = section;
    const label = _CLEAR_SECTION_FIELDS[section].label;
    const n1 = document.getElementById('clear-section-name');
    const n2 = document.getElementById('clear-section-name-2');
    if (n1) n1.textContent = label;
    if (n2) n2.textContent = label;
    document.getElementById('clear-section-modal')?.classList.add('open');
  }
  function closeClearSectionModal() {
    _clearSectionTarget = null;
    document.getElementById('clear-section-modal')?.classList.remove('open');
  }
  function confirmClearSection() {
    const target = _clearSectionTarget;
    const cfg = target && _CLEAR_SECTION_FIELDS[target];
    if (!cfg) return closeClearSectionModal();
    cfg.inputs.forEach(id => {
      const el = document.getElementById(id);
      if (el) el.value = '';
    });
    if (cfg.selects) {
      Object.entries(cfg.selects).forEach(([id, val]) => {
        const el = document.getElementById(id);
        if (el) el.value = val;
      });
    }
    // Hide auto badges + arrangement hints that reference the cleared section
    if (target === 'inner') {
      const b = document.getElementById('inner-calc-badge'); if (b) b.style.display = 'none';
      const h = document.getElementById('inner-arrange-hint'); if (h) h.style.display = 'none';
    } else if (target === 'outer') {
      const b = document.getElementById('outer-calc-badge'); if (b) b.style.display = 'none';
      const h = document.getElementById('outer-arrange-hint'); if (h) h.style.display = 'none';
    }
    // Re-run downstream calcs so dependent fields (and the pricing tab cache)
    // settle on the cleared state, then autosave.
    try { autoCalcCartons(); } catch(e) {}
    try { updateOuterWeightHint(); } catch(e) {}
    try { renderPalletViz(); } catch(e) {}
    if (!_filling) autoSaveWorkbook();
    closeClearSectionModal();
  }

  function openClientMarginModal(encodedName) {
    const clientName = decodeURIComponent(encodedName);
    _marginModalClient = clientName;
    const d = clientDetails[clientName] || {};
    const cur = d.default_margin_pct;
    const input = document.getElementById('client-margin-input');
    const nameEl = document.getElementById('client-margin-name');
    if (nameEl) nameEl.textContent = clientName;
    // Show current saved value, or 50% placeholder when blank/unset.
    if (input) {
      input.value = (cur === '' || cur === null || cur === undefined) ? '' : cur;
      input.placeholder = '50';
    }
    const overlay = document.getElementById('client-margin-modal');
    if (overlay) overlay.classList.add('open');
    setTimeout(() => input?.focus(), 50);
  }
  function closeClientMarginModal() {
    _marginModalClient = null;
    document.getElementById('client-margin-modal')?.classList.remove('open');
  }
  function resetClientMarginToDefault() {
    const input = document.getElementById('client-margin-input');
    if (input) { input.value = ''; input.focus(); }
  }
  function saveClientMarginModal() {
    const clientName = _marginModalClient;
    if (!clientName) return closeClientMarginModal();
    const input = document.getElementById('client-margin-input');
    let raw = (input?.value || '').trim();
    // Empty = reset to default. Otherwise validate the number and clamp to
    // sensible bounds so a typo can't poison the column.
    let stored;
    if (raw === '') {
      stored = '';
    } else {
      const num = parseFloat(raw);
      if (isNaN(num) || num < 0) {
        input?.focus();
        return;
      }
      stored = Math.min(num, 999.99).toFixed(2);
    }
    if (!clientDetails[clientName]) clientDetails[clientName] = {};
    clientDetails[clientName].default_margin_pct = stored;
    saveClientDetail(clientName);
    // Re-render the card so the avatar badge picks up the new value.
    if (typeof renderClientDetailCard === 'function') renderClientDetailCard(clientName);
    closeClientMarginModal();
  }

  function onClientDetailChange(el, encodedName, key) {
    const clientName = decodeURIComponent(encodedName);
    if (!clientDetails[clientName]) clientDetails[clientName] = {};
    clientDetails[clientName][key] = el.value;
    saveClientDetail(clientName);
    // AM/SP/Operations assignment OR rate change → recompute commissions
    // so the dashboard reflects the new ownership/rate without a page
    // reload. Fire-and-forget; recompute is idempotent and UPSERTs
    // pending rows.
    if (key === 'account_manager'     || key === 'salesperson'     || key === 'operations_person' ||
        key === 'account_manager_pct' || key === 'salesperson_pct' || key === 'operations_pct') {
      apiCall('recompute_commissions').then(() => {
        if (typeof loadCommissions === 'function') loadCommissions();
      }).catch(() => {});
    }
  }

  let _clientDetailSaveTimer = null;
  function saveClientDetail(clientName) {
    clearTimeout(_clientDetailSaveTimer);
    _clientDetailSaveTimer = setTimeout(async () => {
      const d = clientDetails[clientName];
      if (!d || !d.id) return;
      await apiCall('save_client_detail', {
        id: d.id,
        email: d.email,
        phone: d.phone,
        primary_contact: d.primary_contact,
        email2:           d.email2           || '',
        phone2:           d.phone2           || '',
        primary_contact2: d.primary_contact2 || '',
        billing_address: d.billing_address,
        shipping_address: d.shipping_address,
        notes: d.notes,
        account_manager:     d.account_manager     || '',
        salesperson:         d.salesperson         || '',
        operations_person:   d.operations_person   || '',
        // Per-role rate overrides. Empty string → server stores NULL →
        // helper falls back to the role's default (AM/SP → 0%,
        // Operations → 5%). "0" stays a real zero (no commission).
        account_manager_pct: (d.account_manager_pct === undefined || d.account_manager_pct === null) ? '' : d.account_manager_pct,
        salesperson_pct:     (d.salesperson_pct     === undefined || d.salesperson_pct     === null) ? '' : d.salesperson_pct,
        operations_pct:      (d.operations_pct      === undefined || d.operations_pct      === null) ? '' : d.operations_pct,
        // Per-client default profit margin (%). Empty string → server stores
        // NULL → UI falls back to 50%. "0" stays a real zero.
        default_margin_pct:  (d.default_margin_pct  === undefined || d.default_margin_pct  === null) ? '' : d.default_margin_pct
      });
    }, 800);
  }

  function renderClientDetailCard(clientName) {
    const wrap = document.getElementById('client-detail-card-wrap');
    if (!wrap) return;
    const d = clientDetails[clientName] || {};
    const items = clientData[clientName] || [];
    const total = items.length;
    const completed = items.filter(i => isFlowComplete(i.flow)).length;
    const open = total - completed;

    // ── Financial totals ────────────────────────────────────────────────
    // Open Orders / Closed Orders: pulled from the Order system.
    // An order "belongs" to this client if order.clientName matches OR any
    // entry's clientName matches. Use orderTotals() for the USD value.
    let openOrdersUsd = 0, closedOrdersUsd = 0;
    let openOrderCount = 0, closedOrderCount = 0;
    Object.values(orderData || {}).forEach(order => {
      const belongsHere = order.clientName === clientName ||
        (order.entries || []).some(e => e.clientName === clientName);
      if (!belongsHere) return;
      const tot = orderTotals(order).totalUsd;
      if (order.status === 'complete') {
        closedOrdersUsd += tot;
        closedOrderCount++;
      } else {
        openOrdersUsd += tot;
        openOrderCount++;
      }
    });

    // Total Pipeline: ALL open (flow not complete) workbooks for this client.
    // Preferred source: the workbook's cached Total Landed Cost from the
    // Pricing tab (tier qty × weighted-avg landed). Falls back to the legacy
    // tier-based estimate for workbooks that haven't been opened on the
    // Pricing tab yet (so they still contribute SOMETHING).
    let pipelineUsd = 0;
    items.forEach(item => {
      if (isFlowComplete(item.flow)) return;
      const detail = workbookDetail[`${clientName}|${item.id}`] || {};

      const cachedLanded = parseFloat(detail.pricingLandedTotal);
      if (!isNaN(cachedLanded) && cachedLanded > 0) {
        pipelineUsd += cachedLanded;
        return;
      }

      const tiers = Array.isArray(detail.tiers) ? detail.tiers : [];
      const tier = tiers.find(t => t.id == detail.selectedTierIdx) || tiers[0];
      if (tier && parseFloat(tier.price) && parseFloat(tier.qty)) {
        pipelineUsd += (parseFloat(tier.price) / USD_TO_RMB) * parseFloat(tier.qty);
      } else {
        const qty = parseFloat(detail.quoteClQty) || 0;
        const price = parseFloat(detail.quoteClUnitPrice) || 0;
        const ship = parseFloat(detail.quoteClShipping) || 0;
        if (qty && price) pipelineUsd += qty * price + ship;
      }
    });
    pipelineUsd = Math.round(pipelineUsd * 100) / 100;

    const fmtUsd = n => '$' + n.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

    // Initials from client name
    const initials = clientName.split(/\s+/).map(w => w[0]).join('').slice(0, 2).toUpperCase();

    const enc = encodeURIComponent(clientName);
    const field = (key, label, placeholder, isTextarea = false, extraClass = '') => {
      const val = (d[key] || '').replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/</g,'&lt;');
      const handler = `onClientDetailChange(this,'${enc}','${key}')`;
      const cls = `cdc-field${extraClass ? ' ' + extraClass : ''}`;
      if (isTextarea) {
        return `<div class="${cls}">
          <div class="cdc-label">${label}</div>
          <textarea class="cdc-value" rows="2" placeholder="${placeholder}" oninput="${handler}">${val}</textarea>
        </div>`;
      }
      return `<div class="${cls}">
        <div class="cdc-label">${label}</div>
        <input class="cdc-value" type="text" value="${val}" placeholder="${placeholder}" oninput="${handler}" />
      </div>`;
    };
    // Employee dropdown for AM / Salesperson / Operations. Drives commission
    // tracking — when a workbook for this client is promoted, whoever is
    // assigned here gets a commission row written. The neighboring percent
    // input is the per-client commission rate override (blank = use the
    // role's default rate, indicated by the placeholder).
    //
    // `key` selects the role:
    //   'account_manager'   — AM dropdown (Parker / Jackson), default 0%
    //   'salesperson'       — SP dropdown (Parker / Jackson), default 0%
    //   'operations_person' — Operations dropdown (Karen),    default 5%
    const empSelect = (key, label) => {
      const cur    = (d[key] || '').trim();
      // Older sibling fields use `<role>_pct`; the operations field is
      // stored on `operations_person` so we strip the `_person` suffix
      // before tacking on `_pct` (otherwise we'd save into a phantom
      // `operations_person_pct` column).
      const pctKey = (key === 'operations_person' ? 'operations' : key) + '_pct';
      // Read raw value first so 0 (explicit "no commission") survives.
      // Also handle DECIMAL columns which come back as strings like "20.00".
      const pctRaw = d[pctKey];
      const pctVal = (pctRaw === null || pctRaw === undefined || pctRaw === '')
                   ? '' : String(parseFloat(pctRaw));
      // Per-role configuration: the people you can pick + the default rate
      // shown as placeholder when the override is blank. Karen lives alone
      // in the Operations slot for now; the array makes it trivial to
      // grow that list later without changing this helper.
      let people, defaultPct, defaultLabel;
      if (key === 'operations_person') {
        people       = ['Karen'];
        defaultPct   = '5';
        defaultLabel = '5%';
      } else {
        people       = ['Parker Low', 'Jackson Hollberg'];
        defaultPct   = '0';
        defaultLabel = '0% (set manually)';
      }
      const opt        = (v) => `<option value="${v}"${v === cur ? ' selected' : ''}>${v || '— Unassigned —'}</option>`;
      const handler    = `onClientDetailChange(this,'${enc}','${key}')`;
      const pctHandler = `onClientDetailChange(this,'${enc}','${pctKey}')`;
      // Operations rate is now a per-USER setting (Profile → User Management
      // → click the user → Commission %). The per-client override input is
      // hidden for that role; AM/SP still get one.
      const showPctInput = (key !== 'operations_person');
      // Wrap the select in ship-select-wrap so we get the same custom triangle
      // arrow used by every other dropdown in the app. appearance:none on the
      // <select> kills the native arrow so we don't double-up. The % input
      // sits to the right at a fixed 86px so it never crowds the dropdown.
      // Pin both inputs to the same explicit height — without it, browsers
      // give <select> a slightly larger native min-height (even with
      // appearance:none) than a sibling <input>, so they end up looking
      // mismatched. 36px is comfy and matches the cdc-value text padding.
      return `<div class="cdc-field">
        <div class="cdc-label">${label}</div>
        <div style="display:flex; gap:6px; align-items:center;">
          <span class="ship-select-wrap" style="display:block; flex:1; min-width:0;">
            <select class="cdc-value" onchange="${handler}"
              style="appearance:none; -webkit-appearance:none; -moz-appearance:none; padding-right:28px; cursor:pointer; height:36px; line-height:1.2; box-sizing:border-box;">
              ${opt('')}
              ${people.map(opt).join('')}
            </select>
          </span>
          ${showPctInput ? `
          <div style="position:relative; width:86px; flex-shrink:0; height:36px;"
               title="Commission rate for this role on this client. Leave blank to use the role default (${defaultLabel}).">
            <input class="cdc-value" type="number" step="0.01" min="0" max="100"
              value="${pctVal}" placeholder="${defaultPct}"
              oninput="${pctHandler}"
              style="padding-right:22px; text-align:right; font-variant-numeric:tabular-nums; height:36px; line-height:1.2; box-sizing:border-box;" />
            <span style="position:absolute; right:9px; top:50%; transform:translateY(-50%);
                         font-size:12px; color:var(--text-muted); pointer-events:none;">%</span>
          </div>
          ` : ''}
        </div>
      </div>`;
    };

    // Margin %: NULL/blank = use 50% default, anything else = the saved value.
    // Badge shows whole-percent integer ("50") to keep the pill compact.
    const marginRaw = (d.default_margin_pct === '' || d.default_margin_pct === null || d.default_margin_pct === undefined) ? 50 : parseFloat(d.default_margin_pct);
    const marginPct = isNaN(marginRaw) ? 50 : marginRaw;
    const marginBadge = Math.round(marginPct);

    wrap.innerHTML = `
      <div class="client-detail-card">
        <div class="cdc-avatar">
          ${initials}
          <span class="cdc-avatar-margin-badge" title="Default profit margin: ${marginPct}%">${marginBadge}</span>
        </div>
        <div class="cdc-left">
          <div class="cdc-name">${clientName}</div>
          <div class="cdc-fields">
            ${field('email',            'Email',            'client@example.com')}
            ${field('phone',            'Phone',            '+1 (555) 000-0000')}
            ${field('primary_contact',  'Primary Contact',  'Contact name')}
            ${field('email2',           'Email 2',          'second@example.com')}
            ${field('phone2',           'Phone 2',          '+1 (555) 000-0000')}
            ${field('primary_contact2', 'Contact 2',        'Second contact name')}
            ${empSelect('account_manager',   'Account Manager')}
            ${empSelect('salesperson',       'Salesperson')}
            ${field('notes',           'Notes',            'Internal notes…',                true, 'cdc-field--tall')}
            ${field('shipping_address','Shipping Address', 'Same as billing or different',   true)}
            ${field('billing_address', 'Billing Address',  'Street, City, State ZIP',        true)}
          </div>
        </div>
        <div class="cdc-right-col">
          <!-- Workbook Request button — sends a one-time intake link to
               the client's email on file. Status sub-line + copy link
               are populated async by hydrateIntakeStatus(). -->
          <div class="cdc-rfq-card">
            <button type="button" class="cdc-rfq-btn" id="cdc-rfq-btn" onclick="sendIntakeRequest('${enc}')" title="Email a one-time intake link to ${(d.email || 'the client').replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/</g,'&lt;')}">
              <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M4 12v7a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-7"/><polyline points="16 6 12 2 8 6"/><line x1="12" y1="2" x2="12" y2="15"/></svg>
              Send Workbook Request
            </button>
            <div class="cdc-rfq-status" id="cdc-rfq-status" style="display:none;"></div>
          </div>
          <div class="cdc-financial">
            <div class="cdc-fin-title">
              <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><path d="M12 6v6l4 2"/></svg>
              Financial Summary
              <button type="button" class="cdc-fin-cog" onclick="openClientMarginModal('${enc}')" title="Edit default profit margin">
                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 0 1 0 2.83 2 2 0 0 1-2.83 0l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 0 1-2 2 2 2 0 0 1-2-2v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 0 1-2.83 0 2 2 0 0 1 0-2.83l.06-.06a1.65 1.65 0 0 0 .33-1.82 1.65 1.65 0 0 0-1.51-1H3a2 2 0 0 1-2-2 2 2 0 0 1 2-2h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 0 1 0-2.83 2 2 0 0 1 2.83 0l.06.06a1.65 1.65 0 0 0 1.82.33H9a1.65 1.65 0 0 0 1-1.51V3a2 2 0 0 1 2-2 2 2 0 0 1 2 2v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 0 1 2.83 0 2 2 0 0 1 0 2.83l-.06.06a1.65 1.65 0 0 0-.33 1.82V9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 0 1 2 2 2 2 0 0 1-2 2h-.09a1.65 1.65 0 0 0-1.51 1z"/></svg>
              </button>
            </div>
            <div class="cdc-fin-stat">
              <span class="cdc-fin-stat-label">Open Orders <span style="font-weight:400; opacity:0.7;">(${openOrderCount})</span></span>
              <span class="cdc-fin-stat-value accent">${fmtUsd(openOrdersUsd)}</span>
            </div>
            <div class="cdc-fin-stat">
              <span class="cdc-fin-stat-label">Closed Orders <span style="font-weight:400; opacity:0.7;">(${closedOrderCount})</span></span>
              <span class="cdc-fin-stat-value success">${fmtUsd(closedOrdersUsd)}</span>
            </div>
            <div class="cdc-fin-stat" style="margin-top:6px; padding-top:10px; border-top:1px solid rgba(107,147,255,0.2);">
              <span class="cdc-fin-stat-label">Total Pipeline</span>
              <span class="cdc-fin-stat-value" style="font-size:18px;">${fmtUsd(pipelineUsd)}</span>
            </div>
          </div>
        </div>
      </div>
    `;

    // Async-populate the intake status line ("Pending — sent 3 days ago")
    // without blocking the initial card render.
    hydrateIntakeStatus(clientName);
  }

  // ── Client-portal RFQ intake helpers ─────────────────────────────────
  // Lightweight toast — used by the intake flow for success messages.
  // Auto-dismisses after 3.5s. Tucked bottom-right so it doesn't cover
  // the Client Details card. Idempotent: clobbers any existing toast.
  function _msToast(msg, kind) {
    let el = document.getElementById('ms-toast');
    if (!el) {
      el = document.createElement('div');
      el.id = 'ms-toast';
      el.style.cssText = 'position:fixed;right:24px;bottom:24px;z-index:9999;padding:12px 18px;border-radius:10px;font-size:13px;font-weight:600;color:#fff;box-shadow:0 6px 24px rgba(0,0,0,0.25);font-family:inherit;max-width:360px;line-height:1.5;opacity:0;transform:translateY(8px);transition:opacity 0.2s, transform 0.2s;';
      document.body.appendChild(el);
    }
    el.style.background = kind === 'error' ? '#dc2626' : '#16a34a';
    el.textContent = msg;
    requestAnimationFrame(() => { el.style.opacity = '1'; el.style.transform = 'translateY(0)'; });
    clearTimeout(el._t);
    el._t = setTimeout(() => {
      el.style.opacity = '0';
      el.style.transform = 'translateY(8px)';
    }, 3500);
  }
  function showToast(msg, kind) { _msToast(msg, kind); }

  // sendIntakeRequest: button handler — calls the API to mint a token,
  // email the client, and refresh the status line below the button.
  async function sendIntakeRequest(encName) {
    const clientName = decodeURIComponent(encName);
    const clientId = dbClientMap[clientName];
    if (!clientId) {
      alert('Please save the client first before sending an intake request.');
      return;
    }
    const d = clientDetails[clientName] || {};
    const email = (d.email || '').trim();
    if (!email) {
      alert('No email on file for this client. Add one in Client Details first.');
      return;
    }
    if (!confirm(`Send a workbook request link to ${email}?\n\nThe link is one-time use and expires in 30 days.`)) return;

    const btn = document.getElementById('cdc-rfq-btn');
    if (btn) {
      btn.disabled = true;
      btn.innerHTML = `<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><path d="M12 6v6l4 2"/></svg> Sending…`;
    }

    try {
      const r = await apiCall('create_intake_token', { client_id: clientId });
      if (r && r.success) {
        showToast(`Intake link sent to ${email}.`, 'success');
        hydrateIntakeStatus(clientName);
      } else {
        const err = (r && r.error) || 'Could not send intake link.';
        alert(err);
        if (btn) {
          btn.disabled = false;
          btn.innerHTML = `<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M4 12v7a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-7"/><polyline points="16 6 12 2 8 6"/><line x1="12" y1="2" x2="12" y2="15"/></svg> Send Workbook Request`;
        }
      }
    } catch (e) {
      alert('Could not send intake link. Check your connection and try again.');
      if (btn) {
        btn.disabled = false;
        btn.innerHTML = `<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M4 12v7a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-7"/><polyline points="16 6 12 2 8 6"/><line x1="12" y1="2" x2="12" y2="15"/></svg> Send Workbook Request`;
      }
    }
  }

  // hydrateIntakeStatus: looks up the most recent active intake token for
  // this client and renders a "Pending — sent X days ago" sub-line under
  // the Send button. No-op when no active token exists.
  async function hydrateIntakeStatus(clientName) {
    const clientId = dbClientMap[clientName];
    const statusEl = document.getElementById('cdc-rfq-status');
    if (!clientId || !statusEl) return;
    try {
      const r = await apiCall('list_intake_tokens', { client_id: clientId });
      const tokens = (r && r.data) || [];
      const active = tokens.find(t => t.status === 'active');
      if (!active) {
        statusEl.style.display = 'none';
        statusEl.innerHTML = '';
        return;
      }
      // Compute "X days ago"
      const sent = new Date(active.created_at.replace(' ', 'T') + 'Z');
      const now  = new Date();
      const diffMs = now - sent;
      const diffMin = Math.floor(diffMs / 60000);
      const diffHr  = Math.floor(diffMs / 3600000);
      const diffDay = Math.floor(diffMs / 86400000);
      let when;
      if (diffMin < 2)      when = 'just now';
      else if (diffMin < 60) when = `${diffMin} min ago`;
      else if (diffHr  < 24) when = `${diffHr} hr ago`;
      else if (diffDay === 1) when = 'yesterday';
      else                   when = `${diffDay} days ago`;

      const scheme = location.protocol;
      const host   = location.host;
      const url    = `${scheme}//${host}/intake.php?t=${active.token}`;
      statusEl.style.display = '';
      statusEl.innerHTML =
        `<span><span class="status-dot"></span>Pending — sent ${when} to ${active.client_email || ''}</span>` +
        `<button type="button" class="copy-link" onclick="copyIntakeLink('${active.token}')" title="Copy intake link to clipboard">Copy link</button>`;
    } catch (e) {
      statusEl.style.display = 'none';
    }
  }

  // clearPendingReview: drops the submittedByClient flag from a workbook's
  // detail_json so the "Pending Review" badge disappears. Used after the
  // operator has reviewed/normalized the intake submission.
  async function clearPendingReview(clientName, workbookId) {
    const key = `${clientName}|${workbookId}`;
    const detail = workbookDetail[key] || {};
    if (!detail.submittedByClient) {
      _msToast('This workbook is not flagged Pending Review.', 'error');
      return;
    }
    if (!confirm(`Clear the Pending Review flag on "${detail.product || 'this workbook'}"?`)) return;
    detail.submittedByClient = false;
    detail.pendingReviewClearedAt = new Date().toISOString();
    workbookDetail[key] = detail;

    const dbId = dbWorkbookMap[key] || workbookId;
    try {
      const r = await apiCall('save_workbook_detail', {
        id: dbId, detail: detail, changed_by: getCurrentUser(), create_revision: false
      });
      if (r && r.success) {
        _msToast('Pending Review cleared.', 'success');
        saveToLocalStorage();
        renderDashboard(clientName);
      } else {
        _msToast('Could not save. Try again.', 'error');
      }
    } catch (e) {
      _msToast('Could not save. Check your connection.', 'error');
    }
  }

  // copyIntakeLink: copies the public intake URL for an active token to
  // the clipboard so the operator can resend manually if needed.
  function copyIntakeLink(token) {
    const url = `${location.protocol}//${location.host}/intake.php?t=${token}`;
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(url).then(
        () => showToast('Intake link copied to clipboard.', 'success'),
        () => prompt('Copy this link:', url)
      );
    } else {
      prompt('Copy this link:', url);
    }
  }

  // ════════════════════════════════════════════════════════════════════
  // REPORT BUILDER
  //
  // Three pieces:
  //   1. _MS_REPORTS — registry of prebuilt report definitions. Each
  //      entry knows its filters, columns, and a rows(filters) function
  //      that pulls fresh data from the in-memory globals (clientData,
  //      orderData, shipmentData, commissionsData, workbookDetail).
  //   2. Generic engine (renderReportsList, runReport, _applyReport-
  //      Filters, _renderReportTable) that turns any registry entry
  //      into a working filterable + sortable + exportable view.
  //   3. Saved-views layer (load/save/delete) backed by app_state under
  //      the key ms_saved_reports, so a saved report follows the user
  //      across devices.
  // ════════════════════════════════════════════════════════════════════

  // Active report state — only meaningful while view-reports is showing
  // the run screen. Reset on every runReport() call so leftover sort
  // state from a previous report doesn't leak into the new one.
  let _reportState = null;
  // Saved-reports cache — list of {id, name, basedOn, filters, savedAt}.
  // Loaded once on first reports view; mutated locally + persisted to
  // app_state. dbClientMap-style key is "ms_saved_reports".
  let _msSavedReports = null;
  let _msSavedReportsLoaded = false;

  // Helpers ────────────────────────────────────────────────────────────
  const _RPT_FMT_USD = v => (typeof v === 'number' && !isNaN(v))
    ? '$' + v.toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2})
    : '—';
  const _RPT_FMT_INT = v => (typeof v === 'number' && !isNaN(v))
    ? v.toLocaleString('en-US')
    : (v ?? '—');
  const _RPT_FMT_PCT = v => (typeof v === 'number' && !isNaN(v))
    ? v.toFixed(1) + '%'
    : '—';
  const _RPT_FMT_DATE = v => {
    if (!v) return '—';
    if (typeof v === 'string' && /^\d{4}-\d{2}-\d{2}/.test(v)) {
      // ISO-ish date: render as short "DD MMM YY"
      const d = new Date(v);
      if (isNaN(d.getTime())) return v;
      return d.toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: '2-digit' });
    }
    return String(v);
  };

  function _rptParseAppDate(s) {
    // Parses the app's "DD MMM YY" format used in clientData rows.
    if (!s) return null;
    const months = { Jan:0, Feb:1, Mar:2, Apr:3, May:4, Jun:5, Jul:6, Aug:7, Sep:8, Oct:9, Nov:10, Dec:11 };
    const parts = String(s).trim().split(/\s+/);
    if (parts.length !== 3) return null;
    const dd = parseInt(parts[0]); const mo = months[parts[1]]; const yy = parseInt(parts[2]);
    if (isNaN(dd) || mo == null || isNaN(yy)) return null;
    return new Date(2000 + yy, mo, dd);
  }

  function _rptDaysSince(anchor) {
    if (!anchor) return null;
    const d = anchor instanceof Date ? anchor : (typeof anchor === 'string' ? new Date(anchor.replace(' ', 'T')) : null);
    if (!d || isNaN(d.getTime())) return null;
    return Math.floor((Date.now() - d.getTime()) / 86400000);
  }

  // Compute a workbook's pipeline USD using the same rules as the
  // Client Details Financial Summary card (cached pricingLandedTotal
  // first, fall back to the selected tier, fall back to legacy quote
  // fields). Open-only — closed workbooks contribute 0.
  function _rptPipelineForWorkbook(clientName, item) {
    if (typeof isFlowComplete === 'function' && isFlowComplete(item.flow)) return 0;
    const detail = workbookDetail[`${clientName}|${item.id}`] || {};
    const cachedLanded = parseFloat(detail.pricingLandedTotal);
    if (!isNaN(cachedLanded) && cachedLanded > 0) return cachedLanded;
    const tiers = Array.isArray(detail.tiers) ? detail.tiers : [];
    const tier = tiers.find(t => t.id == detail.selectedTierIdx) || tiers[0];
    if (tier && parseFloat(tier.price) && parseFloat(tier.qty)) {
      return (parseFloat(tier.price) / USD_TO_RMB) * parseFloat(tier.qty);
    }
    const qty   = parseFloat(detail.quoteClQty)       || 0;
    const price = parseFloat(detail.quoteClUnitPrice) || 0;
    const ship  = parseFloat(detail.quoteClShipping)  || 0;
    return qty && price ? qty * price + ship : 0;
  }

  // ── Report registry ────────────────────────────────────────────────
  // Each entry:
  //   id          unique slug
  //   name        display title
  //   description short blurb
  //   icon        inline SVG path string (rendered inside .reports-card-icon)
  //   filters     [{ id, label, type, options? }]  type: 'select' | 'text' | 'days' | 'date'
  //   columns     [{ id, label, sortable?, align?, format?, link?(row) }]
  //               format: 'usd' | 'int' | 'pct' | 'date'
  //   rows(filters): returns array of plain row objects matching column ids
  //   summarize?(rows): optional override for the summary bar; default
  //               picks up any usd column and shows row count + sum
  const _MS_REPORTS = [
    {
      id: 'pipeline_by_client',
      name: 'Pipeline by Client',
      description: 'Every open workbook (flow not complete) with its current step and dollar value still in motion.',
      icon: '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 3v18h18"/><path d="M7 14l4-4 4 4 5-5"/></svg>',
      filters: [
        { id: 'client', label: 'Client',      type: 'select', optionsFn: () => ['', ...Object.keys(clientData).sort()] },
        { id: 'am',     label: 'Account Mgr', type: 'select', optionsFn: () => ['', 'Parker Low', 'Jackson Hollberg'] },
        { id: 'sp',     label: 'Salesperson', type: 'select', optionsFn: () => ['', 'Parker Low', 'Jackson Hollberg'] },
      ],
      columns: [
        { id: 'client',      label: 'Client',  sortable: true,  link: r => `#/client/${encodeURIComponent(r.client)}` },
        { id: 'product',     label: 'Product', sortable: true,  link: r => `#/client/${encodeURIComponent(r.client)}/workbook/${r._id}` },
        { id: 'step',        label: 'Step',    sortable: true },
        { id: 'pipelineUsd', label: 'Pipeline (USD)', sortable: true, align: 'right', format: 'usd' },
        { id: 'am',          label: 'AM',      sortable: true },
        { id: 'sp',          label: 'SP',      sortable: true },
      ],
      rows(f) {
        const out = [];
        for (const [client, items] of Object.entries(clientData)) {
          if (f.client && client !== f.client) continue;
          const det = clientDetails[client] || {};
          const am  = (det.account_manager || '').trim();
          const sp  = (det.salesperson    || '').trim();
          if (f.am && am !== f.am) continue;
          if (f.sp && sp !== f.sp) continue;
          for (const item of items) {
            if (typeof isFlowComplete === 'function' && isFlowComplete(item.flow)) continue;
            const pUsd = _rptPipelineForWorkbook(client, item);
            const step = (typeof getCurrentStepName === 'function' ? getCurrentStepName(item.flow) : '') || '—';
            out.push({
              _id: item.id,
              client, product: item.product || '—', step,
              pipelineUsd: Math.round(pUsd * 100) / 100,
              am: am || '—', sp: sp || '—',
            });
          }
        }
        return out;
      },
    },
    {
      id: 'quote_to_order_conversion',
      name: 'Quote-to-Order Conversion',
      description: 'How many quotes turn into confirmed orders, by client. Higher conversion = healthier pipeline.',
      icon: '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polyline points="22 7 13.5 15.5 8.5 10.5 2 17"/><polyline points="16 7 22 7 22 13"/></svg>',
      filters: [
        { id: 'client', label: 'Client',      type: 'select', optionsFn: () => ['', ...Object.keys(clientData).sort()] },
        { id: 'am',     label: 'Account Mgr', type: 'select', optionsFn: () => ['', 'Parker Low', 'Jackson Hollberg'] },
      ],
      columns: [
        { id: 'client',     label: 'Client',  sortable: true, link: r => `#/client/${encodeURIComponent(r.client)}` },
        { id: 'workbooks',  label: 'Workbooks', sortable: true, align: 'right', format: 'int' },
        { id: 'quoted',     label: 'Quoted',    sortable: true, align: 'right', format: 'int' },
        { id: 'ordered',    label: 'Ordered',   sortable: true, align: 'right', format: 'int' },
        { id: 'conversionPct', label: 'Conversion', sortable: true, align: 'right', format: 'pct' },
      ],
      rows(f) {
        // A workbook counts as "quoted" once flow.quoteClient is true.
        // It counts as "ordered" once it appears in an order's entries
        // (regardless of order status — placed-but-not-complete still
        // counts as a conversion).
        const orderedWbIds = new Set();
        Object.values(orderData || {}).forEach(o => {
          (o.entries || []).forEach(e => { if (e.workbookId != null) orderedWbIds.add(parseInt(e.workbookId)); });
        });
        const out = [];
        for (const [client, items] of Object.entries(clientData)) {
          if (f.client && client !== f.client) continue;
          const det = clientDetails[client] || {};
          if (f.am && (det.account_manager || '') !== f.am) continue;
          let workbooks = 0, quoted = 0, ordered = 0;
          for (const item of items) {
            workbooks++;
            if (item.flow && item.flow.quoteClient) quoted++;
            // Match by DB id if available, otherwise local item.id
            const dbId = dbWorkbookMap[`${client}|${item.id}`] || parseInt(item.id);
            if (orderedWbIds.has(parseInt(dbId)) || orderedWbIds.has(parseInt(item.id))) ordered++;
          }
          if (workbooks === 0) continue;
          const pct = quoted > 0 ? (ordered / quoted) * 100 : 0;
          out.push({ client, workbooks, quoted, ordered, conversionPct: Math.round(pct * 10) / 10 });
        }
        return out;
      },
    },
    {
      id: 'open_orders_aging',
      name: 'Open Orders Aging',
      description: 'Every order that isn’t marked complete, bucketed by how long it’s been open.',
      icon: '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>',
      filters: [
        { id: 'status', label: 'Status', type: 'select', optionsFn: () => ['', 'pending', 'in_production', 'shipped'] },
        { id: 'bucket', label: 'Aging Bucket', type: 'select', optionsFn: () => ['', '0-7 days', '8-30 days', '31-60 days', '60+ days'] },
      ],
      columns: [
        { id: 'name',     label: 'Order',  sortable: true,  link: r => `#/order/${r._id}` },
        { id: 'client',   label: 'Client', sortable: true,  link: r => `#/client/${encodeURIComponent(r.client)}` },
        { id: 'status',   label: 'Status', sortable: true },
        { id: 'daysOpen', label: 'Days Open', sortable: true, align: 'right', format: 'int' },
        { id: 'bucket',   label: 'Bucket', sortable: true },
        { id: 'totalUsd', label: 'Total (USD)', sortable: true, align: 'right', format: 'usd' },
      ],
      rows(f) {
        const out = [];
        Object.values(orderData || {}).forEach(o => {
          if (o.status === 'complete') return;
          if (f.status && o.status !== f.status) return;
          const created = o.dateCreated || o.createdAt || null;
          const days = _rptDaysSince(_rptParseAppDate(created) || created) ?? 0;
          let bucket;
          if (days <= 7)       bucket = '0-7 days';
          else if (days <= 30) bucket = '8-30 days';
          else if (days <= 60) bucket = '31-60 days';
          else                 bucket = '60+ days';
          if (f.bucket && bucket !== f.bucket) return;
          const totalUsd = (typeof orderTotals === 'function') ? (orderTotals(o).totalUsd || 0) : 0;
          out.push({
            _id: o.id,
            name: o.name || `Order #${o.id}`,
            client: o.clientName || ((o.entries || [])[0]?.clientName) || '—',
            status: (o.status || 'pending'),
            daysOpen: days,
            bucket,
            totalUsd: Math.round(totalUsd * 100) / 100,
          });
        });
        return out;
      },
    },
    {
      id: 'commissions_owed',
      name: 'Commissions Owed (by employee)',
      description: 'Commissions across all roles — filter by employee or status to see what’s pending vs paid.',
      icon: '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><line x1="12" y1="1" x2="12" y2="23"/><path d="M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6"/></svg>',
      filters: [
        { id: 'employee', label: 'Employee', type: 'select', optionsFn: () => {
          const set = new Set();
          (commissionsData || []).forEach(c => { if (c.employee) set.add(c.employee); });
          return ['', ...Array.from(set).sort()];
        }},
        { id: 'role',     label: 'Role',     type: 'select', optionsFn: () => ['', 'account_manager', 'salesperson', 'operations'] },
        { id: 'status',   label: 'Status',   type: 'select', optionsFn: () => ['', 'pending', 'paid', 'cancelled'] },
      ],
      columns: [
        { id: 'employee',    label: 'Employee', sortable: true },
        { id: 'role',        label: 'Role',     sortable: true },
        { id: 'client_name', label: 'Client',   sortable: true, link: r => r.client_name ? `#/client/${encodeURIComponent(r.client_name)}` : null },
        { id: 'product_name',label: 'Product',  sortable: true },
        { id: 'amount_usd',  label: 'Amount (USD)', sortable: true, align: 'right', format: 'usd' },
        { id: 'status',      label: 'Status',   sortable: true },
        { id: 'created_at',  label: 'Date',     sortable: true, format: 'date' },
      ],
      rows(f) {
        const data = Array.isArray(commissionsData) ? commissionsData : [];
        return data.filter(c => {
          if (f.employee && c.employee !== f.employee) return false;
          if (f.role     && c.role     !== f.role)     return false;
          if (f.status   && c.status   !== f.status)   return false;
          return true;
        }).map(c => ({
          employee:    c.employee || '—',
          role:        c.role || '—',
          client_name: c.client_name || '',
          product_name:c.product_name || '—',
          amount_usd:  parseFloat(c.amount_usd) || 0,
          status:      c.status || '—',
          created_at:  c.created_at || '',
        }));
      },
    },
    {
      id: 'margin_analysis',
      name: 'Margin Analysis',
      description: 'Effective margin per workbook based on Pricing-tab Total Landed Cost vs the Sale Per. Flag thin-margin work.',
      icon: '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><line x1="2" y1="12" x2="22" y2="12"/><path d="M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z"/></svg>',
      filters: [
        { id: 'client', label: 'Client',      type: 'select', optionsFn: () => ['', ...Object.keys(clientData).sort()] },
        { id: 'band',   label: 'Margin Band', type: 'select', optionsFn: () => ['', '< 25%', '25–40%', '40–60%', '> 60%'] },
      ],
      columns: [
        { id: 'client',       label: 'Client',  sortable: true,  link: r => `#/client/${encodeURIComponent(r.client)}` },
        { id: 'product',      label: 'Product', sortable: true,  link: r => `#/client/${encodeURIComponent(r.client)}/workbook/${r._id}` },
        { id: 'marginPct',    label: 'Margin %',  sortable: true, align: 'right', format: 'pct' },
        { id: 'landedTotal',  label: 'Landed Cost', sortable: true, align: 'right', format: 'usd' },
        { id: 'salePer',      label: 'Sale Per',  sortable: true, align: 'right', format: 'usd' },
        { id: 'band',         label: 'Band',    sortable: true },
      ],
      rows(f) {
        const out = [];
        for (const [client, items] of Object.entries(clientData)) {
          if (f.client && client !== f.client) continue;
          const det = clientDetails[client] || {};
          const fallbackMargin = parseFloat(det.default_margin_pct);
          for (const item of items) {
            const d = workbookDetail[`${client}|${item.id}`] || {};
            const landed = parseFloat(d.pricingLandedTotal) || 0;
            const sale   = parseFloat(d.pricingSalePer)     || 0;
            let pct = parseFloat(d.pricingMarginPct);
            if (isNaN(pct)) pct = isNaN(fallbackMargin) ? 50 : fallbackMargin;
            if (landed === 0 && sale === 0 && (isNaN(pct) || pct === 0)) continue;
            let band;
            if (pct < 25)       band = '< 25%';
            else if (pct < 40)  band = '25–40%';
            else if (pct < 60)  band = '40–60%';
            else                band = '> 60%';
            if (f.band && band !== f.band) continue;
            out.push({
              _id: item.id,
              client, product: item.product || '—',
              marginPct: Math.round(pct * 10) / 10,
              landedTotal: Math.round(landed * 100) / 100,
              salePer:     Math.round(sale * 100) / 100,
              band,
            });
          }
        }
        return out;
      },
    },
    {
      id: 'pending_review_inbox',
      name: 'Pending Review Inbox',
      description: 'Workbooks the client filled out via the intake link — these need a quick once-over before quoting.',
      icon: '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M22 12h-4l-3 9L9 3l-3 9H2"/></svg>',
      filters: [
        { id: 'client',  label: 'Client',     type: 'select', optionsFn: () => ['', ...Object.keys(clientData).sort()] },
        { id: 'maxAge',  label: 'Max Age (days)', type: 'days' },
      ],
      columns: [
        { id: 'client',     label: 'Client',  sortable: true,  link: r => `#/client/${encodeURIComponent(r.client)}` },
        { id: 'product',    label: 'Product', sortable: true,  link: r => `#/client/${encodeURIComponent(r.client)}/workbook/${r._id}` },
        { id: 'submittedAt',label: 'Submitted', sortable: true, format: 'date' },
        { id: 'daysOld',    label: 'Days Old',  sortable: true, align: 'right', format: 'int' },
        { id: 'contact',    label: 'Contact', sortable: true },
        { id: 'email',      label: 'Email',   sortable: true },
      ],
      rows(f) {
        const out = [];
        const maxAge = f.maxAge ? parseInt(f.maxAge) : null;
        for (const [client, items] of Object.entries(clientData)) {
          if (f.client && client !== f.client) continue;
          for (const item of items) {
            const d = workbookDetail[`${client}|${item.id}`] || {};
            if (!d.submittedByClient) continue;
            const at   = d.submittedByClientAt || '';
            const days = at ? _rptDaysSince(at) : null;
            if (maxAge != null && days != null && days > maxAge) continue;
            out.push({
              _id: item.id,
              client, product: item.product || '—',
              submittedAt: at,
              daysOld: days ?? 0,
              contact: d.submittedByContact || '—',
              email:   d.submittedByEmail   || '—',
            });
          }
        }
        return out;
      },
    },
    {
      id: 'shipment_tracking',
      name: 'Shipment Tracking',
      description: 'All known shipments grouped by status, with mode + ETA.',
      icon: '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><rect x="1" y="3" width="15" height="13"/><polygon points="16 8 20 8 23 11 23 16 16 16 16 8"/><circle cx="5.5" cy="18.5" r="2.5"/><circle cx="18.5" cy="18.5" r="2.5"/></svg>',
      filters: [
        { id: 'status', label: 'Status', type: 'select', optionsFn: () => {
          const set = new Set();
          Object.values(shipmentData || {}).forEach(s => { if (s && s.status) set.add(s.status); });
          return ['', ...Array.from(set).sort()];
        }},
        { id: 'mode',   label: 'Mode',   type: 'select', optionsFn: () => {
          const set = new Set();
          Object.values(shipmentData || {}).forEach(s => { if (s && s.mode) set.add(s.mode); });
          return ['', ...Array.from(set).sort()];
        }},
      ],
      columns: [
        { id: 'name',    label: 'Shipment', sortable: true, link: r => `#/shipment/${r._id}` },
        { id: 'status',  label: 'Status',   sortable: true },
        { id: 'mode',    label: 'Mode',     sortable: true },
        { id: 'eta',     label: 'ETA',      sortable: true, format: 'date' },
        { id: 'cartons', label: 'Cartons',  sortable: true, align: 'right', format: 'int' },
        { id: 'totalUsd',label: 'Total (USD)', sortable: true, align: 'right', format: 'usd' },
      ],
      rows(f) {
        const out = [];
        Object.values(shipmentData || {}).forEach(s => {
          if (!s) return;
          if (f.status && s.status !== f.status) return;
          if (f.mode   && s.mode   !== f.mode)   return;
          // Derive carton + USD totals from whatever shape the shipment
          // record has; fall back to 0 silently rather than crashing the
          // report when a shipment hasn't been fully populated yet.
          let cartons = 0;
          let totalUsd = 0;
          (s.items || s.entries || []).forEach(it => {
            cartons += parseInt(it.cartons || it.cartonCount || 0) || 0;
            const v = parseFloat(it.totalUsd || it.value || 0);
            if (!isNaN(v)) totalUsd += v;
          });
          out.push({
            _id: s.id,
            name: s.name || `Shipment #${s.id}`,
            status: s.status || '—',
            mode:   s.mode   || '—',
            eta:    s.eta || s.etaDate || '',
            cartons,
            totalUsd: Math.round(totalUsd * 100) / 100,
          });
        });
        return out;
      },
    },
  ];
  // Easy lookup by id
  const _MS_REPORT_BY_ID = Object.fromEntries(_MS_REPORTS.map(r => [r.id, r]));

  // ── Saved-views persistence (app_state key: ms_saved_reports) ──────
  async function _ensureSavedReportsLoaded() {
    if (_msSavedReportsLoaded) return;
    _msSavedReportsLoaded = true;
    try {
      const r = await apiCall('get_app_state', { key: 'ms_saved_reports' });
      // get_app_state returns { success, value: <stringified-json|null> }.
      let v = null;
      if (r && r.value) { try { v = JSON.parse(r.value); } catch (e) {} }
      _msSavedReports = Array.isArray(v) ? v : [];
    } catch (e) {
      _msSavedReports = [];
    }
  }
  function _persistSavedReports() {
    try {
      apiCall('save_app_state', {
        key: 'ms_saved_reports',
        value: JSON.stringify(_msSavedReports || [])
      }).catch(() => {});
    } catch (e) {}
  }

  // ════════════════════════════════════════════════════════════════════
  // CUSTOM REPORT BUILDER
  //
  // Custom reports are user-built definitions that pick a data source
  // (Workbooks / Orders / Shipments / Commissions / Clients / Intake)
  // and choose which columns + filters to expose. Stored separately
  // from saved views in app_state under "ms_custom_reports". When run,
  // a virtual report definition is built on the fly and fed into the
  // existing report engine.
  // ════════════════════════════════════════════════════════════════════

  let _msCustomReports = null;
  let _msCustomReportsLoaded = false;
  let _rbState = null; // builder modal scratch state

  // Data sources the builder can pick from. Each one's rows() function
  // returns the FULL universe of rows for that source (with every
  // available column populated); the engine then trims to the columns
  // the user picked. Filter handlers are inline so they share the
  // closure over clientData / orderData / etc.
  const _MS_CUSTOM_REPORT_SOURCES = {
    workbooks: {
      id: 'workbooks',
      name: 'Workbooks',
      desc: 'One row per workbook across every client.',
      icon: '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M2 3h6a4 4 0 0 1 4 4v14a3 3 0 0 0-3-3H2z"/><path d="M22 3h-6a4 4 0 0 0-4 4v14a3 3 0 0 1 3-3h7z"/></svg>',
      columns: [
        { id: 'client',          label: 'Client' },
        { id: 'product',         label: 'Product' },
        { id: 'step',            label: 'Current Step' },
        { id: 'dateCreated',     label: 'Date Created' },
        { id: 'pipelineUsd',     label: 'Pipeline (USD)',  format: 'usd', align: 'right' },
        { id: 'landedTotal',     label: 'Landed Cost',     format: 'usd', align: 'right' },
        { id: 'salePer',         label: 'Sale Per',        format: 'usd', align: 'right' },
        { id: 'marginPct',       label: 'Margin %',        format: 'pct', align: 'right' },
        { id: 'tierQty',         label: 'Selected Tier Qty', format: 'int', align: 'right' },
        { id: 'am',              label: 'Account Manager' },
        { id: 'sp',              label: 'Salesperson' },
        { id: 'isPendingReview', label: 'Pending Review' },
        { id: 'isComplete',      label: 'Complete' },
        { id: 'hasOrder',        label: 'On an Order' },
      ],
      filters: [
        { id: 'client', label: 'Client',      type: 'select', optionsFn: () => ['', ...Object.keys(clientData).sort()] },
        { id: 'am',     label: 'Account Mgr', type: 'select', optionsFn: () => ['', 'Parker Low', 'Jackson Hollberg'] },
        { id: 'sp',     label: 'Salesperson', type: 'select', optionsFn: () => ['', 'Parker Low', 'Jackson Hollberg'] },
        { id: 'step',   label: 'Step',        type: 'select', optionsFn: () => ['', ...flowLabels] },
        { id: 'completion', label: 'Completion', type: 'select', optionsFn: () => ['', 'Open only', 'Complete only'] },
        { id: 'pendingOnly', label: 'Pending Review', type: 'select', optionsFn: () => ['', 'Yes', 'No'] },
      ],
      rows(f) {
        // Build set of workbook IDs that appear in any order so we can
        // populate the hasOrder column without a per-row N² scan.
        const orderWbIds = new Set();
        Object.values(orderData || {}).forEach(o => {
          (o.entries || []).forEach(e => { if (e.workbookId != null) orderWbIds.add(parseInt(e.workbookId)); });
        });

        const out = [];
        for (const [client, items] of Object.entries(clientData)) {
          if (f.client && client !== f.client) continue;
          const det = clientDetails[client] || {};
          if (f.am && (det.account_manager || '') !== f.am) continue;
          if (f.sp && (det.salesperson    || '') !== f.sp) continue;
          for (const item of items) {
            const complete = (typeof isFlowComplete === 'function') ? isFlowComplete(item.flow) : false;
            if (f.completion === 'Open only'    && complete) continue;
            if (f.completion === 'Complete only' && !complete) continue;
            const stepName = (typeof getCurrentStepName === 'function' ? getCurrentStepName(item.flow) : '') || '—';
            if (f.step && stepName !== f.step) continue;
            const d = workbookDetail[`${client}|${item.id}`] || {};
            const isPending = !!d.submittedByClient;
            if (f.pendingOnly === 'Yes' && !isPending) continue;
            if (f.pendingOnly === 'No'  &&  isPending) continue;

            const tiers = Array.isArray(d.tiers) ? d.tiers : [];
            const tier  = tiers.find(t => t.id == d.selectedTierIdx) || tiers[0];
            const tierQty = tier ? (parseFloat(tier.qty) || 0) : 0;
            const dbId = dbWorkbookMap[`${client}|${item.id}`] || parseInt(item.id);
            out.push({
              _id: item.id,
              client, product: item.product || '—', step: stepName,
              dateCreated: item.dateCreated || '',
              pipelineUsd: Math.round(_rptPipelineForWorkbook(client, item) * 100) / 100,
              landedTotal: Math.round((parseFloat(d.pricingLandedTotal) || 0) * 100) / 100,
              salePer:     Math.round((parseFloat(d.pricingSalePer)     || 0) * 100) / 100,
              marginPct:   parseFloat(d.pricingMarginPct) || 0,
              tierQty,
              am: (det.account_manager || '—'),
              sp: (det.salesperson    || '—'),
              isPendingReview: isPending ? 'Yes' : 'No',
              isComplete:      complete  ? 'Yes' : 'No',
              hasOrder:        (orderWbIds.has(parseInt(dbId)) || orderWbIds.has(parseInt(item.id))) ? 'Yes' : 'No',
            });
          }
        }
        return out;
      },
    },
    orders: {
      id: 'orders',
      name: 'Orders',
      desc: 'One row per order with totals + status.',
      icon: '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><circle cx="9" cy="21" r="1"/><circle cx="20" cy="21" r="1"/><path d="M1 1h4l2.68 13.39a2 2 0 0 0 2 1.61h9.72a2 2 0 0 0 2-1.61L23 6H6"/></svg>',
      columns: [
        { id: 'name',     label: 'Order' },
        { id: 'client',   label: 'Client' },
        { id: 'status',   label: 'Status' },
        { id: 'dateCreated', label: 'Date Created' },
        { id: 'daysOpen', label: 'Days Open',     format: 'int', align: 'right' },
        { id: 'totalUsd', label: 'Total (USD)',   format: 'usd', align: 'right' },
        { id: 'entries',  label: 'Workbooks on Order', format: 'int', align: 'right' },
      ],
      filters: [
        { id: 'client', label: 'Client', type: 'select', optionsFn: () => {
          const set = new Set();
          Object.values(orderData || {}).forEach(o => {
            if (o.clientName) set.add(o.clientName);
            (o.entries || []).forEach(e => { if (e.clientName) set.add(e.clientName); });
          });
          return ['', ...Array.from(set).sort()];
        }},
        { id: 'status', label: 'Status', type: 'select', optionsFn: () => {
          const set = new Set();
          Object.values(orderData || {}).forEach(o => { if (o.status) set.add(o.status); });
          return ['', ...Array.from(set).sort()];
        }},
        { id: 'completion', label: 'Completion', type: 'select', optionsFn: () => ['', 'Open only', 'Complete only'] },
      ],
      rows(f) {
        const out = [];
        Object.values(orderData || {}).forEach(o => {
          const cl = o.clientName || ((o.entries || [])[0]?.clientName) || '—';
          if (f.client && cl !== f.client) return;
          if (f.status && o.status !== f.status) return;
          const isComplete = o.status === 'complete';
          if (f.completion === 'Open only'     &&  isComplete) return;
          if (f.completion === 'Complete only' && !isComplete) return;
          const created = o.dateCreated || o.createdAt || '';
          const days = _rptDaysSince(_rptParseAppDate(created) || created) ?? 0;
          const total = (typeof orderTotals === 'function') ? (orderTotals(o).totalUsd || 0) : 0;
          out.push({
            _id: o.id,
            name: o.name || `Order #${o.id}`,
            client: cl,
            status: o.status || 'pending',
            dateCreated: created,
            daysOpen: days,
            totalUsd: Math.round(total * 100) / 100,
            entries: (o.entries || []).length,
          });
        });
        return out;
      },
    },
    shipments: {
      id: 'shipments',
      name: 'Shipments',
      desc: 'One row per shipment.',
      icon: '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><rect x="1" y="3" width="15" height="13"/><polygon points="16 8 20 8 23 11 23 16 16 16 16 8"/><circle cx="5.5" cy="18.5" r="2.5"/><circle cx="18.5" cy="18.5" r="2.5"/></svg>',
      columns: [
        { id: 'name',    label: 'Shipment' },
        { id: 'status',  label: 'Status' },
        { id: 'mode',    label: 'Mode' },
        { id: 'eta',     label: 'ETA' },
        { id: 'cartons', label: 'Cartons',  format: 'int', align: 'right' },
        { id: 'totalUsd',label: 'Total (USD)', format: 'usd', align: 'right' },
      ],
      filters: [
        { id: 'status', label: 'Status', type: 'select', optionsFn: () => {
          const set = new Set();
          Object.values(shipmentData || {}).forEach(s => { if (s && s.status) set.add(s.status); });
          return ['', ...Array.from(set).sort()];
        }},
        { id: 'mode',   label: 'Mode',   type: 'select', optionsFn: () => {
          const set = new Set();
          Object.values(shipmentData || {}).forEach(s => { if (s && s.mode) set.add(s.mode); });
          return ['', ...Array.from(set).sort()];
        }},
      ],
      rows(f) {
        const out = [];
        Object.values(shipmentData || {}).forEach(s => {
          if (!s) return;
          if (f.status && s.status !== f.status) return;
          if (f.mode   && s.mode   !== f.mode)   return;
          let cartons = 0, totalUsd = 0;
          (s.items || s.entries || []).forEach(it => {
            cartons  += parseInt(it.cartons || it.cartonCount || 0) || 0;
            const v = parseFloat(it.totalUsd || it.value || 0);
            if (!isNaN(v)) totalUsd += v;
          });
          out.push({
            _id: s.id,
            name: s.name || `Shipment #${s.id}`,
            status: s.status || '—',
            mode:   s.mode   || '—',
            eta:    s.eta || s.etaDate || '',
            cartons,
            totalUsd: Math.round(totalUsd * 100) / 100,
          });
        });
        return out;
      },
    },
    commissions: {
      id: 'commissions',
      name: 'Commissions',
      desc: 'Commission rows from the Commissions module.',
      icon: '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><line x1="12" y1="1" x2="12" y2="23"/><path d="M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6"/></svg>',
      columns: [
        { id: 'employee',     label: 'Employee' },
        { id: 'role',         label: 'Role' },
        { id: 'client_name',  label: 'Client' },
        { id: 'product_name', label: 'Product' },
        { id: 'amount_usd',   label: 'Amount (USD)', format: 'usd', align: 'right' },
        { id: 'status',       label: 'Status' },
        { id: 'created_at',   label: 'Created', format: 'date' },
      ],
      filters: [
        { id: 'employee', label: 'Employee', type: 'select', optionsFn: () => {
          const set = new Set();
          (commissionsData || []).forEach(c => { if (c.employee) set.add(c.employee); });
          return ['', ...Array.from(set).sort()];
        }},
        { id: 'role',   label: 'Role',   type: 'select', optionsFn: () => ['', 'account_manager', 'salesperson', 'operations'] },
        { id: 'status', label: 'Status', type: 'select', optionsFn: () => ['', 'pending', 'paid', 'cancelled'] },
      ],
      rows(f) {
        return (Array.isArray(commissionsData) ? commissionsData : []).filter(c => {
          if (f.employee && c.employee !== f.employee) return false;
          if (f.role     && c.role     !== f.role)     return false;
          if (f.status   && c.status   !== f.status)   return false;
          return true;
        }).map(c => ({
          employee:     c.employee || '—',
          role:         c.role || '—',
          client_name:  c.client_name || '',
          product_name: c.product_name || '—',
          amount_usd:   parseFloat(c.amount_usd) || 0,
          status:       c.status || '—',
          created_at:   c.created_at || '',
        }));
      },
    },
    clients: {
      id: 'clients',
      name: 'Clients',
      desc: 'One row per client with rolled-up totals.',
      icon: '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M23 21v-2a4 4 0 0 0-3-3.87"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/></svg>',
      columns: [
        { id: 'name',           label: 'Client' },
        { id: 'email',          label: 'Email' },
        { id: 'primary_contact',label: 'Primary Contact' },
        { id: 'am',             label: 'Account Manager' },
        { id: 'sp',             label: 'Salesperson' },
        { id: 'totalWorkbooks', label: 'Workbooks',     format: 'int', align: 'right' },
        { id: 'openWorkbooks',  label: 'Open',          format: 'int', align: 'right' },
        { id: 'pipelineUsd',    label: 'Pipeline (USD)',format: 'usd', align: 'right' },
      ],
      filters: [
        { id: 'am', label: 'Account Mgr', type: 'select', optionsFn: () => ['', 'Parker Low', 'Jackson Hollberg'] },
        { id: 'sp', label: 'Salesperson', type: 'select', optionsFn: () => ['', 'Parker Low', 'Jackson Hollberg'] },
        { id: 'hasOpenPipeline', label: 'Has Open Pipeline', type: 'select', optionsFn: () => ['', 'Yes', 'No'] },
      ],
      rows(f) {
        const out = [];
        for (const [name, items] of Object.entries(clientData)) {
          const det = clientDetails[name] || {};
          if (f.am && (det.account_manager || '') !== f.am) continue;
          if (f.sp && (det.salesperson    || '') !== f.sp) continue;
          let openCt = 0, pipeline = 0;
          items.forEach(it => {
            const complete = (typeof isFlowComplete === 'function') ? isFlowComplete(it.flow) : false;
            if (!complete) {
              openCt++;
              pipeline += _rptPipelineForWorkbook(name, it);
            }
          });
          if (f.hasOpenPipeline === 'Yes' && pipeline === 0) continue;
          if (f.hasOpenPipeline === 'No'  && pipeline >  0) continue;
          out.push({
            name,
            email:           det.email || '',
            primary_contact: det.primary_contact || '',
            am: det.account_manager || '—',
            sp: det.salesperson    || '—',
            totalWorkbooks: items.length,
            openWorkbooks:  openCt,
            pipelineUsd:    Math.round(pipeline * 100) / 100,
          });
        }
        return out;
      },
    },
  };
  const _MS_CUSTOM_SOURCE_LIST = Object.values(_MS_CUSTOM_REPORT_SOURCES);

  async function _ensureCustomReportsLoaded() {
    if (_msCustomReportsLoaded) return;
    _msCustomReportsLoaded = true;
    try {
      const r = await apiCall('get_app_state', { key: 'ms_custom_reports' });
      let v = null;
      if (r && r.value) { try { v = JSON.parse(r.value); } catch (e) {} }
      _msCustomReports = Array.isArray(v) ? v : [];
    } catch (e) {
      _msCustomReports = [];
    }
  }
  function _persistCustomReports() {
    try {
      apiCall('save_app_state', {
        key: 'ms_custom_reports',
        value: JSON.stringify(_msCustomReports || [])
      }).catch(() => {});
    } catch (e) {}
  }

  // Build a virtual report definition from a saved custom config so the
  // existing report-engine renderers can run it unchanged.
  function _buildVirtualCustomDef(custom) {
    const src = _MS_CUSTOM_REPORT_SOURCES[custom.source];
    if (!src) return null;
    const cIds = (custom.columnIds && custom.columnIds.length) ? custom.columnIds : src.columns.map(c => c.id);
    const fIds = (custom.filterIds && custom.filterIds.length) ? custom.filterIds : src.filters.map(f => f.id);
    return {
      id: 'custom_' + custom.id,
      name: custom.name,
      description: `Custom report based on ${src.name}.`,
      icon: src.icon,
      columns: src.columns.filter(c => cIds.includes(c.id)).map(c => Object.assign({ sortable: true }, c)),
      filters: src.filters.filter(f => fIds.includes(f.id)),
      rows:    src.rows.bind(src),
    };
  }

  function runCustomReport(customId) {
    const custom = (_msCustomReports || []).find(c => c.id === customId);
    if (!custom) {
      _msToast('Custom report not found.', 'error');
      location.hash = '#/reports';
      return;
    }
    const def = _buildVirtualCustomDef(custom);
    if (!def) {
      _msToast('Custom report data source unavailable.', 'error');
      return;
    }
    // Stitch the custom def into the lookup so runReport finds it
    _MS_REPORT_BY_ID[def.id] = def;
    runReport(def.id, 'custom');
    _reportState.sourceId = customId; // remember which custom we're running
  }

  // ── Builder modal handlers ─────────────────────────────────────────
  async function openReportBuilder(editCustomId) {
    await _ensureCustomReportsLoaded();
    _rbState = {
      editingId: editCustomId || null,
      source:    null,
      columnIds: new Set(),
      filterIds: new Set(),
      name:      '',
    };
    if (editCustomId) {
      const c = (_msCustomReports || []).find(x => x.id === editCustomId);
      if (c) {
        _rbState.source    = c.source;
        _rbState.columnIds = new Set(c.columnIds || []);
        _rbState.filterIds = new Set(c.filterIds || []);
        _rbState.name      = c.name || '';
      }
    }
    document.getElementById('rb-title-text').textContent = editCustomId ? 'Edit Custom Report' : 'Build a Custom Report';
    document.getElementById('rb-delete-btn').style.display = editCustomId ? '' : 'none';
    document.getElementById('rb-name-input').value = _rbState.name;
    _rbRenderSourceGrid();
    _rbRenderColumnsAndFilters();
    document.getElementById('modal-report-builder').classList.add('open');
  }
  function closeReportBuilder() {
    document.getElementById('modal-report-builder').classList.remove('open');
    _rbState = null;
  }

  function _rbRenderSourceGrid() {
    const grid = document.getElementById('rb-source-grid');
    grid.innerHTML = _MS_CUSTOM_SOURCE_LIST.map(src => {
      const active = _rbState.source === src.id;
      return `<button type="button" class="rb-source-card${active ? ' is-active' : ''}" onclick="rbPickSource('${src.id}')">
        <span class="rb-source-icon">${src.icon}</span>
        <span class="rb-source-name">${_rptEscape(src.name)}</span>
        <span class="rb-source-desc">${_rptEscape(src.desc)}</span>
      </button>`;
    }).join('');
  }

  function rbPickSource(srcId) {
    if (!_rbState) return;
    if (_rbState.source !== srcId) {
      _rbState.source = srcId;
      // Default: select all columns + filters when first picking a source
      const src = _MS_CUSTOM_REPORT_SOURCES[srcId];
      _rbState.columnIds = new Set(src.columns.map(c => c.id));
      _rbState.filterIds = new Set(src.filters.map(f => f.id));
    }
    _rbRenderSourceGrid();
    _rbRenderColumnsAndFilters();
  }

  function _rbRenderColumnsAndFilters() {
    const colSection = document.getElementById('rb-columns-section');
    const fltSection = document.getElementById('rb-filters-section');
    const nameSection= document.getElementById('rb-name-section');
    const saveBtn    = document.getElementById('rb-save-btn');
    if (!_rbState || !_rbState.source) {
      colSection.style.display = 'none';
      fltSection.style.display = 'none';
      nameSection.style.display = 'none';
      saveBtn.disabled = true;
      return;
    }
    const src = _MS_CUSTOM_REPORT_SOURCES[_rbState.source];

    document.getElementById('rb-columns-grid').innerHTML = src.columns.map(c => {
      const checked = _rbState.columnIds.has(c.id);
      return `<label class="rb-check-row">
        <input type="checkbox" ${checked ? 'checked' : ''} onchange="rbToggleColumn('${c.id}', this.checked)" />
        <span>${_rptEscape(c.label)}</span>
      </label>`;
    }).join('');

    document.getElementById('rb-filters-grid').innerHTML = src.filters.length === 0
      ? '<span style="font-size:12px; color:var(--text-muted); font-style:italic;">No filters available for this data source.</span>'
      : src.filters.map(f => {
          const checked = _rbState.filterIds.has(f.id);
          return `<label class="rb-check-row">
            <input type="checkbox" ${checked ? 'checked' : ''} onchange="rbToggleFilter('${f.id}', this.checked)" />
            <span>${_rptEscape(f.label)}</span>
          </label>`;
        }).join('');

    colSection.style.display = '';
    fltSection.style.display = '';
    nameSection.style.display = '';
    _rbUpdateSaveDisabled();
  }

  function rbToggleColumn(id, checked) {
    if (!_rbState) return;
    if (checked) _rbState.columnIds.add(id);
    else         _rbState.columnIds.delete(id);
    _rbUpdateSaveDisabled();
  }
  function rbToggleFilter(id, checked) {
    if (!_rbState) return;
    if (checked) _rbState.filterIds.add(id);
    else         _rbState.filterIds.delete(id);
  }
  function rbToggleAllColumns() {
    if (!_rbState || !_rbState.source) return;
    const src = _MS_CUSTOM_REPORT_SOURCES[_rbState.source];
    const allOn = src.columns.every(c => _rbState.columnIds.has(c.id));
    if (allOn) _rbState.columnIds.clear();
    else       src.columns.forEach(c => _rbState.columnIds.add(c.id));
    _rbRenderColumnsAndFilters();
  }
  function _rbUpdateSaveDisabled() {
    const btn = document.getElementById('rb-save-btn');
    const ok = _rbState && _rbState.source && _rbState.columnIds.size > 0;
    btn.disabled = !ok;
  }

  async function rbSaveAndRun() {
    if (!_rbState || !_rbState.source) return;
    const name = (document.getElementById('rb-name-input').value || '').trim()
              || `${_MS_CUSTOM_REPORT_SOURCES[_rbState.source].name} (${new Date().toLocaleDateString('en-US', {month:'short', day:'numeric'})})`;
    const payload = {
      id: _rbState.editingId || ('cust_' + Math.random().toString(36).slice(2, 10) + Date.now().toString(36)),
      name,
      source: _rbState.source,
      columnIds: Array.from(_rbState.columnIds),
      filterIds: Array.from(_rbState.filterIds),
      createdAt: new Date().toISOString(),
    };
    if (!_msCustomReports) _msCustomReports = [];
    if (_rbState.editingId) {
      const ix = _msCustomReports.findIndex(c => c.id === _rbState.editingId);
      if (ix >= 0) _msCustomReports[ix] = Object.assign({}, _msCustomReports[ix], payload);
    } else {
      _msCustomReports.push(payload);
    }
    _persistCustomReports();
    closeReportBuilder();
    location.hash = `#/reports/custom/${payload.id}`;
  }

  function rbDeleteCurrent() {
    if (!_rbState || !_rbState.editingId) return;
    if (!confirm('Delete this custom report?')) return;
    _msCustomReports = (_msCustomReports || []).filter(c => c.id !== _rbState.editingId);
    _persistCustomReports();
    closeReportBuilder();
    if (location.hash.startsWith('#/reports/custom/')) location.hash = '#/reports';
    else renderReportsView();
  }
  function reportsDeleteCustom(customId) {
    if (!confirm('Delete this custom report?')) return;
    _msCustomReports = (_msCustomReports || []).filter(c => c.id !== customId);
    _persistCustomReports();
    renderReportsView();
  }

  // ── List screen ────────────────────────────────────────────────────
  async function renderReportsView() {
    await _ensureSavedReportsLoaded();
    await _ensureCustomReportsLoaded();
    document.getElementById('header-title').textContent = 'Reports';
    document.querySelectorAll('.sidebar-nav .nav-item').forEach(a => a.classList.remove('active'));
    document.querySelectorAll('.nav-flat-link').forEach(a => a.classList.remove('active'));
    const link = document.getElementById('nav-reports-link');
    if (link) link.classList.add('active');

    document.getElementById('reports-list-screen').style.display = '';
    document.getElementById('reports-run-screen').style.display = 'none';

    const grid = document.getElementById('reports-prebuilt-grid');
    grid.innerHTML = _MS_REPORTS.map(r => `
      <a class="reports-card" href="#/reports/run/${r.id}" onclick="event.preventDefault(); location.hash='#/reports/run/${r.id}'">
        <div class="reports-card-icon">${r.icon}</div>
        <div class="reports-card-title">${_rptEscape(r.name)}</div>
        <div class="reports-card-desc">${_rptEscape(r.description)}</div>
      </a>
    `).join('');

    // Custom Reports grid
    const customGrid  = document.getElementById('reports-custom-grid');
    const customEmpty = document.getElementById('reports-custom-empty');
    const customs     = (_msCustomReports || []).slice().sort((a, b) => (b.createdAt || '').localeCompare(a.createdAt || ''));
    if (customs.length === 0) {
      customGrid.innerHTML = '';
      customEmpty.style.display = '';
    } else {
      customEmpty.style.display = 'none';
      customGrid.innerHTML = customs.map(c => {
        const src = _MS_CUSTOM_REPORT_SOURCES[c.source];
        const srcName = src ? src.name : c.source;
        return `<div class="reports-card" onclick="location.hash='#/reports/custom/${c.id}'">
          <div class="reports-card-icon">${(src && src.icon) || ''}</div>
          <div class="reports-card-title">${_rptEscape(c.name)}</div>
          <div class="reports-card-desc">Custom · ${_rptEscape(srcName)}</div>
          <div class="reports-card-saved-row">
            <span class="reports-card-meta">${(c.columnIds||[]).length} column${(c.columnIds||[]).length===1?'':'s'} · ${(c.filterIds||[]).length} filter${(c.filterIds||[]).length===1?'':'s'}</span>
            <span style="display:flex; gap:4px;">
              <button class="reports-card-del" onclick="event.stopPropagation(); openReportBuilder('${c.id}')" title="Edit this custom report" style="color:var(--text-muted);">✎</button>
              <button class="reports-card-del" onclick="event.stopPropagation(); reportsDeleteCustom('${c.id}')" title="Delete this custom report">×</button>
            </span>
          </div>
        </div>`;
      }).join('');
    }

    const savedGrid  = document.getElementById('reports-saved-grid');
    const savedEmpty = document.getElementById('reports-saved-empty');
    const saved      = (_msSavedReports || []).slice().sort((a, b) => (b.savedAt || '').localeCompare(a.savedAt || ''));
    if (saved.length === 0) {
      savedGrid.innerHTML = '';
      savedEmpty.style.display = '';
    } else {
      savedEmpty.style.display = 'none';
      savedGrid.innerHTML = saved.map(s => {
        const base = _MS_REPORT_BY_ID[s.basedOn];
        const baseName = base ? base.name : s.basedOn;
        const when = s.savedAt ? new Date(s.savedAt).toLocaleDateString('en-US', {month:'short', day:'numeric', year:'numeric'}) : '';
        return `<div class="reports-card" onclick="location.hash='#/reports/saved/${s.id}'">
          <div class="reports-card-icon">${(base && base.icon) || ''}</div>
          <div class="reports-card-title">${_rptEscape(s.name)}</div>
          <div class="reports-card-desc">Based on <strong>${_rptEscape(baseName)}</strong></div>
          <div class="reports-card-saved-row">
            <span class="reports-card-meta">Saved ${_rptEscape(when)}</span>
            <button class="reports-card-del" onclick="event.stopPropagation(); reportsDeleteSaved('${s.id}')" title="Delete this saved view">×</button>
          </div>
        </div>`;
      }).join('');
    }

    showView('view-reports');
  }

  // ── Run screen ─────────────────────────────────────────────────────
  function runReport(reportId, source, savedFilters) {
    const def = _MS_REPORT_BY_ID[reportId];
    if (!def) {
      _msToast(`Report "${reportId}" not found.`, 'error');
      location.hash = '#/reports';
      return;
    }
    document.getElementById('header-title').textContent = `Reports — ${def.name}`;
    document.querySelectorAll('.sidebar-nav .nav-item').forEach(a => a.classList.remove('active'));
    document.querySelectorAll('.nav-flat-link').forEach(a => a.classList.remove('active'));
    const link = document.getElementById('nav-reports-link');
    if (link) link.classList.add('active');

    _reportState = {
      def,
      filters: Object.assign({}, savedFilters || {}),
      sortField: null,
      sortDir: 'asc',
      source: source || (savedFilters ? 'saved' : 'prebuilt'),
      sourceId: savedFilters ? savedFilters._savedId : null,
    };

    document.getElementById('reports-list-screen').style.display = 'none';
    document.getElementById('reports-run-screen').style.display = '';
    document.getElementById('reports-run-name').textContent  = def.name;
    document.getElementById('reports-run-title').textContent = def.name;
    document.getElementById('reports-run-desc').textContent  = def.description;

    _renderReportFilters();
    _applyReportFilters();
    showView('view-reports');
  }

  function _renderReportFilters() {
    const def  = _reportState.def;
    const root = document.getElementById('reports-filter-bar');
    const flts = def.filters || [];
    if (flts.length === 0) { root.innerHTML = ''; root.style.display = 'none'; return; }
    root.style.display = '';

    const html = flts.map(f => {
      const cur = _reportState.filters[f.id] || '';
      if (f.type === 'select') {
        const opts = (typeof f.optionsFn === 'function') ? (f.optionsFn() || []) : (f.options || []);
        return `<div class="reports-filter">
          <label>${_rptEscape(f.label)}</label>
          <select onchange="reportsSetFilter('${f.id}', this.value)">
            ${opts.map(o => {
              const v = String(o);
              const lbl = v === '' ? `All ${_rptEscape(f.label).toLowerCase()}s` : _rptEscape(v.replace(/_/g, ' '));
              return `<option value="${_rptEscape(v)}"${v === cur ? ' selected' : ''}>${lbl}</option>`;
            }).join('')}
          </select>
        </div>`;
      }
      if (f.type === 'days') {
        return `<div class="reports-filter">
          <label>${_rptEscape(f.label)}</label>
          <input type="number" min="0" placeholder="any" value="${_rptEscape(cur)}" oninput="reportsSetFilter('${f.id}', this.value)" />
        </div>`;
      }
      // text fallback
      return `<div class="reports-filter">
        <label>${_rptEscape(f.label)}</label>
        <input type="text" placeholder="search…" value="${_rptEscape(cur)}" oninput="reportsSetFilter('${f.id}', this.value)" />
      </div>`;
    }).join('');

    root.innerHTML = html + `<button class="reports-filter-clear" onclick="reportsClearFilters()">Clear</button>`;
  }

  function reportsSetFilter(id, value) {
    if (!_reportState) return;
    if (value === '' || value == null) {
      delete _reportState.filters[id];
    } else {
      _reportState.filters[id] = value;
    }
    _applyReportFilters();
  }
  function reportsClearFilters() {
    if (!_reportState) return;
    _reportState.filters = {};
    _renderReportFilters();
    _applyReportFilters();
  }

  function _applyReportFilters() {
    if (!_reportState) return;
    const def  = _reportState.def;
    const fc   = Object.assign({}, _reportState.filters);
    delete fc._savedId;
    let rows;
    try { rows = def.rows(fc) || []; }
    catch (e) {
      console.error('[MS report rows]', e);
      rows = [];
    }

    // Sort
    if (_reportState.sortField) {
      const col = def.columns.find(c => c.id === _reportState.sortField);
      if (col) {
        const dir = _reportState.sortDir === 'desc' ? -1 : 1;
        rows.sort((a, b) => {
          const av = a[col.id], bv = b[col.id];
          if (typeof av === 'number' && typeof bv === 'number') return dir * (av - bv);
          return dir * String(av ?? '').localeCompare(String(bv ?? ''));
        });
      }
    }

    _reportState.rows = rows;
    _renderReportTable();
    _renderReportSummary();
  }

  function _renderReportSummary() {
    const def  = _reportState.def;
    const rows = _reportState.rows || [];
    const bar  = document.getElementById('reports-summary-bar');
    const stats = [`<div class="stat"><span class="stat-label">Rows</span><span class="stat-value">${rows.length.toLocaleString('en-US')}</span></div>`];

    // Auto-sum any USD/int columns at the bottom for quick context.
    def.columns.forEach(col => {
      if (col.format === 'usd' || col.format === 'int') {
        const total = rows.reduce((s, r) => s + (parseFloat(r[col.id]) || 0), 0);
        if (total !== 0) {
          stats.push(`<div class="stat"><span class="stat-label">Σ ${_rptEscape(col.label)}</span><span class="stat-value">${col.format === 'usd' ? _RPT_FMT_USD(total) : _RPT_FMT_INT(Math.round(total))}</span></div>`);
        }
      }
    });
    bar.innerHTML = stats.join('');
  }

  function _renderReportTable() {
    const def  = _reportState.def;
    const head = document.getElementById('reports-table-head');
    const body = document.getElementById('reports-table-body');
    const empty= document.getElementById('reports-empty');
    const rows = _reportState.rows || [];

    head.innerHTML = def.columns.map(col => {
      const align = col.align === 'right' ? ' r' : (col.align === 'center' ? ' c' : '');
      const sort  = col.sortable !== false ? ' sortable' : '';
      const dir   = (_reportState.sortField === col.id) ? ` ${_reportState.sortDir}` : '';
      const click = col.sortable !== false ? ` onclick="reportsSort('${col.id}')"` : '';
      return `<th class="${(align + sort + dir).trim()}"${click}>${_rptEscape(col.label)}</th>`;
    }).join('');

    if (rows.length === 0) {
      body.innerHTML = '';
      empty.style.display = '';
      return;
    }
    empty.style.display = 'none';

    body.innerHTML = rows.map(r => {
      const tds = def.columns.map(col => {
        const v = r[col.id];
        let display;
        if (col.format === 'usd')      display = _RPT_FMT_USD(parseFloat(v) || 0);
        else if (col.format === 'int') display = _RPT_FMT_INT(parseInt(v) || 0);
        else if (col.format === 'pct') display = _RPT_FMT_PCT(parseFloat(v) || 0);
        else if (col.format === 'date')display = _RPT_FMT_DATE(v);
        else                           display = (v == null || v === '') ? '—' : _rptEscape(v);
        const align = col.align === 'right' ? ' r' : (col.align === 'center' ? ' c' : '');
        const link = (typeof col.link === 'function') ? col.link(r) : null;
        if (link) {
          return `<td class="${align.trim()}"><a href="${_rptEscape(link)}" onclick="event.preventDefault(); location.hash='${_rptEscape(link)}'" style="color:inherit; text-decoration:none; border-bottom:1px dashed transparent;" onmouseover="this.style.borderBottomColor='var(--accent)'; this.style.color='var(--accent)';" onmouseout="this.style.borderBottomColor='transparent'; this.style.color='inherit';">${display}</a></td>`;
        }
        return `<td class="${align.trim()}">${display}</td>`;
      }).join('');
      return `<tr>${tds}</tr>`;
    }).join('');
  }

  function reportsSort(field) {
    if (!_reportState) return;
    if (_reportState.sortField === field) {
      _reportState.sortDir = _reportState.sortDir === 'asc' ? 'desc' : 'asc';
    } else {
      _reportState.sortField = field;
      _reportState.sortDir = 'asc';
    }
    _applyReportFilters();
  }

  // ── Save / delete saved views ──────────────────────────────────────
  function reportsSaveCurrentView() {
    if (!_reportState) return;
    const def = _reportState.def;
    const proposed = `${def.name} — ${new Date().toLocaleDateString('en-US', {month:'short', day:'numeric'})}`;
    const name = prompt('Save this view as:', proposed);
    if (!name) return;

    if (!_msSavedReports) _msSavedReports = [];
    const id = 'sv_' + Math.random().toString(36).slice(2, 10) + Date.now().toString(36);
    _msSavedReports.push({
      id,
      name: String(name).trim(),
      basedOn: def.id,
      filters: Object.assign({}, _reportState.filters),
      savedAt: new Date().toISOString(),
    });
    _persistSavedReports();
    _msToast('Saved view created.', 'success');
  }

  function reportsDeleteSaved(savedId) {
    if (!_msSavedReports) return;
    const ix = _msSavedReports.findIndex(s => s.id === savedId);
    if (ix < 0) return;
    if (!confirm(`Delete saved view "${_msSavedReports[ix].name}"?`)) return;
    _msSavedReports.splice(ix, 1);
    _persistSavedReports();
    renderReportsView();
  }

  // ── Export (CSV + PDF) — reuses the existing patterns from the
  // Client Quote exports so the look + filename style stays consistent.
  function reportsExportCSV() {
    if (!_reportState || !_reportState.rows || _reportState.rows.length === 0) {
      _msToast('No rows to export. Adjust filters or run a different report.', 'error');
      return;
    }
    const def  = _reportState.def;
    const rows = _reportState.rows;
    const lines = [];
    lines.push(_csvEscape(`Market Sculpt — ${def.name}`));
    lines.push([_csvEscape('Generated'), _csvEscape(new Date().toLocaleString('en-US'))].join(','));
    const fkeys = Object.keys(_reportState.filters || {});
    if (fkeys.length) {
      lines.push([_csvEscape('Filters'), _csvEscape(fkeys.map(k => `${k}=${_reportState.filters[k]}`).join(' · '))].join(','));
    }
    lines.push('');
    lines.push(def.columns.map(c => _csvEscape(c.label)).join(','));
    rows.forEach(r => {
      lines.push(def.columns.map(c => {
        const v = r[c.id];
        if (c.format === 'usd') return _csvEscape((parseFloat(v) || 0).toFixed(2));
        if (c.format === 'int') return _csvEscape(parseInt(v) || 0);
        if (c.format === 'pct') return _csvEscape(((parseFloat(v) || 0)).toFixed(1) + '%');
        if (c.format === 'date')return _csvEscape(_RPT_FMT_DATE(v));
        return _csvEscape(v == null ? '' : v);
      }).join(','));
    });

    const csv = '﻿' + lines.join('\r\n');
    const fname = `report_${def.id}_${new Date().toISOString().slice(0,10)}.csv`;
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const url  = URL.createObjectURL(blob);
    const a    = document.createElement('a');
    a.href = url; a.download = fname;
    document.body.appendChild(a); a.click(); document.body.removeChild(a);
    setTimeout(() => URL.revokeObjectURL(url), 1000);
    _msToast('Report CSV downloaded.', 'success');
  }

  function reportsExportPDF() {
    if (!_reportState || !_reportState.rows || _reportState.rows.length === 0) {
      _msToast('No rows to export.', 'error');
      return;
    }
    const def  = _reportState.def;
    const rows = _reportState.rows;
    const esc  = s => String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');

    const headHtml = def.columns.map(c => {
      const align = c.align === 'right' ? ' class="r"' : (c.align === 'center' ? ' class="c"' : '');
      return `<th${align}>${esc(c.label)}</th>`;
    }).join('');
    const rowsHtml = rows.map(r => '<tr>' + def.columns.map(c => {
      const v = r[c.id];
      let display;
      if (c.format === 'usd')      display = _RPT_FMT_USD(parseFloat(v) || 0);
      else if (c.format === 'int') display = _RPT_FMT_INT(parseInt(v) || 0);
      else if (c.format === 'pct') display = _RPT_FMT_PCT(parseFloat(v) || 0);
      else if (c.format === 'date')display = _RPT_FMT_DATE(v);
      else                         display = (v == null || v === '') ? '—' : esc(v);
      const align = c.align === 'right' ? ' class="r"' : (c.align === 'center' ? ' class="c"' : '');
      return `<td${align}>${display}</td>`;
    }).join('') + '</tr>').join('');

    const filtersStr = Object.entries(_reportState.filters || {})
      .map(([k, v]) => `${esc(k)} = ${esc(v)}`).join(' · ');

    const html = `<!DOCTYPE html><html lang="en"><head>
<meta charset="UTF-8"><title>${esc(def.name)} — Market Sculpt</title>
<style>
  *,*::before,*::after { box-sizing: border-box; margin: 0; padding: 0; }
  body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif; color: #1a1d2e; background: #fff; padding: 28px; font-size: 12px; line-height: 1.5; }
  .header { display: flex; justify-content: space-between; align-items: flex-start; border-bottom: 3px solid #E8751A; padding-bottom: 14px; margin-bottom: 18px; }
  .brand { font-size: 20px; font-weight: 800; color: #E8751A; border-left: 3px solid #E8751A; padding-left: 12px; letter-spacing: -0.3px; }
  .brand-sub { font-size: 10px; font-weight: 500; color: #6b7280; letter-spacing: 0.04em; text-transform: uppercase; margin-top: 4px; }
  .meta-block { text-align: right; font-size: 11px; color: #6b7280; }
  h1 { font-size: 20px; font-weight: 800; margin-bottom: 4px; color: #1a1d2e; }
  .desc { font-size: 12px; color: #6b7280; margin-bottom: 12px; line-height: 1.5; max-width: 760px; }
  .filters { font-size: 11px; color: #374151; padding: 8px 12px; background: #f8f9fb; border-left: 3px solid #6b93ff; border-radius: 4px; margin-bottom: 14px; }
  table { width: 100%; border-collapse: collapse; font-size: 12px; }
  thead th { padding: 9px 11px; font-size: 10px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.05em; color: #9ba3c0; background: #f8f9fb; border-bottom: 1px solid #e5e7eb; text-align: left; }
  thead th.r { text-align: right; } thead th.c { text-align: center; }
  tbody td { padding: 8px 11px; border-bottom: 1px solid #f0f2f5; }
  tbody td.r { text-align: right; } tbody td.c { text-align: center; }
  .footer { margin-top: 18px; padding-top: 12px; border-top: 1px solid #e5e7eb; text-align: center; font-size: 10px; color: #9ba3c0; }
  .footer a { color: #E8751A; text-decoration: none; }
  .print-controls { position: fixed; top: 16px; right: 16px; display: flex; gap: 8px; z-index: 100; }
  .print-controls button { background: #E8751A; color: #fff; border: none; border-radius: 6px; padding: 7px 14px; font-size: 12px; font-weight: 700; cursor: pointer; font-family: inherit; box-shadow: 0 2px 6px rgba(0,0,0,0.15); }
  .print-controls button.secondary { background: #fff; color: #6b7280; border: 1px solid #d1d5db; }
  @media print {
    body { padding: 0; }
    .print-controls { display: none !important; }
    table { page-break-inside: auto; }
    tr { page-break-inside: avoid; }
  }
</style></head><body>
  <div class="print-controls">
    <button onclick="window.print()">Print / Save as PDF</button>
    <button class="secondary" onclick="window.close()">Close</button>
  </div>
  <div class="header">
    <div>
      <div class="brand">Market Sculpt</div>
      <div class="brand-sub">Reports</div>
    </div>
    <div class="meta-block">
      Generated ${esc(new Date().toLocaleString('en-US'))}<br>
      ${esc(rows.length)} rows
    </div>
  </div>
  <h1>${esc(def.name)}</h1>
  <p class="desc">${esc(def.description)}</p>
  ${filtersStr ? `<div class="filters"><strong>Filters:</strong> ${filtersStr}</div>` : ''}
  <table><thead><tr>${headHtml}</tr></thead><tbody>${rowsHtml}</tbody></table>
  <div class="footer">Market Sculpt LLC &nbsp;·&nbsp; <a href="https://marketsculpt.com">marketsculpt.com</a></div>
  <script>window.addEventListener('load', () => setTimeout(() => window.print(), 350));<\/script>
</body></html>`;

    const win = window.open('', '_blank');
    if (!win) { _msToast('Pop-up blocked. Allow pop-ups for this site to use PDF export.', 'error'); return; }
    win.document.open(); win.document.write(html); win.document.close();
  }

  function _rptEscape(s) {
    return String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
  }

  function renderDashboard(clientName) {
    const items = [...(clientData[clientName] || [])];
    const tbody = document.getElementById('dash-tbody');
    const emptyState = document.getElementById('dash-empty');
    const table = document.getElementById('dash-table');

    if (items.length === 0) {
      table.style.display = 'none';
      emptyState.style.display = 'block';
    } else {
      table.style.display = '';
      emptyState.style.display = 'none';
    }

    // ── Flow-progress score (higher = further along) ─────────────────────
    const flowScore = flow => flowSteps.filter(s => flow[s]).length;

    // ── Build workbookId → order lookup for this client ──────────────────
    // Maps workbookId (number) → { orderId, orderName, orderStatus }
    const wbOrderMap = {};
    Object.values(orderData || {}).forEach(order => {
      (order.entries || []).forEach(e => {
        if (e.clientName === clientName) {
          wbOrderMap[parseInt(e.workbookId)] = {
            orderId:     order.id,
            orderName:   order.name || `Order #${order.id}`,
            orderStatus: order.status
          };
        }
      });
    });

    // ── Sort ──────────────────────────────────────────────────────────────
    const months = { Jan:0, Feb:1, Mar:2, Apr:3, May:4, Jun:5, Jul:6, Aug:7, Sep:8, Oct:9, Nov:10, Dec:11 };
    const parseDate = d => {
      if (!d) return new Date(0);
      const parts = d.split(' ');
      return new Date(2000 + parseInt(parts[2]), months[parts[1]], parseInt(parts[0]));
    };
    // Pull each workbook's cached Total Landed Cost from the Pricing
    // tab so we can show a Landed Cost column on this dashboard +
    // sort by it. The cache is written every time the Pricing tab
    // re-renders for that workbook; missing/0 → render as "—".
    const _landedFor = it => {
      const d = workbookDetail[`${clientName}|${it.id}`] || {};
      const v = parseFloat(d.pricingLandedTotal);
      return (!isNaN(v) && v > 0) ? v : 0;
    };

    const dir = _clientSortDir === 'asc' ? 1 : -1;
    items.sort((a, b) => {
      if (_clientSortField === 'product') return dir * a.product.localeCompare(b.product);
      if (_clientSortField === 'dateSubmitted') return dir * (parseDate(a.dateSubmitted) - parseDate(b.dateSubmitted));
      if (_clientSortField === 'status') return dir * (getCurrentStepName(a.flow) || '').localeCompare(getCurrentStepName(b.flow) || '');
      if (_clientSortField === 'landed')  return dir * (_landedFor(a) - _landedFor(b));
      // Default: furthest-along first, then newest date as tiebreaker
      const scoreDiff = flowScore(b.flow) - flowScore(a.flow);
      if (scoreDiff !== 0) return scoreDiff;
      return parseDate(b.dateCreated) - parseDate(a.dateCreated);
    });

    const _fmtUsdShort = v => '$' + v.toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2});

    tbody.innerHTML = items.map(item => {
      const complete = isFlowComplete(item.flow);
      const stepName = getCurrentStepName(item.flow);
      const stepClass = complete ? 'complete' : 'in-progress';

      // Order column
      const orderInfo = wbOrderMap[parseInt(item.id)];
      const orderCell = orderInfo
        ? `<span class="wb-order-pill ${orderInfo.orderStatus === 'complete' ? 'wb-order-pill--closed' : ''}"
              onclick="event.stopPropagation(); location.hash='#/orders'"
              title="View order">${orderInfo.orderName}</span>`
        : '<span style="color:var(--text-muted);">—</span>';

      // Pending Review badge — set by the client-portal RFQ intake flow
      // (intake.php). Stays until the operator clears the flag (the badge
      // is a visual cue that this workbook came in via the intake form
      // and hasn't been reviewed yet).
      const _det = workbookDetail[`${clientName}|${item.id}`] || {};
      const pendingReview = !!_det.submittedByClient;
      const pendingBadge = pendingReview
        ? ` <span class="pending-review-badge" title="Submitted via client intake link — needs review">Pending Review</span>`
        : '';

      // Landed Cost cell — cached pricingLandedTotal from the Pricing
      // tab. Empty → "—" (so the operator knows that workbook hasn't
      // been priced yet).
      const landed = _landedFor(item);
      const landedCell = landed > 0
        ? `<span class="wb-landed-pill" title="Total Landed Cost from this workbook's Pricing tab">${_fmtUsdShort(landed)}</span>`
        : `<span style="color:var(--text-muted);">—</span>`;

      return `
      <tr class="${complete ? 'row-complete' : ''}${pendingReview ? ' row-pending-review' : ''}" onclick="location.hash='#/client/${encodeURIComponent(clientName).replace(/'/g,'%27')}/workbook/${item.id}'">
        <td class="product-name">${item.product}${pendingBadge}</td>
        <td class="col-landed">${landedCell}</td>
        <td class="col-date-created"><span class="date-full">${item.dateCreated}</span><span class="date-short">${shortDate(item.dateCreated)}</span></td>
        <td class="col-date-submitted">${item.dateSubmitted || '—'}</td>
        <td class="col-order">${orderCell}</td>
        <td class="col-flow">
          <div class="flow-group">
            ${flowSteps.map((s, i) => `
              <div class="flow-step">
                <div class="flow-bar ${item.flow[s] ? 'filled' : ''}"></div>
                <span class="flow-label">${flowLabels[i]}</span>
              </div>
            `).join('')}
          </div>
        </td>
        <td class="col-mobile-status"><span class="mobile-status-badge ${stepClass}">${stepName}</span></td>
        <td><button class="action-icon-btn" onclick="event.stopPropagation(); toggleActionMenu(this)" title="Actions">⋮</button><div class="action-menu"><a onclick="event.stopPropagation(); location.hash='#/client/${encodeURIComponent(clientName).replace(/'/g,'%27')}/workbook/${item.id}'">View</a><a onclick="event.stopPropagation(); location.hash='#/client/${encodeURIComponent(clientName).replace(/'/g,'%27')}/workbook/${item.id}'">Edit</a>${pendingReview ? `<a onclick="event.stopPropagation(); clearPendingReview('${clientName.replace(/'/g, "\\'")}', '${item.id}')">Clear Pending Review</a>` : ''}<a onclick="event.stopPropagation(); duplicateWorkbook('${clientName.replace(/'/g, "\\'")}', '${item.id}')">Duplicate</a><a onclick="event.stopPropagation(); openDeleteModal('${clientName.replace(/'/g, "\\'")}', '${item.id}', '${item.product.replace(/'/g, "\\'")}')">Delete</a></div></td>
      </tr>
    `}).join('');

    document.getElementById('header-title').textContent = clientName + ' — Workbooks';
    updateSidebarActive(clientName);
    renderClientDetailCard(clientName);
    showView('view-dashboard');
    addRecentNav({ type: 'client', label: clientName, href: `#/client/${encodeURIComponent(clientName)}` });
  }

  function fillWorkbook(clientName, workbookId) {
    try { _fillWorkbookInner(clientName, workbookId); }
    catch(e) {
      console.error('[MS fillWorkbook]', e);
      _filling = false;
      // Show a recoverable error rather than a silent blank screen.
      // Surface the raw error message + first stack frame in the UI so we
      // can diagnose without making the user dig in DevTools.
      const t = document.getElementById('header-title');
      if (t) t.textContent = 'Error loading workbook';
      showView('view-workbook');
      const wv = document.getElementById('view-workbook');
      if (wv && !wv.querySelector('.ms-load-error')) {
        const errMsg   = (e && e.message) ? e.message : String(e);
        const errStack = (e && e.stack)   ? String(e.stack).split('\n').slice(0, 4).join('\n') : '';
        const escape   = s => String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
        const d = document.createElement('div');
        d.className = 'ms-load-error';
        d.style.cssText = 'padding:48px 32px;text-align:center;';
        d.innerHTML = `<p style="font-size:16px;font-weight:700;color:var(--danger);">Could not load this workbook</p>
          <p style="margin-top:8px;color:var(--text-muted);font-size:13px;">An unexpected error occurred. Your data has not been lost.</p>
          <pre style="display:inline-block;margin-top:14px;padding:10px 14px;background:rgba(251,113,133,0.08);border:1px solid rgba(251,113,133,0.3);border-radius:6px;color:var(--text);font-size:11px;text-align:left;max-width:720px;white-space:pre-wrap;word-break:break-word;">${escape(errMsg)}${errStack ? '\n\n' + escape(errStack) : ''}</pre>
          <div><a href="#" onclick="document.querySelector('.ms-load-error')?.remove();location.hash=''"
             style="display:inline-block;margin-top:16px;font-size:13px;color:var(--accent);">← Back to All Workbooks</a></div>`;
        wv.prepend(d);
      }
    }
  }
  function _fillWorkbookInner(clientName, workbookId) {
    // Save previous workbook immediately before switching to a different one
    const switching = currentClient && currentWorkbookId &&
                      (currentClient !== clientName || currentWorkbookId !== workbookId);
    if (switching) {
      clearTimeout(saveTimer);
      const prevDetail = collectWorkbookDetail();
      const prevKey = `${currentClient}|${currentWorkbookId}`;
      workbookDetail[prevKey] = prevDetail;
      syncClientDataName(currentClient, currentWorkbookId, prevDetail);
      const prevDbId = dbWorkbookMap[prevKey] || currentWorkbookId;
      // create_revision: true — switching workbooks is a meaningful save point
      apiCall('save_workbook_detail', { id: prevDbId, detail: prevDetail, changed_by: getCurrentUser(), create_revision: true });
      saveToLocalStorage();
    }

    _filling = true;
    currentClient = clientName;
    currentWorkbookId = workbookId;

    // Start presence heartbeat for this workbook (stops any previous one first)
    startPresenceHeartbeat(parseInt(workbookId, 10));

    // Back button context
    const backBtn = document.getElementById('btn-back');
    if (backBtn) {
      const bHash  = _wbBackHash  || `#/client/${encodeURIComponent(clientName)}`;
      const bLabel = _wbBackLabel || 'Back to Workbooks';
      backBtn.textContent = `← ${bLabel}`;
      backBtn.onclick = (e) => { e.preventDefault(); _wbBackHash = null; _wbBackLabel = null; location.hash = bHash; };
      _wbBackHash = null; _wbBackLabel = null;
    }

    // Reset to default Workbook tab
    document.querySelectorAll('.wb-tab-content').forEach(el => el.classList.remove('active'));
    document.querySelectorAll('.wb-tab').forEach(el => el.classList.remove('active'));
    const defaultTab = document.getElementById('wb-tab-workbook');
    if (defaultTab) defaultTab.classList.add('active');
    const defaultBtn = document.querySelector('.wb-tab[onclick*="workbook"]');
    if (defaultBtn) defaultBtn.classList.add('active');

    const key = `${clientName}|${workbookId}`;
    const data = workbookDetail[key];

    // Render status bar from client data
    const items = clientData[clientName] || [];
    const item = items.find(i => i.id === parseInt(workbookId));
    if (item) renderStatusBar(item.flow);
    // Sync the Watchers count badge with whatever's saved on this workbook
    if (typeof _updateWatchersCountBadge === 'function') _updateWatchersCountBadge();

    // Clear existing tier rows (both tables)
    document.getElementById('tier-body').innerHTML = '';
    tierCount = 0;
    document.getElementById('wb-tier-body').innerHTML = '';
    wbTierCount = 0;

    function _s(id, val) { const el = document.getElementById(id); if (el) el.value = val || ''; }

    if (data && !Array.isArray(data) && (data.client || data.product || data.productImages || data.productImage)) {
      // Workbook tab
      // Populate the Client dropdown options first (it's a <select>),
      // then set the active selection. Falls back to plain .value
      // assignment if the helper isn't loaded yet (defensive).
      if (typeof populateClientNameSelect === 'function') {
        populateClientNameSelect(data.client || currentClient || '');
      } else {
        _s('client-name', data.client);
      }
      _s('product-name', data.product);
      _s('product-desc', data.desc);
      _s('dim-in-l', data.dimInL);
      _s('dim-in-w', data.dimInW);
      _s('dim-in-h', data.dimInH);
      // Load cm values or convert from inches
      if (data.dimCmL) {
        _s('dim-cm-l', data.dimCmL);
        _s('dim-cm-w', data.dimCmW);
        _s('dim-cm-h', data.dimCmH);
      } else if (data.dimInL) {
        convertDim('dim-in-l', 'dim-cm-l', 'in');
        convertDim('dim-in-w', 'dim-cm-w', 'in');
        convertDim('dim-in-h', 'dim-cm-h', 'in');
      }
      // Category / subcategory
      _s('product-category', data.productCategory);
      _s('product-category-2', data.productCategory2 || '');
      document.getElementById('cat2-wrap').classList.toggle('has-value', !!data.productCategory2);
      if (data.productCategory) updateSubcategories();
      _s('product-subcategory', data.productSubcategory);
      _s('product-subcategory-2', data.productSubcategory2 || '');
      // Restore the "+ Add second material" toggle. Default to enabled
      // whenever a secondary value or other-text actually exists so
      // legacy workbooks (saved before the toggle existed) auto-show
      // their secondary material on next load.
      const mat2Toggle = document.getElementById('mat2-toggle');
      if (mat2Toggle) {
        const hasSecondary = !!(data.productSubcategory2 || data.productSubcategoryOther2);
        mat2Toggle.checked = !!data.materialSecondEnabled || hasSecondary;
        if (typeof onMat2ToggleVisibility === 'function') onMat2ToggleVisibility();
      }
      // Restore the "Other" custom-material text + reveal the input
      // when the saved value was "Other". _onMaterialChange() flips
      // the visibility based on the select state.
      _s('product-subcategory-other',   data.productSubcategoryOther  || '');
      _s('product-subcategory-other-2', data.productSubcategoryOther2 || '');
      // Pallet Max Height — restore from this workbook's saved value
      // (data.palletMaxHeight). Falls back to the HTML default of 60"
      // for legacy workbooks that never saved this field. The
      // localStorage default is NOT applied here — it only seeds
      // BRAND-NEW workbooks at creation time, so a recent default
      // change doesn't rewrite the height on every existing workbook.
      if (typeof applyPalletMaxHeight === 'function') applyPalletMaxHeight(data.palletMaxHeight);
      // Pallet manual mode: restore the checkbox + sync the dependent
      // UI (gray-out + label) so a hard refresh doesn't lose the flag.
      const palletManualEl = document.getElementById('pallet-manual');
      if (palletManualEl) {
        palletManualEl.checked = !!data.palletManualMode;
        if (typeof onPalletManualToggle === 'function') {
          // _filling guard inside onPalletManualToggle skips autosave;
          // calling it just for the UI side-effects (gray + label swap).
          onPalletManualToggle();
        }
      }
      // Pallet 4 mm divider toggle — only applies in manual mode but we
      // restore the checkbox state regardless so toggling manual mode
      // back on shows their previous choice.
      const palletDividerEl = document.getElementById('pallet-divider');
      if (palletDividerEl) palletDividerEl.checked = !!data.palletDivider;
      // Product Dimensions lock — restore the checkbox state then call
      // the toggle so the disabled state on the dim inputs matches.
      const productLockEl = document.getElementById('product-dims-lock');
      if (productLockEl) {
        productLockEl.checked = !!data.productDimsLocked;
        if (typeof onProductDimsLockToggle === 'function') onProductDimsLockToggle();
      }
      // Manual freight-cost override — restore the value first so the
      // toggle handler picks it up; calcFreight runs after.
      _s('freight-cost-override', data.freightCostOverrideUsd);
      const freightOverrideEl = document.getElementById('freight-cost-override-toggle');
      if (freightOverrideEl) {
        freightOverrideEl.checked = !!data.freightCostOverrideOn;
        if (typeof onShippingCostOverrideToggle === 'function') onShippingCostOverrideToggle();
      }
      // Weight-only override — restore the checkbox + qty + kg/lb,
      // then call the toggle so the gray-out + enable state matches.
      _s('weight-only-qty', data.weightOnlyCaseQty);
      _s('weight-only-kg',  data.weightOnlyKg);
      _s('weight-only-lbs', data.weightOnlyLbs);
      const weightOnlyEl = document.getElementById('weight-only-override');
      if (weightOnlyEl) {
