      _s('case-only-h-cm',         data.caseOnlyHCm);
      _s('case-only-h-in',         data.caseOnlyHIn);
      _s('case-only-weight-kg',    data.caseOnlyWeightKg);
      _s('case-only-weight-lbs',   data.caseOnlyWeightLbs);
      const caseOnlyEl = document.getElementById('case-only-override');
      if (caseOnlyEl) {
        caseOnlyEl.checked = !!data.caseOnlyOverride;
        if (typeof onCaseOnlyToggle === 'function') onCaseOnlyToggle();
      }
      // Pallet load mode — pallet | loose. Pick the radio that matches
      // the saved value (defaults to "pallet" when blank / legacy).
      const _loadModeSaved = data.palletLoadMode === 'loose' ? 'loose' : 'pallet';
      const _loadModeEl = document.getElementById('pallet-load-' + _loadModeSaved);
      if (_loadModeEl) _loadModeEl.checked = true;
      // Free-form pallet notes
      _s('pallet-notes',       data.palletNotes);
      _s('pallet-stack-notes', data.palletStackNotes);
      document.getElementById('mat2-wrap').classList.toggle('has-value', !!data.productSubcategory2);
      checkSecondaryLock();
      if (typeof _onMaterialChange === 'function') _onMaterialChange();
      _s('materials', data.materials);
      _s('pantone-text', data.pantone);
      _s('cmyk', data.cmyk);
      _s('color-notes', data.colorNotes);
      // RFQ Line Items
      document.getElementById('rfq-body').innerHTML = '';
      rfqCount = 0;
      const hasRfqData = data.rfqItems && Array.isArray(data.rfqItems) && data.rfqItems.length > 0
        && data.rfqItems.some(i => i.item || i.sku || i.qty || i.priceRmb || i.leadTime);
      if (hasRfqData) {
        data.rfqItems.forEach((rfqItem, idx) => {
          // First row: replace empty or old "Main Item" placeholder with the actual product name
          let itemName = rfqItem.item;
          if (idx === 0 && (!itemName || itemName === 'Main Item')) itemName = data.product || '';
          addRfqRow(itemName, rfqItem.sku || '', rfqItem.qty, rfqItem.priceRmb, rfqItem.leadTime, rfqItem.sample || false, rfqItem.variants || []);
        });
      } else if (data.qty || data.unitPriceRmb) {
