      if (data.cartonOuterWIn && !data.cartonOuterWCm) convertDim('carton-outer-w-in','carton-outer-w-cm','in');
      if (data.cartonOuterHIn && !data.cartonOuterHCm) convertDim('carton-outer-h-in','carton-outer-h-cm','in');
