      }
      renderArtGallery();
      _clientLogo = data.clientLogo || null;
      renderClientLogo();
      setTimeout(renderPalletViz, 50);
    } else {
      // Fill with basic info from the client list
      const items = clientData[clientName] || [];
      const item = items.find(i => i.id === parseInt(workbookId));
      document.getElementById('client-name').value = clientName;
      document.getElementById('product-name').value = item ? item.product : '';
      document.getElementById('product-desc').value = item ? item.description : '';
      // Clear other fields
      ['dim-in-l','dim-in-w','dim-in-h','dim-mm-l','dim-mm-w','dim-mm-h','materials','pantone-text','cmyk','color-notes','quote-qc'].forEach(id => {
        const el = document.getElementById(id);
        if (el) el.value = '';
      });
      // Clear images and videos
      _productImages = [];
      renderImageGallery();
      _productVideos = [];
      renderVideoGallery();
      _artImages = [];
      renderArtGallery();
      _clientLogo = null;
      renderClientLogo();
      // Apply any category suggested during creation
      if (_pendingWorkbookCategory) {
        const pend = _pendingWorkbookCategory;
        _pendingWorkbookCategory = null;
        if (pend.cat) {
          document.getElementById('product-category').value = pend.cat;
          updateSubcategories();
          if (pend.sub) {
            // Set after updateSubcategories populates the options
            setTimeout(() => {
              const subSel = document.getElementById('product-subcategory');
              if (subSel) {
                subSel.value = pend.sub;
                if (!subSel.value) { // option not found, add it
                  const opt = document.createElement('option');
                  opt.value = pend.sub; opt.textContent = pend.sub;
                  subSel.appendChild(opt);
                  subSel.value = pend.sub;
                }
              }
            }, 50);
          }
        } else {
          document.getElementById('product-category').value = '';
          document.getElementById('product-category-2').value = '';
          document.getElementById('cat2-wrap').classList.remove('has-value');
          document.getElementById('product-subcategory').innerHTML = '<option value="">Select category first...</option>';
          document.getElementById('product-subcategory-2').innerHTML = '<option value="">None</option>';
          document.getElementById('mat2-wrap').classList.remove('has-value');
        }
      } else {
        document.getElementById('product-category').value = '';
        document.getElementById('product-category-2').value = '';
        document.getElementById('cat2-wrap').classList.remove('has-value');
        document.getElementById('product-subcategory').innerHTML = '<option value="">Select category first...</option>';
        document.getElementById('product-subcategory-2').innerHTML = '<option value="">None</option>';
        document.getElementById('mat2-wrap').classList.remove('has-value');
      }
      addTierRow(100); addWbTierRow(100);
      addTierRow(250); addWbTierRow(250);
      addTierRow(500); addWbTierRow(500);
      _selectedTierId = null;
      // Brand-new workbook: clear any stale pitch snap left over from
      // whatever workbook was open before. Without this, the dropdown
      // would still show the synthetic pitch option on the fresh page.
      window._fullContainerPitchSnap = null;
      populateTierDropdown();
      // Seed RFQ with product name only; SKU is entered manually
      document.getElementById('rfq-body').innerHTML = '';
      rfqCount = 0;
      const _newProd = item ? (item.product || '') : '';
      addRfqRow(_newProd, ''); addRfqRow(); addRfqRow();
      recalcRfqTotals();
      // Brand-new workbook: no fees applied yet, no overrides.
      _appliedFees = new Set();
      _appliedFeeOverrides = Object.create(null);
    }

    // Shipping lead times — fall back to typical China→US transit defaults
    // when the workbook has no saved override. Runs in both data and no-data
    // branches so switching between workbooks resets stale values from the
    // previously-loaded workbook.
    const _setLead = (id, val, def) => {
      const el = document.getElementById(id);
      if (el) el.value = (val !== undefined && val !== null && val !== '') ? val : def;
    };
    _setLead('ship-lead-slow',      data?.shipLeadSlow,      '30-40');
    _setLead('ship-lead-fast',      data?.shipLeadFast,      '20-30');
    _setLead('ship-lead-airupp',    data?.shipLeadAirupp,    '7-10');
    _setLead('ship-lead-directair', data?.shipLeadDirectair, '3-5');

    // Per-workbook freight rate overrides. Reset to defaults first
    // so a previous workbook's edits don't leak into this one, then
    // paint the saved values back into the inputs.
    if (typeof _applyFreightRates === 'function') {
      _applyFreightRates(data?.freightRates, true);
    }

    // Render the 3D box previews from the just-loaded dims
    if (typeof renderBoxViz === 'function') {
      renderBoxViz('product');
      renderBoxViz('inner');
      renderBoxViz('outer');
    }

    // Trigger filled state on all inputs
    document.querySelectorAll('#view-workbook input, #view-workbook textarea').forEach(el => updateFilled(el));

    const prodName = document.getElementById('product-name').value || 'Workbook';
    document.getElementById('header-title').textContent = clientName + ' — ' + prodName;
    updateSidebarActive(clientName);
    fillQuoteInvoice(clientName, prodName);
    showView('view-workbook');
    addRecentNav({ type: 'workbook', label: prodName, sub: clientName, href: `#/client/${encodeURIComponent(clientName)}/workbook/${workbookId}` });
    calcFreight();
    // Delay clearing _filling to let queued input events (from calcFreight etc.) fire while still blocked
    setTimeout(() => {
      _filling = false;
      // Wire up presence focus tracking now that the RFQ table is populated
      _initPresenceFocusTracking();
      // Re-apply lock after all dynamic rows (RFQ, tiers) have been added
      if (_wbLocked) lockWorkbookTab(true);
      // Update promote button to show "X SKUs in Inventory" if already promoted
      updatePromoteButton();
      // Collapse the data-heavy sections so the operator lands on a
      // clean Product Overview view, then populate the inline summary
      // line on each collapsed header so the key numbers are visible
      // without expanding.
      _collapseHeavySectionsOnOpen();
      _updateAllSectionSummaries();
      // Wrap any [data-rich] textarea in the formatting / AI toolbar.
      // Idempotent — safe to re-call when switching workbooks.
      if (typeof initRichEditors === 'function') initRichEditors();
      // Disable browser autofill on every workbook input so Chrome
      // doesn't dump saved usernames/passwords (e.g. "Parker Low") into
      // random text fields (Sale Per, Quantity, dimensions, video URL,
      // etc.). autocomplete="off" alone is unreliable, so we layer:
      //   1. HTML-level attributes (autocomplete/data-1p-ignore/etc.)
      //   2. A scrub pass that clears any value matching the session
      //      display name (Chrome autofill leaves it behind).
      //   3. A delayed re-scrub at 600ms because some autofill kicks in
      //      AFTER the initial paint, AFTER our first sweep.
      try {
        const wbView = document.getElementById('view-workbook');
        const sessName = (window.MS_SESSION && (window.MS_SESSION.name || window.MS_SESSION.display_name)) || '';
        const sessUser = (window.MS_SESSION && window.MS_SESSION.username) || '';
        // IDs that genuinely could legitimately contain the user's name
        // (e.g. CTA-name fields). Empty list — the workbook never stores
        // the session user's name in a data field, so any match is garbage.
        const allowList = new Set([]);
        const _scrubAutofill = () => {
          if (!wbView) return;
          wbView.querySelectorAll('input, textarea, select').forEach(el => {
            if (el.type === 'checkbox' || el.type === 'radio' || el.type === 'file') return;
            // Layer 1 — anti-autofill markup (idempotent)
            if (!el.hasAttribute('autocomplete')) el.setAttribute('autocomplete', 'off');
            if (!el.hasAttribute('autocorrect'))  el.setAttribute('autocorrect', 'off');
            if (!el.hasAttribute('spellcheck'))   el.setAttribute('spellcheck', 'false');
            if (!el.hasAttribute('data-1p-ignore')) el.setAttribute('data-1p-ignore', 'true');
            if (!el.hasAttribute('data-lpignore'))  el.setAttribute('data-lpignore', 'true');
            if (!el.hasAttribute('data-form-type')) el.setAttribute('data-form-type', 'other');
            // Layer 2 — clear values that are obvious autofill leftovers
            if (el.tagName === 'INPUT' && typeof el.value === 'string' && el.value) {
              const v = el.value.trim();
              if (allowList.has(el.id)) return;
              const isUserName = sessName && v.toLowerCase() === sessName.toLowerCase();
              const isUserId   = sessUser && v.toLowerCase() === sessUser.toLowerCase();
              if (isUserName || isUserId) {
                el.value = '';
                // fire input so any autosave debouncer notices the clear
                try { el.dispatchEvent(new Event('input', { bubbles: true })); } catch (_) {}
              }
            }
          });
          // The video URL input is an entry-only buffer — workbook load
          // never writes to it. If it has any value at this point, it
          // is browser autofill garbage. Always clear it.
          const vid = document.getElementById('videoUrlInput');
          if (vid && vid.value) vid.value = '';
        };
        _scrubAutofill();
        // Chrome's autofill sometimes runs AFTER our first sweep — re-check.
        setTimeout(_scrubAutofill, 600);
        setTimeout(_scrubAutofill, 1500);
      } catch (e) { /* best-effort — never block the workbook from loading */ }
      // One-shot autosave after _filling clears so cache fields written
      // during the initial render pass (pricingProductCostUsd,
      // pricingShippingCostUsd, pricingGrandTotalCost,
      // pricingShipmentWeightKg, pricingShipmentCbm) reach detail_json
      // without requiring an input event. Without this, opening a
      // workbook recomputes the in-memory caches but they stay un-
      // persisted unless the operator types something — which is why
      // the Orders page kept showing stale fallback numbers after the
      // cache schema changed.
      if (typeof autoSaveWorkbook === 'function') autoSaveWorkbook();
    }, 200);
  }  // end _fillWorkbookInner

  function syncClientDataName(client, workbookId, detail) {
    const items = clientData[client] || [];
    const item = items.find(i => i.id === parseInt(workbookId));
    if (item && detail.product) {
      item.product = detail.product;
      item.description = detail.desc || item.description;
    }
  }

  /* ── Workbook client dropdown ─────────────────────────────────────────
     The Client field in Product Overview is a <select> so the operator
     can either confirm the active client or move the workbook to a
     different one. Repopulated on workbook open so the option list
     stays in sync with the sidebar. */
  function populateClientNameSelect(selected) {
    const sel = document.getElementById('client-name');
    if (!sel || sel.tagName !== 'SELECT') return;
    const names = Object.keys(clientData || {}).sort((a, b) => a.localeCompare(b));
    // Build options — keep the current value selected even if it isn't
    // in the client list yet (e.g. after a fresh sidebar reload before
    // clientData is fully hydrated).
    const opts = ['<option value="">Select a client…</option>'];
    let hasSelected = false;
    names.forEach(n => {
      const isSel = n === selected;
      if (isSel) hasSelected = true;
      const safe = n.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
      opts.push(`<option value="${safe}"${isSel ? ' selected' : ''}>${safe}</option>`);
    });
    if (selected && !hasSelected) {
      const safe = selected.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
      opts.push(`<option value="${safe}" selected>${safe}</option>`);
    }
    sel.innerHTML = opts.join('');
    // Cache the on-load value so we know what to revert to if the user
    // cancels a move-confirmation prompt.
    sel.dataset.previousClient = selected || '';
  }

  async function onWorkbookClientChange(sel) {
    const newClient = (sel.value || '').trim();
    const prevClient = sel.dataset.previousClient || currentClient || '';
    if (!newClient || newClient === prevClient) {
      return; // no-op (or "Select a client…" placeholder)
    }
    if (!currentWorkbookId) {
      sel.value = prevClient;
      return;
    }
    const productName = (document.getElementById('product-name')?.value || 'this workbook').trim() || 'this workbook';
    const ok = confirm(
      `Move "${productName}" from ${prevClient || '(no client)'} to ${newClient}?\n\n` +
      `The workbook will move into ${newClient}'s list. This is reversible — you can move it back the same way.`
    );
    if (!ok) {
      sel.value = prevClient;
      return;
    }
    // Persist any in-flight edits before the move so we don't lose them
    // when the workbook detail is reloaded under the new client key.
    try { if (typeof autoSaveWorkbook === 'function') await autoSaveWorkbook(); } catch (_) {}

    const wbDbId = dbWorkbookMap[`${prevClient}|${currentWorkbookId}`] || currentWorkbookId;
    const r = await apiCall('move_workbook', { id: wbDbId, target_client: newClient });
    if (!r || !r.success) {
      alert(r && r.error ? r.error : 'Failed to move workbook. Please try again.');
      sel.value = prevClient;
      return;
    }
    // Refresh client + workbook caches so the sidebar reflects the move,
    // then navigate to the new (client, workbook) pair.
    try { await loadFromDatabase(); } catch (_) {}
    if (typeof rebuildSidebar === 'function') rebuildSidebar();
    const newWbId = r.new_workbook_id || currentWorkbookId;
    location.hash = `#/client/${encodeURIComponent(newClient)}/workbook/${newWbId}`;
    if (typeof showToast === 'function') {
      showToast(`Moved "${productName}" to ${newClient}`, 'success');
    }
  }

  function getCurrentUser() {
    return (window.MS_SESSION && window.MS_SESSION.name) ? window.MS_SESSION.name : (localStorage.getItem('ms_user_name') || '');
  }

  function saveCurrentWorkbookIfOpen() {
    // No _appReady check here — navigation saves must always fire
    if (!currentClient || !currentWorkbookId) return;
    clearTimeout(saveTimer);
    const detail = collectWorkbookDetail();
    const key = `${currentClient}|${currentWorkbookId}`;
    workbookDetail[key] = detail;
    syncClientDataName(currentClient, currentWorkbookId, detail);
    const dbId = dbWorkbookMap[key] || currentWorkbookId;
    showSaveStatus('saving');
    // create_revision: true on navigation saves — these become history entries
    apiCall('save_workbook_detail', { id: dbId, detail: detail, changed_by: getCurrentUser(), create_revision: true })
      .then(r => showSaveStatus(r && r.success ? 'saved' : 'error'));
    saveToLocalStorage();
  }

  function showSaveStatus(state) {
    const el = document.getElementById('save-status');
    if (!el) return;
    el.textContent = state === 'saving' ? 'Saving…' : state === 'saved' ? 'Saved ✓' : 'Save failed';
    el.style.color = state === 'error' ? 'var(--danger)' : state === 'saved' ? 'var(--success)' : 'var(--text-muted)';
    el.style.opacity = '1';
    if (state !== 'saving') setTimeout(() => { el.style.opacity = '0'; }, 2500);
  }

  /* ── Samples Dashboard ────────────────────────────────────────────────── */
  const SAMPLE_STATUSES = ['pending', 'requested', 'received', 'approved'];
  const SAMPLE_STATUS_LABELS = { pending: 'Pending', requested: 'Requested', received: 'Received', approved: 'Approved' };
  const SAMPLE_STATUS_COLORS = {
    pending:   { bg: 'rgba(107,147,255,0.12)', border: 'rgba(107,147,255,0.4)', text: '#6b93ff' },
    requested: { bg: 'rgba(251,175,52,0.12)',  border: 'rgba(251,175,52,0.4)', text: '#f59e0b' },
    received:  { bg: 'rgba(74,222,128,0.12)',  border: 'rgba(74,222,128,0.4)', text: '#4ade80' },
    approved:  { bg: 'rgba(52,211,153,0.12)',  border: 'rgba(52,211,153,0.4)', text: '#34d399' },
  };

  // sampleMeta is stored alongside rfqItems: sampleStatuses[rowIndex] = 'pending'|'received' etc.
  let _samplesFilter = 'all';

  function collectAllSamples() {
    const results = [];
    for (const [key, detail] of Object.entries(workbookDetail)) {
      if (!detail || !detail.rfqItems) continue;
      const [clientName, workbookId] = key.split('|');
      detail.rfqItems.forEach((item, idx) => {
        if (!item.sample) return;
        const status = (detail.sampleStatuses && detail.sampleStatuses[idx]) || 'pending';
        const usdPrice = item.priceRmb ? (parseFloat(item.priceRmb) / USD_TO_RMB).toFixed(2) : '';
        results.push({
          clientName,
          workbookId,
          product: detail.product || 'Untitled',
          item: item.item || '—',
          qty: item.qty || '—',
          priceRmb: item.priceRmb || '',
          priceUsd: usdPrice,
          leadTime: item.leadTime || '',
          status,
          rowIndex: idx,
          key
        });
      });
    }
    return results;
  }

  function renderSamplesDashboard() {
    document.getElementById('header-title').textContent = 'Sample Requests';
    document.querySelectorAll('.sidebar-nav .nav-item').forEach(a => a.classList.remove('active'));
    document.querySelectorAll('.nav-flat-link').forEach(a => a.classList.remove('active'));
    const samplesNav = document.getElementById('nav-samples-link');
    if (samplesNav) samplesNav.classList.add('active');
    showView('view-samples');

    const allSamples = collectAllSamples();

    // Update count badge
    const countBadge = document.getElementById('samples-count-badge');
    if (countBadge) countBadge.textContent = allSamples.length === 1 ? '1 sample' : `${allSamples.length} samples`;

    // Update samples badge in nav (delegate to canonical function for consistent logic)
    rebuildSamplesNav();

    // Stats row
    const statsRow = document.getElementById('samples-stats-row');
    if (statsRow) {
      const counts = { pending: 0, requested: 0, received: 0, approved: 0 };
      allSamples.forEach(s => { if (counts[s.status] !== undefined) counts[s.status]++; });
      const statCards = [
        { label: 'Total Samples', value: allSamples.length, icon: '◆', color: 'var(--accent)' },
        { label: 'Pending', value: counts.pending, icon: '⏳', color: '#6b93ff' },
        { label: 'Requested', value: counts.requested, icon: '📦', color: '#f59e0b' },
        { label: 'Received', value: counts.received, icon: '✅', color: '#4ade80' },
        { label: 'Approved', value: counts.approved, icon: '🎉', color: '#34d399' },
      ];
      statsRow.innerHTML = statCards.map(c => `
        <div style="background:var(--surface2); border:1px solid var(--border); border-radius:var(--radius); padding:14px 16px;">
          <div style="font-size:20px; font-weight:700; color:${c.color}; line-height:1.1;">${c.value}</div>
          <div style="font-size:11px; color:var(--text-muted); text-transform:uppercase; letter-spacing:0.05em; margin-top:3px;">${c.label}</div>
        </div>
      `).join('');
    }

    renderSamplesTable(allSamples);
  }

  function renderSamplesTable(allSamples) {
    const tbody = document.getElementById('samples-tbody');
    const emptyEl = document.getElementById('samples-empty');
    const tableEl = document.getElementById('samples-table');

    const filtered = _samplesFilter === 'all' ? allSamples : allSamples.filter(s => s.status === _samplesFilter);

    if (filtered.length === 0) {
      tbody.innerHTML = '';
      if (emptyEl) emptyEl.style.display = '';
      if (tableEl) tableEl.style.display = 'none';
      return;
    }
    if (emptyEl) emptyEl.style.display = 'none';
    if (tableEl) tableEl.style.display = '';

    // String-escape HTML inputs so client/product names containing < & " etc.
    // can't break the markup or open injection holes via the title= attr.
    const esc = v => String(v == null ? '' : v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');

    tbody.innerHTML = filtered.map((s, i) => {
      const sc = SAMPLE_STATUS_COLORS[s.status] || SAMPLE_STATUS_COLORS.pending;
      const wbHref     = `#/client/${encodeURIComponent(s.clientName)}/workbook/${s.workbookId}`;
      const clientHref = `#/client/${encodeURIComponent(s.clientName)}`;
      const rmb = s.priceRmb ? `¥${parseFloat(s.priceRmb).toLocaleString('en-US', {minimumFractionDigits:2, maximumFractionDigits:2})}` : '—';
      const usd = s.priceUsd ? `$${parseFloat(s.priceUsd).toLocaleString('en-US', {minimumFractionDigits:2, maximumFractionDigits:2})}` : '—';
      const lead = s.leadTime ? `${s.leadTime}d` : '—';
      // Client → deterministic per-name color via _clientChipStyle (same hue
      // every render). Now clickable so users can drill into the client.
      const clientPill = `<span class="inv-client-chip" style="${_clientChipStyle(s.clientName)}"
          onclick="event.stopPropagation(); location.hash='${clientHref.substring(1)}'"
          title="${esc(s.clientName)}">${esc(s.clientName)}</span>`;
      // Workbook → existing accent-blue pill with arrow, drills into the workbook.
      const wbPill = `<span class="inv-wb-pill" onclick="event.stopPropagation(); location.hash='${wbHref.substring(1)}'"
          title="${esc(s.product)}" style="max-width:100%; min-width:0;"
          ><span class="inv-wb-pill-text">${esc(s.product)}</span><span class="inv-wb-pill-arrow">→</span></span>`;
      return `
        <tr>
          <td style="font-weight:600; color:var(--text);" title="${esc(s.item)}">${esc(s.item)}</td>
          <td class="samples-pill-cell">${clientPill}</td>
          <td class="samples-pill-cell">${wbPill}</td>
          <td style="text-align:right; font-weight:600;">${s.qty !== '—' ? parseFloat(s.qty).toLocaleString('en-US') : '—'}</td>
          <td style="text-align:right;">${rmb}</td>
          <td style="text-align:right; color:var(--success);">${usd}</td>
          <td style="color:var(--text-muted);">${lead}</td>
          <td style="text-align:center;">
            <select class="sample-status-sel" onchange="updateSampleStatus('${s.key}', ${s.rowIndex}, this.value)"
              style="background:${sc.bg}; border:1px solid ${sc.border}; color:${sc.text}; border-radius:20px; padding:3px 8px; font-size:11px; font-weight:600; cursor:pointer; outline:none; -webkit-appearance:none; text-align:center; max-width:100%;">
              ${SAMPLE_STATUSES.map(st => `<option value="${st}" ${st === s.status ? 'selected' : ''}>${SAMPLE_STATUS_LABELS[st]}</option>`).join('')}
            </select>
          </td>
          <td style="text-align:center;">
            <span class="remove-tier" onclick="removeSampleRequest('${s.key}', ${s.rowIndex})" title="Unmark as sample (keeps the RFQ line item, just removes it from this list)" style="font-size:18px; color:var(--text-muted);">&times;</span>
          </td>
        </tr>
      `;
    }).join('');
  }

  function updateSampleStatus(key, rowIndex, newStatus) {
    if (!workbookDetail[key]) return;
    if (!workbookDetail[key].sampleStatuses) workbookDetail[key].sampleStatuses = {};
    workbookDetail[key].sampleStatuses[rowIndex] = newStatus;
    // Save to DB
    const [clientName, workbookId] = key.split('|');
    const dbId = dbWorkbookMap[key] || workbookId;
    apiCall('save_workbook_detail', { id: dbId, detail: workbookDetail[key], changed_by: getCurrentUser() });
    saveToLocalStorage();
    // Re-render table and stats
    const freshSamples = collectAllSamples();
    renderSamplesTable(freshSamples);
    rebuildSamplesNav();
    // Update count badge
    const countBadge = document.getElementById('samples-count-badge');
    if (countBadge) countBadge.textContent = freshSamples.length === 1 ? '1 sample' : `${freshSamples.length} samples`;
  }

  // Remove a sample row directly from the Samples dashboard. We keep the
  // underlying RFQ line item intact (in case the operator just wanted to
  // un-flag it as a sample without deleting the row from the workbook),
  // and clear the saved status entry too. Persists to the DB.
  function removeSampleRequest(key, rowIndex) {
    const detail = workbookDetail[key];
    if (!detail || !detail.rfqItems || !detail.rfqItems[rowIndex]) return;
    if (!confirm('Remove this sample request? The RFQ line item stays in the workbook — only the sample flag clears.')) return;
    detail.rfqItems[rowIndex].sample = false;
    if (detail.sampleStatuses) {
      delete detail.sampleStatuses[rowIndex];
    }
    const [, workbookId] = key.split('|');
    const dbId = dbWorkbookMap[key] || workbookId;
    apiCall('save_workbook_detail', { id: dbId, detail, changed_by: getCurrentUser() });
    saveToLocalStorage();
    // If the workbook is open in the workbook view, sync the checkbox
    // visually so it updates without a reload.
    const openKey = (typeof currentClient !== 'undefined' && typeof currentWorkbookId !== 'undefined')
      ? `${currentClient}|${currentWorkbookId}` : null;
    if (openKey === key) {
      const rfqRows = document.querySelectorAll('#rfq-body tr:not([data-rfq-parent]):not([data-rfq-add-for])');
      const targetRow = rfqRows[rowIndex];
      if (targetRow) {
        const cb = targetRow.querySelector('.rfq-sample-check');
        if (cb && cb.checked) { cb.checked = false; toggleRfqSample(cb); }
      }
    }
    const freshSamples = collectAllSamples();
    renderSamplesTable(freshSamples);
    rebuildSamplesNav();
    const countBadge = document.getElementById('samples-count-badge');
    if (countBadge) countBadge.textContent = freshSamples.length === 1 ? '1 sample' : `${freshSamples.length} samples`;
  }

  function filterSamples(filter, btn) {
    _samplesFilter = filter;
    document.querySelectorAll('#view-samples .status-filter-btn').forEach(b => b.classList.remove('active'));
    if (btn) btn.classList.add('active');
    renderSamplesTable(collectAllSamples());
  }

  /* ── RFQ Queue ───────────────────────────────────────────────────────────── */

  // A workbook belongs in the RFQ queue when:
  //  - user clicked "RFQ" to send it (sentToRfq flag on detail)
  //  - status is still at Quote Submitted (not yet advanced to Quote to Client)
  //  - Karen hasn't pushed it back for review yet (sentForReview === false).
  //    Once she clicks Send for Review the workbook moves to the Ready-
  //    for-Review queue and drops out of here, even though the flow_step
  //    is still 1 (Karen's action doesn't auto-advance the flow per the
  //    operator's UX direction — the reviewer advances manually).
  function collectAllRfqs() {
    const results = [];
    for (const [key, detail] of Object.entries(workbookDetail)) {
      if (!detail || !detail.sentToRfq) continue;
      if (detail.sentForReview) continue;
      const [clientName, workbookId] = key.split('|');
      // Only include if flow is still at quoteSubmitted (not advanced past)
      const items = clientData[clientName] || [];
      const item = items.find(i => String(i.id) === String(workbookId));
      if (!item || !item.flow) continue;
      if (!item.flow.quoteSubmitted || item.flow.quoteClient) continue;

      // Aggregate totals across RFQ line items (parents + variants)
      const rfqItems = (detail.rfqItems || []).concat(
        (detail.rfqItems || []).flatMap(r => r.variants || [])
      );
      let totalQty = 0, totalRmb = 0;
      rfqItems.forEach(r => {
        const q = parseFloat(r.qty) || 0;
        const p = parseFloat(r.priceRmb) || 0;
        totalQty += q;
        totalRmb += q * p;
      });
      const totalUsd = totalRmb / USD_TO_RMB;

      results.push({
        clientName,
        workbookId,
        key,
        product: detail.product || 'Untitled',
        sentToRfqAt: detail.sentToRfqAt || null,
        lineItems: (detail.rfqItems || []).length,
        totalQty,
        totalRmb,
        totalUsd,
      });
    }
    // Oldest first
    results.sort((a, b) => {
      const at = a.sentToRfqAt ? new Date(a.sentToRfqAt).getTime() : 0;
      const bt = b.sentToRfqAt ? new Date(b.sentToRfqAt).getTime() : 0;
      return at - bt;
    });
    return results;
  }

  function rebuildRfqNav() {
    const all = collectAllRfqs();
    // No "actionable vs remaining" distinction here — every RFQ is actionable for Karen
    _applyNavBadge(document.getElementById('badge-rfq'), 0, all.length);
  }

  function _rfqTimeAgo(iso) {
    if (!iso) return '—';
    const then = new Date(iso).getTime();
    if (isNaN(then)) return '—';
    const secs = Math.max(0, (Date.now() - then) / 1000);
    if (secs < 60)     return 'just now';
    if (secs < 3600)   return `${Math.floor(secs/60)}m ago`;
    if (secs < 86400)  return `${Math.floor(secs/3600)}h ago`;
    if (secs < 604800) return `${Math.floor(secs/86400)}d ago`;
    const d = new Date(iso);
    return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
  }

  function renderRfqDashboard() {
    document.getElementById('header-title').textContent = 'RFQ Queue';
    document.querySelectorAll('.sidebar-nav .nav-item').forEach(a => a.classList.remove('active'));
    document.querySelectorAll('.nav-flat-link').forEach(a => a.classList.remove('active'));
    const rfqNav = document.getElementById('nav-rfq-link');
    if (rfqNav) rfqNav.classList.add('active');
    showView('view-rfq');

    const all = collectAllRfqs();

    const countBadge = document.getElementById('rfq-count-badge');
    if (countBadge) countBadge.textContent = all.length === 1 ? '1 RFQ' : `${all.length} RFQs`;
    rebuildRfqNav();

    // Stats
    const statsRow = document.getElementById('rfq-stats-row');
    if (statsRow) {
      const totalLineItems = all.reduce((n, r) => n + r.lineItems, 0);
      const totalQty       = all.reduce((n, r) => n + r.totalQty, 0);
      const totalRmb       = all.reduce((n, r) => n + r.totalRmb, 0);
      const totalUsd       = all.reduce((n, r) => n + r.totalUsd, 0);
      const statCards = [
        { label: 'In Queue', value: all.length, color: 'var(--accent)' },
        { label: 'Line Items', value: totalLineItems, color: '#6b93ff' },
        { label: 'Total Qty', value: totalQty.toLocaleString('en-US'), color: '#f59e0b' },
        { label: 'Total (RMB)', value: `¥${Math.round(totalRmb).toLocaleString('en-US')}`, color: '#ef4444' },
        { label: 'Total (USD)', value: `$${totalUsd.toLocaleString('en-US', {minimumFractionDigits:2, maximumFractionDigits:2})}`, color: '#10b981' },
      ];
      statsRow.innerHTML = statCards.map(c => `
        <div style="background:var(--surface2); border:1px solid var(--border); border-radius:var(--radius); padding:14px 16px;">
          <div style="font-size:20px; font-weight:700; color:${c.color}; line-height:1.1;">${c.value}</div>
          <div style="font-size:11px; color:var(--text-muted); text-transform:uppercase; letter-spacing:0.05em; margin-top:3px;">${c.label}</div>
        </div>
      `).join('');
    }

    renderRfqTable(all);
  }

  function renderRfqTable(all) {
    const tbody   = document.getElementById('rfq-tbody');
    const emptyEl = document.getElementById('rfq-empty');
    const tableEl = document.getElementById('rfq-table');
    if (!tbody) return;

    if (all.length === 0) {
      tbody.innerHTML = '';
      if (emptyEl) emptyEl.style.display = '';
      if (tableEl) tableEl.style.display = 'none';
      return;
    }
    if (emptyEl) emptyEl.style.display = 'none';
    if (tableEl) tableEl.style.display = '';

    tbody.innerHTML = all.map(r => {
      const wbHref = `#/client/${encodeURIComponent(r.clientName)}/workbook/${r.workbookId}`;
      const rmb = r.totalRmb > 0 ? `¥${Math.round(r.totalRmb).toLocaleString('en-US')}` : '—';
      const usd = r.totalUsd > 0 ? `$${r.totalUsd.toLocaleString('en-US', {minimumFractionDigits:2, maximumFractionDigits:2})}` : '—';
      // Whole row is the affordance to open the workbook so Karen can
      // edit it. Client name is intentionally non-navigable here — the
      // RFQ Queue is a workspace, not a client-browsing surface.
      const clientEsc  = String(r.clientName || '').replace(/'/g, "\\'");
      const productEsc = String(r.product || '').replace(/'/g, "\\'");
      return `
        <tr class="rfq-row" style="cursor:pointer;" onclick="location.hash='${wbHref.substring(1)}'">
          <td><span class="rfq-client-name" title="${clientEsc}">${r.clientName}</span></td>
          <td style="font-weight:600; color:var(--text); overflow:hidden; text-overflow:ellipsis; white-space:nowrap;">${r.product}<span style="font-size:11px; color:var(--text-muted); margin-left:8px; font-weight:500;">→ open</span></td>
          <td style="color:var(--text-muted); font-size:12px;" title="${r.sentToRfqAt || ''}">${_rfqTimeAgo(r.sentToRfqAt)}</td>
          <td style="text-align:right;">${r.lineItems}</td>
          <td style="text-align:right; font-weight:600;">${r.totalQty.toLocaleString('en-US')}</td>
          <td style="text-align:right; white-space:nowrap;">${rmb}</td>
          <td style="text-align:right; white-space:nowrap; color:var(--success);">${usd}</td>
          <td style="text-align:right;">
            <button class="btn rfq-review-btn"
              onclick="event.stopPropagation(); submitWorkbookForReview(${r.workbookId}, '${clientEsc}', '${productEsc}', this);"
              title="Mark as ready for review — advances the workbook out of the queue and emails Jackson + Parker."
              style="font-size:11px; padding:5px 11px; white-space:nowrap; background:var(--accent); color:#fff; border:none; border-radius:6px; cursor:pointer; font-weight:600;">
              Send for Review
            </button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // Hover affordance for the now-clickable RFQ Queue rows. Adds a
  // subtle background tint so it's obvious the row is the click target.
  (function _injectRfqRowHoverCss() {
    if (document.getElementById('rfq-row-hover-style')) return;
    const s = document.createElement('style');
    s.id = 'rfq-row-hover-style';
    s.textContent = `
      .rfq-row:hover { background: rgba(110, 140, 255, 0.05); }
      .rfq-row:hover td { color: var(--text); }
      .rfq-review-btn:hover { opacity: 0.9; }
      .rfq-review-btn:disabled { opacity: 0.5; cursor: not-allowed; }
    `;
    document.head.appendChild(s);
  })();

  // Per-row "Send for Review" action on the RFQ Queue. Tells the server
  // to advance this workbook past quoteSubmitted (so it leaves the queue)
  // and email the internal review list (Jackson + Parker). The button
  // disables itself + shows a spinner while the request is in flight so
  // double-clicks don't fire twice.
  async function submitWorkbookForReview(workbookId, clientName, productName, btn) {
    if (!workbookId) return;
    if (btn) { btn.disabled = true; const old = btn.textContent; btn.dataset.oldLabel = old; btn.textContent = 'Sending…'; }
    try {
      const res = await apiCall('submit_for_review', {
        workbook_id: workbookId,
        client_name: clientName || '',
        product_name: productName || '',
      });
      if (res && res.success) {
        if (btn) {
          btn.textContent = res.re_sent ? 'Re-sent ✓' : 'Sent ✓';
          btn.style.background = 'var(--success, #10b981)';
          btn.style.color = '#fff';
        }
        // Refresh the queue so the row drops out (workbook advanced
        // past quoteSubmitted → no longer qualifies).
        if (typeof renderRfqDashboard === 'function') {
          setTimeout(renderRfqDashboard, 600);
        }
      } else {
        alert((res && res.error) ? res.error : 'Couldn\'t send for review — try again.');
        if (btn) { btn.disabled = false; btn.textContent = btn.dataset.oldLabel || 'Send for Review'; }
      }
    } catch (e) {
      console.error('[submitWorkbookForReview]', e);
      alert('Network error sending for review — try again.');
      if (btn) { btn.disabled = false; btn.textContent = btn.dataset.oldLabel || 'Send for Review'; }
    }
  }

  // Toggle current workbook's sentToRfq state — called from the RFQ button on status bar
  async function toggleSendToRfq() {
    if (!currentClient || !currentWorkbookId) return;
    const key = `${currentClient}|${currentWorkbookId}`;

    // Once sent, the button is one-shot until the operator uses the
    // back button (←) on the status bar to revert. Defense-in-depth
    // for the disabled attribute set in renderStatusBar — scripted
    // clicks / accessibility tooling shouldn't be able to re-fire.
    const existingDetail = workbookDetail[key] || {};
    if (existingDetail.sentToRfq) return;

    // Collect fresh DOM state so we never overwrite the DB record with a stale/partial detail.
    // collectWorkbookDetail now preserves sentToRfq/sentToRfqAt from the existing entry,
    // so we set the new flags AFTER collecting.
    let detail;
    try { detail = collectWorkbookDetail(); }
    catch(e) {
      console.error('[RFQ] collectWorkbookDetail failed, falling back to existing detail', e);
      detail = Object.assign({}, existingDetail);
    }
    const turningOn = !detail.sentToRfq;
    detail.sentToRfq   = turningOn;
    detail.sentToRfqAt = turningOn ? new Date().toISOString() : null;
    workbookDetail[key] = detail;

    // Persist to DB (fire-and-forget) + localStorage
    try {
      const dbId = dbWorkbookMap[key] || currentWorkbookId;
      apiCall('save_workbook_detail', { id: dbId, detail, changed_by: getCurrentUser() });
    } catch(e) { console.error('[RFQ] save failed', e); }
    saveToLocalStorage();

    // Reflect in nav + button state
    try { rebuildRfqNav(); } catch(e) { console.error('[RFQ] rebuildRfqNav failed', e); }
    try { rebuildReviewNav(); } catch (_) {}
    const items = clientData[currentClient];
    const item = items ? items.find(i => i.id === parseInt(currentWorkbookId)) : null;
    if (item) renderStatusBar(item.flow);
  }

  // Called from the in-workbook "Send for Review" button. Same backend
  // action as the RFQ Queue button — submit_for_review advances the
  // flow past quoteSubmitted (so the workbook leaves the queue) and
  // emails Jackson + Parker that it's ready for review.
  async function submitCurrentWorkbookForReview() {
    if (!currentClient || !currentWorkbookId) return;
    const key = `${currentClient}|${currentWorkbookId}`;
    const detail = workbookDetail[key] || {};
    // One-shot per stage 1 — operator goes back via ← to re-enable.
    // Defense-in-depth for the disabled attribute on the button.
    if (detail.sentForReview) return;
    const productName = detail.product || document.getElementById('product-name')?.value || '';
    const btn = document.getElementById('btn-submit-review');
    const labelEl = document.getElementById('btn-submit-review-label');
    const dbId = dbWorkbookMap[key] || currentWorkbookId;
    // Update only the label span so the SVG icons in the button aren't
    // wiped out. Same idea applies to the error / final-state paths
    // below — we touch labelEl.textContent, never btn.textContent.
    if (btn && labelEl) { btn.disabled = true; btn.dataset.oldLabel = labelEl.textContent; labelEl.textContent = 'Sending…'; }
    try {
      // Make sure the latest edits land in detail_json before we mark
      // the workbook ready — otherwise Karen's review request would
      // ship the pre-edit state to Jackson + Parker.
      try {
        const liveDetail = collectWorkbookDetail();
        workbookDetail[key] = liveDetail;
        await apiCall('save_workbook_detail', { id: dbId, detail: liveDetail, changed_by: getCurrentUser() });
      } catch (e) { console.error('[submitForReview] save failed', e); }

      const res = await apiCall('submit_for_review', {
        workbook_id: dbId,
        client_name: currentClient,
        product_name: productName,
      });
      if (res && res.success) {
        // Persist the Sent state so the button stays in its 'Sent ✓'
        // form across reloads instead of reverting to the outlined
        // ready state. The server has its own JSON_SET fallback for
        // the RFQ Queue per-row path; this branch covers the
        // in-workbook click + writes a fresh detail save with the
        // flag so the local cache is consistent immediately.
        const det = workbookDetail[key] || {};
        det.sentForReview   = true;
        det.sentForReviewAt = new Date().toISOString();
        workbookDetail[key] = det;
        try { apiCall('save_workbook_detail', { id: dbId, detail: det, changed_by: getCurrentUser() }); } catch (_) {}

        // Refresh the status bar so the advance applies + the button
        // re-renders into its 'Sent ✓' state (NOT hidden — the
        // visibility rule keeps it on screen across the full review
        // window now).
        const items = clientData[currentClient];
        const itemRow = items ? items.find(i => i.id === parseInt(currentWorkbookId)) : null;
        if (itemRow && res.flow) { itemRow.flow = res.flow; renderStatusBar(itemRow.flow); }
        try { rebuildRfqNav(); } catch (_) {}
        try { rebuildReviewNav(); } catch (_) {}
      } else {
        alert((res && res.error) ? res.error : 'Couldn\'t send for review — try again.');
        if (btn) {
          btn.disabled = false;
          if (labelEl) labelEl.textContent = btn.dataset.oldLabel || 'Send for Review';
        }
      }
    } catch (e) {
      console.error('[submitCurrentWorkbookForReview]', e);
      alert('Network error sending for review — try again.');
      if (btn) {
        btn.disabled = false;
        if (labelEl) labelEl.textContent = btn.dataset.oldLabel || 'Send for Review';
      }
    }
  }

  /* ── Ready-for-Review Queue ──────────────────────────────────────────── */

  // A workbook belongs in the Ready-for-Review queue when:
  //   • Karen has pressed Send for Review (detail.sentForReview === true)
  //   • The reviewer hasn't manually advanced the flow past Quote
  //     Submitted yet (flow.quoteClient === false).
  // Send for Review does NOT auto-advance the flow_step — the reviewer
  // advances the status bar manually after they've looked at the
  // workbook, which is what drops it out of this queue.
  function collectAllReadyForReview() {
    const results = [];
    for (const [key, detail] of Object.entries(workbookDetail)) {
      if (!detail || !detail.sentForReview) continue;
      const [clientName, workbookId] = key.split('|');
      const items = clientData[clientName] || [];
      const item = items.find(i => String(i.id) === String(workbookId));
      if (!item || !item.flow) continue;
      // Out of queue once the reviewer has advanced past Quote
      // Submitted (i.e. quoteClient is true) OR if anything stomped
      // the flow further along the chain.
      if (item.flow.quoteClient || item.flow.clientApproved) continue;

      // Aggregate RFQ totals — same as the RFQ Queue collector so the
      // numbers tie out across both views for the same workbook.
      const rfqItems = (detail.rfqItems || []).concat(
        (detail.rfqItems || []).flatMap(r => r.variants || [])
      );
      let totalQty = 0, totalRmb = 0;
      rfqItems.forEach(r => {
        const q = parseFloat(r.qty) || 0;
        const p = parseFloat(r.priceRmb) || 0;
        totalQty += q;
        totalRmb += q * p;
      });
      const totalUsd = totalRmb / USD_TO_RMB;

      results.push({
        clientName,
        workbookId,
        key,
        product: detail.product || 'Untitled',
        sentForReviewAt: detail.sentForReviewAt || null,
        lineItems: (detail.rfqItems || []).length,
        totalQty,
        totalRmb,
        totalUsd,
      });
    }
    // Oldest first — reviewer addresses the longest-waiting workbook next.
    results.sort((a, b) => {
      const at = a.sentForReviewAt ? new Date(a.sentForReviewAt).getTime() : 0;
      const bt = b.sentForReviewAt ? new Date(b.sentForReviewAt).getTime() : 0;
      return at - bt;
    });
    return results;
  }

  function rebuildReviewNav() {
    const all = collectAllReadyForReview();
    _applyNavBadge(document.getElementById('badge-review'), 0, all.length);
  }

  function renderReviewDashboard() {
    document.getElementById('header-title').textContent = 'Ready for Review';
    document.querySelectorAll('.sidebar-nav .nav-item').forEach(a => a.classList.remove('active'));
    document.querySelectorAll('.nav-flat-link').forEach(a => a.classList.remove('active'));
    const navLink = document.getElementById('nav-review-link');
    if (navLink) navLink.classList.add('active');
    showView('view-review');

    const all = collectAllReadyForReview();

    const countBadge = document.getElementById('review-count-badge');
    if (countBadge) {
      countBadge.textContent = all.length === 1 ? '1 to review' : `${all.length} to review`;
    }
    rebuildReviewNav();

    // Stats — same shape as RFQ for visual consistency.
    const statsRow = document.getElementById('review-stats-row');
    if (statsRow) {
      const totalLineItems = all.reduce((n, r) => n + r.lineItems, 0);
      const totalQty       = all.reduce((n, r) => n + r.totalQty, 0);
      const totalRmb       = all.reduce((n, r) => n + r.totalRmb, 0);
      const totalUsd       = all.reduce((n, r) => n + r.totalUsd, 0);
      const statCards = [
        { label: 'Awaiting Review', value: all.length, color: '#5b6fcc' },
        { label: 'Line Items', value: totalLineItems, color: '#6b93ff' },
        { label: 'Total Qty', value: totalQty.toLocaleString('en-US'), color: '#f59e0b' },
        { label: 'Total (RMB)', value: `¥${Math.round(totalRmb).toLocaleString('en-US')}`, color: '#ef4444' },
        { label: 'Total (USD)', value: `$${totalUsd.toLocaleString('en-US', {minimumFractionDigits:2, maximumFractionDigits:2})}`, color: '#10b981' },
      ];
      statsRow.innerHTML = statCards.map(c => `
        <div style="background:var(--surface2); border:1px solid var(--border); border-radius:var(--radius); padding:14px 16px;">
          <div style="font-size:20px; font-weight:700; color:${c.color}; line-height:1.1;">${c.value}</div>
          <div style="font-size:11px; color:var(--text-muted); text-transform:uppercase; letter-spacing:0.05em; margin-top:3px;">${c.label}</div>
        </div>
      `).join('');
    }

    renderReviewTable(all);
  }

  function renderReviewTable(all) {
    const tbody   = document.getElementById('review-tbody');
    const emptyEl = document.getElementById('review-empty');
    const tableEl = document.getElementById('review-table');
    if (!tbody) return;

    if (all.length === 0) {
      tbody.innerHTML = '';
      if (emptyEl) emptyEl.style.display = '';
      if (tableEl) tableEl.style.display = 'none';
      return;
    }
    if (emptyEl) emptyEl.style.display = 'none';
    if (tableEl) tableEl.style.display = '';

    tbody.innerHTML = all.map(r => {
      const wbHref = `#/client/${encodeURIComponent(r.clientName)}/workbook/${r.workbookId}`;
      const rmb = r.totalRmb > 0 ? `¥${Math.round(r.totalRmb).toLocaleString('en-US')}` : '—';
      const usd = r.totalUsd > 0 ? `$${r.totalUsd.toLocaleString('en-US', {minimumFractionDigits:2, maximumFractionDigits:2})}` : '—';
      const clientEsc = String(r.clientName || '').replace(/'/g, "\\'");
      return `
        <tr class="review-row" onclick="location.hash='${wbHref.substring(1)}'">
          <td><span class="review-client-name" title="${clientEsc}">${r.clientName}</span></td>
          <td style="font-weight:600; color:var(--text); overflow:hidden; text-overflow:ellipsis; white-space:nowrap;">${r.product}<span style="font-size:11px; color:var(--text-muted); margin-left:8px; font-weight:500;">→ open</span></td>
          <td style="color:var(--text-muted); font-size:12px;" title="${r.sentForReviewAt || ''}">${_rfqTimeAgo(r.sentForReviewAt)}</td>
          <td style="text-align:right;">${r.lineItems}</td>
          <td style="text-align:right; font-weight:600;">${r.totalQty.toLocaleString('en-US')}</td>
          <td style="text-align:right; white-space:nowrap;">${rmb}</td>
          <td style="text-align:right; white-space:nowrap; color:var(--success);">${usd}</td>
        </tr>
      `;
    }).join('');
  }

  function router() {
    hideRecentNav();
    resetSidebarSearch();
    let hash;
    try { hash = decodeURIComponent(location.hash || '#/'); }
    catch(e) { hash = location.hash || '#/'; }

    // Match: #/client/{name}/workbook/{id}
    const wbMatch = hash.match(/^#\/client\/(.+?)\/workbook\/(\d+)$/);
    if (wbMatch) {
      fillWorkbook(wbMatch[1], wbMatch[2]);
      return;
    }

    // Leaving the workbook editor — clear presence immediately
    stopPresenceHeartbeat();

    // Save current workbook before leaving its view
    saveCurrentWorkbookIfOpen();

    // Match: #/samples
    if (hash === '#/samples') {
      renderSamplesDashboard();
      return;
    }

    // Match: #/rfq
    if (hash === '#/rfq') {
      renderRfqDashboard();
      return;
    }

    // Match: #/review — Ready-for-Review queue (workbooks Karen has
    // pushed back for Jackson + Parker to review).
    if (hash === '#/review') {
      renderReviewDashboard();
      return;
    }

    // Match: #/shipments
    if (hash === '#/shipments') {
      renderShipmentsList();
      return;
    }

    // Match: #/shipment/{id}
    const shipMatch = hash.match(/^#\/shipment\/(\d+)$/);
    if (shipMatch) {
      renderShipmentDetail(shipMatch[1]);
      return;
    }

    // Match: #/orders
    if (hash === '#/orders') {
      renderOrdersList();
      return;
    }

    // Match: #/inventory
    if (hash === '#/inventory') {
      renderInventoryView();
      return;
    }

    // Match: #/commissions
    if (hash === '#/commissions') {
      renderCommissionsView();
      return;
    }

    // Match: #/reports — list of prebuilt + saved reports
    if (hash === '#/reports') {
      renderReportsView();
      return;
    }
    // Match: #/reports/run/{id} — run a prebuilt report
    const repRunMatch = hash.match(/^#\/reports\/run\/([a-z0-9_-]+)$/i);
    if (repRunMatch) {
      runReport(repRunMatch[1], 'prebuilt');
      return;
    }
    // Match: #/reports/saved/{id} — load a saved view
    const repSavedMatch = hash.match(/^#\/reports\/saved\/([a-z0-9_-]+)$/i);
    if (repSavedMatch) {
      (async () => {
        await _ensureSavedReportsLoaded();
        const sv = (_msSavedReports || []).find(s => s.id === repSavedMatch[1]);
        if (!sv) {
          _msToast('Saved view not found.', 'error');
          location.hash = '#/reports';
          return;
        }
        // Saved views built on custom reports — re-register the virtual
        // def from the custom config so the engine can find it after a
        // page reload (custom defs are otherwise built ad-hoc on run).
        if (typeof sv.basedOn === 'string' && sv.basedOn.indexOf('custom_') === 0) {
          await _ensureCustomReportsLoaded();
          const customId = sv.basedOn.slice('custom_'.length);
          const custom = (_msCustomReports || []).find(c => c.id === customId);
          if (custom) {
            const def = _buildVirtualCustomDef(custom);
            if (def) _MS_REPORT_BY_ID[def.id] = def;
          }
        }
        runReport(sv.basedOn, 'saved', Object.assign({}, sv.filters || {}, { _savedId: sv.id }));
      })();
      return;
    }
    // Match: #/reports/custom/{id} — run a user-built custom report
    const repCustomMatch = hash.match(/^#\/reports\/custom\/([a-z0-9_-]+)$/i);
    if (repCustomMatch) {
      (async () => {
        await _ensureCustomReportsLoaded();
        runCustomReport(repCustomMatch[1]);
      })();
      return;
    }

    // Match: #/order/{id}
    const orderMatch = hash.match(/^#\/order\/(\d+)$/);
    if (orderMatch) {
      renderOrderDetail(orderMatch[1]);
      return;
    }

    // Match: #/client/{name}
    const clientMatch = hash.match(/^#\/client\/(.+)$/);
    if (clientMatch) {
      renderDashboard(clientMatch[1]);
      return;
    }

    // Default: home
    document.getElementById('header-title').textContent = 'Market Sculpt';
    document.querySelectorAll('.sidebar-nav .nav-item').forEach(a => a.classList.remove('active'));
    document.querySelectorAll('.nav-flat-link').forEach(a => a.classList.remove('active'));
    const allWbNav = document.getElementById('nav-all-workbooks');
    if (allWbNav) allWbNav.classList.add('active');
    renderRecentWorkbooks();
    showView('view-home');
  }

  let _currentStatusFilter = 'all';
  let _homeSortField = 'date';
  let _homeSortDir = 'desc';
  let _clientSortField = 'date';
  let _clientSortDir = 'desc';

  function updateSortArrows(tableSelector, field, dir) {
    document.querySelectorAll(`${tableSelector} th.sortable`).forEach(th => {
      th.classList.remove('asc', 'desc');
    });
    const clickedTh = event.target.closest('th');
    if (clickedTh) clickedTh.classList.add(dir);
  }

  function sortHomeTable(field) {
    if (_homeSortField === field) {
      _homeSortDir = _homeSortDir === 'asc' ? 'desc' : 'asc';
    } else {
      _homeSortField = field;
      _homeSortDir = 'asc';
    }
    updateSortArrows('#view-home .dash-table', field, _homeSortDir);
    renderRecentWorkbooks();
  }

  function sortClientTable(field) {
    if (_clientSortField === field) {
      _clientSortDir = _clientSortDir === 'asc' ? 'desc' : 'asc';
    } else {
      _clientSortField = field;
      _clientSortDir = 'asc';
    }
    updateSortArrows('#dash-table', field, _clientSortDir);
    renderDashboard(document.getElementById('header-title').textContent.replace(' — Workbooks', ''));
  }

  function filterByStatus(status) {
    _currentStatusFilter = status;
    document.querySelectorAll('.status-filter-btn').forEach(btn => btn.classList.remove('active'));
    event.target.classList.add('active');
    renderRecentWorkbooks();
  }

  function getItemCurrentStep(flow) {
    let lastStep = null;
    for (let i = flowSteps.length - 1; i >= 0; i--) {
      if (flow[flowSteps[i]]) { lastStep = flowSteps[i]; break; }
    }
    return lastStep;
  }

  function renderRecentWorkbooks() { try { _renderRecentWorkbooksInner(); } catch(e) { console.error('[MS renderRecentWorkbooks]', e); } }
  function _renderRecentWorkbooksInner() {
    // Gather all workbooks with their client name
    const all = [];
    for (const [client, items] of Object.entries(clientData)) {
      items.forEach(item => all.push({ ...item, client }));
    }

    // Sort
    const months = { Jan:0, Feb:1, Mar:2, Apr:3, May:4, Jun:5, Jul:6, Aug:7, Sep:8, Oct:9, Nov:10, Dec:11 };
    const parseDate = d => {
      if (!d) return new Date(0);
      const parts = d.split(' ');
      return new Date(2000 + parseInt(parts[2]), months[parts[1]], parseInt(parts[0]));
    };
    const dir = _homeSortDir === 'asc' ? 1 : -1;
    all.sort((a, b) => {
      if (_homeSortField === 'product') return dir * a.product.localeCompare(b.product);
      if (_homeSortField === 'client') return dir * a.client.localeCompare(b.client);
      if (_homeSortField === 'status') return dir * (getCurrentStepName(a.flow) || '').localeCompare(getCurrentStepName(b.flow) || '');
      return dir * (parseDate(a.dateCreated) - parseDate(b.dateCreated));
    });

    // Apply status filter
    let filtered = all;
    if (_currentStatusFilter === 'complete') {
      filtered = all.filter(item => isFlowComplete(item.flow));
    } else if (_currentStatusFilter === 'none') {
      filtered = all.filter(item => getItemCurrentStep(item.flow) === null);
    } else if (_currentStatusFilter !== 'all') {
      filtered = all.filter(item => {
        const currentStep = getItemCurrentStep(item.flow);
        return currentStep === _currentStatusFilter;
      });
    }

    const recent = filtered;
    const filterEmpty = document.getElementById('filter-empty');
    const tbody = document.getElementById('recent-tbody');

    tbody.innerHTML = recent.map(item => {
      const complete = isFlowComplete(item.flow);
      const stepName = getCurrentStepName(item.flow);
      const stepClass = complete ? 'complete' : 'in-progress';

      return `
      <tr class="${complete ? 'row-complete' : ''}" style="cursor:pointer;" onclick="location.hash='#/client/${encodeURIComponent(item.client).replace(/'/g,'%27')}/workbook/${item.id}'">
        <td class="product-name">${item.product}</td>
        <td class="col-client">${item.client}</td>
        <td class="col-date-created"><span class="date-full">${item.dateCreated}</span><span class="date-short">${shortDate(item.dateCreated)}</span></td>
        <td class="col-flow">
          <div class="flow-group">
            ${flowSteps.map((s, i) => `
              <div class="flow-step">
                <div class="flow-bar ${item.flow[s] ? 'filled' : ''}"></div>
                <span class="flow-label">${flowLabels[i]}</span>
              </div>
            `).join('')}
          </div>
        </td>
        <td class="col-mobile-status"><span class="mobile-status-badge ${stepClass}">${stepName}</span></td>
        <td><button class="action-icon-btn" onclick="event.stopPropagation(); toggleActionMenu(this)" title="Actions">⋮</button><div class="action-menu"><a onclick="event.stopPropagation(); location.hash='#/client/${encodeURIComponent(item.client)}/workbook/${item.id}'">View</a><a onclick="event.stopPropagation(); location.hash='#/client/${encodeURIComponent(item.client)}/workbook/${item.id}'">Edit</a><a onclick="event.stopPropagation(); duplicateWorkbook('${item.client.replace(/'/g, "\\'")}', '${item.id}')">Duplicate</a><a onclick="event.stopPropagation(); openDeleteModal('${item.client.replace(/'/g, "\\'")}', '${item.id}', '${item.product.replace(/'/g, "\\'")}')">Delete</a></div></td>
      </tr>
      `;
    }).join('');

    if (filterEmpty) {
      if (recent.length === 0 && _currentStatusFilter !== 'all') {
        filterEmpty.style.display = 'block';
        tbody.closest('table').style.display = 'none';
      } else {
        filterEmpty.style.display = 'none';
        tbody.closest('table').style.display = '';
      }
    }
  }  // end _renderRecentWorkbooksInner

  window.MS_SESSION = { name: '<?= addslashes($_msUser) ?>', role: '<?= $_msRole ?>', id: <?= $_msUserId ?>, username: '<?= addslashes($_msUsername) ?>' };
