  function autoSaveWorkbook() {
    if (!currentClient || !currentWorkbookId || _filling || !_appReady) return;
    // Two-tier save: write to localStorage IMMEDIATELY so a hard
    // refresh within the next second never loses data, then debounce
    // the slower API call so we don't hammer the server on every
    // keystroke. localStorage write is synchronous and microseconds-fast.
    try {
      const key = `${currentClient}|${currentWorkbookId}`;
      const detail = collectWorkbookDetail();
      workbookDetail[key] = detail;
      saveToLocalStorage();
    } catch (e) { /* best-effort — don't block input flow */ }
    clearTimeout(saveTimer);
    saveTimer = setTimeout(() => {
      doSaveWorkbook();
    }, 400); // Server-side save 400ms after last change (was 800ms)
  }

  function doSaveWorkbook() {
    if (!currentClient || !currentWorkbookId) return;
    try {
      const detail = collectWorkbookDetail();
      const key = `${currentClient}|${currentWorkbookId}`;
      workbookDetail[key] = detail;

      // Save to DB — autosave does NOT create a revision (only nav saves do)
      const dbId = dbWorkbookMap[key] || currentWorkbookId;
      showSaveStatus('saving');
      apiCall('save_workbook_detail', { id: dbId, detail: detail, changed_by: getCurrentUser(), create_revision: false })
        .then(r => {
          showSaveStatus(r && r.success ? 'saved' : 'error');
          if (r && r.success) {
            // Clear the live-broadcast local-dirty flag on every input
            // we just persisted — the server now has our values, so
            // it's safe for an incoming broadcast to update them later.
            try {
              document.querySelectorAll('#view-workbook [data-local-dirty="1"]')
                .forEach(el => { delete el.dataset.localDirty; });
            } catch(_) {}
            // Bump our own cursor so the next dirty-check poll doesn't
            // echo this save back at us as a 'remote' change. We
            // re-poll on the next 2s tick, which will baseline against
            // the server's updated_at and skip-self via updated_by.
          }
        });

      syncClientDataName(currentClient, currentWorkbookId, detail);

      saveToLocalStorage();
    } catch(e) {
      console.error('[MS doSaveWorkbook]', e);
      showSaveStatus('error');
    }
  }

  // Listen for changes on workbook form fields
  let _isDirty = false; // true once the user has made any edit this session
  const _wbView = document.getElementById('view-workbook');
  _wbView.addEventListener('input', function(e) {
    if (e.target.matches('input, textarea, select')) {
      _isDirty = true;
      // Layer 2 of the live-broadcast safety: mark this input as
      // having unsaved local edits. _applyRemoteWorkbookDetail will
      // skip writing to any element with data-local-dirty="1" so
      // Karen's in-flight 400ms autosave window can't be overwritten
      // by an incoming broadcast from Jackson. Flag is cleared after
      // a successful doSaveWorkbook round-trip.
      try { e.target.dataset.localDirty = '1'; } catch(_) {}
      autoSaveWorkbook();
      // Keep header title in sync when product name is edited
      if (e.target.id === 'product-name') {
        document.getElementById('header-title').textContent = currentClient + ' — ' + (e.target.value || 'Workbook');
      }
    }
  });
  // Also catch select/dropdown changes (some browsers fire change but not input)
  _wbView.addEventListener('change', function(e) {
    if (e.target.matches('select')) { _isDirty = true; autoSaveWorkbook(); }
  });

  // Save to DB when leaving/refreshing the page
  window.addEventListener('beforeunload', function() {
    if (!currentClient || !currentWorkbookId || !_appReady) return;
    clearTimeout(saveTimer);
    const detail = collectWorkbookDetail();
    const key = `${currentClient}|${currentWorkbookId}`;
    workbookDetail[key] = detail;
    saveToLocalStorage();
    // Use sendBeacon so the request survives page unload
    const dbId = dbWorkbookMap[key] || currentWorkbookId;
    const payload = JSON.stringify({ action: 'save_workbook_detail', id: dbId, detail: detail });
    navigator.sendBeacon('api.php', new Blob([payload], { type: 'application/json' }));
  });

  /* ── Orders module state (must be declared before init) ────────────────── */
  let orderData = {};
  let _nextOrderId = 1;
  let _currentOrderId = null;
  let _orderFilter = 'all';
  let _orderPickerSelected = new Set();
  // Per-item numeric snapshot (units / weight / cost / price / cbm)
  // for the Create Order picker. Built fresh each buildOrderPickerList
  // call. Keyed by `${clientName}|${wb.id}` so the grand total card
  // can sum without re-walking clientData / workbookDetail.
  let _orderPickerItemData = {};
  let _orderAddPickerSelected = new Set();
  // Snapshot of per-item numbers (units / weight / cost / price / cbm)
  // built fresh on every buildOrderAddPickerList call. Keyed by
  // `${clientName}|${wb.id}` so the grand total card can sum without
  // re-walking clientData / workbookDetail.
  let _orderAddPickerItemData = {};
  let _shipOrderPickerSelected = new Set();
  // Per-order numeric snapshot (units / weight / cost / price / cbm)
  // for the Add to Shipment picker. Built fresh on each
  // buildShipOrderPickerList call. Keyed by orderId so the grand
  // total card can sum across selected orders without re-walking
  // every workbook in workbookDetail.
  let _shipPickerOrderData = {};

  /* ── Shipments module state (must be declared before init) ─────────────── */
  let shipmentData = {};
  let _nextShipmentId = 1;
  let _currentShipmentId = null;

  // ── Remote-change polling state ────────────────────────────────────────
  let _lastOrdersJson    = '';   // raw DB string from last successful poll
  let _lastShipmentsJson = '';   // same for shipments
  let _pollActive        = false; // guard against overlapping polls
  let _wbPickerSelected = new Set();
  let _shipFilter = 'all';
  const CONTAINER_SPECS = {
    '20ft': { label: "20' Standard",  cbm: 25,  maxKg: 21700, maxPallets: 10 },
    '40ft': { label: "40' Standard",  cbm: 55,  maxKg: 26500, maxPallets: 20 },
    '40hc': { label: "40' High Cube", cbm: 65,  maxKg: 26500, maxPallets: 21 },
  };

  /* ── Init ──────────────────────────────────────────────────────────────── */
  // Footer date
  document.getElementById('gen-date').textContent = new Date().toLocaleDateString('en-US', {
    year: 'numeric', month: 'long', day: 'numeric'
  });

  // Load data: try DB first, then LocalStorage, then use hardcoded fallback
  // ── INVENTORY ───────────────────────────────────────────────────────────
  let inventoryData = []; // [{id, sku, product_name, variant_name, client_name, workbook_id, promoted_at}]
  let _invSort = { col: null, dir: 1 }; // current inventory sort state
  // Which (workbook_id|product_name) groups are currently expanded so
  // their variant SKUs are visible. Default: empty → every group starts
  // collapsed (just the parent SKU shows, with a chevron + variant count
  // badge indicating there's more underneath). Click the parent row to
  // toggle. State lives in-memory only — survives re-renders within the
  // session but resets on page reload, which is fine: the user expects
  // a clean collapsed view by default.
  const _invExpandedGroups = new Set();

  async function loadInventory() {
    const res = await apiCall('get_inventory');
    if (res.success) {
      inventoryData = res.data || [];
      // Inventory badge intentionally not shown
    }
  }

  // Dashboard-view state — remembered across navigations within the session
  let _invClientFilter = 'all';   // 'all' or client name
  let _invTab = 'dashboard';      // 'dashboard' | 'skus'

  function _invFilteredRows() {
    if (_invClientFilter === 'all') return inventoryData.slice();
    return inventoryData.filter(r => (r.client_name || '') === _invClientFilter);
  }

  function populateInventoryClientFilter() {
    const sel = document.getElementById('inventory-client-filter');
    if (!sel) return;
    // Unique client names present in inventory, sorted
    const clientsWithSkus = Array.from(new Set(inventoryData.map(r => r.client_name).filter(Boolean))).sort();
    const current = _invClientFilter;
    sel.innerHTML = `<option value="all">All Clients${inventoryData.length ? ' (' + inventoryData.length + ')' : ''}</option>` +
      clientsWithSkus.map(n => {
        const count = inventoryData.filter(r => r.client_name === n).length;
        return `<option value="${n.replace(/"/g,'&quot;')}"${n === current ? ' selected' : ''}>${n} (${count})</option>`;
      }).join('');
    // If the current filter is no longer present (client removed), fall back to 'all'
    if (current !== 'all' && !clientsWithSkus.includes(current)) {
      _invClientFilter = 'all';
      sel.value = 'all';
    }
  }

  function filterInventoryByClient(value) {
    _invClientFilter = value || 'all';
    // Re-render the active pane only — the other will catch up when switched to
    if (_invTab === 'dashboard') {
      renderInventoryDashboard();
    } else {
      const q = document.getElementById('inventory-search')?.value || '';
      filterInventory(q); // respects search within the client filter
    }
    // Update the count badge — always reflects the current client filter
    _updateInventoryCountBadge();
  }

  function _updateInventoryCountBadge() {
    const badge = document.getElementById('inventory-count-badge');
    if (!badge) return;
    const rows = _invFilteredRows();
    badge.textContent = rows.length === 1 ? '1 SKU' : `${rows.length.toLocaleString('en-US')} SKUs`;
  }

  function switchInventoryTab(tab, btn) {
    _invTab = tab;
    document.querySelectorAll('.inv-tab-btn').forEach(b => b.classList.remove('active'));
    if (btn) btn.classList.add('active');
    const dashPane = document.getElementById('inventory-dashboard-pane');
    const skusPane = document.getElementById('inventory-skus-pane');
    if (tab === 'dashboard') {
      if (dashPane) dashPane.style.display = '';
      if (skusPane) skusPane.style.display = 'none';
      renderInventoryDashboard();
    } else {
      if (dashPane) dashPane.style.display = 'none';
      if (skusPane) skusPane.style.display = '';
      const q = document.getElementById('inventory-search')?.value || '';
      filterInventory(q);
    }
  }

  function renderInventoryView() {
    document.querySelectorAll('.nav-flat-link').forEach(a => a.classList.remove('active'));
    const invNav = document.getElementById('nav-inventory-link');
    if (invNav) invNav.classList.add('active');
    document.getElementById('header-title').textContent = 'Inventory';
    _invSort = { col: null, dir: 1 };
    const searchEl = document.getElementById('inventory-search');
    if (searchEl) searchEl.value = '';

    // Rebuild client filter dropdown from current data
    populateInventoryClientFilter();
    _updateInventoryCountBadge();

    // Default to dashboard tab on entry (per design: no raw SKU list up front)
    const dashBtn = document.getElementById('inv-tab-dashboard');
    const skusBtn = document.getElementById('inv-tab-skus');
    document.querySelectorAll('.inv-tab-btn').forEach(b => b.classList.remove('active'));
    if (_invTab === 'skus' && skusBtn) {
      skusBtn.classList.add('active');
      switchInventoryTab('skus', skusBtn);
    } else {
      if (dashBtn) dashBtn.classList.add('active');
      _invTab = 'dashboard';
      const dashPane = document.getElementById('inventory-dashboard-pane');
      const skusPane = document.getElementById('inventory-skus-pane');
      if (dashPane) dashPane.style.display = '';
      if (skusPane) skusPane.style.display = 'none';
      renderInventoryDashboard();
    }
    showView('view-inventory');
  }

  // Build the dashboard: stat cards + top clients + recent activity + sparkline
  function renderInventoryDashboard() {
    const host = document.getElementById('inventory-dashboard-content');
    if (!host) return;

    const rows = _invFilteredRows();
    const scope = _invClientFilter === 'all' ? 'all clients' : _invClientFilter;

    // Empty state
    if (!rows.length) {
      host.innerHTML = `
        <div class="section-card" style="padding:60px 24px; text-align:center; color:var(--text-muted);">
          <div style="font-size:40px; margin-bottom:14px;">📦</div>
          <div style="font-size:16px; font-weight:600; color:var(--text); margin-bottom:6px;">
            ${_invClientFilter === 'all' ? 'No SKUs promoted yet' : `No SKUs for ${_invClientFilter}`}
          </div>
          <div style="font-size:13px; max-width:360px; margin:0 auto;">
            Open a workbook, click <strong>Promote to Permanent SKU</strong> on RFQ line items, and they'll show up here.
          </div>
        </div>`;
      return;
    }

    // ── Core metrics ──
    const now = Date.now();
    const DAY = 24 * 60 * 60 * 1000;

    const promotedAtMs = r => { const t = r.promoted_at ? Date.parse(r.promoted_at) : NaN; return isNaN(t) ? 0 : t; };

    // Resolve workbook_id -> product name across all clients (used when a
    // specific client is selected so recent activity can show the source wb).
    const workbookNameById = {};
    try {
      if (typeof clientData === 'object' && clientData) {
        Object.values(clientData).forEach(list => {
          if (!Array.isArray(list)) return;
          list.forEach(wb => {
            if (wb && wb.id != null) workbookNameById[String(wb.id)] = wb.product || '';
          });
        });
      }
    } catch (e) { /* clientData may not be ready on first paint */ }

    const uniqueClients  = new Set(rows.map(r => r.client_name).filter(Boolean)).size;
    const uniqueWorkbooks = new Set(rows.map(r => r.workbook_id).filter(Boolean)).size;
    const withVariants   = rows.filter(r => r.variant_name && String(r.variant_name).trim()).length;
    const latestTs       = rows.reduce((m, r) => Math.max(m, promotedAtMs(r)), 0);
    const latestLabel    = latestTs ? _relativeTime(latestTs, now) : '—';

    // Coverage: % of SKUs that have a source workbook id attached
    const withSource = rows.filter(r => r.workbook_id).length;
    const coveragePct = rows.length ? Math.round((withSource / rows.length) * 100) : 0;

    // ── Top clients by SKU count (skip when filtered to single client) ──
    const topClientsHtml = (() => {
      if (_invClientFilter !== 'all') return ''; // no sense showing a one-bar chart
      const counts = {};
      rows.forEach(r => {
        const c = r.client_name || '—';
        counts[c] = (counts[c] || 0) + 1;
      });
      const sorted = Object.entries(counts).sort((a, b) => b[1] - a[1]).slice(0, 5);
      if (!sorted.length) return '';
      const max = sorted[0][1];
      return `
        <div class="section-card" style="padding:18px 20px;">
          <div class="inv-dash-row-title">Top clients by SKU count</div>
          ${sorted.map(([name, n]) => `
            <div class="inv-topclient-row">
              <div class="inv-topclient-name" title="${name}">${name}</div>
              <div class="inv-topclient-bar-wrap">
                <div class="inv-topclient-bar" style="width:${(n / max) * 100}%;"></div>
              </div>
              <div class="inv-topclient-count">${n}</div>
            </div>
          `).join('')}
        </div>`;
    })();

    // ── Recent activity (last 5 SKUs added, newest first) ──
    // Columnar layout: [SKU 100px][Workbook pill 1fr][Our Cost][Client Cost][Date →]
    // Workbook pill now shows in ALL views (All Clients + specific-client).
    // Our Cost / Client Cost only appear when a specific client is selected.
    const recentHtml = (() => {
      const sorted = rows.slice().sort((a, b) => promotedAtMs(b) - promotedAtMs(a)).slice(0, 5);
      const showCosts = _invClientFilter !== 'all';
      const esc = s => String(s || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');

      // "April 22nd" style date with ordinal suffix
      const ordinalSuffix = d => { const n = d % 100; if (n >= 11 && n <= 13) return 'th'; switch (d % 10) { case 1: return 'st'; case 2: return 'nd'; case 3: return 'rd'; default: return 'th'; } };
      const fmtPretty = ts => {
        if (!ts) return '—';
        const d = new Date(ts);
        if (isNaN(d.getTime())) return '—';
        return `${d.toLocaleString('en-US', { month: 'long' })} ${d.getDate()}${ordinalSuffix(d.getDate())}`;
      };
      const fmtUsd = n => '$' + Number(n).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

      // Pull "Our Cost (USD)" from the matching RFQ line on that workbook.
      const ourCostUsdFor = (row) => {
        if (!row || !row.workbook_id || !row.client_name || !row.sku) return null;
        const key = `${row.client_name}|${row.workbook_id}`;
        const det = (typeof workbookDetail === 'object' && workbookDetail) ? workbookDetail[key] : null;
        if (!det || !Array.isArray(det.rfqItems)) return null;
        for (const it of det.rfqItems) {
          if (it && String(it.sku || '').trim() === String(row.sku).trim()) {
            const rmb = parseFloat(String(it.priceRmb || '').replace(/,/g, ''));
            if (rmb > 0 && USD_TO_RMB > 0) return rmb / USD_TO_RMB;
            return null;
          }
          if (Array.isArray(it && it.variants)) {
            for (const v of it.variants) {
              if (v && String(v.sku || '').trim() === String(row.sku).trim()) {
                const rmb = parseFloat(String(v.priceRmb || '').replace(/,/g, ''));
                if (rmb > 0 && USD_TO_RMB > 0) return rmb / USD_TO_RMB;
                return null;
              }
            }
          }
        }
        return null;
      };

      const costPh = '<span style="color:var(--text-muted); opacity:.7; font-style:italic;" title="Client Cost lives on the Pricing tab — not wired up yet">—</span>';

      // Fluid CSS Grid: every column uses minmax(floor, fraction) so the
      // card ALWAYS fits its parent (no horizontal overflow), but columns
      // still align vertically across rows. minmax() lets cells shrink
      // below the fr-share if the container is narrow, and text-ellipsis
      // picks up the slack.
      //
      // All-Clients view (main page): only Product · SKU · Workbook.
      // Specific-client view: adds Our Cost · Client Cost · Date.
      const gridCols = showCosts
        ? 'minmax(110px, 1.4fr) minmax(70px, 0.7fr) minmax(110px, 1.3fr) minmax(90px, 0.9fr) minmax(80px, 0.8fr) minmax(110px, 1fr)'
        : 'minmax(160px, 2fr)  minmax(100px, 1fr)  minmax(160px, 2fr)';

      // Table-style header row: column titles live once at the top.
      const colHeaders = showCosts
        ? ['Product', 'SKU', 'Workbook', 'Our Cost', 'Client Cost', 'Date']
        : ['Product', 'SKU', 'Workbook'];
      const headerRowStyle = `display:grid; grid-template-columns:${gridCols}; column-gap:12px; align-items:center; padding:6px 0 8px; border-bottom:1px solid var(--border); margin-bottom:4px;`;
      const headerCellStyle = 'font-size:10px; font-weight:700; color:var(--text-muted); text-transform:uppercase; letter-spacing:0.06em; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;';

      return `
        <div class="section-card" style="padding:18px 20px; min-width:0;">
          <div class="inv-dash-row-title">Recent activity</div>
          <div style="${headerRowStyle}">
            ${colHeaders.map(h => `<div style="${headerCellStyle}">${h}</div>`).join('')}
          </div>
          ${sorted.map(r => {
            const wbName = r.workbook_id != null ? (workbookNameById[String(r.workbook_id)] || '') : '';
            const wbHref = (wbName && r.client_name && r.workbook_id)
              ? `#/client/${encodeURIComponent(r.client_name)}/workbook/${r.workbook_id}`
              : '';
            const wbCell = wbName
              ? (wbHref
                  ? `<span class="inv-wb-pill" onclick="location.hash='${wbHref.substring(1)}'" title="${esc(wbName)}" style="max-width:100%; min-width:0;"><span class="inv-wb-pill-text">${esc(wbName)}</span><span class="inv-wb-pill-arrow">→</span></span>`
                  : `<span style="color:var(--text); overflow:hidden; text-overflow:ellipsis; white-space:nowrap;">${esc(wbName)}</span>`)
              : `<span style="color:var(--text-muted); opacity:.6; font-size:12px;">—</span>`;

            // Cost + Date cells only when a specific client is selected.
            let extraCells = '';
            if (showCosts) {
              const oc = ourCostUsdFor(r);
              const ocHtml = (oc != null)
                ? `<span style="color:var(--success, #16a34a); font-weight:600;">${fmtUsd(oc)}</span>`
                : `<span style="color:var(--text-muted); opacity:.7;">—</span>`;
              extraCells = `
                <div style="display:flex; align-items:center; min-width:0; overflow:hidden;" title="Derived from the matching RFQ line">${ocHtml}</div>
                <div style="display:flex; align-items:center; min-width:0; overflow:hidden;">${costPh}</div>
                <div style="display:flex; align-items:center; color:var(--text); font-size:12px; overflow:hidden; min-width:0; white-space:nowrap;" title="${esc(r.promoted_at || '')}">${fmtPretty(r.promoted_at)}</div>`;
            }

            return `
              <div class="inv-activity-row" style="display:grid; grid-template-columns:${gridCols}; column-gap:12px; align-items:center;">
                <div style="display:flex; align-items:center; min-width:0; overflow:hidden; color:var(--text); font-weight:600;" title="${esc(r.product_name)}">
                  <span style="overflow:hidden; text-overflow:ellipsis; white-space:nowrap;">${esc(r.product_name) || '—'}</span>
                </div>
                <div style="display:flex; align-items:center; min-width:0; overflow:hidden;">
                  <span class="inv-sku" style="overflow:hidden; text-overflow:ellipsis; white-space:nowrap;">${esc(r.sku) || '—'}</span>
                </div>
                <div style="display:flex; align-items:center; min-width:0; overflow:hidden;">${wbCell}</div>
                ${extraCells}
              </div>`;
          }).join('')}
        </div>`;
    })();

    // ── Sparkline: SKUs added per week over the last 12 weeks ──
    const sparkHtml = (() => {
      const weeks = 12;
      const buckets = new Array(weeks).fill(0);
      const weekStart = now - weeks * 7 * DAY;
      rows.forEach(r => {
        const t = promotedAtMs(r);
        if (!t || t < weekStart) return;
        const idx = Math.min(weeks - 1, Math.floor((t - weekStart) / (7 * DAY)));
        buckets[idx]++;
      });
      const max = Math.max(1, ...buckets);
      const startLabel = new Date(weekStart).toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
      const endLabel   = new Date(now).toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
      return `
        <div class="section-card" style="padding:18px 20px;">
          <div class="inv-dash-row-title">SKUs added per week · last 12 weeks</div>
          <div class="inv-sparkline">
            ${buckets.map((n, i) => {
              const h = (n / max) * 100;
              const weekOf = new Date(weekStart + i * 7 * DAY).toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
              return `<div class="inv-sparkline-bar" style="height:${Math.max(2, h)}%;" title="Week of ${weekOf}: ${n} SKU${n !== 1 ? 's' : ''}"></div>`;
            }).join('')}
          </div>
          <div class="inv-sparkline-labels">
            <span>${startLabel}</span>
            <span>${endLabel}</span>
          </div>
        </div>`;
    })();

    // ── Assemble ──
    // Scope note at top when filtered to a client
    const scopeNote = _invClientFilter !== 'all'
      ? `<div style="font-size:12px; color:var(--text-muted); margin-bottom:12px;">Showing <strong style="color:var(--text);">${_invClientFilter}</strong> only · <a href="#" onclick="event.preventDefault(); document.getElementById('inventory-client-filter').value='all'; filterInventoryByClient('all');" style="color:var(--accent); text-decoration:none;">Clear filter</a></div>`
      : '';

    host.innerHTML = `
      ${scopeNote}
      <div style="display:grid; grid-template-columns:repeat(auto-fit, minmax(160px, 1fr)); gap:12px; margin-bottom:16px;">
        <div class="inv-stat-card">
          <div class="inv-stat-card-value" style="color:var(--accent);">${rows.length.toLocaleString('en-US')}</div>
          <div class="inv-stat-card-label">Total SKUs</div>
        </div>
        <div class="inv-stat-card">
          <div class="inv-stat-card-value" style="color:#a855f7;">${uniqueClients}</div>
          <div class="inv-stat-card-label">${_invClientFilter === 'all' ? 'Clients' : 'Client'}</div>
        </div>
        <div class="inv-stat-card">
          <div class="inv-stat-card-value" style="color:#6b93ff;">${uniqueWorkbooks}</div>
          <div class="inv-stat-card-label">Source Workbooks</div>
        </div>
        <div class="inv-stat-card">
          <div class="inv-stat-card-value" style="color:#f59e0b;">${withVariants}</div>
          <div class="inv-stat-card-label">With Variants</div>
        </div>
        <div class="inv-stat-card">
          <div class="inv-stat-card-value" style="color:var(--text); font-size:16px;">${latestLabel}</div>
          <div class="inv-stat-card-label">Latest Addition</div>
        </div>
        <div class="inv-stat-card">
          <div class="inv-stat-card-value" style="color:${coveragePct >= 80 ? '#10b981' : coveragePct >= 50 ? '#f59e0b' : '#ef4444'};">${coveragePct}%</div>
          <div class="inv-stat-card-label">Source Coverage</div>
          <div class="inv-stat-card-sub">${withSource}/${rows.length} linked</div>
        </div>
      </div>

      ${topClientsHtml || recentHtml
        ? `<div style="display:grid; grid-template-columns:${topClientsHtml ? 'repeat(auto-fit, minmax(320px, 1fr))' : '1fr'}; gap:12px; margin-bottom:12px;">
            ${topClientsHtml}
            ${recentHtml}
          </div>`
        : ''}

      ${sparkHtml}
    `;
  }

  // ══════════════════════════════════════════════════════════════════════
  // COMMISSIONS DASHBOARD
  // Owner-facing reporting view. Pulls all rows once via get_commissions and
  // filters in memory (employee × role). Mirrors Inventory dashboard's card
  // rhythm so the two views feel consistent.
  // ══════════════════════════════════════════════════════════════════════
  let commissionsData = [];          // [{id, role, employee, client_total_usd, commission_amount, status, ...}]
  let _commEmployeeFilter = 'all';   // 'all' | 'Parker Low' | 'Jackson Hollberg'
  let _commRoleFilter     = 'all';   // 'all' | 'account_manager' | 'salesperson'

  async function loadCommissions() {
    try {
      // Reconcile first — picks up any (client, workbook) pairs that became
      // commissionable after the original promote/order (e.g. AM/SP got
      // assigned later, or the workbook's rfqItems totals changed). The
      // server is idempotent and refreshes pending rows in place; paid rows
      // stay frozen. Failures here shouldn't block the read of existing rows.
      //
      // Send the live Client Quote totals from workbookDetail so any
      // Sale Per typed since the last autosave round-trip ALSO shows
      // up as a commission row — guarantees "Client Quote entered →
      // commission shows" without waiting on the saved detail_json.
      // Server-side path 1c uses this to create pairs for workbooks
      // that haven't been promoted / aren't in an order yet too.
      const liveQuoteTotals = {};
      try {
        Object.entries(workbookDetail || {}).forEach(([key, d]) => {
          const v = parseFloat(d && d.pricingClientQuoteTotal);
          if (!isNaN(v) && v > 0) {
            // Map JS key (clientName|localId) to DB key (clientName|dbId).
            // dbWorkbookMap is populated by loadFromDatabase; keys that
            // aren't in it fall back to the local id (which IS the DB
            // id for workbooks loaded from the DB).
            const dbKey = (typeof dbWorkbookMap === 'object' && dbWorkbookMap && dbWorkbookMap[key])
              ? `${key.split('|')[0]}|${dbWorkbookMap[key]}`
              : key;
            liveQuoteTotals[dbKey] = v;
          }
        });
      } catch (_) { /* missing workbookDetail / dbWorkbookMap — server falls back to saved detail_json */ }

      try { await apiCall('recompute_commissions', { client_quote_totals: liveQuoteTotals }); }
      catch (e) { console.warn('[commissions] recompute_commissions failed', e); }

      const res = await apiCall('get_commissions');
      if (res && res.success) commissionsData = res.data || [];
    } catch (e) { console.error('[commissions] loadCommissions failed', e); }
  }

  function _commFilteredRows() {
    return commissionsData.filter(r => {
      if (_commEmployeeFilter !== 'all' && r.employee !== _commEmployeeFilter) return false;
      if (_commRoleFilter     !== 'all' && r.role     !== _commRoleFilter)     return false;
      return true;
    });
  }

  function filterCommissionsByEmployee(v) { _commEmployeeFilter = v; renderCommissionsDashboard(); }
  function filterCommissionsByRole(v)     { _commRoleFilter     = v; renderCommissionsDashboard(); }

  // Which employees have their per-client / per-workbook breakdown expanded
  // on the scoreboard. Survives re-renders triggered by filter changes.
  const _commExpandedEmployees = new Set();
  // Per-employee toggle for the "Archived (prior months)" sub-section
  // of the breakdown. Independent of _commExpandedEmployees so the
  // operator can keep an employee's active section open while the
  // older-months drawer stays closed.
  const _commArchiveExpanded = new Set();
  function toggleCommissionArchive(name) {
    if (_commArchiveExpanded.has(name)) _commArchiveExpanded.delete(name);
    else _commArchiveExpanded.add(name);
    renderCommissionsDashboard();
  }
  function toggleEmployeeExpand(name) {
    if (_commExpandedEmployees.has(name)) _commExpandedEmployees.delete(name);
    else _commExpandedEmployees.add(name);
    renderCommissionsDashboard();
  }

  // Toggle a single commission row between paid and pending. Hits
  // set_commission_status, then mutates the matching entry in
  // commissionsData so the UI reflects without a full reload — and so
  // the year/month buckets in the Earnings-over-time card recompute on
  // the next render. event.stopPropagation() is the caller's job; this
  // function only handles the network + state update.
  async function setCommissionPaid(id, paid) {
    const status = paid ? 'paid' : 'pending';
    const r = await apiCall('set_commission_status', { id, status });
    if (!r.success) { alert(r.error || 'Failed to update commission status.'); return; }
    const row = commissionsData.find(x => x.id === id);
    if (row) {
      row.status  = status;
      row.paid_at = paid ? new Date().toISOString() : null;
    }
    renderCommissionsDashboard();
  }

  // Selected year for the "Earnings over time" card. null = pick the most
  // recent year with data (clamped at render time once we know what years
  // actually have rows under the current filters).
  let _commTimeYear = null;
  function setCommTimeYear(y) {
    _commTimeYear = parseInt(y, 10) || null;
    renderCommissionsDashboard();
  }

  // Optional focus on a single employee in the Earnings-over-time card —
  // clicking a legend chip filters the chart and dims the per-individual
  // rows. Click again (or "Clear focus") to restore the team view.
  let _commTimeFocusEmp = null;
  function setCommTimeFocusEmp(name) {
    if (!name || _commTimeFocusEmp === name) {
      _commTimeFocusEmp = null;
    } else {
      _commTimeFocusEmp = name;
    }
    renderCommissionsDashboard();
  }

  // Deterministic per-employee swatch using the same HSL hash trick as
  // _clientChipStyle, but tuned for solid bar fills (saturated mid-tone)
  // rather than translucent chips. Same name → same color across renders.
  //
  // EMPLOYEE_HUE_OVERRIDES pins specific names to fixed hues when the hash
  // happens to land them too close to another teammate's color. Karen
  // hashed to ~197 (cyan-blue) which read identical to Jackson on the
  // stacked bars, so we force her to a clear green here. Add new entries
  // when a clash shows up — leaving an employee out of the map falls back
  // to the deterministic hash.
  const EMPLOYEE_HUE_OVERRIDES = {
    'Karen': 140, // green
  };
  function _employeeSwatch(name) {
    const safe = (name || '—').toString();
    let hue;
    if (Object.prototype.hasOwnProperty.call(EMPLOYEE_HUE_OVERRIDES, safe)) {
      hue = EMPLOYEE_HUE_OVERRIDES[safe];
    } else {
      let hash = 0;
      for (let i = 0; i < safe.length; i++) {
        hash = ((hash << 5) - hash) + safe.charCodeAt(i);
        hash |= 0;
      }
      hue = Math.abs(hash) % 360;
    }
    return {
      fill: `hsl(${hue}, 62%, 52%)`,
      tint: `hsl(${hue}, 62%, 92%)`,
      ink:  `hsl(${hue}, 55%, 28%)`,
    };
  }

  async function renderCommissionsView() {
    document.querySelectorAll('.nav-flat-link').forEach(a => a.classList.remove('active'));
    const navLink = document.getElementById('nav-commissions-link');
    if (navLink) navLink.classList.add('active');
    document.getElementById('header-title').textContent = 'Commissions';
    await loadCommissions();
    renderCommissionsDashboard();
    showView('view-commissions');
  }

  function renderCommissionsDashboard() {
    const host = document.getElementById('commissions-dashboard-content');
    if (!host) return;

    const rows  = _commFilteredRows();
    const badge = document.getElementById('commissions-count-badge');
    if (badge) badge.textContent = `${rows.length} row${rows.length !== 1 ? 's' : ''}`;

    // Empty state — guides the user toward setup
    if (!rows.length) {
      host.innerHTML = `
        <div class="section-card" style="padding:60px 24px; text-align:center; color:var(--text-muted);">
          <div style="font-size:40px; margin-bottom:14px;">💼</div>
          <div style="font-size:16px; font-weight:600; color:var(--text); margin-bottom:6px;">
            ${commissionsData.length === 0 ? 'No commissions yet' : 'No rows match the current filter'}
          </div>
          <div style="font-size:13px; max-width:440px; margin:0 auto;">
            ${commissionsData.length === 0
              ? 'Assign an <strong>Account Manager</strong> or <strong>Salesperson</strong> to a client, then promote a workbook with priced RFQ items. Commissions will land here automatically (20% of client total).'
              : 'Try clearing the Employee or Role filter to see all rows.'}
          </div>
        </div>`;
      return;
    }

    // ── Formatters ──
    const fmtUsd  = n => '$' + (parseFloat(n) || 0).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    const fmtUsd0 = n => '$' + Math.round(parseFloat(n) || 0).toLocaleString('en-US');
    const fmtPretty = iso => {
      if (!iso) return '—';
      const d = new Date(iso); if (isNaN(d.getTime())) return '—';
      const months = ['January','February','March','April','May','June','July','August','September','October','November','December'];
      const day = d.getDate();
      const suf = (n => (n>3 && n<21) ? 'th' : ({1:'st',2:'nd',3:'rd'}[n%10]||'th'))(day);
      return `${months[d.getMonth()]} ${day}${suf}`;
    };
    const esc = s => String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');

    // ── KPI strip ──
    const totalEarned = rows.reduce((s, r) => s + (parseFloat(r.commission_amount) || 0), 0);
    const pending     = rows.filter(r => r.status === 'pending').reduce((s, r) => s + (parseFloat(r.commission_amount) || 0), 0);
    const paid        = rows.filter(r => r.status === 'paid').reduce((s, r) => s + (parseFloat(r.commission_amount) || 0), 0);
    const wbCount     = new Set(rows.map(r => r.workbook_id)).size;
    const avgPerWb    = wbCount > 0 ? totalEarned / wbCount : 0;
    const anyEstimate = rows.some(r => +r.is_estimate === 1);

    const statCard = (label, value, subtext, accent) => `
      <div class="section-card" style="padding:16px 18px; min-width:0;">
        <div style="font-size:11px; font-weight:700; color:var(--text-muted); text-transform:uppercase; letter-spacing:0.06em; line-height:1.3;">${label}</div>
        <div style="font-size:22px; font-weight:700; color:${accent || 'var(--text)'}; margin-top:6px; line-height:1.15; overflow-wrap:anywhere; word-break:break-word;">${value}</div>
        ${subtext ? `<div style="font-size:11px; color:var(--text-muted); margin-top:4px; line-height:1.3;">${subtext}</div>` : ''}
      </div>`;

    // auto-fit grid: 4-up on desktop, naturally re-flows to 2-up at
    // tablet width and 1-up on phones so the $50k values don't truncate.
    const kpiHtml = `
      <div style="display:grid; grid-template-columns:repeat(auto-fit, minmax(170px, 1fr)); gap:12px; margin-bottom:18px;">
        ${statCard('Total Earned', fmtUsd(totalEarned), `${rows.length} commission row${rows.length !== 1 ? 's' : ''}`)}
        ${statCard('Pending Payout', fmtUsd(pending), 'Not yet marked paid', 'var(--accent)')}
        ${statCard('Paid Out', fmtUsd(paid), 'Marked paid', 'var(--success, #16a34a)')}
        ${statCard('Avg / Workbook', fmtUsd(avgPerWb), `${wbCount} unique workbook${wbCount !== 1 ? 's' : ''}`)}
      </div>
      ${anyEstimate ? `
        <div style="background:rgba(232,117,26,0.08); border:1px solid rgba(232,117,26,0.25); border-radius:10px; padding:10px 14px; margin-bottom:18px; font-size:12px; color:var(--text-muted);">
          ⓘ Some commissions are <strong>estimates</strong>: they use Our Cost (RFQ-derived USD) until "Client Cost" is wired up on the Pricing tab.
        </div>` : ''}
    `;

    // ── Per-employee scoreboard ──
    const empMap = {};
    rows.forEach(r => {
      const e = r.employee || '—';
      if (!empMap[e]) empMap[e] = { am: 0, sp: 0, op: 0, total: 0, paid: 0, pending: 0, count: 0 };
      const amt = parseFloat(r.commission_amount) || 0;
      empMap[e].total += amt;
      empMap[e].count += 1;
      // Split each row into paid vs pending so the scoreboard card can
      // show "X paid / Y pending" without re-walking the rows in render.
      if (r.status === 'paid') empMap[e].paid    += amt;
      else                     empMap[e].pending += amt;
      if      (r.role === 'account_manager') empMap[e].am += amt;
      else if (r.role === 'salesperson')     empMap[e].sp += amt;
      else if (r.role === 'operations')      empMap[e].op += amt;
    });
    const employees = Object.entries(empMap).sort((a, b) => b[1].total - a[1].total);

    // Role pill (used by the recent-activity table AND the expanded
    // breakdown). Hoisted above empHtml so the breakdown can call it.
    // Each role gets a distinct color so the eye can sort the rows fast:
    //   AM       — blue
    //   Sales    — orange (the brand accent)
    //   Ops      — green-teal (visually separated from the other two so
    //              Karen's slice on a stacked bar pops without colliding)
    const rolePill = role => {
      const styles = {
        account_manager: { label: 'AM',    bg: 'rgba(107,147,255,0.12)', fg: '#6b93ff',           bd: 'rgba(107,147,255,0.35)' },
        salesperson:     { label: 'Sales', bg: 'rgba(232,117,26,0.12)',  fg: 'var(--accent)',     bd: 'rgba(232,117,26,0.35)'  },
        operations:      { label: 'Ops',   bg: 'rgba(22,163,74,0.12)',   fg: '#16a34a',           bd: 'rgba(22,163,74,0.35)'   },
      };
      const s = styles[role] || { label: role || '—', bg: 'var(--surface2)', fg: 'var(--text-muted)', bd: 'var(--border)' };
      return `<span style="background:${s.bg}; color:${s.fg}; border:1px solid ${s.bd}; padding:2px 8px; border-radius:10px; font-size:11px; font-weight:600; white-space:nowrap;">${s.label}</span>`;
    };

    // Per-employee breakdown (rendered when the card is expanded). Groups
    // this employee's commission rows by client, then lists each workbook
    // with its rate, the client total it ran against, and the resulting
    // commission. Sorts clients by total descending so the biggest earner
    // floats to the top.
    const fmtRate = frac => {
      const pct = (parseFloat(frac) || 0) * 100;
      return (pct % 1 === 0 ? pct.toFixed(0) : pct.toFixed(2)) + '%';
    };
    // Status pill: maps the workbook's flow (or absence) to a colored
    // tag rendered next to the workbook product link in each
    // commission row. Handles three buckets:
    //   - Live workbook: pill from flowLabels (Quote / Submitted /
    //     Approved / Ordered / Complete)
    //   - Workbook missing from clientData (deleted or archived):
    //     muted "Archived" pill
    //   - No flow info at all: blank string (don't show a misleading pill)
    const _statusPillStyles = {
      quoteChina:        { bg: 'rgba(150,150,150,0.14)', fg: '#6b7280', bd: 'rgba(150,150,150,0.35)', label: 'Quote' },
      quoteSubmitted:    { bg: 'rgba(107,147,255,0.12)', fg: '#6b93ff', bd: 'rgba(107,147,255,0.35)', label: 'Submitted' },
      quoteClient:       { bg: 'rgba(107,147,255,0.18)', fg: '#6b93ff', bd: 'rgba(107,147,255,0.45)', label: 'Quote Sent' },
      clientApproved:    { bg: 'rgba(232,117,26,0.12)',  fg: 'var(--accent)', bd: 'rgba(232,117,26,0.35)', label: 'Approved' },
      officeInvoice:     { bg: 'rgba(232,117,26,0.18)',  fg: 'var(--accent)', bd: 'rgba(232,117,26,0.45)', label: 'Invoiced' },
      confirmedPayment:  { bg: 'rgba(22,163,74,0.12)',   fg: '#16a34a', bd: 'rgba(22,163,74,0.35)', label: 'Paid' },
      orderChina:        { bg: 'rgba(22,163,74,0.20)',   fg: '#16a34a', bd: 'rgba(22,163,74,0.55)', label: 'Ordered' },
      complete:          { bg: 'rgba(22,163,74,0.20)',   fg: '#16a34a', bd: 'rgba(22,163,74,0.55)', label: 'Complete' },
      archived:          { bg: 'rgba(150,150,150,0.10)', fg: '#9ca3af', bd: 'rgba(150,150,150,0.30)', label: 'Archived' },
    };
    const statusPillFor = (clientName, workbookId) => {
      const wbs = clientData[clientName] || [];
      const wb  = wbs.find(x => parseInt(x.id) === parseInt(workbookId));
      if (!wb) return _statusPillStyles.archived;
      const flow = wb.flow || {};
      if (typeof isFlowComplete === 'function' && isFlowComplete(flow)) return _statusPillStyles.complete;
      let lastKey = null;
      for (let i = flowSteps.length - 1; i >= 0; i--) {
        if (flow[flowSteps[i]]) { lastKey = flowSteps[i]; break; }
      }
      return lastKey ? _statusPillStyles[lastKey] : null;
    };
    const renderStatusPill = (clientName, workbookId) => {
      const s = statusPillFor(clientName, workbookId);
      if (!s) return '';
      return `<span style="background:${s.bg}; color:${s.fg}; border:1px solid ${s.bd}; padding:1px 7px; border-radius:9px; font-size:10px; font-weight:700; white-space:nowrap; text-transform:uppercase; letter-spacing:0.04em;">${s.label}</span>`;
    };

    // Relative-age helper: '3d ago' / '2w ago' / '4mo ago' / 'today'.
    // Used both for row age (since created_at) and "paid X ago" hover
    // copy on archived rows.
    const _ageAgo = (iso) => {
      if (!iso) return '';
      const d = new Date(iso);
      if (isNaN(d.getTime())) return '';
      const ms = Date.now() - d.getTime();
      const day = Math.floor(ms / 86400000);
      if (day <= 0) return 'today';
      if (day < 7)  return `${day}d ago`;
      if (day < 30) return `${Math.floor(day / 7)}w ago`;
      if (day < 365) return `${Math.floor(day / 30)}mo ago`;
      return `${Math.floor(day / 365)}y ago`;
    };

    // "Archived" = paid AND paid_at is in a calendar month BEFORE the
    // current one. Active rows include all pending + this-month-paid
    // rows. Lets the operator close out a month visually without losing
    // the history.
    const _now = new Date();
    const _curYear  = _now.getFullYear();
    const _curMonth = _now.getMonth();
    const _isArchivedRow = (r) => {
      if (r.status !== 'paid' || !r.paid_at) return false;
      const p = new Date(r.paid_at);
      if (isNaN(p.getTime())) return false;
      return (p.getFullYear() < _curYear) ||
             (p.getFullYear() === _curYear && p.getMonth() < _curMonth);
    };

    // Stable role order: AM → Sales → Ops → anything else. Hoisted
    // to buildEmployeeBreakdown scope so both the active and the
    // archived role-grouping use the same ordering.
    const roleOrder = ['account_manager', 'salesperson', 'operations'];

    const buildEmployeeBreakdown = (empName) => {
      const myRows = rows.filter(r => r.employee === empName);
      if (!myRows.length) {
        return `<div style="margin-top:14px; padding-top:14px; border-top:1px dashed var(--border); font-size:12px; color:var(--text-muted);">No commissions match the current filters.</div>`;
      }
      // Split into active (pending + this-month paid) and archived
      // (paid in a previous calendar month). Both halves group by
      // client; archived sits inside a collapsible section below.
      const activeRows   = myRows.filter(r => !_isArchivedRow(r));
      const archivedRows = myRows.filter(r =>  _isArchivedRow(r));
      const byClient = {};
      activeRows.forEach(r => {
        const c = r.client_name || '—';
        if (!byClient[c]) byClient[c] = [];
        byClient[c].push(r);
      });
      const clientNames = Object.keys(byClient).sort((a, b) => {
        const sa = byClient[a].reduce((s, r) => s + (parseFloat(r.commission_amount) || 0), 0);
        const sb = byClient[b].reduce((s, r) => s + (parseFloat(r.commission_amount) || 0), 0);
        return sb - sa;
      });
      // Single-row renderer: workbook + status + age | client total |
      // commission $ | paid toggle. Role + rate live in the role-group
      // header above so they're not repeated on every row — gives the
      // workbook pill the horizontal room it needs to actually show
      // the product name instead of "Med…" / "Lar…".
      // `archived=true` switches the row to a muted treatment + pulls
      // its age from paid_at instead of created_at, so the same
      // function powers both the active section and the prior-months
      // drawer below it.
      const renderCommissionRow = (r, archived = false) => {
        const wbHash = `/client/${encodeURIComponent(r.client_name)}/workbook/${r.workbook_id}`;
        const wbClick = `event.stopPropagation(); location.hash='${wbHash}'`;
        const product = esc(r.product_name) || '—';
        const isEst = +r.is_estimate === 1;
        const isPaid = r.status === 'paid';
        const rowBg = archived
          ? 'rgba(150,150,150,0.06)'
          : (isPaid ? 'rgba(22,163,74,0.12)' : 'var(--surface)');
        const rowBorder = archived
          ? '1px solid var(--border)'
          : (isPaid ? '1px solid rgba(22,163,74,0.35)' : '1px solid transparent');
        const leftAccent = archived
          ? '3px solid rgba(22,163,74,0.35)'
          : (isPaid ? '3px solid rgba(22,163,74,0.35)' : '1px solid transparent');
        const opacity = archived ? '0.85' : '1';
        const paidTitle = archived
          ? 'Mark this commission as pending again (e.g. paid in error)'
          : (isPaid && r.paid_at
              ? `Paid ${new Date(r.paid_at).toLocaleDateString()} — click to mark pending`
              : 'Click to mark this commission as paid');
        const statusPillHtml = renderStatusPill(r.client_name, r.workbook_id);
        const ageSrc = archived ? r.paid_at : r.created_at;
        const ageStr = _ageAgo(ageSrc);
        const ageLabel = archived ? `paid ${ageStr}` : ageStr;
        const ageHtml = ageStr
          ? `<span style="font-size:10px; color:var(--text-muted); font-variant-numeric:tabular-nums; white-space:nowrap;" title="${archived ? 'Paid' : 'Commission row created'} ${ageSrc ? new Date(ageSrc).toLocaleString() : ''}">${ageLabel}</span>`
          : '';
        // Paid button toggles back to pending on click. The .comm-paid-btn
        // / .comm-pay-btn classes carry the hover treatment — the Paid
        // button morphs on hover into an outlined 'Unpay' look so the
        // toggle affordance is obvious (operator wasn't sure clicking
        // would revert before).
        const buttonHtml = (archived || isPaid)
          ? `<button type="button" class="comm-paid-btn"
              onclick="event.stopPropagation(); setCommissionPaid(${r.id}, false)"
              title="${paidTitle}">
              <svg class="comm-paid-check" width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg>
              <span class="comm-paid-label">Paid</span>
              <span class="comm-paid-unpay">Unpay</span>
            </button>`
          : `<button type="button" class="comm-pay-btn"
              onclick="event.stopPropagation(); setCommissionPaid(${r.id}, true)"
              title="${paidTitle}">
              Mark paid
            </button>`;

        // Sub-line shows the client total this commission was rated
        // against (e.g. "Quote: $16,223") plus the age — small, muted,
        // tucked under the workbook pill so the main line stays clean.
        const subParts = [];
        if (r.client_total_usd) subParts.push(`Quote: <strong style="color:var(--text); font-weight:600;">${fmtUsd0(r.client_total_usd)}</strong>`);
        if (ageStr)             subParts.push(archived ? `paid ${ageStr}` : ageStr);
        const subHtml = subParts.length
          ? `<div style="font-size:10px; color:var(--text-muted); margin-top:3px; padding-left:2px; font-variant-numeric:tabular-nums;">${subParts.join(' &nbsp;·&nbsp; ')}</div>`
          : '';

        return `
          <div class="comm-row" style="display:flex; align-items:center; gap:12px; padding:8px 10px; border-radius:6px; background:${rowBg}; border:${rowBorder}; border-left:${leftAccent}; opacity:${opacity};">
            <div style="flex:1 1 auto; min-width:0; display:flex; flex-direction:column;">
              <div style="display:flex; align-items:center; gap:8px; min-width:0;">
                <span class="inv-wb-pill" onclick="${wbClick}" title="${product}" style="min-width:0; max-width:100%; flex:0 1 auto;">
                  <span class="inv-wb-pill-text">${product}</span><span class="inv-wb-pill-arrow">→</span>
                </span>
                ${statusPillHtml}
              </div>
              ${subHtml}
            </div>
            <span style="font-size:14px; color:var(--success, #16a34a); font-weight:700; font-variant-numeric:tabular-nums; text-align:right; min-width:90px; white-space:nowrap; flex-shrink:0;">
              ${fmtUsd(r.commission_amount)}${isEst ? '<span style="margin-left:4px; font-size:10px; color:var(--text-muted); font-style:italic;" title="Estimate — Client Cost not yet wired">est</span>' : ''}
            </span>
            ${buttonHtml}
          </div>`;
      };

      const clientBlocks = clientNames.map(c => {
        const cRows = byClient[c];
        const cSubtotal = cRows.reduce((s, r) => s + (parseFloat(r.commission_amount) || 0), 0);
        const clientHash = `/client/${encodeURIComponent(c)}`;
        const clientChipClick = `event.stopPropagation(); location.hash='${clientHash}'`;

        // Group this client's rows by role so the role pill + rate
        // appear once as a section header instead of repeating on
        // every row. When all rows in a role group share the same
        // rate the header reads "AM · 5%"; if they differ (rare —
        // workbook-level overrides) the header reads "AM · varies"
        // and the per-row rate is shown inline next to the amount.
        const byRole = {};
        cRows.forEach(r => {
          const k = r.role || '—';
          if (!byRole[k]) byRole[k] = [];
          byRole[k].push(r);
        });
        const roleKeys = Object.keys(byRole).sort((a, b) => {
          const ai = roleOrder.indexOf(a); const bi = roleOrder.indexOf(b);
          return (ai === -1 ? 99 : ai) - (bi === -1 ? 99 : bi);
        });
        // Per-client paid totals — feed both the client header chip
        // ("$X paid of $Y") and the green progress bar underneath it.
        const cPaidTotal  = cRows.reduce((s, r) => s + (r.status === 'paid' ? (parseFloat(r.commission_amount) || 0) : 0), 0);
        const cPaidPct    = cSubtotal > 0 ? Math.min(100, (cPaidTotal / cSubtotal) * 100) : 0;
        const cPaidCount  = cRows.filter(r => r.status === 'paid').length;
        const cFullyPaid  = cPaidCount === cRows.length && cRows.length > 0;

        const roleGroups = roleKeys.map(roleKey => {
          const rows = byRole[roleKey];
          const rates = [...new Set(rows.map(r => parseFloat(r.commission_rate) || 0))];
          const rateLabel = rates.length === 1 ? fmtRate(rates[0]) : 'varies';
          const groupTotal = rows.reduce((s, r) => s + (parseFloat(r.commission_amount) || 0), 0);
          // Per-role paid totals so the role header can show progress
          // independently when a client has multiple roles (AM + SP +
          // Ops on the same workbooks).
          const groupPaid  = rows.reduce((s, r) => s + (r.status === 'paid' ? (parseFloat(r.commission_amount) || 0) : 0), 0);
          const groupPct   = groupTotal > 0 ? Math.min(100, (groupPaid / groupTotal) * 100) : 0;
          const groupFully = groupPaid > 0 && groupPaid >= groupTotal - 0.005;
          const wbRows = rows.map(renderCommissionRow).join('');
          // Right-side summary: '$X paid of $Y' + tiny inline progress
          // chip. Color shifts from muted → green as more is paid.
          const groupPaidLabel = groupPaid > 0
            ? `<span style="color:#16a34a; font-weight:700;">${fmtUsd(groupPaid)}</span> <span style="color:var(--text-muted); font-weight:500;">paid of</span> <span style="color:var(--text); font-weight:700;">${fmtUsd(groupTotal)}</span>`
            : `<span style="color:var(--text-muted); font-weight:500;">0 paid of</span> <span style="color:var(--text); font-weight:700;">${fmtUsd(groupTotal)}</span>`;
          return `
            <div style="margin-bottom:8px;">
              <div style="display:flex; align-items:center; gap:8px; padding:4px 4px 4px; font-size:11px; color:var(--text-muted); font-weight:600;">
                ${rolePill(roleKey)}
                <span style="font-variant-numeric:tabular-nums;">${rateLabel}</span>
                <span style="margin-left:auto; font-variant-numeric:tabular-nums; font-size:11px;">${groupPaidLabel}${groupFully ? ' <span style="color:#16a34a; font-weight:700;">✓</span>' : ''}</span>
              </div>
              <!-- Progress bar — green fill grows as rows are marked paid.
                   3px tall, sits between the role header and the rows. -->
              <div style="height:3px; background:rgba(22,163,74,0.10); border-radius:99px; overflow:hidden; margin:0 4px 6px;">
                <div style="height:100%; width:${groupPct}%; background:#16a34a; border-radius:99px; transition:width 0.25s ease;"></div>
              </div>
              <div style="display:flex; flex-direction:column; gap:5px;">${wbRows}</div>
            </div>`;
        }).join('');

        // Client-level paid summary in the header line — same colour
        // language as the role header so the eye reads them as one
        // system ("how much have I paid this client this month").
        const cPaidLabel = cPaidTotal > 0
          ? `<span style="color:#16a34a; font-weight:700;">${fmtUsd(cPaidTotal)}</span> <span style="color:var(--text-muted);">paid of</span> <span style="color:var(--text); font-weight:700;">${fmtUsd(cSubtotal)}</span>`
          : `<span style="color:var(--text-muted);">0 paid of</span> <span style="color:var(--text); font-weight:700;">${fmtUsd(cSubtotal)}</span>`;

        return `
          <div style="margin-bottom:14px;">
            <div style="display:flex; align-items:center; justify-content:space-between; margin-bottom:4px; gap:10px;">
              <span class="inv-client-chip" onclick="${clientChipClick}" style="${_clientChipStyle(c)} cursor:pointer; max-width:60%; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;" title="${esc(c)} — open client">${esc(c)}</span>
              <span style="font-size:11px; color:var(--text-muted); font-weight:600; white-space:nowrap; font-variant-numeric:tabular-nums;">
                ${cRows.length} workbook${cRows.length !== 1 ? 's' : ''} &nbsp;·&nbsp; ${cPaidLabel}${cFullyPaid ? ' <span style="color:#16a34a; font-weight:700;">✓</span>' : ''}
              </span>
            </div>
            <!-- Client-level progress — slightly taller (4px) than the
                 per-role bars so the visual hierarchy stays clear. -->
            <div style="height:4px; background:rgba(22,163,74,0.10); border-radius:99px; overflow:hidden; margin:0 0 10px;">
              <div style="height:100%; width:${cPaidPct}%; background:#16a34a; border-radius:99px; transition:width 0.25s ease;"></div>
            </div>
            ${roleGroups}
          </div>
        `;
      }).join('');
      // Archived (paid in a previous calendar month) — collapsed by
      // default behind a count-bearing toggle so the recent month
      // stays the focus, but the operator can still audit / un-pay
      // older rows on demand. Per-row markup mirrors the active
      // section, just rendered inside the collapsed block.
      let archivedHtml = '';
      if (archivedRows.length) {
        const archByClient = {};
        archivedRows.forEach(r => {
          const c = r.client_name || '—';
          if (!archByClient[c]) archByClient[c] = [];
          archByClient[c].push(r);
        });
        const archClientNames = Object.keys(archByClient).sort((a, b) => {
          const sa = archByClient[a].reduce((s, r) => s + (parseFloat(r.commission_amount) || 0), 0);
          const sb = archByClient[b].reduce((s, r) => s + (parseFloat(r.commission_amount) || 0), 0);
          return sb - sa;
        });
        const archSubtotal = archivedRows.reduce((s, r) => s + (parseFloat(r.commission_amount) || 0), 0);
        const archExpanded = _commArchiveExpanded.has(empName);
        const archBlocks = archClientNames.map(c => {
          const cRows = archByClient[c];
          const cSubtotal = cRows.reduce((s, r) => s + (parseFloat(r.commission_amount) || 0), 0);
          // Same role-grouping as the active section so the archive
          // reads with the same rhythm — no per-row AM/Sales/Ops pill
          // repetition, more space for the workbook name.
          const archByRole = {};
          cRows.forEach(r => {
            const k = r.role || '—';
            if (!archByRole[k]) archByRole[k] = [];
            archByRole[k].push(r);
          });
          const archRoleKeys = Object.keys(archByRole).sort((a, b) => {
            const ai = roleOrder.indexOf(a); const bi = roleOrder.indexOf(b);
            return (ai === -1 ? 99 : ai) - (bi === -1 ? 99 : bi);
          });
          const archRoleGroups = archRoleKeys.map(roleKey => {
            const rows = archByRole[roleKey];
            const rates = [...new Set(rows.map(r => parseFloat(r.commission_rate) || 0))];
            const rateLabel = rates.length === 1 ? fmtRate(rates[0]) : 'varies';
            const groupTotal = rows.reduce((s, r) => s + (parseFloat(r.commission_amount) || 0), 0);
            const wbRowsArch = rows.map(r => renderCommissionRow(r, true)).join('');
            return `
              <div style="margin-bottom:6px;">
                <div style="display:flex; align-items:center; gap:8px; padding:4px 4px 5px; font-size:11px; color:var(--text-muted); font-weight:600;">
                  ${rolePill(roleKey)}
                  <span style="font-variant-numeric:tabular-nums;">${rateLabel}</span>
                  <span style="margin-left:auto; color:var(--text); font-weight:700; font-variant-numeric:tabular-nums;">${fmtUsd(groupTotal)}</span>
                </div>
                <div style="display:flex; flex-direction:column; gap:5px;">${wbRowsArch}</div>
              </div>`;
          }).join('');
          return `
            <div style="margin-bottom:10px;">
              <div style="display:flex; align-items:center; justify-content:space-between; margin-bottom:4px; gap:10px;">
                <span style="font-size:11px; font-weight:700; color:var(--text-muted); text-transform:uppercase; letter-spacing:0.06em;">${esc(c)}</span>
                <span style="font-size:11px; color:var(--text-muted); font-weight:600; white-space:nowrap;">${cRows.length} row${cRows.length !== 1 ? 's' : ''} · ${fmtUsd(cSubtotal)}</span>
              </div>
              ${archRoleGroups}
            </div>`;
        }).join('');
        const chevronArch = `<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" style="transition:transform 0.2s; transform:rotate(${archExpanded ? 90 : 0}deg);"><polyline points="9 18 15 12 9 6"/></svg>`;
        archivedHtml = `
          <div style="margin-top:14px; padding-top:14px; border-top:1px dashed var(--border);">
            <div onclick="event.stopPropagation(); toggleCommissionArchive(${JSON.stringify(empName)})" style="display:flex; align-items:center; gap:8px; cursor:pointer; user-select:none; padding:6px 4px; font-size:11px; font-weight:700; text-transform:uppercase; letter-spacing:0.06em; color:var(--text-muted);">
              ${chevronArch}
              <span>Archived (prior months)</span>
              <span style="margin-left:auto; font-weight:700; color:var(--text);">${archivedRows.length} row${archivedRows.length !== 1 ? 's' : ''} · ${fmtUsd(archSubtotal)}</span>
            </div>
            ${archExpanded ? `<div style="margin-top:8px;">${archBlocks}</div>` : ''}
          </div>`;
      }
      return `
        <div style="margin-top:14px; padding-top:14px; border-top:1px dashed var(--border);">
          ${clientBlocks || '<div style="font-size:12px; color:var(--text-muted); padding:8px 0;">No active commissions this month.</div>'}
        </div>
        ${archivedHtml}
      `;
    };

    const empHtml = employees.length ? `
      <div class="section-card" style="padding:18px 20px; margin-bottom:18px;">
        <div class="inv-dash-row-title">Per-employee scoreboard</div>
        <div style="font-size:11px; color:var(--text-muted); margin-top:2px;">Click a card to see which clients and workbooks are paying out.</div>
        <div style="display:grid; grid-template-columns:repeat(auto-fit, minmax(280px, 1fr)); gap:14px; margin-top:10px;">
          ${employees.map(([name, t]) => {
            const expanded   = _commExpandedEmployees.has(name);
            const toggleAttr = `onclick='toggleEmployeeExpand(${JSON.stringify(name)})'`;
            // Chevron rotates 90° when the card is open. Pure CSS transform.
            const chevron = `
              <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor"
                   stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"
                   style="color:var(--text-muted); transition:transform 0.2s; transform:rotate(${expanded ? 90 : 0}deg);">
                <polyline points="9 18 15 12 9 6"/>
              </svg>`;
            // Paid % drives the thin progress bar under the header. When
            // total is 0 the bar stays empty (no divide-by-zero). When
            // every row on this card is paid the bar is fully green —
            // matches the Mark-Paid pill color so the visual story is
            // consistent: green = settled, gray = still owed.
            const paidPct = t.total > 0 ? Math.min(100, (t.paid / t.total) * 100) : 0;
            const allPaid = t.total > 0 && t.pending <= 0.005; // float fuzz
            return `
              <div style="border:1px solid var(--border); border-radius:12px; padding:16px; background:var(--surface2); min-width:0; ${expanded ? 'box-shadow: 0 0 0 1px var(--accent-glow) inset;' : ''}">
                <div ${toggleAttr} style="display:flex; flex-wrap:wrap; align-items:center; gap:10px; margin-bottom:10px; cursor:pointer; user-select:none;" title="Click to ${expanded ? 'collapse' : 'expand'} breakdown">
                  <div style="width:36px; height:36px; flex-shrink:0; border-radius:50%; background:var(--accent-glow); color:var(--accent); display:flex; align-items:center; justify-content:center; font-weight:700; font-size:14px;">
                    ${esc((name || '?').split(/\s+/).map(w => w[0]).join('').slice(0,2).toUpperCase())}
                  </div>
                  <div style="flex:1 1 100px; min-width:0;">
                    <div style="font-weight:600; color:var(--text); font-size:14px; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;">${esc(name)}</div>
                    <div style="font-size:11px; color:var(--text-muted);">${t.count} row${t.count !== 1 ? 's' : ''}</div>
                  </div>
                  <div style="margin-left:auto; font-size:20px; font-weight:700; color:var(--text); font-variant-numeric:tabular-nums; white-space:nowrap;">${fmtUsd(t.total)}</div>
                  ${chevron}
                </div>

                <!-- Paid vs pending strip — one line of labels + a thin
                     progress bar. Green portion = paid, gray = pending.
                     Lets the operator glance at a card and see how much
                     of this person's earnings have actually been paid out
                     without having to expand the breakdown. -->
                <div style="margin-bottom:12px;">
                  <div style="display:flex; justify-content:space-between; align-items:center; font-size:11px; margin-bottom:5px; gap:8px;">
                    <span style="color:#16a34a; font-weight:600; display:inline-flex; align-items:center; gap:4px;">
                      <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg>
                      Paid ${fmtUsd(t.paid)}
                    </span>
                    <span style="color:var(--text-muted); font-weight:600;">Pending ${fmtUsd(t.pending)}</span>
                  </div>
                  <div style="height:4px; border-radius:2px; background:var(--border); overflow:hidden;" title="${paidPct.toFixed(0)}% paid">
                    <div style="height:100%; width:${paidPct}%; background:#16a34a; transition:width 0.25s;"></div>
                  </div>
                  ${allPaid ? '<div style="font-size:10px; color:#16a34a; font-weight:700; margin-top:5px; text-transform:uppercase; letter-spacing:0.05em;">All settled</div>' : ''}
                </div>

                <div style="display:grid; grid-template-columns:repeat(auto-fit, minmax(110px, 1fr)); gap:10px;">
                  <div style="padding:8px 10px; border-radius:8px; background:rgba(107,147,255,0.1); border:1px solid rgba(107,147,255,0.2);">
                    <div style="font-size:10px; font-weight:700; color:var(--text-muted); text-transform:uppercase; letter-spacing:0.05em;">Account Mgr</div>
                    <div style="font-size:15px; font-weight:600; color:var(--text); margin-top:2px;">${fmtUsd(t.am)}</div>
                  </div>
                  <div style="padding:8px 10px; border-radius:8px; background:rgba(232,117,26,0.08); border:1px solid rgba(232,117,26,0.2);">
                    <div style="font-size:10px; font-weight:700; color:var(--text-muted); text-transform:uppercase; letter-spacing:0.05em;">Salesperson</div>
                    <div style="font-size:15px; font-weight:600; color:var(--text); margin-top:2px;">${fmtUsd(t.sp)}</div>
                  </div>
                  ${t.op > 0 ? `
                    <div style="padding:8px 10px; border-radius:8px; background:rgba(22,163,74,0.1); border:1px solid rgba(22,163,74,0.25);">
                      <div style="font-size:10px; font-weight:700; color:var(--text-muted); text-transform:uppercase; letter-spacing:0.05em;">Operations</div>
                      <div style="font-size:15px; font-weight:600; color:var(--text); margin-top:2px;">${fmtUsd(t.op)}</div>
                    </div>
                  ` : ''}
                </div>
                ${expanded ? buildEmployeeBreakdown(name) : ''}
              </div>
            `;
          }).join('')}
        </div>
      </div>
    ` : '';

    // ── Earnings over time ──────────────────────────────────────────────
    // Bucket commissions by month, year, AND employee so the chart can
    // show per-individual stacks and the "Per individual" section below
    // can render a mini 12-month chart per person. Status (paid vs
    // pending) is also tracked so the year-summary strip and tooltips
    // can still surface the payout split.
    const monthBuckets    = {}; // 'YYYY-MM' -> { total, pending, paid }
    const yearBuckets     = {}; // YYYY      -> { total, pending, paid }
    const monthEmpBuckets = {}; // 'YYYY-MM' -> { [employee]: amount }
    const yearEmpBuckets  = {}; // YYYY      -> { [employee]: { total, paid, pending } }
    const allEmployees    = new Set();
    rows.forEach(r => {
      const ts = r.created_at;
      if (!ts) return;
      const d = new Date(ts);
      if (isNaN(d.getTime())) return;
      const yyyy = d.getFullYear();
      const mm   = String(d.getMonth() + 1).padStart(2, '0');
      const key  = `${yyyy}-${mm}`;
      const amt  = parseFloat(r.commission_amount) || 0;
      const emp  = (r.employee || '—').trim() || '—';
      allEmployees.add(emp);
      if (!monthBuckets[key])      monthBuckets[key]      = { total: 0, pending: 0, paid: 0 };
      if (!yearBuckets[yyyy])      yearBuckets[yyyy]      = { total: 0, pending: 0, paid: 0 };
      if (!monthEmpBuckets[key])   monthEmpBuckets[key]   = {};
      if (!yearEmpBuckets[yyyy])   yearEmpBuckets[yyyy]   = {};
      if (!monthEmpBuckets[key][emp])  monthEmpBuckets[key][emp]  = 0;
      if (!yearEmpBuckets[yyyy][emp])  yearEmpBuckets[yyyy][emp]  = { total: 0, paid: 0, pending: 0 };
      monthBuckets[key].total += amt;
      yearBuckets[yyyy].total += amt;
      monthEmpBuckets[key][emp] += amt;
      yearEmpBuckets[yyyy][emp].total += amt;
      if (r.status === 'paid') {
        monthBuckets[key].paid += amt;
        yearBuckets[yyyy].paid += amt;
        yearEmpBuckets[yyyy][emp].paid += amt;
      } else {
        monthBuckets[key].pending += amt;
        yearBuckets[yyyy].pending += amt;
        yearEmpBuckets[yyyy][emp].pending += amt;
      }
    });

    const yearsAvailable = Object.keys(yearBuckets).map(Number).sort((a, b) => b - a);
    // Clamp the selected year to one that actually has data under the
    // current filters. If nothing matches, fall back to current calendar
    // year so the chart still renders an empty 12-month skeleton.
    let selectedYear = _commTimeYear;
    if (!yearsAvailable.includes(selectedYear)) {
      selectedYear = yearsAvailable[0] || new Date().getFullYear();
    }

    const monthAbbr = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
    const monthValues = monthAbbr.map((_, idx) => {
      const mm = String(idx + 1).padStart(2, '0');
      return monthBuckets[`${selectedYear}-${mm}`] || { total: 0, pending: 0, paid: 0 };
    });
    const maxMonthTotal = Math.max(0.01, ...monthValues.map(m => m.total));
    const yearTot   = yearBuckets[selectedYear]?.total   || 0;
    const yearPend  = yearBuckets[selectedYear]?.pending || 0;
    const yearPaid  = yearBuckets[selectedYear]?.paid    || 0;
    const monthsWith = monthValues.filter(m => m.total > 0).length;
    const avgPerMonth = monthsWith > 0 ? yearTot / monthsWith : 0;

    // Order employees by their selected-year contribution (largest first)
    // so colors and rows below tell a consistent story. Anyone with zero
    // in the selected year still appears in the legend if they had rows
    // in *any* year — that way a low-volume month doesn't make a person
    // visually disappear from the team view.
    const empOrderForYear = Array.from(allEmployees).sort((a, b) => {
      const ay = (yearEmpBuckets[selectedYear]?.[a]?.total) || 0;
      const by = (yearEmpBuckets[selectedYear]?.[b]?.total) || 0;
      if (by !== ay) return by - ay;
      return a.localeCompare(b);
    });

    // Year selector — uses the same custom-arrow pattern as the rest of
    // the app's dropdowns. Always include `selectedYear` in the option
    // list even if it has no rows, so the dropdown reflects current state.
    const yearOptionSet = Array.from(new Set([...yearsAvailable, selectedYear])).sort((a, b) => b - a);
    const yearSelector = `
      <span class="ship-select-wrap" style="min-width:120px;">
        <select onchange="setCommTimeYear(this.value)"
          style="width:100%; height:32px; padding:0 30px 0 12px; border:1px solid var(--border); border-radius:8px; background:var(--surface2); color:var(--text); font-size:13px; font-family:inherit; outline:none; cursor:pointer; appearance:none; -webkit-appearance:none; font-weight:600;">
          ${yearOptionSet.map(y => `<option value="${y}"${y === selectedYear ? ' selected' : ''}>${y}</option>`).join('')}
        </select>
      </span>
    `;

    // Per-employee color legend, ordered like the stack (top -> bottom of
    // each bar matches left -> right of legend). Click a chip to focus
    // just that person — drives `_commTimeFocusEmp`.
    const empLegendHtml = empOrderForYear.length ? `
      <div style="display:flex; flex-wrap:wrap; gap:8px; margin-top:10px;">
        ${empOrderForYear.map(emp => {
          const isFocused = _commTimeFocusEmp === emp;
          const isDimmed  = _commTimeFocusEmp && !isFocused;
          const sw = _employeeSwatch(emp);
          return `
            <button onclick="setCommTimeFocusEmp(${JSON.stringify(emp)})"
              title="${esc(emp)} — click to focus${isFocused ? ' (click again to clear)' : ''}"
              style="cursor:pointer; display:inline-flex; align-items:center; gap:6px; padding:4px 10px; border-radius:999px; font-family:inherit; font-size:12px; font-weight:600;
                     background:${isFocused ? sw.fill : 'var(--surface2)'};
                     color:${isFocused ? '#fff' : 'var(--text)'};
                     border:1px solid ${isFocused ? sw.fill : 'var(--border)'};
                     opacity:${isDimmed ? 0.45 : 1};
                     transition:opacity 0.1s, transform 0.1s;"
              onmouseenter="this.style.transform='translateY(-1px)'"
              onmouseleave="this.style.transform=''">
              <span style="width:10px; height:10px; border-radius:3px; background:${sw.fill};"></span>
              <span style="white-space:nowrap; overflow:hidden; text-overflow:ellipsis; max-width:160px;">${esc(emp)}</span>
            </button>
          `;
        }).join('')}
        ${_commTimeFocusEmp ? `
          <button onclick="setCommTimeFocusEmp(null)"
            style="cursor:pointer; padding:4px 10px; border-radius:999px; font-family:inherit; font-size:12px; font-weight:600;
                   background:transparent; color:var(--text-muted); border:1px dashed var(--border);">
            Clear focus
          </button>` : ''}
      </div>
    ` : '';

    // The main chart. Each column is a flex-column: $ label on top, bar
    // at the bottom (anchored via flex-end), month abbr below. Each bar
    // is now stacked by employee — segments ordered to match the legend
    // (top of stack = first in legend) so the eye can follow names left
    // to right, top to bottom. min-height keeps tiny months visible.
    const chartHtml = `
      <div style="display:grid; grid-template-columns:repeat(12, 1fr); gap:6px; height:170px; margin-top:12px;">
        ${monthValues.map((m, idx) => {
          const mmKey = `${selectedYear}-${String(idx + 1).padStart(2, '0')}`;
          const empMap = monthEmpBuckets[mmKey] || {};
          // When a person is focused, only their slice contributes to
          // the visible bar height — everyone else's segments collapse.
          const visibleTotal = _commTimeFocusEmp
            ? (empMap[_commTimeFocusEmp] || 0)
            : m.total;
          const heightPct = (visibleTotal / maxMonthTotal) * 100;

          // Build per-employee segments in legend order. flex-direction
          // column-reverse stacks them upward, so reverse the legend
          // here so the first legend entry sits at the *top* of the
          // stack (most-prominent person on top).
          const segs = empOrderForYear
            .filter(emp => !_commTimeFocusEmp || emp === _commTimeFocusEmp)
            .map(emp => {
              const v = empMap[emp] || 0;
              if (v <= 0) return '';
              const pctOfBar = visibleTotal > 0 ? (v / visibleTotal) * 100 : 0;
              const sw = _employeeSwatch(emp);
              return `<div style="height:${pctOfBar}%; background:${sw.fill};" title="${esc(emp)}: ${esc(fmtUsd(v))}"></div>`;
            }).reverse().join('');

          // Build a textual tooltip listing every employee with money in
          // this month, plus the paid/pending split.
          const empLines = Object.entries(empMap)
            .filter(([, v]) => v > 0)
            .sort((a, b) => b[1] - a[1])
            .map(([emp, v]) => `${emp}: ${fmtUsd(v)}`).join(' · ');
          const tooltip = `${monthAbbr[idx]} ${selectedYear}: ${fmtUsd(m.total)}` +
                          (empLines ? ` — ${empLines}` : '') +
                          (m.paid > 0    ? ` · paid ${fmtUsd(m.paid)}`       : '') +
                          (m.pending > 0 ? ` · pending ${fmtUsd(m.pending)}` : '');
          const labelTotal = _commTimeFocusEmp ? visibleTotal : m.total;
          return `
            <div style="display:flex; flex-direction:column; align-items:center; min-width:0;">
              <div style="font-size:9px; color:var(--text-muted); font-variant-numeric:tabular-nums; height:14px; line-height:14px; white-space:nowrap; overflow:hidden;">
                ${labelTotal > 0 ? fmtUsd0(labelTotal) : ''}
              </div>
              <div style="flex:1; width:100%; display:flex; align-items:flex-end; justify-content:center; padding:2px 0;">
                <div style="width:80%; max-width:32px; height:${heightPct}%; ${visibleTotal > 0 ? 'min-height:3px;' : ''} display:flex; flex-direction:column-reverse; border-radius:5px 5px 0 0; overflow:hidden; background:var(--surface);"
                     title="${esc(tooltip)}">
                  ${segs}
                </div>
              </div>
              <div style="font-size:10px; color:var(--text-muted); margin-top:4px; font-weight:600;">${monthAbbr[idx]}</div>
            </div>
          `;
        }).join('')}
      </div>
    `;

    // Per-individual section: one row per employee with a 12-month mini
    // bar chart (their own scale), year total, and paid/pending split.
    // Each person uses the *same* color as in the main stack so the eye
    // can track them between the two views without a second mental hop.
    const perIndividualHtml = empOrderForYear.length ? `
      <div style="margin-top:20px; padding-top:14px; border-top:1px dashed var(--border);">
        <div style="display:flex; align-items:center; justify-content:space-between; gap:10px; flex-wrap:wrap; margin-bottom:10px;">
          <div style="font-size:11px; font-weight:700; color:var(--text-muted); text-transform:uppercase; letter-spacing:0.06em;">Per individual — ${selectedYear}</div>
          <div style="font-size:11px; color:var(--text-muted);">Each row scaled to that person's biggest month</div>
        </div>
        <div style="display:flex; flex-direction:column; gap:8px;">
          ${empOrderForYear.map(emp => {
            const sw = _employeeSwatch(emp);
            const empMonths = monthAbbr.map((_, idx) => {
              const mmKey = `${selectedYear}-${String(idx + 1).padStart(2, '0')}`;
              return (monthEmpBuckets[mmKey]?.[emp]) || 0;
            });
            const empMax = Math.max(0.01, ...empMonths);
            const empYearStats = yearEmpBuckets[selectedYear]?.[emp] || { total: 0, paid: 0, pending: 0 };
            const isFocused = _commTimeFocusEmp === emp;
            const isDimmed  = _commTimeFocusEmp && !isFocused;
            return `
              <div style="display:grid; grid-template-columns:minmax(140px, 180px) 1fr minmax(150px, 180px); gap:14px; align-items:center;
                          padding:8px 10px; border-radius:10px; background:var(--surface2); border:1px solid var(--border);
                          opacity:${isDimmed ? 0.5 : 1}; transition:opacity 0.1s;">
                <div style="display:flex; align-items:center; gap:8px; min-width:0;">
                  <span style="width:10px; height:10px; border-radius:3px; background:${sw.fill}; flex-shrink:0;"></span>
                  <span style="font-weight:600; color:var(--text); font-size:13px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;" title="${esc(emp)}">${esc(emp)}</span>
                </div>
                <div style="display:grid; grid-template-columns:repeat(12, 1fr); gap:3px; height:38px;">
                  ${empMonths.map((v, idx) => {
                    const h = (v / empMax) * 100;
                    const tip = v > 0 ? `${monthAbbr[idx]} ${selectedYear}: ${fmtUsd(v)}` : `${monthAbbr[idx]} ${selectedYear}: —`;
                    return `
                      <div style="display:flex; flex-direction:column; align-items:center; justify-content:flex-end; min-width:0;" title="${esc(tip)}">
                        <div style="width:100%; height:${h}%; ${v > 0 ? 'min-height:2px;' : ''} background:${v > 0 ? sw.fill : 'transparent'}; border-radius:3px 3px 0 0;"></div>
                      </div>
                    `;
                  }).join('')}
                </div>
                <div style="display:flex; flex-direction:column; align-items:flex-end; gap:2px; font-variant-numeric:tabular-nums;">
                  <span style="font-size:14px; font-weight:700; color:var(--text);">${fmtUsd(empYearStats.total)}</span>
                  <span style="font-size:10px; color:var(--text-muted);">
                    ${empYearStats.paid > 0    ? `<span style="color:var(--success, #16a34a); font-weight:600;">${fmtUsd0(empYearStats.paid)}</span> paid`       : ''}
                    ${empYearStats.paid > 0 && empYearStats.pending > 0 ? ' · ' : ''}
                    ${empYearStats.pending > 0 ? `<span style="color:var(--accent); font-weight:600;">${fmtUsd0(empYearStats.pending)}</span> pending` : ''}
                    ${empYearStats.total === 0 ? 'No earnings this year' : ''}
                  </span>
                </div>
              </div>
            `;
          }).join('')}
        </div>
      </div>
    ` : '';

    // All-year totals strip — clickable chips so you can jump between
    // years. Each chip now lists per-employee splits underneath the
    // year total, so you can see who carried which year at a glance.
    const allYearChips = yearsAvailable.length ? `
      <div style="margin-top:18px; padding-top:14px; border-top:1px dashed var(--border);">
        <div style="font-size:11px; font-weight:700; color:var(--text-muted); text-transform:uppercase; letter-spacing:0.06em; margin-bottom:8px;">All years</div>
        <div style="display:flex; flex-wrap:wrap; gap:10px;">
          ${yearsAvailable.map(y => {
            const isActive = y === selectedYear;
            const tot = yearBuckets[y].total;
            const empSplits = Object.entries(yearEmpBuckets[y] || {})
              .filter(([, v]) => v.total > 0)
              .sort((a, b) => b[1].total - a[1].total);
            return `
              <button onclick="setCommTimeYear(${y})"
                style="cursor:pointer; padding:10px 14px; border-radius:10px; font-family:inherit; text-align:left; min-width:160px;
                       background:${isActive ? 'var(--accent-glow)' : 'var(--surface2)'};
                       border:1px solid ${isActive ? 'color-mix(in srgb, var(--accent) 50%, var(--border))' : 'var(--border)'};
                       color:${isActive ? 'var(--accent)' : 'var(--text)'};
                       display:inline-flex; flex-direction:column; align-items:flex-start; gap:6px;
                       transition:transform 0.1s, box-shadow 0.1s;"
                onmouseenter="this.style.transform='translateY(-1px)'"
                onmouseleave="this.style.transform=''">
                <span style="font-size:10px; font-weight:700; color:var(--text-muted); text-transform:uppercase; letter-spacing:0.06em;">${y}</span>
                <span style="font-size:14px; font-weight:700; font-variant-numeric:tabular-nums;">${fmtUsd0(tot)}</span>
                ${empSplits.length ? `
                  <span style="display:flex; flex-direction:column; gap:2px; width:100%;">
                    ${empSplits.map(([emp, v]) => {
                      const sw = _employeeSwatch(emp);
                      return `
                        <span style="display:flex; align-items:center; gap:6px; font-size:11px; color:var(--text-muted); font-weight:500;">
                          <span style="width:8px; height:8px; border-radius:2px; background:${sw.fill}; flex-shrink:0;"></span>
                          <span style="white-space:nowrap; overflow:hidden; text-overflow:ellipsis; max-width:90px;" title="${esc(emp)}">${esc(emp)}</span>
                          <span style="margin-left:auto; font-variant-numeric:tabular-nums; color:var(--text); font-weight:600;">${fmtUsd0(v.total)}</span>
                        </span>
                      `;
                    }).join('')}
                  </span>
                ` : ''}
              </button>
            `;
          }).join('')}
        </div>
      </div>
    ` : '';

    // Pill-style mini summary above the chart so the headline numbers for
    // the *selected year* are obvious at a glance.
    const yearSummaryStrip = `
      <div style="display:flex; flex-wrap:wrap; gap:18px; align-items:center; font-size:12px; color:var(--text-muted); margin-top:6px;">
        <span><strong style="color:var(--text); font-size:15px; font-weight:700;">${fmtUsd(yearTot)}</strong> total</span>
        <span>·</span>
        <span><strong style="color:var(--accent); font-weight:700;">${fmtUsd(yearPend)}</strong> pending</span>
        <span>·</span>
        <span><strong style="color:var(--success, #16a34a); font-weight:700;">${fmtUsd(yearPaid)}</strong> paid</span>
        <span>·</span>
        <span>${fmtUsd(avgPerMonth)} avg/mo${monthsWith ? ` over ${monthsWith} active month${monthsWith !== 1 ? 's' : ''}` : ''}</span>
      </div>
    `;

    const earningsOverTimeHtml = `
      <div class="section-card" style="padding:18px 20px; margin-bottom:18px;">
        <div style="display:flex; align-items:center; gap:14px; flex-wrap:wrap;">
          <div style="flex:1; min-width:0;">
            <div class="inv-dash-row-title">Earnings over time</div>
            <div style="font-size:11px; color:var(--text-muted); margin-top:2px;">Monthly totals — ${selectedYear}${_commTimeFocusEmp ? ` · focused on <strong style="color:var(--text);">${esc(_commTimeFocusEmp)}</strong>` : ''}</div>
          </div>
          ${yearSelector}
        </div>
        ${yearSummaryStrip}
        ${empLegendHtml}
        ${chartHtml}
        ${perIndividualHtml}
        ${allYearChips}
      </div>
    `;

    // ── Top clients by commission (mirrors Inventory's "top clients by SKU count") ──
    const clientMap = {};
    rows.forEach(r => {
      const k = r.client_name || '—';
      if (!clientMap[k]) clientMap[k] = 0;
      clientMap[k] += parseFloat(r.commission_amount) || 0;
    });
    const topClients = Object.entries(clientMap).sort((a,b) => b[1] - a[1]).slice(0, 5);
    const maxClient = topClients[0] ? topClients[0][1] : 1;

    const topClientsHtml = topClients.length ? `
      <div class="section-card" style="padding:18px 20px; margin-bottom:18px;">
        <div class="inv-dash-row-title">Top clients by commission</div>
        <div style="margin-top:10px;">
          ${topClients.map(([name, amt]) => {
            const pct = Math.max(4, (amt / Math.max(maxClient, 0.01)) * 100);
            return `
              <div class="inv-topclient-row">
                <div class="inv-topclient-name" title="${esc(name)}">${esc(name)}</div>
                <div class="inv-topclient-bar-wrap"><div class="inv-topclient-bar" style="width:${pct}%;"></div></div>
                <div class="inv-topclient-count">${fmtUsd0(amt)}</div>
              </div>`;
          }).join('')}
        </div>
      </div>
    ` : '';

    // ── Recent commission activity (table-style with header row) ──
    const recent = rows.slice(0, 8);
    const gridCols = 'minmax(110px, 1.4fr) minmax(80px, 0.8fr) minmax(110px, 1.3fr) minmax(110px, 1fr) minmax(70px, 0.6fr) minmax(80px, 0.8fr) minmax(100px, 0.9fr)';
    const colHeaders = ['Product', 'SKU', 'Client', 'Employee', 'Role', 'Amount', 'Date'];
    const headerRowStyle = `display:grid; grid-template-columns:${gridCols}; column-gap:12px; align-items:center; padding:6px 0 8px; border-bottom:1px solid var(--border); margin-bottom:4px;`;
    const headerCellStyle = 'font-size:10px; font-weight:700; color:var(--text-muted); text-transform:uppercase; letter-spacing:0.06em; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;';
    const cellStyle = 'display:flex; align-items:center; min-width:0; overflow:hidden; color:var(--text); font-size:13px;';
    // rolePill is declared above (alongside the per-employee breakdown
    // builder) so both the breakdown and this recent-activity table can
    // reuse the same pill rendering.

    const recentHtml = `
      <div class="section-card" style="padding:18px 20px; min-width:0;">
        <div class="inv-dash-row-title">Recent commission activity</div>
        <div style="${headerRowStyle}">
          ${colHeaders.map(h => `<div style="${headerCellStyle}">${h}</div>`).join('')}
        </div>
        ${recent.map(r => {
          const amt = parseFloat(r.commission_amount) || 0;
          const wbHref = (r.client_name && r.workbook_id)
            ? `#/client/${encodeURIComponent(r.client_name)}/workbook/${r.workbook_id}`
            : '';
          // Product cell becomes a clickable workbook pill when we can route to it.
          const productCell = wbHref
            ? `<span class="inv-wb-pill" onclick="location.hash='${wbHref.substring(1)}'" title="${esc(r.product_name)}" style="max-width:100%; min-width:0;"><span class="inv-wb-pill-text">${esc(r.product_name) || '—'}</span><span class="inv-wb-pill-arrow">→</span></span>`
            : `<span style="overflow:hidden; text-overflow:ellipsis; white-space:nowrap;" title="${esc(r.product_name)}">${esc(r.product_name) || '—'}</span>`;
          return `
            <div class="inv-activity-row" style="display:grid; grid-template-columns:${gridCols}; column-gap:12px; align-items:center;">
              <div style="${cellStyle}">${productCell}</div>
              <div style="${cellStyle}"><span class="inv-sku" style="overflow:hidden; text-overflow:ellipsis; white-space:nowrap;">${esc(r.sku) || '—'}</span></div>
              <div style="${cellStyle}"><span style="overflow:hidden; text-overflow:ellipsis; white-space:nowrap;">${esc(r.client_name) || '—'}</span></div>
              <div style="${cellStyle}"><span style="overflow:hidden; text-overflow:ellipsis; white-space:nowrap;">${esc(r.employee) || '—'}</span></div>
              <div style="${cellStyle}">${rolePill(r.role)}</div>
              <div style="${cellStyle}"><span style="color:var(--success, #16a34a); font-weight:600;">${fmtUsd(amt)}</span>${+r.is_estimate === 1 ? '<span style="margin-left:6px; font-size:10px; color:var(--text-muted); font-style:italic;" title="Estimate based on Our Cost — Client Cost not yet wired">est</span>' : ''}</div>
              <div style="${cellStyle} white-space:nowrap;" title="${esc(r.created_at || '')}">${fmtPretty(r.created_at)}</div>
            </div>`;
        }).join('')}
      </div>
    `;

    host.innerHTML = kpiHtml + empHtml + earningsOverTimeHtml + topClientsHtml + recentHtml;
  }

  // Small helper — human-readable relative time (e.g. "2 days ago", "just now")
  function _relativeTime(ts, now) {
    const diff = now - ts;
    const SEC = 1000, MIN = 60 * SEC, HR = 60 * MIN, DAY = 24 * HR;
    if (diff < 30 * SEC)  return 'just now';
    if (diff < HR)        { const m = Math.floor(diff / MIN); return `${m} min${m !== 1 ? 's' : ''} ago`; }
    if (diff < DAY)       { const h = Math.floor(diff / HR);  return `${h} hour${h !== 1 ? 's' : ''} ago`; }
    if (diff < 7 * DAY)   { const d = Math.floor(diff / DAY); return `${d} day${d !== 1 ? 's' : ''} ago`; }
    if (diff < 30 * DAY)  { const w = Math.floor(diff / (7 * DAY)); return `${w} week${w !== 1 ? 's' : ''} ago`; }
    if (diff < 365 * DAY) { const mo = Math.floor(diff / (30 * DAY)); return `${mo} month${mo !== 1 ? 's' : ''} ago`; }
    const y = Math.floor(diff / (365 * DAY));
    return `${y} year${y !== 1 ? 's' : ''} ago`;
  }

  // Deterministic color per client name → each client gets its own hue chip.
  // Same name always produces the same color across renders.
  function _clientChipStyle(name) {
    if (!name) return '';
    let hash = 0;
    for (let i = 0; i < name.length; i++) {
      hash = ((hash << 5) - hash) + name.charCodeAt(i);
      hash |= 0;
    }
    const hue = Math.abs(hash) % 360;
    return `background:hsl(${hue},72%,93%);color:hsl(${hue},55%,32%);border-color:hsl(${hue},60%,72%);`;
  }

  function renderInventoryTable(rows) {
    const wrap = document.getElementById('inventory-list-content');
    if (!wrap) return;
    if (!rows.length) {
      wrap.innerHTML = `
        <div style="text-align:center; padding:60px 24px; color:var(--text-muted);">
          <div style="font-size:32px; margin-bottom:12px;">📦</div>
          <div style="font-size:16px; font-weight:600; margin-bottom:6px;">No SKUs promoted yet</div>
          <div style="font-size:13px;">Open a workbook and promote RFQ line items to add SKUs here.</div>
        </div>`;
      return;
    }
    const fmtDate = ts => {
      if (!ts) return '—';
      const d = new Date(ts);
      return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: '2-digit' });
    };
    // Pre-compute workbook names so we can sort on them
    const enriched = rows.map(r => {
      let wbName = '';
      let wbHref = '';
      if (r.workbook_id && r.client_name) {
        const items = clientData[r.client_name] || [];
        const wb = items.find(i => i.id == r.workbook_id);
        if (wb) { wbName = wb.product; wbHref = `#/client/${encodeURIComponent(r.client_name)}/workbook/${r.workbook_id}`; }
      }
      return { ...r, _wbName: wbName, _wbHref: wbHref };
    });
    // Group rows by (workbook_id, product_name) so variants always
    // render beneath their parent SKU regardless of which column the
    // operator sorted by. Each group has a parent (variant_name = null)
    // and a list of variants; orphan variants (no parent in inventory)
    // become their own one-item groups so they still appear in the list.
    const _groups = new Map();
    enriched.forEach(r => {
      const key = `${r.workbook_id || ''}|${(r.product_name || '').toLowerCase()}|${r.client_name || ''}`;
      let g = _groups.get(key);
      if (!g) { g = { key, parent: null, variants: [], _key: key }; _groups.set(key, g); }
      const isVariant = !!(r.variant_name && String(r.variant_name).trim());
      if (isVariant) g.variants.push(r);
      else g.parent = r; // last-write wins if duplicates somehow exist
    });
    // Each group's "representative" row drives the sort. Parents win;
    // orphan-variant groups use their first variant.
    const groups = [..._groups.values()].map(g => ({
      ...g,
      rep: g.parent || g.variants[0],
    }));

    // Sort groups (one row per group from the sort's perspective). The
    // variant rows always follow their group's parent in render order —
    // they no longer interleave when sorting by SKU / Added / etc.
    if (_invSort.col) {
      groups.sort((a, b) => {
        const ra = a.rep, rb = b.rep;
        let va, vb;
        if      (_invSort.col === 'product')  { va = (ra.product_name || '').toLowerCase(); vb = (rb.product_name || '').toLowerCase(); }
        else if (_invSort.col === 'sku')      { va = (ra.sku || '').toLowerCase();          vb = (rb.sku || '').toLowerCase(); }
        else if (_invSort.col === 'client')   { va = (ra.client_name || '').toLowerCase();  vb = (rb.client_name || '').toLowerCase(); }
        else if (_invSort.col === 'workbook') { va = (ra._wbName || '').toLowerCase();      vb = (rb._wbName || '').toLowerCase(); }
        else if (_invSort.col === 'added')    { va = ra.promoted_at || '';                  vb = rb.promoted_at || ''; }
        else { return 0; }
        if (va !== vb) return va < vb ? -_invSort.dir : _invSort.dir;
        // Stable secondary by workbook_id so groups with the same sort
        // key still come out in a deterministic order.
        return (a.rep.workbook_id || 0) - (b.rep.workbook_id || 0);
      });
    }
    // Variants within a group always sort alphabetically — they read
    // naturally regardless of the column the group is sorted by.
    groups.forEach(g => {
      g.variants.sort((a, b) =>
        (a.variant_name || '').toLowerCase() < (b.variant_name || '').toLowerCase() ? -1 : 1
      );
    });
    // Sort icon helper
    const sortIco = col => {
      const active = _invSort.col === col;
      const up = active && _invSort.dir === 1;
      const color = active ? 'var(--accent)' : 'var(--text-muted)';
      return `<svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="${color}" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" style="flex-shrink:0;">
        <polyline points="${up ? '18 15 12 9 6 15' : '6 9 12 15 18 9'}"/>
      </svg>`;
    };
    const thStyle = `style="cursor:pointer; user-select:none; white-space:nowrap;"`;
    wrap.innerHTML = `
      <table class="inv-table">
        <thead>
          <tr>
            <th onclick="sortInventory('product')" ${thStyle}><span style="display:inline-flex;align-items:center;gap:4px;">Product ${sortIco('product')}</span></th>
            <th onclick="sortInventory('sku')" ${thStyle}><span style="display:inline-flex;align-items:center;gap:4px;">SKU ${sortIco('sku')}</span></th>
            <th onclick="sortInventory('client')" ${thStyle}><span style="display:inline-flex;align-items:center;gap:4px;">Client ${sortIco('client')}</span></th>
            <th onclick="sortInventory('workbook')" ${thStyle}><span style="display:inline-flex;align-items:center;gap:4px;">Source Workbook ${sortIco('workbook')}</span></th>
            <th onclick="sortInventory('added')" ${thStyle}><span style="display:inline-flex;align-items:center;gap:4px;">Added ${sortIco('added')}</span></th>
            <th></th>
          </tr>
        </thead>
        <tbody>
          ${groups.map(g => {
            // Helper cells — same shape for parent + variant rows so
            // the columns line up; only the Product cell differs.
            const cellsFor = (r) => `
              <td><span class="inv-sku">${r.sku}</span></td>
              <td>${r.client_name ? `<span class="inv-client-chip" style="${_clientChipStyle(r.client_name)}">${r.client_name}</span>` : `<span style="color:var(--text-muted); font-size:12px;">—</span>`}</td>
              <td>${r._wbHref ? `<span class="inv-wb-pill" onclick="event.stopPropagation(); location.hash='${r._wbHref}'" title="${r._wbName}"><span class="inv-wb-pill-text">${r._wbName}</span><span class="inv-wb-pill-arrow">→</span></span>` : `<span style="color:var(--text-muted); font-size:12px;">${r._wbName || '—'}</span>`}</td>
              <td style="color:var(--text-muted); font-size:12px;">${fmtDate(r.promoted_at)}</td>
              <td style="text-align:center;"><button class="inv-remove-btn" onclick="event.stopPropagation(); removeInventorySku(${r.id})" title="Remove from inventory">&times;</button></td>`;

            const variantCount = g.variants.length;
            const isExpanded   = _invExpandedGroups.has(g.key);
            const keyAttr      = g.key.replace(/"/g, '&quot;');
            const keyJs        = g.key.replace(/'/g, "\\'");

            let html = '';

            if (g.parent) {
              // Parent SKU header row. When there are variants, the row
              // becomes clickable to toggle them; chevron + badge make
              // the affordance obvious. When there are NO variants the
              // row reads identically to before (no chevron, no badge,
              // no click handler).
              const chevron = variantCount > 0
                ? `<span class="inv-chevron" style="display:inline-block; width:10px; margin-right:8px; color:var(--text-muted); transition:transform 0.15s; transform:${isExpanded ? 'rotate(90deg)' : 'none'};">▶</span>`
                : `<span style="display:inline-block; width:18px;"></span>`;
              const badge = variantCount > 0
                ? `<span style="display:inline-block; margin-left:10px; padding:2px 8px; background:rgba(110,140,255,0.12); color:#5b6fcc; border-radius:10px; font-size:10px; font-weight:700; letter-spacing:0.03em;">${variantCount} variant${variantCount === 1 ? '' : 's'}</span>`
                : '';
              const clickAttr = variantCount > 0 ? `onclick="toggleInventoryGroup('${keyJs}')"` : '';
              const cursorStyle = variantCount > 0 ? ' cursor:pointer;' : '';
              html += `<tr data-inv-group-header="${keyAttr}" style="${cursorStyle}" ${clickAttr}>
                <td>
                  <div class="inv-product-name" style="display:flex; align-items:center;">
                    ${chevron}<span>${g.parent.product_name || '—'}</span>${badge}
                  </div>
                </td>
                ${cellsFor(g.parent)}
              </tr>`;
            }

            // Variant sub-rows. Hidden by default; revealed by
            // toggleInventoryGroup. When the group has NO parent (orphan
            // variants — promoted before the parent SKU existed, or
            // parent was deleted), the variants render unconditionally
            // so they're still visible.
            const variantRowsHidden = !!g.parent && !isExpanded;
            const variantStyle = variantRowsHidden ? 'display:none; background:rgba(0,0,0,0.015);' : 'background:rgba(0,0,0,0.015);';
            g.variants.forEach(r => {
              html += `<tr data-inv-group="${keyAttr}" style="${variantStyle}">
                <td>
                  <div style="padding-left:36px;">
                    ${g.parent ? '' : `<div style="font-size:11px; color:var(--text-muted); margin-bottom:2px;">${r.product_name || ''}</div>`}
                    <div class="inv-product-name" style="font-weight:500; color:var(--text); display:flex; align-items:center; gap:6px;">
                      <span style="color:var(--text-muted); font-weight:400;">↳</span>
                      <span>${r.variant_name}</span>
                    </div>
                  </div>
                </td>
                ${cellsFor(r)}
              </tr>`;
            });

            return html;
          }).join('')}
        </tbody>
      </table>`;
  }

  function sortInventory(col) {
    if (_invSort.col === col) { _invSort.dir *= -1; } else { _invSort.col = col; _invSort.dir = 1; }
    const q = document.getElementById('inventory-search')?.value || '';
    filterInventory(q);
  }

  // Toggle the variant-list visibility for one Inventory group. Updates
  // the chevron in-place + flips the display on every variant row whose
  // data-inv-group matches the key — no full re-render, so the user's
  // scroll position is preserved when clicking a group deep in the list.
  function toggleInventoryGroup(key) {
    const expand = !_invExpandedGroups.has(key);
    if (expand) _invExpandedGroups.add(key); else _invExpandedGroups.delete(key);
    // querySelectorAll's attribute selector handles quotes / spaces by
    // way of CSS.escape; fall back to a literal string match if
    // CSS.escape is missing (very old browsers).
    const safeKey = (typeof CSS !== 'undefined' && CSS.escape) ? CSS.escape(key) : key.replace(/"/g, '\\"');
    document.querySelectorAll(`tr[data-inv-group="${safeKey}"]`).forEach(r => {
      r.style.display = expand ? '' : 'none';
    });
    const header = document.querySelector(`tr[data-inv-group-header="${safeKey}"]`);
    if (header) {
      const chev = header.querySelector('.inv-chevron');
      if (chev) chev.style.transform = expand ? 'rotate(90deg)' : 'none';
    }
  }

  function filterInventory(query) {
    const q = (query || '').toLowerCase().trim();
    // Respect the client filter first, then text search within it.
    const base = _invFilteredRows();
    if (!q) { renderInventoryTable(base); return; }
    renderInventoryTable(base.filter(r =>
      (r.sku || '').toLowerCase().includes(q) ||
      (r.product_name || '').toLowerCase().includes(q) ||
      (r.variant_name || '').toLowerCase().includes(q) ||
      (r.client_name || '').toLowerCase().includes(q)
    ));
  }

  async function removeInventorySku(id) {
    if (!confirm('Remove this SKU from inventory?')) return;
    const res = await apiCall('remove_sku', { id });
    if (res.success) {
      inventoryData = inventoryData.filter(r => r.id !== id);
      // Re-populate dropdown (a client may have dropped to zero SKUs) and refresh current view
      populateInventoryClientFilter();
      _updateInventoryCountBadge();
      if (_invTab === 'dashboard') {
        renderInventoryDashboard();
      } else {
        const q = document.getElementById('inventory-search')?.value || '';
        filterInventory(q);
      }
    }
  }

  function updatePromoteButton() {
    const btn = document.getElementById('btn-promote-sku');
    if (!btn) return;
    const wbDbId = dbWorkbookMap[`${currentClient}|${currentWorkbookId}`] || currentWorkbookId;
    const wbSkus = inventoryData.filter(r => String(r.workbook_id) === String(wbDbId));
    if (wbSkus.length > 0) {
      const n = wbSkus.length;
      btn.innerHTML = `<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg><span style="color:var(--success);">✓ ${n} SKU${n !== 1 ? 's' : ''} in Inventory</span>`;
      btn.onclick = () => { location.hash = '#/inventory'; };
      btn.title = 'View in Inventory';
      btn.onmouseover = () => { btn.style.borderColor = 'var(--success)'; btn.style.color = 'var(--success)'; };
      btn.onmouseout  = () => { btn.style.borderColor = 'var(--border)'; btn.style.color = 'var(--text-muted)'; };
    } else {
      btn.innerHTML = `<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M12 2l3.09 6.26L22 9.27l-5 4.87L18.18 21 12 17.77 5.82 21 7 14.14 2 9.27l6.91-1.01L12 2z"/></svg>Promote to Permanent SKU`;
      btn.onclick = () => promoteWorkbookToInventory();
      btn.title = 'Promote all RFQ SKUs from this workbook to permanent SKUs';
      btn.onmouseover = () => { btn.style.borderColor = 'var(--accent)'; btn.style.color = 'var(--accent)'; };
      btn.onmouseout  = () => { btn.style.borderColor = 'var(--border)'; btn.style.color = 'var(--text-muted)'; };
    }
  }

  async function promoteWorkbookToInventory() {
    const rfqItems = collectRfqItems();
    const toPromote = [];
    rfqItems.forEach(item => {
      if (!item.sku) return;
      // qty + unit_price_usd are sent so the server can record commission rows
      // for the AM / Salesperson / Operations on this client. unit_price_usd
      // is derived from the RFQ row's RMB price using the live FX rate and
      // the ceil-to-cent helper so the per-line USD matches whatever the
      // operator sees in the workbook UI.
      const qtyNum   = parseFloat(String(item.qty || '').replace(/,/g, '')) || 0;
      const rmbNum   = parseFloat(String(item.priceRmb || '').replace(/,/g, '')) || 0;
      const usdNum   = (rmbNum > 0 && USD_TO_RMB > 0) ? _fxUsdFromRmb(rmbNum) : 0;
      const wbId     = dbWorkbookMap[`${currentClient}|${currentWorkbookId}`] || currentWorkbookId;
      toPromote.push({
        sku: item.sku,
        product_name: item.item || item.sku,
        variant_name: null,
        client_name: currentClient,
        workbook_id: wbId,
        qty: qtyNum,
        unit_price_usd: usdNum,
      });
      // Push every variant under this parent as its own inventory row,
      // using the variant's own (auto- or manually-assigned) SKU. Each
      // variant becomes a permanent inventory item the operator can
      // track stock / orders against independently of the parent.
      // Variants without a SKU are skipped (server requires sku) — the
      // auto-suggester normally prevents that, but if the operator
      // explicitly cleared the field and a parent SKU + variant name
      // couldn't form a suggestion, drop it gracefully.
      (item.variants || []).forEach(v => {
        const vSku = String(v.sku || '').trim();
        if (!vSku) return;
        const vQty   = parseFloat(String(v.qty || '').replace(/,/g, '')) || 0;
        const vRmb   = parseFloat(String(v.priceRmb || '').replace(/,/g, '')) || 0;
        const vUsd   = (vRmb > 0 && USD_TO_RMB > 0) ? _fxUsdFromRmb(vRmb) : 0;
        toPromote.push({
          sku: vSku,
          product_name: item.item || item.sku,
          variant_name: v.variant || null,
          client_name: currentClient,
          workbook_id: wbId,
          qty: vQty,
          unit_price_usd: vUsd,
        });
      });
    });
    if (!toPromote.length) {
      alert('No SKUs found on this workbook\'s RFQ items. Add SKUs to line items first.');
      return;
    }
    // Commission gross — prefer the customer-facing Client Quote
    // "Total Order" line (Sale Per × qty + applied fees). That's the
    // dollar amount the customer pays and what AM / SP / Ops should
    // be commissioned on. Falls back to the cost-side RFQ Grand Total
    // when Sale Per hasn't been typed yet, so commission rows still
    // land for workbooks promoted before pricing is finalized.
    const _ps   = (typeof _lastRfqPriceSummary !== 'undefined' && _lastRfqPriceSummary) || null;
    const _wbDetail = workbookDetail[`${currentClient}|${currentWorkbookId}`] || {};
    const workbookTotalUsd    = (_ps && _ps.grandUsd > 0) ? _ps.grandUsd : 0;
    const clientQuoteTotalUsd = parseFloat(_wbDetail.pricingClientQuoteTotal) || 0;
    const res = await apiCall('promote_to_sku', {
      items: toPromote,
      workbook_total_usd:    workbookTotalUsd,
      client_quote_total_usd: clientQuoteTotalUsd,
      usd_to_rmb: USD_TO_RMB || 0
    });
    if (res.success) {
      await loadInventory();
      // Server may have recorded commission rows for the AM/SP on this
      // client — refresh in-memory data so the Commissions dashboard is
      // fresh next time it's opened.
      loadCommissions();
      updatePromoteButton();
    }
  }

  (async function init() {
    // Try loading from LocalStorage immediately for fast render
    loadFromLocalStorage();
    loadShipments();
    loadOrders();
    loadInventory();
    loadCommissions();
    rebuildSidebar();
    rebuildShipmentsNav();
    rebuildOrdersNav();
    rebuildSamplesNav();
    rebuildRfqNav();
    rebuildReviewNav();
    restoreNavSectionStates();
    // Wrap in try/catch so a crash inside fillWorkbook never prevents loadFromDatabase() from running
    try { router(); } catch(e) { console.error('[MS Router] init render error:', e); }

    // Check for portal change requests on load, then every 60 s
    checkPortalChanges();
    setInterval(checkPortalChanges,    60_000);
    setInterval(pollForRemoteChanges,  60_000); // picks up partner changes across all data

    // Then try loading from database (will override if successful)
    // If the user typed something before the DB responded, capture it so we don't lose it
    const preDbClient = currentClient;
    const preDbWbId = currentWorkbookId;
    const dbLoaded = await loadFromDatabase();
    if (dbLoaded === true) {
      console.log('Data loaded from database');
      // Only preserve pre-DB form state if the user actually made edits before DB responded
      if (_isDirty && preDbClient && preDbWbId) {
        const preKey = `${preDbClient}|${preDbWbId}`;
        workbookDetail[preKey] = collectWorkbookDetail();
      }
      rebuildRfqNav();    // workbookDetail (incl. sentToRfq flags) now populated from DB
      rebuildReviewNav(); // …and the Ready-for-Review badge from sentForReview flags
      router(); // Re-render with DB data (or user's edits if they were faster)
    } else if (dbLoaded === 'empty') {
      // DB reachable and confirmed empty — safe to seed, but only once per device.
      // The ms_db_seeded flag gets set inside loadFromDatabase the first time
      // workbooks are successfully loaded from the DB, so we only seed on a truly
      // fresh device/browser.
      const alreadySeeded = (() => { try { return localStorage.getItem('ms_db_seeded') === '1'; } catch(e) { return false; } })();
      if (!alreadySeeded) {
        console.log('DB empty on fresh device — seeding with local sample data');
        seedDatabase();
      } else {
        console.log('DB reports empty but device has seeded before — skipping seed (safety guard)');
      }
    } else {
      // dbLoaded === false (API failure) — keep using local data; NEVER seed here.
      console.log('API unreachable, using local/fallback data (skipping seed)');
    }

    // Sync orders and shipments from DB (multi-user shared state)
    const [ordersFromDB, shipmentsFromDB] = await Promise.all([
      syncOrdersFromDB(),
      syncShipmentsFromDB(),
    ]);
    if (ordersFromDB || shipmentsFromDB) {
      rebuildOrdersNav();
      rebuildShipmentsNav();
      // If the current view is an order or shipment, re-render it with fresh data
      const h = location.hash;
      if (h.startsWith('#/order') || h.startsWith('#/shipment') || h.startsWith('#/orders') || h.startsWith('#/shipments')) {
        router();
      }
    }

    // Allow autosave now — just after _filling clears (200ms in fillWorkbook + small buffer)
    setTimeout(() => { _appReady = true; }, 210);

    // Kick off background notification polling. Runs on every page so
    // a watcher gets the Chrome notification even if they're on the
    // home view, not the specific workbook.
    if (typeof startNotificationsPolling === 'function') startNotificationsPolling();

    // Restore saved username into sidebar input
  })();

  // In-memory guard so multiple concurrent callers can't both enter this function.
  let _seedingInFlight = false;
  async function seedDatabase() {
    // Guard 1: prevent concurrent invocations
    if (_seedingInFlight) {
      console.warn('[seedDatabase] already in flight — skipping duplicate call');
      return;
    }
    // Guard 2: persistent flag — once seeded on this device, never again
    try {
      if (localStorage.getItem('ms_db_seeded') === '1') {
        console.warn('[seedDatabase] ms_db_seeded flag set — aborting to prevent duplicates');
        return;
      }
    } catch(e) {}

    _seedingInFlight = true;
    try {
      // Guard 3: re-check DB before inserting. Require success AND empty — if the
      // call fails we bail (transient API errors used to trigger re-seeds, which
      // was the root cause of cross-device workbook duplication).
      const wbResult = await apiCall('get_workbooks');
      if (!wbResult.success) {
        console.warn('[seedDatabase] get_workbooks failed — aborting seed to avoid dupes');
        return;
      }
      if (wbResult.data && wbResult.data.length > 0) {
        // DB already has workbooks — mark seeded and bail
        try { localStorage.setItem('ms_db_seeded', '1'); } catch(e) {}
        return;
      }

      // Get existing clients from DB to build the map
      const clientResult = await apiCall('get_clients');
      if (clientResult.success && clientResult.data) {
        clientResult.data.forEach(c => { dbClientMap[c.name] = c.id; });
      }

      // Seed any missing clients
      for (const name of Object.keys(clientData).sort()) {
        if (!dbClientMap[name]) {
          const r = await apiCall('add_client', { name });
          if (r.success) dbClientMap[name] = r.id;
        }
      }

      // Seed workbooks
      for (const [clientName, items] of Object.entries(clientData)) {
        const clientId = dbClientMap[clientName];
        if (!clientId) continue;
        for (const item of items) {
          const detail = workbookDetail[`${clientName}|${item.id}`] || {};
          const r = await apiCall('add_workbook', {
            client_id: clientId,
            product_name: item.product,
            description: item.description,
            detail: detail
          });
          if (r.success) {
            // Update flow
            const step = flowToStep(item.flow);
            await apiCall('update_flow', { id: r.id, flow_step: step });
            dbWorkbookMap[`${clientName}|${r.id}`] = r.id;
          }
        }
      }
      // Lock out future seed attempts on this device
      try { localStorage.setItem('ms_db_seeded', '1'); } catch(e) {}
      saveToLocalStorage();
      console.log('Database seeded with sample data');
    } finally {
      _seedingInFlight = false;
    }
  }

  /* ══════════════════════════════════════════════════════════════════════
     SHIPMENTS MODULE
  ══════════════════════════════════════════════════════════════════════ */

  // shipmentData, _nextShipmentId, _currentShipmentId, _wbPickerSelected, CONTAINER_SPECS declared above init()

  // ── Persistence ──────────────────────────────────────────────────────
  function saveShipments() {
    try { localStorage.setItem('ms_shipmentData', JSON.stringify(shipmentData)); } catch(e) {}
    try { localStorage.setItem('ms_nextShipmentId', String(_nextShipmentId)); } catch(e) {}
    if (Object.keys(shipmentData).length > 0 || _nextShipmentId > 1) {
      const payload = JSON.stringify({ data: shipmentData, nextId: _nextShipmentId });
      _lastShipmentsJson = payload; // prevent our own save from triggering a poll re-render
      apiCall('save_app_state', { key: 'ms_shipments', value: payload }).catch(() => {});
    }
  }

  function loadShipments() {
    try {
      const sd = localStorage.getItem('ms_shipmentData');
      const ni = localStorage.getItem('ms_nextShipmentId');
      if (sd) Object.assign(shipmentData, JSON.parse(sd));
      if (ni) _nextShipmentId = parseInt(ni) || 1;
    } catch(e) {}
    // Ensure the shipments nav section is never persisted as collapsed
    try {
      const nc = JSON.parse(localStorage.getItem('ms_nav_collapsed') || '{}');
      if (nc['nav-section-containers']) {
        delete nc['nav-section-containers'];
        localStorage.setItem('ms_nav_collapsed', JSON.stringify(nc));
      }
    } catch(e) {}
  }

  // ── Calculations ─────────────────────────────────────────────────────
  // Shared per-workbook stat helper used by every order / shipment
  // picker + card. Centralizes the source-of-truth selection so all
  // surfaces show the same numbers as the Pricing / Shipping tabs.
  //
  // Returns { units, weightKg, cost, price, cbm }:
  //   - units:    palletTotalCartons (Total Units to Ship) when set,
  //               else the selected pricing tier qty.
  //   - weightKg: cached pricingShipmentWeightKg (from
  //               renderContainerViz).
  //   - cost:     cached pricingGrandTotalCost (the Pricing tab's
  //               "Grand Total Cost (USD)" bar = product + shipping,
  //               no fees, no margin). Falls back to pricingLandedTotal
  //               for workbooks not yet re-rendered with the new cache.
  //   - price:    cached pricingClientQuoteTotal (the Client Quote
  //               "Total Order" line = Sale Per × qty + applied fees).
  //   - cbm:      cached pricingShipmentCbm. When that's 0 (no carton
  //               specs to drive the freight calc), fall back to
  //               product L × W × H × units / 1,000,000 so the CBM
  //               surfaces regardless of carton-spec completion.
  function _wbStatsForPicker(detail) {
    const d = detail || {};
    const tiers     = Array.isArray(d.tiers) ? d.tiers : [];
    const selTier   = tiers.find(t => t.id == d.selectedTierIdx) || tiers[0];
    const palletTot = parseInt(String(d.palletTotalCartons || '').replace(/,/g, ''), 10);
    const units = (!isNaN(palletTot) && palletTot > 0)
      ? palletTot
      : (selTier ? (parseInt(String(selTier.qty || '').replace(/,/g, ''), 10) || 0) : 0);
    let weightKg = parseFloat(d.pricingShipmentWeightKg) || 0;
    if (weightKg === 0) {
      // Fallback: the cache is only written from renderPalletViz (which
      // needs carton dims to produce pallets) or from calcFreight's
      // weight-driven branch (which needs the workbook to be opened to
      // run). Compute the honest value here from the same override
      // fields used by _shipUnit, so the Orders page can render weight
      // even when neither writer has fired yet for this workbook.
      if (d.weightOnlyOverride) {
        const wq = parseInt(String(d.weightOnlyCaseQty || '').replace(/,/g, ''), 10) || 0;
        const wk = parseFloat(d.weightOnlyKg) || 0;
        if (wq > 0 && wk > 0) weightKg = wq * wk;
      } else if (d.caseOnlyOverride) {
        const cn = parseInt(String(d.caseOnlyCasesOrder || '').replace(/,/g, ''), 10) || 0;
        const ck = parseFloat(d.caseOnlyWeightKg) || 0;
        if (cn > 0 && ck > 0) weightKg = cn * ck;
      } else {
        // Default flow — outer-carton weight × ceil(units / units-per-outer).
        const ow = parseFloat(d.cartonOuterWeight) || 0;
        const ic = parseInt(d.cartonInnerCount) || 0;
        const oc = parseInt(d.cartonOuterCount) || 0;
        const upo = ic * oc;
        if (ow > 0 && upo > 0 && units > 0) {
          weightKg = ow * Math.ceil(units / upo);
        }
      }
    }
    // Prefer the new Grand Total Cost bar value; fall back to the
    // older landed-total cache so existing workbooks aren't stuck on 0
    // until they're re-opened on the Pricing tab.
    const cost = parseFloat(d.pricingGrandTotalCost) || parseFloat(d.pricingLandedTotal) || 0;
    const price = parseFloat(d.pricingClientQuoteTotal) || 0;
    let cbm = parseFloat(d.pricingShipmentCbm) || 0;
    if (cbm === 0 && units > 0) {
      // Fallback hierarchy depends on which Override is active. The
      // product-dim fallback is meaningless when the operator chose
      // Case-Only (ship unit = case, not product) or Weight-Only
      // (no dims at all). Without this guard, Candy Pan-style workbooks
      // — case-only with leftover product dims from a prior life — show
      // a fake CBM derived from product L×W×H × units that bears no
      // relation to how the goods actually ship.
      if (d.weightOnlyOverride) {
        // No dims, period. CBM is genuinely unknown.
        cbm = 0;
      } else if (d.caseOnlyOverride) {
        // Use case dims × case count if supplied; otherwise unknown.
        const cl = parseFloat(d.caseOnlyLCm) || 0;
        const cw = parseFloat(d.caseOnlyWCm) || 0;
        const ch = parseFloat(d.caseOnlyHCm) || 0;
        const cn = parseInt(String(d.caseOnlyCasesOrder || '').replace(/,/g, ''), 10) || 0;
        if (cl > 0 && cw > 0 && ch > 0 && cn > 0) {
          cbm = (cl * cw * ch * cn) / 1_000_000;
        }
      } else {
        // Default mode — product dims × units, the historical fallback.
        const pl = parseFloat(d.dimCmL) || 0;
        const pw = parseFloat(d.dimCmW) || 0;
        const ph = parseFloat(d.dimCmH) || 0;
        if (pl > 0 && pw > 0 && ph > 0) {
          cbm = (pl * pw * ph * units) / 1_000_000;
        }
      }
    }
    // Total lead = max(production lead across rfqItems) + max
    // shipping lead from the selected freight mode's input (parses
    // "20-30" as 30; falls back to 0 when the lead field is blank).
    // Mirrors the Client Quote header's "Total Lead" computation so
    // downstream surfaces show the same number the operator sees on
    // the workbook itself.
    const rfqItems = Array.isArray(d.rfqItems) ? d.rfqItems : [];
    let prodLead = 0;
    rfqItems.forEach(it => {
      const n = parseInt(String(it.leadTime || '').match(/\d+/g)?.pop() || '', 10);
      if (!isNaN(n) && n > prodLead) prodLead = n;
    });
    const mode = d.freightMode || 'slow';
    const shipLeadKey = ({slow:'shipLeadSlow', fast:'shipLeadFast', airupp:'shipLeadAirupp', directair:'shipLeadDirectair'})[mode] || 'shipLeadSlow';
    const shipLeadStr = String(d[shipLeadKey] || '').trim();
    let shipLead = 0;
    if (shipLeadStr) {
      const m = shipLeadStr.match(/^(\d+)\s*[-–—]\s*(\d+)$/);
      if (m) shipLead = Math.max(parseInt(m[1], 10), parseInt(m[2], 10));
      else { const n = parseInt(shipLeadStr, 10); if (!isNaN(n)) shipLead = n; }
    }
    const leadDays = (prodLead || 0) + (shipLead || 0);
    // ── Product cost (USD) — authoritative path ─────────────────────
    // Compute directly from detail_json instead of trusting the
    // pricingProductCostUsd cache (which is brittle: it only exists
    // for workbooks opened-and-saved since the cache schema landed).
    //
    // Honest formula: effectiveQty × selectedTier.price / FX. Mirrors
    // renderPricingTab's productTotalRmb computation (line ~19562)
    // without needing the DOM.
    //
    // Variant note: when an RFQ row has variants with DIFFERENT
    // per-unit RMB prices, renderPricingTab uses a qty-weighted
    // average across variants instead of the parent's flat price.
    // For the dashboard rollup we use the simple tier × qty approach
    // — close enough for the Orders summary, and exactly right for
    // the common case where variants share one tier price.
    const _ms_FX = 7.2; // matches USD_TO_RMB
    let productCost = parseFloat(d.pricingProductCostUsd) || 0;
    if (productCost === 0) {
      const tierPrice = selTier ? (parseFloat(String(selTier.price || '').replace(/,/g, '')) || 0) : 0;
      if (units > 0 && tierPrice > 0) {
        productCost = (units * tierPrice) / _ms_FX;
      }
    }
    // ── Shipping (USD) — derive from cachedTotal − product ──────────
    // The cached pricingGrandTotalCost is reliable (it's _msCeil2 of
    // product + shipping at save time and the user has confirmed it
    // matches the Pricing tab). Subtracting the computed product
    // gives shipping that's GUARANTEED to tie to Total. This beats
    // the old weight×rate fallback, which assumed a rate that didn't
    // always match what calcFreight actually used.
    //
    // Cache-first path remains: if pricingShippingCostUsd is present,
    // trust it (it was written from the same render that produced
    // the total, so they're consistent by construction).
    let shippingUsd = parseFloat(d.pricingShippingCostUsd) || 0;
    if (shippingUsd === 0) {
      const cachedTotal = parseFloat(d.pricingGrandTotalCost) || 0;
      if (cachedTotal > 0 && productCost > 0 && cachedTotal > productCost) {
        shippingUsd = cachedTotal - productCost;
      } else {
        // Last-resort fallback for workbooks with no Pricing-tab cache
        // at all (brand new, never priced): honor explicit override,
        // else weight × rate.
        const overrideOn  = !!d.freightCostOverrideOn;
        const overrideStr = String(d.freightCostOverrideUsd || '').replace(/,/g, '').trim();
        const overrideVal = parseFloat(overrideStr);
        if (overrideOn && isFinite(overrideVal) && overrideVal >= 0) {
          shippingUsd = overrideVal;
        } else {
          const fr = (d.freightRates && typeof d.freightRates === 'object') ? d.freightRates : {};
          const rateMap = {
            slow:      parseFloat(fr.slow)      || 12,
            fast:      parseFloat(fr.fast)      || 14,
            airupp:    parseFloat(fr.airupp)    || 44,
            directair: parseFloat(fr.directair) || 65,
          };
          const rateRmb = rateMap[mode] || 0;
          if (weightKg > 0 && rateRmb > 0) {
            shippingUsd = (weightKg * rateRmb) / _ms_FX;
          }
        }
      }
    }
    return { units, weightKg, cost, price, cbm, leadDays, shippingUsd, productCost };
  }

  function calcWorkbookShipStats(detail, qty) {
    qty = parseInt(qty) || 0;
    const outerLCm     = parseFloat(detail.cartonOuterLCm)    || 0;
    const outerWCm     = parseFloat(detail.cartonOuterWCm)    || 0;
    const outerHCm     = parseFloat(detail.cartonOuterHCm)    || 0;
    const outerWeightKg = parseFloat(detail.cartonOuterWeight) || 0;
    const innerCount   = parseInt(detail.cartonInnerCount)    || 0;
    const outerCount   = parseInt(detail.cartonOuterCount)    || 0;
    const unitsPerOuter = innerCount * outerCount;

    let totalCartons = 0;
    if (unitsPerOuter > 0 && qty > 0) totalCartons = Math.ceil(qty / unitsPerOuter);

    let cbmPerCarton = 0;
    if (outerLCm > 0 && outerWCm > 0 && outerHCm > 0)
      cbmPerCarton = (outerLCm * outerWCm * outerHCm) / 1000000;
    const totalCbm = parseFloat((cbmPerCarton * totalCartons).toFixed(2));
    const totalWeightKg = parseFloat((outerWeightKg * totalCartons).toFixed(1));

    // Pallet stacking: standard 40×48" pallet = 121.9 × 101.6 cm, max height 180 cm
    const PL = 121.9, PW = 101.6, PH = 180;
    let palletsNeeded = 0;
    if (outerLCm > 0 && outerWCm > 0 && outerHCm > 0 && totalCartons > 0) {
      const perRow    = Math.max(1, Math.floor(PL / outerLCm));
      const perCol    = Math.max(1, Math.floor(PW / outerWCm));
      const perLayer  = perRow * perCol;
      const maxLayers = Math.max(1, Math.floor(PH / outerHCm));
      const perPallet = Math.max(1, perLayer * maxLayers);
      palletsNeeded   = Math.ceil(totalCartons / perPallet);
    } else if (totalCartons > 0) {
      // Fallback: assume 20 cartons/pallet
      palletsNeeded = Math.ceil(totalCartons / 20);
    }

    return { qty, totalCartons, totalCbm, totalWeightKg, palletsNeeded, unitsPerOuter };
  }

  function orderShipStats(orderId) {
    const order = orderData[orderId];
    if (!order) return { qty: 0, totalCartons: 0, totalCbm: 0, totalWeightKg: 0, palletsNeeded: 0, totalRmb: 0, totalUsd: 0, wbCount: 0 };
    let qty = 0, totalCartons = 0, totalCbm = 0, totalWeightKg = 0, palletsNeeded = 0, totalRmb = 0, totalUsd = 0;
    const exchange = 7.2;
    (order.entries || []).forEach(wbEntry => {
      const key    = `${wbEntry.clientName}|${wbEntry.workbookId}`;
      const detail = workbookDetail[key];
      if (!detail) return;

      // Units / weight / CBM: source-of-truth via the shared helper
      // so the shipment view shows the SAME numbers as the Add to
      // Shipment modal + the Orders list card. Previously this
      // function pulled qty from the selected pricing tier (often a
      // production tier larger than what's actually being shipped),
      // which inflated cartons/CBM/weight by 3-5× when the ship qty
      // (palletTotalCartons) differed from the tier qty.
      const w = _wbStatsForPicker(detail);
      qty           += w.units;
      totalWeightKg += w.weightKg;
      totalCbm      += w.cbm;

      // Cartons + pallets are derived from carton specs (no
      // dedicated cache). Use the helper's qty so the carton count
      // matches the units shown above. When carton specs are missing
      // both stay 0 and the row displays "—" for those cells.
      const s = calcWorkbookShipStats(detail, w.units);
      totalCartons  += s.totalCartons;
      palletsNeeded += s.palletsNeeded;

      // USD / RMB monetary totals — keep the legacy tier × qty math
      // (this is what the Order list + shipment chip have always
      // shown). The customer-facing Client Quote total and our Grand
      // Total Cost are surfaced via the picker / order-card stat
      // strip instead.
      const tiers = Array.isArray(detail.tiers) ? detail.tiers : [];
      const tier  = tiers.find(t => t.id == detail.selectedTierIdx) || tiers[0];
      const tQty  = tier ? (parseFloat(tier.qty)   || 0) : 0;
      const price = tier ? (parseFloat(tier.price) || 0) : 0;
      totalRmb += price * tQty;
      totalUsd += (price / exchange) * tQty;
    });
    return {
      wbCount:      (order.entries || []).length,
      qty:          qty,
      totalCartons: totalCartons,
      totalCbm:     parseFloat(totalCbm.toFixed(2)),
      totalWeightKg: parseFloat(totalWeightKg.toFixed(1)),
      palletsNeeded: Math.ceil(palletsNeeded),
      totalRmb:     Math.round(totalRmb * 100) / 100,
      totalUsd:     Math.round(totalUsd * 100) / 100,
    };
  }

  function shipmentTotals(shipment) {
    let totalCbm = 0, totalKg = 0, totalPallets = 0;
    (shipment.entries || []).forEach(entry => {
      if (entry.orderId) {
        const s = orderShipStats(entry.orderId);
        totalCbm     += s.totalCbm;
        totalKg      += s.totalWeightKg;
        totalPallets += s.palletsNeeded;
      } else {
        // Legacy workbook entry
        const key    = `${entry.clientName}|${entry.workbookId}`;
        const detail = workbookDetail[key];
        if (!detail) return;
        const s = calcWorkbookShipStats(detail, entry.qty);
        totalCbm     += s.totalCbm;
        totalKg      += s.totalWeightKg;
        totalPallets += s.palletsNeeded;
      }
    });
    return {
      cbm:     parseFloat(totalCbm.toFixed(2)),
      kg:      parseFloat(totalKg.toFixed(1)),
      pallets: totalPallets,
    };
  }

  // ── Nav ──────────────────────────────────────────────────────────────
  function rebuildShipmentsNav() {
    const ids = Object.keys(shipmentData);
    // Actionable = any linked order has a change request
    const shipActionable = ids.filter(id => {
      const entries = shipmentData[id].entries || [];
      return entries.some(e => e.orderId && orderData[e.orderId]?.changeRequested);
    }).length;
    _applyNavBadge(document.getElementById('badge-shipments'), shipActionable, ids.length);
    // Shipments list (if a sub-nav list element exists — may not, since Shipments is now a flat link)
    const list = document.getElementById('shipments-nav-list');
    if (!list) return;
    list.innerHTML = ids.map(id => {
      const s = shipmentData[id];
      const statusDot = `<span class="nav-shipment-dot ${s.status}"></span>`;
      return `<div class="nav-shipment-item" id="nav-ship-${id}" onclick="location.hash='#/shipment/${id}'">
        ${statusDot}<span style="flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${s.name}</span>
      </div>`;
    }).join('');
  }

  function rebuildSamplesNav() {
    const all = collectAllSamples();
    // Actionable = any order linked to the same workbook has a change request
    const sampleActionable = all.filter(s => {
      return Object.values(orderData).some(o =>
        o.changeRequested &&
        (o.entries || []).some(e =>
          e.clientName === s.clientName && String(e.workbookId) === String(s.workbookId)
        )
      );
    }).length;
    _applyNavBadge(document.getElementById('badge-samples'), sampleActionable, all.length);
  }

  // ── Create ────────────────────────────────────────────────────────────
  function openNewShipmentModal() {
    document.getElementById('new-ship-name').value = '';
    document.getElementById('new-ship-container').value = '40hc';
    document.getElementById('modal-new-shipment').classList.add('open');
    setTimeout(() => document.getElementById('new-ship-name').focus(), 80);
  }
  function closeNewShipmentModal() {
    document.getElementById('modal-new-shipment').classList.remove('open');
  }

  function createShipment(e) {
    e.preventDefault();
    const name      = document.getElementById('new-ship-name').value.trim();
    const container = document.getElementById('new-ship-container').value;
    if (!name) return;
    const id = _nextShipmentId++;
    shipmentData[id] = {
      id, name,
      containerType: container,
      status: 'planning',
      dateCreated: new Date().toLocaleDateString('en-GB', {day:'2-digit', month:'short', year:'2-digit'}),
      etd: '', eta: '',
      entries: [],
    };
    saveShipments();
    rebuildShipmentsNav();
    closeNewShipmentModal();
    location.hash = `#/shipment/${id}`;
  }

  // ── List view ────────────────────────────────────────────────────────
  function renderShipmentsList() {
    document.getElementById('header-title').textContent = 'Shipments';
    document.querySelectorAll('.sidebar-nav .nav-item').forEach(a => a.classList.remove('active'));
    document.querySelectorAll('.nav-flat-link').forEach(a => a.classList.remove('active'));
    const shipNav = document.getElementById('nav-shipments-link');
    if (shipNav) shipNav.classList.add('active');
    showView('view-shipments');
    renderShipmentsContent();
  }

  function filterShipments(status, btn) {
    _shipFilter = status;
    document.querySelectorAll('.ship-filter-btn').forEach(b => b.classList.remove('active'));
    if (btn) btn.classList.add('active');
    renderShipmentsContent();
  }

  // Completed = delivered for 30+ days. Missing deliveredOn = treated as recent.
  function _isArchiveCompleted(s) {
    if (!s || s.status !== 'delivered' || !s.deliveredOn) return false;
    const delivered = new Date(s.deliveredOn);
    if (isNaN(delivered.getTime())) return false;
    const days = (Date.now() - delivered.getTime()) / 86400000;
    return days >= 30;
  }

  function renderShipmentsContent() {
    const el = document.getElementById('shipment-list-content');
    if (!el) return;

    const allIds = Object.keys(shipmentData);
    if (allIds.length === 0) {
      el.innerHTML = `<div class="shipment-list-empty">
        <div class="shipment-list-empty-icon">🚢</div>
        <div class="shipment-list-empty-title">No shipments yet</div>
        <div class="shipment-list-empty-sub">Create a shipment to consolidate workbooks into a container.</div>
      </div>`;
      return;
    }

    // Split completed (delivered 30+ days) from the main list
    const completedIds = allIds.filter(id => _isArchiveCompleted(shipmentData[id]));
    const ids          = allIds.filter(id => !_isArchiveCompleted(shipmentData[id]));

    const STATUS_ORDER = ['planning', 'booked', 'in_transit', 'delivered'];
    const filterLabels = { all: 'All', planning: 'Planning', booked: 'Booked', in_transit: 'In Transit', delivered: 'Delivered' };

    // Counts per status for badges on filter buttons (main list only — completed is separate)
    const counts = { all: ids.length };
    ids.forEach(id => {
      const st = shipmentData[id].status;
      counts[st] = (counts[st] || 0) + 1;
    });

    const filterBar = `<div class="ship-filter-bar">
      ${['all','planning','booked','in_transit','delivered'].map(s =>
        `<button class="ship-filter-btn${_shipFilter === s ? ' active' : ''}" onclick="filterShipments('${s}', this)">
          ${filterLabels[s]}${counts[s] ? ` <span style="opacity:0.7">(${counts[s]})</span>` : ''}
        </button>`
      ).join('')}
    </div>`;

    function buildCard(id) {
      const s      = shipmentData[id];
      const spec   = CONTAINER_SPECS[s.containerType] || CONTAINER_SPECS['40hc'];
      const tot    = shipmentTotals(s);
      const cbmPct    = spec.cbm       > 0 ? Math.round((tot.cbm     / spec.cbm)       * 100) : 0;
      const kgPct     = spec.maxKg     > 0 ? Math.round((tot.kg      / spec.maxKg)     * 100) : 0;
      const palletPct = spec.maxPallets > 0 ? Math.round((tot.pallets / spec.maxPallets) * 100) : 0;
      const isDelivered = s.status === 'delivered';
      const eta = isDelivered
        ? (s.deliveredOn ? `<strong style="color:#34d399">${s.deliveredOn}</strong>` : '—')
        : (s.eta ? `<strong>${s.eta}</strong>` : '—');
      const etaLabel = isDelivered ? 'Delivered' : 'ETA';
      const entries = s.entries || [];
      const orderEntries = entries.filter(e => e.orderId);
      const shipHasChangeRequest = orderEntries.some(e => orderData[e.orderId]?.changeRequested);
      const wbPills = orderEntries.length === 0
        ? `<span style="font-size:12px;color:var(--text-muted);font-style:italic;">No orders added</span>`
        : orderEntries.map(e => {
            const order = orderData[e.orderId];
            if (!order) return '';
            const href = `#/order/${e.orderId}`;
            const crTag = order.changeRequested
              ? `<span style="background:#fff7ed;border:1px solid #fed7aa;color:#E8751A;font-size:9px;font-weight:700;text-transform:uppercase;padding:1px 5px;border-radius:10px;margin-left:4px;vertical-align:middle;">⚑ Hold</span>`
              : '';
            return `<span class="sc-wb-pill" onclick="event.stopPropagation(); location.hash='${href}'">${order.clientName} – ${order.name}${crTag}<span class="sc-wb-pill-arrow">→</span></span>`;
          }).join('');
      const wbCount = orderEntries.length;
      const overStyle = 'color:#ef4444 !important; font-weight:700;';
      const cbmOver = cbmPct > 100; const kgOver = kgPct > 100; const palOver = palletPct > 100;

      return `<div class="shipment-card${shipHasChangeRequest ? ' has-change-request' : ''}" onclick="location.hash='#/shipment/${id}'">
        <div class="sc-left">
          <span class="sc-title">${s.name}</span>
          <span class="sc-eta">${etaLabel} ${eta}</span>
        </div>
        <div class="sc-wb-list">
          <div class="sc-wb-count">${wbCount} order${wbCount !== 1 ? 's' : ''}</div>
          ${wbPills}
        </div>
        <div class="sc-right-wrap">
          <div class="sc-stats-row">
            <span${cbmOver ? ` style="${overStyle}"` : ''}><span class="sc-stat-inline"${cbmOver ? ` style="${overStyle}"` : ''}>${tot.cbm}/${spec.cbm}</span> CBM (${cbmPct}%)</span>
            <span class="sc-divider">|</span>
            <span${kgOver ? ` style="${overStyle}"` : ''}><span class="sc-stat-inline"${kgOver ? ` style="${overStyle}"` : ''}>${tot.kg.toLocaleString('en-US')}</span> kg (${kgPct}%)</span>
            <span class="sc-divider">|</span>
            <span${palOver ? ` style="${overStyle}"` : ''}><span class="sc-stat-inline"${palOver ? ` style="${overStyle}"` : ''}>${tot.pallets}</span> pallet${tot.pallets !== 1 ? 's' : ''} (${palletPct}%)</span>
          </div>
          <div class="sc-right">
            <span class="ship-status-badge ship-status-${s.status}">${s.status.replace('_',' ')}</span>
            <span class="shipment-container-tag">${spec.label}</span>
          </div>
        </div>
      </div>`;
    }

    // Split into active and delivered
    const filtered = ids.filter(id => _shipFilter === 'all' || shipmentData[id].status === _shipFilter);
    const active    = filtered.filter(id => shipmentData[id].status !== 'delivered');
    const delivered = filtered.filter(id => shipmentData[id].status === 'delivered');

    // Sort active by status order
    active.sort((a, b) => STATUS_ORDER.indexOf(shipmentData[a].status) - STATUS_ORDER.indexOf(shipmentData[b].status));

    let html = filterBar;

    if (active.length > 0) {
      html += `<div class="shipment-cards">${active.map(buildCard).join('')}</div>`;
    }

    if (delivered.length > 0) {
      html += `<div class="sc-section-label" style="margin-top:${active.length > 0 ? '20px' : '0'}">Delivered</div>
        <div class="shipment-cards" style="opacity:0.7">${delivered.map(buildCard).join('')}</div>`;
    }

    if (active.length === 0 && delivered.length === 0) {
      html += `<div style="padding:30px 0; text-align:center; color:var(--text-muted); font-size:13px;">No shipments match this filter.</div>`;
    }

    // ── Completed (archived) — delivered 30+ days ago, grouped by month, collapsed by default ──
    // Always rendered, even when empty, so users can see the section exists.
    let completedBody;
    if (completedIds.length === 0) {
      completedBody = `<div style="padding:20px 0;text-align:center;color:var(--text-muted);font-size:13px;font-style:italic;">
        No shipments archived yet. Delivered shipments move here 30 days after their delivery date.
      </div>`;
    } else {
      // Group by "YYYY-MM" of deliveredOn
      const byMonth = {};
      completedIds.forEach(id => {
        const s = shipmentData[id];
        const d = new Date(s.deliveredOn);
        const key = `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;
        (byMonth[key] = byMonth[key] || []).push(id);
      });
      // Sort months newest → oldest
      const monthKeys = Object.keys(byMonth).sort().reverse();
      const MONTH_NAMES = ['January','February','March','April','May','June','July','August','September','October','November','December'];
      completedBody = monthKeys.map(k => {
        const [y, m] = k.split('-');
        const label = `${MONTH_NAMES[parseInt(m,10)-1]} ${y}`;
        // Sort shipments within a month newest → oldest by deliveredOn
        const sortedIds = byMonth[k].slice().sort((a, b) =>
          new Date(shipmentData[b].deliveredOn) - new Date(shipmentData[a].deliveredOn)
        );
        return `<div class="completed-month-label">${label} <span style="color:var(--text-muted);font-weight:500;">(${sortedIds.length})</span></div>
          <div class="shipment-cards" style="opacity:0.75;margin-bottom:16px;">${sortedIds.map(buildCard).join('')}</div>`;
      }).join('');
    }

    html += `<div class="section-card collapsed" style="margin-top:24px;">
      <div class="section-header section-header-collapsible" onclick="toggleSection(this.closest('.section-card'))">
        <span class="section-title">Archived <span style="color:var(--text-muted);font-weight:500;margin-left:6px;">(${completedIds.length})</span></span>
        <span class="section-chevron" style="margin-left:auto;">›</span>
      </div>
      <div class="section-body" style="padding:16px 20px;">
        ${completedBody}
      </div>
    </div>`;

    el.innerHTML = html;
  }

  // ── Detail view ──────────────────────────────────────────────────────
  function renderShipmentDetail(id) {
    _currentShipmentId = parseInt(id);
    const s = shipmentData[_currentShipmentId];
    if (!s) { location.hash = '#/shipments'; return; }

    document.getElementById('header-title').textContent = s.name;
    document.querySelectorAll('.sidebar-nav .nav-item').forEach(a => a.classList.remove('active'));
    document.querySelectorAll('.nav-flat-link').forEach(a => a.classList.remove('active'));
    const shipNav = document.getElementById('nav-shipments-link');
    if (shipNav) shipNav.classList.add('active');

    // Fill header fields
    document.getElementById('ship-detail-name').value      = s.name;
    document.getElementById('ship-detail-status').value    = s.status;
    document.getElementById('ship-detail-etd').value       = s.etd || '';
    document.getElementById('ship-detail-eta').value       = s.eta || '';
    document.getElementById('ship-detail-delivered').value = s.deliveredOn || '';
    document.getElementById('ship-delivered-wrap').style.display = s.status === 'delivered' ? 'flex' : 'none';

    // Container type buttons
    document.querySelectorAll('.container-type-btn').forEach(btn => {
      btn.classList.toggle('active', btn.dataset.type === s.containerType);
    });

    renderShipmentOrders();
    renderShipmentUtilization();
    showView('view-shipment-detail');
  }

  function renderShipmentOrders() {
    const s = shipmentData[_currentShipmentId];
    if (!s) return;
    const listEl  = document.getElementById('ship-order-list');
    const emptyEl = document.getElementById('ship-order-empty');
    const countEl = document.getElementById('ship-order-count');
    const entries = s.entries || [];

    const orderEntries  = entries.filter(e => e.orderId);
    const sampleEntries = entries.filter(e => e.sampleKey != null && e.sampleRowIndex != null);
    if (countEl) {
      const parts = [];
      if (orderEntries.length)  parts.push(`${orderEntries.length} order${orderEntries.length !== 1 ? 's' : ''}`);
      if (sampleEntries.length) parts.push(`${sampleEntries.length} sample${sampleEntries.length !== 1 ? 's' : ''}`);
      countEl.textContent = parts.join(' · ');
    }

    if (orderEntries.length === 0 && sampleEntries.length === 0) {
      if (emptyEl) emptyEl.style.display = '';
      if (listEl)  listEl.innerHTML = '';
      return;
    }
    if (emptyEl) emptyEl.style.display = 'none';

    const fmt2 = v => v.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

    // Build sample cards first (small, distinct from full order cards)
    // so the operator can see them at a glance underneath the orders.
    const sampleCardsHtml = entries.map((entry, idx) => {
      if (entry.sampleKey == null || entry.sampleRowIndex == null) return '';
      const detail = workbookDetail[entry.sampleKey];
      if (!detail || !detail.rfqItems || !detail.rfqItems[entry.sampleRowIndex]) {
        // Sample's underlying RFQ row was deleted — surface a stub so
        // the operator can clear it from the shipment.
        return `<div class="ship-order-card" style="border-style:dashed; opacity:0.7;">
          <div class="ship-order-card-header">
            <div>
              <div class="soc-client" style="color:var(--text-muted);">Missing sample</div>
              <div class="soc-name" style="font-style:italic;">The original RFQ line item is gone.</div>
            </div>
            <button class="ship-wb-remove" onclick="event.stopPropagation(); removeOrderFromShipment(${idx})" title="Remove">×</button>
          </div>
        </div>`;
      }
      const item = detail.rfqItems[entry.sampleRowIndex];
      const [clientName, workbookId] = entry.sampleKey.split('|');
      const product = detail.product || workbookId;
      const wbHref  = `#/client/${encodeURIComponent(clientName)}/workbook/${workbookId}`;
      const qtyStr  = item.qty ? `${parseInt(item.qty).toLocaleString('en-US')} units` : '';
      const status  = (detail.sampleStatuses && detail.sampleStatuses[entry.sampleRowIndex]) || 'pending';
      const sc      = SAMPLE_STATUS_COLORS[status] || SAMPLE_STATUS_COLORS.pending;
      return `<div class="ship-order-card" onclick="location.hash='${wbHref}'" style="border-left:3px solid ${sc.border};">
        <div class="ship-order-card-header">
          <div>
            <div class="soc-client">${clientName} &nbsp;·&nbsp; <span style="font-weight:600; color:${sc.text}; font-size:11px; text-transform:uppercase; letter-spacing:0.04em;">Sample · ${SAMPLE_STATUS_LABELS[status]}</span></div>
            <div class="soc-name">${item.item || '(unnamed sample)'} <span style="color:var(--text-muted); font-weight:500;">— from ${product}${qtyStr ? ' · ' + qtyStr : ''}</span></div>
          </div>
          <button class="ship-wb-remove" onclick="event.stopPropagation(); removeOrderFromShipment(${idx})" title="Remove">×</button>
        </div>
      </div>`;
    }).filter(Boolean).join('');

    const orderCardsHtml = entries.map((entry, idx) => {
      if (!entry.orderId) return '';
      const order = orderData[entry.orderId];
      if (!order) return '';
      const stats  = orderShipStats(entry.orderId);
      const orderHref = `#/order/${entry.orderId}`;

      // Each stat is gated independently — Weight + CBM fall back to
      // the cached values from renderContainerViz when outer carton
      // dims aren't filled in (so we surface what we have instead of
      // dashing the whole row when one input is missing).
      const qtyStr     = stats.qty           > 0 ? stats.qty.toLocaleString('en-US') : '—';
      const cartonStr  = stats.totalCartons  > 0 ? stats.totalCartons.toLocaleString('en-US') : '—';
      const palletStr  = stats.palletsNeeded > 0 ? stats.palletsNeeded : '—';
      const cbmStr     = stats.totalCbm      > 0 ? stats.totalCbm + ' m³' : '—';
      const weightStr  = stats.totalWeightKg > 0 ? stats.totalWeightKg.toLocaleString('en-US') + ' kg' : '—';
      const usdStr     = stats.totalUsd      > 0 ? `$${fmt2(stats.totalUsd)}` : '—';
      const rmbStr     = stats.totalRmb      > 0 ? `¥${fmt2(stats.totalRmb)}` : '';

      // Workbook pills
      const wbPills = (order.entries || []).map(wbEntry => {
        const key    = `${wbEntry.clientName}|${wbEntry.workbookId}`;
        const detail = workbookDetail[key] || {};
        const prod   = detail.product || wbEntry.workbookId;
        const href   = `#/client/${encodeURIComponent(wbEntry.clientName)}/workbook/${wbEntry.workbookId}`;
        return `<span class="soc-wb-pill" onclick="event.stopPropagation(); _wbBackHash='#/shipment/${_currentShipmentId}'; _wbBackLabel='Back to Shipment'; location.hash='${href}'">${prod} →</span>`;
      }).join('');

      const crBanner = order.changeRequested
        ? `<div class="soc-cr-banner">
            <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M4 15s1-1 4-1 5 2 8 2 4-1 4-1V3s-1 1-4 1-5-2-8-2-4 1-4 1z"/><line x1="4" y1="22" x2="4" y2="15"/></svg>
            <span>Change request pending — <strong>hold this order</strong></span>
            <a href="#/order/${entry.orderId}" onclick="event.stopPropagation(); location.hash='#/order/${entry.orderId}'">View Request →</a>
           </div>`
        : '';

      return `<div class="ship-order-card${order.changeRequested ? ' has-change-request' : ''}" onclick="location.hash='${orderHref}'">
        <div class="ship-order-card-header">
          <div>
            <div class="soc-client">${order.clientName}</div>
            <div class="soc-name">${order.name} &nbsp;·&nbsp; ${stats.wbCount} workbook${stats.wbCount !== 1 ? 's' : ''}</div>
          </div>
          <div style="display:flex; align-items:center; gap:10px;">
            <div class="soc-cost">
              <span class="soc-cost-usd">${usdStr}</span>
              ${rmbStr ? `<span class="soc-cost-rmb">${rmbStr}</span>` : ''}
            </div>
            <button class="ship-wb-remove" onclick="event.stopPropagation(); removeOrderFromShipment(${idx})" title="Remove">×</button>
          </div>
        </div>
        <div class="ship-order-card-body">
          <div class="soc-workbooks">
            <div class="soc-wb-label">Workbooks</div>
            ${wbPills || '<span style="font-size:12px;color:var(--text-muted);font-style:italic;">None</span>'}
          </div>
          <div class="soc-stats">
            <div class="soc-stat"><span class="soc-stat-val">${qtyStr}</span><span class="soc-stat-lbl">Units</span></div>
            <div class="soc-stat"><span class="soc-stat-val">${cartonStr}</span><span class="soc-stat-lbl">Cartons</span></div>
            <div class="soc-stat"><span class="soc-stat-val">${palletStr}</span><span class="soc-stat-lbl">Pallets</span></div>
            <div class="soc-stat"><span class="soc-stat-val">${cbmStr}</span><span class="soc-stat-lbl">CBM</span></div>
            <div class="soc-stat"><span class="soc-stat-val">${weightStr}</span><span class="soc-stat-lbl">Weight</span></div>
          </div>
        </div>
        ${crBanner}
      </div>`;
    }).join('');

    listEl.innerHTML = orderCardsHtml + sampleCardsHtml;
    // Keep the Container View in lockstep with the order list —
    // every add/remove/detail-load path funnels through here.
    if (typeof renderShipmentContainerViz === 'function') renderShipmentContainerViz();
  }

  function deleteShipment(id) {
    const s = shipmentData[id];
    if (!s) return;
    if (!confirm(`Delete "${s.name}"? This cannot be undone.`)) return;
    delete shipmentData[id];
    saveShipments();
    rebuildShipmentsNav();
    location.hash = '#/shipments';
  }

  function deleteOrder(id) {
    const o = orderData[id];
    if (!o) return;
    if (!confirm(`Delete "${o.name}"? This cannot be undone.`)) return;
    delete orderData[id];
    saveOrders();
    rebuildOrdersNav();
    location.hash = '#/orders';
  }

  function removeOrderFromShipment(idx) {
    const s = shipmentData[_currentShipmentId];
    if (!s) return;
    s.entries.splice(idx, 1);
    saveShipments();
    renderShipmentOrders();
    renderShipmentUtilization();
  }

  // ── Container View ─────────────────────────────────────────────────
  // A bordered 40' HC outline at a FIXED 67 m³ scale. Each order
  // is a proportional colored block (width ∝ CBM) sitting inside,
  // labeled with name + CBM. Below it: a weight cap bar against
  // 26,000 kg (the truck axle limit — many shipments hit this
  // before they hit volume). Overflow on EITHER axis triggers an
  // amber bar. Per-order color reuses the shared client palette so
  // an order keeps a stable hue across views.
  const _SHIP_CV_PALETTE = ['#6b93ff','#f59e0b','#4ade80','#f472b6','#a78bfa','#34d399','#fb923c','#38bdf8','#e879f9','#facc15'];
  const _SHIP_CV_CAP    = 67;     // usable m³ in a 40' HC
  const _SHIP_CV_WT_CAP = 26000;  // max payload kg for a 40' HC (truck axle limit)

  function renderShipmentContainerViz() {
    const card  = document.getElementById('ship-container-viz-card');
    const empty = document.getElementById('ship-cv-empty');
    const body  = document.getElementById('ship-cv-body');
    const summ  = document.getElementById('ship-cv-cbm-summary');
    if (!card || !body) return;
    const s = shipmentData[_currentShipmentId];
    if (!s) return;

    // One volume per order (orders only — samples have no CBM model).
    const orders = (s.entries || [])
      .filter(e => e.orderId && orderData[e.orderId])
      .map((e, i) => {
        const o  = orderData[e.orderId];
        const st = (typeof orderShipStats === 'function') ? orderShipStats(e.orderId) : { totalCbm: 0, totalWeightKg: 0 };
        return {
          id:       e.orderId,
          name:     o.name || `Order #${e.orderId}`,
          cbm:      parseFloat(st.totalCbm) || 0,
          weightKg: parseFloat(st.totalWeightKg) || 0,
          color:    _SHIP_CV_PALETTE[i % _SHIP_CV_PALETTE.length],
        };
      })
      .filter(x => x.cbm > 0 || x.weightKg > 0);

    if (orders.length === 0) {
      if (empty) { empty.style.display = ''; empty.textContent =
        (s.entries || []).some(e => e.orderId) ? 'Orders have no CBM yet — open each workbook\'s Shipping tab to populate it.' : 'Add orders to see the container fill.'; }
      body.style.display = 'none';
      if (summ) summ.textContent = '';
      return;
    }
    if (empty) empty.style.display = 'none';
    body.style.display = '';

    const totalCbm  = orders.reduce((a, x) => a + x.cbm, 0);
    const totalWtKg = orders.reduce((a, x) => a + (x.weightKg || 0), 0);
    const fmtCbm    = n => n.toLocaleString('en-US', { minimumFractionDigits: 1, maximumFractionDigits: 1 });
    const fmtKg     = n => n.toLocaleString('en-US', { maximumFractionDigits: 0 });

    // Distribute orders across as many 67 m³ containers as needed.
    // Orders that don't fit in the current container roll into the
    // next; if a single order is itself larger than 67 m³ it splits
    // across containers (same color carries continuity). Each
    // container is rendered as its own outline below.
    const containers = [];
    let active = { fills: [], used: 0 };
    orders.forEach(o => {
      let remaining = o.cbm;
      while (remaining > 0) {
        if (active.used >= _SHIP_CV_CAP - 0.0001) {
          containers.push(active);
          active = { fills: [], used: 0 };
        }
        const take = Math.min(remaining, _SHIP_CV_CAP - active.used);
        active.fills.push({ id: o.id, name: o.name, color: o.color, cbm: take });
        active.used += take;
        remaining   -= take;
      }
    });
    if (active.used > 0 || containers.length === 0) containers.push(active);
    const containerCount = containers.length;

    // Header summary — now multi-container aware: when more than one
    // container is in use, the cap labels show the COMBINED capacity
    // so "over by" only fires when total exceeds N × 67 m³ (or
    // N × 26,000 kg) rather than the single-container limit.
    if (summ) {
      const cbmCapTot = _SHIP_CV_CAP * containerCount;
      const cbmOver   = Math.max(0, totalCbm - cbmCapTot);
      const cbmFree   = Math.max(0, cbmCapTot - totalCbm);
      const wtCapTot  = _SHIP_CV_WT_CAP * containerCount;
      const wtOverAll = Math.max(0, totalWtKg - wtCapTot);
      const cnt       = containerCount > 1 ? ` · ${containerCount} containers` : '';
      const cbmTxt = cbmOver > 0
        ? `<span style="color:#d97706; font-weight:700;">${fmtCbm(totalCbm)} / ${fmtCbm(cbmCapTot)} m³ · over by ${fmtCbm(cbmOver)}</span>`
        : `${fmtCbm(totalCbm)} / ${fmtCbm(cbmCapTot)} m³ · ${fmtCbm(cbmFree)} free`;
      const wtTxt = totalWtKg > 0
        ? (wtOverAll > 0
          ? ` · <span style="color:#d97706; font-weight:700;">${fmtKg(totalWtKg)} / ${fmtKg(wtCapTot)} kg · over by ${fmtKg(wtOverAll)}</span>`
          : ` · ${fmtKg(totalWtKg)} / ${fmtKg(wtCapTot)} kg`)
        : '';
      summ.innerHTML = cbmTxt + wtTxt + cnt;
    }

    const legend = `
      <div style="display:flex; flex-wrap:wrap; gap:8px 16px; margin-top:16px;">
        ${orders.map(o => `
          <div style="display:flex; align-items:center; gap:7px; font-size:12px;">
            <span style="width:12px; height:12px; border-radius:3px; background:${o.color}; flex-shrink:0; box-shadow:0 0 0 1px rgba(0,0,0,0.08);"></span>
            <span style="font-weight:600; color:var(--text);">${o.name}</span>
            <span style="color:var(--text-muted);">${fmtCbm(o.cbm)} m³${o.weightKg > 0 ? ` · ${fmtKg(o.weightKg)} kg` : ''}</span>
          </div>`).join('')}
      </div>`;

    // ── Container outlines (one per 67 m³ slice) ───────────────────
    // Each container = a bordered rectangle. Orders inside as
    // proportional colored blocks (width ∝ CBM share of 67), each
    // divided by a white separator and labeled with name + CBM.
    // Unused length renders as a plain "X m³ free" zone. Orders
    // that span multiple containers carry the same color so the
    // operator can trace one shipment across the row.
    const renderContainer = (c, idx) => {
      const used     = c.used;
      const freeC    = Math.max(0, _SHIP_CV_CAP - used);
      const fillsHtml = c.fills.map(f => {
        const w = (f.cbm / _SHIP_CV_CAP) * 100;
        const showName = w > 12;
        const showCbm  = w > 6;
        return `<div title="${f.name} — ${fmtCbm(f.cbm)} m³"
          style="width:${w}%; background:${f.color}; display:flex; flex-direction:column; align-items:center; justify-content:center; gap:2px; overflow:hidden; padding:0 4px; box-sizing:border-box; border-right:2px solid #fff;">
          ${showName ? `<span style="font-size:11px; font-weight:700; color:#fff; text-shadow:0 1px 2px rgba(0,0,0,0.35); white-space:nowrap; max-width:100%; overflow:hidden; text-overflow:ellipsis;">${f.name}</span>` : ''}
          ${showCbm  ? `<span style="font-size:10px; font-weight:600; color:rgba(255,255,255,0.92); text-shadow:0 1px 2px rgba(0,0,0,0.3); white-space:nowrap;">${fmtCbm(f.cbm)} m³</span>` : ''}
        </div>`;
      }).join('');
      const freePct = (freeC / _SHIP_CV_CAP) * 100;
      const freeZone = freePct > 0.5
        ? `<div style="width:${freePct}%; display:flex; align-items:center; justify-content:center; background:var(--surface2); color:var(--text-muted);">
             ${freePct > 8 ? `<span style="font-size:11px; font-weight:600;">${fmtCbm(freeC)} m³ free</span>` : ''}
           </div>`
        : '';
      const label = containerCount > 1
        ? `Container ${idx + 1} of ${containerCount}`
        : `40' HC Container`;
      return `
        <div style="margin-bottom:${idx < containerCount - 1 ? 12 : 0}px;">
          <div style="display:flex; align-items:center; justify-content:space-between; gap:6px; margin-bottom:6px; font-size:11px; font-weight:700; text-transform:uppercase; letter-spacing:0.05em; color:var(--text-muted);">
            <span>${label}</span><span style="opacity:0.6;">${fmtCbm(used)} / ${_SHIP_CV_CAP} m³</span>
          </div>
          <div style="display:flex; height:84px; border:3px solid var(--text); border-radius:8px; overflow:hidden; background:var(--surface);">
            ${fillsHtml}${freeZone}
          </div>
        </div>`;
    };

    const vizHtml = containers.map(renderContainer).join('') + buildWeightBar();

    // Weight cap bar — scales against (N containers × 26,000 kg).
    // When the cargo spans multiple containers via CBM, the weight
    // cap likewise scales since each truck-axle limit is per
    // container. Per-order colors match the container blocks above
    // so the operator can map "this color is heavy" vs "bulky".
    // Hidden when no order has weight cached.
    function buildWeightBar() {
      if (totalWtKg <= 0) return '';
      const perCap = _SHIP_CV_WT_CAP;
      const wtCap  = perCap * containerCount;
      const wtOverAll = Math.max(0, totalWtKg - wtCap);
      const wtFreeAll = Math.max(0, wtCap - totalWtKg);
      const scaleMax  = Math.max(totalWtKg, wtCap);
      const wtBlocks = orders.filter(o => o.weightKg > 0).map(o => {
        const w = (o.weightKg / scaleMax) * 100;
        const showLbl = w > 10;
        return `<div title="${o.name} — ${fmtKg(o.weightKg)} kg"
          style="width:${w}%; background:${o.color}; display:flex; align-items:center; justify-content:center; overflow:hidden; border-right:2px solid #fff;">
          ${showLbl ? `<span style="font-size:10px; font-weight:700; color:#fff; text-shadow:0 1px 2px rgba(0,0,0,0.35); white-space:nowrap;">${fmtKg(o.weightKg)} kg</span>` : ''}
        </div>`;
      }).join('');
      const wtFreePct = wtOverAll > 0 ? 0 : (wtFreeAll / wtCap) * 100 * (wtCap / scaleMax);
      const wtFreeZone = wtFreePct > 0.5
        ? `<div style="width:${wtFreePct}%; display:flex; align-items:center; justify-content:center; background:var(--surface2); color:var(--text-muted);">
             ${wtFreePct > 8 ? `<span style="font-size:10px; font-weight:600;">${fmtKg(wtFreeAll)} kg free</span>` : ''}
           </div>` : '';
      const capMarker = totalWtKg > wtCap
        ? `<div style="position:absolute; top:-4px; bottom:-4px; left:${(wtCap / scaleMax) * 100}%; width:2px; background:repeating-linear-gradient(180deg, #d97706 0 4px, transparent 4px 8px); z-index:2;"></div>`
        : '';
      const capLabel = containerCount > 1
        ? `${fmtKg(wtCap)} kg max (${containerCount} × ${fmtKg(perCap)})`
        : `${fmtKg(perCap)} kg max (truck axle limit)`;
      return `
        <div style="display:flex; align-items:center; justify-content:space-between; gap:6px; margin:14px 0 6px; font-size:11px; font-weight:700; text-transform:uppercase; letter-spacing:0.05em; color:var(--text-muted);">
          <span>Weight</span><span style="opacity:0.6;">${capLabel}</span>
        </div>
        <div style="position:relative; display:flex; height:32px; border:2px solid var(--text); border-radius:6px; overflow:hidden; background:var(--surface);">
          ${wtBlocks}${wtFreeZone}
          ${capMarker}
        </div>
        ${wtOverAll > 0 ? `<div style="margin-top:6px; font-size:11px; color:#d97706; font-weight:700;">⚠ Over weight cap by ${fmtKg(wtOverAll)} kg — split the load, downgauge cartons, or add another container.</div>` : ''}`;
    }

    body.innerHTML = vizHtml + legend;
  }

  function renderShipmentUtilization() {
    const s    = shipmentData[_currentShipmentId];
    if (!s) return;
    const spec = CONTAINER_SPECS[s.containerType] || CONTAINER_SPECS['40hc'];
    const tot  = shipmentTotals(s);

    function setUtil(prefix, val, max, unit) {
      const rawPct = max > 0 ? (val / max) * 100 : 0;
      const isOver = rawPct > 100;
      const barPct = Math.min(100, rawPct);
      const cls = isOver ? 'danger' : rawPct >= 85 ? 'warn' : '';
      const cur = document.getElementById(`ship-util-${prefix}-cur`);
      const mx  = document.getElementById(`ship-util-${prefix}-max`);
      const bar = document.getElementById(`ship-util-${prefix}-bar`);
      const pctEl = document.getElementById(`ship-util-${prefix}-pct`);
      if (cur) {
        cur.textContent = val.toLocaleString('en-US');
        cur.style.color = isOver ? '#ef4444' : '';
      }
      if (mx)  mx.textContent  = `/ ${max.toLocaleString('en-US')}`;
      if (bar) { bar.style.width = barPct.toFixed(1) + '%'; bar.className = 'ship-util-fill' + (cls ? ' ' + cls : ''); }
      if (pctEl) {
        pctEl.textContent = rawPct.toFixed(0) + '% full';
        pctEl.style.color = isOver ? '#ef4444' : '';
        pctEl.style.fontWeight = isOver ? '700' : '';
      }
    }

    setUtil('cbm', tot.cbm,    spec.cbm,        'm³');
    setUtil('wt',  tot.kg,     spec.maxKg,       'kg');
    setUtil('pal', tot.pallets, spec.maxPallets,  '');
  }

  // ── Container type selector ──────────────────────────────────────────
  function setContainerType(type) {
    const s = shipmentData[_currentShipmentId];
    if (!s) return;
    s.containerType = type;
    saveShipments();
    document.querySelectorAll('.container-type-btn').forEach(btn => {
      btn.classList.toggle('active', btn.dataset.type === type);
    });
    renderShipmentUtilization();
  }

  // ── Inline edits ─────────────────────────────────────────────────────
  function onShipmentNameChange() {
    const s = shipmentData[_currentShipmentId];
    if (!s) return;
    s.name = document.getElementById('ship-detail-name').value;
    saveShipments();
    rebuildShipmentsNav();
    document.getElementById('header-title').textContent = s.name;
  }
  function onShipmentStatusChange() {
    const s = shipmentData[_currentShipmentId];
    if (!s) return;
    s.status = document.getElementById('ship-detail-status').value;
    const wrap = document.getElementById('ship-delivered-wrap');
    if (wrap) wrap.style.display = s.status === 'delivered' ? 'flex' : 'none';
    saveShipments();
    rebuildShipmentsNav();
  }
  function onShipmentDateChange() {
    const s = shipmentData[_currentShipmentId];
    if (!s) return;
    s.etd         = document.getElementById('ship-detail-etd').value;
    s.eta         = document.getElementById('ship-detail-eta').value;
    s.deliveredOn = document.getElementById('ship-detail-delivered').value;
    saveShipments();
  }

  // ── Add Order to Shipment modal ──────────────────────────────────────
  let _shipSamplePickerSelected = new Set();

  function openAddOrderToShipmentModal() {
    _shipOrderPickerSelected = new Set();
    _shipSamplePickerSelected = new Set();
    // Populate client filter dropdown
    const sel = document.getElementById('ship-order-picker-client');
    sel.innerHTML = '<option value="">All clients</option>';
    Object.keys(clientData).sort().forEach(name => {
      const opt = document.createElement('option');
      opt.value = name; opt.textContent = name;
      sel.appendChild(opt);
    });
    document.getElementById('ship-order-picker-search').value = '';
    buildShipOrderPickerList('');
    buildShipSamplePickerList('');
    _updateShipPickerCounts();
    document.getElementById('modal-add-order-to-shipment').classList.add('open');
  }

  function closeAddOrderToShipmentModal() {
    document.getElementById('modal-add-order-to-shipment').classList.remove('open');
    _shipOrderPickerSelected = new Set();
    _shipSamplePickerSelected = new Set();
    const gt = document.getElementById('ship-picker-grand-total');
    if (gt) gt.style.display = 'none';
  }

  function onShipOrderClientChange() {
    const q = document.getElementById('ship-order-picker-search').value;
    buildShipOrderPickerList(q);
    buildShipSamplePickerList(q);
  }

  function buildShipOrderPickerList(query) {
    const list = document.getElementById('ship-order-picker-list');
    if (!list) return;
    const filterClient = document.getElementById('ship-order-picker-client').value;
    query = (query || '').toLowerCase();

    const s = shipmentData[_currentShipmentId];
    const alreadyIn = new Set((s ? s.entries : []).filter(e => e.orderId).map(e => String(e.orderId)));

    const fmt2 = v => v.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    const palette = ['#6b93ff','#f59e0b','#4ade80','#f472b6','#a78bfa','#34d399','#fb923c','#38bdf8'];
    const sortedClients = Object.keys(clientData).sort();

    // Group orders by client
    const clients = filterClient ? [filterClient] : sortedClients;

    let html = '';
    let totalShown = 0;

    // Reset the per-order snapshot for this render so removed /
    // filtered orders don't linger in the grand total sums.
    _shipPickerOrderData = {};

    clients.forEach(clientName => {
      const orders = Object.values(orderData).filter(o => o.clientName === clientName);
      const color    = palette[sortedClients.indexOf(clientName) % palette.length];
      const initials = clientName.substring(0, 3).toUpperCase();

      const matchedOrders = orders.filter(o =>
        !query || o.name.toLowerCase().includes(query) || clientName.toLowerCase().includes(query)
      );
      if (matchedOrders.length === 0) return;

      // Client group label (only when showing all clients)
      if (!filterClient) {
        html += `<div class="wb-picker-group-label">${clientName}</div>`;
      }

      matchedOrders.forEach(order => {
        totalShown++;
        const id        = String(order.id);
        const isChecked = _shipOrderPickerSelected.has(id);
        const inShip    = alreadyIn.has(id);
        const wbCount   = (order.entries || []).length;

        // Sum the per-workbook stats across this order so we can show
        // total units / weight / cost / price / CBM as the order's
        // shape. Helper centralizes the source-of-truth selection +
        // CBM fallback so every picker / card stays aligned.
        let units = 0, weightKg = 0, cost = 0, price = 0, cbm = 0;
        (order.entries || []).forEach(entry => {
          const key = `${entry.clientName}|${entry.workbookId}`;
          const w = _wbStatsForPicker(workbookDetail[key]);
          units    += w.units;
          weightKg += w.weightKg;
          cost     += w.cost;
          price    += w.price;
          cbm      += w.cbm;
        });
        _shipPickerOrderData[id] = { units, weightKg, cost, price, cbm };

        // Per-row stat line: units · weight (CBM) · our cost. CBM is
        // tucked in next to weight (colored so it reads as one
        // shipment-dimensions phrase) so the operator can scan both
        // numbers without hunting. Mirrors the Add Workbook to Order
        // picker; falls back to "—" individually when caches haven't
        // been populated yet.
        const partsSummary = [];
        partsSummary.push(units > 0 ? `${units.toLocaleString('en-US')} units` : '— units');
        const cbmPill = cbm > 0
          ? ` <span style="color:var(--accent); font-weight:600;">(${cbm.toLocaleString('en-US', {minimumFractionDigits: 1, maximumFractionDigits: 1})} CBM)</span>`
          : '';
        const weightCbmStr = weightKg > 0
          ? `${weightKg.toLocaleString('en-US', {maximumFractionDigits: 0})} kg${cbmPill}`
          : (cbm > 0 ? `— kg${cbmPill}` : '— kg');
        partsSummary.push(weightCbmStr);
        partsSummary.push(cost > 0 ? `$${fmt2(cost)}` : '—');
        const statStr = partsSummary.join(' · ');

        html += `<div class="wb-picker-item${isChecked ? ' selected' : ''}"
            style="${inShip ? 'opacity:0.4; pointer-events:none;' : ''}"
            onclick="toggleShipOrderPickerItem('${id}')">
          <div style="width:40px; height:40px; border-radius:8px; background:${color}22; border:1px solid ${color}44; display:flex; align-items:center; justify-content:center; font-size:11px; font-weight:800; color:${color}; flex-shrink:0; letter-spacing:0.02em;">
            ${initials}
          </div>
          <div class="wb-picker-info">
            <div class="wb-picker-product">${order.name}</div>
            <div class="wb-picker-client">${clientName} &nbsp;·&nbsp; ${wbCount} workbook${wbCount !== 1 ? 's' : ''}${inShip ? ' · Already in shipment' : ''}</div>
            <div class="wb-picker-tiers">${statStr}</div>
          </div>
          <div style="width:20px; height:20px; border-radius:4px; border:2px solid ${isChecked ? 'var(--accent)' : 'var(--border)'}; background:${isChecked ? 'var(--accent)' : 'transparent'}; display:flex; align-items:center; justify-content:center; flex-shrink:0; transition:all 0.15s;">
            ${isChecked ? '<svg width="11" height="9" viewBox="0 0 11 9" fill="none"><path d="M1 4L4 7.5L10 1" stroke="white" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>' : ''}
          </div>
        </div>`;
      });
    });

    if (totalShown === 0) {
      list.innerHTML = `<div style="text-align:center; padding:30px; color:var(--text-muted); font-size:13px;">
        ${query ? 'No orders match your search.' : 'No orders found.'}
      </div>`;
      _renderShipPickerGrandTotal();
      return;
    }
    list.innerHTML = html;
    _renderShipPickerGrandTotal();
  }

  // Sums the per-order snapshot across selected orders and paints the
  // Grand Total card. Hidden when nothing is selected. Mirrors
  // _renderOrderAddGrandTotal / _renderOrderPickerGrandTotal.
  function _renderShipPickerGrandTotal() {
    const card = document.getElementById('ship-picker-grand-total');
    if (!card) return;
    const sel = _shipOrderPickerSelected;
    if (!sel || sel.size === 0) {
      card.style.display = 'none';
      return;
    }
    card.style.display = '';
    let units = 0, weightKg = 0, cost = 0, price = 0, cbm = 0;
    sel.forEach(id => {
      const d = (_shipPickerOrderData && _shipPickerOrderData[id]) || null;
      if (!d) return;
      units    += d.units    || 0;
      weightKg += d.weightKg || 0;
      cost     += d.cost     || 0;
      price    += d.price    || 0;
      cbm      += d.cbm      || 0;
    });
    const fmtNum = n => n.toLocaleString('en-US');
    const fmtUsd = n => '$' + n.toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2});
    const fmtKg  = n => n.toLocaleString('en-US', {maximumFractionDigits: 0}) + ' kg';
    const fmtCbm = n => n.toLocaleString('en-US', {minimumFractionDigits: 1, maximumFractionDigits: 1});
    const set = (id, txt) => { const el = document.getElementById(id); if (el) el.textContent = txt; };
    set('ship-picker-gt-count',  `${sel.size} order${sel.size === 1 ? '' : 's'} selected`);
    set('ship-picker-gt-units',  units    > 0 ? fmtNum(units)  : '—');
    set('ship-picker-gt-weight', weightKg > 0 ? fmtKg(weightKg) : '—');
    set('ship-picker-gt-cost',   cost     > 0 ? fmtUsd(cost)    : '—');
    set('ship-picker-gt-price',  price    > 0 ? fmtUsd(price)   : '—');
    const cbmCap = 67;
    const cbmOver = cbm > cbmCap ? cbm - cbmCap : 0;
    _renderCbmFillIndicator('ship-picker-gt-cbm-label', 'ship-picker-gt-cbm-bar', cbm, cbmCap, cbmOver, fmtCbm);
  }

  // Shared CBM fill indicator: paints the label + progress bar and
  // surfaces an amber overflow badge when total CBM exceeds the
  // single-container cap (67 m³). Used by every picker / card so the
  // overflow signal looks identical across the app. labelId targets
  // a span whose innerHTML we control; barId targets the fill div.
  function _renderCbmFillIndicator(labelId, barId, cbm, cbmCap, cbmOver, fmtCbm) {
    const labelEl = document.getElementById(labelId);
    if (labelEl) {
      if (cbm <= 0) {
        labelEl.innerHTML = `— / ${cbmCap} CBM`;
      } else if (cbmOver > 0) {
        // Amber + warning glyph + "+X.X over" so the operator knows
        // they've spilled into a 2nd container.
        labelEl.innerHTML = `<span style="color:#fde047;">⚠</span> ${fmtCbm(cbm)} / ${cbmCap} CBM <span style="color:#fde047; font-weight:800; margin-left:4px;">+${fmtCbm(cbmOver)} over</span>`;
      } else {
        labelEl.innerHTML = `${fmtCbm(cbm)} / ${cbmCap} CBM`;
      }
    }
    const bar = document.getElementById(barId);
    if (bar) {
      const fillPct = Math.min(100, cbm > 0 ? (cbm / cbmCap) * 100 : 0);
      bar.style.width = fillPct + '%';
      bar.style.background = cbmOver > 0 ? '#fde047' : '#fff';
    }
  }

  function filterShipOrderPicker(query) {
    buildShipOrderPickerList(query);
    buildShipSamplePickerList(query);
  }

  function toggleShipOrderPickerItem(id) {
    if (_shipOrderPickerSelected.has(id)) {
      _shipOrderPickerSelected.delete(id);
    } else {
      _shipOrderPickerSelected.add(id);
    }
    buildShipOrderPickerList(document.getElementById('ship-order-picker-search').value);
    _updateShipPickerCounts();
  }

  function _updateShipPickerCounts() {
    const oc = document.getElementById('ship-picker-orders-count');
    const sc = document.getElementById('ship-picker-samples-count');
    if (oc) oc.textContent = _shipOrderPickerSelected.size  > 0 ? `${_shipOrderPickerSelected.size} selected`  : '';
    if (sc) sc.textContent = _shipSamplePickerSelected.size > 0 ? `${_shipSamplePickerSelected.size} selected` : '';
  }

  // ── Sample picker section in the +Add to Shipment modal ───────────
  // Populates the "Samples" list under the Orders list. Mirrors the
  // orders picker behavior — same client filter + same search box.
  // sampleId encoding: `<clientName>|<workbookId>|<rowIndex>`. We store
  // just enough to round-trip back to the original RFQ line item when
  // we render the shipment entry later.
  function buildShipSamplePickerList(query) {
    const list = document.getElementById('ship-sample-picker-list');
    if (!list) return;
    const filterClient = document.getElementById('ship-order-picker-client').value;
    query = (query || '').toLowerCase();

    const s = shipmentData[_currentShipmentId];
    const alreadyIn = new Set((s ? s.entries : [])
      .filter(e => e.sampleKey != null && e.sampleRowIndex != null)
      .map(e => `${e.sampleKey}|${e.sampleRowIndex}`));

    const allSamples = collectAllSamples();
    const palette = ['#6b93ff','#f59e0b','#4ade80','#f472b6','#a78bfa','#34d399','#fb923c','#38bdf8'];
    const sortedClients = Object.keys(clientData).sort();

    const matched = allSamples.filter(sm => {
      if (filterClient && sm.clientName !== filterClient) return false;
      if (!query) return true;
      const hay = `${sm.item} ${sm.product} ${sm.clientName}`.toLowerCase();
      return hay.includes(query);
    });

    if (matched.length === 0) {
      list.innerHTML = `<div style="text-align:center; padding:18px 12px; color:var(--text-muted); font-size:12px; font-style:italic;">${query ? 'No samples match your search.' : 'No sample requests flagged yet. Tick the Sample box on any RFQ row to add one here.'}</div>`;
      return;
    }

    let html = '';
    let lastClient = null;
    matched.forEach(sm => {
      const sampleId = `${sm.key}|${sm.rowIndex}`;
      const isChecked = _shipSamplePickerSelected.has(sampleId);
      const inShip    = alreadyIn.has(sampleId);
      const color     = palette[sortedClients.indexOf(sm.clientName) % palette.length] || palette[0];
      const initials  = sm.clientName.substring(0, 3).toUpperCase();

      // Group label only when showing all clients
      if (!filterClient && sm.clientName !== lastClient) {
        html += `<div class="wb-picker-group-label">${sm.clientName}</div>`;
        lastClient = sm.clientName;
      }
      const qtyStr  = sm.qty && sm.qty !== '—' ? `${parseInt(sm.qty).toLocaleString('en-US')} units` : '';
      const subline = `${sm.product}${qtyStr ? ' · ' + qtyStr : ''} · ${sm.status}`;

      html += `<div class="wb-picker-item${isChecked ? ' selected' : ''}"
          style="${inShip ? 'opacity:0.4; pointer-events:none;' : ''}"
          onclick="toggleShipSamplePickerItem('${sampleId.replace(/'/g, "\\'")}')">
        <div style="width:40px; height:40px; border-radius:8px; background:${color}22; border:1px solid ${color}44; display:flex; align-items:center; justify-content:center; font-size:11px; font-weight:800; color:${color}; flex-shrink:0; letter-spacing:0.02em;">
          ${initials}
        </div>
        <div class="wb-picker-info">
          <div class="wb-picker-product">${sm.item || '(unnamed sample)'}</div>
          <div class="wb-picker-client">${sm.clientName} &nbsp;·&nbsp; ${subline}${inShip ? ' · Already in shipment' : ''}</div>
        </div>
        <div style="width:20px; height:20px; border-radius:4px; border:2px solid ${isChecked ? 'var(--accent)' : 'var(--border)'}; background:${isChecked ? 'var(--accent)' : 'transparent'}; display:flex; align-items:center; justify-content:center; flex-shrink:0; transition:all 0.15s;">
          ${isChecked ? '<svg width="11" height="9" viewBox="0 0 11 9" fill="none"><path d="M1 4L4 7.5L10 1" stroke="white" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>' : ''}
        </div>
      </div>`;
    });
    list.innerHTML = html;
  }

  function toggleShipSamplePickerItem(sampleId) {
    if (_shipSamplePickerSelected.has(sampleId)) {
      _shipSamplePickerSelected.delete(sampleId);
    } else {
      _shipSamplePickerSelected.add(sampleId);
    }
    buildShipSamplePickerList(document.getElementById('ship-order-picker-search').value);
    _updateShipPickerCounts();
  }

  function confirmAddOrderToShipment() {
    if (_shipOrderPickerSelected.size === 0 && _shipSamplePickerSelected.size === 0) {
      alert('Select at least one order or sample.'); return;
    }
    const s = shipmentData[_currentShipmentId];
    if (!s) return;
    s.entries = s.entries || [];
    _shipOrderPickerSelected.forEach(id => {
      const orderId = parseInt(id);
      const alreadyIn = s.entries.some(e => e.orderId === orderId);
      if (!alreadyIn) s.entries.push({ orderId });
    });
    _shipSamplePickerSelected.forEach(sampleId => {
      // sampleId = "clientName|workbookId|rowIndex" — split from the right
      // so client names containing '|' don't break parsing.
      const lastBar = sampleId.lastIndexOf('|');
      const sampleKey = sampleId.substring(0, lastBar);
      const sampleRowIndex = parseInt(sampleId.substring(lastBar + 1));
      const alreadyIn = s.entries.some(e => e.sampleKey === sampleKey && e.sampleRowIndex === sampleRowIndex);
      if (!alreadyIn) s.entries.push({ sampleKey, sampleRowIndex });
    });
    saveShipments();
    closeAddOrderToShipmentModal();
    renderShipmentOrders();
    renderShipmentUtilization();
  }

  function buildWbPickerList(query) {
    const list = document.getElementById('wb-picker-list');
    if (!list) return;
    query = (query || '').toLowerCase();

    // Collect completed workbooks only
    const all = [];
    Object.entries(clientData).forEach(([clientName, wbs]) => {
      (wbs || []).forEach(wb => {
        // Only include completed workbooks
        if (!isFlowComplete(wb.flow || {})) return;
        const key    = `${clientName}|${wb.id}`;
        const detail = workbookDetail[key] || {};
        const product = detail.product || wb.product || '—';
        if (query && !product.toLowerCase().includes(query) && !clientName.toLowerCase().includes(query)) return;
        const tiers  = (detail.tiers || []);
        const tierStr = tiers.length > 0
          ? tiers.map(t => `${parseInt(t.qty || 0).toLocaleString('en-US')} units`).join(' · ')
          : 'No tiers set';
        all.push({ clientName, workbookId: wb.id, product, tierStr, detail, key: `${clientName}|${wb.id}` });
      });
    });

    if (all.length === 0) {
      list.innerHTML = `<div style="text-align:center; padding:30px; color:var(--text-muted); font-size:13px;">
        ${query ? 'No completed workbooks match your search.' : 'No completed workbooks found.'}
      </div>`;
      return;
    }

    // Client colour palette for avatars
    const palette = ['#6b93ff','#f59e0b','#4ade80','#f472b6','#a78bfa','#34d399','#fb923c','#38bdf8'];
    const clientColors = {};
    let colorIdx = 0;

    list.innerHTML = all.map((item) => {
      if (!clientColors[item.clientName]) {
        clientColors[item.clientName] = palette[colorIdx++ % palette.length];
      }
      const color      = clientColors[item.clientName];
      const isChecked  = _wbPickerSelected.has(item.key);
      // Client avatar: up to 3 chars of client name
      const initials   = item.clientName.substring(0, 3).toUpperCase();

      return `<div class="wb-picker-item${isChecked ? ' selected' : ''}"
          onclick="toggleWbPickerItem('${item.key.replace(/'/g,"\\'")}')">
        <div style="width:40px; height:40px; border-radius:8px; background:${color}22; border:1px solid ${color}44; display:flex; align-items:center; justify-content:center; font-size:11px; font-weight:800; color:${color}; flex-shrink:0; letter-spacing:0.02em;">
          ${initials}
        </div>
        <div class="wb-picker-info">
          <div class="wb-picker-product">${item.product}</div>
          <div class="wb-picker-client">${item.clientName}</div>
          <div class="wb-picker-tiers">${item.tierStr}</div>
        </div>
        <div style="width:20px; height:20px; border-radius:4px; border:2px solid ${isChecked ? 'var(--accent)' : 'var(--border)'}; background:${isChecked ? 'var(--accent)' : 'transparent'}; display:flex; align-items:center; justify-content:center; flex-shrink:0; transition:all 0.15s;">
          ${isChecked ? '<svg width="11" height="9" viewBox="0 0 11 9" fill="none"><path d="M1 4L4 7.5L10 1" stroke="white" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>' : ''}
        </div>
      </div>`;
    }).join('');
  }

  function filterWbPicker(query) {
    buildWbPickerList(query);
  }

  function toggleWbPickerItem(key) {
    if (_wbPickerSelected.has(key)) {
      _wbPickerSelected.delete(key);
    } else {
      _wbPickerSelected.add(key);
    }
    buildWbPickerList(document.getElementById('wb-picker-search').value);
  }

  function confirmAddWorkbook() {
    if (_wbPickerSelected.size === 0) { alert('Select at least one workbook.'); return; }
    const s = shipmentData[_currentShipmentId];
    if (!s) return;
    _wbPickerSelected.forEach(key => {
      const [clientName, workbookId] = key.split('|');
      // Don't add duplicates
      const alreadyAdded = s.entries.some(e => e.clientName === clientName && String(e.workbookId) === String(workbookId));
      if (!alreadyAdded) {
        s.entries.push({ clientName, workbookId: parseInt(workbookId) || workbookId, qty: 1000 });
      }
    });
    saveShipments();
    closeAddOrderToShipmentModal();
    renderShipmentOrders();
    renderShipmentUtilization();
  }

  function removeWorkbookFromShipment(idx) {
    const s = shipmentData[_currentShipmentId];
    if (!s) return;
    s.entries.splice(idx, 1);
    saveShipments();
    renderShipmentOrders();
    renderShipmentUtilization();
  }

  // ── CSS for selected picker item ─────────────────────────────────────
  (function() {
    const style = document.createElement('style');
    style.textContent = '.wb-picker-item.selected { background: rgba(107,147,255,0.1); outline: 2px solid rgba(107,147,255,0.4); border-radius: var(--radius-sm); }';
    document.head.appendChild(style);
  })();

  // ══════════════════════════════════════════════════════════════════════
  // ORDERS MODULE
  // ══════════════════════════════════════════════════════════════════════

  // ── Persistence ──────────────────────────────────────────────────────
  function saveOrders() {
    try { localStorage.setItem('ms_orderData', JSON.stringify(orderData)); } catch(e) {}
    try { localStorage.setItem('ms_nextOrderId', String(_nextOrderId)); } catch(e) {}
    if (Object.keys(orderData).length > 0 || _nextOrderId > 1) {
      const payload = JSON.stringify({ data: orderData, nextId: _nextOrderId });
      _lastOrdersJson = payload; // prevent our own save from triggering a poll re-render
      apiCall('save_app_state', { key: 'ms_orders', value: payload }).catch(() => {});
    }
  }

  function loadOrders() {
    try {
      const d = localStorage.getItem('ms_orderData');
      const n = localStorage.getItem('ms_nextOrderId');
      if (d) { orderData = JSON.parse(d); }
      if (n) { _nextOrderId = Math.max(parseInt(n) || 1, ...Object.keys(orderData).map(Number).map(x => x + 1), 1); }
    } catch(e) { orderData = {}; _nextOrderId = 1; }
  }

  // ── Sync orders/shipments from DB (overwrites local if DB has data) ──
  async function syncOrdersFromDB() {
    try {
      const res = await apiCall('get_app_state', { key: 'ms_orders' });
      if (!res.success) return false;
      if (res.value) {
        _lastOrdersJson = res.value; // seed poll cache so first poll doesn't false-trigger
        const stored = JSON.parse(res.value);
        if (stored && stored.data && Object.keys(stored.data).length > 0) {
          orderData    = stored.data;
          _nextOrderId = stored.nextId || Math.max(1, ...Object.keys(stored.data).map(Number).map(x => x + 1));
          try { localStorage.setItem('ms_orderData',   JSON.stringify(orderData)); } catch(e) {}
          try { localStorage.setItem('ms_nextOrderId', String(_nextOrderId));       } catch(e) {}
          return true;
        }
      }
      // DB empty — push local data up so other users can see it
      if (Object.keys(orderData).length > 0) {
        const payload = JSON.stringify({ data: orderData, nextId: _nextOrderId });
        _lastOrdersJson = payload;
        await apiCall('save_app_state', { key: 'ms_orders', value: payload });
      }
    } catch(e) { console.warn('syncOrdersFromDB:', e); }
    return false;
  }

  async function syncShipmentsFromDB() {
    try {
      const res = await apiCall('get_app_state', { key: 'ms_shipments' });
      if (!res.success) return false;
      if (res.value) {
        _lastShipmentsJson = res.value; // seed poll cache
        const stored = JSON.parse(res.value);
        if (stored && stored.data && Object.keys(stored.data).length > 0) {
          shipmentData    = stored.data;
          _nextShipmentId = stored.nextId || Math.max(1, ...Object.keys(stored.data).map(Number).map(x => x + 1));
          try { localStorage.setItem('ms_shipmentData',   JSON.stringify(shipmentData)); } catch(e) {}
          try { localStorage.setItem('ms_nextShipmentId', String(_nextShipmentId));       } catch(e) {}
          return true;
        }
      }
      // DB empty — push local data up
      if (Object.keys(shipmentData).length > 0) {
        const payload = JSON.stringify({ data: shipmentData, nextId: _nextShipmentId });
        _lastShipmentsJson = payload;
        await apiCall('save_app_state', { key: 'ms_shipments', value: payload });
      }
    } catch(e) { console.warn('syncShipmentsFromDB:', e); }
    return false;
  }

  // ── Totals helper ────────────────────────────────────────────────────
  // ── Background poll — picks up changes made on another device/browser ──
  async function pollForRemoteChanges() {
    if (_pollActive) return; // don't overlap with a slow previous poll
    _pollActive = true;
    try {
      const h = location.hash;
      const onWorkbookEditor = h.startsWith('#/client/') && h.includes('/workbook/');
      const onOrdersView     = h.startsWith('#/order');
      const onShipmentsView  = h.startsWith('#/shipment');

      // ── 1. Orders & shipments — lightweight raw-string comparison ──────
      const [ordRes, shipRes] = await Promise.all([
        apiCall('get_app_state', { key: 'ms_orders' }),
        apiCall('get_app_state', { key: 'ms_shipments' }),
      ]);

      let ordChanged = false, shipChanged = false;

      if (ordRes.success && ordRes.value && ordRes.value !== _lastOrdersJson) {
        _lastOrdersJson = ordRes.value;
        const s = JSON.parse(ordRes.value);
        if (s?.data) {
          orderData    = s.data;
          _nextOrderId = s.nextId || _nextOrderId;
          try { localStorage.setItem('ms_orderData',   JSON.stringify(orderData)); } catch(e) {}
          try { localStorage.setItem('ms_nextOrderId', String(_nextOrderId));       } catch(e) {}
          rebuildOrdersNav();
          ordChanged = true;
        }
      }

      if (shipRes.success && shipRes.value && shipRes.value !== _lastShipmentsJson) {
        _lastShipmentsJson = shipRes.value;
        const s = JSON.parse(shipRes.value);
        if (s?.data) {
          shipmentData    = s.data;
          _nextShipmentId = s.nextId || _nextShipmentId;
          try { localStorage.setItem('ms_shipmentData',   JSON.stringify(shipmentData)); } catch(e) {}
          try { localStorage.setItem('ms_nextShipmentId', String(_nextShipmentId));       } catch(e) {}
          rebuildShipmentsNav();
          shipChanged = true;
        }
      }

      // Re-render only the relevant view if it's currently open
      if (ordChanged && onOrdersView)     router();
      if (shipChanged && onShipmentsView) router();

      // ── 2. Workbooks & clients — heavier call, skip if actively editing ─
      if (!_isDirty) {
        const preClient = currentClient;
        const preWbId   = currentWorkbookId;
        const dbLoaded  = await loadFromDatabase();
        // Only re-render when we actually got workbooks from the DB (true).
        // 'empty' = DB reachable but empty → no change to show;
        // false = API error → keep showing local state.
        if (dbLoaded === true) {
          rebuildSidebar();
          // Avoid re-rendering the workbook editor mid-session (would reset the form)
          if (!onWorkbookEditor) {
            router();
          }
        }
      }
    } catch(e) { /* silent — network blip shouldn't surface as an error */ }
    finally { _pollActive = false; }
  }

  // ── Real-time presence ────────────────────────────────────────────────────
  // Each user gets a random color per session, stored so it stays consistent
  // while the tab is open but varies across users/devices.
  //
  // These are declared with `var` (not `let`/`const`) on purpose: the module
  // init IIFE at the bottom of the file calls router() during its sync
  // prefix, and on a workbook URL that resolves to fillWorkbook →
  // startPresenceHeartbeat, which reads these variables. Since the init
  // IIFE runs BEFORE this declaration line, `let` would put us in the
  // temporal dead zone and throw \"Cannot access '_presenceInterval' before
  // initialization\". `var` hoists to undefined, which the falsy guards in
  // stopPresenceHeartbeat already handle correctly.
  var _PRESENCE_COLORS = [
    '#e74c3c','#3498db','#2ecc71','#f39c12',
    '#9b59b6','#1abc9c','#e67e22','#e91e63','#16a085','#8e44ad'
  ];
  var _myPresenceColor = sessionStorage.getItem('ms_presence_color');
  if (!_myPresenceColor) {
    _myPresenceColor = _PRESENCE_COLORS[Math.floor(Math.random() * _PRESENCE_COLORS.length)];
    sessionStorage.setItem('ms_presence_color', _myPresenceColor);
  }

  var _presenceWorkbookId = null;
  var _presenceInterval   = null;
  var _myFocusedField     = '';

  // Live cell-value sync state
  var _cellValuesSince    = '';   // server timestamp cursor for delta polling
  var _pendingPushes      = new Map(); // fieldPath -> debounce timer id

  // Live workbook-broadcast state. Cursor for the lightweight dirty-check
  // poll (separate from cell-values — cell-values handles RFQ keystrokes,
  // this handles whole-workbook saves of every other field).
  // _lastSeenUpdatedAt is the timestamp of the last save we've ALREADY
  // applied locally. Bumped both on remote saves we apply AND on our own
  // saves (so the next poll doesn't echo our own change back at us).
  var _lastSeenUpdatedAt  = '';
  var _wbBroadcastInflight = false; // guard against overlapping pulls

  // ── In-app + Chrome browser notifications ──────────────────────────
  // Polled every 12 s on every page (not just workbooks) so a watcher
  // sees milestone notifications even when they're on the home view.
  // Cursor stays in sessionStorage so reloading the same tab doesn't
  // re-fire notifications you already saw, but a brand-new session
  // starts fresh and shows the most recent batch (catch-up).
  var _notifSince        = sessionStorage.getItem('ms_notif_since') || '';
  var _notifInterval     = null;
  var _notifSeenIds      = new Set(); // dedupe across rapid polls within one session
  // Hint state for the "Enable browser notifications" prompt — we only
  // surface it on the Watchers modal (a natural place) when permission
  // is still in its default state.
  var _notifPromptShown  = false;

  function _notifSupported() {
    return typeof window !== 'undefined' && 'Notification' in window;
  }
  function _notifPermission() {
    return _notifSupported() ? Notification.permission : 'unsupported';
  }
  async function requestBrowserNotifPermission() {
    if (!_notifSupported()) return 'unsupported';
    try {
      const r = await Notification.requestPermission();
      return r;
    } catch (e) { return 'denied'; }
  }

  function _showBrowserNotification(n) {
    if (!_notifSupported() || _notifPermission() !== 'granted') return;
    try {
      const opts = {
        body: n.body || '',
        icon: '/favicon.svg',
        badge: '/favicon.svg',
        tag:  'ms-notif-' + n.id,
        requireInteraction: false,
        silent: false,
      };
      const notif = new Notification(n.title || 'Market Sculpt', opts);
      if (n.url) {
        notif.onclick = () => {
          window.focus();
          // n.url is an absolute app URL with a hash — assigning to
          // location.href triggers our hash router. If it's just a
          // hash fragment, set location.hash directly.
          if (/^#/.test(n.url)) location.hash = n.url;
          else                  location.href = n.url;
          notif.close();
        };
      }
      // Best-effort fire-and-forget mark-as-read so the same row
      // doesn't re-pop on a different tab. Server-side cursor will
      // also have moved past it on the next poll.
      apiCall('mark_notification_read', { id: n.id }).catch(() => {});
    } catch (e) {}
  }

  async function _pollNotifications() {
    try {
      const r = await apiCall('get_notifications', { since: _notifSince });
      if (!r || !r.success) return;
      if (r.server_now) {
        _notifSince = r.server_now;
        try { sessionStorage.setItem('ms_notif_since', _notifSince); } catch (e) {}
      }
      const items = Array.isArray(r.data) ? r.data : [];
      items.forEach(n => {
        if (_notifSeenIds.has(n.id)) return;
        _notifSeenIds.add(n.id);
        _showBrowserNotification(n);
      });
    } catch (e) {}
  }

  function startNotificationsPolling() {
    if (_notifInterval) return;
    // First call after a short delay so the rest of the page can mount
    setTimeout(_pollNotifications, 800);
    _notifInterval = setInterval(_pollNotifications, 12000);
  }
  function stopNotificationsPolling() {
    if (_notifInterval) { clearInterval(_notifInterval); _notifInterval = null; }
  }

  function startPresenceHeartbeat(workbookId) {
    // Stop any previous heartbeat (switching workbooks)
    stopPresenceHeartbeat(/* silent */ true);
    _presenceWorkbookId = workbookId;
    _cellValuesSince    = '';   // reset cursor for new workbook
    _lastSeenUpdatedAt  = '';   // baseline on first dirty-check response
    _sendPresenceHeartbeat();
    _pollPresence();
    _pollCellValues();
    _pollWorkbookDirty();
    _presenceInterval = setInterval(() => {
      _sendPresenceHeartbeat();
      _pollPresence();
      _pollCellValues();
      _pollWorkbookDirty();
    }, 2000);  // 2 s — near real-time cursor tracking like Google Sheets
  }

  function stopPresenceHeartbeat(silent = false) {
    if (_presenceInterval) { clearInterval(_presenceInterval); _presenceInterval = null; }
    if (_presenceWorkbookId) {
      if (!silent) {
        // Best-effort instant clear via beacon so we vanish immediately
        try {
          navigator.sendBeacon(
            'api.php?action=clear_presence',
            new Blob([JSON.stringify({action:'clear_presence'})], {type:'application/json'})
          );
        } catch(e) {}
      }
      _presenceWorkbookId = null;
      _myFocusedField     = '';
      _cellValuesSince    = '';
      _lastSeenUpdatedAt  = '';
      // Cancel any pending cell-value pushes
      _pendingPushes.forEach(t => clearTimeout(t));
      _pendingPushes.clear();
      _clearPresenceIndicators();
    }
  }

  async function _sendPresenceHeartbeat() {
    if (!_presenceWorkbookId) return;
    // Re-render the banner + section bars with our current local
    // _myFocusedField BEFORE awaiting the network round-trip, so the
    // UI feels instant when the user clicks into a new section.
    _refreshPresenceUI();
    try {
      await apiCall('update_presence', {
        workbook_id:   _presenceWorkbookId,
        focused_field: _myFocusedField,
        color:         _myPresenceColor
      });
    } catch(e) {}
  }

  // Cache the most-recent server response so _renderPresence can be
  // re-run with the same other-user list when our local state (focused
  // section) changes — no need to wait for the next poll.
  var _lastPresenceUsers = [];

  async function _pollPresence() {
    if (!_presenceWorkbookId) return;
    try {
      const res = await apiCall('get_presence', { workbook_id: _presenceWorkbookId });
      if (res?.success) {
        _lastPresenceUsers = res.users || [];
        _renderPresence(_lastPresenceUsers);
      }
    } catch(e) {}
  }

  function _refreshPresenceUI() {
    if (_presenceWorkbookId) _renderPresence(_lastPresenceUsers);
  }

  // ── Live cell value sync ──────────────────────────────────────────────────
  // Use raw fetch for the high-frequency sync calls so we don't trigger
  // apiCall()'s saveToLocalStorage() on every keystroke and poll.
  async function _liveFetch(action, body) {
    try {
      const res = await fetch(`${API_URL}?action=${action}`, {
        method:  'POST',
        headers: { 'Content-Type': 'application/json', 'Accept': 'application/json' },
        body:    JSON.stringify(body)
      });
      if (!res.ok) return null;
      return await res.json();
    } catch(e) { return null; }
  }

  // Debounced per-field push: only one timer per fieldPath. Each new keystroke
  // resets that field's timer; once it fires we send only the latest value.
  // 250 ms feels live without hammering the DB.
  function _pushCellValue(fieldPath, value) {
    if (!_presenceWorkbookId || !fieldPath) return;
    const existing = _pendingPushes.get(fieldPath);
    if (existing) clearTimeout(existing);
    const timer = setTimeout(() => {
      _pendingPushes.delete(fieldPath);
      _liveFetch('push_cell_value', {
        workbook_id: _presenceWorkbookId,
        field_path:  fieldPath,
        value:       value
      });
    }, 250);
    _pendingPushes.set(fieldPath, timer);
  }

  // Pull every remote cell update since our cursor and apply it — but never
  // clobber an input that's currently focused locally (that would steal the
  // user's in-progress typing).
  async function _pollCellValues() {
    if (!_presenceWorkbookId) return;
    try {
      const res = await _liveFetch('pull_cell_values', {
        workbook_id: _presenceWorkbookId,
        since:       _cellValuesSince
      });
      if (!res?.success) return;
      if (res.server_now) _cellValuesSince = res.server_now;
      const updates = res.updates || [];
      if (updates.length === 0) return;

      const rfqBody = document.getElementById('rfq-body');
      if (!rfqBody) return;

      updates.forEach(u => {
        const sep = u.field_path.lastIndexOf(':');
        if (sep < 0) return;
        const rowId = u.field_path.slice(0, sep);
        const idx   = parseInt(u.field_path.slice(sep + 1), 10);
        const row   = document.getElementById(rowId);
        if (!row) return;
        const inputs = row.querySelectorAll('input');
        const input  = inputs[idx];
        if (!input) return;
        // Don't overwrite the cell the user is currently typing in
        if (document.activeElement === input) return;
        // Don't overwrite if value is already in sync (avoid cursor jumps)
        if (input.value === u.value) return;
        input.value = u.value;
        // Briefly flash the cell so the change is visible
        input.style.transition = 'background-color 0.6s ease';
        input.style.backgroundColor = 'rgba(232, 117, 26, 0.18)';
        setTimeout(() => { input.style.backgroundColor = ''; }, 600);
        // Notify any listeners (e.g. totals recalc) that this input changed
        input.dispatchEvent(new Event('input', { bubbles: true }));
      });
    } catch(e) {}
  }

  /* ── Live workbook-broadcast (whole-document sync) ────────────────────
     The cell-value sync above covers RFQ keystrokes. This handles every
     OTHER field — product name, descriptions, dimensions, fees, splits,
     freight, tier prices, pricing margin, sale per, etc. — by polling a
     lightweight 'has this workbook been saved by anyone else?' endpoint
     on the existing 2s heartbeat tick. If so, pull fresh detail_json and
     apply the diff in-place without disturbing focused inputs.

     Why this exists: today, once a user makes their FIRST edit in a
     session, the 60s background refresh (_isDirty guard) silently turns
     OFF — they never see another user's changes without a hard refresh.
     This new path deliberately ignores _isDirty and uses per-input
     safety guards (focused-input + locally-dirty) instead.
  */
  async function _pollWorkbookDirty() {
    if (!_presenceWorkbookId) return;
    if (_wbBroadcastInflight) return; // skip overlapping polls
    _wbBroadcastInflight = true;
    try {
      const res = await apiCall('get_workbook_dirty', {
        workbook_id: _presenceWorkbookId,
        since:       _lastSeenUpdatedAt || ''
      });
      if (!res || !res.success) return;

      // First call baselines the cursor without firing — we don't want
      // to replay every change since the dawn of time.
      if (!_lastSeenUpdatedAt) {
        _lastSeenUpdatedAt = res.updated_at || res.server_now || '';
        return;
      }

      // No change since our last seen timestamp → nothing to do, but
      // advance to the server's clock so clock drift doesn't bite us.
      if (!res.changed) {
        // Don't move the cursor backward if server_now is older than
        // what we already have (shouldn't happen but be defensive).
        if (res.server_now && res.server_now > _lastSeenUpdatedAt) {
          _lastSeenUpdatedAt = res.server_now;
        }
        return;
      }

      // Skip self-echoes: if the save was by us, we already have the
      // value (and no surprise flash). Just advance the cursor.
      const me = (typeof getCurrentUser === 'function') ? (getCurrentUser() || '') : '';
      if (me && res.updated_by && String(res.updated_by) === String(me)) {
        _lastSeenUpdatedAt = res.updated_at;
        return;
      }

      // Remote change detected — pull fresh detail and apply.
      // get_workbook is a GET endpoint reading $_GET['id']; apiCall
      // doesn't support query params, so call fetch directly.
      const full = await _wbBroadcastGetWorkbook(_presenceWorkbookId);
      if (!full || !full.success || !full.data || !full.data.detail) return;
      _applyRemoteWorkbookDetail(full.data.detail, res.updated_by || '');
      _lastSeenUpdatedAt = res.updated_at;
    } catch (e) {
      // Network blips are fine — _lastSeenUpdatedAt isn't advanced on
      // failure, so the next successful poll re-detects the missed change.
      console.debug('[wb-broadcast] poll failed', e);
    } finally {
      _wbBroadcastInflight = false;
    }
  }

  // apiCall wrapper helper — most calls in this file POST a JSON body,
  // but get_workbook is GET with query params. Small adapter so the
  // call site reads cleanly.
  function _wbBroadcastGetWorkbook(id) {
    return fetch('api.php?action=get_workbook&id=' + encodeURIComponent(id), {
      headers: { 'Accept': 'application/json' }
    }).then(r => r.json());
  }

  /* Apply a freshly-pulled detail_json to the open workbook form.
     Surgical: only mutates individual input .value properties on
     non-focused, non-locally-dirty inputs, never re-renders the whole
     form skeleton. The orange-flash UX matches _pollCellValues so the
     two paths feel like one mechanism to the operator.

     The whitelist captures fields that map 1:1 from detail_json keys
     to DOM input IDs. Section-level reconciliation (RFQ rows,
     fee picker, shipment splits, tier rows) is delegated to the same
     fillWorkbook helpers that handle initial load — but only when the
     section's data has actually changed shape (item count, etc.), to
     avoid heavy rebuilds on every poll.
  */
  function _applyRemoteWorkbookDetail(detail, byWho) {
    if (!detail || typeof detail !== 'object') return;

    // Stash the freshly-pulled detail in our in-memory cache so any
    // section that re-renders from workbookDetail (Pricing tab, etc.)
    // reads the new values instead of stale ones.
    const key = `${currentClient}|${currentWorkbookId}`;
    workbookDetail[key] = detail;

    // ── Scalar field whitelist ─────────────────────────────────────
    // Three groups based on how the input expects its value:
    //   • scalar  — text / number / textarea — set .value
    //   • select  — <select> — set .value
    //   • checkbox — <input type=checkbox> — set .checked
    // Each entry: [detailKey, inputId]. Covers every field
    // collectWorkbookDetail writes that has a 1:1 DOM input mapping
    // (so dimensions, carton specs, shipping options, freight overrides,
    // fees, quote / invoice / art tabs, color & material text, pallet
    // notes, pricing inputs, etc.). Section-level state — rfqItems,
    // tiers, appliedFees, appliedFeeOverrides, shipmentSplits,
    // freightRates per-method — is handled below.
    const scalarFields = [
      // Workbook tab — product + dims
      ['product',                 'product-name'],
      ['desc',                    'product-desc'],
      ['productSubcategoryOther', 'product-subcategory-other'],
      ['productSubcategoryOther2','product-subcategory-other-2'],
      ['materials',               'materials'],
      ['pantone',                 'pantone-text'],
      ['cmyk',                    'cmyk'],
      ['colorNotes',              'color-notes'],
      ['qcNotes',                 'quote-qc'],
      ['dimInL',                  'dim-in-l'],
      ['dimInW',                  'dim-in-w'],
      ['dimInH',                  'dim-in-h'],
      ['dimCmL',                  'dim-cm-l'],
      ['dimCmW',                  'dim-cm-w'],
      ['dimCmH',                  'dim-cm-h'],
      ['dimWeightKg',             'dim-weight-kg'],
      ['dimWeightLbs',            'dim-weight-lbs'],
      ['dimPackaging',            'dim-packaging'],
      // Inner carton
      ['cartonInnerLIn',     'carton-inner-l-in'],
      ['cartonInnerLCm',     'carton-inner-l-cm'],
      ['cartonInnerWIn',     'carton-inner-w-in'],
      ['cartonInnerWCm',     'carton-inner-w-cm'],
      ['cartonInnerHIn',     'carton-inner-h-in'],
      ['cartonInnerHCm',     'carton-inner-h-cm'],
      ['cartonInnerWeight',  'carton-inner-weight'],
      ['cartonInnerCount',   'carton-inner-count'],
      ['cartonInnerRow',     'carton-inner-row'],
      ['cartonInnerSide',    'carton-inner-side'],
      ['cartonInnerStack',   'carton-inner-stack'],
      ['cartonInnerWall',    'carton-inner-wall'],
      // Outer carton
      ['cartonOuterLIn',     'carton-outer-l-in'],
      ['cartonOuterLCm',     'carton-outer-l-cm'],
      ['cartonOuterWIn',     'carton-outer-w-in'],
      ['cartonOuterWCm',     'carton-outer-w-cm'],
      ['cartonOuterHIn',     'carton-outer-h-in'],
      ['cartonOuterHCm',     'carton-outer-h-cm'],
      ['cartonOuterWeight',  'carton-outer-weight'],
      ['cartonOuterCount',   'carton-outer-count'],
      ['cartonOuterRow',     'carton-outer-row'],
      ['cartonOuterSide',    'carton-outer-side'],
      ['cartonOuterStack',   'carton-outer-stack'],
      ['cartonOuterWall',    'carton-outer-wall'],
      ['cartonUnitWeight',   'carton-unit-weight'],
      ['palletTotalCartons', 'pallet-total-cartons'],
      ['palletNotes',        'pallet-notes'],
      ['palletStackNotes',   'pallet-stack-notes'],
      // Shipping tab — freight overrides
      ['freightHsCode',         'freight-hs-code'],
      ['freightCostOverrideUsd','freight-cost-override'],
      ['shipLeadSlow',          'ship-lead-slow'],
      ['shipLeadFast',          'ship-lead-fast'],
      ['shipLeadAirupp',        'ship-lead-airupp'],
      ['shipLeadDirectair',     'ship-lead-directair'],
      // Weight-only override
      ['weightOnlyCaseQty', 'weight-only-qty'],
      ['weightOnlyKg',      'weight-only-kg'],
      ['weightOnlyLbs',     'weight-only-lbs'],
      // Case-only override
      ['caseOnlyProductsPer','case-only-products-per'],
      ['caseOnlyCasesOrder', 'case-only-cases-order'],
      ['caseOnlyLCm',        'case-only-l-cm'],
      ['caseOnlyLIn',        'case-only-l-in'],
      ['caseOnlyWCm',        'case-only-w-cm'],
      ['caseOnlyWIn',        'case-only-w-in'],
      ['caseOnlyHCm',        'case-only-h-cm'],
      ['caseOnlyHIn',        'case-only-h-in'],
      ['caseOnlyWeightKg',   'case-only-weight-kg'],
      ['caseOnlyWeightLbs',  'case-only-weight-lbs'],
      // Pricing tab
      ['pricingSalePer',    'ps-sale-per'],
      ['pricingMarginPct',  'ps-margin-pct'],
      // Workbook-tab fees (USD + RMB + descriptions)
      ['feeSampleDesc',  'fee-sample-desc'],
      ['feeSampleRmb',   'fee-sample-rmb'],
      ['feeSampleUsd',   'fee-sample-usd'],
      ['feeToolingDesc', 'fee-tooling-desc'],
      ['feeToolingRmb',  'fee-tooling-rmb'],
      ['feeToolingUsd',  'fee-tooling-usd'],
      ['feeDieDesc',     'fee-die-desc'],
      ['feeDieRmb',      'fee-die-rmb'],
      ['feeDieUsd',      'fee-die-usd'],
      ['feePlateDesc',   'fee-plate-desc'],
      ['feePlateRmb',    'fee-plate-rmb'],
      ['feePlateUsd',    'fee-plate-usd'],
      ['feeDesignDesc',  'fee-design-desc'],
      ['feeDesignUsd',   'fee-design-usd'],
      // Quote tab
      ['quoteDate',        'quote-date'],
      ['quoteValidUntil',  'quote-valid-until'],
      ['quoteClQty',       'quote-cl-qty'],
      ['quoteClUnitPrice', 'quote-cl-unit-price'],
      ['quoteClShipping',  'quote-cl-shipping'],
      ['quoteClNotes',     'quote-cl-notes'],
      // Invoice tab
      ['invNumber',    'inv-number'],
      ['invDate',      'inv-date'],
      ['invDueDate',   'inv-due-date'],
      ['invQty',       'inv-qty'],
      ['invUnitPrice', 'inv-unit-price'],
      ['invShipping',  'inv-shipping'],
      ['invNotes',     'inv-notes'],
      // Art tab
      ['artDueDate', 'art-due-date'],
      ['artNotes',   'art-notes'],
    ];

    // <select> dropdowns. Same .value semantics as text inputs but
    // listed separately for clarity (and to make checkbox handling
    // below explicit by exclusion).
    const selectFields = [
      ['productCategory',    'product-category'],
      ['productCategory2',   'product-category-2'],
      ['productSubcategory', 'product-subcategory'],
      ['productSubcategory2','product-subcategory-2'],
      ['freightMode',        'freight-mode'],
      ['invStatus',          'inv-status'],
      ['invMethod',          'inv-method'],
      ['artStatus',          'art-status'],
    ];

    // <input type=checkbox> — .checked instead of .value, and we
    // dispatch 'change' (not 'input') so the existing onchange
    // handlers fire (palletManualToggle, weight-only-toggle,
    // case-only-toggle, etc. — each of these does grayout / cascade
    // logic the broadcast needs to trigger).
    const checkboxFields = [
      ['palletManualMode',     'pallet-manual'],
      ['palletDivider',        'pallet-divider'],
      ['productDimsLocked',    'product-dims-lock'],
      ['freightCostOverrideOn','freight-cost-override-toggle'],
      ['weightOnlyOverride',   'weight-only-override'],
      ['caseOnlyOverride',     'case-only-override'],
      ['materialSecondEnabled','mat2-toggle'],
    ];

    let scalarChanges = 0;
    // Shared per-element apply helper — encapsulates the focus + dirty
    // guards + the orange flash so every field type uses the same path.
    const applyValueChange = (el, doSet) => {
      // SAFETY 1 — focused-input guard. Never overwrite an input the
      // operator is currently typing in / interacting with.
      if (document.activeElement === el) return false;
      // SAFETY 2 — local-dirty guard. Skip inputs the operator has
      // edited since their last successful autosave (the 400ms window).
      if (el.dataset && el.dataset.localDirty === '1') return false;
      const changed = doSet();
      if (!changed) return false;
      // Orange flash so the operator sees what just changed.
      try {
        el.style.transition = 'background-color 0.6s ease';
        el.style.backgroundColor = 'rgba(232, 117, 26, 0.18)';
        setTimeout(() => { el.style.backgroundColor = ''; }, 600);
      } catch(_) {}
      return true;
    };

    scalarFields.concat(selectFields).forEach(([k, id]) => {
      const newVal = detail[k];
      if (newVal === undefined || newVal === null) return;
      const el = document.getElementById(id);
      if (!el) return;
      const next = String(newVal);
      const changed = applyValueChange(el, () => {
        const cur = String(el.value == null ? '' : el.value);
        if (cur === next) return false;
        el.value = next;
        return true;
      });
      if (!changed) return;
      scalarChanges++;
      // input event for inputs/textareas, change for selects — most
      // listeners bind to one or the other, so fire both to be safe.
      try { el.dispatchEvent(new Event('input', { bubbles: true })); } catch(_) {}
      try { el.dispatchEvent(new Event('change', { bubbles: true })); } catch(_) {}
    });

    checkboxFields.forEach(([k, id]) => {
      const newVal = detail[k];
      if (newVal === undefined || newVal === null) return;
      const el = document.getElementById(id);
      if (!el) return;
      const next = !!newVal;
      const changed = applyValueChange(el, () => {
        if (!!el.checked === next) return false;
        el.checked = next;
        return true;
      });
      if (!changed) return;
      scalarChanges++;
      // Checkboxes fire change, not input — and many have onchange
      // wired to a toggle handler that cascades visual state.
      try { el.dispatchEvent(new Event('change', { bubbles: true })); } catch(_) {}
    });

    // ── Per-method freight rates ───────────────────────────────────
    // freightMethodRates is a JS object (not a single input); the four
    // editable rate inputs feed it via onFreightRateInput. On a remote
    // change we need to update both the object AND the visible inputs,
    // then re-paint dependent UI (rate chip, comparison table, etc).
    if (detail.freightRates && typeof detail.freightRates === 'object'
        && typeof freightMethodRates !== 'undefined') {
      let ratesChanged = false;
      ['slow','fast','airupp','directair'].forEach(m => {
        const r = parseFloat(detail.freightRates[m]);
        if (!isFinite(r) || r < 0) return;
        if (freightMethodRates[m] !== r) {
          freightMethodRates[m] = r;
          ratesChanged = true;
        }
        // Mirror to the matching input (if not focused / locally dirty).
        const rateEl = document.getElementById('freight-rate-input-' + m);
        if (rateEl) {
          applyValueChange(rateEl, () => {
            const cur = parseFloat(rateEl.value);
            if (cur === r) return false;
            rateEl.value = r.toFixed(2);
            return true;
          });
        }
      });
      if (ratesChanged && typeof calcFreight === 'function') {
        try { calcFreight(); } catch(_) {}
      }
    }

    // ── Section-level updates ──────────────────────────────────────
    // For sections that contain arrays of rows (fees, splits, tiers),
    // the simplest correct path is to re-run the same recalc + render
    // helpers fillWorkbook uses on load — they're already idempotent.
    // We only call them when the section's data has actually changed,
    // and we suppress any cosmetic 'flash' since the change is
    // structural (rows added/removed), not a single value.

    // ── Pricing tab Additional Fees ────────────────────────────────
    // Three pieces of state to keep in sync:
    //   1. _extraFeeRows  — custom rows from the Workbook-tab fees
    //      section (Sample/Tooling/Die/Plate/Design are scalar inputs
    //      handled above; extras are dynamic and need renderExtraFeeRows
    //      to repaint).
    //   2. _appliedFees   — Set of fee ids ticked on the Pricing tab.
    //   3. _appliedFeeOverrides — per-fee USD overrides typed on the
    //      Pricing tab.
    // After updating the in-memory state we explicitly call
    // renderPricingFeesCard() so the fees card body refreshes (it's
    // guarded against re-render while an override input is focused —
    // safe to call any time). The pricing-tab full re-render below
    // also triggers it, but calling explicitly ensures the card
    // reflects the broadcast even on tabs other than Pricing.
    let feesStructureChanged = false;
    let feesValueChanged     = false;

    if (Array.isArray(detail.extraFeeRows)) {
      // Reconstruct the local extras array. Cheap to do unconditionally
      // since the renderer is idempotent — but only re-render when the
      // shape actually changed to skip unnecessary DOM churn.
      const before = JSON.stringify(_extraFeeRows.map(r => ({type:r.type, desc:r.desc, rmb:r.rmb, usd:r.usd})));
      _extraFeeRows = [];
      _extraFeeCounter = 0;
      detail.extraFeeRows.forEach(r => {
        _extraFeeCounter++;
        _extraFeeRows.push({ id: _extraFeeCounter, type: r.type || '', desc: r.desc || '', rmb: r.rmb || 0, usd: r.usd || 0 });
      });
      const after = JSON.stringify(_extraFeeRows.map(r => ({type:r.type, desc:r.desc, rmb:r.rmb, usd:r.usd})));
      if (before !== after) {
        feesStructureChanged = true;
        if (typeof renderExtraFeeRows === 'function') {
          try { renderExtraFeeRows(); } catch(_) {}
        }
      }
    }

    if (Array.isArray(detail.appliedFees)) {
      const incoming = new Set(detail.appliedFees);
      // Replace the local Set wholesale if anything differs.
      let changed = (incoming.size !== _appliedFees.size);
      if (!changed) {
        for (const id of incoming) { if (!_appliedFees.has(id)) { changed = true; break; } }
      }
      if (changed) { _appliedFees = incoming; feesStructureChanged = true; }
    }

    if (detail.appliedFeeOverrides && typeof detail.appliedFeeOverrides === 'object') {
      const before = JSON.stringify(_appliedFeeOverrides);
      _appliedFeeOverrides = Object.create(null);
      Object.keys(detail.appliedFeeOverrides).forEach(k => {
        const v = parseFloat(detail.appliedFeeOverrides[k]);
        if (isFinite(v) && v >= 0) _appliedFeeOverrides[k] = v;
      });
      const after = JSON.stringify(_appliedFeeOverrides);
      if (before !== after) feesValueChanged = true;
    }

    // Always re-render the fees card if any fee state changed (Pricing
    // tab visibility doesn't matter — the body needs to be up to date
    // for when the operator switches tabs OR opens the Notify modal).
    if (feesStructureChanged || feesValueChanged) {
      if (typeof renderPricingFeesCard === 'function') {
        try { renderPricingFeesCard(); } catch(_) {}
      }
      // Brief accent flash on the fees card so the operator sees that
      // SOMETHING in this section changed — per-row flash isn't
      // possible since the whole body is re-rendered in one shot.
      try {
        const card = document.getElementById('pricing-fees-card');
        if (card) {
          const orig = card.style.boxShadow || '';
          card.style.transition = 'box-shadow 0.4s ease, border-color 0.4s ease';
          card.style.boxShadow = '0 0 0 2px rgba(232, 117, 26, 0.45)';
          setTimeout(() => { card.style.boxShadow = orig; }, 900);
        }
      } catch(_) {}
    }

    // Shipment splits — same wholesale replace, then re-render.
    if (Array.isArray(detail.shipmentSplits)) {
      _shipmentSplits = [];
      _splitCounter = 0;
      detail.shipmentSplits.forEach(r => {
        _splitCounter++;
        _shipmentSplits.push({ id: _splitCounter, method: r.method || 'slow', qty: r.qty || '' });
      });
      if (typeof renderShipmentSplits === 'function') renderShipmentSplits();
    }

    // Trigger downstream renders so any open tab reflects the new
    // values. These are all idempotent re-renders that read from the
    // DOM + workbookDetail; they don't touch focused inputs.
    try {
      if (scalarChanges > 0 && typeof recalcRfqTotals === 'function') recalcRfqTotals();
      if (typeof _refreshPricingForSplits === 'function') _refreshPricingForSplits();
      else if (typeof renderPricingTab === 'function') renderPricingTab();
      if (typeof _updateAllSectionSummaries === 'function') _updateAllSectionSummaries();
    } catch (e) { console.debug('[wb-broadcast] downstream render', e); }

    // Tiny toast so the operator knows a change came in (not just
    // mysterious orange flashes). Fires on ANY real change: scalar
    // field, fees structure (add/remove/toggle), fee override value,
    // or shipment splits.
    const splitsChanged = Array.isArray(detail.shipmentSplits); // any incoming splits payload = potential change
    if (scalarChanges > 0 || feesStructureChanged || feesValueChanged || splitsChanged) {
      _showWbBroadcastToast(byWho || 'Someone');
    }
  }

  function _showWbBroadcastToast(who) {
    let toast = document.getElementById('wb-broadcast-toast');
    if (!toast) {
      toast = document.createElement('div');
      toast.id = 'wb-broadcast-toast';
      toast.style.cssText = 'position:fixed; bottom:24px; right:24px; background:#1a1d2e; color:#fff; padding:10px 16px; border-radius:8px; font-size:13px; font-weight:600; box-shadow:0 4px 16px rgba(0,0,0,0.25); opacity:0; transform:translateY(8px); transition:opacity 0.18s, transform 0.18s; z-index:1200; max-width:280px;';
      document.body.appendChild(toast);
    }
    toast.textContent = `${who} updated this workbook`;
    requestAnimationFrame(() => {
      toast.style.opacity = '1';
      toast.style.transform = 'translateY(0)';
    });
    if (toast._hideTimer) clearTimeout(toast._hideTimer);
    toast._hideTimer = setTimeout(() => {
      toast.style.opacity = '0';
      toast.style.transform = 'translateY(8px)';
    }, 2600);
  }

  function _clearPresenceIndicators() {
    document.querySelectorAll('[data-presence]').forEach(el => {
      el.style.outline = '';
      delete el.dataset.presence;
    });
    document.querySelectorAll('.presence-name-tag').forEach(el => el.remove());
    const rfqBar = document.getElementById('rfq-presence-bar');
    if (rfqBar) rfqBar.innerHTML = '';
    document.querySelectorAll('.section-presence-bar').forEach(b => { b.innerHTML = ''; });
    const banner = document.getElementById('wb-presence-banner');
    if (banner) { banner.innerHTML = ''; banner.style.display = 'none'; }
  }

  // Tiny helper: avatar chip for one user, used by the section bars and
  // the RFQ bar so styling stays consistent. The RFQ bar shows the
  // full name pill (legacy look); other section bars use the compact
  // initials variant to keep small headers uncluttered.
  function _presenceChip(u, opts) {
    const initials = (typeof _watcherInitials === 'function') ? _watcherInitials(u.display_name) : (u.display_name || '?').charAt(0);
    const compact = opts && opts.compact;
    if (compact) {
      return `<span class="presence-chip-mini" title="${(u.display_name || '').replace(/"/g,'&quot;')} is editing"
              style="background:${u.color}; color:#fff;">${initials}</span>`;
    }
    return `<span style="display:inline-flex;align-items:center;gap:5px;
                 background:${u.color}22;border:1px solid ${u.color}88;
                 border-radius:20px;padding:3px 10px 3px 7px;
                 font-size:11px;font-weight:700;color:${u.color};white-space:nowrap;">
      <span style="width:7px;height:7px;border-radius:50%;background:${u.color};
                   display:inline-block;
                   animation:presence-pulse 2s ease-in-out infinite;"></span>
      ${u.display_name}
    </span>`;
  }

  function _renderPresence(users) {
    _clearPresenceIndicators();
    if (!Array.isArray(users)) users = [];

    // Only render presence UI when we're actually on a workbook detail
    // view — the banner doesn't make sense from the home page or list views.
    const onWorkbook = !!document.getElementById('view-workbook')?.classList.contains('active');
    if (!onWorkbook) return;

    // Prepend the current viewer as a "You" entry so the banner always
    // shows at least one name (otherwise the user thinks the feature is
    // broken when they're testing alone). Self entry uses the live local
    // _myFocusedField and _myPresenceColor so the section chip + the
    // banner pill both update instantly when they click into a section,
    // without waiting for the next 2 s poll.
    const selfDisplay = (window.MS_SESSION && window.MS_SESSION.name) ? window.MS_SESSION.name : 'You';
    const selfId      = (window.MS_SESSION && window.MS_SESSION.id) || 0;
    const selfEntry = {
      display_name:  selfDisplay,
      color:         _myPresenceColor,
      focused_field: _myFocusedField || '',
      is_self:       true,
      _id:           selfId,
    };
    // Combined list — self first so "You" appears at the front of the banner
    const all = [selfEntry, ...users];

    // ── Top "X is editing" banner ───────────────────────────────────────
    // Names are colored per-user so they line up with their highlights.
    // Renders "You", "You and Parker", "You, Parker and Jackson" etc.
    const banner = document.getElementById('wb-presence-banner');
    if (banner) {
      const labelFor = u => u.is_self
        ? `<span class="wb-presence-name" style="color:${u.color}; border-bottom: 2px solid ${u.color};" title="${selfDisplay}">You</span>`
        : `<span class="wb-presence-name" style="color:${u.color}; border-bottom: 2px solid ${u.color};">${u.display_name}</span>`;
      const parts = all.map(labelFor);
      // When only "You" are editing — alone — swap the bland "is
      // editing" for "is smart" as a small morale boost. Other single-
      // user / multi-user cases stay on the normal verbiage.
      const soloSelf = all.length === 1 && all[0].is_self;
      const verb  = all.length === 1 ? 'is editing' : 'are editing';
      let listHtml;
      if (parts.length === 1)      listHtml = `${parts[0]} ${soloSelf ? 'is smart' : verb}`;
      else if (parts.length === 2) listHtml = `${parts[0]} and ${parts[1]} ${verb}`;
      else                          listHtml = `${parts.slice(0, -1).join(', ')} and ${parts[parts.length - 1]} ${verb}`;

      const wherePills = all.map(u => {
        const p = _parsePresenceField(u.focused_field);
        if (!p.section) return '';
        const label = _SECTION_LABELS[p.section] || p.section;
        const who = u.is_self ? 'You' : u.display_name.split(/\s+/)[0];
        return `<span class="wb-presence-where-pill" style="border-color:${u.color}66; color:${u.color};">${who} → ${label}</span>`;
      }).filter(Boolean).join('');

      banner.innerHTML =
        `<span class="wb-presence-pulse" style="background:${_myPresenceColor};"></span>` +
        `<span class="wb-presence-text">${listHtml}</span>` +
        `<span class="wb-presence-where">${wherePills}</span>`;
      banner.style.display = '';
    }

    // ── Per-section bars + RFQ legacy bar ───────────────────────────────
    // Group everyone (including self) by their currently-focused section.
    const bySection = new Map();
    all.forEach(u => {
      const p = _parsePresenceField(u.focused_field);
      if (!p.section) return;
      if (!bySection.has(p.section)) bySection.set(p.section, []);
      bySection.get(p.section).push(u);
    });

    bySection.forEach((list, sec) => {
      if (sec === 'rfq') {
        // Keep the original full-pill style on the RFQ bar (legacy look)
        const rfqBar = document.getElementById('rfq-presence-bar');
        if (rfqBar) rfqBar.innerHTML = list.map(u => _presenceChip(u, { compact: false })).join('');
      }
      // Also populate the generic section bar (covers RFQ if it has the
      // newer slot, plus all other sections). Compact initials variant.
      const slots = document.querySelectorAll(`.section-presence-bar[data-section-bar="${sec}"]`);
      slots.forEach(slot => {
        slot.innerHTML = list.map(u => _presenceChip(u, { compact: true })).join('');
      });
    });

    // ── Cell highlights (Google Sheets style) — RFQ only, OTHER USERS only.
    // We deliberately don't outline our own cell — that's what the native
    // browser focus ring is for, and a colored outline on top of it looks
    // doubled-up.
    users.forEach(u => {
      const p = _parsePresenceField(u.focused_field);
      if (!p.cellPath) return;
      const sep   = p.cellPath.lastIndexOf(':');
      if (sep < 0) return;
      const rowId = p.cellPath.slice(0, sep);
      const idx   = parseInt(p.cellPath.slice(sep + 1), 10);
      const row   = document.getElementById(rowId);
      if (!row) return;
      const input = row.querySelectorAll('input')[idx];
      if (!input) return;

      input.style.outline      = `3px solid ${u.color}`;
      input.style.outlineOffset = '-1px';
      input.dataset.presence   = '1';

      const rect = input.getBoundingClientRect();
      if (rect.width === 0) return;
      const headerEl  = document.querySelector('.app-header');
      const headerBottom = headerEl ? headerEl.getBoundingClientRect().bottom : 64;
      const safeTop = headerBottom + 6;
      if (rect.top < safeTop) return;
      if (rect.bottom > window.innerHeight) return;
      const tagTop = Math.min(rect.bottom + 3, window.innerHeight - 24);
      const tag = document.createElement('div');
      tag.className   = 'presence-name-tag';
      tag.textContent = u.display_name;
      tag.style.cssText = `
        background:${u.color};
        position:fixed;
        top:${tagTop}px;
        left:${rect.left}px;
        z-index:9999;
        pointer-events:none;
      `;
      document.body.appendChild(tag);
    });
  }

  // Section name → friendly label, used by the top "X is editing" banner
  // and per-section presence bars. Keep keys identical to the data-section
  // attributes on each .section-card in the workbook view.
  const _SECTION_LABELS = {
    overview:           'Product Overview',
    rfq:                'RFQ',
    tiers:              'Tiered Pricing',
    fees:               'Additional Fees',
    dimensions:         'Dimensions & Carton',
    'pricing-summary':  'Delivered Cost',
    'client-quote':     'Client Quote',
    quote:              'Quote for Client',
    art:                'Art',
    invoice:            'Office Invoice',
  };

  // Parse "section|cellPath" or "section" or "" into { section, cellPath }.
  // Older clients (or RFQ-only state) wrote bare cellPaths without a
  // section prefix — those still parse correctly with section = null.
  function _parsePresenceField(field) {
    if (!field) return { section: null, cellPath: null };
    const pipe = field.indexOf('|');
    if (pipe < 0) {
      // No pipe: either just a section name, or legacy bare cellPath
      return /^[a-z][a-z0-9-]*$/i.test(field)
        ? { section: field, cellPath: null }
        : { section: null,  cellPath: field };
    }
    return { section: field.slice(0, pipe) || null, cellPath: field.slice(pipe + 1) || null };
  }

  // Look up the data-section ancestor of a focused element. Used by the
  // generic workbook focus tracker so any input in any section reports
  // its section to other viewers.
  function _sectionFor(el) {
    const sec = el && el.closest && el.closest('[data-section]');
    return sec ? sec.getAttribute('data-section') : null;
  }

  // Attach focus tracking. The RFQ table keeps its cell-precise format
  // (so the cell-highlight feature still works); every OTHER input in
  // the workbook view reports just the section it lives in. Both feed
  // into _myFocusedField as "<section>|<cellPath?>".
  // ════════════════════════════════════════════════════════════════════
  // Rich-text editor — markdown formatting toolbar + AI text actions
  //
  // Wraps any [data-rich] textarea with a small toolbar (Bold, Italic,
  // bullet/numbered list, ✨ AI). Format buttons mutate the textarea
  // value with markdown-style markers so the underlying storage stays
  // plain text — collectWorkbookDetail / autosave / fillWorkbook all
  // continue to work without changes. The AI button opens a dropdown
  // of one-click actions that POST to api.php → ai_text_action,
  // which proxies to Anthropic Claude (configured at the top of api.php).
  // ════════════════════════════════════════════════════════════════════
  // Init or re-sync every [data-rich] textarea. Idempotent — first
  // call wraps the textarea in a contenteditable surface; subsequent
  // calls re-sync the surface from textarea.value (which fillWorkbook
  // mutates programmatically when switching workbooks).
  function initRichEditors() {
    document.querySelectorAll('textarea[data-rich]').forEach(ta => {
      if (!ta._msRichInit) _msInitOneRichEditor(ta);
      else                 _msSyncFromTextarea(ta);
    });
  }

  // Convert legacy markdown-marker content (left over from before the
  // switch to true WYSIWYG) into HTML the contenteditable can render.
  // If the input already looks like HTML (contains a tag), leave it
  // alone — it round-trips cleanly through innerHTML.
  function _msMarkdownToHtml(text) {
    if (!text) return '';
    // Already HTML-ish? Use as-is.
    if (/<[a-z][^>]*>/i.test(text)) return text;
    let html = text
      // Escape any stray <, > before applying transforms so user-typed
      // angle brackets don't get treated as tags.
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      // Bold + italic: order matters — process bold first so the **
      // pairs aren't gobbled by the italic single-* matcher.
      .replace(/\*\*([^*]+?)\*\*/g, '<strong>$1</strong>')
      .replace(/\*([^*]+?)\*/g, '<em>$1</em>')
      .replace(/~~([^~]+?)~~/g, '<del>$1</del>')
      // Heading "## Foo" at line start
      .replace(/(^|\n)## (.+?)(?=\n|$)/g, '$1<h3>$2</h3>')
      // List items: convert "- foo" runs into <ul><li>foo</li></ul>,
      // "1. foo" runs into <ol><li>foo</li></ol>. Keep it crude — only
      // groups of consecutive list lines.
      .replace(/(^|\n)((?:- .+(?:\n|$))+)/g, (_m, lead, block) => {
        const items = block.trim().split('\n').map(l => `<li>${l.replace(/^- /, '')}</li>`).join('');
        return `${lead}<ul>${items}</ul>`;
      })
      .replace(/(^|\n)((?:\d+\. .+(?:\n|$))+)/g, (_m, lead, block) => {
        const items = block.trim().split('\n').map(l => `<li>${l.replace(/^\d+\. /, '')}</li>`).join('');
        return `${lead}<ol>${items}</ol>`;
      })
      // Plain newlines → <br> for line breaks inside paragraphs
      .replace(/\n/g, '<br>');
    return html;
  }

  // Sync textarea.value (the source of truth for save/load) into the
  // contenteditable's innerHTML. Called on init AND whenever
  // fillWorkbook updates a textarea programmatically.
  function _msSyncFromTextarea(ta) {
    const editor = ta._msRichEditor;
    if (!editor) return;
    const html = _msMarkdownToHtml(ta.value || '');
    if (editor.innerHTML !== html) editor.innerHTML = html;
  }

  function _msInitOneRichEditor(textarea) {
    if (!textarea || textarea._msRichInit) return;
    textarea._msRichInit = true;
    const wrap = document.createElement('div');
    wrap.className = 'ms-rich-editor';
    textarea.parentNode.insertBefore(wrap, textarea);
    const toolbar = document.createElement('div');
    toolbar.className = 'ms-rich-toolbar';
    toolbar.innerHTML = `
      <button type="button" class="ms-rich-btn" data-cmd="bold" title="Bold (⌘B)"><strong>B</strong></button>
      <button type="button" class="ms-rich-btn" data-cmd="italic" title="Italic (⌘I)"><em>I</em></button>
      <button type="button" class="ms-rich-btn" data-cmd="underline" title="Underline (⌘U)"><span style="text-decoration:underline;">U</span></button>
      <button type="button" class="ms-rich-btn" data-cmd="strikethrough" title="Strikethrough"><span style="text-decoration:line-through;">S</span></button>
      <span class="ms-rich-divider"></span>
      <button type="button" class="ms-rich-btn" data-cmd="ul" title="Bulleted list" aria-label="Bulleted list">
        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="8" y1="6" x2="21" y2="6"/><line x1="8" y1="12" x2="21" y2="12"/><line x1="8" y1="18" x2="21" y2="18"/><circle cx="3.5" cy="6" r="1.2" fill="currentColor"/><circle cx="3.5" cy="12" r="1.2" fill="currentColor"/><circle cx="3.5" cy="18" r="1.2" fill="currentColor"/></svg>
      </button>
      <button type="button" class="ms-rich-btn" data-cmd="ol" title="Numbered list" aria-label="Numbered list">
        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="10" y1="6" x2="21" y2="6"/><line x1="10" y1="12" x2="21" y2="12"/><line x1="10" y1="18" x2="21" y2="18"/><path d="M4 6h1v-2.5"/><path d="M4 10h2.5c0 -0.5 -0.5 -1 -1.25 -1s-1.25 0.5 -1.25 1c0 1.5 2.5 1.5 2.5 3h-2.5"/><path d="M4 14.5c0.5 -0.5 1 -0.5 1.5 0c0.5 0.5 0.5 1.5 0 2c0.5 0.5 0.5 1.5 0 2c-0.5 0.5 -1 0.5 -1.5 0"/></svg>
      </button>
      <span class="ms-rich-divider"></span>
      <button type="button" class="ms-rich-btn" data-cmd="heading" title="Section heading">H</button>
      <button type="button" class="ms-rich-btn ms-rich-btn--ai" data-cmd="ai" title="AI text actions">AI</button>
      <div class="ms-rich-ai-menu">
        <button type="button" class="ms-rich-ai-item" data-ai="improve"><span class="ai-icon">✨</span><span>Improve writing</span></button>
        <button type="button" class="ms-rich-ai-item" data-ai="shorter"><span class="ai-icon">✂️</span><span>Make shorter</span></button>
        <button type="button" class="ms-rich-ai-item" data-ai="expand"><span class="ai-icon">📖</span><span>Expand with detail</span></button>
        <button type="button" class="ms-rich-ai-item" data-ai="fix_grammar"><span class="ai-icon">✓</span><span>Fix grammar</span></button>
        <button type="button" class="ms-rich-ai-item" data-ai="professional"><span class="ai-icon">👔</span><span>Make professional</span></button>
        <button type="button" class="ms-rich-ai-item" data-ai="bullet_summary"><span class="ai-icon">≡</span><span>Summarize as bullets</span></button>
        <button type="button" class="ms-rich-ai-item" data-ai="custom"><span class="ai-icon">✏️</span><span>Custom prompt…</span></button>
      </div>
    `;

    // Build the contenteditable surface — this is what the operator
    // sees and types into. Bold/italic/etc. render inline as styled
    // HTML, not as raw markdown markers like the old textarea showed.
    const editor = document.createElement('div');
    editor.className  = 'ms-rich-content';
    editor.contentEditable = 'true';
    editor.spellcheck = true;
    editor.setAttribute('role', 'textbox');
    editor.setAttribute('aria-multiline', 'true');
    if (textarea.placeholder) editor.setAttribute('data-placeholder', textarea.placeholder);

    wrap.appendChild(toolbar);
    wrap.appendChild(editor);
    // Move the original textarea inside the wrap and hide it. It stays
    // the source of truth for save/load — collectWorkbookDetail reads
    // textarea.value, autosave watchers fire on its input event.
    textarea.style.cssText += ';display:none;';
    wrap.appendChild(textarea);

    // Initial population: convert any legacy markdown markers into HTML
    // so old saves render as actual bold/italic instead of literal **'s.
    editor.innerHTML = _msMarkdownToHtml(textarea.value || '');
    textarea._msRichEditor = editor;

    // On every keystroke / format change, push the rendered HTML back
    // into the hidden textarea + fire an input event so existing
    // autosave + presence-broadcast listeners pick up the change.
    const sync = () => {
      const html = editor.innerHTML;
      // Treat empty editor as truly empty so collectWorkbookDetail
      // doesn't store stray "<br>" artifacts the browser inserts.
      const empty = html.replace(/<br\s*\/?>/gi, '').replace(/\s+/g, '') === '';
      textarea.value = empty ? '' : html;
      textarea.dispatchEvent(new Event('input', { bubbles: true }));
    };
    editor.addEventListener('input', sync);
    editor.addEventListener('blur',  sync);

    // Paste handler: strip foreign formatting so pasting from Word /
    // websites doesn't dump weird styles into the editor. Plain text
    // wins; the operator can apply our format buttons after.
    editor.addEventListener('paste', e => {
      e.preventDefault();
      const text = (e.clipboardData || window.clipboardData)?.getData('text/plain') || '';
      document.execCommand('insertText', false, text);
    });

    const aiMenu = toolbar.querySelector('.ms-rich-ai-menu');
    toolbar.querySelectorAll('[data-cmd]').forEach(btn => {
      // mousedown (not click) so the editor's selection doesn't get
      // wiped before execCommand runs — clicking a button steals
      // focus and clears Selection ranges.
      btn.addEventListener('mousedown', e => { e.preventDefault(); });
      btn.addEventListener('click', e => {
        e.preventDefault(); e.stopPropagation();
        const cmd = btn.getAttribute('data-cmd');
        if (cmd === 'ai') {
          document.querySelectorAll('.ms-rich-ai-menu.open').forEach(m => { if (m !== aiMenu) m.classList.remove('open'); });
          aiMenu.classList.toggle('open');
          return;
        }
        _msApplyRichFormat(editor, cmd);
        sync();
      });
    });
    toolbar.querySelectorAll('[data-ai]').forEach(btn => {
      btn.addEventListener('click', async e => {
        e.preventDefault(); e.stopPropagation();
        aiMenu.classList.remove('open');
        await _msRunAiAction(editor, textarea, btn.getAttribute('data-ai'));
      });
    });
    document.addEventListener('click', e => {
      if (!toolbar.contains(e.target)) aiMenu.classList.remove('open');
    });
    // ⌘B / ⌘I / ⌘U: contenteditable handles these natively, but we
    // re-route through our handler to make sure sync() fires.
    editor.addEventListener('keydown', e => {
      if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 'b') { e.preventDefault(); _msApplyRichFormat(editor, 'bold');      sync(); }
      if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 'i') { e.preventDefault(); _msApplyRichFormat(editor, 'italic');    sync(); }
      if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 'u') { e.preventDefault(); _msApplyRichFormat(editor, 'underline'); sync(); }
    });
  }

  // Apply a format to the current selection inside the contenteditable.
  // Uses document.execCommand — deprecated in spec but still works in
  // every modern browser and is the only practical way to get
  // bold/italic/underline toggling without writing a full Range API
  // implementation. Editor must be focused first or execCommand no-ops.
  function _msApplyRichFormat(editor, cmd) {
    editor.focus();
    if (cmd === 'bold')          document.execCommand('bold');
    else if (cmd === 'italic')   document.execCommand('italic');
    else if (cmd === 'underline')document.execCommand('underline');
    else if (cmd === 'strikethrough') document.execCommand('strikeThrough');
    else if (cmd === 'ul')       document.execCommand('insertUnorderedList');
    else if (cmd === 'ol')       document.execCommand('insertOrderedList');
    else if (cmd === 'heading') {
      // formatBlock toggles a paragraph block to the given tag. Cycle
      // between H3 and P so clicking again removes the heading.
      const sel = document.getSelection();
      const node = sel?.anchorNode;
      const inHeading = node && (node.nodeType === 1 ? node : node.parentElement)?.closest('h1,h2,h3,h4,h5,h6');
      document.execCommand('formatBlock', false, inHeading ? 'p' : 'h3');
    }
  }

  // AI action: send the editor's plain-text content to the backend,
  // replace the editor with the response. Sends innerText (not HTML)
  // so Claude sees clean prose instead of tag soup; response comes
  // back as plain text and we drop it back in as innerText to preserve
  // line breaks. Operator can re-apply formatting after.
  async function _msRunAiAction(editor, textarea, action) {
    const text = (editor.innerText || '').trim();
    let prompt = '';
    if (action === 'custom') {
      prompt = window.prompt('What would you like the AI to do with this text?', '');
      if (!prompt) return;
    } else if (!text) {
      alert('Type something in this field first — AI needs context to work with.');
      return;
    }
    const wrap = editor.closest('.ms-rich-editor');
    const toolbar = wrap?.querySelector('.ms-rich-toolbar');
    let busy;
    if (toolbar) {
      busy = document.createElement('span');
      busy.className = 'ms-rich-ai-busy';
      busy.innerHTML = '<span class="dot"></span>Thinking…';
      toolbar.appendChild(busy);
    }
    editor.contentEditable = 'false';
    try {
      const r = await apiCall('ai_text_action', { text, action, prompt });
      if (!r || !r.success) {
        alert((r && r.error) || 'AI request failed.');
        return;
      }
      if (typeof r.text === 'string') {
        // Convert any markdown the model returned into HTML, then drop
        // it into the editor. innerText would lose paragraph breaks.
        editor.innerHTML = _msMarkdownToHtml(r.text);
        textarea.value = editor.innerHTML;
        textarea.dispatchEvent(new Event('input', { bubbles: true }));
        if (typeof _msToast === 'function') _msToast('AI updated this field.', 'success');
      }
    } catch (e) {
      alert('AI request failed: ' + (e && e.message ? e.message : 'unknown error'));
    } finally {
      editor.contentEditable = 'true';
      busy?.remove();
    }
  }

  function _initPresenceFocusTracking() {
    const rfqBody = document.getElementById('rfq-body');
    if (rfqBody && !rfqBody._presenceReady) {
      rfqBody._presenceReady = true;

      rfqBody.addEventListener('focusin', e => {
        if (e.target.tagName !== 'INPUT') return;
        const row = e.target.closest('tr[id]');
        if (!row) return;
        const inputs = [...row.querySelectorAll('input')];
        const idx    = inputs.indexOf(e.target);
        if (idx < 0) return;
        _myFocusedField = `rfq|${row.id}:${idx}`;
        _sendPresenceHeartbeat();
      });

      rfqBody.addEventListener('focusout', () => {
        setTimeout(() => {
          if (!rfqBody.contains(document.activeElement)) {
            // Only clear if focus didn't land in another tracked section
            const newSec = _sectionFor(document.activeElement);
            if (!newSec || newSec === 'rfq') {
              _myFocusedField = '';
              _sendPresenceHeartbeat();
            }
          }
        }, 120);
      });

      // Live cell-value broadcast (RFQ-specific): every keystroke
      // (debounced inside _pushCellValue) sends the field's current value
      // so other viewers see it within ~250 ms + their next 2 s poll.
      rfqBody.addEventListener('input', e => {
        if (!e.isTrusted) return;
        if (typeof _filling !== 'undefined' && _filling) return;
        if (e.target.tagName !== 'INPUT') return;
        if (e.target.type === 'checkbox') return;
        const row = e.target.closest('tr[id]');
        if (!row) return;
        const inputs = [...row.querySelectorAll('input')];
        const idx    = inputs.indexOf(e.target);
        if (idx < 0) return;
        _pushCellValue(`${row.id}:${idx}`, e.target.value);
      });
    }

    // Generic workbook-wide section tracker. Fires on focus into any
    // input/textarea/select that's inside a [data-section] container —
    // covers Product Overview, Additional Fees, Dimensions, etc. The
    // RFQ table is its own [data-section="rfq"] so the listener fires
    // there too, but the more-specific RFQ handler above runs first
    // (event delegation order) and writes the cell-precise format.
    const wbView = document.getElementById('view-workbook');
    if (wbView && !wbView._presenceReady) {
      wbView._presenceReady = true;
      wbView.addEventListener('focusin', e => {
        const t = e.target;
        if (!t || (t.tagName !== 'INPUT' && t.tagName !== 'TEXTAREA' && t.tagName !== 'SELECT')) return;
        // Don't downgrade an RFQ cell focus to section-only — the more-
        // specific RFQ handler above already set the field correctly.
        if (_myFocusedField && _myFocusedField.indexOf('rfq|') === 0 && t.closest('#rfq-body')) return;
        const section = _sectionFor(t);
        if (!section) return;
        if (section === 'rfq' && t.closest('#rfq-body')) return; // RFQ handles itself
        const newField = section;
        if (newField !== _myFocusedField) {
          _myFocusedField = newField;
          _sendPresenceHeartbeat();
        }
      });
      wbView.addEventListener('focusout', () => {
        setTimeout(() => {
          const a = document.activeElement;
          // If focus went to nothing tracked, clear our presence
          if (!a || !wbView.contains(a)) {
            if (_myFocusedField !== '') {
              _myFocusedField = '';
              _sendPresenceHeartbeat();
            }
            return;
          }
          if (a.tagName !== 'INPUT' && a.tagName !== 'TEXTAREA' && a.tagName !== 'SELECT') {
            if (_myFocusedField !== '') {
              _myFocusedField = '';
              _sendPresenceHeartbeat();
            }
          }
        }, 120);
      });
    }
  }

  // Clear presence immediately when the tab is closed / navigated away from
  window.addEventListener('beforeunload', () => {
    if (_presenceWorkbookId) {
      try {
        navigator.sendBeacon(
          'api.php?action=clear_presence',
          new Blob([JSON.stringify({action:'clear_presence'})], {type:'application/json'})
        );
      } catch(e) {}
    }
  });

  function orderTotals(order) {
    let totalUsd = 0, totalRmb = 0;
    (order.entries || []).forEach(e => {
      const key = `${e.clientName}|${e.workbookId}`;
      const detail = workbookDetail[key];
      if (!detail) return;
      const tiers = Array.isArray(detail.tiers) ? detail.tiers : [];
      const selectedIdx = detail.selectedTierIdx;
      const tier = tiers.find(t => t.id == selectedIdx) || tiers[0];
      if (tier && tier.price) {
        const priceRmb = parseFloat(tier.price) || 0;
        const qty = parseFloat(tier.qty) || 0;
        const exchange = 7.2;
        totalRmb += priceRmb * qty;
        totalUsd += (priceRmb / exchange) * qty;
      }
    });
    return { totalUsd: Math.round(totalUsd * 100) / 100, totalRmb: Math.round(totalRmb * 100) / 100 };
  }

  // ── Nav badge helper ─────────────────────────────────────────────────
  // actionable > 0 → orange pulsing badge with actionable count
  // actionable = 0, total > 0 → blue badge with total count
  // total = 0 → badge hidden
  function _applyNavBadge(badge, actionable, total) {
    if (!badge) return;
    // Clear prior content + attention class (leftover from single-badge era)
    badge.classList.remove('attention');
    const remaining = Math.max(0, (total || 0) - (actionable || 0));
    const parts = [];
    if (actionable > 0) parts.push(`<span class="nav-badge-pill attention">${actionable}</span>`);
    if (remaining > 0)  parts.push(`<span class="nav-badge-pill">${remaining}</span>`);
    badge.innerHTML = parts.join('');
  }

  // ── Nav ──────────────────────────────────────────────────────────────
  function rebuildOrdersNav() {
    const ids = Object.keys(orderData);
    // Actionable = client has requested changes on an order
    _applyNavBadge(
      document.getElementById('badge-orders'),
      ids.filter(id => orderData[id].changeRequested).length,
      ids.length
    );
  }

  // ── Portal change-request polling ────────────────────────────────────
  async function checkPortalChanges() {
    try {
      // Fetch every portal token currently in changes_requested state
      const pending = await apiCall('get_pending_changes');
      if (!Array.isArray(pending)) return;

      // Build lookup sets keyed by "clientName|orderName"
      const flaggedKeys  = new Set(pending.map(p => `${p.client_name}|${p.order_name}`));
      const tokenByKey   = {};
      pending.forEach(p => { tokenByKey[`${p.client_name}|${p.order_name}`] = p.token; });

      let changed = false;
      Object.keys(orderData).forEach(id => {
        const o   = orderData[id];
        const key = `${o.clientName}|${o.name}`;
        const shouldFlag = flaggedKeys.has(key);

        if (shouldFlag && !o.changeRequested) {
          o.changeRequested = true;
          if (!o.portalToken) o.portalToken = tokenByKey[key]; // backfill token for future use
          changed = true;
        } else if (!shouldFlag && o.changeRequested) {
          // No longer in the pending list → was approved / resolved
          o.changeRequested = false;
          changed = true;
        }
      });

      if (changed) {
        saveOrders();
        renderOrdersContent();
        rebuildOrdersNav();
        // Shipment & sample badges depend on linked orders' changeRequested state
        rebuildShipmentsNav();
        rebuildSamplesNav();
      }
    } catch(e) { /* silent — don't disrupt UI on poll failure */ }
  }

  // ── Create Order modal ───────────────────────────────────────────────
  function openNewOrderModal() {
    _orderPickerSelected = new Set();
    // Populate client dropdown
    const sel = document.getElementById('order-picker-client');
    sel.innerHTML = '<option value="">Select a client…</option>';
    Object.keys(clientData).sort().forEach(name => {
      const opt = document.createElement('option');
      opt.value = name;
      opt.textContent = name;
      sel.appendChild(opt);
    });
    // Hide workbook section until client chosen
    document.getElementById('order-picker-wb-section').style.display = 'none';
    document.getElementById('order-picker-search').value = '';
    document.getElementById('order-picker-list').innerHTML = '';
    // Hide the grand total card on open in case it was left visible
    // from a previous Cancel without a re-render.
    const gt = document.getElementById('order-picker-grand-total');
    if (gt) gt.style.display = 'none';
    document.getElementById('modal-new-order').classList.add('open');
  }

  function closeNewOrderModal() {
    document.getElementById('modal-new-order').classList.remove('open');
    _orderPickerSelected = new Set();
    const gt = document.getElementById('order-picker-grand-total');
    if (gt) gt.style.display = 'none';
  }

  function onOrderPickerClientChange() {
    const client = document.getElementById('order-picker-client').value;
    const section = document.getElementById('order-picker-wb-section');
    if (!client) {
      section.style.display = 'none';
      _orderPickerSelected = new Set();
      _renderOrderPickerGrandTotal();
      return;
    }
    _orderPickerSelected = new Set();
    document.getElementById('order-picker-search').value = '';
    // Match the inline `display:flex; flex-direction:column` set in
    // the modal HTML — using '' here would resolve to block and break
    // the flex sizing of the inner search + list.
    section.style.display = 'flex';
    buildOrderPickerList('');
  }

  function buildOrderPickerList(query) {
    const list = document.getElementById('order-picker-list');
    if (!list) return;
    const clientName = document.getElementById('order-picker-client').value;
    if (!clientName) return;
    query = (query || '').toLowerCase();

    // Status groups: latest → earliest
    const statusGroups = [
      { key: 'complete',         label: 'Complete' },
      { key: 'orderChina',       label: 'Order Placed' },
      { key: 'confirmedPayment', label: 'Payment Confirmed' },
      { key: 'officeInvoice',    label: 'Office Invoice' },
      { key: 'clientApproved',   label: 'Client Approved' },
      { key: 'quoteClient',      label: 'Quote Sent to Client' },
      { key: 'quoteSubmitted',   label: 'Quote Submitted' },
      { key: 'quoteChina',       label: 'Quote from China' },
      { key: 'new',              label: 'New' },
    ];

    const palette = ['#6b93ff','#f59e0b','#4ade80','#f472b6','#a78bfa','#34d399','#fb923c','#38bdf8'];
    const color = palette[Object.keys(clientData).sort().indexOf(clientName) % palette.length];

    const buckets = {};
    statusGroups.forEach(g => { buckets[g.key] = []; });

    // Reset the per-item snapshot for this render so removed / filtered
    // workbooks don't linger in the grand total sums.
    _orderPickerItemData = {};

    (clientData[clientName] || []).forEach(wb => {
      const key     = `${clientName}|${wb.id}`;
      const detail  = workbookDetail[key] || {};
      const product = detail.product || wb.product || '—';
      if (query && !product.toLowerCase().includes(query)) return;
      // Per-workbook stat line: total units · total weight · total cost.
      // Helper centralizes the source-of-truth selection so all
      // pickers / cards stay aligned with the Pricing tab.
      const w = _wbStatsForPicker(detail);
      _orderPickerItemData[key] = { units: w.units, weightKg: w.weightKg, cost: w.cost, price: w.price, cbm: w.cbm };
      // CBM tucked in next to weight, colored so it reads as one
      // shipment-dimensions phrase.
      const partsSummary = [];
      partsSummary.push(w.units > 0 ? `${w.units.toLocaleString('en-US')} units` : '— units');
      const cbmPill = w.cbm > 0
        ? ` <span style="color:var(--accent); font-weight:600;">(${w.cbm.toLocaleString('en-US', {minimumFractionDigits: 1, maximumFractionDigits: 1})} CBM)</span>`
        : '';
      const weightCbmStr = w.weightKg > 0
        ? `${w.weightKg.toLocaleString('en-US', {maximumFractionDigits: 0})} kg${cbmPill}`
        : (w.cbm > 0 ? `— kg${cbmPill}` : '— kg');
      partsSummary.push(weightCbmStr);
      partsSummary.push(w.cost > 0 ? `$${w.cost.toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2})}` : '—');
      const tierStr = partsSummary.join(' · ');
      const item = { clientName, workbookId: wb.id, product, tierStr, key };

      const flow = wb.flow || {};
      if (isFlowComplete(flow)) {
        buckets['complete'].push(item);
      } else {
        const lastStep = [...flowSteps].reverse().find(s => flow[s]);
        buckets[lastStep || 'new'].push(item);
      }
    });

    let html = '';
    let totalItems = 0;
    statusGroups.forEach(group => {
      const items = buckets[group.key];
      if (!items || items.length === 0) return;
      totalItems += items.length;
      html += `<div class="wb-picker-group-label">${group.label}</div>`;
      items.forEach(item => {
        const isChecked = _orderPickerSelected.has(item.key);
        const initials  = item.clientName.substring(0, 3).toUpperCase();
        html += `<div class="wb-picker-item${isChecked ? ' selected' : ''}"
            onclick="toggleOrderPickerItem('${item.key.replace(/'/g,"\\'")}')">
          <div style="width:40px; height:40px; border-radius:8px; background:${color}22; border:1px solid ${color}44; display:flex; align-items:center; justify-content:center; font-size:11px; font-weight:800; color:${color}; flex-shrink:0; letter-spacing:0.02em;">
            ${initials}
          </div>
          <div class="wb-picker-info">
            <div class="wb-picker-product">${item.product}</div>
            <div class="wb-picker-tiers">${item.tierStr}</div>
          </div>
          <div style="width:20px; height:20px; border-radius:4px; border:2px solid ${isChecked ? 'var(--accent)' : 'var(--border)'}; background:${isChecked ? 'var(--accent)' : 'transparent'}; display:flex; align-items:center; justify-content:center; flex-shrink:0; transition:all 0.15s;">
            ${isChecked ? '<svg width="11" height="9" viewBox="0 0 11 9" fill="none"><path d="M1 4L4 7.5L10 1" stroke="white" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>' : ''}
          </div>
        </div>`;
      });
    });

    if (totalItems === 0) {
      list.innerHTML = `<div style="text-align:center; padding:30px; color:var(--text-muted); font-size:13px;">
        ${query ? 'No workbooks match your search.' : 'No workbooks found for this client.'}
      </div>`;
      _renderOrderPickerGrandTotal();
      return;
    }
    list.innerHTML = html;
    _renderOrderPickerGrandTotal();
  }

  // Mirrors _renderOrderAddGrandTotal but reads from the Create Order
  // picker's selected set + per-item snapshot. Hidden when nothing is
  // checked. CBM bar caps visually at 100% but the numeric label keeps
  // climbing past 67 to signal overflow into a 2nd container.
  function _renderOrderPickerGrandTotal() {
    const card = document.getElementById('order-picker-grand-total');
    if (!card) return;
    const sel = _orderPickerSelected;
    if (!sel || sel.size === 0) {
      card.style.display = 'none';
      return;
    }
    card.style.display = '';
    let units = 0, weightKg = 0, cost = 0, price = 0, cbm = 0;
    sel.forEach(key => {
      const d = (_orderPickerItemData && _orderPickerItemData[key]) || null;
      if (!d) return;
      units    += d.units    || 0;
      weightKg += d.weightKg || 0;
      cost     += d.cost     || 0;
      price    += d.price    || 0;
      cbm      += d.cbm      || 0;
    });
    const fmtNum = n => n.toLocaleString('en-US');
    const fmtUsd = n => '$' + n.toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2});
    const fmtKg  = n => n.toLocaleString('en-US', {maximumFractionDigits: 0}) + ' kg';
    const fmtCbm = n => n.toLocaleString('en-US', {minimumFractionDigits: 1, maximumFractionDigits: 1});
    const set = (id, txt) => { const el = document.getElementById(id); if (el) el.textContent = txt; };
    set('order-picker-gt-count',  `${sel.size} selected`);
    set('order-picker-gt-units',  units    > 0 ? fmtNum(units)  : '—');
    set('order-picker-gt-weight', weightKg > 0 ? fmtKg(weightKg) : '—');
    set('order-picker-gt-cost',   cost     > 0 ? fmtUsd(cost)    : '—');
    set('order-picker-gt-price',  price    > 0 ? fmtUsd(price)   : '—');
    const cbmCap = 67;
    const cbmOver = cbm > cbmCap ? cbm - cbmCap : 0;
    _renderCbmFillIndicator('order-picker-gt-cbm-label', 'order-picker-gt-cbm-bar', cbm, cbmCap, cbmOver, fmtCbm);
  }

  function filterOrderPicker(query) {
    buildOrderPickerList(query);
  }

  function toggleOrderPickerItem(key) {
    if (_orderPickerSelected.has(key)) {
      _orderPickerSelected.delete(key);
    } else {
      _orderPickerSelected.add(key);
    }
    buildOrderPickerList(document.getElementById('order-picker-search').value);
  }

  function createOrder() {
    const clientName = document.getElementById('order-picker-client').value;
    if (!clientName) { alert('Please select a client.'); return; }
    if (_orderPickerSelected.size === 0) { alert('Select at least one workbook.'); return; }

    const entries = [];
    _orderPickerSelected.forEach(key => {
      const lastPipe   = key.lastIndexOf('|');
      const workbookId = key.substring(lastPipe + 1);
      entries.push({ clientName, workbookId });
    });

    const id  = _nextOrderId++;
    const num = String(id).padStart(3, '0');
    orderData[id] = {
      id,
      name: `Order #${num}`,
      clientName,
      status: 'draft',
      dateCreated: new Date().toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: '2-digit' }),
      poNumber: '',
      depositPct: 30,
      notes: '',
      entries,
    };
    saveOrders();
    rebuildOrdersNav();
    closeNewOrderModal();
    location.hash = `#/order/${id}`;
  }

  // ── List view ────────────────────────────────────────────────────────
  /* ── CSV Export ─────────────────────────────────────────────────────────── */
  function downloadCsv(filename, headers, rows) {
    const esc = v => {
      const s = (v == null ? '' : String(v));
      return (s.includes(',') || s.includes('"') || s.includes('\n'))
        ? '"' + s.replace(/"/g, '""') + '"' : s;
    };
    const csv = [headers, ...rows].map(r => r.map(esc).join(',')).join('\r\n');
    const a = Object.assign(document.createElement('a'), {
      href: URL.createObjectURL(new Blob([csv], { type: 'text/csv;charset=utf-8;' })),
      download: filename
    });
    document.body.appendChild(a); a.click(); document.body.removeChild(a);
  }

  function buildOrderRows(o) {
    const rate = USD_TO_RMB || 7.24;
    const f2 = v => v > 0 ? parseFloat(v).toFixed(2) : '';
    const rows = [];
    const statusLabel = { draft:'Draft', confirmed:'Confirmed', in_production:'In Production', complete:'Complete' };
    (o.entries || []).forEach(entry => {
      const detail   = workbookDetail[`${entry.clientName}|${entry.workbookId}`] || {};
      const product  = detail.product || `Workbook #${entry.workbookId}`;
      const rfqItems = (detail.rfqItems || []).filter(i => i.item || i.qty || i.priceRmb);
      const base = [o.name || `Order #${o.id}`, o.dateCreated || '', o.clientName || '', o.poNumber || '', statusLabel[o.status] || o.status, product];
      if (!rfqItems.length) {
        rows.push([...base, '', '', '', '', '', '', '']);
      } else {
        rfqItems.forEach(item => {
          const rmb   = parseFloat(item.priceRmb) || 0;
          const qty   = parseFloat(item.qty)      || 0;
          const usd   = rmb / rate;
          rows.push([...base, item.item || '', item.sku || '', qty || '', f2(rmb), f2(usd), f2(rmb * qty), f2((rmb * qty) / rate)]);
        });
      }
    });
    return rows;
  }

  function exportOrderCsv(orderId) {
    const o = orderData[orderId != null ? orderId : _currentOrderId];
    if (!o) return;
    const headers = ['Order','Date','Client','PO #','Status','Product','Item','SKU','Qty','Unit Price (RMB)','Unit Price (USD)','Total (RMB)','Total (USD)'];
    const rows = buildOrderRows(o);
    // Totals row
    const totalUsd = rows.reduce((s, r) => s + (parseFloat(r[12]) || 0), 0);
    const totalRmb = rows.reduce((s, r) => s + (parseFloat(r[11]) || 0), 0);
    rows.push(['','','','','','','','','TOTAL','','',totalRmb.toFixed(2), totalUsd.toFixed(2)]);
    downloadCsv(`${(o.name || 'Order').replace(/[^a-z0-9]/gi,'-')}.csv`, headers, rows);
  }

  function exportAllOrdersCsv() {
    const orders = Object.values(orderData);
    if (!orders.length) { alert('No orders to export.'); return; }
    const headers = ['Order','Date','Client','PO #','Status','Product','Item','SKU','Qty','Unit Price (RMB)','Unit Price (USD)','Total (RMB)','Total (USD)'];
    const rows = orders.flatMap(o => buildOrderRows(o));
    const today = new Date().toISOString().slice(0,10);
    downloadCsv(`All-Orders-${today}.csv`, headers, rows);
  }

  function renderOrdersList() {
    document.getElementById('header-title').textContent = 'Orders';
    document.querySelectorAll('.sidebar-nav .nav-item').forEach(a => a.classList.remove('active'));
    document.querySelectorAll('.nav-flat-link').forEach(a => a.classList.remove('active'));
    const ordNav = document.getElementById('nav-orders-link');
    if (ordNav) ordNav.classList.add('active');
    showView('view-orders');
    renderOrdersContent();
  }

  function filterOrders(status, btn) {
    _orderFilter = status;
    document.querySelectorAll('.order-filter-btn').forEach(b => b.classList.remove('active'));
    if (btn) btn.classList.add('active');
    renderOrdersContent();
  }

  function renderOrdersContent() {
    const el = document.getElementById('order-list-content');
    if (!el) return;

    const ids = Object.keys(orderData);
    if (ids.length === 0) {
      el.innerHTML = `<div class="order-list-empty">
        <div class="order-list-empty-icon">📋</div>
        <div class="order-list-empty-title">No orders yet</div>
        <div class="order-list-empty-sub">Create an order to track approved workbooks through production.</div>
      </div>`;
      return;
    }

    const STATUS_ORDER = ['draft', 'confirmed', 'in_production', 'complete'];
    const filterLabels = { all: 'All', attention: '⚑ Needs Attention', draft: 'Draft', confirmed: 'Confirmed', in_production: 'In Production', complete: 'Complete' };

    const counts = { all: ids.length, attention: ids.filter(id => orderData[id].changeRequested).length };
    ids.forEach(id => {
      const st = orderData[id].status;
      counts[st] = (counts[st] || 0) + 1;
    });

    const filterBar = `<div class="order-filter-bar">
      ${['all','attention','draft','confirmed','in_production','complete'].map(s => {
        const isAttention = s === 'attention';
        return `<button class="order-filter-btn${isAttention ? ' attention-btn' : ''}${_orderFilter === s ? ' active' : ''}" onclick="filterOrders('${s}', this)">
          ${filterLabels[s]}${counts[s] ? ` <span style="opacity:0.7">(${counts[s]})</span>` : ''}
        </button>`;
      }).join('')}
    </div>`;

    function buildOrderCard(id) {
      const o = orderData[id];
      const tot = orderTotals(o);
      const entries = o.entries || [];
      const wbCount = entries.length;

      // Aggregate per-workbook stats across this order so the card
      // can show Units / Weight / Cost (ours) / Price (customer) /
      // CBM / Lead. Helper centralizes the source-of-truth selection
      // so this card reads the same numbers as the Pricing tab and
      // every picker. Per-workbook lead time = max(production lead,
      // selected freight mode's shipping lead); order lead = max
      // across the order's workbooks (a 30-day workbook sets the
      // floor for the whole shipment).
      let agUnits = 0, agWeightKg = 0, agCost = 0, agPrice = 0, agCbm = 0, agMaxLead = 0, agShipping = 0, agProductCost = 0;
      const wbStatsByEntry = new Map();
      entries.forEach(e => {
        const key = `${e.clientName}|${e.workbookId}`;
        const w = _wbStatsForPicker(workbookDetail[key]);
        wbStatsByEntry.set(key, w);
        agUnits       += w.units;
        agWeightKg    += w.weightKg;
        agCost        += w.cost;
        agPrice       += w.price;
        agCbm         += w.cbm;
        agShipping    += (w.shippingUsd || 0);
        agProductCost += (w.productCost || 0);
        if (w.leadDays > agMaxLead) agMaxLead = w.leadDays;
      });

      const _fxRate = (typeof USD_TO_RMB === 'number' && USD_TO_RMB > 0) ? USD_TO_RMB : 7.2;
      const wbPills = wbCount === 0
        ? `<span style="font-size:12px;color:var(--text-muted);font-style:italic;">No workbooks</span>`
        : entries.map(e => {
            const key = `${e.clientName}|${e.workbookId}`;
            const detail = workbookDetail[key];
            const prod = detail ? (detail.product || 'Untitled') : 'Untitled';
            const href = `#/client/${encodeURIComponent(e.clientName)}/workbook/${e.workbookId}`;
            // Per-workbook pricing — Client Quote Total Order (Sale
            // Per × qty + applied fees) so the per-row number matches
            // what the customer is charged. RMB is the USD value
            // back-converted at the live FX rate.
            const w = wbStatsByEntry.get(key) || { price: 0 };
            let wbRmb = '', wbUsd = '';
            if (w.price > 0) {
              const totalUsd = w.price;
              const totalRmb = totalUsd * _fxRate;
              wbUsd = `$${totalUsd.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
              wbRmb = `¥${totalRmb.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
            }
            const priceStr = (wbRmb || wbUsd)
              ? `<span class="oc-wb-prices">${[wbRmb, wbUsd].filter(Boolean).join('&nbsp;&nbsp;')}</span>`
              : '';
            return `<div class="oc-wb-row">
              <span class="oc-wb-pill" onclick="event.stopPropagation(); _wbBackHash='#/orders'; _wbBackLabel='Back to Orders'; location.hash='${href}'">${prod} <span style="opacity:0.75;">→</span></span>
              ${priceStr}
            </div>`;
          }).join('');

      const statusLabel = o.status.replace('_', ' ');
      // Right-side TOTAL — the Client Quote Total Order summed
      // across the order's workbooks (matches the per-workbook pills
      // above and the Price (cust) cell in the stat strip below).
      // Falls back to the legacy tier-cost total when no workbook
      // has Sale Per typed yet so a brand-new order still renders
      // a non-zero header total.
      const headerUsd = agPrice > 0 ? agPrice : (tot.totalUsd || 0);
      const headerRmb = agPrice > 0 ? (agPrice * _fxRate) : (tot.totalRmb || 0);
      const usdStr = headerUsd > 0 ? `$${headerUsd.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}` : '—';
      const rmbStr = headerRmb > 0 ? `¥${headerRmb.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}` : '';
      // Lead-time badge: max across all workbooks in the order. A
      // 30-day production workbook drives the whole order's earliest
      // possible ship date. Hidden when no workbook contributes a lead.
      // Sibling "arrives" pill projects the expected delivery date as
      // a live forecast — "if I placed this order today, when does it
      // land?" — so it advances day-by-day rather than being anchored
      // to the order's creation date. Useful for draft / in-production
      // orders where the client wants a current ETA.
      // Format like "July 25th, 2026" / "Aug 9th, 2026" — full month
      // name (Intl en-US), day with ordinal suffix, four-digit year.
      // Ordinal rules: 1st/2nd/3rd/4th-20th th, then 21st/22nd/23rd
      // and the 11/12/13 exceptions all end in 'th'.
      const _ordinalSuffix = (day) => {
        if (day >= 11 && day <= 13) return 'th';
        switch (day % 10) {
          case 1: return 'st';
          case 2: return 'nd';
          case 3: return 'rd';
          default: return 'th';
        }
      };
      const _fmtCardDate = (d) => {
        if (!d) return '';
        const month = d.toLocaleDateString('en-US', { month: 'long' });
        const day   = d.getDate();
        const year  = d.getFullYear();
        return `${month} ${day}${_ordinalSuffix(day)}, ${year}`;
      };
      let arrivesBadge = '';
      if (agMaxLead > 0) {
        // Anchor to today at midnight local time so the date doesn't
        // jitter across timezone boundaries within the same day.
        const today = new Date();
        today.setHours(0, 0, 0, 0);
        const arrives = new Date(today.getTime() + agMaxLead * 86400000);
        arrivesBadge = `<span style="display:inline-flex; align-items:center; gap:5px; padding:2px 8px; border-radius:9px; background:rgba(16,185,129,0.10); color:#10b981; border:1px solid rgba(16,185,129,0.30); font-size:10px; font-weight:700; letter-spacing:0.05em; white-space:nowrap;" title="Projected arrival if the order is placed today — today + ${agMaxLead} day lead"><span style="text-transform:uppercase;">Arrives</span><span style="text-transform:none; letter-spacing:0;">${_fmtCardDate(arrives)}</span></span>`;
      }
      const leadBadge = agMaxLead > 0
        ? `<span style="display:inline-flex; align-items:center; gap:4px; padding:2px 8px; border-radius:9px; background:rgba(232,117,26,0.10); color:var(--accent); border:1px solid rgba(232,117,26,0.30); font-size:10px; font-weight:700; text-transform:uppercase; letter-spacing:0.05em; white-space:nowrap;" title="Longest workbook lead time in this order — production + shipping">${agMaxLead} day lead</span>`
        : '';
      const leadBlock = (leadBadge || arrivesBadge)
        ? `<div style="display:flex; gap:6px; flex-wrap:wrap; margin-top:4px;">${leadBadge}${arrivesBadge}</div>`
        : '';
      const changeBadge = o.changeRequested
        ? `<span class="oc-change-badge"><svg width="9" height="9" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" style="flex-shrink:0"><path d="M4 15s1-1 4-1 5 2 8 2 4-1 4-1V3s-1 1-4 1-5-2-8-2-4 1-4 1z"/><line x1="4" y1="22" x2="4" y2="15"/></svg> Change Requested</span>`
        : '';

      // Compact stat strip rendered as a footer row inside the card —
      // shows the 5 aggregate metrics + a container-fill bar so the
      // operator can size the order at a glance from the list. Each
      // stat falls back to "—" individually so a partial order still
      // surfaces what it has.
      const fmtUsdT = n => n > 0 ? '$' + n.toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2}) : '—';
      const fmtKgT  = n => n > 0 ? n.toLocaleString('en-US', {maximumFractionDigits: 0}) + ' kg' : '—';
      const fmtCbmT = n => n > 0 ? n.toLocaleString('en-US', {minimumFractionDigits: 1, maximumFractionDigits: 1}) : '—';
      const fmtNumT = n => n > 0 ? n.toLocaleString('en-US') : '—';
      const cbmCapT = 67;
      const fillPctT  = agCbm > 0 ? Math.min(100, (agCbm / cbmCapT) * 100) : 0;
      const cbmOverT  = agCbm > cbmCapT ? agCbm - cbmCapT : 0;
      // Overflow indicator: amber bar + "+X.X over" pill when total
      // CBM exceeds the single 40' HC container cap (67 m³).
      const cbmValHtml = agCbm > 0
        ? (cbmOverT > 0
            ? `<span style="color:#d97706;">⚠</span> ${fmtCbmT(agCbm)} <span class="oc-stat-cbm-cap">/ ${cbmCapT}</span> <span style="color:#d97706; font-weight:800; margin-left:4px;">+${fmtCbmT(cbmOverT)} over</span>`
            : `${fmtCbmT(agCbm)} <span class="oc-stat-cbm-cap">/ ${cbmCapT}</span>`)
        : '—';
      const cbmBarColor = cbmOverT > 0 ? '#f59e0b' : 'var(--accent)';
      // Cost decomposition: each workbook caches productCost,
      // shippingUsd, and grandTotalCost independently on the Pricing
      // tab. We display all three from the cached values directly.
      //
      // IMPORTANT: Total (ours) is the cached agCost rollup, NOT the
      // recomputed (product + shipping) sum. Each workbook's cached
      // grandTotalCost is ceil-2 of (productTotal + shippingUsd) at
      // SAVE time — so per-workbook ceiling lands cleanly. Summing
      // product and shipping streams independently re-ceils each one
      // separately, which can drift by a cent or two per workbook
      // (e.g. $30,804.26 cached vs $30,803.76 recomputed). Cached
      // total wins — it's what the operator saw on the Pricing tab.
      //
      // Falls back to (product + shipping) only when agCost is truly
      // missing (brand-new order, no workbooks priced yet).
      const agCostProduct = agProductCost;
      const agTotalOurs   = agCost > 0
        ? agCost
        : (agProductCost + agShipping);
      // Profit cell — Price (cust) minus Total (ours). Uses the new
      // additive Total (ours) above (product + shipping) so Profit
      // always equals Price − Total as displayed in the same row.
      // Operator sanity-check: the three cost cells visibly add up,
      // and Profit visibly equals Price − Total. Red when negative
      // (selling below cost — flags a pricing mistake) and green
      // otherwise. Blanks out when no workbook in the order has Sale
      // Per typed yet.
      const profitT       = (agPrice > 0 && agTotalOurs > 0) ? (agPrice - agTotalOurs) : 0;
      const profitHasData = (agPrice > 0 && agTotalOurs > 0);
      const profitColor   = profitT < 0 ? 'var(--danger, #dc2626)' : 'var(--success, #16a34a)';
      const profitHtml    = profitHasData
        ? `<span style="color:${profitColor}; font-weight:700;">${fmtUsdT(profitT)}</span>`
        : '—';
      const statStrip = `<div class="oc-stat-strip">
        <div class="oc-stat"><span class="oc-stat-label">Units</span><span class="oc-stat-val">${fmtNumT(agUnits)}</span></div>
        <div class="oc-stat"><span class="oc-stat-label">Weight</span><span class="oc-stat-val">${fmtKgT(agWeightKg)}</span></div>
        <div class="oc-stat" title="Product cost only — Total (ours) minus Shipping. Sum of each workbook's Pricing-tab Product Cost (no fees, no margin)."><span class="oc-stat-label">Cost (ours)</span><span class="oc-stat-val">${fmtUsdT(agCostProduct)}</span></div>
        <div class="oc-stat" title="Total shipping cost (USD) across all workbooks in this order — sum of each workbook's Pricing-tab Shipping Cost (USD)."><span class="oc-stat-label">Shipping</span><span class="oc-stat-val">${fmtUsdT(agShipping)}</span></div>
        <div class="oc-stat" title="Total (ours) = Cost (ours) + Shipping. What it costs us to land this order before margin and fees."><span class="oc-stat-label">Total (ours)</span><span class="oc-stat-val">${fmtUsdT(agTotalOurs)}</span></div>
        <div class="oc-stat"><span class="oc-stat-label">Price (cust)</span><span class="oc-stat-val">${fmtUsdT(agPrice)}</span></div>
        <div class="oc-stat"><span class="oc-stat-label">Profit</span><span class="oc-stat-val">${profitHtml}</span></div>
        <div class="oc-stat oc-stat--cbm">
          <span class="oc-stat-label">CBM</span>
          <span class="oc-stat-val">${cbmValHtml}</span>
          <div class="oc-cbm-bar"><div class="oc-cbm-bar-fill" style="width:${fillPctT}%; background:${cbmBarColor};"></div></div>
        </div>
      </div>`;

      return `<div class="order-card${o.changeRequested ? ' has-change-request' : ''}" onclick="location.hash='#/order/${id}'">
        <div class="oc-card-main">
          <div class="oc-left">
            <span class="oc-client">${o.clientName}</span>
            <span class="oc-title">${o.name}</span>
            <span class="oc-date">${o.dateCreated}</span>
            ${leadBlock}
            ${changeBadge}
          </div>
          <div class="oc-wb-list">
            <div class="oc-wb-count">${wbCount} workbook${wbCount !== 1 ? 's' : ''}</div>
            ${wbPills}
          </div>
          <div class="oc-right-wrap">
            ${(agShipping > 0 && agPrice > agShipping) ? `
            <div class="oc-grand-breakdown">
              <div class="oc-gb-row">
                <span class="oc-gb-label">Price (theirs)</span>
                <span class="oc-gb-val">${fmtUsdT(agPrice - agShipping)}</span>
              </div>
              <div class="oc-gb-row">
                <span class="oc-gb-label">+ Shipping</span>
                <span class="oc-gb-val">${fmtUsdT(agShipping)}</span>
              </div>
              <div class="oc-gb-divider"></div>
            </div>` : ''}
            <div class="oc-grand-total">
              <span class="oc-grand-label">Total</span>
              <span class="oc-grand-usd">${usdStr}</span>
              ${rmbStr ? `<span class="oc-grand-rmb">${rmbStr}</span>` : ''}
            </div>
          </div>
        </div>
        ${statStrip}
      </div>`;
    }

    const filtered = ids.filter(id => {
      if (_orderFilter === 'all')       return true;
      if (_orderFilter === 'attention') return !!orderData[id].changeRequested;
      return orderData[id].status === _orderFilter;
    });
    const active   = filtered.filter(id => orderData[id].status !== 'complete');
    const complete = filtered.filter(id => orderData[id].status === 'complete');

    active.sort((a, b) => {
      // Change-requested orders always float to the top
      const aCR = orderData[a].changeRequested ? 0 : 1;
      const bCR = orderData[b].changeRequested ? 0 : 1;
      if (aCR !== bCR) return aCR - bCR;
      return STATUS_ORDER.indexOf(orderData[a].status) - STATUS_ORDER.indexOf(orderData[b].status);
    });

    let html = filterBar;

    if (active.length > 0) {
      html += `<div class="order-cards">${active.map(buildOrderCard).join('')}</div>`;
    }
    if (complete.length > 0) {
      html += `<div class="sc-section-label" style="margin-top:${active.length > 0 ? '20px' : '0'}">Complete</div>
        <div class="order-cards" style="opacity:0.7">${complete.map(buildOrderCard).join('')}</div>`;
    }
    if (active.length === 0 && complete.length === 0) {
      html += `<div style="padding:30px 0; text-align:center; color:var(--text-muted); font-size:13px;">No orders match this filter.</div>`;
    }

    el.innerHTML = html;
  }

  // ── Detail view ──────────────────────────────────────────────────────
  function renderOrderDetail(id) {
    _currentOrderId = parseInt(id);
    const o = orderData[_currentOrderId];
    if (!o) { location.hash = '#/orders'; return; }

    document.getElementById('header-title').textContent = o.name;
    document.querySelectorAll('.sidebar-nav .nav-item').forEach(a => a.classList.remove('active'));
    document.querySelectorAll('.nav-flat-link').forEach(a => a.classList.remove('active'));
    const ordNav = document.getElementById('nav-orders-link');
    if (ordNav) ordNav.classList.add('active');

    document.getElementById('order-detail-client-name').textContent = o.clientName;
    document.getElementById('order-detail-name').value = o.name;
    document.getElementById('order-detail-po').value = o.poNumber || '';
    document.getElementById('order-detail-deposit-pct').value = o.depositPct != null ? o.depositPct : 30;
    document.getElementById('order-detail-notes').value = o.notes || '';
    document.getElementById('order-detail-date-tag').textContent = o.dateCreated;

    renderOrderSheet();
    renderOrderDepositTracking();
    showView('view-order-detail');

    // Show or hide the change-request panel
    const crCard = document.getElementById('order-cr-card');
    if (crCard) {
      if (o.changeRequested) {
        crCard.style.display = '';
        loadChangeRequestDetails(_currentOrderId);
      } else {
        crCard.style.display = 'none';
      }
    }
  }

  async function loadChangeRequestDetails(orderId) {
    const o = orderData[orderId];
    if (!o) return;
    const body = document.getElementById('cr-body');
    const meta = document.getElementById('cr-meta');
    if (!body) return;
    body.innerHTML = '<div style="color:var(--text-muted);font-size:13px;">Loading…</div>';

    const params = o.portalToken
      ? { token: o.portalToken }
      : { client_name: o.clientName, order_name: o.name };

    const res = await apiCall('get_change_request', params);
    if (!res.success) {
      body.innerHTML = '<div style="color:var(--text-muted);font-size:13px;">Could not load change request details.</div>';
      return;
    }

    // Header meta: client email + date
    if (meta) {
      const dateStr = res.submitted_at
        ? new Date(res.submitted_at).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric', hour: '2-digit', minute: '2-digit' })
        : '';
      meta.textContent = [res.client_email, dateStr].filter(Boolean).join(' · ');
    }

    let html = '';

    // Overall client comment
    if (res.client_comment && res.client_comment.trim()) {
      html += `<div class="cr-comment">
        <div class="cr-comment-label">Client Comment</div>
        <div class="cr-comment-text">${res.client_comment.trim().replace(/\n/g, '<br>')}</div>
      </div>`;
    }

    // Flagged line items
    const changes = res.line_changes || [];
    const items   = res.items        || [];
    if (changes.length > 0) {
      html += `<div class="cr-items-label">${changes.length} Item${changes.length !== 1 ? 's' : ''} Flagged</div>`;
      html += changes.map(ch => {
        const itm      = items[ch.idx] || {};
        const itemName = itm.item    || `Item #${ch.idx + 1}`;
        const product  = itm.product || '';
        const qty      = itm.qty     ? `Qty: ${Number(itm.qty).toLocaleString('en-US')}` : '';
        return `<div class="cr-item">
          <div class="cr-item-header">
            ${product ? `<span class="cr-item-product">${product}</span><span style="color:var(--border)">·</span>` : ''}
            <span class="cr-item-name">${itemName}</span>
            ${qty ? `<span style="font-size:11px;color:var(--text-muted);margin-left:auto;">${qty}</span>` : ''}
          </div>
          <div class="cr-item-note">${ch.note ? ch.note.replace(/\n/g, '<br>') : '<em style="opacity:0.6">No note provided</em>'}</div>
        </div>`;
      }).join('');
    }

    if (!html) {
      html = '<div style="color:var(--text-muted);font-size:13px;font-style:italic;">No details available.</div>';
    }

    body.innerHTML = html;
  }

  // Which workbooks in the Order Sheet are expanded to show their
  // variant breakdown. Collapsed by default (empty set). Keyed by
  // `${clientName}|${workbookId}`. Survives re-renders so editing
  // elsewhere doesn't snap an open workbook shut.
  const _orderSheetExpanded = new Set();
  function toggleOrderSheetWb(key) {
    if (_orderSheetExpanded.has(key)) _orderSheetExpanded.delete(key);
    else _orderSheetExpanded.add(key);
    const safe = key.replace(/"/g, '\\"');
    const expanded = _orderSheetExpanded.has(key);
    document.querySelectorAll(`tr[data-osh-wb="${safe}"]`).forEach(r => {
      r.style.display = expanded ? '' : 'none';
    });
    const chev = document.querySelector(`.osh-chevron[data-osh-chev="${safe}"]`);
    if (chev) chev.style.transform = expanded ? 'rotate(90deg)' : '';
  }

  function renderOrderSheet() {
    const o = orderData[_currentOrderId];
    if (!o) return;
    const tbody = document.getElementById('order-sheet-tbody');
    const tfoot = document.getElementById('order-sheet-tfoot');
    const table = document.getElementById('order-sheet-table');
    const empty = document.getElementById('order-sheet-empty');
    const count = document.getElementById('order-wb-count');
    const entries = o.entries || [];

    if (count) count.textContent = entries.length > 0 ? `${entries.length} workbook${entries.length !== 1 ? 's' : ''}` : '';

    if (entries.length === 0) {
      if (table) table.style.display = 'none';
      if (empty) empty.style.display = '';
      if (tfoot) tfoot.innerHTML = '';
      return;
    }
    if (table) table.style.display = '';
    if (empty) empty.style.display = 'none';

    let grandUsd = 0, grandMaxLead = 0;
    // Order-level profit grand total — Σ (workbook sale − workbook cost)
    // across every workbook with both numbers cached. Workbooks
    // missing pricingGrandTotalCost contribute 0 (column shows "—"
    // for those rows so the operator can spot the gap).
    let grandProfitUsd = 0;
    // Sum cached shipment metrics across the order's workbooks. These
    // come from renderContainerViz / renderPricingTab caches written
    // when the operator visits each workbook's Shipping / Pricing tab,
    // so older / never-opened workbooks contribute 0 until visited.
    let totalWeightKg = 0, totalCbm = 0;
    const fmt2 = v => v.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

    tbody.innerHTML = entries.map((entry, idx) => {
      const key     = `${entry.clientName}|${entry.workbookId}`;
      const detail  = workbookDetail[key] || {};
      totalWeightKg += parseFloat(detail.pricingShipmentWeightKg) || 0;
      totalCbm      += parseFloat(detail.pricingShipmentCbm)      || 0;

      // Detect a stale entry — the workbook the order references no
      // longer exists in clientData (archived / deleted on the
      // Clients view). Render a distinct "Missing" row with a clear
      // remove action so the operator can reconcile the order
      // without hunting through Settings.
      const wbList   = (typeof clientData === 'object' && clientData) ? (clientData[entry.clientName] || []) : [];
      const liveWb   = wbList.find(wb => parseInt(wb.id) === parseInt(entry.workbookId));
      const isMissing = !liveWb && !detail.product;
      if (isMissing) {
        return `<tr class="order-sheet-wb-header" style="background:rgba(220,38,38,0.06);">
          <td colspan="6" style="border-top:1px dashed var(--danger, #dc2626); border-bottom:1px dashed var(--danger, #dc2626); padding:12px 14px;">
            <div style="display:flex; align-items:center; gap:10px;">
              <span style="font-size:14px;">⚠</span>
              <div style="flex:1; min-width:0;">
                <div style="font-weight:700; color:var(--danger, #dc2626); font-size:13px;">Missing workbook — was archived or deleted</div>
                <div style="font-size:11px; color:var(--text-muted); margin-top:2px;">${entry.clientName} · workbook #${entry.workbookId} · no live data to render</div>
              </div>
            </div>
          </td>
          <td style="text-align:right; vertical-align:middle;">
            <button class="order-sheet-remove" onclick="removeWorkbookFromOrder(${idx})" title="Remove this stale entry from the order"
              style="border-color:var(--danger, #dc2626); color:var(--danger, #dc2626);">×</button>
          </td>
        </tr>`;
      }

      const product = detail.product || (liveWb && liveWb.product) || entry.workbookId;
      const wbHref  = `#/client/${encodeURIComponent(entry.clientName)}/workbook/${entry.workbookId}`;
      const rfqItems = (detail.rfqItems || []).filter(i => i.item || i.qty || i.priceRmb);
      const splits   = Array.isArray(detail.shipmentSplits) ? detail.shipmentSplits.filter(s => s.qty > 0) : [];
      const splitBadges = splits.map(s => {
        const label = { slow:'Slow Boat', fast:'Fast Boat', airupp:'Air + UPS', directair:'Direct Air' }[s.method] || s.method;
        return `<span class="split-badge">${s.qty.toLocaleString('en-US')} ${label}</span>`;
      }).join('');

      // Lead time (production + shipping) for this workbook, via the
      // shared helper so it matches the order-card badge + pickers.
      const wbStats  = _wbStatsForPicker(detail);
      const wbLead   = wbStats.leadDays || 0;
      if (wbLead > grandMaxLead) grandMaxLead = wbLead;
      const leadStr  = wbLead > 0 ? `${wbLead} days` : '—';

      const _fxRate = (typeof USD_TO_RMB === 'number' && USD_TO_RMB > 0) ? USD_TO_RMB : 7.2;
      const fmt3 = v => v.toLocaleString('en-US', { minimumFractionDigits: 3, maximumFractionDigits: 3 });
      const esc = s => String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');

      // Effective qty per item = sum of variant qtys when the item
      // has variants (the parent's own qty is a placeholder in that
      // case, mirroring the Client Quote), else the item's own qty.
      const itemEffQty = it => {
        const vs = Array.isArray(it.variants) ? it.variants.filter(v => v && (v.variant || v.qty)) : [];
        if (vs.length) return vs.reduce((s, v) => s + (parseFloat(String(v.qty || '').replace(/,/g,'')) || 0), 0);
        return parseFloat(String(it.qty || '').replace(/,/g,'')) || 0;
      };
      const wbClientQuote = parseFloat(detail.pricingClientQuoteTotal) || 0;
      const wbTotalQty    = rfqItems.reduce((s, it) => s + itemEffQty(it), 0);
      const useQuote      = wbClientQuote > 0 && wbTotalQty > 0;
      // Per-unit sale price from the Client Quote = total ÷ total qty
      // (fees amortized; constant across the workbook's variants since
      // Sale Per is one workbook-level value).
      const wbSaleUnit    = (useQuote && wbTotalQty > 0) ? (wbClientQuote / wbTotalQty) : 0;
      // Cost-side fallback per-unit USD when no Client Quote yet —
      // qty-weighted blend so the workbook total still ≈ Σ rfq cost.
      const wbCostUnit = (() => {
        if (useQuote || wbTotalQty <= 0) return 0;
        let costSum = 0;
        rfqItems.forEach(it => {
          const vs = Array.isArray(it.variants) ? it.variants.filter(v => v && (v.variant || v.qty)) : [];
          if (vs.length) {
            vs.forEach(v => {
              const vq = parseFloat(String(v.qty || '').replace(/,/g,'')) || 0;
              const vr = parseFloat(String(v.priceRmb || '').replace(/,/g,'')) || parseFloat(it.priceRmb) || 0;
              costSum += (vr / _fxRate) * vq;
            });
          } else {
            const iq = parseFloat(String(it.qty || '').replace(/,/g,'')) || 0;
            const ir = parseFloat(it.priceRmb) || 0;
            costSum += (ir / _fxRate) * iq;
          }
        });
        return wbTotalQty > 0 ? costSum / wbTotalQty : 0;
      })();
      const perUnit  = useQuote ? wbSaleUnit : wbCostUnit;
      const wbTotal  = perUnit > 0 ? perUnit * wbTotalQty : 0;
      grandUsd += wbTotal;

      // Per-unit COST for the workbook. The TRUE cost basis is:
      //   pricingGrandTotalCost (product + shipping)
      //   + pricingAppliedFeesAsIs (real cost of applied fees — NOT
      //     the override, so any fee markup the operator typed flows
      //     into profit instead of being silently absorbed).
      // Spread evenly across qty for per-row math. Per-line profit
      // therefore reflects product margin + fee markup × (rowQty /
      // wbTotalQty) — i.e. each row carries its proportional share of
      // the fee markup as profit.
      const wbGrandTotalCost   = parseFloat(detail.pricingGrandTotalCost) || 0;
      const wbAppliedFeesAsIs  = parseFloat(detail.pricingAppliedFeesAsIs) || 0;
      const wbTrueCostBasis    = wbGrandTotalCost + wbAppliedFeesAsIs;
      const wbCostPerUnit      = wbTotalQty > 0 && wbTrueCostBasis > 0 ? wbTrueCostBasis / wbTotalQty : 0;
      const profitPerUnit      = (useQuote && wbCostPerUnit > 0) ? (wbSaleUnit - wbCostPerUnit) : 0;
      const haveProfit         = useQuote && wbCostPerUnit > 0 && wbTotalQty > 0;
      const wbProfit           = haveProfit ? profitPerUnit * wbTotalQty : 0;
      grandProfitUsd          += wbProfit;

      // Profit-cell helper — green for positive, red for negative,
      // muted dash when we don't have the data to compute it.
      const profitCell = (amount, has) => {
        if (!has) return `<td style="text-align:right; color:var(--text-muted);">—</td>`;
        const color = amount > 0 ? '#10b981' : amount < 0 ? '#dc2626' : 'var(--text-muted)';
        const sign  = amount > 0 ? '' : ''; // negative sign already in fmt
        return `<td style="text-align:right; font-weight:700; color:${color};">${sign}$${fmt2(amount)}</td>`;
      };

      const isExpanded = _orderSheetExpanded.has(key);
      const chevron = `<span class="osh-chevron" data-osh-chev="${esc(key)}" style="display:inline-block; margin-right:6px; opacity:0.6; transition:transform 0.15s; transform:${isExpanded ? 'rotate(90deg)' : 'none'};">▶</span>`;

      // Workbook header row — click anywhere on it (except the link
      // or the × button) to expand/collapse the variant breakdown.
      // Shows the workbook-level summary so the row is useful even
      // while collapsed.
      let rows = `<tr class="order-sheet-wb-header" style="cursor:pointer;" onclick="toggleOrderSheetWb('${esc(key).replace(/'/g,"\\'")}')">
        <td>
          ${chevron}<a class="order-sheet-product-link" href="${wbHref}"
            onclick="event.stopPropagation(); _wbBackHash='#/order/${_currentOrderId}'; _wbBackLabel='Back to Order'; event.preventDefault(); location.hash='${wbHref.substring(1)}'">
            ${esc(product)} <span style="font-size:11px; opacity:0.5;">→</span>
          </a>
          ${splitBadges}
        </td>
        <td style="text-align:right;">${wbTotalQty > 0 ? wbTotalQty.toLocaleString('en-US') : '—'}</td>
        <td style="text-align:right; color:var(--text-muted);">${perUnit > 0 ? '$' + fmt3(perUnit) : '—'}</td>
        <td style="text-align:right; font-weight:700;">${wbTotal > 0 ? '$' + fmt2(wbTotal) : '—'}</td>
        ${profitCell(wbProfit, haveProfit)}
        <td style="text-align:right; color:var(--text-muted);">${leadStr}</td>
        <td style="text-align:right;">
          <button class="order-sheet-remove" onclick="event.stopPropagation(); removeWorkbookFromOrder(${idx})" title="Remove">×</button>
        </td>
      </tr>`;

      // Detail rows — one per variant (or per item when no variants).
      // Hidden unless this workbook is expanded; toggled in-place by
      // toggleOrderSheetWb without a full re-render.
      const detailStyle = isExpanded ? '' : 'display:none;';
      if (rfqItems.length === 0) {
        rows += `<tr data-osh-wb="${esc(key)}" style="${detailStyle}">
          <td colspan="7" style="padding:8px 12px 12px 36px; color:var(--text-muted); font-size:12px; font-style:italic;">No line items</td>
        </tr>`;
      } else {
        // Per UX direction — when a workbook is EXPANDED, show its
        // variants as the line-item breakdown so the operator can see
        // what's actually inside ("Bulk Bag — Small / Medium / Large").
        // If an item has no variants we just show the item itself
        // (which will read identically to the workbook header for
        // single-item workbooks — that's the correct collapsed state).
        rfqItems.forEach(item => {
          const vs = Array.isArray(item.variants) ? item.variants.filter(v => v && (v.variant || v.qty)) : [];
          if (vs.length > 0) {
            // Per-variant rows. Show each variant indented under the
            // workbook header with its own qty + line total. Skip
            // empty placeholder variants (no qty AND no name).
            vs.forEach(v => {
              const vQty = parseFloat(String(v.qty || '').replace(/,/g,'')) || 0;
              const vTot = perUnit > 0 ? perUnit * vQty : 0;
              const vProfit = haveProfit && vQty > 0 ? profitPerUnit * vQty : 0;
              const vLabel = (v.variant || '').trim() || 'Variant';
              // Prefix the variant with its parent item name when the
              // workbook has multiple parents — disambiguates which
              // 'Small' belongs to which bag. Single-parent workbooks
              // can skip the prefix since context is unambiguous.
              const prefix = rfqItems.length > 1 ? `${esc(item.item || 'Item')} — ` : '';
              rows += `<tr data-osh-wb="${esc(key)}" class="order-sheet-line-row" style="${detailStyle}">
                <td style="padding-left:52px; color:var(--text-muted);">
                  <span style="color:var(--text-muted); font-weight:400; margin-right:6px;">↳</span>
                  ${prefix}<span style="color:var(--text); font-weight:500;">${esc(vLabel)}</span>
                </td>
                <td style="text-align:right;">${vQty > 0 ? vQty.toLocaleString('en-US') : '—'}</td>
                <td style="text-align:right; color:var(--text-muted);">${perUnit > 0 ? '$' + fmt3(perUnit) : '—'}</td>
                <td style="text-align:right; font-weight:600;">${vTot > 0 ? '$' + fmt2(vTot) : '—'}</td>
                ${profitCell(vProfit, haveProfit && vQty > 0)}
                <td></td>
                <td></td>
              </tr>`;
            });
          } else {
            // No variants — show the item itself as the single line.
            const itemQty = parseFloat(String(item.qty || '').replace(/,/g,'')) || 0;
            const iTot = perUnit > 0 ? perUnit * itemQty : 0;
            const iProfit = haveProfit && itemQty > 0 ? profitPerUnit * itemQty : 0;
            rows += `<tr data-osh-wb="${esc(key)}" class="order-sheet-line-row" style="${detailStyle}">
              <td style="padding-left:36px;">${esc(item.item || '—')}</td>
              <td style="text-align:right;">${itemQty > 0 ? itemQty.toLocaleString('en-US') : '—'}</td>
              <td style="text-align:right; color:var(--text-muted);">${perUnit > 0 ? '$' + fmt3(perUnit) : '—'}</td>
              <td style="text-align:right; font-weight:600;">${iTot > 0 ? '$' + fmt2(iTot) : '—'}</td>
              ${profitCell(iProfit, haveProfit && itemQty > 0)}
              <td></td>
              <td></td>
            </tr>`;
          }
        });
      }

      return rows;
    }).join('');

    // Grand total footer
    const grandUsdStr     = grandUsd > 0 ? `$${fmt2(grandUsd)}` : '—';
    const grandLeadStr    = grandMaxLead > 0 ? `${grandMaxLead} days` : '—';
    // Shipment line: weight + CBM (out of one 40' HC container's 67 m³)
    // with a small fill indicator so the operator can spot a near-full
    // container at a glance. Hidden when neither metric is populated.
    const fmtKg  = n => n.toLocaleString('en-US', {maximumFractionDigits: 0}) + ' kg';
    const fmtCbm = n => n.toLocaleString('en-US', {minimumFractionDigits: 1, maximumFractionDigits: 1});
    const cbmCap = 67;
    const fillPct = totalCbm > 0 ? Math.min(100, (totalCbm / cbmCap) * 100) : 0;
    const cbmOver = totalCbm > cbmCap ? totalCbm - cbmCap : 0;
    // Overflow indicator: amber bar + "+X.X over" pill when total
    // CBM exceeds the single 40' HC container cap.
    const cbmHtml = totalCbm > 0
      ? (cbmOver > 0
          ? `<span style="color:#d97706;">⚠</span> ${fmtCbm(totalCbm)} / ${cbmCap} CBM <span style="color:#d97706; font-weight:800; margin-left:4px;">+${fmtCbm(cbmOver)} over</span>`
          : `${fmtCbm(totalCbm)} / ${cbmCap} CBM`)
      : '—';
    const cbmBarColor = cbmOver > 0 ? '#f59e0b' : 'var(--accent)';
    const wtStr   = totalWeightKg > 0 ? fmtKg(totalWeightKg) : '—';
    const showShipRow = totalCbm > 0 || totalWeightKg > 0;
    const shipRow = showShipRow
      ? `<tr>
          <td colspan="3" style="font-weight:700; font-size:11px; text-transform:uppercase; letter-spacing:0.04em; color:var(--text-muted); padding-top:4px;">Shipment</td>
          <td colspan="4" style="text-align:right; font-size:12px; padding-top:4px;">
            <span style="color:var(--text-muted); margin-right:14px;">Weight: <strong style="color:var(--text);">${wtStr}</strong></span>
            <span style="color:var(--text-muted);">CBM: <strong style="color:var(--text);">${cbmHtml}</strong></span>
            <div style="margin-top:5px; height:4px; background:var(--surface2); border-radius:99px; overflow:hidden; max-width:260px; margin-left:auto;">
              <div style="height:100%; width:${fillPct}%; background:${cbmBarColor}; border-radius:99px; transition:width 0.2s;"></div>
            </div>
          </td>
        </tr>`
      : '';
    // Grand profit color follows the same green/red/muted rule as the
    // per-row cells. Falls back to '—' when no workbook contributed
    // (every row was missing a sale or a cost).
    const profitColor   = grandProfitUsd > 0 ? '#10b981' : grandProfitUsd < 0 ? '#dc2626' : 'var(--text-muted)';
    const grandProfitStr = grandProfitUsd !== 0 ? `$${fmt2(grandProfitUsd)}` : '—';
    tfoot.innerHTML = `<tr>
      <td colspan="3" style="font-weight:700; font-size:12px; text-transform:uppercase; letter-spacing:0.04em; color:var(--text-muted);">Grand Total</td>
      <td style="text-align:right; font-size:15px; font-weight:800;">${grandUsdStr}</td>
      <td style="text-align:right; font-size:14px; font-weight:800; color:${profitColor};">${grandProfitStr}</td>
      <td style="text-align:right; font-weight:700; color:var(--text-muted);">${grandLeadStr}</td>
      <td></td>
    </tr>${shipRow}`;
  }

  // Per-section "Add payment" inline form state. Resets on render.
  let _addingPaymentFor = null;
  function openAddPaymentForm(type) { _addingPaymentFor = type; renderOrderDepositTracking(); }
  function closeAddPaymentForm()    { _addingPaymentFor = null; renderOrderDepositTracking(); }

  function saveNewPayment(type) {
    const o = orderData[_currentOrderId];
    if (!o) return;
    const amtEl  = document.getElementById('pay-new-amt');
    const dateEl = document.getElementById('pay-new-date');
    const noteEl = document.getElementById('pay-new-note');
    const amt = parseFloat(amtEl?.value || '0');
    if (!(amt > 0)) { alert('Enter a payment amount > 0.'); amtEl?.focus(); return; }
    if (!Array.isArray(o.payments)) o.payments = [];
    o.payments.push({
      id: 'p' + Date.now() + Math.floor(Math.random() * 1000),
      type,
      amountUsd: Math.round(amt * 100) / 100,
      dateIso: dateEl?.value || new Date().toISOString().slice(0, 10),
      note:    (noteEl?.value || '').trim(),
    });
    _addingPaymentFor = null;
    saveOrders();
    renderOrderDepositTracking();
    renderOrdersList(); // refresh the dashboard cards too
  }

  function removeOrderPayment(idx) {
    const o = orderData[_currentOrderId];
    if (!o || !Array.isArray(o.payments) || !o.payments[idx]) return;
    if (!confirm('Remove this payment?')) return;
    o.payments.splice(idx, 1);
    saveOrders();
    renderOrderDepositTracking();
    renderOrdersList();
  }

  function renderOrderDepositTracking() {
    const o = orderData[_currentOrderId];
    if (!o) return;
    const container = document.getElementById('order-deposit-rows');
    if (!container) return;

    // Deposit base is the CUSTOMER-facing total (sum of each
    // workbook's Client Quote Total Order across the order's
    // entries). The deposit is collected against what the client
    // actually wires, not against our internal tier-cost math.
    // Falls back to the legacy orderTotals.totalUsd (tier × qty)
    // when no workbook has Sale Per typed yet so a brand-new
    // order still shows a non-zero deposit.
    const pct = o.depositPct != null ? o.depositPct : 30;
    let baseUsd = 0;
    (o.entries || []).forEach(e => {
      const w = _wbStatsForPicker(workbookDetail[`${e.clientName}|${e.workbookId}`]);
      baseUsd += w.price || 0;
    });
    if (baseUsd <= 0) {
      baseUsd = orderTotals(o).totalUsd || 0;
    }
    const depositAmt = Math.round(baseUsd * (pct / 100) * 100) / 100;
    const balanceAmt = Math.round((baseUsd - depositAmt) * 100) / 100;

    // Payments array drives the new behavior. Legacy depositPaid /
    // balancePaid booleans on older orders are honored as "fully
    // paid" defaults when no payments array exists yet — so existing
    // orders don't lose state. Once the operator adds a payment, the
    // payments array becomes authoritative and the booleans are
    // ignored (no destructive migration).
    if (!Array.isArray(o.payments)) o.payments = [];
    const payments = o.payments;
    const sumFor = (type) => payments
      .filter(p => p && p.type === type)
      .reduce((s, p) => s + (parseFloat(p.amountUsd) || 0), 0);

    const fmtUsd  = v => `$${(v || 0).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
    const fmtDate = iso => {
      if (!iso) return '—';
      const d = new Date(iso); if (isNaN(d.getTime())) return iso;
      return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
    };

    // Build one section ("Deposit" or "Balance") with its target
    // amount, list of partial-payment rows, progress, and either an
    // Add Payment button or the inline new-payment form.
    const sectionHtml = (type, label, target) => {
      const sectionPayments = payments
        .map((p, idx) => ({ p, idx }))
        .filter(({ p }) => p && p.type === type);
      const paidSum = sumFor(type);
      const legacyFull = (type === 'deposit' && o.depositPaid && sectionPayments.length === 0)
                     || (type === 'balance' && o.balancePaid && sectionPayments.length === 0);
      const fullyPaid = legacyFull || (target > 0 && paidSum >= target - 0.005);
      const remaining = Math.max(0, target - paidSum);
      const pctPaid   = target > 0 ? Math.min(100, (paidSum / target) * 100) : 0;
      const headerColor = fullyPaid ? 'var(--success, #16a34a)' : 'var(--text)';
      const isAddOpen = _addingPaymentFor === type;

      const rowsHtml = sectionPayments.length
        ? sectionPayments.map(({ p, idx }) => `
            <div style="display:grid; grid-template-columns:auto 1fr auto auto; gap:10px; align-items:center; padding:6px 10px; border-radius:6px; background:var(--surface2); margin-top:6px;">
              <span style="font-size:11px; color:var(--text-muted); font-variant-numeric:tabular-nums; white-space:nowrap;">${fmtDate(p.dateIso)}</span>
              <span style="font-size:12px; color:var(--text); overflow:hidden; text-overflow:ellipsis; white-space:nowrap;" title="${(p.note || '').replace(/"/g,'&quot;')}">${p.note || '<span style="color:var(--text-muted); font-style:italic;">—</span>'}</span>
              <span style="font-size:13px; font-weight:700; color:var(--success, #16a34a); font-variant-numeric:tabular-nums; white-space:nowrap;">${fmtUsd(p.amountUsd)}</span>
              <button type="button" onclick="removeOrderPayment(${idx})" title="Remove this payment"
                style="background:none; border:none; color:var(--text-muted); cursor:pointer; font-size:14px; line-height:1; padding:2px 6px; font-family:inherit;">×</button>
            </div>`).join('')
        : (fullyPaid
          ? `<div style="margin-top:6px; padding:6px 10px; font-size:11px; color:var(--text-muted); font-style:italic;">Marked fully paid (legacy flag) — add a payment to record the wire details.</div>`
          : '');

      const addFormHtml = isAddOpen ? `
        <div style="margin-top:8px; padding:10px; border:1px dashed var(--accent); border-radius:6px; background:rgba(107,147,255,0.05);">
          <div style="display:grid; grid-template-columns:repeat(auto-fit, minmax(140px, 1fr)); gap:8px; margin-bottom:8px;">
            <div>
              <label style="font-size:10px; font-weight:700; text-transform:uppercase; letter-spacing:0.05em; color:var(--text-muted); display:block; margin-bottom:3px;">Amount (USD)</label>
              <input type="number" id="pay-new-amt" step="0.01" min="0" placeholder="${remaining > 0 ? remaining.toFixed(2) : '0.00'}" autofocus
                style="width:100%; height:32px; padding:0 8px; border:1px solid var(--border); border-radius:4px; background:var(--surface); color:var(--text); font-size:13px; font-family:inherit; box-sizing:border-box;" />
            </div>
            <div>
              <label style="font-size:10px; font-weight:700; text-transform:uppercase; letter-spacing:0.05em; color:var(--text-muted); display:block; margin-bottom:3px;">Date</label>
              <input type="date" id="pay-new-date" value="${new Date().toISOString().slice(0,10)}"
                style="width:100%; height:32px; padding:0 8px; border:1px solid var(--border); border-radius:4px; background:var(--surface); color:var(--text); font-size:13px; font-family:inherit; box-sizing:border-box;" />
            </div>
            <div>
              <label style="font-size:10px; font-weight:700; text-transform:uppercase; letter-spacing:0.05em; color:var(--text-muted); display:block; margin-bottom:3px;">Note (optional)</label>
              <input type="text" id="pay-new-note" placeholder="Wire ref, who paid, etc."
                style="width:100%; height:32px; padding:0 8px; border:1px solid var(--border); border-radius:4px; background:var(--surface); color:var(--text); font-size:13px; font-family:inherit; box-sizing:border-box;" />
            </div>
          </div>
          <div style="display:flex; gap:6px; justify-content:flex-end;">
            <button type="button" onclick="closeAddPaymentForm()" style="font-size:12px; padding:5px 12px; border:1px solid var(--border); background:transparent; color:var(--text-muted); border-radius:4px; cursor:pointer; font-family:inherit;">Cancel</button>
            <button type="button" onclick="saveNewPayment('${type}')" style="font-size:12px; padding:5px 12px; border:1px solid var(--accent); background:var(--accent); color:#fff; border-radius:4px; cursor:pointer; font-family:inherit; font-weight:600;">Save Payment</button>
          </div>
        </div>` : `
        <div style="margin-top:6px;">
          <button type="button" onclick="openAddPaymentForm('${type}')"
            style="font-size:11px; padding:4px 10px; border:1px dashed var(--border); background:transparent; color:var(--text-muted); border-radius:4px; cursor:pointer; font-family:inherit;">+ Add payment</button>
        </div>`;

      return `
        <div style="padding:10px 0; border-bottom:1px solid var(--border);">
          <div style="display:flex; align-items:baseline; gap:10px; flex-wrap:wrap;">
            <span style="font-weight:700; color:${headerColor}; font-size:13px;">${label}</span>
            <span style="color:var(--text-muted); font-size:12px;">target ${fmtUsd(target)}</span>
            ${fullyPaid
              ? `<span style="margin-left:auto; font-size:12px; font-weight:700; color:var(--success, #16a34a);">✓ Fully paid</span>`
              : `<span style="margin-left:auto; font-size:12px; color:var(--text-muted);"><strong style="color:var(--success, #16a34a);">${fmtUsd(paidSum)}</strong> of ${fmtUsd(target)} paid · <strong style="color:var(--text);">${fmtUsd(remaining)}</strong> remaining</span>`}
          </div>
          <div style="margin-top:6px; height:5px; background:var(--surface2); border-radius:99px; overflow:hidden;">
            <div style="height:100%; width:${pctPaid}%; background:var(--success, #16a34a); border-radius:99px; transition:width 0.2s;"></div>
          </div>
          ${rowsHtml}
          ${addFormHtml}
        </div>`;
    };

    container.innerHTML =
      sectionHtml('deposit', `${pct}% Deposit`, depositAmt) +
      sectionHtml('balance', `${100 - pct}% Balance`, balanceAmt);
  }

  // ── Add Workbook to Order modal ──────────────────────────────────────
  function openAddWorkbookToOrderModal() {
    const o = orderData[_currentOrderId];
    if (!o) return;
    _orderAddPickerSelected = new Set();
    document.getElementById('order-add-wb-search').value = '';
    buildOrderAddPickerList('');
    document.getElementById('modal-add-wb-to-order').classList.add('open');
  }

  function closeAddWorkbookToOrderModal() {
    document.getElementById('modal-add-wb-to-order').classList.remove('open');
    _orderAddPickerSelected = new Set();
  }

  function buildOrderAddPickerList(query) {
    const list = document.getElementById('order-add-wb-list');
    if (!list) return;
    const o = orderData[_currentOrderId];
    if (!o) return;
    query = (query || '').toLowerCase();

    // Determine which clients to show: single client or all if "Multiple Clients"
    const isMulti = o.clientName === 'Multiple Clients';
    const allowedClients = isMulti
      ? Object.keys(clientData)
      : [o.clientName];

    // Status groups: latest → earliest
    const statusGroups = [
      { key: 'complete',         label: 'Complete' },
      { key: 'orderChina',       label: 'Order Placed' },
      { key: 'confirmedPayment', label: 'Payment Confirmed' },
      { key: 'officeInvoice',    label: 'Office Invoice' },
      { key: 'clientApproved',   label: 'Client Approved' },
      { key: 'quoteClient',      label: 'Quote Sent to Client' },
      { key: 'quoteSubmitted',   label: 'Quote Submitted' },
      { key: 'quoteChina',       label: 'Quote from China' },
      { key: 'new',              label: 'New' },
    ];

    const palette = ['#6b93ff','#f59e0b','#4ade80','#f472b6','#a78bfa','#34d399','#fb923c','#38bdf8'];
    const clientColors = {};
    let colorIdx = 0;
    function getClientColor(name) {
      if (!clientColors[name]) clientColors[name] = palette[colorIdx++ % palette.length];
      return clientColors[name];
    }

    // Already in this order (by key)
    const existingKeys = new Set((o.entries || []).map(e => `${e.clientName}|${e.workbookId}`));

    const buckets = {};
    statusGroups.forEach(g => { buckets[g.key] = []; });

    // Per-item numeric snapshot — keyed by `${clientName}|${wb.id}`.
    // The grand total card consumes this map to sum across selected
    // rows without re-walking clientData / workbookDetail.
    _orderAddPickerItemData = {};

    allowedClients.forEach(clientName => {
      (clientData[clientName] || []).forEach(wb => {
        const key     = `${clientName}|${wb.id}`;
        if (existingKeys.has(key)) return; // skip already-added
        const detail  = workbookDetail[key] || {};
        const product = detail.product || wb.product || '—';
        if (query && !product.toLowerCase().includes(query) && !clientName.toLowerCase().includes(query)) return;
        // Order summary line: units · weight · cost. Helper centralizes
        // source-of-truth selection so this picker matches the Pricing
        // tab + every other order surface.
        const w = _wbStatsForPicker(detail);
        _orderAddPickerItemData[key] = { units: w.units, weightKg: w.weightKg, cost: w.cost, price: w.price, cbm: w.cbm };
        // CBM tucked in next to weight, colored so it reads as one
        // shipment-dimensions phrase.
        const partsSummary = [];
        partsSummary.push(w.units > 0 ? `${w.units.toLocaleString('en-US')} units` : '— units');
        const cbmPill = w.cbm > 0
          ? ` <span style="color:var(--accent); font-weight:600;">(${w.cbm.toLocaleString('en-US', {minimumFractionDigits: 1, maximumFractionDigits: 1})} CBM)</span>`
          : '';
        const weightCbmStr = w.weightKg > 0
          ? `${w.weightKg.toLocaleString('en-US', {maximumFractionDigits: 0})} kg${cbmPill}`
          : (w.cbm > 0 ? `— kg${cbmPill}` : '— kg');
        partsSummary.push(weightCbmStr);
        partsSummary.push(w.cost > 0 ? `$${w.cost.toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2})}` : '—');
        const tierStr = partsSummary.join(' · ');
        const item = { clientName, workbookId: wb.id, product, tierStr, key };

        const flow = wb.flow || {};
        if (isFlowComplete(flow)) {
          buckets['complete'].push(item);
        } else {
          const lastStep = [...flowSteps].reverse().find(s => flow[s]);
          buckets[lastStep || 'new'].push(item);
        }
      });
    });

    let html = '';
    let totalItems = 0;
    statusGroups.forEach(group => {
      const items = buckets[group.key];
      if (!items || items.length === 0) return;
      totalItems += items.length;
      html += `<div class="wb-picker-group-label">${group.label}</div>`;
      items.forEach(item => {
        const color     = getClientColor(item.clientName);
        const isChecked = _orderAddPickerSelected.has(item.key);
        const initials  = item.clientName.substring(0, 3).toUpperCase();
        html += `<div class="wb-picker-item${isChecked ? ' selected' : ''}"
            onclick="toggleOrderAddPickerItem('${item.key.replace(/'/g,"\\'")}')">
          <div style="width:40px; height:40px; border-radius:8px; background:${color}22; border:1px solid ${color}44; display:flex; align-items:center; justify-content:center; font-size:11px; font-weight:800; color:${color}; flex-shrink:0; letter-spacing:0.02em;">
            ${initials}
          </div>
          <div class="wb-picker-info">
            <div class="wb-picker-product">${item.product}</div>
            <div class="wb-picker-client">${item.clientName}</div>
            <div class="wb-picker-tiers">${item.tierStr}</div>
          </div>
          <div style="width:20px; height:20px; border-radius:4px; border:2px solid ${isChecked ? 'var(--accent)' : 'var(--border)'}; background:${isChecked ? 'var(--accent)' : 'transparent'}; display:flex; align-items:center; justify-content:center; flex-shrink:0; transition:all 0.15s;">
            ${isChecked ? '<svg width="11" height="9" viewBox="0 0 11 9" fill="none"><path d="M1 4L4 7.5L10 1" stroke="white" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>' : ''}
          </div>
        </div>`;
      });
    });

    if (totalItems === 0) {
      list.innerHTML = `<div style="text-align:center; padding:30px; color:var(--text-muted); font-size:13px;">
        ${query ? 'No workbooks match your search.' : 'All workbooks are already in this order.'}
      </div>`;
      _renderOrderAddGrandTotal();
      return;
    }
    list.innerHTML = html;
    _renderOrderAddGrandTotal();
  }

  // Sums the per-item snapshots (units / weight / cost / price / cbm)
  // across selected keys and paints the grand total card. Hidden when
  // nothing is checked. CBM bar is capped visually at 100% but the
  // numeric label can exceed 67 — that signals overflow into a 2nd
  // container, which is useful information rather than something to
  // hide.
  function _renderOrderAddGrandTotal() {
    const card = document.getElementById('order-add-grand-total');
    if (!card) return;
    const sel = _orderAddPickerSelected;
    if (!sel || sel.size === 0) {
      card.style.display = 'none';
      return;
    }
    card.style.display = '';
    let units = 0, weightKg = 0, cost = 0, price = 0, cbm = 0;
    sel.forEach(key => {
      const d = (_orderAddPickerItemData && _orderAddPickerItemData[key]) || null;
      if (!d) return;
      units    += d.units    || 0;
      weightKg += d.weightKg || 0;
      cost     += d.cost     || 0;
      price    += d.price    || 0;
      cbm      += d.cbm      || 0;
    });
    const fmtNum = n => n.toLocaleString('en-US');
    const fmtUsd = n => '$' + n.toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2});
    const fmtKg  = n => n.toLocaleString('en-US', {maximumFractionDigits: 0}) + ' kg';
    const fmtCbm = n => n.toLocaleString('en-US', {minimumFractionDigits: 1, maximumFractionDigits: 1});
    const set = (id, txt) => { const el = document.getElementById(id); if (el) el.textContent = txt; };
    set('order-add-gt-count',  `${sel.size} selected`);
    set('order-add-gt-units',  units    > 0 ? fmtNum(units)         : '—');
    set('order-add-gt-weight', weightKg > 0 ? fmtKg(weightKg)        : '—');
    set('order-add-gt-cost',   cost     > 0 ? fmtUsd(cost)           : '—');
    set('order-add-gt-price',  price    > 0 ? fmtUsd(price)          : '—');
    const cbmCap = 67;
    const cbmOver = cbm > cbmCap ? cbm - cbmCap : 0;
    _renderCbmFillIndicator('order-add-gt-cbm-label', 'order-add-gt-cbm-bar', cbm, cbmCap, cbmOver, fmtCbm);
  }

  function filterOrderAddPicker(query) {
    buildOrderAddPickerList(query);
  }

  function toggleOrderAddPickerItem(key) {
    if (_orderAddPickerSelected.has(key)) {
      _orderAddPickerSelected.delete(key);
    } else {
      _orderAddPickerSelected.add(key);
    }
    buildOrderAddPickerList(document.getElementById('order-add-wb-search').value);
  }

  function confirmAddWorkbookToOrder() {
    if (_orderAddPickerSelected.size === 0) { alert('Select at least one workbook.'); return; }
    const o = orderData[_currentOrderId];
    if (!o) return;
    _orderAddPickerSelected.forEach(key => {
      const lastPipe   = key.lastIndexOf('|');
      const clientName = key.substring(0, lastPipe);
      const workbookId = key.substring(lastPipe + 1);
      // Don't add duplicates
      const alreadyIn = (o.entries || []).some(e => e.clientName === clientName && e.workbookId == workbookId);
      if (!alreadyIn) {
        o.entries = o.entries || [];
        o.entries.push({ clientName, workbookId });
      }
    });
    // If order was single-client but now has multiple, update clientName
    const clients = [...new Set((o.entries || []).map(e => e.clientName))];
    if (clients.length > 1) o.clientName = 'Multiple Clients';
    saveOrders();
    closeAddWorkbookToOrderModal();
    renderOrderSheet();
    renderOrderDepositTracking();
    document.getElementById('order-detail-client-name').textContent = o.clientName;
  }

  function removeWorkbookFromOrder(idx) {
    const o = orderData[_currentOrderId];
    if (!o) return;
    o.entries.splice(idx, 1);
    saveOrders();
    renderOrderSheet();
    renderOrderDepositTracking();
  }

  // ── Inline edits ─────────────────────────────────────────────────────
  function onOrderNameChange() {
    const o = orderData[_currentOrderId];
    if (!o) return;
    o.name = document.getElementById('order-detail-name').value;
    saveOrders();
    rebuildOrdersNav();
    document.getElementById('header-title').textContent = o.name;
  }

  function onOrderStatusChange() {
    const o = orderData[_currentOrderId];
    if (!o) return;
    o.status = document.getElementById('order-detail-status').value;
    saveOrders();
    rebuildOrdersNav();
  }

  function onOrderPoChange() {
    const o = orderData[_currentOrderId];
    if (!o) return;
    o.poNumber = document.getElementById('order-detail-po').value;
    saveOrders();
  }

  function onOrderDepositPctChange() {
    const o = orderData[_currentOrderId];
    if (!o) return;
    const val = parseInt(document.getElementById('order-detail-deposit-pct').value) || 30;
    o.depositPct = Math.min(100, Math.max(0, val));
    saveOrders();
    renderOrderDepositTracking();
  }

  function onOrderNotesChange() {
    const o = orderData[_currentOrderId];
    if (!o) return;
    o.notes = document.getElementById('order-detail-notes').value;
    saveOrders();
  }

  function onOrderDepositPaidChange(type, checked) {
    const o = orderData[_currentOrderId];
    if (!o) return;
    if (type === 'deposit') o.depositPaid = checked;
    if (type === 'balance') o.balancePaid = checked;
    saveOrders();
  }

</script>
<!-- Build badge — bottom-right, shows the server file mtime so the
     operator can confirm a hard refresh actually picked up the latest
     deploy. If a fix doesn't appear to land, the timestamp here tells
     us instantly whether the browser is on stale JS. -->
<div id="ms-build-badge"
     style="position:fixed; bottom:6px; right:8px; z-index:9999; font: 10px/1 -apple-system,BlinkMacSystemFont,sans-serif; color:#9ca3af; background:rgba(255,255,255,0.7); padding:3px 6px; border-radius:4px; pointer-events:none; user-select:none;">
  build <?= htmlspecialchars($_msBuildIso, ENT_QUOTES) ?>
</div>
</body>
</html>
